# ==========================================================
# QBIT INPUT NORMALIZATION
#
# MODULE-LEVEL HELPER
#
# Used by QbitDialer startup and QuantumMathEngine.
# Does not create or replace a Qbit.
# ==========================================================

def normalize_qbit_input(
    state_input: Any,
) -> Tuple[complex, complex]:

    if isinstance(
        state_input,
        (int, float, complex),
    ):
        state_input = (
            complex(state_input),
            0.0 + 0.0j,
        )

    elif isinstance(
        state_input,
        (list, tuple),
    ):
        state_input = tuple(
            complex(x)
            for x in state_input
        )

    elif isinstance(
        state_input,
        dict,
    ):
        if "alpha" in state_input:

            alpha = state_input.get(
                "alpha",
                0.0 + 0.0j,
            )

            beta = state_input.get(
                "beta",
                0.0 + 0.0j,
            )

            state_input = (
                complex(alpha),
                complex(beta),
            )

        elif "state" in state_input:

            return normalize_qbit_input(
                state_input["state"]
            )

        elif "qbit" in state_input:

            return normalize_qbit_input(
                state_input["qbit"]
            )

        else:

            raise ValueError(
                "Dictionary does not contain "
                "a recognizable Qbit state"
            )

    else:

        raise ValueError(
            "Cannot convert "
            f"{type(state_input)!r} "
            "to Qbit state"
        )

    if len(state_input) == 0:

        state_input = (
            1 / math.sqrt(2),
            1 / math.sqrt(2),
        )

    elif len(state_input) != 2:

        state_input = (
            state_input[0],
            (
                state_input[1]
                if len(state_input) > 1
                else 0.0 + 0.0j
            ),
        )

    alpha, beta = (
        complex(state_input[0]),
        complex(state_input[1]),
    )

    norm = math.sqrt(
        abs(alpha) ** 2 +
        abs(beta) ** 2
    ) or 1.0

    return (
        alpha / norm,
        beta / norm,
    )
