# SAFE EVENT BUS
# ==========================================================

class EventBusStub:

    def __init__(
        self,
        event=None,
        track=None,
        emit=None,
        task=None,
        payload=None,
    ):
        self._callbacks = defaultdict(list)

    def emit(
        self,
        event_type,
        payload=None,
    ):
        callbacks = list(
            self._callbacks.get(
                event_type,
                [],
            )
        )

        for callback in callbacks:
            try:
                result = callback(payload)

                # IMPORTANT:
                #
                # Do not create an asyncio loop here.
                #
                # Construction and synchronous event
                # delivery must remain lifecycle-safe.
                #
                # If an async callback is returned and no
                # runtime loop owns it, simply leave it alone.
                #
                if inspect.isawaitable(result):
                    try:
                        result.close()
                    except Exception:
                        pass

            except Exception:
                logger.exception(
                    "[EventBusStub] callback failed: %s",
                    event_type,
                )

        return True

    def publish(
        self,
        event_type,
        payload=None,
    ):
        return self.emit(
            event_type,
            payload,
        )

    def subscribe(
        self,
        event_type,
        callback,
    ):
        if callable(callback):
            self._callbacks[
                event_type
            ].append(callback)

    def unsubscribe(
        self,
        event_type,
        callback,
    ):
        callbacks = self._callbacks.get(
            event_type,
            [],
        )

        if callback in callbacks:
            callbacks.remove(callback)


