# ==========================================================
# DUAL EMIT
# ==========================================================
#
# DualEmit provides TWO distinct channels:
#
#   EVENT CHANNEL
#       QbitDialer -> EventBus -> SEED AI / subscribers
#
#   EXECUTION CHANNEL
#       QbitDialer -> existing asyncio runtime
#
# DualEmit does NOT own the Qbit loop.
# DualEmit does NOT create another Qbit.
# DualEmit does NOT create a second asyncio runtime.
#
# The QbitDialer remains the authority for Qbit processing.
# ==========================================================


class DualEmit:

    def __init__(
        self,
        *,
        event_bus=None,
        loop=None,
        logger=None,
    ):
        self.event_bus = event_bus
        self.loop = loop

        self.logger = (
            logger
            or logging.getLogger(
                "QbitDialer"
            )
        )

        self._active = True
        self._shutdown = False

    # ==========================================================
    # LIFECYCLE
    # ==========================================================

    def attach_event_bus(self, event_bus):
        if event_bus is None:
            return False

        self.event_bus = event_bus

        if self.logger:
            self.logger.debug(
                "[DualEmit] EventBus attached"
            )

        return True

    def bind_loop(self, loop):
        if loop is None:
            return False

        self.loop = loop
        self._active = True
        self._shutdown = False

        if self.logger:
            self.logger.debug(
                "[DualEmit] Async loop bound"
            )

        return True

    def activate(self):
        self._shutdown = False
        self._active = True

        return True

    def deactivate(self):
        self._active = False

        return True

    def shutdown(self):
        self._active = False
        self._shutdown = True

        self.event_bus = None
        self.loop = None

        return True

    @property
    def active(self):
        return (
            self._active
            and not self._shutdown
        )

    # ==========================================================
    # SEMANTIC EVENT CHANNEL
    # ==========================================================

    def emit_event(
        self,
        event,
        payload=None,
    ):

        if not self.active:
            return False

        if not event:
            return False

        bus = self.event_bus

        if bus is None:

            if self.logger:
                self.logger.debug(
                    "[DualEmit] EventBus not attached | "
                    "event=%s",
                    event,
                )

            return False

        try:

            emitter = getattr(
                bus,
                "emit",
                None,
            )

            if callable(emitter):

                return emitter(
                    event,
                    payload,
                )

            publisher = getattr(
                bus,
                "publish",
                None,
            )

            if callable(publisher):

                return publisher(
                    event,
                    payload,
                )

        except Exception:

            if self.logger:
                self.logger.exception(
                    "[DualEmit] Event emission failed | "
                    "event=%s",
                    event,
                )

        return False

    # ==========================================================
    # CONVENIENCE EVENT ALIAS
    # ==========================================================

    def emit(
        self,
        event,
        payload=None,
    ):
        return self.emit_event(
            event,
            payload,
        )

    # ==========================================================
    # EXECUTION CHANNEL
    # ==========================================================

    def emit_exec(
        self,
        target,
    ):

        if not self.active:

            if self.logger:
                self.logger.debug(
                    "[DualEmit] Execution rejected | "
                    "inactive"
                )

            return False

        if target is None:
            return False

        loop = self.loop

        if loop is None:

            if self.logger:
                self.logger.error(
                    "[DualEmit] Execution rejected | "
                    "no asyncio loop bound"
                )

            return False

        # ------------------------------------------------------
        # Verify loop state.
        # ------------------------------------------------------

        try:

            if loop.is_closed():

                if self.logger:
                    self.logger.error(
                        "[DualEmit] Execution rejected | "
                        "loop is closed"
                    )

                return False

        except Exception:
            pass

        # ======================================================
        # COROUTINE
        # ======================================================

        if asyncio.iscoroutine(target):

            try:

                # ----------------------------------------------
                # Already inside the target loop.
                #
                # create_task() is cleaner than submitting the
                # coroutine back across the same loop.
                # ----------------------------------------------

                try:

                    running_loop = (
                        asyncio.get_running_loop()
                    )

                except RuntimeError:

                    running_loop = None

                if running_loop is loop:

                    return loop.create_task(
                        target
                    )

                # ----------------------------------------------
                # Called from another thread.
                # ----------------------------------------------

                return (
                    asyncio.run_coroutine_threadsafe(
                        target,
                        loop,
                    )
                )

            except Exception:

                self.logger.exception(
                    "[DualEmit] Coroutine scheduling failed"
                )

                # Prevent "coroutine was never awaited".
                try:
                    target.close()
                except Exception:
                    pass

                return False

        # ======================================================
        # ASYNC CALLABLE
        # ======================================================

        if callable(target):

            try:

                # ------------------------------------------------
                # If this is an async function, do not call it
                # immediately from the caller thread.
                # ------------------------------------------------

                if asyncio.iscoroutinefunction(
                    target
                ):

                    async def _invoke_async_callable():
                        return await target()

                    return self.emit_exec(
                        _invoke_async_callable()
                    )

                # ------------------------------------------------
                # Normal synchronous callable.
                # ------------------------------------------------

                return loop.call_soon_threadsafe(
                    target
                )

            except Exception:

                self.logger.exception(
                    "[DualEmit] Callable scheduling failed"
                )

                return False

        # ======================================================
        # INVALID TARGET
        # ======================================================

        if self.logger:
            self.logger.error(
                "[DualEmit] Cannot execute target type: %s",
                type(target).__name__,
            )

        return False

    # ==========================================================
    # SAFE COROUTINE EXECUTION
    # ==========================================================

    def emit_coroutine(
        self,
        coroutine,
    ):


        return self.emit_exec(
            coroutine
        )

    # ==========================================================
    # SAFE FUNCTION EXECUTION
    # ==========================================================

    def emit_callable(
        self,
        func,
    ):

        if not callable(func):
            raise TypeError(
                "emit_callable requires callable"
            )

        return self.emit_exec(
            func
        )
