class ComputeFallback:

    def __init__(
        self,
        name="fallback",
        qbit=None,
    ):

        self.name = name

        self.qbit = qbit

        self.engine = (
            QuantumMathEngine()
        )

        self.compute_brain = (
            ComputeBrain(
                name=name,
                qbit=qbit,
                quantum_engine=self.engine,
            )
        )

        self.confidence = 0.0

    def compute(
        self,
        signals=None,
    ):

        if signals is None:
            signals = self.qbit

        if signals is None:
            self.confidence = 0.0
            return self.confidence

        thought = (
            self.compute_brain.process(
                signals
            )
        )

        self.confidence = (
            thought.get(
                "confidence",
                0.0,
            )
        )

        return self.confidence

    def adapt(self):

        return None
