# QBIT DIALER
# ==========================================================

MAX_LIMP_ATTEMPTS = 3

class QbitDialer:

    # ==========================================================
    # SINGLETON
    # ==========================================================

    _instance = None
    _lock = threading.Lock()

    # Compatibility alias used by older dialer sections.
    _instance_lock = _lock

    INTENT_STATE = "INTENT_STATE"

    # ==========================================================
    # SINGLETON ALLOCATION
    # ==========================================================

    def __new__(
        cls,
        *args,
        **kwargs,
    ):

        with cls._lock:

            if cls._instance is None:

                cls._instance = super().__new__(
                    cls
                )

                cls._instance._constructed = False

        return cls._instance

    # ==========================================================
    # CONSTRUCTOR
    #
    # CONSTRUCTION != RUNTIME
    #
    # This constructor:
    #
    #   - binds the authoritative Qbit
    #   - binds the authoritative EventBus
    #   - binds the authoritative QbitQueueLoop
    #   - creates the command plane
    #   - registers command definitions
    #   - binds dependencies
    #
    # It DOES NOT:
    #
    #   - start Qbit runtime
    #   - start queue runtime
    #   - start heartbeat runtime
    #   - start HUD
    #   - start audio
    #   - start modem
    #   - create duplicate authoritative objects
    # ==========================================================

    def __init__(
        self,
        *args,
        emit=None,
        qbit=None,
        qbit_queue=None,
        handler=None,
        fathud=None,		
        throttle_hz=60.0,
        name="QbitDialer",
        event_bus=None,
        seedcore=None,
        queue_loop=None,
        qbit_queue_loop=None,
        qbitqueueloop=None,
        heartbeatemitter=None,
        loop=None,
        payload=None,
        qbit_core=None,
        healthmonitor=None,
        compute_brain=None,
        transformer_brain=None,
        adaptive_priority_engine=None,
        action_engine=None,
        quantum_math_engine=None,
        track_system=None,
        watchdog=None,
        cognition_map=None,
        cognitive_governor=None,
        governor=None,
        memory_graph=None,
        memory_system=None,
        memory_crytilizer=None,
        time_travel_engine=None,
        qbit_instance=None,
        initial_state=None,
        storage_root="./SEED_ROOT",
        buffer_limit=100,
        **kwargs,
    ):

        # ======================================================
        # SINGLETON CONSTRUCTOR GUARD
        #
        # QbitDialer.__new__ returns the one authoritative
        # instance. Python still invokes __init__ on every
        # constructor call, so __init__ must be idempotent.
        #
        # A duplicate constructor pass must NOT:
        #   - rebuild FATHUD
        #   - rebuild brains
        #   - rebuild command state
        #   - replace Qbit/QueueLoop/EventBus authority
        #
        # Later runtime dependencies are attached through the
        # explicit late-binding path owned by main3.
        # ======================================================

        if getattr(
            self,
            "_constructed",
            False,
        ):
            self.logger = logging.getLogger(
                "QbitDialer"
            )
            self.logger.info(
                "[QbitDialer] Duplicate constructor call reused "
                "authoritative singleton | FATHUD/brains/runtime preserved"
            )
            return

        # ======================================================
        # LOGGER MUST EXIST FIRST
        # ======================================================

        self.logger = logging.getLogger(
            "QbitDialer"
        )

        # Action security evaluates the final command envelope.
        self.security = SEEDSecurityManager()

        # ======================================================
        # COGNITIVE BRAIN AUTHORITY
        #
        # QbitDialer does NOT create the brains.
        #
        # Existing SEED cognitive components are attached here.
        #
        #     Qbit
        #        â†“
        #     ComputeBrain
        #        â†“
        #     ThoughtPacket
        #        â†“
        #     TransformerBrain
        #        â†“
        #     QbitDialer command authority
        #
        # No duplicate ComputeBrain.
        # No duplicate TransformerBrain.
        # ======================================================

        self.compute_brain = (
            compute_brain
            if compute_brain is not None
            else ComputeBrain(
                qbit=self.qbit,
                quantum_engine=QuantumMathEngine(),
            )
        )

        self.transformer_brain = (
            transformer_brain
            if transformer_brain is not None
            else TransformerBrain(
                "qbit_dialer",
                qbit=self.qbit,
                compute_brain=self.compute_brain,
            )
        )

        # ======================================================
        # VALIDATE COGNITIVE DEPENDENCIES
        # ======================================================

        if self.compute_brain is not None:

            if not callable(
                getattr(
                    self.compute_brain,
                    "process",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] Attached Compute_Brain "
                    "must expose process()"
                )

            self.logger.info(
                "[QbitDialer] Compute_Brain attached | "
                "brain=%s",
                type(
                    self.compute_brain
                ).__name__,
            )

        else:

            self.logger.warning(
                "[QbitDialer] Compute_Brain not attached"
            )

        if self.transformer_brain is not None:

            if not callable(
                getattr(
                    self.transformer_brain,
                    "analyze",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] Attached Transformer_Brain "
                    "must expose analyze()"
                )

            self.logger.info(
                "[QbitDialer] TransformerBrain attached | "
                "brain=%s",
                type(
                    self.transformer_brain
                ).__name__,
            )

        else:

            self.logger.warning(
                "[QbitDialer] TransformerBrain not attached"
            )
        # =================   ===========  ===========
#        self.action_engine = action_engine
        # ======================================================
        # SINGLE-INITIALIZATION GUARD
        #
        # A singleton may receive dependencies later from main.
        # Re-entry therefore performs ONLY late binding.
        #
        # It must NEVER reconstruct the object.
        # ======================================================

        with self._instance_lock:

            if getattr(
                self,
                "_constructed",
                False,
            ):

                late_event_bus = (
                    event_bus
                    if event_bus is not None
                    else getattr(
                        self,
                        "event_bus",
                        None,
                    )
                )

                self._bind_late_dependencies(
                    emit=(
                        getattr(
                            late_event_bus,
                            "emit",
                            None,
                        )
                        if late_event_bus is not None
                        else None
                    ),
                    event_bus=late_event_bus,
                    seedcore=seedcore,
                    # The UI queue is a presentation buffer only.
                    # When the authoritative QbitQueueLoop is supplied, never pass
                    # the UI queue into late dependency binding.
                    qbit_queue=(
                        qbit_queue_loop
                        if isinstance(qbit_queue_loop, QbitQueueLoop)
                        else None
                    ),
                    qbit_queue_loop=qbit_queue_loop,
                    heartbeatemitter=(
                        heartbeatemitter
                        if heartbeatemitter is not None
                        else getattr(
                            self,
                            "heartbeatemitter",
                            None,
                        )
                    ),
                    loop=loop,
                    healthmonitor=(
                        healthmonitor
                        if healthmonitor is not None
                        else getattr(
                            self,
                            "healthmonitor",
                            None,
                        )
                    ),
                    track_system=kwargs.get(
                        "track_system",
                        getattr(
                            self,
                            "track_system",
                            None,
                        ),
                    ),
                    oracle=kwargs.get(
                        "oracle",
                        getattr(
                            self,
                            "oracle",
                            None,
                        ),
                    ),
                    channel_manager=kwargs.get(
                        "channel_manager",
                        getattr(
                            self,
                            "channel_manager",
                            None,
                        ),
                    ),
                    action_engine=kwargs.get(
                        "action_engine",
                        getattr(
                            self,
                            "action_engine",
                            None,
                        ),
                    ),
                    agent_manager=kwargs.get(
                        "agent_manager",
                        getattr(
                            self,
                            "agent_manager",
                            None,
                        ),
                    ),
                )

                return

            self._initialized = False
            self._constructed = False

        # ======================================================
        # BASIC CONFIGURATION
        # ======================================================

        self.qbitqueueloop = qbitqueueloop
        self.name = name
        self.storage_root = storage_root
        self.handler = handler

        # ======================================================
        # AUTHORITATIVE EVENTBUS
        #
        # EventBus is required.
        # QbitDialer does not manufacture one.
        # ======================================================

        authoritative_event_bus = (
            event_bus
            if event_bus is not None
            else kwargs.get(
                "event_bus",
                None,
            )
        )

        if authoritative_event_bus is None:

            raise RuntimeError(
                "[QbitDialer] "
                "requires authoritative EventBus"
            )

        event_emit = getattr(
            authoritative_event_bus,
            "emit",
            None,
        )

        if not callable(event_emit):

            raise RuntimeError(
                "[QbitDialer] "
                "received invalid EventBus: "
                "missing callable emit()"
            )

        self.event_bus = (
            authoritative_event_bus
        )

        # ======================================================
        # EMITTER
        # ======================================================

        self.emit = event_emit

        self._emit = None
        self.EVENT_EMIT = None

        # ======================================================
        # CORE REFERENCE
        # ======================================================

        self.seedcore = seedcore
        self.seed_core = seedcore
        self.core = seedcore

        self.fiveg = kwargs.get(
            "fiveg",
            None,
        )

        # ======================================================
        # AUTHORITATIVE QBIT
        #
        # ONE QBIT ONLY.
        #
        # Primary authority:
        #
        #     qbit=...
        #
        # Compatibility:
        #
        #     qbit_core
        #     qbit_instance
        #
        # QbitDialer NEVER manufactures a replacement.
        # ======================================================

        authoritative_qbit = qbit

        if authoritative_qbit is None:

            authoritative_qbit = (
                qbit_core
                if qbit_core is not None
                else qbit_instance
            )

        if authoritative_qbit is None:

            raise RuntimeError(
                "[QbitDialer] "
                "No authoritative Qbit supplied"
            )

        if not isinstance(
            authoritative_qbit,
            QbitClass,
        ):

            raise TypeError(
                "[QbitDialer] "
                "supplied authoritative Qbit is invalid: "
                f"{type(authoritative_qbit)!r}"
            )

        # Bind EXACT supplied object.
        self.qbit = (
            authoritative_qbit
        )

        self.qbit_instance = (
            authoritative_qbit
        )

        self.qbit_core = (
            authoritative_qbit
        )

        # Identity validation when primary qbit was supplied.
        if qbit is not None:

            if self.qbit is not qbit:

                raise RuntimeError(
                    "[QbitDialer] "
                    "Authoritative Qbit identity violation"
                )

        self.logger.info(
            "[QbitDialer] Authoritative Qbit bound | "
            "same_instance=%s | qbit=%s",
            (
                self.qbit is qbit
                if qbit is not None
                else "compatibility"
            ),
            getattr(
                self.qbit,
                "id",
                "unidentified",
            ),
        )

        # ======================================================
        # RUNTIME TIMING
        # ======================================================

        try:

            hz = float(
                throttle_hz
            )

        except (
            TypeError,
            ValueError,
        ):

            hz = 60.0

        hz = max(
            hz,
            0.001,
        )

        self.loop_hz = hz

        # Historical compatibility:
        # throttle_hz has been used as an interval.
        self.throttle_hz = (
            1.0 / hz
        )

        self.loop_interval = (
            self.throttle_hz
        )

        # ======================================================
        # BUFFER CONFIGURATION
        # ======================================================

        try:

            buffer_limit_value = int(
                buffer_limit
            )

        except (
            TypeError,
            ValueError,
        ):

            buffer_limit_value = 100

        self.buffer_limit = max(
            buffer_limit_value,
            1,
        )

        # ONE buffer registry.
        self.buffers = defaultdict(
            lambda: deque(
                maxlen=256
            )
        )

        self.buffers.setdefault(
            "heartbeat",
            deque(maxlen=256),
        )

        self.buffers.setdefault(
            "measurement",
            deque(maxlen=256),
        )

        self.buffers.setdefault(
            "qbit",
            deque(maxlen=256),
        )

        self.buffers.setdefault(
            "command",
            deque(maxlen=256),
        )

        self.buffers.setdefault(
            "error",
            deque(maxlen=128),
        )

        self._measurement_count = 0
        self._last_measurement_log = 0.0
        self._measurement_log_interval = 1.0
        self.last_measurement = None

        # ======================================================
        # INTERNAL QBIT STATE
        # ======================================================

        self._qbit_update_count = 0

        self._publish_interval = 0.10
        self._last_publish_time = 0.0
        self._last_published_payload = None

        self.emit_queue_limit = 512
        self.qbit_emit_interval = 0.500

        self._last_emit_by_event = {}
        self._emit_suppressed = 0
        self._emit_queue_dropped = 0

        self._publish_count = 0
        self._publish_suppressed = 0
        self._publish_duplicates = 0
        self._publish_errors = 0
        self._qbit_update_skipped = 0

        self._qbit_state_pending = False

        # ======================================================
        # INTERNAL EVENT / WORK QUEUE
        #
        # This is NOT the authoritative QbitQueueLoop.
        #
        # It is only the dialer's local bounded event buffer.
        # ======================================================

        self.queue = deque(
            maxlen=1024
        )

        # ======================================================
        # CALLBACKS
        # ======================================================

        self._emit_callbacks = []
        self.qbit_callbacks = []
        self._listeners = []

        # ======================================================
        # LIFECYCLE
        #
        # Construction is OFF.
        # Runtime starts only through explicit startup.
        # ======================================================

        self.running = False
        self._running = False
        self._qbit_running = False

        self._stopping = False
        self._thread_running = False

        self._qbit_task = None
        self._thread = None
        self._qbit_thread = None
        self._loop_owner_thread = None

        self.qbit_queue_loop = queue_loop
        self._qbit_queue_loop = queue_loop
        self.queue_loop = queue_loop
        self._qbit_queue = queue_loop
        self.qbit_queue = queue_loop


        self.shutdown_flag = (
            threading.Event()
        )

        self._loops = {}
        self._loop_threads = {}

        self._runtime_started = False
        self._async_runtime_started = False
        self._heartbeat_bound = False

        self._runtime_state = "OFF"

        # ======================================================
        # LOCKS
        # ======================================================

        self._qbit_lock = (
            threading.RLock()
        )

        self.lock = threading.RLock()

        self._bus_lock = (
            threading.RLock()
        )

        self.command_lock = (
            threading.RLock()
        )

        # ======================================================
        # QUEUE AUTHORITY
        #
        # MAIN / BOOT RUNTIME IS AUTHORITATIVE.
        #
        # QbitDialer NEVER creates another QbitQueueLoop.
        #
        # Accepted inputs:
        #
        #   qbit_queue_loop=QbitQueueLoop(...)
        #       -> authoritative loop
        #
        #   qbit_queue=QbitQueueLoop(...)
        #       -> compatibility alias for authoritative loop
        #
        # Anything else:
        #
        #   -> reject
        #
        # This constructor MUST NOT create a QbitQueueLoop.
        # ======================================================

        self.queue_loop = None
        self._qbit_queue = None

        supplied_queue_loop = (
            qbit_queue_loop
            if isinstance(
                qbit_queue_loop,
                QbitQueueLoop,
            )
            else None
        )

        supplied_queue = qbit_queue

        # ------------------------------------------------------
        # PRIMARY AUTHORITATIVE LOOP
        # ------------------------------------------------------

        if supplied_queue_loop is not None:

            self.queue_loop = (
                supplied_queue_loop
            )

            self._qbit_queue = (
                supplied_queue_loop
            )

        # ------------------------------------------------------
        # COMPATIBILITY:
        # qbit_queue may itself be the authoritative loop.
        # ------------------------------------------------------

        elif isinstance(
            supplied_queue,
            QbitQueueLoop,
        ):

            self.queue_loop = (
                supplied_queue
            )

            self._qbit_queue = (
                supplied_queue
            )

        # ------------------------------------------------------
        # RAW QUEUE COMPATIBILITY
        #
        # A raw queue is NOT converted into a new
        # QbitQueueLoop here.
        #
        # The authoritative QbitQueueLoop must be supplied
        # by main/runtime.
        # ------------------------------------------------------

        elif supplied_queue is not None:

            raise RuntimeError(
                "[QbitDialer] Raw qbit_queue supplied without "
                "authoritative QbitQueueLoop. "
                "QbitDialer will not manufacture a queue loop."
            )

        # ------------------------------------------------------
        # NO QUEUE
        #
        # Do not silently construct one.
        # ------------------------------------------------------

        else:

            raise RuntimeError(
                "[QbitDialer] No authoritative QbitQueueLoop supplied. "
                "QbitDialer requires the runtime-owned queue loop."
            )

        # ======================================================
        # QUEUE IDENTITY VALIDATION
        # ======================================================

        if self.queue_loop is None:

            raise RuntimeError(
                "[QbitDialer] "
                "requires a valid authoritative QbitQueueLoop"
            )

        if not isinstance(
            self.queue_loop,
            QbitQueueLoop,
        ):

            raise TypeError(
                "[QbitDialer] "
                "queue_loop is not a QbitQueueLoop: "
                f"{type(self.queue_loop)!r}"
            )

        # ------------------------------------------------------
        # PRIMARY IDENTITY CHECK
        # ------------------------------------------------------

        if supplied_queue_loop is not None:

            if self.queue_loop is not supplied_queue_loop:

                raise RuntimeError(
                    "[QbitDialer] "
                    "authoritative QbitQueueLoop identity "
                    "violation"
                )

        # ------------------------------------------------------
        # COMPATIBILITY IDENTITY CHECK
        # ------------------------------------------------------

        if isinstance(
            supplied_queue,
            QbitQueueLoop,
        ):

            if self.queue_loop is not supplied_queue:

                raise RuntimeError(
                    "[QbitDialer] "
                    "authoritative QbitQueueLoop identity "
                    "violation"
                )

        # ======================================================
        # QUEUE ALIAS
        #
        # qbit_queue points to the SAME authoritative object.
        #
        # There is no second queue loop.
        # ======================================================

        self.qbit_queue = (
            self.queue_loop
        )

        # ======================================================
        # QUEUE HANDLER BINDING
        #
        # Binding only.
        # Does NOT start the queue loop.
        # ======================================================

        try:

            set_handler = getattr(
                self.queue_loop,
                "set_handler",
                None,
            )

            if callable(
                set_handler
            ):

                set_handler(
                    self.execute_command
                )

            elif hasattr(
                self.queue_loop,
                "handler",
            ):

                current_handler = getattr(
                    self.queue_loop,
                    "handler",
                    None,
                )

                if current_handler is None:

                    self.queue_loop.handler = (
                        self.execute_command
                    )

                elif current_handler is not self.execute_command:

                    self.logger.warning(
                        "[QbitDialer] "
                        "QbitQueueLoop already has a different "
                        "handler; preserving existing handler"
                    )

        except Exception as exc:

            self.logger.warning(
                "[QbitDialer] "
                "Queue handler binding warning | %s",
                exc,
            )

        # ======================================================
        # FINAL QUEUE AUTHORITY ASSERTION
        # ======================================================

        if self.qbit_queue is not self.queue_loop:

            raise RuntimeError(
                "[QbitDialer] "
                "qbit_queue / queue_loop identity mismatch"
            )

        self.logger.info(
            "[QbitDialer] Authoritative QbitQueueLoop bound | "
            "same_instance=%s | type=%s",
            (
                self.qbit_queue is self.queue_loop
            ),
            type(
                self.queue_loop
            ).__name__,
        )

        # ======================================================
        # STATE QUEUE
        # ======================================================

        self.state_queue = (
            queue.Queue()
        )

        self.qbit_buffer = deque(
            maxlen=self.buffer_limit
        )

        # ======================================================
        # PAYLOAD / STATE
        # ======================================================

        self.payload = payload
        self.initial_state = initial_state

        self.qbit_state = None
        self.tick = None
        self.confidence = {}

        # ======================================================
        # COMMAND PLANE
        #
        # QbitDialer is authoritative command authority.
        # ======================================================

        self.command_queue = (
            queue.Queue()
        )

        self.frame_queue = (
            asyncio.Queue()
        )

        self.commands = []

        self._command_error_count = 0
        self._last_command = None

        self.commands_received = 0
        self.commands_accepted = 0
        self.commands_rejected = 0
        self.commands_queued = 0
        self.commands_executed = 0
        self.commands_failed = 0
        self.commands_cancelled = 0

        self.command_registry = {}

        self.command_history = deque(
            maxlen=500
        )

        self.command_plane = {
            "online": False,
            "authority": "QbitDialer",
            "transport": "QbitQueueLoop",
            "source": "QBIT",
            "thought_loop": "STANDBY",
            "commands": 0,
            "last_command": None,
            "last_result": None,
            "last_error": None,
        }

        # ======================================================
        # REGISTRY
        # ======================================================

        self.registry = (
            SEED_KERNEL_REGISTRY.setdefault(
                "qbits",
                {},
            )
        )

        # ======================================================
        # COGNITIVE DEPENDENCIES
        #
        # References only.
        # ======================================================

        self.adaptive_priority_engine = (
            adaptive_priority_engine
        )

        self.watchdog = (
            watchdog
        )

        self.cognition_map = (
            cognition_map
        )

        self.governor = (
            governor
            if governor is not None
            else cognitive_governor
        )

        self.memory_graph = (
            memory_graph
        )

        self.memory_system = (
            memory_system
        )

        self.memory_crystallizer = (
            kwargs.get(
                "memory_crystallizer",
                memory_crytilizer,
            )
        )

        self.constraint_guardian = (
            kwargs.get(
                "constraint_guardian",
                None,
            )
        )

        self.instruction_decoder = (
            kwargs.get(
                "instruction_decoder",
                None,
            )
        )

        self.time_travel_engine = (
            time_travel_engine
        )

        # ======================================================
        # DO NOT USE undefined dialer_kwargs
        #
        # Previous constructor contained:
        #
        #     dialer_kwargs["priority_engine"] = ...
        #
        # but dialer_kwargs was never defined.
        #
        # The authoritative object is already stored above.
        # ======================================================

        # ======================================================
        # HEALTH
        # ======================================================

        if isinstance(
            healthmonitor,
            type,
        ):

            self.healthmonitor = (
                healthmonitor()
            )

        elif healthmonitor is not None:

            self.healthmonitor = (
                healthmonitor
            )

        else:

            try:

                from seed.systemutils.healthmonitor import (
                    HealthMonitor as _HealthMonitor,
                )

                self.healthmonitor = (
                    _HealthMonitor()
                )

            except Exception:

                self.healthmonitor = (
                    HealthMonitorFallback()
                )

        if not hasattr(
            self.healthmonitor,
            "load",
        ):

            raise RuntimeError(
                "[FATAL] HealthMonitor has no "
                "load() method: "
                f"{type(self.healthmonitor)!r}"
            )

        self.system_monitor = (
            SystemMonitor()
        )

        self._health_monitor_source = (
            self.healthmonitor
        )

        # Compatibility alias.
        self.health_monitor = (
            self.healthmonitor
        )

        # ======================================================
        # HEARTBEAT
        #
        # Reference only.
        # No heartbeat startup here.
        # ======================================================

        self.heartbeatemitter = (
            heartbeatemitter
        )

        self.heartbeat = (
            heartbeatemitter
        )

        # ======================================================
        # COGNITION
        # ======================================================

        self.intent_engine = (
            kwargs.get(
                "intent_engine",
                None,
            )
        )

        self.adaptive_engine = (
            kwargs.get(
                "adaptive_engine",
                None,
            )
        )

        # ======================================================
        # AUDIO / MODEM
        #
        # Cognitive inputs only.
        # No hardware activation.
        # ======================================================

        self.audio_modem_manager = kwargs.get(
            "audio_modem_manager",
            None,
        )

        self.audio = kwargs.get(
            "audio",
            None,
        )

        self.modem = kwargs.get(
            "modem",
            None,
        )

        # ======================================================
        # HUD
        #
        # QbitDialer does NOT own HUD lifecycle.
        # ======================================================

        self.fat_layer = None

        self._hud_available = False
        self._hud_start_owned_elsewhere = True
        self._hud_port = 8765

        self.controller = None

        # ======================================================
        # SECURITY
        # ======================================================

        self._security = None

        self.permission_system = (
            kwargs.get(
                "permission_system",
                None,
            )
        )

        # ======================================================
        # TRACKING
        # ======================================================

        self.module_health = defaultdict(
            lambda: {
                "state": "OK",
                "yellow": 0,
                "red": 0,
                "timestamp": 0,
                "last_flag": None,
            }
        )

        try:

            self.trust = (
                SensorTrustManager()
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "SensorTrustManager construction failed"
            )

            self.trust = None

        try:

            self.track_manager = (
                TrackIDManager()
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "TrackIDManager construction failed"
            )

            self.track_manager = None

        self._track_id = None

        # ======================================================
        # NEURAL BRIDGE
        # ======================================================

        self.encoder = (
            QbitBinaryEncoder()
        )

        try:

            self.neural_bridge = (
                NeuralBridge(
                    encoder=self.encoder,
                    kernel_bus=kwargs.get(
                        "kernel_bus",
                        None,
                    ),
                )
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "NeuralBridge initialization failed"
            )

            self.neural_bridge = None

        # ======================================================
        # TRANSFORMER BRAINS
        #
        # Cognitive objects only.
        # ======================================================

        self.cpu = None
        self.system_calc = None
        self.modem_brain = None
        self.audio_brain = None

        try:

            self.cpu = TransformerBrain(
                "cpu",
                qbit=self.qbit,
            )

            self.system_calc = TransformerBrain(
                "system_calc",
                qbit=self.qbit,
            )

            self.modem_brain = TransformerBrain(
                "modem",
                qbit=self.qbit,
            )

            self.audio_brain = TransformerBrain(
                "audio",
                qbit=self.qbit,
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "TransformerBrain initialization failed"
            )

            self.cpu = None
            self.system_calc = None
            self.modem_brain = None
            self.audio_brain = None

        # ======================================================
        # PASSIVE AUDIO BRAIN
        #
        # Only used when no supplied/injected audio compute
        # authority exists.
        #
        # No hardware.
        # No threads.
        # No asyncio tasks.
        # ======================================================

        if self.audio is None:

            class _PassiveAudioBrain:

                def __init__(
                    self,
                    name="audio",
                    qbit=None,
                ):

                    self.name = name
                    self.qbit = qbit

                    self.confidence = 0.0
                    self.samples = 0
                    self.learning_rate = 0.02

                    self.history = deque(
                        maxlen=256
                    )

                    self.weights = defaultdict(
                        lambda: 1.0
                    )

                    self.last_snapshot = None
                    self.last_score = 0.0
                    self.last_adaptation = 0.0

                    self.active = False
                    self.running = False

                def compute(
                    self,
                    snapshot=None,
                ):

                    self.last_snapshot = (
                        snapshot
                    )

                    self.samples += 1

                    score = 0.0

                    if isinstance(
                        snapshot,
                        dict,
                    ):

                        try:

                            value = snapshot.get(
                                "audio_confidence",
                                snapshot.get(
                                    "audio",
                                    0.0,
                                ),
                            )

                            if isinstance(
                                value,
                                (int, float),
                            ):

                                score = float(
                                    value
                                )

                        except Exception:

                            score = 0.0

                    if not math.isfinite(
                        score
                    ):

                        score = 0.0

                    score = max(
                        0.0,
                        min(
                            1.0,
                            score,
                        ),
                    )

                    self.last_score = (
                        score
                    )

                    self.history.append(
                        score
                    )

                    self.confidence = (
                        score
                    )

                    return self.confidence

                def adapt(
                    self,
                ):

                    if len(
                        self.history
                    ) < 2:

                        return self.confidence

                    previous = (
                        self.history[-2]
                    )

                    current = (
                        self.history[-1]
                    )

                    delta = (
                        current - previous
                    )

                    if not math.isfinite(
                        delta
                    ):

                        delta = 0.0

                    self.last_adaptation = (
                        delta
                        * self.learning_rate
                    )

                    for key in list(
                        self.weights.keys()
                    ):

                        try:

                            self.weights[key] += (
                                self.last_adaptation
                            )

                            self.weights[key] = max(
                                0.05,
                                min(
                                    2.50,
                                    self.weights[key],
                                ),
                            )

                        except Exception:

                            self.weights[key] = 1.0

                    return self.confidence

                def status(
                    self,
                ):

                    return {
                        "name": self.name,
                        "active": self.active,
                        "running": self.running,
                        "confidence": self.confidence,
                        "samples": self.samples,
                        "last_score": self.last_score,
                        "last_adaptation": self.last_adaptation,
                    }

                def stop(
                    self,
                ):

                    self.active = False
                    self.running = False

                    return True

            self.audio = _PassiveAudioBrain(
                name="audio",
                qbit=self.qbit,
            )

        # ======================================================
        # MODEM COMPUTE FALLBACK
        # ======================================================

        if self.modem is None:

            if self.modem_brain is not None and callable(
                getattr(
                    self.modem_brain,
                    "compute",
                    None,
                )
            ):

                self.modem = (
                    self.modem_brain
                )

            else:

                self.modem = ComputeFallback(
                    "modem"
                )

        # ======================================================
        # AUDIO COMPUTE VALIDATION
        # ======================================================

        if not callable(
            getattr(
                self.audio,
                "compute",
                None,
            )
        ):

            self.logger.warning(
                "[QbitDialer] "
                "Audio compute authority unavailable; "
                "audio confidence will be held safely"
            )

        # ======================================================
        # MODEM COMPUTE VALIDATION
        # ======================================================

        if not callable(
            getattr(
                self.modem,
                "compute",
                None,
            )
        ):

            self.logger.warning(
                "[QbitDialer] "
                "Modem compute authority unavailable; "
                "modem confidence will be held safely"
            )

        # ======================================================
        # LIMP / PLANNING STATE
        # ======================================================

        self._internal_clock = (
            time.time()
        )

        self.limp_mode = False
        self.limp_reason = None
        self.limp_attempts = 0

        self.brain_go = False
        self.planning = False
        self.idle = True

        self._recovery_running = False
        self._recovery_pending = False

        self.monitor_interval = 1.0
        self.recovery_interval = 1.0
        self.max_limp_attempts = (
            MAX_LIMP_ATTEMPTS
        )

        self.success_rate = 0.0
        self.backup_attempts = 0

        # ======================================================
        # GOVERNOR / RELEASE STATE
        # ======================================================

        self.release_threshold = 0.5

        # ======================================================
        # EVENT STATE
        # ======================================================

        self.event_log = []

        self._subscribed = False
        self._authority_ready = False

        # ======================================================
        # ASYNC LOOP REFERENCE
        #
        # Caller owns the asyncio loop.
        # ======================================================

        self.loop = loop

        # ======================================================
        # CONFIG
        # ======================================================

        self.config = kwargs.get(
            "config",
            {},
        )

        # ======================================================
        # ORACLE
        # ======================================================

        self.oracle = kwargs.get(
            "oracle",
            None,
        )

        # ======================================================
        # OPTIONAL CROSS-SYSTEM DEPENDENCIES
        #
        # Preserve injected objects.
        # Do NOT initialize them to None after binding.
        # ======================================================

        self.track_system = kwargs.get(
            "track_system",
            None,
        )

        self.channel_manager = kwargs.get(
            "channel_manager",
            None,
        )

        self.agent_manager = kwargs.get(
            "agent_manager",
            None,
        )

        # ======================================================
        # QBIT STATE
        # ======================================================

        self._initialize_qbit_state(
            initial_state=initial_state
        )

        # ======================================================
        # PHASE-1 COMMAND REGISTRATION
        #
        # Registration is safe.
        # Execution does not begin here.
        # ======================================================

        try:

            register_commands = getattr(
                self,
                "_register_phase1_commands",
                None,
            )

            if callable(
                register_commands
            ):

                register_commands()
                self.logger.info(
                    "[QbitDialer] Constructor phase-1 command registration returned"
                )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "Phase-1 command registration failed"
            )

        # ======================================================
        # TRACK AUTHORITY
        # ======================================================
        #
        # TrackSystem owns context/lineage.
        # QbitDialer keeps the supplied TrackSystem reference
        # through late dependency binding below.
        #
        # No legacy upstream-track hook is executed during
        # constructor boot.
        # ======================================================

        # ======================================================
        # INITIAL BOOT PAYLOAD
        #
        # STORE ONLY.
        # ======================================================

        self.payload = {
            "intent": "system",
            "action": "noop",
            "data": payload,
            "meta": {
                "source": "QbitDialer",
                "boot": True,
                "state": "constructed",
            },
        }

        # ======================================================
        # DEPENDENCY STATE
        # ======================================================

        self._dependencies_bound = False

        # ======================================================
        # LATE DEPENDENCY BINDING
        #
        # Preserve already-bound authoritative objects.
        #
        # IMPORTANT:
        #   - Do NOT construct a QbitQueueLoop here.
        #   - Do NOT replace the authoritative Qbit.
        #   - Do NOT replace the authoritative EventBus.
        #   - Do NOT start any runtime.
        #   - Do NOT create heartbeat/runtime tasks.
        #
        # All objects supplied here are references only.
        # ======================================================

        self.logger.info(
            "[QbitDialer] Constructor late dependency binding BEGIN"
        )

        self._bind_late_dependencies(
            emit=(
                getattr(
                    event_bus,
                    "emit",
                    None,
                )
                if event_bus is not None
                else None
            ),
            event_bus=event_bus,
            seedcore=seedcore,
            qbit_queue=(
                qbit_queue
                if qbit_queue is not None
                else qbit_queue_loop
            ),
            qbit_queue_loop=qbit_queue_loop,
            heartbeatemitter=(
                heartbeatemitter
                if heartbeatemitter is not None
                else getattr(
                    self,
                    "heartbeatemitter",
                    None,
                )
            ),
            loop=loop,
            healthmonitor=(
                healthmonitor
                if healthmonitor is not None
                else getattr(
                    self,
                    "healthmonitor",
                    None,
                )
            ),
            track_system=kwargs.get(
                "track_system",
                getattr(
                    self,
                    "track_system",
                    None,
                ),
            ),
            oracle=kwargs.get(
                "oracle",
                getattr(
                    self,
                    "oracle",
                    None,
                ),
            ),
            channel_manager=kwargs.get(
                "channel_manager",
                getattr(
                    self,
                    "channel_manager",
                    None,
                ),
            ),
            agent_manager=kwargs.get(
                "agent_manager",
                getattr(
                    self,
                    "agent_manager",
                    None,
                ),
            ),
            action_engine=kwargs.get(
                "action_engine",
                getattr(
                    self,
                    "action_engine",
                    None,
                ),
            ),
            compute_brain=self.compute_brain,
            transformer_brain=self.transformer_brain,
        )

        self.logger.info(
            "[QbitDialer] Constructor late dependency binding RETURNED"
        )

        # ======================================================
        # AUTHORITATIVE IDENTITY ASSERTIONS
        #
        # Late binding is NOT allowed to replace authority.
        # ======================================================

        if self.qbit_queue is not self.queue_loop:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding changed "
                "authoritative QbitQueueLoop identity"
            )

        if self._qbit_queue is not self.queue_loop:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding changed "
                "_qbit_queue identity"
            )

        if self.qbit is not self.qbit_instance:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding changed "
                "authoritative Qbit identity"
            )

        if self.qbit is not self.qbit_core:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding changed "
                "qbit_core identity"
            )

        if self.event_bus is None:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding removed "
                "authoritative EventBus"
            )
        # ==========================================================
        # FATHUD ADAPTER
        # ==========================================================
        #
        # FATHUD is a developer/observer interface.
        #
        # QbitDialer remains the command authority.
        # FATHUD does not become a second command plane.
        #
        # ==========================================================

        self.fathud = FATHUDAdapter(
            event_bus=self.event_bus,
            qbit=getattr(
                self,
                "qbit",
                None,
            ),
            qbit_dialer=self,
            command_plane=self,
            seedcore=getattr(
                self,
                "seedcore",
                None,
            ),
        )

        self.fat_layer = self.fathud

        self.logger.info(
            "[QbitDialer] FATHUD adapter bound | "
            "fathud=%s | fat_layer=%s",
            type(
                self.fathud
            ).__name__,
            type(
                self.fat_layer
            ).__name__,
        )
        # ======================================================
        # FINAL CONSTRUCTION STATE
        #
        # Construction succeeds, but runtime remains OFF.
        # ======================================================

        self._initialized = True
        self._constructed = True

        self.running = False
        self._running = False
        self._qbit_running = False
        self._runtime_started = False
        self._async_runtime_started = False
        self._runtime_state = "OFF"

        # ======================================================
        # CONSTRUCTION STATUS
        # ======================================================

        qbit_obj = getattr(
            self,
            "qbit",
            None,
        )

        queue_obj = getattr(
            self,
            "_qbit_queue",
            None,
        )

        heartbeat_obj = getattr(
            self,
            "heartbeatemitter",
            None,
        )

        event_bus_obj = getattr(
            self,
            "event_bus",
            None,
        )

        self.logger.info(
            "[QbitDialer] CONSTRUCTED | "
            "qbit=%s(%s) | "
            "queue=%s(%s) | "
            "heartbeat=%s(%s) | "
            "event_bus=%s(%s) | "
            "runtime=OFF | "
            "authority=QbitDialer",
            (
                type(qbit_obj).__name__
                if qbit_obj is not None
                else "None"
            ),
            getattr(
                qbit_obj,
                "id",
                "unidentified",
            ),
            (
                type(queue_obj).__name__
                if queue_obj is not None
                else "None"
            ),
            getattr(
                queue_obj,
                "id",
                "unidentified",
            ),
            (
                type(heartbeat_obj).__name__
                if heartbeat_obj is not None
                else "None"
            ),
            getattr(
                heartbeat_obj,
                "module",
                "unidentified",
            ),
            (
                type(event_bus_obj).__name__
                if event_bus_obj is not None
                else "None"
            ),
            (
                "attached"
                if event_bus_obj is not None
                else "pending"
            ),
        )

        # ======================================================
        # INITIAL RUNTIME STATE
        # ======================================================

        self._qbit_task = None

        # Startup supervision.
        self._start_lock = None
        self._heartbeat_start_task = None
        self._heartbeat_start_pending = False

        # ======================================================
        # RUNTIME CADENCE
        # ======================================================

        # Internal Qbit execution maximum:
        # 10 Hz.
        self.qbit_runtime_interval = 0.100

        # Outward telemetry:
        # 2 Hz maximum.
        self.qbit_emit_interval = 0.500

        self._last_qbit_emit = 0.0
        self._qbit_last_cycle_time = 0.0
        self._qbit_overrun_count = 0

        # ======================================================
        # HEARTBEAT TELEMETRY
        # ======================================================

        self._heartbeat_sequence = 0
        self._last_heartbeat = None
        self._previous_heartbeat = None
        self._last_heartbeat_payload = None
        self._heartbeat_state = {}

        self._heartbeat_log_interval = 5.0
        self._last_heartbeat_log = 0.0

        # ======================================================
        # CONSTRUCTOR DIAGNOSTICS
        # ======================================================

        self._runtime_start_count = 0
        self._runtime_stop_count = 0

        self.logger.info(
            "[QbitDialer] Runtime controls initialized | "
            "qbit_rate<=10Hz | telemetry<=2Hz | "
            "single_task=True | heartbeat_supervised=True"
        )


    # ==========================================================
    # LATE DEPENDENCY BINDING
    #
    # BIND ONLY.
    #
    # QbitDialer does not create runtime objects here.
    # main.py remains authoritative for QbitQueueLoop.
    # ==========================================================

    # ==========================================================
    # COMPUTE BRAIN AUTHORITY BINDING
    #
    # Bind the EXISTING SEED ComputeBrain.
    #
    # NEVER create a replacement brain here.

    def _bind_late_dependencies(
        self,
        *,
        event_bus=None,
        emit=None,
        compute_brain=None,
        transformer_brain=None,
        action_engine=None,
        qbit_queue=None,
        qbit_queue_loop=None,
        heartbeatemitter=None,
        heartbeat=None,
        track_system=None,
        seedcore=None,
        oracle=None,
        channel_manager=None,
        agent_manager=None,
        health_monitor=None,
        **kwargs,
    ):

        # ------------------------------------------------------
        # EventBus
        # ------------------------------------------------------

        if event_bus is not None:

            self.event_bus = event_bus

            event_emit = getattr(
                event_bus,
                "emit",
                None,
            )

            if callable(
                event_emit
            ):

                self.emit = event_emit

        # ------------------------------------------------------
        # Legacy emit compatibility
        # ------------------------------------------------------

        if emit is not None:

            # EventBus-like object.
            if (
                hasattr(
                    emit,
                    "publish",
                )
                or hasattr(
                    emit,
                    "emit",
                )
            ):

                self.event_bus = emit

                event_emit = getattr(
                    emit,
                    "emit",
                    None,
                )

                if callable(
                    event_emit
                ):

                    self.emit = event_emit

            # Plain callable emitter.
            elif callable(
                emit
            ):

                self.emit_callback = emit

        if self.compute_brain is None:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding removed "
                "authoritative ComputeBrain"
            )

        if self.transformer_brain is None:

            raise RuntimeError(
                "[QbitDialer] "
                "Late dependency binding removed "
                "authoritative TransformerBrain"
            )

        # ------------------------------------------------------
        # AUTHORITATIVE QUEUE LOOP
        #
        # main.py owns the QbitQueueLoop.
        #
        # Late binding may:
        #
        #   - bind the authoritative loop if one is supplied
        #   - confirm an already-bound loop
        #
        # It MUST NOT:
        #
        #   - construct a QbitQueueLoop
        #   - replace an existing authoritative loop
        #   - accept a raw queue as the authoritative loop
        # ------------------------------------------------------

        authoritative_queue = None

        if qbit_queue_loop is not None:

            authoritative_queue = (
                qbit_queue_loop
            )

        elif qbit_queue is not None:

            authoritative_queue = (
                qbit_queue
            )

        if authoritative_queue is not None:

            if not isinstance(
                authoritative_queue,
                QbitQueueLoop,
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "late-bound queue must be "
                    "the authoritative QbitQueueLoop: "
                    f"{type(authoritative_queue)!r}"
                )

            existing_queue = getattr(
                self,
                "queue_loop",
                None,
            )

            # --------------------------------------------------
            # Existing authoritative loop
            # --------------------------------------------------

            if existing_queue is not None:

                if existing_queue is not authoritative_queue:

                    raise RuntimeError(
                        "[QbitDialer] "
                        "authoritative QbitQueueLoop identity "
                        "violation during late binding"
                    )

            # --------------------------------------------------
            # First late binding
            # --------------------------------------------------

            else:

                self.queue_loop = (
                    authoritative_queue
                )

            # --------------------------------------------------
            # ALL QUEUE ALIASES MUST POINT TO THE SAME OBJECT
            # --------------------------------------------------

            self._qbit_queue = (
                self.queue_loop
            )

            self.qbit_queue = (
                self.queue_loop
            )

            # --------------------------------------------------
            # Re-bind command authority.
            #
            # Binding only.
            # Does NOT start the queue loop.
            # --------------------------------------------------

            try:

                set_handler = getattr(
                    self.queue_loop,
                    "set_handler",
                    None,
                )

                if callable(
                    set_handler
                ):

                    set_handler(
                        self.execute_command
                    )

                elif hasattr(
                    self.queue_loop,
                    "handler",
                ):

                    current_handler = getattr(
                        self.queue_loop,
                        "handler",
                        None,
                    )

                    if current_handler is None:

                        self.queue_loop.handler = (
                            self.execute_command
                        )

                    elif (
                        current_handler
                        is not self.execute_command
                    ):

                        self.logger.warning(
                            "[QbitDialer] "
                            "QbitQueueLoop already has a "
                            "different handler; preserving "
                            "existing handler"
                        )

            except Exception as exc:

                self.logger.warning(
                    "[QbitDialer] "
                    "Late queue handler binding warning | %s",
                    exc,
                )

        # ------------------------------------------------------
        # FINAL QUEUE AUTHORITY VALIDATION
        #
        # If the dialer has already been constructed, these
        # aliases must remain synchronized.
        # ------------------------------------------------------

        existing_queue_loop = getattr(
            self,
            "queue_loop",
            None,
        )

        existing_qbit_queue = getattr(
            self,
            "qbit_queue",
            None,
        )

        existing_internal_queue = getattr(
            self,
            "_qbit_queue",
            None,
        )

        if existing_queue_loop is not None:

            if not isinstance(
                existing_queue_loop,
                QbitQueueLoop,
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "queue_loop is not a QbitQueueLoop: "
                    f"{type(existing_queue_loop)!r}"
                )

            # queue_loop is the authoritative runtime object.
            # Compatibility aliases may be stale after an earlier
            # binding pass, so repair them to the same object rather
            # than rejecting the authoritative runtime.
            if existing_qbit_queue is not existing_queue_loop:
                self.qbit_queue = existing_queue_loop

            if existing_internal_queue is not existing_queue_loop:
                self._qbit_queue = existing_queue_loop

        # ------------------------------------------------------
        # Heartbeat
        # ------------------------------------------------------

        if heartbeat is not None:

            self.heartbeat = (
                heartbeat
            )

        if heartbeatemitter is not None:

            self.heartbeatemitter = (
                heartbeatemitter
            )

            # Compatibility alias.
            self.heartbeat = (
                heartbeatemitter
            )

        # ------------------------------------------------------
        # Core dependencies
        # ------------------------------------------------------

        if track_system is not None:

            self.track_system = (
                track_system
            )

        if seedcore is not None:

            self.seedcore = (
                seedcore
            )

            self.seed_core = (
                seedcore
            )

            self.core = (
                seedcore
            )

        if oracle is not None:

            self.oracle = (
                oracle
            )

        if channel_manager is not None:

            self.channel_manager = (
                channel_manager
            )

        if agent_manager is not None:

            self.agent_manager = (
                agent_manager
            )

        if action_engine is not None:

            self.action_engine = (
                action_engine
            )

        # ------------------------------------------------------
        # Health monitor
        # ------------------------------------------------------

        if health_monitor is not None:

            self.healthmonitor = (
                health_monitor
            )

            # Compatibility alias.
            self.health_monitor = (
                health_monitor
            )

        # ------------------------------------------------------
        # COGNITIVE BRAINS
        #
        # Bind the existing SEED cognitive components.
        #
        # Never manufacture replacement brains.
        # Never erase an already-authoritative brain when
        # this late-binding call does not supply one.
        # ------------------------------------------------------

        if compute_brain is not None:

            existing_compute_brain = getattr(
                self,
                "compute_brain",
                None,
            )

            if (
                existing_compute_brain is not None
                and existing_compute_brain is not compute_brain
            ):

                raise RuntimeError(
                    "[QbitDialer] "
                    "ComputeBrain identity violation | "
                    "existing ComputeBrain cannot be replaced"
                )

            self.compute_brain = compute_brain

        else:

            compute_brain = getattr(
                self,
                "compute_brain",
                None,
            )

        if transformer_brain is not None:

            existing_transformer_brain = getattr(
                self,
                "transformer_brain",
                None,
            )

            if (
                existing_transformer_brain is not None
                and existing_transformer_brain is not transformer_brain
            ):

                raise RuntimeError(
                    "[QbitDialer] "
                    "TransformerBrain identity violation | "
                    "existing TransformerBrain cannot be replaced"
                )

            self.transformer_brain = transformer_brain

        else:

            transformer_brain = getattr(
                self,
                "transformer_brain",
                None,
            )

        # ------------------------------------------------------
        # Cognitive dependency validation
        # ------------------------------------------------------

        if self.compute_brain is not None:

            if not callable(
                getattr(
                    self.compute_brain,
                    "process",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "Attached ComputeBrain must expose process()"
                )

        if self.transformer_brain is not None:

            if not callable(
                getattr(
                    self.transformer_brain,
                    "analyze",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "Attached TransformerBrain must expose analyze()"
                )

        # ------------------------------------------------------
        # Preserve unknown legacy dependencies.
        #
        # Only bind missing attributes.
        #
        # Never overwrite an existing authoritative object.
        # ------------------------------------------------------

        for name, value in kwargs.items():

            if value is None:

                continue

            if not hasattr(
                self,
                name,
            ):

                setattr(
                    self,
                    name,
                    value,
                )

        # ------------------------------------------------------
        # Dependency state
        # ------------------------------------------------------

        self._dependencies_bound = True

        self.logger.debug(
            "[QbitDialer] Late dependencies bound | "
            "event_bus=%s | "
            "queue=%s | "
            "queue_loop=%s | "
            "heartbeat=%s | "
            "track=%s | "
            "seed_core=%s | "
            "compute_brain=%s | "
            "action_engine=%s | "
            "transformer_brain=%s | ",
            type(
                getattr(
                    self,
                    "event_bus",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "_qbit_queue",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "queue_loop",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "heartbeatemitter",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "track_system",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "seedcore",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "compute_brain",
                    None,
                )).__name__,
            type(
                getattr(
                    self,
                    "transformer_brain",
                    None,
                )).__name__,
            type(
                getattr(
                    self,
                    "action_engine",
                    None,
                )).__name__,
            )
        
        # ------------------------------------------------------
        # FINAL QUEUE IDENTITY ASSERTION
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "queue_loop",
            None,
        )

        qbit_queue = getattr(
            self,
            "qbit_queue",
            None,
        )

        internal_queue = getattr(
            self,
            "_qbit_queue",
            None,
        )

        if not isinstance(
            queue_loop,
            QbitQueueLoop,
        ):

            raise RuntimeError(
                "[QbitDialer] "
                "authoritative queue_loop is missing or invalid"
            )

        if (
            qbit_queue is not queue_loop
            or internal_queue is not queue_loop
        ):

            raise RuntimeError(
                "[QbitDialer] "
                "QbitQueueLoop alias identity violation"
            )

    # ==========================================================

    def bind_compute_brain(
        self,
        compute_brain,
    ):

        if compute_brain is None:

            raise TypeError(
                "[QbitDialer] ComputeBrain cannot be None"
            )

        process = getattr(
            compute_brain,
            "process",
            None,
        )

        if not callable(
            process
        ):

            raise TypeError(
                "[QbitDialer] ComputeBrain must expose "
                "callable process()"
            )

        existing = getattr(
            self,
            "compute_brain",
            None,
        )

        if (
            existing is not None
            and existing is not compute_brain
        ):

            raise RuntimeError(
                "[QbitDialer] ComputeBrain authority violation | "
                "existing ComputeBrain cannot be replaced"
            )

        self.compute_brain = compute_brain

        self.logger.info(
            "[QbitDialer] ComputeBrain bound | "
            "same_instance=%s | brain=%s",
            existing is None
            or existing is compute_brain,
            type(
                compute_brain
            ).__name__,
        )

        return compute_brain

    # ==========================================================
    def _bind_quantum_math_engine(self):
        engine = getattr(
            self,
            "quantum_math_engine",
            None,
        )

        if engine is None:
            engine = QuantumMathEngine(
                qbit=self.qbit,
                qbit_queue_loop=self.qbit_queue_loop,
                qbit_dialer=self,
                heartbeat_emitter=self.heartbeat_emitter,
                emit=self.emit,
                track_system=self.track_system,
                runtime_context=getattr(
                    self,
                    "runtime_context",
                    None,
                ),
                compute_brain=getattr(
                    self,
                    "compute_brain",
                    None,
                ),
                transformer_brain=getattr(
                    self,
                    "transformer_brain",
                    None,
                ),
            )

            self.quantum_math_engine = engine

        engine.bind_runtime(
            qbit=self.qbit,
            qbit_queue_loop=self.qbit_queue_loop,
            qbit_dialer=self,
            heartbeat_emitter=self.heartbeat_emitter,
            track_system=self.track_system,
            emit=self.emit,
            runtime_context=getattr(
                self,
                "runtime_context",
                None,
            ),
            compute_brain=getattr(
                self,
                "compute_brain",
                None,
            ),
            transformer_brain=getattr(
                self,
                "transformer_brain",
                None,
            ),
        )
 
        return engine
    # ==========================================================
    # COGNITIVE PIPELINE
    #
    # AUTHORITATIVE FLOW:
    #
    # Qbit
    # |
    # v
    # ComputeBrain
    # |
    # v
    # ThoughtPacket
    # |
    # v
    # TransformerBrain
    # |
    # v
    # CognitiveResult
    # |
    # +--------------------+
    # |                    |
    # v                    v
    # IntentEngine          AnalyticsEngine
    # |
    # v
    # ActionEngine
    # |
    # v
    # QbitDialer
    # |
    # v
    # submit_command()
    # |
    # v
    # QbitQueueLoop
    # |
    # v
    # execution_result
    # |
    # v
    # AnalyticsEngine
    # |
    # v
    # ThoughtFeedback
    # |
    # +----> next cognitive cycle
    #
    # IMPORTANT:
    #
    # - Every Qbit is processable.
    # - User input is OPTIONAL.
    # - Heartbeat Qbits are processable.
    # - Idle/system Qbits are processable.
    # - Qbit remains the identity/lineage anchor.
    # - ComputeBrain owns thought generation.
    # - TransformerBrain owns thought transformation.
    # - IntentEngine owns interpretation.
    # - ActionEngine proposes action.
    # - QbitDialer remains command authority.
    # - submit_command() remains sole command admission.
    # - QbitQueueLoop owns execution/transport.
    # - AnalyticsEngine observes the complete cycle.
    # - ThoughtFeedback closes the cognitive loop.
    # ==========================================================

    async def _run_qbit_cognitive_pipeline(
        self,
        qbit,
        cognitive_context,
        compute_result,
        transform_result,
    ):
        # ======================================================
        # 0. QBIT IS THE PROCESSING TRIGGER
        # ======================================================

        if qbit is None:

            return {
                "status": "rejected",
                "reason": "qbit_unavailable",
                "user_input_required": False,
            }

        context = dict(
            cognitive_context
            if isinstance(
                cognitive_context,
                dict,
            )
            else {}
        )

        # ======================================================
        # 1. AUTHORITATIVE QBIT CONTEXT
        # ======================================================

        qbit_id = context.get(
            "qbit_id"
        )

        if qbit_id is None:

            qbit_id = self._extract_qbit_field(
                qbit,
                "qbit_id",
                None,
            )

        if qbit_id is None:

            qbit_id = self._extract_qbit_field(
                qbit,
                "id",
                None,
            )

        task_id = context.get(
            "task_id"
        )

        if task_id is None:

            task_id = self._extract_qbit_field(
                qbit,
                "task_id",
                None,
            )

        track_id = context.get(
            "track_id"
        )

        if track_id is None:

            track_id = self._extract_qbit_field(
                qbit,
                "track_id",
                None,
            )

        pipeline_id = context.get(
            "pipeline_id"
        )

        if pipeline_id is None:

            pipeline_id = self._extract_qbit_field(
                qbit,
                "pipeline_id",
                None,
            )

        source = context.get(
            "source",
            "QBIT",
        )

        channel = context.get(
            "channel",
            "QBIT",
        )

        # ======================================================
        # 1A. QBIT SEMANTIC CONTEXT
        #
        # WHO / WHAT / WHERE / WHY / HOW
        #
        # Qbit remains authoritative.
        # Context is fallback only.
        # Nothing is invented.
        # ======================================================

        semantic_context = {}

        for semantic_field in (
            "who",
            "what",
            "where",
            "why",
            "how",
        ):

            value = context.get(
                semantic_field
            )

            if value is None:

                value = self._extract_qbit_field(
                    qbit,
                    semantic_field,
                    None,
                )

            if value is not None:

                semantic_context[
                    semantic_field
                ] = value

        # ======================================================
        # 2. PROCESSING CLASSIFICATION
        # ======================================================

        heartbeat_driven = (
            source == "core_heartbeat"
            or source == "HEARTBEAT"
            or source == "HEARTBEAT_QBIT"
            or channel == "HEARTBEAT"
            or channel == "HEARTBEAT_QBIT"
        )

        idle_qbit = (
            source in (
                "IDLE",
                "IDLE_QBIT",
                "SYSTEM_IDLE",
            )
            or channel in (
                "IDLE",
                "IDLE_QBIT",
            )
        )

        context[
            "qbit_present"
        ] = True

        context[
            "user_input_required"
        ] = False

        context[
            "heartbeat_driven"
        ] = heartbeat_driven

        context[
            "idle_qbit"
        ] = idle_qbit

        context[
            "processing_reason"
        ] = context.get(
            "processing_reason",
            (
                "HEARTBEAT_QBIT"
                if heartbeat_driven
                else (
                    "IDLE_QBIT"
                    if idle_qbit
                    else "QBIT_RECEIVED"
                )
            ),
        )

        context[
            "semantic_context"
        ] = dict(
            semantic_context
        )

        # ======================================================
        # 3. FEEDBACK CYCLE ID
        # ======================================================

        feedback_cycle_id = (
            f"QFEEDBACK-{uuid4()}"
        )

        context[
            "feedback_cycle_id"
        ] = feedback_cycle_id

        # ======================================================
        # 4. THOUGHT
        # ======================================================

        thought_packet = compute_result

        if thought_packet is None:

            thought_packet = {

                "packet_type":
                    "ThoughtPacket",

                "type":
                    "ThoughtPacket",

                "status":
                    "EMPTY_THOUGHT",

                "reason":
                    "compute_returned_none",

                "qbit":
                    qbit,

            }

        elif not isinstance(
            thought_packet,
            dict,
        ):

            thought_packet = {

                "packet_type":
                    "ThoughtPacket",

                "type":
                    "ThoughtPacket",

                "value":
                    thought_packet,

                "qbit":
                    qbit,

            }

        # ------------------------------------------------------
        # Authoritative thought metadata.
        # ------------------------------------------------------

        thought_packet.setdefault(
            "packet_type",
            "ThoughtPacket",
        )

        thought_packet.setdefault(
            "type",
            "ThoughtPacket",
        )

        thought_packet.setdefault(
            "qbit",
            qbit,
        )

        thought_packet.setdefault(
            "qbit_id",
            qbit_id,
        )

        thought_packet.setdefault(
            "task_id",
            task_id,
        )

        thought_packet.setdefault(
            "track_id",
            track_id,
        )

        thought_packet.setdefault(
            "pipeline_id",
            pipeline_id,
        )

        thought_packet.setdefault(
            "source",
            source,
        )

        thought_packet.setdefault(
            "channel",
            channel,
        )

        thought_packet.setdefault(
            "feedback_cycle_id",
            feedback_cycle_id,
        )

        thought_packet.setdefault(
            "user_input_required",
            False,
        )

        thought_packet.setdefault(
            "heartbeat_driven",
            heartbeat_driven,
        )

        thought_packet.setdefault(
            "idle_qbit",
            idle_qbit,
        )

        thought_packet.setdefault(
            "semantic_context",
            dict(
                semantic_context
            ),
        )

        # Preserve WHO / WHAT / WHERE / WHY / HOW
        # directly on the ThoughtPacket.

        for semantic_field, value in (
            semantic_context.items()
        ):

            thought_packet.setdefault(
                semantic_field,
                value,
            )

        # ======================================================
        # 5. TRANSFORMER BRAIN
        # ======================================================

        transformed = transform_result

        if transformed is None:

            transformed = {

                "packet_type":
                    "TransformedThoughtPacket",

                "type":
                    "CognitiveResult",

                "thought":
                    thought_packet,

                "intent":
                    None,

                "action":
                    None,

                "qbit":
                    qbit,

                "qbit_id":
                    qbit_id,

                "task_id":
                    task_id,

                "track_id":
                    track_id,

                "pipeline_id":
                    pipeline_id,

                "feedback_cycle_id":
                    feedback_cycle_id,

            }

        elif not isinstance(
            transformed,
            dict,
        ):

            transformed = {

                "packet_type":
                    "TransformedThoughtPacket",

                "type":
                    "CognitiveResult",

                "value":
                    transformed,

            }

        transformed.setdefault(
            "thought",
            thought_packet,
        )

        transformed.setdefault(
            "qbit",
            qbit,
        )

        transformed.setdefault(
            "qbit_id",
            qbit_id,
        )

        transformed.setdefault(
            "task_id",
            task_id,
        )

        transformed.setdefault(
            "track_id",
            track_id,
        )

        transformed.setdefault(
            "pipeline_id",
            pipeline_id,
        )

        transformed.setdefault(
            "feedback_cycle_id",
            feedback_cycle_id,
        )

        transformed.setdefault(
            "user_input_required",
            False,
        )

        transformed.setdefault(
            "heartbeat_driven",
            heartbeat_driven,
        )

        transformed.setdefault(
            "idle_qbit",
            idle_qbit,
        )

        transformed.setdefault(
            "semantic_context",
            dict(
                semantic_context
            ),
        )

        for semantic_field, value in (
            semantic_context.items()
        ):

            transformed.setdefault(
                semantic_field,
                value,
            )

        # ======================================================
        # 6. INTENT ENGINE
        # ======================================================

        intent_engine = getattr(
            self,
            "intent_engine",
            None,
        )

        intent_result = None

        intent_input = {

            "stage":
                "INTENT",

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "feedback_cycle_id":
                feedback_cycle_id,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "user_input_required":
                False,

            "authority":
                "QbitDialer",

            "brains": {

                "compute":
                    "ComputeBrain",

                "transformer":
                    "TransformerBrain",

            },

            "next_engine":
                "ActionEngine",

        }

        # Preserve semantic decision fields.

        intent_input.update(
            semantic_context
        )

        if intent_engine is not None:

            intent_method = None

            for method_name in (
                "process",
                "evaluate",
                "process_event",
                "handle",
                "ingest",
                "submit",
            ):

                candidate = getattr(
                    intent_engine,
                    method_name,
                    None,
                )

                if callable(candidate):

                    intent_method = candidate

                    break

            if intent_method is not None:

                try:

                    intent_result = (
                        intent_method(
                            intent_input
                        )
                    )

                    if inspect.isawaitable(
                        intent_result
                    ):

                        intent_result = (
                            await intent_result
                        )

                except TypeError:

                    try:

                        intent_result = (
                            intent_method(
                                event=intent_input
                            )
                        )

                        if inspect.isawaitable(
                            intent_result
                        ):

                            intent_result = (
                                await intent_result
                            )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] IntentEngine "
                            "feedback failed | "
                            "qbit_id=%s | track_id=%s",
                            qbit_id,
                            track_id,
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] IntentEngine "
                        "processing failed | "
                        "qbit_id=%s | track_id=%s",
                        qbit_id,
                        track_id,
                    )

        # ======================================================
        # 7. ACTION ENGINE
        #
        # ACTION ENGINE PROPOSES.
        #
        # IT DOES NOT EXECUTE.
        # IT DOES NOT SUBMIT.
        # ======================================================

        action_engine = getattr(
            self,
            "action_engine",
            None,
        )

        action_result = None

        action_input = {

            "stage":
                "ACTION_PROPOSAL",

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "intent":
                intent_result,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "feedback_cycle_id":
                feedback_cycle_id,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "authority":
                "QbitDialer",

            "execute":
                False,

            "submit":
                False,

            "user_input_required":
                False,

            "brains": {

                "compute":
                    "ComputeBrain",

                "transformer":
                    "TransformerBrain",

            },

            "engines": {

                "intent":
                    "IntentEngine",

                "action":
                    "ActionEngine",

                "analytics":
                    "AnalyticsEngine",

            },

            "command_authority":
                "QbitDialer",

            "command_admission":
                "submit_command",

        }

        action_input.update(
            semantic_context
        )

        if action_engine is not None:

            action_method = None

            for method_name in (
                "propose",
                "process",
                "evaluate",
                "plan",
                "build_action",
                "create_action",
                "analyze",
            ):

                candidate = getattr(
                    action_engine,
                    method_name,
                    None,
                )

                if callable(candidate):

                    action_method = candidate

                    break

            if action_method is not None:

                try:

                    action_result = (
                        action_method(
                            action_input
                        )
                    )

                    if inspect.isawaitable(
                        action_result
                    ):

                        action_result = (
                            await action_result
                        )

                except TypeError:

                    try:

                        action_result = (
                            action_method(
                                event=action_input
                            )
                        )

                        if inspect.isawaitable(
                            action_result
                        ):

                            action_result = (
                                await action_result
                            )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] ActionEngine "
                            "proposal failed | "
                            "qbit_id=%s | track_id=%s",
                            qbit_id,
                            track_id,
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] ActionEngine "
                        "processing failed | "
                        "qbit_id=%s | track_id=%s",
                        qbit_id,
                        track_id,
                    )

        # ======================================================
        # 7A. ACTION RESULT NORMALIZATION
        #
        # Convert the proposal into a command envelope.
        #
        # QbitDialer remains the authority.
        # ======================================================

        command_proposal = None

        if isinstance(
            action_result,
            dict,
        ):

            command_proposal = dict(
                action_result
            )

        elif action_result is not None:

            command_proposal = {

                "value":
                    action_result,

            }

        if command_proposal is None:

            command_proposal = {}

        # Preserve semantic fields from the Qbit.

        for semantic_field, value in (
            semantic_context.items()
        ):

            if (
                value is not None
                and command_proposal.get(
                    semantic_field
                ) is None
            ):

                command_proposal[
                    semantic_field
                ] = value

        # ======================================================
        # 7B. AUTHORITATIVE COMMAND ENVELOPE
        # ======================================================

        command_envelope = {

            "type":
                "CognitiveCommand",

            "command_type":
                "COGNITIVE_ACTION",

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "feedback_cycle_id":
                feedback_cycle_id,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "intent":
                intent_result,

            "action":
                command_proposal,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "user_input_required":
                False,

            "authority":
                "QbitDialer",

            "command_authority":
                "QbitDialer",

            "command_admission":
                "submit_command",

            "execute":
                False,

            "submit":
                False,

            "execution_owner":
                "QbitQueueLoop",

            "proposed_by":
                "ActionEngine",

            "cognitive_cycle":
                "Qbit cognitive pipeline",

        }

        # Carry WHO / WHAT / WHERE / WHY / HOW at
        # the command-envelope level as well.

        command_envelope.update(
            {
                field:
                    semantic_context.get(
                        field
                    )
                for field in (
                    "who",
                    "what",
                    "where",
                    "why",
                    "how",
                )
                if semantic_context.get(
                    field
                ) is not None
            }
        )

        # ======================================================
        # 7C. COMMAND ADMISSION
        #
        # THIS IS THE RETURN PATH TO THE DIALER.
        #
        # No direct execute().
        # No direct execute_all().
        # No second queue.
        # No direct QbitQueueLoop manipulation.
        #
        # submit_command() is the sole admission point.
        # ======================================================

        command_admission_result = None

        has_action_proposal = bool(
            command_proposal
        )

        if has_action_proposal:

            submit_command = getattr(
                self,
                "submit_command",
                None,
            )

            if callable(
                submit_command
            ):

                try:

                    command_admission_result = (
                        submit_command(
                            command_envelope
                        )
                    )

                    if inspect.isawaitable(
                        command_admission_result
                    ):

                        command_admission_result = (
                            await command_admission_result
                        )

                    self.logger.info(
                        "[QbitDialer] Cognitive action "
                        "submitted for admission | "
                        "qbit_id=%s | track_id=%s | "
                        "feedback_cycle=%s",
                        qbit_id,
                        track_id,
                        feedback_cycle_id,
                    )

                except TypeError:

                    try:

                        command_admission_result = (
                            submit_command(
                                command=command_envelope
                            )
                        )

                        if inspect.isawaitable(
                            command_admission_result
                        ):

                            command_admission_result = (
                                await command_admission_result
                            )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Cognitive command "
                            "admission failed | "
                            "qbit_id=%s | track_id=%s",
                            qbit_id,
                            track_id,
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Cognitive command "
                        "submission failed | "
                        "qbit_id=%s | track_id=%s",
                        qbit_id,
                        track_id,
                    )

            else:

                self.logger.warning(
                    "[QbitDialer] submit_command unavailable | "
                    "cognitive action retained as proposal | "
                    "qbit_id=%s | track_id=%s",
                    qbit_id,
                    track_id,
                )

        # ======================================================
        # 8. COMPLETE COGNITIVE STATE
        # ======================================================

        cognitive_state = {

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "intent":
                intent_result,

            "action":
                action_result,

            "command":
                command_envelope,

            "command_admission":
                command_admission_result,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "feedback_cycle_id":
                feedback_cycle_id,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "user_input_required":
                False,

            "authority":
                "QbitDialer",

        }

        # ======================================================
        # 9. ANALYTICS ENGINE
        # ======================================================

        analytics_engine = getattr(
            self,
            "analytics_engine",
            None,
        )

        analytics_result = None

        analytics_input = {

            "stage":
                "COGNITIVE_CYCLE",

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "intent":
                intent_result,

            "action":
                action_result,

            "command":
                command_envelope,

            "command_admission":
                command_admission_result,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "feedback_cycle_id":
                feedback_cycle_id,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "user_input_required":
                False,

            "authority":
                "QbitDialer",

            "command_authority":
                "QbitDialer",

            "brains": {

                "compute":
                    "ComputeBrain",

                "transformer":
                    "TransformerBrain",

            },

            "engines": {

                "intent":
                    "IntentEngine",

                "action":
                    "ActionEngine",

                "analytics":
                    "AnalyticsEngine",

            },

        }

        if analytics_engine is not None:

            analytics_method = None

            for method_name in (
                "analyze",
                "process",
                "record",
                "record_event",
                "track",
                "track_event",
                "ingest",
            ):

                candidate = getattr(
                    analytics_engine,
                    method_name,
                    None,
                )

                if callable(candidate):

                    analytics_method = candidate

                    break

            if analytics_method is not None:

                try:

                    analytics_result = (
                        analytics_method(
                            analytics_input
                        )
                    )

                    if inspect.isawaitable(
                        analytics_result
                    ):

                        analytics_result = (
                            await analytics_result
                        )

                except TypeError:

                    try:

                        analytics_result = (
                            analytics_method(
                                event=analytics_input
                            )
                        )

                        if inspect.isawaitable(
                            analytics_result
                        ):

                            analytics_result = (
                                await analytics_result
                            )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] AnalyticsEngine "
                            "feedback failed | "
                            "qbit_id=%s | track_id=%s",
                            qbit_id,
                            track_id,
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] AnalyticsEngine "
                        "processing failed | "
                        "qbit_id=%s | track_id=%s",
                        qbit_id,
                        track_id,
                    )

        # ======================================================
        # 10. AUTHORITATIVE COGNITIVE LINK
        # ======================================================

        cognitive_link = {

            "authority":
                "QbitDialer",

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "feedback_cycle_id":
                feedback_cycle_id,

            "user_input_required":
                False,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "brains": {

                "compute":
                    "ComputeBrain",

                "transformer":
                    "TransformerBrain",

            },

            "engines": {

                "intent":
                    "IntentEngine",

                "action":
                    "ActionEngine",

                "analytics":
                    "AnalyticsEngine",

            },

            "dialer": {

                "authority":
                    "QbitDialer",

                "command_admission":
                    "submit_command",

            },

            "execution": {

                "owner":
                    "QbitQueueLoop",

                "admission":
                    "QbitDialer",

                "direct_execution":
                    False,

            },

            "flow": [

                "Qbit",

                "ComputeBrain",

                "ThoughtPacket",

                "TransformerBrain",

                "CognitiveResult",

                "IntentEngine",

                "ActionEngine",

                "QbitDialer",

                "submit_command",

                "QbitQueueLoop",

                "execution_result",

                "AnalyticsEngine",

                "ThoughtFeedback",

                "next_cognitive_cycle",

            ],

            "feedback": {

                "enabled":
                    True,

                "source":
                    "ThoughtFeedback",

                "target":
                    "Qbit cognitive pipeline",

                "reprocess_qbit":
                    True,

            },

        }

        # ======================================================
        # 11. COMPLETE COGNITIVE RESULT
        # ======================================================

        cognitive_result = {

            "status":
                "cognitive_complete",

            "stage":
                "COGNITIVE_FEEDBACK",

            "qbit":
                qbit,

            "qbit_id":
                qbit_id,

            "task_id":
                task_id,

            "track_id":
                track_id,

            "pipeline_id":
                pipeline_id,

            "source":
                source,

            "channel":
                channel,

            "thought":
                thought_packet,

            "transform":
                transformed,

            "intent":
                intent_result,

            "action":
                action_result,

            "command":
                command_envelope,

            "command_admission":
                command_admission_result,

            "analytics":
                analytics_result,

            "semantic_context":
                dict(
                    semantic_context
                ),

            "feedback_cycle_id":
                feedback_cycle_id,

            "cognitive_link":
                cognitive_link,

            "user_input_required":
                False,

            "heartbeat_driven":
                heartbeat_driven,

            "idle_qbit":
                idle_qbit,

            "command_authority":
                "QbitDialer",

            "command_admission_path":
                "submit_command",

            "execution_owner":
                "QbitQueueLoop",

            "thought_feedback":
                True,

        }

        # ======================================================
        # 12. RETAIN THOUGHT FEEDBACK
        # ======================================================

        self.last_thought = (
            thought_packet
        )

        self.last_cognitive_result = (
            cognitive_result
        )

        try:

            if not isinstance(
                getattr(
                    self,
                    "cognitive_state",
                    None,
                ),
                dict,
            ):

                self.cognitive_state = {}

            self.cognitive_state[
                "last_thought"
            ] = thought_packet

            self.cognitive_state[
                "last_cognitive_result"
            ] = cognitive_result

            self.cognitive_state[
                "last_feedback_cycle"
            ] = cognitive_result

            self.cognitive_state[
                "last_qbit"
            ] = qbit

            self.cognitive_state[
                "last_qbit_id"
            ] = qbit_id

            self.cognitive_state[
                "last_task_id"
            ] = task_id

            self.cognitive_state[
                "last_track_id"
            ] = track_id

            self.cognitive_state[
                "last_command"
            ] = command_envelope

            self.cognitive_state[
                "last_command_admission"
            ] = command_admission_result

        except Exception:

            self.logger.debug(
                "[QbitDialer] Cognitive state retention failed",
                exc_info=True,
            )

        # ======================================================
        # 13. THOUGHT FEEDBACK EVENT
        # ======================================================

        try:

            await self._emit_safe(
                "QBIT_THOUGHT_FEEDBACK",
                cognitive_result,
            )

        except Exception:

            self.logger.debug(
                "[QbitDialer] Thought feedback emission failed",
                exc_info=True,
            )

        # ======================================================
        # 14. LOG COMPLETE CYCLE
        # ======================================================

        self.logger.info(
            "[QbitDialer] Cognitive feedback complete | "
            "qbit_id=%s | task_id=%s | track_id=%s | "
            "heartbeat=%s | idle=%s | intent=%s | action=%s | "
            "admission=%s | feedback=%s",
            qbit_id,
            task_id,
            track_id,
            heartbeat_driven,
            idle_qbit,
            (
                intent_result.get("name")
                if isinstance(
                    intent_result,
                    dict,
                )
                else intent_result
            ),
            (
                action_result.get("name")
                if isinstance(
                    action_result,
                    dict,
                )
                else action_result
            ),
            (
                command_admission_result.get("status")
                if isinstance(
                    command_admission_result,
                    dict,
                )
                else command_admission_result
            ),
            feedback_cycle_id,
        )

        return cognitive_result
# ==========================================================

    @property
    def command_count(self):
        return len(self.command_registry)

# ===========================================================
    def enqueue_qbit_frame(self, frame, priority=None):

        queue_loop = getattr(
            self,
            "queue_loop",
            None,
        )

        if queue_loop is None:

            self.logger.warning(
                "[QbitDialer] QbitQueueLoop unavailable"
            )

            return False

        return queue_loop.put(
            frame,
            priority=priority,
        )

# ============================================================================

    def _hud_log(self, message, level="INFO"):

        hud = getattr(
            self,
            "fat_layer",
            None,
        )

        if hud is None:
            return False

        append_log = getattr(
            hud,
            "append_log",
            None,
        )

        if not callable(append_log):
            return False

        try:

            result = append_log(
                message
            )

            if inspect.isawaitable(
                result
            ):

                # --------------------------------------------------
                # IMPORTANT:
                #
                # _hud_log() is synchronous.
                #
                # Do NOT:
                #   - create another event loop
                #   - call asyncio.run()
                #   - create a background thread
                #   - create an uncontrolled task
                #
                # The authoritative async runtime owns scheduling.
                # --------------------------------------------------

                try:

                    running_loop = (
                        asyncio.get_running_loop()
                    )

                except RuntimeError:

                    running_loop = None

                if running_loop is not None:

                    # A loop is already running, but this method is
                    # synchronous. Do not schedule a second runtime.
                    #
                    # Close the unused coroutine when possible so
                    # Python does not leave an unawaited coroutine.

                    close_method = getattr(
                        result,
                        "close",
                        None,
                    )

                    if callable(close_method):

                        try:
                            close_method()
                        except Exception:
                            pass

                    self.logger.debug(
                        "[QbitDialer] HUD append_log returned "
                        "awaitable; authoritative async runtime "
                        "owns scheduling"
                    )

                    return False

                # No running event loop exists here. The synchronous
                # HUD interface cannot safely execute an async result.
                close_method = getattr(
                    result,
                    "close",
                    None,
                )

                if callable(close_method):

                    try:
                        close_method()
                    except Exception:
                        pass

                self.logger.debug(
                    "[QbitDialer] HUD append_log returned "
                    "awaitable; no async runtime available"
                )

                return False

            return True

        except Exception:

            self.logger.debug(
                "[QbitDialer] HUD logging failed",
                exc_info=True,
            )

            return False

    # ======================================================
    # SAFE RE-BINDING
    #
    # BIND EXISTING RUNTIME DEPENDENCIES ONLY.
    #
    # IMPORTANT:
    #
    # This method NEVER:
    #
    #     - creates a Qbit
    #     - creates a ComputeBrain
    #     - creates a TransformerBrain
    #     - creates a QbitQueueLoop
    #     - creates a command queue
    #     - starts a runtime
    #
    # It only reconnects already-authoritative objects.
    # ======================================================

    def _refresh_runtime_bindings(
        self,
        *,
        event_bus=None,
        emit=None,
        seedcore=None,
        compute_brain=None,
        transformer_brain=None,
        qbit_queue=None,
        qbit_queue_loop=None,
        heartbeatemitter=None,
        action_engine=None,
        loop=None,
    ):

        # --------------------------------------------------
        # EventBus
        # --------------------------------------------------

        if event_bus is not None:

            self.event_bus = event_bus

        if emit is not None:

            self.emit = emit

        elif getattr(
            self,
            "event_bus",
            None,
        ) is not None:

            event_emit = getattr(
                self.event_bus,
                "emit",
                None,
            )

            if callable(
                event_emit
            ):

                self.emit = event_emit

        # --------------------------------------------------
        # Core
        # --------------------------------------------------

        if seedcore is not None:

            self.seedcore = seedcore
            self.seed_core = seedcore
            self.core = seedcore

        # --------------------------------------------------
        # Existing cognitive authorities
        #
        # Never construct replacements here.
        # --------------------------------------------------

        if compute_brain is not None:

            existing_compute_brain = getattr(
                self,
                "compute_brain",
                None,
            )

            if (
                existing_compute_brain is not None
                and existing_compute_brain is not compute_brain
            ):

                raise RuntimeError(
                    "[QbitDialer] "
                    "ComputeBrain identity violation during "
                    "runtime rebinding"
                )

            self.compute_brain = compute_brain

        if transformer_brain is not None:

            existing_transformer_brain = getattr(
                self,
                "transformer_brain",
                None,
            )

            if (
                existing_transformer_brain is not None
                and existing_transformer_brain is not transformer_brain
            ):

                raise RuntimeError(
                    "[QbitDialer] "
                    "TransformerBrain identity violation during "
                    "runtime rebinding"
                )

            self.transformer_brain = transformer_brain

        # --------------------------------------------------
        # Validate already-bound cognitive authorities.
        # --------------------------------------------------

        current_compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if current_compute_brain is not None:

            if not callable(
                getattr(
                    current_compute_brain,
                    "process",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "Bound ComputeBrain does not expose process()"
                )

        current_transformer_brain = getattr(
            self,
            "transformer_brain",
            None,
        )

        if current_transformer_brain is not None:

            if not callable(
                getattr(
                    current_transformer_brain,
                    "analyze",
                    None,
                )
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "Bound TransformerBrain does not expose analyze()"
                )

        # --------------------------------------------------
        # Heartbeat
        # --------------------------------------------------

        if heartbeatemitter is not None:

            self.heartbeatemitter = (
                heartbeatemitter
            )

            self.heartbeat = (
                heartbeatemitter
            )

        # --------------------------------------------------
        # ActionEngine
        # --------------------------------------------------

        if ActionEngine is not None:

            self.actionengine = (
                actionengine
            )

            self.actionengine = (
                actionengine
            )


        # --------------------------------------------------
        # Async loop
        # --------------------------------------------------

        if loop is not None:

            self.loop = loop

        # ==================================================
        # QUEUE REBINDING
        #
        # QbitQueueLoop is authoritative.
        #
        # A raw queue MUST NOT be converted into a new loop.
        # ==================================================

        supplied_loop = None

        if isinstance(
            qbit_queue_loop,
            QbitQueueLoop,
        ):

            supplied_loop = (
                qbit_queue_loop
            )

        elif isinstance(
            qbit_queue,
            QbitQueueLoop,
        ):

            supplied_loop = (
                qbit_queue
            )

        # --------------------------------------------------
        # Existing authoritative loop
        # --------------------------------------------------

        if supplied_loop is not None:

            existing_loop = getattr(
                self,
                "queue_loop",
                None,
            )

            if (
                existing_loop is not None
                and existing_loop is not supplied_loop
            ):

                raise RuntimeError(
                    "[QbitDialer] "
                    "QbitQueueLoop identity violation during "
                    "runtime rebinding"
                )

            self.queue_loop = supplied_loop

            self._qbit_queue = supplied_loop
            self.qbit_queue = supplied_loop

        # --------------------------------------------------
        # No supplied loop:
        #
        # Preserve the already-bound authoritative loop.
        # --------------------------------------------------

        else:

            existing_loop = getattr(
                self,
                "queue_loop",
                None,
            )

            if existing_loop is not None:

                self._qbit_queue = (
                    existing_loop
                )

                self.qbit_queue = (
                    existing_loop
                )

        # ==================================================
        # FINAL QUEUE IDENTITY VALIDATION
        # ==================================================

        final_loop = getattr(
            self,
            "queue_loop",
            None,
        )

        if final_loop is not None:

            if not isinstance(
                final_loop,
                QbitQueueLoop,
            ):

                raise TypeError(
                    "[QbitDialer] "
                    "queue_loop is not a QbitQueueLoop: "
                    f"{type(final_loop)!r}"
                )

            if getattr(
                self,
                "_qbit_queue",
                None,
            ) is not final_loop:

                raise RuntimeError(
                    "[QbitDialer] "
                    "_qbit_queue / queue_loop identity mismatch"
                )

            if getattr(
                self,
                "qbit_queue",
                None,
            ) is not final_loop:

                raise RuntimeError(
                    "[QbitDialer] "
                    "qbit_queue / queue_loop identity mismatch"
                )

        # ==================================================
        # QUEUE COMMAND AUTHORITY
        #
        # Reconnect the existing Dialer to the same loop.
        # Do not replace the loop.
        # ==================================================

        if final_loop is not None:

            try:

                set_handler = getattr(
                    final_loop,
                    "set_handler",
                    None,
                )

                if callable(
                    set_handler
                ):

                    set_handler(
                        self.execute_command
                    )

            except Exception as exc:

                self.logger.warning(
                    "[QbitDialer] "
                    "runtime queue handler rebinding warning | %s",
                    exc,
                )

        # ==================================================
        # FINAL BRAIN / RUNTIME DIAGNOSTIC
        # ==================================================

        self.logger.debug(
            "[QbitDialer] Runtime bindings refreshed | "
            "event_bus=%s | "
            "compute_brain=%s | "
            "transformer_brain=%s | "
            "queue_loop=%s | "
            "action_engine=%s | "
            "heartbeat=%s | "
            "seedcore=%s",
            type(
                getattr(
                    self,
                    "event_bus",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "compute_brain",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "transformer_brain",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "queue_loop",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "action_engine",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "heartbeatemitter",
                    None,
                )
            ).__name__,
            type(
                getattr(
                    self,
                    "seedcore",
                    None,
                )
            ).__name__,
        )

        return self

    # ======================================================
    # QBIT STATE INITIALIZATION
    # ======================================================

    def _initialize_qbit_state(
        self,
        initial_state=None,
    ):

        q = self.qbit

        if not isinstance(
            q,
            QbitClass,
        ):

            raise RuntimeError(
                "[QBIT CORRUPTION] "
                f"Expected Qbit, got {type(q)!r}"
            )

        # --------------------------------------------------
        # Initial vector
        # --------------------------------------------------

        if initial_state is None:

            initial_state = getattr(
                q,
                "state",
                None,
            )

        if initial_state is None:

            initial_state = (
                1.0 + 0.0j,
                0.0 + 0.0j,
            )

        try:

            self.initial_state = (
                normalize_qbit_input(
                    initial_state
                )
            )

        except Exception:

            self.logger.warning(
                "[QbitDialer] "
                "Invalid initial Qbit state; "
                "using |0>"
            )

            self.initial_state = (
                1.0 + 0.0j,
                0.0 + 0.0j,
            )

        # --------------------------------------------------
        # Upstream track
        # --------------------------------------------------

        upstream = getattr(
            q,
            "upstream_track",
            {},
        )

        if not isinstance(
            upstream,
            dict,
        ):

            upstream = {}

        # --------------------------------------------------
        # Local state
        # --------------------------------------------------

        self.qbit_state = {
            "tick": upstream.get(
                "tick"
            ),
            "chaos": 0.0,
            "monitor": 0.95,
            "analytics": 0.5,
            "multiplier": 1.0,
            "pressure": 0.0,
            "state": self.initial_state,
            "lifecycle": "CONSTRUCTED",
        }

        # --------------------------------------------------
        # Preserve Qbit weight
        # --------------------------------------------------

        try:

            current_weight = float(
                getattr(
                    q,
                    "weight",
                    1.0,
                )
            )

        except (
            TypeError,
            ValueError,
        ):

            current_weight = 1.0

        if not math.isfinite(
            current_weight
        ):

            current_weight = 1.0

        q.weight = current_weight

        # --------------------------------------------------
        # Track identity
        # --------------------------------------------------

        if (
            self.track_manager is not None
            and self._track_id is None
        ):

            try:

                qbit_id = (
                    getattr(
                        q,
                        "id",
                        None,
                    )
                    or
                    getattr(
                        q,
                        "qbit_id",
                        None,
                    )
                )

                metadata = {
                    "source": "QbitDialer",
                    "module": "qbit_dialer",
                    "module_id": "QBIT-DIALER",
                    "qbit_id": qbit_id,
                    "qbit_state": dict(
                        self.qbit_state
                    ),
                    "weight": q.weight,
                    "channel": "QBIT",
                    "authority": "SYSTEM",
                }

                new_track = getattr(
                    self.track_manager,
                    "new",
                    None,
                )

                if callable(
                    new_track
                ):

                    self._track_id = (
                        new_track(
                            channel="QBIT",
                            skill="QBIT",
                            priority=50,
                            metadata=metadata,
                            domain_override="SYSTEM",
                            reasoning_input=self.qbit_state,
                        )
                    )

                if self._track_id is not None:

                    if not isinstance(
                        getattr(
                            q,
                            "track",
                            None,
                        ),
                        dict,
                    ):

                        q.track = {}

                    q.track[
                        "track_id"
                    ] = self._track_id

            except Exception:

                self.logger.exception(
                    "[QbitDialer] "
                    "Track identity initialization failed"
                )

    # ======================================================
    # QUEUE BINDING
    #
    # BIND ONLY.
    #
    # QbitDialer never creates a QbitQueueLoop here.
    # Runtime ownership remains with main.py.
    # ======================================================

    def bind_queue_loop(
        self,
        queue_loop,
    ):

        if not isinstance(
            queue_loop,
            QbitQueueLoop,
        ):

            raise TypeError(
                "[QbitDialer] "
                "queue_loop must be QbitQueueLoop"
            )

        # --------------------------------------------------
        # Existing authoritative queue
        #
        # Never replace it with another instance.
        # --------------------------------------------------

        existing_queue = getattr(
            self,
            "queue_loop",
            None,
        )

        if existing_queue is not None:

            if existing_queue is not queue_loop:

                raise RuntimeError(
                    "[QbitDialer] "
                    "authoritative QbitQueueLoop identity "
                    "violation in bind_queue_loop"
                )

        # --------------------------------------------------
        # Bind exact authoritative object.
        # --------------------------------------------------

        self.queue_loop = (
            queue_loop
        )

        self._qbit_queue = (
            queue_loop
        )

        self.qbit_queue = (
            queue_loop
        )

        # --------------------------------------------------
        # Bind command authority.
        #
        # Binding only.
        # Does NOT start the queue loop.
        # --------------------------------------------------

        try:

            set_handler = getattr(
                queue_loop,
                "set_handler",
                None,
            )

            if callable(
                set_handler
            ):

                set_handler(
                    self.execute_command
                )

            elif hasattr(
                queue_loop,
                "handler",
            ):

                current_handler = getattr(
                    queue_loop,
                    "handler",
                    None,
                )

                if current_handler is None:

                    queue_loop.handler = (
                        self.execute_command
                    )

                elif (
                    current_handler
                    is not self.execute_command
                ):

                    self.logger.warning(
                        "[QbitDialer] "
                        "QbitQueueLoop already has a "
                        "different handler; preserving "
                        "existing handler"
                    )

        except Exception as exc:

            self.logger.warning(
                "[QbitDialer] "
                "Queue handler binding warning | %s",
                exc,
            )

        # --------------------------------------------------
        # Final identity assertion
        # --------------------------------------------------

        if (
            self.queue_loop is not queue_loop
            or self._qbit_queue is not queue_loop
            or self.qbit_queue is not queue_loop
        ):

            raise RuntimeError(
                "[QbitDialer] "
                "QbitQueueLoop alias identity violation"
            )

        # --------------------------------------------------
        # Runtime remains OFF.
        #
        # This method only establishes ownership/binding.
        # --------------------------------------------------

        self.logger.info(
            "[QbitDialer] "
            "QbitQueueLoop bound | "
            "same_instance=True | "
            "runtime=OFF"
        )

        return queue_loop
    # ======================================================
    # EVENT BUS BINDING
    #
    # FREE DATA PIPELINE
    #
    # EventBus carries:
    #
    #   INFO
    #   QBIT
    #   COMPUTE
    #   TELEMETRY
    #   STATE
    #   HEARTBEAT
    #   TRACK
    #   SYSTEM
    #   COMMAND
    #   OTHER DATA
    #
    # QbitDialer may consume and emit through the bus.
    #
    # This method ONLY binds the bus.
    # It does NOT create a bus.
    # It does NOT start runtime.
    # It does NOT route arbitrary data into
    # execute_command().
    # ======================================================

    def set_event_bus(
        self,
        event_bus,
    ):

        if event_bus is None:

            raise ValueError(
                "[QbitDialer] "
                "event_bus cannot be None"
            )

        # --------------------------------------------------
        # EventBus must provide an outbound data interface.
        #
        # emit() is preferred.
        # publish() remains compatible with older buses.
        # --------------------------------------------------

        event_emit = getattr(
            event_bus,
            "emit",
            None,
        )

        event_publish = getattr(
            event_bus,
            "publish",
            None,
        )

        if not callable(
            event_emit
        ) and not callable(
            event_publish
        ):

            raise TypeError(
                "[QbitDialer] "
                "event_bus requires emit() "
                "or publish()"
            )

        # --------------------------------------------------
        # Preserve authoritative EventBus.
        # --------------------------------------------------

        self.event_bus = event_bus

        # --------------------------------------------------
        # Preferred emitter.
        # --------------------------------------------------

        if callable(
            event_emit
        ):

            self.emit = event_emit

        else:

            self.emit = event_publish

        # --------------------------------------------------
        # Compatibility emitter.
        #
        # Keep a callable reference available without
        # changing the authoritative EventBus.
        # --------------------------------------------------

        self.emit_callback = (
            self.emit
        )

        # --------------------------------------------------
        # Capability flags.
        #
        # These describe what the bound bus supports.
        # They do not alter routing behavior.
        # --------------------------------------------------

        self._event_bus_supports_emit = (
            callable(event_emit)
        )

        self._event_bus_supports_publish = (
            callable(event_publish)
        )

        # --------------------------------------------------
        # EventBus identity.
        # --------------------------------------------------

        self._event_bus_bound = True

        self.logger.info(
            "[QbitDialer] EventBus bound | "
            "type=%s | "
            "emit=%s | "
            "publish=%s | "
            "pipeline=FREE_DATA",
            type(
                event_bus
            ).__name__,
            self._event_bus_supports_emit,
            self._event_bus_supports_publish,
        )

        return event_bus
# =======================================================================

# =======================================================================
    # ------------------------- REST OF FUNCTIONS --------------------------

    def _schedule_async(
        self,
        coro,
    ):

        if coro is None:

            return None

        # --------------------------------------------------
        # Resolve authoritative asyncio loop.
        # --------------------------------------------------

        loop = getattr(
            self,
            "loop",
            None,
        )

        if loop is None:

            try:

                loop = asyncio.get_running_loop()

            except RuntimeError:

                loop = None

        # --------------------------------------------------
        # No loop available.
        #
        # Prevent:
        #
        #   coroutine was never awaited
        #
        # by explicitly closing the coroutine.
        # --------------------------------------------------

        if loop is None:

            self.logger.warning(
                "[QbitDialer] "
                "No asyncio loop available"
            )

            try:

                coro.close()

            except Exception:

                pass

            return None

        # --------------------------------------------------
        # Running loop.
        #
        # If already executing on this loop, schedule
        # directly without crossing a thread boundary.
        # --------------------------------------------------

        if loop.is_running():

            try:

                running_loop = (
                    asyncio.get_running_loop()
                )

            except RuntimeError:

                running_loop = None

            if running_loop is loop:

                return loop.create_task(
                    coro
                )

            # --------------------------------------------------
            # Loop is running elsewhere.
            #
            # Thread-safe submission preserves the existing
            # cross-thread behavior.
            # --------------------------------------------------

            return asyncio.run_coroutine_threadsafe(
                coro,
                loop,
            )

        # --------------------------------------------------
        # Loop exists but is not currently running.
        # --------------------------------------------------

        try:

            return loop.create_task(
                coro
            )

        except Exception as exc:

            self.logger.warning(
                "[QbitDialer] "
                "Unable to schedule coroutine | %s",
                exc,
            )

            try:

                coro.close()

            except Exception:

                pass

            return None

    # ======================================================================
    # QBIT / TRACK IDENTITY AUTHORITY
    #
    # Qbit = DATA / BLOOD CELL
    #
    # TrackID = DATA PATH / RELATIONSHIP IDENTITY
    #
    # QbitDialer owns the binding relationship to the PRIMARY /
    # AUTHORITATIVE Qbit.
    #
    # TrackSystem / TrackIDManager remains responsible for TrackID
    # creation and assignment.
    #
    # MULTI-QBIT ARCHITECTURE:
    #
    #     PRIMARY QBIT
    #         |
    #         +--> task / cognitive chain
    #         |
    #         +--> subsequent Qbits
    #                 |
    #                 +--> own qbit_id
    #                 +--> own track_id
    #                 +--> shared task/pipeline/parent context
    #
    # `self.qbit` represents the Dialer's authoritative bound Qbit.
    #
    # It does NOT mean that only one Qbit may exist in the system.
    #
    # Incoming/subsequent Qbits must be processed through:
    #
    #     submit_qbit_command()
    #          â†“
    #     _process_received_qbit()
    #          â†“
    #     ComputeBrain
    #          â†“
    #     TransformerBrain
    #          â†“
    #     submit_command()
    #
    # This section NEVER:
    #
    #     - creates a Qbit
    #     - creates a TrackID
    #     - creates a queue
    #     - starts a loop
    #     - starts a runtime
    #     - executes a command
    #     - replaces another Qbit's identity
    #
    # It ONLY binds/synchronizes EXISTING authoritative identity.
    # ======================================================================

    @property
    def qbit(
        self,
    ):

        return getattr(
            self,
            "_qbit",
            None,
        )


    @qbit.setter
    def qbit(
        self,
        value,
    ):

        # ==============================================================
        # [PHASE: QBIT AUTHORITY BINDING]
        # [AUTHORITY: Qbit]
        # [OWNER: QbitDialer]
        #
        # This setter binds the Dialer's PRIMARY / AUTHORITATIVE Qbit.
        #
        # It does not claim ownership of every Qbit that enters the
        # system.
        # ==============================================================

        from seed.core.qbit.qbit import Qbit

        if not isinstance(
            value,
            Qbit,
        ):

            raise TypeError(
                "[LOCKED] "
                "qbit must be Qbit instance, "
                f"got {type(value)!r}"
            )

        # ==============================================================
        # EXISTING AUTHORITATIVE QBIT
        #
        # If the exact same Qbit is supplied again, this is a harmless
        # rebinding/idempotent synchronization.
        # ==============================================================

        existing_qbit = getattr(
            self,
            "_qbit",
            None,
        )

        if existing_qbit is not None:

            if existing_qbit is value:

                self._synchronize_qbit_authority(
                    value
                )

                return

            # ----------------------------------------------------------
            # A DIFFERENT Qbit is a legitimate DATA object.
            #
            # Do NOT replace the Dialer's authoritative primary Qbit.
            #
            # The incoming Qbit must remain independently identifiable
            # and enter the normal receive/cognitive pipeline.
            # ----------------------------------------------------------

            self.logger.debug(
                "[QbitDialer] Secondary Qbit received | "
                "primary_qbit=%s | incoming_qbit=%s | "
                "route=RECEIVE_PIPELINE",
                getattr(
                    existing_qbit,
                    "id",
                    None,
                ),
                getattr(
                    value,
                    "id",
                    None,
                ),
            )

            # ----------------------------------------------------------
            # Preserve the incoming Qbit's own identity and metadata.
            #
            # No replacement of self._qbit occurs here.
            # ----------------------------------------------------------

            self._synchronize_qbit_authority(
                value,
                bind_primary=False,
            )

            return

        # ==============================================================
        # FIRST AUTHORITATIVE QBIT BINDING
        # ==============================================================

        self._qbit = value

        self._synchronize_qbit_authority(
            value,
            bind_primary=True,
        )


    # ======================================================================
    # QBIT AUTHORITY SYNCHRONIZATION
    #
    # Synchronizes EXISTING metadata only.
    #
    # This helper does not create identity.
    # ======================================================================

    def _synchronize_qbit_authority(
        self,
        qbit,
        *,
        bind_primary=False,
    ):

        # ==============================================================
        # 1. RESOLVE EXISTING QBIT ID
        # ==============================================================

        qbit_id = getattr(
            qbit,
            "qbit_id",
            None,
        )

        if qbit_id is None:

            qbit_id = getattr(
                qbit,
                "id",
                None,
            )

        # ==============================================================
        # 2. RESOLVE EXISTING TRACK ID
        #
        # Never generate one here.
        # ==============================================================

        qbit_track_id = getattr(
            qbit,
            "track_id",
            None,
        )

        if qbit_track_id is None:

            qbit_track = getattr(
                qbit,
                "track",
                None,
            )

            if isinstance(
                qbit_track,
                dict,
            ):

                qbit_track_id = (
                    qbit_track.get(
                        "track_id"
                    )
                    or qbit_track.get(
                        "id"
                    )
                )

            elif qbit_track is not None:

                qbit_track_id = (
                    getattr(
                        qbit_track,
                        "track_id",
                        None,
                    )
                    or getattr(
                        qbit_track,
                        "id",
                        None,
                    )
                )

        # ==============================================================
        # 3. SYNCHRONIZE DIALER TRACK CONTEXT
        #
        # Only the PRIMARY Qbit establishes the Dialer's default
        # track context.
        #
        # Secondary Qbits retain their own track identity.
        # ==============================================================

        if bind_primary:

            current_track_id = getattr(
                self,
                "_track_id",
                None,
            )

            if current_track_id is None:

                if qbit_track_id is not None:

                    self._track_id = qbit_track_id

                    current_track_id = (
                        qbit_track_id
                    )

            elif (
                qbit_track_id is not None
                and current_track_id != qbit_track_id
            ):

                # ------------------------------------------------------
                # Do NOT overwrite the Dialer's established primary
                # TrackID because another Qbit arrived.
                # ------------------------------------------------------

                self.logger.debug(
                    "[QbitDialer] Primary TrackID preserved | "
                    "dialer_track=%s | incoming_qbit_track=%s",
                    current_track_id,
                    qbit_track_id,
                )

        else:

            current_track_id = qbit_track_id

        # ==============================================================
        # 4. PRESERVE QBIT TRACK STRUCTURE
        # ==============================================================

        qbit_track = getattr(
            qbit,
            "track",
            None,
        )

        if (
            qbit_track_id is not None
            and isinstance(
                qbit_track,
                dict,
            )
            and qbit_track.get(
                "track_id"
            ) is None
        ):

            qbit_track[
                "track_id"
            ] = qbit_track_id

        # ==============================================================
        # 5. PRESERVE EXISTING TASK / PIPELINE CONTEXT
        #
        # These fields are relationship metadata, not new identity.
        # ==============================================================

        task = getattr(
            qbit,
            "task",
            None,
        )

        task_id = getattr(
            qbit,
            "task_id",
            None,
        )

        pipeline_id = getattr(
            qbit,
            "pipeline_id",
            None,
        )

        parent_id = getattr(
            qbit,
            "parent_id",
            None,
        )

        relationships = getattr(
            qbit,
            "relationships",
            None,
        )

        data_lineage = getattr(
            qbit,
            "data_lineage",
            None,
        )

        # --------------------------------------------------------------
        # If a task already carries these values, preserve them on the
        # Qbit object only when the Qbit does not already expose them.
        # --------------------------------------------------------------

        if isinstance(
            task,
            dict,
        ):

            if task_id is None:

                task_id = task.get(
                    "task_id"
                )

            if pipeline_id is None:

                pipeline_id = task.get(
                    "pipeline_id"
                )

            if parent_id is None:

                parent_id = task.get(
                    "parent_id"
                )

            if relationships is None:

                relationships = task.get(
                    "relationships"
                )

            if data_lineage is None:

                data_lineage = task.get(
                    "data_lineage"
                )

        # ==============================================================
        # 6. PRESERVE ACCESS TO EXISTING IDENTITY
        #
        # qbit.id remains authoritative.
        #
        # qbit.qbit_id is only synchronized when it is missing.
        # ==============================================================

        if (
            qbit_id is not None
            and getattr(
                qbit,
                "qbit_id",
                None,
            ) is None
        ):

            try:

                qbit.qbit_id = qbit_id

            except Exception:

                pass

        if (
            qbit_track_id is not None
            and getattr(
                qbit,
                "track_id",
                None,
            ) is None
        ):

            try:

                qbit.track_id = qbit_track_id

            except Exception:

                pass

        if (
            task_id is not None
            and getattr(
                qbit,
                "task_id",
                None,
            ) is None
        ):

            try:

                qbit.task_id = task_id

            except Exception:

                pass

        if (
            pipeline_id is not None
            and getattr(
                qbit,
                "pipeline_id",
                None,
            ) is None
        ):

            try:

                qbit.pipeline_id = pipeline_id

            except Exception:

                pass

        if (
            parent_id is not None
            and getattr(
                qbit,
                "parent_id",
                None,
            ) is None
        ):

            try:

                qbit.parent_id = parent_id

            except Exception:

                pass

        if (
            relationships is not None
            and getattr(
                qbit,
                "relationships",
                None,
            ) is None
        ):

            try:

                qbit.relationships = relationships

            except Exception:

                pass

        if (
            data_lineage is not None
            and getattr(
                qbit,
                "data_lineage",
                None,
            ) is None
        ):

            try:

                qbit.data_lineage = data_lineage

            except Exception:

                pass

        # ==============================================================
        # 7. REGISTER QBIT WITHOUT REPLACING PRIMARY QBIT
        #
        # If the Dialer already has a registry, retain the exact Qbit
        # instance for later relationship/cognitive processing.
        # ==============================================================

        try:

            registry = getattr(
                self,
                "registry",
                None,
            )

            if not isinstance(
                registry,
                dict,
            ):

                registry = {}

                self.registry = registry

            if qbit_id is not None:

                existing_registered = registry.get(
                    qbit_id
                )

                if (
                    existing_registered is None
                    or existing_registered is qbit
                ):

                    registry[
                        qbit_id
                    ] = qbit

        except Exception:

            self.logger.debug(
                "[QbitDialer] Qbit registry synchronization failed",
                exc_info=True,
            )

        # ==============================================================
        # 8. NON-DESTRUCTIVE DIALER LINK
        #
        # This records the relationship only.
        # It does not make the Dialer the creator of the Qbit.
        # ==============================================================

        try:

            if not hasattr(
                qbit,
                "dialer",
            ):

                qbit.dialer = self

        except Exception:

            pass

        # ==============================================================
        # 9. OBSERVABILITY
        # ==============================================================

        try:

            self.logger.debug(
                "[QbitDialer] Qbit identity synchronized | "
                "primary=%s | "
                "qbit_id=%s | "
                "track_id=%s | "
                "task_id=%s | "
                "pipeline_id=%s | "
                "parent_id=%s",
                bind_primary,
                qbit_id,
                qbit_track_id,
                task_id,
                pipeline_id,
                parent_id,
            )

        except Exception:

            pass

    # ======================================================================
    # TRACK ID
    #
    # Read-only identity view from the perspective of QbitDialer.
    #
    # Priority:
    #
    #     1. Live Dialer track
    #     2. Qbit track
    #     3. Dialer cached identity
    #
    # No identity is generated here.
    # ======================================================================

    @property
    def track_id(
        self,
    ):
        # ==============================================================
        # [PHASE: TRACK ID READ]
        # [AUTHORITY: TrackIDManager]
        # [OWNER: QbitDialer]
        #
        # Return the current authoritative TrackID.
        # ==============================================================

        track = getattr(
            self,
            "track",
            None,
        )

        # --------------------------------------------------------------
        # 1. Live Dialer Track
        # --------------------------------------------------------------

        if isinstance(
            track,
            dict,
        ):

            track_id = track.get(
                "track_id"
            )

            if track_id is not None:

                return track_id

        # --------------------------------------------------------------
        # 2. Authoritative Qbit Track
        # --------------------------------------------------------------

        qbit = getattr(
            self,
            "_qbit",
            None,
        )

        if qbit is not None:

            qbit_track = getattr(
                qbit,
                "track",
                None,
            )

            if isinstance(
                qbit_track,
                dict,
            ):

                track_id = qbit_track.get(
                    "track_id"
                )

                if track_id is not None:

                    return track_id

            qbit_track_id = getattr(
                qbit,
                "track_id",
                None,
            )

            if qbit_track_id is not None:

                return qbit_track_id

        # --------------------------------------------------------------
        # 3. Initialization / binding fallback
        # --------------------------------------------------------------

        return getattr(
            self,
            "_track_id",
            None,
        )


    @track_id.setter
    def track_id(
        self,
        value,
    ):
        # ==============================================================
        # [PHASE: TRACK ID STORAGE]
        # [AUTHORITY: TrackIDManager]
        # [OWNER: QbitDialer]
        #
        # Store an already-authorized identity.
        #
        # This setter does NOT generate or reinterpret identity.
        # ==============================================================

        if value is None:

            self._track_id = None

            return

        self._track_id = value

        # --------------------------------------------------------------
        # Synchronize existing Dialer Track.
        # --------------------------------------------------------------

        track = getattr(
            self,
            "track",
            None,
        )

        if isinstance(
            track,
            dict,
        ):

            track[
                "track_id"
            ] = value

        # --------------------------------------------------------------
        # Synchronize existing authoritative Qbit.
        #
        # Qbit identity is preserved; only the already-authorized
        # TrackID relationship is propagated.
        # --------------------------------------------------------------

        qbit = getattr(
            self,
            "_qbit",
            None,
        )

        if qbit is not None:

            try:

                qbit_track = getattr(
                    qbit,
                    "track",
                    None,
                )

                if isinstance(
                    qbit_track,
                    dict,
                ):

                    qbit_track[
                        "track_id"
                    ] = value

            except Exception:

                pass

            try:

                if getattr(
                    qbit,
                    "track_id",
                    None,
                ) is None:

                    qbit.track_id = value

            except Exception:

                pass

        # --------------------------------------------------------------
        # Observability.
        # --------------------------------------------------------------

        try:

            self.logger.debug(
                "[QbitDialer] "
                "TrackID synchronized | "
                "track_id=%s | "
                "qbit_id=%s",
                value,
                getattr(
                    qbit,
                    "id",
                    getattr(
                        qbit,
                        "qbit_id",
                        None,
                    ),
                )
                if qbit is not None
                else None,
            )

        except Exception:

            pass

    def _encode(
        self,
        qbit_data,
    ):

        try:

            # ------------------------------------------------------
            # Preferred structured serialization.
            # ------------------------------------------------------

            if isinstance(
                qbit_data,
                dict,
            ):

                envelope = dict(
                    qbit_data
                )

            else:

                # Preserve object data without requiring the
                # transport layer to understand the object.
                envelope = {
                    "data": qbit_data,
                }

            # ------------------------------------------------------
            # Explicit transport identity.
            # ------------------------------------------------------

            envelope.setdefault(
                "data_type",
                "QBIT_DATA",
            )

            envelope.setdefault(
                "data_role",
                "BLOOD_CELL",
            )

            envelope.setdefault(
                "transport_source",
                "QbitDialer",
            )

            envelope.setdefault(
                "transport_authority",
                "QbitDialer",
            )

            envelope.setdefault(
                "transport_timestamp",
                time.time(),
            )

            # ------------------------------------------------------
            # JSON provides deterministic structured transport.
            #
            # default=str preserves compatibility with UUID,
            # enums, custom IDs, and legacy objects.
            # ------------------------------------------------------

            return json.dumps(
                envelope,
                default=str,
                separators=(
                    ",",
                    ":",
                ),
            ).encode(
                "utf-8"
            )

        except Exception:

            # ------------------------------------------------------
            # Last-resort compatibility encoding.
            #
            # Never allow transport serialization failure to
            # destroy the Qbit pipeline.
            # ------------------------------------------------------

            return str(
                qbit_data
            ).encode(
                "utf-8"
            )


    # ==========================================================
    # QBIT DATA PROCESS / SEND
    #
    # AUTHORITATIVE QBIT DATA TRANSPORT BRIDGE
    #
    # This method prepares Qbit/data for transport.
    #
    # It does NOT:
    #
    #     - execute commands
    #     - call command handlers
    #     - create a command queue
    #     - create a QbitQueueLoop
    #     - create a second runtime
    #     - create a second Qbit
    #
    # DATA FLOW:
    #
    #     Qbit / Qbit Data
    #          |
    #          v
    #     identity + lineage
    #          |
    #          v
    #     task / track / pipeline context
    #          |
    #          v
    #     capability metadata
    #          |
    #          v
    #     transport envelope
    #          |
    #          v
    #        _encode()
    #          |
    #          v
    #         send()
    #
    # COGNITIVE / COMMAND PROCESSING remains separate:
    #
    #     Qbit
    #       -> ComputeBrain
    #       -> ThoughtPacket
    #       -> TransformerBrain
    #       -> command envelope
    #       -> submit_command()
    #
    # ==========================================================

    def process_and_send(
        self,
        qbit_data,
    ):

        try:

            # ======================================================
            # 1. DETERMINE INPUT TYPE
            #
            # Preserve a real Qbit object as DATA.
            #
            # Never stringify the Qbit.
            # ======================================================

            qbit_type = globals().get(
                "Qbit",
                None,
            )

            is_qbit_object = (
                qbit_type is not None
                and isinstance(
                    qbit_data,
                    qbit_type,
                )
            )

            # ======================================================
            # 2. BUILD BASE TRANSPORT ENVELOPE
            # ======================================================

            if is_qbit_object:

                qbit = qbit_data

                transport_data = {

                    "qbit": qbit,

                }

            elif isinstance(
                qbit_data,
                dict,
            ):

                qbit = qbit_data.get(
                    "qbit"
                )

                transport_data = dict(
                    qbit_data
                )

            else:

                qbit = None

                transport_data = {

                    "data": qbit_data,

                }

            # ======================================================
            # 3. RESOLVE EXISTING QBIT IDENTITY
            #
            # Do not manufacture Qbit identity here.
            # ======================================================

            qbit_id = transport_data.get(
                "qbit_id"
            )

            if qbit_id is None and qbit is not None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "qbit_id",
                    None,
                )

            if qbit_id is None and qbit is not None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            track_id = transport_data.get(
                "track_id"
            )

            if track_id is None and qbit is not None:

                track_id = self._extract_qbit_field(
                    qbit,
                    "track_id",
                    None,
                )

            task_id = transport_data.get(
                "task_id"
            )

            if task_id is None and qbit is not None:

                task_id = self._extract_qbit_field(
                    qbit,
                    "task_id",
                    None,
                )

            pipeline_id = transport_data.get(
                "pipeline_id"
            )

            if pipeline_id is None and qbit is not None:

                pipeline_id = self._extract_qbit_field(
                    qbit,
                    "pipeline_id",
                    None,
                )

            parent_id = transport_data.get(
                "parent_id"
            )

            if parent_id is None and qbit is not None:

                parent_id = self._extract_qbit_field(
                    qbit,
                    "parent_id",
                    None,
                )

            # ======================================================
            # 4. EXISTING QBIT TASK CONTEXT
            # ======================================================

            task = transport_data.get(
                "task"
            )

            if task is None and qbit is not None:

                task = self._extract_qbit_field(
                    qbit,
                    "task",
                    None,
                )

            if isinstance(
                task,
                dict,
            ):

                task_id = (
                    task.get(
                        "task_id"
                    )
                    or task_id
                )

                qbit_id = (
                    task.get(
                        "qbit_id"
                    )
                    or qbit_id
                )

                track_id = (
                    task.get(
                        "track_id"
                    )
                    or track_id
                )

                pipeline_id = (
                    task.get(
                        "pipeline_id"
                    )
                    or pipeline_id
                )

            # ======================================================
            # 5. TRACK RELATIONSHIP
            #
            # TrackID belongs to the data path/relationship.
            #
            # If it already exists, preserve it.
            # If it does not, use the existing Dialer routing-ID
            # mechanism rather than inventing a new Qbit identity.
            # ======================================================

            if (
                track_id is None
                and qbit is not None
            ):

                track = self._extract_qbit_field(
                    qbit,
                    "track",
                    None,
                )

                if isinstance(
                    track,
                    dict,
                ):

                    track_id = (
                        track.get(
                            "track_id"
                        )
                        or track.get(
                            "id"
                        )
                    )

                elif track is not None:

                    track_id = (
                        getattr(
                            track,
                            "track_id",
                            None,
                        )
                        or getattr(
                            track,
                            "id",
                            None,
                        )
                    )

            if track_id is None and qbit is not None:

                track_id = self._generate_command_track_id(
                    qbit
                )

            # ======================================================
            # 6. WHO / WHAT / WHERE / WHY / HOW
            # ======================================================

            source = transport_data.get(
                "source"
            )

            if source is None and qbit is not None:

                source = self._extract_qbit_field(
                    qbit,
                    "source",
                    None,
                )

            if source is None:

                source = "QBIT"

            target = transport_data.get(
                "target",
                transport_data.get(
                    "destination"
                ),
            )

            channel = transport_data.get(
                "channel"
            )

            if channel is None:

                channel = transport_data.get(
                    "channel_id"
                )

            if channel is None and qbit is not None:

                channel = self._extract_qbit_field(
                    qbit,
                    "channel",
                    None,
                )

            intent = transport_data.get(
                "intent"
            )

            if intent is None:

                intent = transport_data.get(
                    "reason"
                )

            if intent is None:

                intent = transport_data.get(
                    "purpose"
                )

            # ======================================================
            # 7. EXISTING LINEAGE / RELATIONSHIPS
            # ======================================================

            relationships = transport_data.get(
                "relationships"
            )

            if relationships is None and isinstance(
                task,
                dict,
            ):

                relationships = task.get(
                    "relationships"
                )

            if relationships is None and qbit is not None:

                relationships = self._extract_qbit_field(
                    qbit,
                    "relationships",
                    None,
                )

            if not isinstance(
                relationships,
                dict,
            ):

                relationships = {}

            data_lineage = transport_data.get(
                "data_lineage"
            )

            if data_lineage is None and isinstance(
                task,
                dict,
            ):

                data_lineage = task.get(
                    "data_lineage"
                )

            if data_lineage is None and qbit is not None:

                data_lineage = self._extract_qbit_field(
                    qbit,
                    "data_lineage",
                    None,
                )

            if not isinstance(
                data_lineage,
                dict,
            ):

                data_lineage = {}

            # ======================================================
            # 8. PAYLOAD / DATA
            # ======================================================

            payload = transport_data.get(
                "payload"
            )

            if payload is None:

                payload = transport_data.get(
                    "data"
                )

            # If the transport item is an actual Qbit, its payload
            # remains inside the Qbit rather than being converted
            # into a command.

            if payload is None and qbit is not None:

                payload = self._extract_qbit_field(
                    qbit,
                    "payload",
                    None,
                )

            # ======================================================
            # 9. CAPABILITY / COMMAND METADATA
            #
            # Catalog and registry are descriptive/control state.
            #
            # They do not execute anything here.
            # ======================================================

            command_name = (
                transport_data.get(
                    "command"
                )
                or transport_data.get(
                    "name"
                )
                or transport_data.get(
                    "action"
                )
            )

            if isinstance(
                command_name,
                str,
            ):

                command_name = command_name.strip().upper()

            capability = {}

            catalog = getattr(
                self,
                "command_catalog",
                None,
            )

            registry = getattr(
                self,
                "command_registry",
                None,
            )

            if (
                command_name
                and isinstance(
                    catalog,
                    dict,
                )
            ):

                capability = catalog.get(
                    command_name,
                    {},
                )

                if not isinstance(
                    capability,
                    dict,
                ):

                    capability = {}

            handler = None

            if (
                command_name
                and isinstance(
                    registry,
                    dict,
                )
            ):

                handler = registry.get(
                    command_name
                )

            # ======================================================
            # 10. COMPLETE TRANSPORT IDENTITY
            # ======================================================

            transport_data.update({

                "data_type": "QBIT_DATA",

                "data_role": "BLOOD_CELL",

                "qbit": qbit,

                "qbit_id": qbit_id,

                "task_id": task_id,

                "track_id": track_id,

                "pipeline_id": pipeline_id,

                "parent_id": parent_id,

                "source": source,

                "target": target,

                "channel": channel,

                "intent": intent,

                "who": transport_data.get(
                    "who",
                    source,
                ),

                "what": transport_data.get(
                    "what",
                    payload,
                ),

                "where": transport_data.get(
                    "where",
                    {
                        "source": source,
                        "target": target,
                        "channel": channel,
                        "track_id": track_id,
                    },
                ),

                "why": transport_data.get(
                    "why",
                    intent,
                ),

                "how": transport_data.get(
                    "how",
                    "QBIT_DATA_TRANSPORT",
                ),

                "task": task,

                "relationships": relationships,

                "data_lineage": data_lineage,

            })

            # ======================================================
            # 11. COGNITIVE ROUTING METADATA
            #
            # Multiple Qbits can share task/pipeline context while
            # retaining independent Qbit and Track identities.
            # ======================================================

            transport_data[
                "cognitive_link"
            ] = {

                "qbit_id": qbit_id,

                "track_id": track_id,

                "task_id": task_id,

                "pipeline_id": pipeline_id,

                "parent_id": parent_id,

                "authority": "QbitDialer",

                "input_type": "QBIT_DATA",

                "next_processor": "ComputeBrain",

                "command_authority": "QbitDialer",

            }

            # ======================================================
            # 12. CAPABILITY LINK
            # ======================================================

            transport_data[
                "capability"
            ] = {

                "command": command_name,

                "known": bool(
                    capability
                ),

                "executable": callable(
                    handler
                ),

                "cataloged": bool(
                    command_name
                    and isinstance(
                        catalog,
                        dict,
                    )
                    and command_name in catalog
                ),

                "dynamic": bool(
                    capability.get(
                        "dynamic",
                        False,
                    )
                )
                if isinstance(
                    capability,
                    dict,
                )
                else False,

                "generated": bool(
                    capability.get(
                        "generated",
                        False,
                    )
                )
                if isinstance(
                    capability,
                    dict,
                )
                else False,

            }

            # ======================================================
            # 13. TRANSPORT CONTROL
            #
            # Explicitly identify this as DATA transport.
            # ======================================================

            transport_data[
                "transport"
            ] = {

                "processor": "QbitDialer",

                "authority": "QbitDialer",

                "destination": "KERNEL_BUS",

                "purpose": "QBIT_DATA_TRANSPORT",

                "execution": False,

                "command_execution": False,

                "cognitive_processing": True,

                "raw_qbit": bool(
                    qbit is not None
                ),

            }

            # ======================================================
            # 14. WRITE EXISTING QBIT ROUTING METADATA
            #
            # Preserve the SAME Qbit instance.
            # No Qbit recreation.
            # ======================================================

            if qbit is not None:

                for field_name, value in (
                    (
                        "track_id",
                        track_id,
                    ),
                    (
                        "task_id",
                        task_id,
                    ),
                    (
                        "pipeline_id",
                        pipeline_id,
                    ),
                    (
                        "parent_id",
                        parent_id,
                    ),
                    (
                        "relationships",
                        relationships,
                    ),
                    (
                        "data_lineage",
                        data_lineage,
                    ),
                ):

                    if value is None:

                        continue

                    try:

                        current = getattr(
                            qbit,
                            field_name,
                            None,
                        )

                        if current is None:

                            setattr(
                                qbit,
                                field_name,
                                value,
                            )

                    except Exception:

                        pass

            # ======================================================
            # 15. ENCODE
            #
            # The encoder receives the complete data envelope.
            #
            # It must not receive str(qbit) as a command.
            # ======================================================

            binary_packet = self._encode(
                transport_data
            )

            # ======================================================
            # 16. SEND
            #
            # This is DATA transport only.
            # ======================================================

            result = self.send(
                binary_packet
            )

            # ======================================================
            # 17. OBSERVABILITY
            # ======================================================

            try:

                self.logger.debug(
                    "[QbitDialer] Qbit DATA transported | "
                    "qbit_id=%s | task_id=%s | track_id=%s | "
                    "pipeline_id=%s | source=%s | "
                    "destination=%s | command=%s",
                    qbit_id,
                    task_id,
                    track_id,
                    pipeline_id,
                    source,
                    target,
                    command_name,
                )

            except Exception:

                pass

            return result

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            try:

                self.logger.exception(
                    "[QbitDialer] process_and_send failed | "
                    "error=%s: %s",
                    type(exc).__name__,
                    exc,
                )

            except Exception:

                pass

            return False

    # ================================================================
    # SEED AI OS â€” GLOBAL SEND COMMAND
    #
    # SEND = GLOBAL SEED AI INTERNAL COMMAND
    #
    # Every module may request transmission through:
    #
    #     dialer.send(...)
    #
    # SEND itself is a COMMAND.
    #
    # It therefore MUST enter the authoritative command plane:
    #
    #     send()
    #       â†“
    #     SEND command envelope
    #       â†“
    #     submit_command()
    #       â†“
    #     command_registry["SEND"]
    #       â†“
    #     command_queue
    #       â†“
    #     _process_command_plane()
    #       â†“
    #     _execute_qbit_command()
    #       â†“
    #     _cmd_send()
    #       â†“
    #     _transport_send()
    #
    # IMPORTANT:
    #
    #     Qbit = DATA
    #     SEND = CONTROL COMMAND
    #
    # SEND does NOT itself execute transport.
    #
    # The SEND handler owns the eventual transport operation.
    #
    # This gives every SEED subsystem one standard way to transmit:
    #
    #     Kernel
    #     Core
    #     Qbit
    #     ComputeBrain
    #     TransformerBrain
    #     TrackSystem
    #     EventBus
    #     FATHUD
    #     CLI
    #     internal services
    #
    # ================================================================

    def send(
        self,
        data,
        *,
        source=None,
        destination=None,
        channel=None,
        qbit=None,
        qbit_id=None,
        track_id=None,
        task_id=None,
        pipeline_id=None,
        parent_id=None,
        priority=5,
        confidence=1.0,
        args=None,
        kwargs=None,
        metadata=None,
    ):

        # ============================================================
        # 1. LIFECYCLE GUARD
        # ============================================================

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] SEND rejected | "
                "shutdown in progress"
            )

            return {
                "status": "rejected",
                "command": "SEND",
                "reason": "shutdown_in_progress",
            }

        # ============================================================
        # 2. RESOLVE EXISTING QBIT CONTEXT
        #
        # Never manufacture Qbit identity.
        # ============================================================

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        if qbit is not None:

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "qbit_id",
                    None,
                )

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            if track_id is None:

                track_id = self._extract_qbit_field(
                    qbit,
                    "track_id",
                    None,
                )

            if task_id is None:

                task_id = self._extract_qbit_field(
                    qbit,
                    "task_id",
                    None,
                )

            if pipeline_id is None:

                pipeline_id = self._extract_qbit_field(
                    qbit,
                    "pipeline_id",
                    None,
                )

            if parent_id is None:

                parent_id = self._extract_qbit_field(
                    qbit,
                    "parent_id",
                    None,
                )

            if source is None:

                source = self._extract_qbit_field(
                    qbit,
                    "source",
                    None,
                )

            if channel is None:

                channel = self._extract_qbit_field(
                    qbit,
                    "channel",
                    None,
                )

        # ============================================================
        # 3. DEFAULT INTERNAL SOURCE
        # ============================================================

        if source is None:

            source = "SEED_AI_INTERNAL"

        # ============================================================
        # 4. NORMALIZE OPTIONAL ARGUMENTS
        # ============================================================

        if args is None:

            args = []

        elif not isinstance(
            args,
            (list, tuple),
        ):

            args = [
                args
            ]

        else:

            args = list(
                args
            )

        if kwargs is None:

            kwargs = {}

        elif not isinstance(
            kwargs,
            dict,
        ):

            kwargs = {}

        else:

            kwargs = dict(
                kwargs
            )

        if metadata is None:

            metadata = {}

        elif not isinstance(
            metadata,
            dict,
        ):

            metadata = {
                "value": metadata,
            }

        else:

            metadata = dict(
                metadata
            )

        # ============================================================
        # 5. BUILD GLOBAL SEND COMMAND
        #
        # SEND is a real command.
        #
        # It goes through the SAME command authority as every other
        # SEED command.
        # ============================================================

        payload = {

            "data": data,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "parent_id": parent_id,

            "source": source,

            "destination": destination,

            "channel": channel,

            "metadata": metadata,

            "transport_requested": True,

            "command": "SEND",

        }

        command_envelope = {

            "name": "SEND",

            "command": "SEND",

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "parent_id": parent_id,

            "source": source,

            "destination": destination,

            "channel": channel,

            "priority": priority,

            "confidence": confidence,

            "args": args,

            "kwargs": kwargs,

            "payload": payload,

            "metadata": metadata,

            "authority": "QbitDialer",

            "command_source": source,

            "cognitive_source": (
                "SEED_AI_INTERNAL"
            ),

        }

        # ============================================================
        # 6. CAPABILITY LINK
        #
        # SEND must be visible in both the catalog and executable
        # registry.
        #
        # Registration itself remains owned by the command
        # capability system.
        # ============================================================

        command_catalog = getattr(
            self,
            "command_catalog",
            None,
        )

        command_registry = getattr(
            self,
            "command_registry",
            None,
        )

        if isinstance(
            command_catalog,
            dict,
        ):

            capability = command_catalog.get(
                "SEND"
            )

            if not isinstance(
                capability,
                dict,
            ):

                capability = {}

            capability.update({

                "name": "SEND",

                "source": "SEED_AI_INTERNAL",

                "authority": "QbitDialer",

                "system": "QbitDialer",

                "method": "_cmd_send",

                "global": True,

                "dynamic": True,

                "state": (
                    "EXECUTABLE"
                    if (
                        isinstance(
                            command_registry,
                            dict,
                        )
                        and callable(
                            command_registry.get(
                                "SEND"
                            )
                        )
                    )
                    else capability.get(
                        "state",
                        "PENDING",
                    )
                ),

            })

            command_catalog[
                "SEND"
            ] = capability

        # ============================================================
        # 7. ONE AUTHORITATIVE COMMAND PATH
        #
        # Do NOT write to kernel_bus here.
        # Do NOT invoke a handler here.
        # Do NOT create another queue.
        # ============================================================

        try:

            result = self.submit_command(
                command_envelope
            )

            return result

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] SEND command admission failed | "
                "qbit_id=%s | track_id=%s | error=%s: %s",
                qbit_id,
                track_id,
                type(exc).__name__,
                exc,
            )

            return {
                "status": "failed",
                "command": "SEND",
                "reason": "send_command_admission_error",
                "qbit_id": qbit_id,
                "track_id": track_id,
                "task_id": task_id,
                "pipeline_id": pipeline_id,
                "error": str(exc),
                "error_type": type(
                    exc
                ).__name__,
            }


    # ================================================================
    # SEED COGNITIVE INPUT COMMAND
    #
    # ASK_SEED is a data-ingress command. It creates a NEW task Qbit
    # and sends that Qbit through ComputeBrain -> TransformerBrain.
    # It never executes the model output and never bypasses submit_command.
    # ================================================================

    async def _cmd_ask_seed(self, payload, *args, **kwargs):
        if not isinstance(payload, dict):
            payload = {"user_input": payload}

        user_input = (
            payload.get("user_input")
            or payload.get("text")
            or payload.get("message")
            or payload.get("data")
        )
        if user_input is None:
            return {
                "status": "failed",
                "reason": "ASK_SEED requires user_input",
            }

        task = self.create_task(
            {
                "user_input": str(user_input),
                "text": str(user_input),
                "source": payload.get("source", "FATHUD"),
                "what": str(user_input),
                "why": "cognitive_request",
                "where": payload.get("where", "SEED_COGNITION"),
                "how": "ComputeBrain",
                "metadata": {
                    "input_type": "USER_COGNITIVE_INPUT",
                    "oracle_branch": True,
                },
            },
            command_list=[],
            task_name="SEED_AI_COGNITIVE_INPUT",
            source_qbit=getattr(self, "qbit", None),
        )

        return {
            "status": "cognitive_task_created",
            "task_id": task.get("task_id") if isinstance(task, dict) else None,
            "qbit_id": task.get("qbit_id") if isinstance(task, dict) else None,
            "result": task,
        }


    # ================================================================
    # SEND COMMAND HANDLER
    #
    # This is the EXECUTABLE implementation registered as:
    #
    #     command_registry["SEND"]
    #
    # It is reached ONLY by the normal QbitDialer command executor.
    #
    # ================================================================

    async def _cmd_send(
        self,
        payload,
        *args,
        **kwargs,
    ):

        if not isinstance(
            payload,
            dict,
        ):

            payload = {
                "data": payload,
            }

        data = payload.get(
            "data"
        )

        destination = payload.get(
            "destination"
        )

        channel = payload.get(
            "channel"
        )

        qbit_id = payload.get(
            "qbit_id"
        )

        track_id = payload.get(
            "track_id"
        )

        task_id = payload.get(
            "task_id"
        )

        pipeline_id = payload.get(
            "pipeline_id"
        )

        self.logger.info(
            "[QbitDialer] SEND EXECUTE | "
            "qbit_id=%s | track_id=%s | task_id=%s | "
            "pipeline_id=%s | destination=%s | channel=%s",
            qbit_id,
            track_id,
            task_id,
            pipeline_id,
            destination,
            channel,
        )

        # ============================================================
        # ACTUAL TRANSPORT
        #
        # The handler executes transport through the private
        # transport mechanism.
        #
        # This is the ONLY place SEND actually writes the bus.
        # ============================================================

        return await self._transport_send(
            data,
            destination=destination,
            channel=channel,
            qbit_id=qbit_id,
            track_id=track_id,
            task_id=task_id,
            pipeline_id=pipeline_id,
        )


    # ================================================================
    # PRIVATE TRANSPORT
    #
    # LOW-LEVEL BUS OPERATION.
    #
    # This is NOT a command.
    #
    # It is called by the SEND command handler.
    # ================================================================

    async def _transport_send(
        self,
        data,
        *,
        destination=None,
        channel=None,
        qbit_id=None,
        track_id=None,
        task_id=None,
        pipeline_id=None,
    ):

        try:

            kernel_bus = getattr(
                self,
                "kernel_bus",
                None,
            )

            if kernel_bus is None:

                self.logger.warning(
                    "[QbitDialer] SEND transport unavailable | "
                    "kernel_bus=None | qbit_id=%s | "
                    "track_id=%s",
                    qbit_id,
                    track_id,
                )

                return {
                    "status": "failed",
                    "stage": "transport",
                    "command": "SEND",
                    "reason": "kernel_bus_unavailable",
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "task_id": task_id,
                    "pipeline_id": pipeline_id,
                }

            write = getattr(
                kernel_bus,
                "write",
                None,
            )

            if not callable(
                write
            ):

                return {
                    "status": "failed",
                    "stage": "transport",
                    "command": "SEND",
                    "reason": "kernel_bus_write_unavailable",
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                }

            result = write(
                data
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            return {

                "status": "sent",

                "command": "SEND",

                "qbit_id": qbit_id,

                "track_id": track_id,

                "task_id": task_id,

                "pipeline_id": pipeline_id,

                "destination": destination,

                "channel": channel,

                "result": result,

            }

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] SEND transport failed | "
                "qbit_id=%s | track_id=%s | "
                "error=%s: %s",
                qbit_id,
                track_id,
                type(exc).__name__,
                exc,
            )

            return {

                "status": "failed",

                "stage": "transport",

                "command": "SEND",

                "reason": "transport_error",

                "qbit_id": qbit_id,

                "track_id": track_id,

                "task_id": task_id,

                "pipeline_id": pipeline_id,

                "error": str(
                    exc
                ),

                "error_type": type(
                    exc
                ).__name__,

            }


    # ================================================================
    # QBIT TASK CREATION
    #
    # QBIT = DATA / BLOOD CELL
    #
    # A Qbit carries:
    #
    #     WHO   = origin / owner / actor
    #     WHAT  = data / command / intent
    #     WHERE = source / destination / channel / track
    #     WHY   = reason / intent / purpose
    #     HOW   = processing / routing / transformation
    #     RELATION = what this Qbit is connected to
    #
    # FLOW:
    #
    #     Source Qbit
    #       â†“
    #     Qbit Data Identity
    #       â†“
    #     Data Lineage / Relationship Map
    #       â†“
    #     NEW Task Qbit
    #       â†“
    #     Compute Brain
    #       â†“
    #     Intent / Processing
    #       â†“
    #     Command Plane
    #       â†“
    #     QbitDialer Authority
    #       â†“
    #     command_queue
    #       â†“
    #     _process_command_plane()
    #       â†“
    #     _execute_qbit_command()
    #
    # IMPORTANT:
    #
    # QbitDialer remains the command authority.
    #
    # The Compute Brain processes Qbit DATA.
    #
    # create_task() NEVER:
    #
    #     - directly executes a command
    #     - creates another command queue
    #     - creates another QbitQueueLoop
    #     - starts another runtime
    #     - manufactures command handlers
    #     - reuses the authoritative runtime Qbit as a task Qbit
    #     - overwrites self.qbit with a task Qbit
    #
    # Every task receives a NEW Qbit identity.
    #
    # ================================================================

    def create_task(
        self,
        payload,
        command_list=None,
        task_name="LOAD_SEED_AI_COMMAND_LIST",
        source_qbit=None,
    ):

        # ============================================================
        # 1. RESOLVE SOURCE / AUTHORITATIVE QBIT
        #
        # IMPORTANT:
        #
        # The Dialer's authoritative self.qbit is the SOURCE Qbit.
        #
        # It is NEVER converted into the task Qbit.
        #
        # The task receives a NEW Qbit object below.
        # ============================================================

        source_qbit = (
            source_qbit
            if source_qbit is not None
            else getattr(
                self,
                "qbit",
                None,
            )
        )

        # ------------------------------------------------------------
        # A payload may explicitly carry the producer/source Qbit.
        #
        # Prefer it when it is a real Qbit object.
        #
        # This allows IntentEngine -> QbitQueueLoop -> QbitDialer
        # lineage to remain attached to the Qbit that actually caused
        # this task to be created.
        # ------------------------------------------------------------

        if isinstance(
            payload,
            dict,
        ):

            for source_key in (
                "source_qbit",
                "parent_qbit",
                "authoritative_qbit",
            ):

                candidate_qbit = payload.get(
                    source_key
                )

                if candidate_qbit is not None:

                    if candidate_qbit is not source_qbit:

                        if hasattr(
                            candidate_qbit,
                            "id",
                        ):

                            source_qbit = candidate_qbit

                            break

        # ============================================================
        # 2. SOURCE QBIT DATA IDENTITY
        #
        # If no live source Qbit exists, create ONLY a source/data
        # object as the fallback.
        #
        # This fallback does NOT become the Dialer's task identity.
        # ============================================================

        if source_qbit is None:

            source_qbit = Qbit(
                payload=payload
            )

        source_qbit_id = getattr(
            source_qbit,
            "id",
            None,
        )

        source_track_id = getattr(
            source_qbit,
            "track_id",
            None,
        )

        # ============================================================
        # 3. CREATE A NEW TASK QBIT
        #
        # THIS IS THE FIX.
        #
        # Every create_task() invocation receives a NEW Qbit object.
        #
        # NEVER:
        #
        #     task_qbit = self.qbit
        #
        # NEVER:
        #
        #     task_qbit = self.qbit_instance
        #
        # NEVER:
        #
        #     self.qbit = task_qbit
        #
        # The authoritative runtime Qbit remains untouched.
        # ============================================================

        task_qbit = Qbit(
            payload=payload
        )

        task_qbit_id = getattr(
            task_qbit,
            "id",
            None,
        )

        # ------------------------------------------------------------
        # HARD IDENTITY GUARD
        #
        # A task Qbit MUST NOT share the source Qbit ID.
        # ------------------------------------------------------------

        if (
            task_qbit_id is None
            or (
                source_qbit_id is not None
                and task_qbit_id == source_qbit_id
            )
        ):

            task_qbit = Qbit(
                payload=payload
            )

            task_qbit_id = getattr(
                task_qbit,
                "id",
                None,
            )

        # ------------------------------------------------------------
        # Preserve producer/source track lineage.
        #
        # The task belongs to the source cognitive/data track.
        # ------------------------------------------------------------

        if source_track_id is not None:

            try:

                task_qbit.track_id = (
                    source_track_id
                )

            except Exception:

                pass

        # Preserve producer provenance and cognitive labels on the task Qbit.
        for field_name, field_value in (
            ("source", getattr(source_qbit, "source", None) or getattr(source_qbit, "origin", None)),
            ("source_of_start", getattr(source_qbit, "source_of_start", None)),
            ("classification", getattr(source_qbit, "classification", None) or getattr(source_qbit, "data_class", None)),
            ("intent", getattr(source_qbit, "intent", None)),
        ):
            if field_name == "source" and not field_value:
                field_value = "QBIT"
            if field_value is not None:
                try:
                    setattr(task_qbit, field_name, field_value)
                except Exception:
                    pass

        task_track_id = getattr(
            task_qbit,
            "track_id",
            None,
        )

        # ============================================================
        # 4. ESTABLISH TASK PARENT RELATIONSHIP
        #
        # The NEW task Qbit points back to the source Qbit.
        #
        # This creates:
        #
        #     source Qbit
        #          â†“
        #     task Qbit
        #
        # without recycling the source identity.
        # ============================================================

        parent_id = source_qbit_id

        if parent_id is None:

            if isinstance(
                payload,
                dict,
            ):

                parent_id = (
                    payload.get("parent_id")
                    or payload.get("qbit_id")
                    or payload.get("source_qbit_id")
                )

        try:

            task_qbit.parent_id = (
                parent_id
            )

        except Exception:

            pass

        try:

            task_qbit.source_qbit_id = (
                source_qbit_id
            )

        except Exception:

            pass

        try:

            task_qbit.parent_qbit_id = (
                parent_id
            )

        except Exception:

            pass

        # ============================================================
        # 5. ENSURE QBIT REGISTRY
        #
        # Register BOTH:
        #
        #     source Qbit
        #     NEW task Qbit
        #
        # Never replace one with the other.
        # ============================================================

        if not hasattr(
            self,
            "registry",
        ) or self.registry is None:

            self.registry = {}

        if source_qbit_id is not None:

            self.registry[
                source_qbit_id
            ] = source_qbit

        if task_qbit_id is not None:

            self.registry[
                task_qbit_id
            ] = task_qbit

        # ============================================================
        # 6. AUTHORITATIVE SEED COMMAND VOCABULARY
        # ============================================================
# 6. AUTHORITATIVE SEED COMMAND VOCABULARY
# ============================================================
# ============================================================
# 6. RESOLVE COMMANDS FROM THE RECEIVED QBIT
#
# create_task() MUST NOT manufacture an executable command
# list when the source Qbit does not contain one.
#
# The Qbit is the source of truth.
#
# IntentEngine currently produces:
#
#     INTENT=IDLE
#     action=COMPUTE_BRAIN
#
# That is cognitive routing metadata, NOT a command such as
# RUN / STOP / SEARCH / etc.
#
# Therefore:
#
#     no explicit command
#         ->
#     empty task command set
#
# The authoritative command catalog remains available to the
# command plane and is NOT copied into every task.
# ============================================================

        if command_list is None:

            command_list = []

        command_list = list(
            command_list
        )
# ============================================================
# 6A. RECOVER EXPLICIT COMMAND FROM PAYLOAD
# ============================================================

        if not command_list and isinstance(
            payload,
            dict,
        ):

            explicit_command = (
                payload.get("command")
                or payload.get("cmd")
            )

            if explicit_command is None:

                action_value = payload.get(
                    "action"
                )

                if( 
                    isinstance(
                        action_value,
                        str,
                    )
                    and action_value.strip().upper()
                    != "COMPUTE_BRAIN"
                ):

                    explicit_command = (
                        action_value
                    )

            if explicit_command is not None:

                command_list = [
                    explicit_command
                ]
        # ============================================================
        # 7. ENSURE COMMAND CATALOG
        # ============================================================

        if not hasattr(
            self,
            "command_catalog",
        ) or self.command_catalog is None:

            self.command_catalog = {}

        # ============================================================
        # 8. NORMALIZE COMMAND CONTRACT
        # ============================================================

        normalized_commands = []

        for command in command_list:

            command_name = None

            if isinstance(
                command,
                str,
            ):

                command_name = command.strip()

                if "=" in command_name:

                    command_name = (
                        command_name.split(
                            "=",
                            1,
                        )[0]
                    )

            elif isinstance(
                command,
                dict,
            ):

                command_name = (
                    command.get("name")
                    or command.get("command")
                    or command.get("cmd")
                    or command.get("action")
                )

                if command_name is not None:

                    command_name = str(
                        command_name
                    ).strip()

                    if "=" in command_name:

                        command_name = (
                            command_name.split(
                                "=",
                                1,
                            )[0]
                        )

            if not command_name:

                continue

            command_name = (
                str(
                    command_name
                )
                .strip()
                .upper()
            )

            if command_name:

                normalized_commands.append(
                    command_name
                )

        # ============================================================
        # 9. REMOVE DUPLICATES
        # ============================================================

        normalized_commands = list(
            dict.fromkeys(
                normalized_commands
            )
        )

        # ============================================================
        # AUTHORITATIVE COMMAND REGISTRATION
        #
        # create_task() supplies the SEED AI command vocabulary.
        #
        # Dynamic capability discovery supplies the actual handlers.
        #
        # This is ONE registration path.
        # ============================================================

        self._register_phase1_commands(
            command_list=normalized_commands
        )

        # ============================================================
        # 10. REGISTER COMMAND VOCABULARY
        # ============================================================

        with self.command_lock:

            for command_name in normalized_commands:

                existing = (
                    self.command_catalog.get(
                        command_name
                    )
                )

                if not isinstance(
                    existing,
                    dict,
                ):

                    existing = {}

                existing.setdefault(
                    "name",
                    command_name,
                )

                existing.setdefault(
                    "source",
                    "SEED_AI_COMMAND_VOCABULARY",
                )

                existing.setdefault(
                    "authority",
                    "QbitDialer",
                )

                existing.setdefault(
                    "state",
                    "CATALOGED",
                )

                self.command_catalog[
                    command_name
                ] = existing

        # ============================================================
        # 11. SNAPSHOT COMMAND STATE
        # ============================================================

        registered_commands = sorted(
            getattr(
                self,
                "command_registry",
                {},
            ).keys()
        )

        registered_set = set(
            registered_commands
        )

        cataloged_commands = sorted(
            self.command_catalog.keys()
        )

        catalog_set = set(
            cataloged_commands
        )

        resolved_commands = [
            command
            for command in normalized_commands
            if command in catalog_set
        ]

        executable_commands = [
            command
            for command in normalized_commands
            if command in registered_set
        ]

        pending_commands = [
            command
            for command in normalized_commands
            if (
                command in catalog_set
                and command not in registered_set
            )
        ]

        unknown_commands = [
            command
            for command in normalized_commands
            if command not in catalog_set
        ]

        # ============================================================
        # 12. TASK / DATA IDENTITY
        # ============================================================

        task_id = (
            f"QTASK-{uuid.uuid4()}"
        )

        created_at = time.time()

        # ------------------------------------------------------------
        # The task follows the source Qbit's track.
        # ------------------------------------------------------------

        track_id = (
            task_track_id
            or source_track_id
        )

        # ============================================================
        # 13. EXTRACT DATA CONTEXT
        #
        # This is the "WHO / WHAT / WHERE / WHY" layer.
        #
        # Read provenance from the received Qbit first, then allow
        # the payload to refine it. Never lose the producer context.
        # ============================================================

        source_qbit_source = self._extract_qbit_field(
            source_qbit,
            "source",
            None,
        )

        if source_qbit_source is None:
            source_qbit_source = self._extract_qbit_field(
                source_qbit,
                "source_of_start",
                None,
            )

        source_qbit_classification = self._extract_qbit_field(
            source_qbit,
            "classification",
            None,
        )

        source_qbit_intent = self._extract_qbit_field(
            source_qbit,
            "intent",
            None,
        )

        if isinstance(
            payload,
            dict,
        ):

            data_source = payload.get(
                "source",
                payload.get(
                    "origin",
                    source_qbit_source or "QBIT",
                ),
            )

            data_target = payload.get(
                "target",
                payload.get(
                    "destination",
                    None,
                ),
            )

            data_channel = payload.get(
                "channel",
                None,
            )

            data_intent = payload.get(
                "intent",
                payload.get(
                    "reason",
                    payload.get(
                        "purpose",
                        source_qbit_intent,
                    ),
                ),
            )

            data_classification = payload.get(
                "classification",
                payload.get(
                    "data_classification",
                    payload.get(
                        "class",
                        source_qbit_classification,
                    ),
                ),
            )

            data_context = payload.get(
                "context",
                None,
            )

        else:

            data_source = "QBIT"

            data_target = None

            data_channel = None

            data_intent = source_qbit_intent

            data_classification = source_qbit_classification

            data_context = None

        # ------------------------------------------------------------
        # IntentEngine is the intent authority.
        # Never send an intent-less task into the cognitive path.
        # ------------------------------------------------------------

        if not data_intent:
            intent_engine = getattr(
                self,
                "intent_engine",
                None,
            )
            extractor = getattr(
                intent_engine,
                "_extract_intent_name",
                None,
            ) if intent_engine is not None else None
            if callable(extractor):
                try:
                    data_intent = extractor(source_qbit)
                except Exception:
                    data_intent = None
            if not data_intent and intent_engine is not None:
                scorer = getattr(
                    intent_engine,
                    "score_intents",
                    None,
                )
                if callable(scorer):
                    try:
                        scored = scorer()
                        if isinstance(scored, tuple) and scored:
                            data_intent = scored[0]
                        elif isinstance(scored, str):
                            data_intent = scored
                    except Exception:
                        data_intent = None

        if not data_intent:
            data_intent = "IDLE"

        # Classification is part of the compute envelope.
        if not data_classification:
            data_classification = data_intent

        # ============================================================
        # 14. DATA RELATIONSHIP IDENTITY
        #
        # A Qbit is not isolated data.
        #
        # Preserve its relationship to:
        #
        #     Source Qbit
        #     Task Qbit
        #     Task
        #     Track
        #     Channel
        #     Source
        #     Target
        #     Intent
        #     Command
        #     Compute Brain
        #     QbitDialer
        # ============================================================

        relationships = {

            "qbit_id": task_qbit_id,

            "source_qbit_id": source_qbit_id,

            "parent_id": parent_id,

            "task_id": task_id,

            "track_id": track_id,

            "source": data_source,

            "target": data_target,

            "channel": data_channel,

            "intent": data_intent,

            "command": (
                normalized_commands
            ),

            "processor": "COMPUTE_BRAIN",

            "command_authority": "QbitDialer",

        }

        # ============================================================
        # 15. DATA MOVEMENT / LINEAGE
        #
        # Record WHERE the Qbit came from, WHERE it is going,
        # and HOW it moves through the system.
        # ============================================================

        data_lineage = {

            "created_by": "QBIT",

            "created_at": created_at,

            "current_owner": "QbitDialer",

            "current_processor": "COMPUTE_BRAIN",

            "source": data_source,

            "destination": data_target,

            "channel": data_channel,

            "track_id": track_id,

            "qbit_id": task_qbit_id,

            "source_qbit_id": source_qbit_id,

            "parent_id": parent_id,

            "task_id": task_id,

            "movement_path": [

                "QBIT",

                "QBIT_DIALER",

                "COMPUTE_BRAIN",

                "INTENT_PROCESSING",

                "COMMAND_PLANE",

                "QBIT_DIALER",

                "COMMAND_QUEUE",

                "COMMAND_EXECUTION",

            ],

            "state": "CREATED",

        }

        # ============================================================
        # 16. COMPUTE BRAIN CONTRACT
        #
        # Qbit = blood cell / information carrier.
        #
        # Compute Brain = processing organ.
        #
        # QbitDialer = command authority / circulatory controller.
        # ============================================================

        compute_contract = {

            "processor": "COMPUTE_BRAIN",

            "input_type": "QBIT_DATA",

            "data_role": "BLOOD_CELL",

            "processing_required": True,

            "intent_required": True,

            "relationship_resolution_required": True,

            "lineage_tracking_required": True,

            "who_required": True,

            "what_required": True,

            "where_required": True,

            "why_required": True,

            "how_required": True,

            "command_authority": "QbitDialer",

            "execution_allowed": False,

            "execution_stage": "COMMAND_PLANE",

        }

        # ============================================================
        # 17. DETERMINE TASK STATE
        # ============================================================

        if executable_commands:

            task_state = "PARTIAL"

        else:

            task_state = "PROPOSED"

        # ============================================================
        # 18. BUILD QBIT-OWNED TASK
        # ============================================================

        task = {

            # --------------------------------------------------------
            # IDENTITY
            # --------------------------------------------------------

            "task_id": task_id,

            "qbit_id": task_qbit_id,

            "source_qbit_id": source_qbit_id,

            "parent_id": parent_id,

            "track_id": track_id,

            "task_name": task_name,

            # --------------------------------------------------------
            # PROVENANCE
            # --------------------------------------------------------

            "source": data_source,

            "source_of_start": data_source,

            "classification": data_classification,

            "intent": data_intent,

            "authority": "QbitDialer",

            "origin": "QBIT_GENERATED",

            "controller": "SEED_COGNITIVE_LAYER",

            # --------------------------------------------------------
            # DATA
            # --------------------------------------------------------

            "payload": payload,

            "data_type": "QBIT_DATA",

            "data_role": "BLOOD_CELL",

            # --------------------------------------------------------
            # WHO / WHAT / WHERE / WHY
            # --------------------------------------------------------

            "who": data_source,

            "what": {

                "payload": payload,

                "commands": normalized_commands,

            },

            "where": {

                "source": data_source,

                "target": data_target,

                "channel": data_channel,

                "track_id": track_id,

            },

            "why": data_intent,

            # --------------------------------------------------------
            # RELATIONSHIP MAP
            # --------------------------------------------------------

            "relationships": relationships,

            # --------------------------------------------------------
            # DATA LINEAGE
            # --------------------------------------------------------

            "data_lineage": data_lineage,

            # --------------------------------------------------------
            # COMPUTE BRAIN
            # --------------------------------------------------------

            "compute": compute_contract,

            # --------------------------------------------------------
            # COMMAND CONTRACT
            # --------------------------------------------------------

            "commands": normalized_commands,

            "resolved_commands": resolved_commands,

            "executable_commands": executable_commands,

            "pending_commands": pending_commands,

            "unknown_commands": unknown_commands,

            "registered_commands": registered_commands,

            "cataloged_commands": cataloged_commands,

            # --------------------------------------------------------
            # COUNTS
            # --------------------------------------------------------

            "command_count": len(
                normalized_commands
            ),

            "resolved_count": len(
                resolved_commands
            ),

            "executable_count": len(
                executable_commands
            ),

            "pending_count": len(
                pending_commands
            ),

            "unknown_count": len(
                unknown_commands
            ),

            # --------------------------------------------------------
            # LIFECYCLE
            # --------------------------------------------------------

            "state": task_state,

            "created_at": created_at,

            # --------------------------------------------------------
            # COGNITIVE ROUTING
            # --------------------------------------------------------

            "cognitive_source": {

                "qbit_id": source_qbit_id,

                "task_qbit_id": task_qbit_id,

                "parent_id": parent_id,

                "track_id": track_id,

                "source": "QBIT",

                "processor": "COMPUTE_BRAIN",

                "authority": "QbitDialer",

            },

            # --------------------------------------------------------
            # EXECUTION CONTRACT
            # --------------------------------------------------------

            "requires_intent_evaluation": True,

            "requires_relationship_resolution": True,

            "requires_data_lineage": True,

            "requires_action_authorization": True,

            "execution_authority": "QbitDialer",

            "execution_path": (
                "COMPUTE_BRAIN"
                " -> INTENT_PROCESSING"
                " -> COMMAND_PLANE"
                " -> submit_command"
                " -> command_queue"
                " -> _process_command_plane"
                " -> _execute_qbit_command"
            ),

            "user_task_manager": False,

            # --------------------------------------------------------
            # SAFETY
            # --------------------------------------------------------

            "execution_started": False,

            "execution_completed": False,

        }

        # ============================================================
        # 19. ATTACH TASK TO NEW TASK QBIT
        #
        # CRITICAL:
        #
        # The task is attached to task_qbit.
        #
        # NEVER attach it to self.qbit/source_qbit.
        # ============================================================

        task_qbit.task = task

        try:

            task_qbit.task_id = task_id

        except Exception:

            pass

        try:

            task_qbit.track_id = track_id

        except Exception:

            pass

        try:

            task_qbit.data_lineage = (
                data_lineage
            )

        except Exception:

            pass

        try:

            task_qbit.relationships = (
                relationships
            )

        except Exception:

            pass

        try:

            task_qbit.compute_contract = (
                compute_contract
            )

        except Exception:

            pass

        try:

            task_qbit.source = data_source

        except Exception:

            pass

        try:

            task_qbit.target = data_target

        except Exception:

            pass

        try:

            task_qbit.channel = data_channel

        except Exception:

            pass

        try:

            task_qbit.intent = data_intent

        except Exception:

            pass

        try:

            task_qbit.parent_id = parent_id

        except Exception:

            pass

        try:

            task_qbit.source_qbit_id = (
                source_qbit_id
            )

        except Exception:

            pass

        # ------------------------------------------------------------
        # NEVER:
        #
        #     self.qbit = task_qbit
        #
        # The authoritative Dialer Qbit remains untouched.
        # ------------------------------------------------------------

        self._last_qbit_task = task

        self._last_task_qbit = (
            task_qbit
        )

        # ============================================================
        # 20. LEGACY USER TASK COMPATIBILITY
        # ============================================================

        if getattr(
            self,
            "user_input_task",
            None,
        ) is not None:

            try:

                self.user_input_task = task

            except Exception as exc:

                try:

                    self.logger.debug(
                        "[QbitDialer] user_input_task compatibility "
                        "update failed: %s",
                        exc,
                    )

                except Exception:

                    pass

        # ============================================================
        # 21. QBIT DATA QUEUE
        #
        # DATA ONLY.
        #
        # This is NOT the command queue.
        #
        # IMPORTANT:
        #
        # Queue the NEW task Qbit.
        #
        # Do NOT re-admit the authoritative source Qbit.
        # ============================================================

        qbit_queue = getattr(
            self,
            "_qbit_queue",
            None,
        )

        if qbit_queue is not None:

            try:

                qbit_queue.put(
                    task_qbit
                )

            except Exception as exc:

                try:

                    self.logger.error(
                        "[QbitDialer] Qbit data queue insertion "
                        "failed: %s",
                        exc,
                    )

                except Exception:

                    pass

        # ============================================================
        # 22. SEND NEW TASK QBIT THROUGH COMPUTE BRAIN
        #
        # IMPORTANT:
        #
        # This is DATA PROCESSING.
        #
        # It is NOT command execution.
        #
        # The Compute Brain determines:
        #
        #     what this data means
        #     what it relates to
        #     where it should go
        #     why it exists
        #     what action, if any, should eventually be requested
        #
        # QbitDialer retains final command authority.
        # ============================================================

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if compute_brain is None:

            compute_brain = getattr(
                self,
                "cognitive_kernel",
                None,
            )

        if compute_brain is not None:

            process_qbit = getattr(
                compute_brain,
                "process_qbit",
                None,
            )

            if callable(
                process_qbit
            ):

                try:

                    compute_result = process_qbit(
                        task_qbit
                    )

                    if inspect.isawaitable(
                        compute_result
                    ):

                        # Do not create a second processing loop.
                        #
                        # If create_task() is called from an active
                        # asyncio runtime, the existing runtime owns
                        # the coroutine.

                        try:

                            loop = (
                                asyncio.get_running_loop()
                            )

                            loop.create_task(
                                compute_result,
                                name=(
                                    "QbitDialer-ComputeBrain"
                                ),
                            )

                        except RuntimeError:

                            pass

                    else:

                        try:

                            task[
                                "compute_result"
                            ] = compute_result

                        except Exception:

                            pass

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Compute Brain "
                        "Qbit processing failed"
                    )

        else:

            self.logger.warning(
                "[QbitDialer] Compute Brain unavailable | "
                "Qbit retained as unprocessed data | qbit_id=%s",
                task_qbit_id,
            )

        # ============================================================
        # 23. OBSERVABILITY
        # ============================================================

        try:

            self.logger.info(
                "[QbitDialer] QBIT TASK CREATED | "
                "task_id=%s | "
                "qbit_id=%s | "
                "parent_id=%s | "
                "source_qbit_id=%s | "
                "track_id=%s | "
                "source=%s | "
                "target=%s | "
                "channel=%s | "
                "why=%s | "
                "state=%s | "
                "commands=%d | "
                "executable=%d | "
                "pending=%d | "
                "unknown=%d",
                task_id,
                task_qbit_id,
                parent_id,
                source_qbit_id,
                track_id,
                data_source,
                data_target,
                data_channel,
                data_intent,
                task_state,
                len(
                    normalized_commands
                ),
                len(
                    executable_commands
                ),
                len(
                    pending_commands
                ),
                len(
                    unknown_commands
                ),
            )

            if pending_commands:

                self.logger.info(
                    "[QbitDialer] QBIT TASK COMMANDS PENDING "
                    "EXECUTABLE HANDLERS | "
                    "task=%s | pending=%s",
                    task_id,
                    pending_commands,
                )

            if unknown_commands:

                self.logger.warning(
                    "[QbitDialer] QBIT TASK CONTAINS "
                    "UNKNOWN COMMAND VOCABULARY | "
                    "task=%s | unknown=%s",
                    task_id,
                    unknown_commands,
                )

        except Exception:

            pass

        # ============================================================
        # 24. RETURN NEW TASK QBIT
        #
        # The returned object is the task/data Qbit.
        #
        # self.qbit remains the authoritative runtime Qbit.
        # ============================================================

        return task_qbit

# ================================================================
# SEED AI OS â€” QBIT DIALER / ORACLE ATTACHMENT GATE
# ================================================================
# FILE:
#   C:\SEED_ROOT\seed\core\dialers\qbit_dialer.py
#
# VERSION:
#   25.0-T BOOT-ORDER SAFETY HOTFIX
#
# PHASE:
#   BOOT / CORE ATTACHMENT
#
# PURPOSE:
#   Prevent QbitDialer from attempting to attach Oracle to a
#   nonexistent SEEDCore instance.
#
# AUTHORITY:
#   QbitDialer boot layer
#
# BOOT CONTRACT:
#   QbitDialer MAY initialize before SEEDCore.
#   Oracle attachment MUST wait until a valid SEEDCore exists.
#
# IMPORTANT:
#   This does NOT create a fake SEEDCore.
#   This does NOT restore TaskManager.
#   This does NOT suppress the dependency.
#
#   It simply defers Oracle attachment until SEEDCore is real.

#    Attach Oracle only when a valid SEEDCore exists.

#    Returns:
#        Oracle instance when attached.
#        None when SEEDCore is not yet available.

#    This method is intentionally safe to call during early boot.
# ================================================================

    def _ensure_oracle(self):


    # ------------------------------------------------------------
    # SEEDCORE BOOT GATE
    # ------------------------------------------------------------
        seedcore = getattr(self, "seedcore", None)

        if seedcore is None:
            try:
                self.logger.info(
                    "[QbitDialer] SEEDCore not ready; "
                    "Oracle attachment deferred"
                )
            except Exception:
                print(
                    "[QbitDialer] SEEDCore not ready; "
                    "Oracle attachment deferred"
                )

            return None

    # ------------------------------------------------------------
    # ORACLE ALREADY ATTACHED
    # ------------------------------------------------------------
        if getattr(self, "oracle", None) is not None:
            return self.oracle

    # ------------------------------------------------------------
    # ATTACH ORACLE TO VALID SEEDCORE
    # ------------------------------------------------------------
        try:
            self.oracle = attach_oracle(seedcore)

            try:
                self.logger.info(
                    "[QbitDialer] Oracle attached to SEEDCore"
                )
            except Exception:
                print(
                    "[QbitDialer] Oracle attached to SEEDCore"
                )

            return self.oracle

        except Exception as e:
        # --------------------------------------------------------
        # DO NOT TURN DEFERRED BOOT INTO FATAL BOOT FAILURE
        # --------------------------------------------------------
            try:
                self.logger.warning(
                    "[QbitDialer] Oracle attachment deferred: %s",
                    e,
                )
            except Exception:
                print(
                    f"[QbitDialer] Oracle attachment deferred: {e}"
                )

            return None


    def attach_seedcore(self, seedcore):
        if seedcore is None:
            raise ValueError("attach_seedcore() received None")
        self.seedcore = seedcore

        self.logger.info(
            "[QbitDialer] SEEDCore attached: %r",
            seedcore
        )

        if self.oracle is None:
            self._ensure_oracle()

        return self.seedcore
# ===============================================================
# ================================================================
# MESSAGE / SELF-DIRECTED CONTROL
#
# Internal SEED / Qbit message intake.
#
# Flow:
#
#     Message
#        â†“
#     QbitDialer
#        â†“
#     Command Plane
#        â†“
#     Qbit
#        â†“
#     Intent / Processing
#        â†“
#     Command Execution
#        â†“
#     FATHUD / EventBus subscribers
#
# QbitDialer owns command authority.
# FATHUD is an observer / developer interface.
# FATHUD does NOT become a command-loop owner.
# ================================================================

    def handle_message(
        self,
        msg,
    ):

        if not isinstance(
            msg,
            dict,
        ):
            self.logger.warning(
                "[QbitDialer] Ignored invalid message | type=%s",
                type(msg).__name__,
            )
            return False

        msg_type = msg.get(
            "type"
        )

        # ------------------------------------------------------------
        # COMMAND-PLANE MESSAGE
        #
        # Give explicit command messages priority.
        # ------------------------------------------------------------

        if msg_type in (
            "QBIT_COMMAND",
            "COMMAND",
            "EXECUTE_COMMAND",
            "QBIT_REQUEST",
        ):

            return self._handle_command_plane_message(
                msg
            )

        # ------------------------------------------------------------
        # QBIT OUTBOX PROPOSAL
        # ------------------------------------------------------------

        if msg_type == QBIT_OUTBOX_PROPOSAL:

            return self._decide_outbox_proposal(
                msg
            )

        # ------------------------------------------------------------
        # SELF BOOT REQUEST
        # ------------------------------------------------------------

        if msg_type in (
            "REQUEST_SELF_BOOT",
            "SELF_BOOT",
        ):

            return self._decide_self_boot(
                msg
            )

        # ------------------------------------------------------------
        # FATHUD / DEVELOPER MESSAGE
        #
        # FATHUD messages enter the same command plane.
        # They do not receive a private execution path.
        # ------------------------------------------------------------

        if msg_type in (
            "FATHUD_COMMAND",
            "FATHUD_REQUEST",
            "DEVHUD_COMMAND",
        ):

            msg = dict(
                msg
            )

            msg.setdefault(
                "source",
                "FATHUD",
            )

            return self._handle_command_plane_message(
                msg
            )

        # ------------------------------------------------------------
        # UNKNOWN MESSAGE
        # ------------------------------------------------------------

        self.logger.debug(
            "[QbitDialer] Message ignored | type=%s",
            msg_type,
        )

        return False


    # ================================================================
    # COMMAND PLANE MESSAGE
    #
    # ONE AUTHORITATIVE COMMAND PATH.
    #
    # FATHUD, internal SEED messages, Qbit requests, and external
    # command sources all converge here.
    # ================================================================

    def _handle_command_plane_message(
        self,
        msg,
    ):

        content = msg.get(
            "content",
            msg.get(
                "command",
                msg.get(
                    "request",
                    None,
                ),
            ),
        )

        if content is None:

            self.logger.warning(
                "[QbitDialer] Command-plane message missing "
                "command/content"
            )

            return False

        source = msg.get(
            "source",
            "INTERNAL",
        )

        authority = msg.get(
            "authority",
            "QbitDialer",
        )

        # ------------------------------------------------------------
        # Build command envelope.
        # ------------------------------------------------------------

        command = {
            "type": "QBIT_COMMAND",
            "command": content,
            "source": source,
            "authority": authority,
            "request_id": msg.get(
                "request_id"
            ),
            "timestamp": msg.get(
                "timestamp",
                time.time(),
            ),
        }

        # Preserve additional request information.
        for key in (
            "intent",
            "priority",
            "track",
            "channel",
            "target",
            "payload",
            "context",
        ):

            if key in msg:

                command[key] = msg[key]

        # ------------------------------------------------------------
        # Publish command-plane observation.
        # ------------------------------------------------------------

        self._publish_command_plane_event(
            "COMMAND_RECEIVED",
            command,
        )

        # ------------------------------------------------------------
        # QBIT IS THE COMMAND COMMUNICATION OBJECT.
        #
        # Never create a replacement Qbit.
        # ------------------------------------------------------------

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        if qbit is None:

            self.logger.error(
                "[QbitDialer] Command rejected | "
                "authoritative Qbit unavailable"
            )

            self._publish_command_plane_event(
                "COMMAND_REJECTED",
                {
                    **command,
                    "reason": "QBIT_UNAVAILABLE",
                },
            )

            return False

        # ------------------------------------------------------------
        # Attach command to the authoritative Qbit.
        # ------------------------------------------------------------

        try:

            payload = getattr(
                qbit,
                "payload",
                None,
            )

            if not isinstance(
                payload,
                dict,
            ):

                payload = {}

                try:
                    qbit.payload = payload
                except Exception:
                    pass

            payload.update(
                command
            )

            try:
                qbit.command = content
            except Exception:
                pass

            try:
                qbit.request = command
            except Exception:
                pass

            try:
                qbit.source = source
            except Exception:
                pass

        except Exception:

            self.logger.exception(
                "[QbitDialer] Failed to attach command to Qbit"
            )

            return False

        # ------------------------------------------------------------
        # Publish Qbit to EventBus / FATHUD subscribers.
        # ------------------------------------------------------------

        self._publish_qbit(
            qbit,
            event="QBIT_COMMAND",
        )

        # ------------------------------------------------------------
        # AUTHORITATIVE COMMAND EXECUTION.
        #
        # Do not call a second command executor.
        # ------------------------------------------------------------

        try:

            result = self.execute_command(
                command
            )

            if inspect.isawaitable(
                result
            ):

                return result

            return result

        except Exception:

            self.logger.exception(
                "[QbitDialer] Command-plane execution failed"
            )

            self._publish_command_plane_event(
                "COMMAND_ERROR",
                {
                    **command,
                    "state": "ERROR",
                },
            )

            return False


    # ================================================================
    # COMMAND-PLANE EVENT PUBLICATION
    #
    # EventBus is authoritative event transport.
    # FATHUD observes through its registered interface.
    # ================================================================

    def _publish_command_plane_event(
        self,
        event,
        payload,
    ):

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is not None:

            emit = getattr(
                event_bus,
                "emit",
                None,
            )

            if callable(
                emit
            ):

                try:

                    emit(
                        event,
                        payload,
                    )

                except TypeError:

                    try:

                        emit(
                            {
                                "event": event,
                                "payload": payload,
                                "source": "QbitDialer",
                                "authority": "QbitDialer",
                                "timestamp": time.time(),
                            }
                        )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Command-plane EventBus "
                            "publication failed"
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Command-plane EventBus "
                        "publication failed"
                    )

        # ------------------------------------------------------------
        # FATHUD direct observer compatibility.
        #
        # No loop creation.
        # No thread creation.
        # No command execution here.
        # ------------------------------------------------------------

        fathud = getattr(
            self,
            "fathud",
            None,
        )

        if fathud is None:

            fathud = getattr(
                self,
                "FATHUD",
                None,
            )

        if fathud is None:
            return

        for method_name in (
            "receive_event",
            "publish",
            "emit",
            "update",
        ):

            method = getattr(
                fathud,
                method_name,
                None,
            )

            if not callable(
                method
            ):
                continue

            try:

                result = method(
                    event,
                    payload,
                )

                if inspect.isawaitable(
                    result
                ):

                    try:

                        loop = asyncio.get_running_loop()

                        loop.create_task(
                            result,
                            name="QbitDialer-FATHUD-Publish",
                        )

                    except RuntimeError:

                        pass

            except TypeError:

                try:

                    result = method(
                        {
                            "event": event,
                            "payload": payload,
                            "source": "QbitDialer",
                        }
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        try:

                            loop = asyncio.get_running_loop()

                            loop.create_task(
                                result,
                                name="QbitDialer-FATHUD-Publish",
                            )

                        except RuntimeError:

                            pass

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] FATHUD publication failed"
                    )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] FATHUD publication failed"
                )

            break


    # ================================================================
    # QBIT OUTBOX PROPOSAL
    # ================================================================

    def _decide_outbox_proposal(
        self,
        msg,
    ):

        content = msg.get(
            "content",
            "",
        )

        path = msg.get(
            "path",
            None,
        )

        proposal = {
            "type": QBIT_OUTBOX_PROPOSAL,
            "content": content,
            "path": path,
            "source": "QBIT_DIALER",
            "authority": "QbitDialer",
            "state": "PROPOSED",
            "timestamp": time.time(),
        }

        self._last_outbox_proposal = proposal

        self.logger.info(
            "[QbitDialer] Outbox proposal received | path=%s",
            path,
        )

        # ------------------------------------------------------------
        # Send proposal through the same Qbit command plane.
        # ------------------------------------------------------------

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Outbox proposal retained | "
                "authoritative Qbit unavailable"
            )

            return proposal

        try:

            payload = getattr(
                qbit,
                "payload",
                None,
            )

            if not isinstance(
                payload,
                dict,
            ):

                payload = {}

                try:
                    qbit.payload = payload
                except Exception:
                    pass

            payload.update(
                {
                    "type": "QBIT_OUTBOX_PROPOSAL",
                    "proposal": proposal,
                }
            )

            self._publish_qbit(
                qbit,
                event="QBIT_OUTBOX_PROPOSAL",
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] Failed to publish outbox proposal"
            )

        return proposal

# =================================================================
#    Evaluate a self-boot request through the existing ethics gate.
#
#    Self-boot remains an explicitly gated operation.
#   
#    Execute the already-authorized self-boot operation.
# ===========================================================
    # ==========================================================
    # SELF-BOOT EXECUTION
    #
    # Qbit is the control / reasoning channel.
    #
    # SEED does not blindly call self_boot().
    #
    # Flow:
    #
    #     SELF_BOOT_REQUEST
    #          â†“
    #     DISCOVER
    #          â†“
    #     ASSESS
    #          â†“
    #     PLAN
    #          â†“
    #     AUTHORIZE
    #          â†“
    #     EXECUTE
    #          â†“
    #     VERIFY
    #          â†“
    #     LEARN / REPORT
    #
    # Qbit controls the decision data.
    # Existing subsystem owners retain lifecycle ownership.
    # ==========================================================

    def _execute_self_boot(
        self,
        qbit=None,
        context=None,
    ):

        qbit = qbit or getattr(
            self,
            "qbit",
            None,
        )

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Self-boot rejected | "
                "authoritative Qbit unavailable"
            )

            return False

        context = (
            context
            if isinstance(context, dict)
            else {}
        )

        # ======================================================
        # 1. DISCOVERY
        # ======================================================

        registry = (
            self._collect_self_boot_registry()
        )

        # ======================================================
        # 2. SYSTEM FEEL / STATE
        #
        # "How it feels" is represented as observable system
        # state rather than pretending the machine has human
        # emotions.
        #
        # This gives Qbit a compact internal condition model.
        # ======================================================

        system_feel = (
            self._assess_system_condition(
                registry
            )
        )

        # ======================================================
        # 3. QBIT SELF-BOOT REQUEST
        # ======================================================

        request = {
            "type": "SELF_BOOT",
            "phase": "DISCOVER",

            "request": context.get(
                "content",
                "self boot",
            ),

            "registry": registry,

            "system_feel": system_feel,

            "options": {
                "inspect": True,
                "assess": True,
                "plan": True,
                "repair": True,
                "connect": True,
                "register": True,
                "initialize": True,
                "verify": True,
                "rollback": True,
                "learn": True,
                "report": True,
            },

            "authority": "QbitDialer",
            "source": "SEED",
            "timestamp": time.time(),
        }

        # ======================================================
        # 4. PUT DECISION DATA INTO THE AUTHORITATIVE QBIT
        # ======================================================

        try:

            payload = getattr(
                qbit,
                "payload",
                None,
            )

            if not isinstance(
                payload,
                dict,
            ):

                payload = {}

                try:
                    qbit.payload = payload
                except Exception:
                    pass

            payload.update(
                request
            )

            try:
                qbit.intent = "SELF_BOOT"
            except Exception:
                pass

            try:
                qbit.system_feel = system_feel
            except Exception:
                pass

            try:
                qbit.self_boot_options = (
                    request["options"]
                )
            except Exception:
                pass

        except Exception:

            self.logger.exception(
                "[QbitDialer] Failed to prepare "
                "self-boot Qbit"
            )

            return False

        # ======================================================
        # 5. PUBLISH THE QBIT
        # ======================================================

        self._publish_qbit(
            qbit,
            event="SELF_BOOT",
        )

        # ======================================================
        # 6. QBIT COGNITION / PLANNING
        #
        # Give ComputeBrain / TransformerBrain the opportunity
        # to determine what should happen.
        # ======================================================

        try:

            result = self._process_qbit(
                qbit
            )

            if inspect.isawaitable(
                result
            ):

                return result

            return result

        except Exception:

            self.logger.exception(
                "[QbitDialer] Self-boot Qbit processing failed"
            )

            return False


    # ==========================================================
    # SYSTEM CONDITION
    #
    # Observable "how SEED feels".
    #
    # No fake emotion.
    # This is a machine-state assessment used by Qbit.
    # ==========================================================

    def _assess_system_condition(
        self,
        registry=None,
    ):

        registry = (
            registry
            if isinstance(registry, dict)
            else {}
        )

        condition = {
            "state": "UNKNOWN",
            "confidence": 0.0,

            "health": {
                "status": "UNKNOWN",
            },

            "capability": {
                "modules": len(
                    registry.get(
                        "modules",
                        [],
                    )
                ),
                "commands": len(
                    registry.get(
                        "commands",
                        [],
                    )
                ),
                "adapters": len(
                    registry.get(
                        "adapters",
                        [],
                    )
                ),
                "connections": len(
                    registry.get(
                        "connections",
                        [],
                    )
                ),
                "skills": len(
                    registry.get(
                        "skills",
                        [],
                    )
                ),
                "repair": len(
                    registry.get(
                        "repair",
                        [],
                    )
                ),
            },

            "signals": [],
        }

        # ------------------------------------------------------
        # Health monitor
        # ------------------------------------------------------

        health = getattr(
            self,
            "health_monitor",
            None,
        )

        if health is not None:

            for method_name in (
                "get_status",
                "status",
                "snapshot",
            ):

                method = getattr(
                    health,
                    method_name,
                    None,
                )

                if callable(method):

                    try:

                        value = method()

                        if inspect.isawaitable(
                            value
                        ):

                            # This helper is synchronous.
                            # Async health collection belongs to
                            # the async cognitive path.
                            continue

                        condition["health"] = value

                        break

                    except Exception:

                        self.logger.debug(
                            "[QbitDialer] Health assessment "
                            "failed",
                            exc_info=True,
                        )

        # ------------------------------------------------------
        # Qbit runtime
        # ------------------------------------------------------

        if getattr(
            self,
            "_qbit_running",
            False,
        ):

            condition["signals"].append(
                "QBIT_ONLINE"
            )

        else:

            condition["signals"].append(
                "QBIT_OFFLINE"
            )

        # ------------------------------------------------------
        # Queue transport
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is not None:

            condition["signals"].append(
                "QBIT_QUEUE_CONNECTED"
            )

        else:

            condition["signals"].append(
                "QBIT_QUEUE_WAITING"
            )

        # ------------------------------------------------------
        # Registry knowledge
        # ------------------------------------------------------

        if condition["capability"]["modules"]:

            condition["signals"].append(
                "MODULE_KNOWLEDGE_AVAILABLE"
            )

        if condition["capability"]["commands"]:

            condition["signals"].append(
                "COMMAND_KNOWLEDGE_AVAILABLE"
            )

        if condition["capability"]["repair"]:

            condition["signals"].append(
                "REPAIR_CAPABILITY_AVAILABLE"
            )

        # ------------------------------------------------------
        # Overall machine condition
        # ------------------------------------------------------

        if (
            "QBIT_ONLINE"
            in condition["signals"]
            and
            "QBIT_QUEUE_CONNECTED"
            in condition["signals"]
        ):

            condition["state"] = "READY"
            condition["confidence"] = 1.0

        elif (
            "QBIT_ONLINE"
            in condition["signals"]
        ):

            condition["state"] = "DEGRADED"
            condition["confidence"] = 0.7

        else:

            condition["state"] = "WAITING"
            condition["confidence"] = 0.4

        return condition
# ================================================================
# REPRESENTATION
# ================================================================

    # ==========================================================
    # SELF-BOOT DECISION / REGISTRY SYNCHRONIZATION
    #
    # QbitDialer = command authority / cognitive coordinator.
    #
    # Self-boot flow:
    #
    #     incoming message
    #          â†“
    #     intent classification
    #          â†“
    #     ethics
    #          â†“
    #     registry discovery
    #          â†“
    #     module / command / adapter / connection snapshot
    #          â†“
    #     Qbit communication packet
    #          â†“
    #     Qbit processing / planning
    #          â†“
    #     authoritative command execution
    #
    # This does NOT create a second runtime.
    # This does NOT directly start arbitrary modules.
    # ==========================================================

    def _decide_self_boot(
        self,
        msg,
    ):

        content = (
            msg.get("content", "")
            if isinstance(msg, dict)
            else str(msg or "")
        )

        content = content.strip()

        if not content:
            self.log(
                "[QbitDialer] Self-boot ignored | empty message"
            )
            return False

        # ------------------------------------------------------
        # 1. CLASSIFY INTENT
        # ------------------------------------------------------

        intent = self.classify_intent(
            content
        )

        self.log(
            "[QbitDialer] Self-boot intent | %s",
            intent,
        )

        # ------------------------------------------------------
        # 2. ETHICS / SAFETY GATE
        # ------------------------------------------------------

        ethics = getattr(
            self,
            "ethics",
            None,
        )

        if ethics is not None:

            allow = getattr(
                ethics,
                "allow",
                None,
            )

            if callable(allow):

                try:

                    if not allow(
                        intent,
                        content,
                    ):

                        self.log(
                            "[QbitDialer] Self-boot denied by ethics | "
                            "intent=%s",
                            intent,
                        )

                        return False

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Ethics evaluation failed"
                    )

                    return False

        # ------------------------------------------------------
        # 3. BUILD LIVE SYSTEM KNOWLEDGE
        #
        # Do not maintain a second hard-coded list here.
        #
        # Discover what the running SEED installation actually
        # knows about.
        # ------------------------------------------------------

        registry_snapshot = (
            self._collect_self_boot_registry()
        )

        # ------------------------------------------------------
        # 4. PACKAGE REGISTRY KNOWLEDGE INTO QBIT
        #
        # Qbit becomes the communication object carrying the
        # discovered system information into the cognitive path.
        # ------------------------------------------------------

        qbit_payload = {
            "type": "SELF_BOOT_REQUEST",

            "intent": intent,

            "content": content,

            "registry": registry_snapshot,

            "source": "QbitDialer",

            "authority": "QbitDialer",

            "timestamp": time.time(),
        }

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        # ------------------------------------------------------
        # Prefer the authoritative Qbit's payload interface.
        # ------------------------------------------------------

        if qbit is not None:

            try:

                existing_payload = getattr(
                    qbit,
                    "payload",
                    None,
                )

                if isinstance(
                    existing_payload,
                    dict,
                ):

                    existing_payload.update(
                        qbit_payload
                    )

                else:

                    try:
                        qbit.payload = qbit_payload
                    except Exception:
                        pass

                # --------------------------------------------------
                # Attach structured cognitive context when supported.
                # --------------------------------------------------

                try:
                    qbit.self_boot_context = (
                        registry_snapshot
                    )
                except Exception:
                    pass

                try:
                    qbit.intent = intent
                except Exception:
                    pass

                try:
                    qbit.request = content
                except Exception:
                    pass

                # --------------------------------------------------
                # Communicate through the authoritative Qbit path.
                # --------------------------------------------------

                self._publish_qbit(
                    qbit,
                    event="SELF_BOOT_REQUEST",
                )

                # --------------------------------------------------
                # Let the existing Qbit cognitive path process it.
                # --------------------------------------------------

                result = self._process_qbit(
                    qbit
                )

                if inspect.isawaitable(
                    result
                ):

                    return result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Self-boot Qbit communication failed"
                )

                return False

        # ------------------------------------------------------
        # No authoritative Qbit.
        #
        # Do NOT create one here.
        # ------------------------------------------------------

        self.log(
            "[QbitDialer] Self-boot waiting | "
            "authoritative Qbit unavailable"
        )

        return False


    # ==========================================================
    # COLLECT SELF-BOOT REGISTRY
    #
    # Builds a live description of the capabilities already
    # connected to SEED.
    #
    # No registry replacement.
    # No duplicate registry.
    # No invented modules.
    # ==========================================================

    def _collect_self_boot_registry(
        self,
    ):

        snapshot = {
            "classes": [],
            "commands": [],
            "modules": [],
            "adapters": [],
            "connections": [],
            "skills": [],
            "nodes": [],
            "brains": [],
            "repair": [],
        }

        # ------------------------------------------------------
        # Registry candidates.
        #
        # Use whichever registries are already attached to the
        # QbitDialer / SEED runtime.
        # ------------------------------------------------------

        registries = (
            "registry",
            "sregistry",
            "module_registry",
            "module_registry_manager",
            "command_registry",
            "channel_manager",
            "device_manager",
            "connection_registry",
            "adapter_registry",
            "node_registry",
            "skill_registry",
        )

        seen_objects = set()

        for name in registries:

            registry = getattr(
                self,
                name,
                None,
            )

            if registry is None:
                continue

            identity = id(registry)

            if identity in seen_objects:
                continue

            seen_objects.add(
                identity
            )

            self._extract_registry_information(
                registry,
                snapshot,
                source=name,
            )

        # ------------------------------------------------------
        # Known attached system components.
        #
        # These are references, not lifecycle ownership.
        # ------------------------------------------------------

        components = (
            "qbit",
            "qbit_queue_loop",
            "event_bus",
            "compute_brain",
            "transformer_brain",
            "oracle",
            "seed_core",
            "heartbeat",
            "heartbeat_emitter",
            "intent_engine",
            "agent_manager",
            "action_engine",
            "device_manager",
            "health_monitor",
            "cognition_map",
            "adaptive_priority_engine",
            "memory_weighting_system",
            "cognitive_governor",
            "qbit_watchdog",
            "seed_relay",
            "analytics_engine",
            "adaptive_engine",
            "constraint_guardian",
            "ethics",
            "memory_manager",
            "qbit_action_controller",
            "time_travel_engine",
            "sys_os",
            "channel_manager",
            "ipc_bridge",
            "hud_reader",
        )

        for name in components:

            obj = getattr(
                self,
                name,
                None,
            )

            if obj is None:
                continue

            snapshot["modules"].append(
                self._describe_component(
                    name,
                    obj,
                )
            )

            cls_name = type(
                obj
            ).__name__

            if cls_name not in snapshot["classes"]:

                snapshot["classes"].append(
                    cls_name
                )

        # ------------------------------------------------------
        # Attached brains.
        # ------------------------------------------------------

        for name in (
            "compute_brain",
            "transformer_brain",
            "system_calc",
        ):

            brain = getattr(
                self,
                name,
                None,
            )

            if brain is None:
                continue

            snapshot["brains"].append(
                self._describe_component(
                    name,
                    brain,
                )
            )

        # ------------------------------------------------------
        # Normalize / deduplicate.
        # ------------------------------------------------------

        for key in snapshot:

            if isinstance(
                snapshot[key],
                list,
            ):

                snapshot[key] = self._dedupe_registry_items(
                    snapshot[key]
                )

        return snapshot


    # ==========================================================
    # REGISTRY EXTRACTION
    # ==========================================================

    def _extract_registry_information(
        self,
        registry,
        snapshot,
        source="registry",
    ):

        # ------------------------------------------------------
        # Commands
        # ------------------------------------------------------

        command_registry = getattr(
            registry,
            "command_registry",
            None,
        )

        if isinstance(
            command_registry,
            dict,
        ):

            snapshot["commands"].extend(
                str(key)
                for key in command_registry.keys()
            )

        # ------------------------------------------------------
        # Modules
        # ------------------------------------------------------

        module_registry = getattr(
            registry,
            "modules",
            None,
        )

        if isinstance(
            module_registry,
            dict,
        ):

            for name, obj in module_registry.items():

                snapshot["modules"].append(
                    self._describe_component(
                        str(name),
                        obj,
                    )
                )

                if obj is not None:

                    snapshot["classes"].append(
                        type(obj).__name__
                    )

        # ------------------------------------------------------
        # Adapters
        # ------------------------------------------------------

        adapters = getattr(
            registry,
            "adapters",
            None,
        )

        if isinstance(
            adapters,
            dict,
        ):

            for name, obj in adapters.items():

                snapshot["adapters"].append(
                    self._describe_component(
                        str(name),
                        obj,
                    )
                )

        elif isinstance(
            adapters,
            (list, tuple, set),
        ):

            for obj in adapters:

                snapshot["adapters"].append(
                    self._describe_component(
                        type(obj).__name__,
                        obj,
                    )
                )

        # ------------------------------------------------------
        # Connections
        # ------------------------------------------------------

        connections = getattr(
            registry,
            "connections",
            None,
        )

        if isinstance(
            connections,
            dict,
        ):

            for name, obj in connections.items():

                snapshot["connections"].append(
                    self._describe_component(
                        str(name),
                        obj,
                    )
                )

        # ------------------------------------------------------
        # Nodes
        # ------------------------------------------------------

        nodes = getattr(
            registry,
            "nodes",
            None,
        )

        if isinstance(
            nodes,
            dict,
        ):

            for name, obj in nodes.items():

                snapshot["nodes"].append(
                    self._describe_component(
                        str(name),
                        obj,
                    )
                )

        # ------------------------------------------------------
        # Skills
        # ------------------------------------------------------

        skills = getattr(
            registry,
            "skills",
            None,
        )

        if isinstance(
            skills,
            dict,
        ):

            snapshot["skills"].extend(
                str(key)
                for key in skills.keys()
            )

        elif isinstance(
            skills,
            (list, tuple, set),
        ):

            snapshot["skills"].extend(
                str(skill)
                for skill in skills
            )

        # ------------------------------------------------------
        # Repair / autofix capabilities
        # ------------------------------------------------------

        for attr in (
            "repair_tools",
            "autofix",
            "autofix_tools",
            "repair_skills",
        ):

            value = getattr(
                registry,
                attr,
                None,
            )

            if isinstance(
                value,
                dict,
            ):

                snapshot["repair"].extend(
                    str(key)
                    for key in value.keys()
                )

            elif isinstance(
                value,
                (list, tuple, set),
            ):

                snapshot["repair"].extend(
                    str(item)
                    for item in value
                )


    # ==========================================================
    # COMPONENT DESCRIPTION
    # ==========================================================

    def _describe_component(
        self,
        name,
        obj,
    ):

        if obj is None:

            return {
                "name": str(name),
                "class": None,
                "available": False,
            }

        return {
            "name": str(name),
            "class": type(obj).__name__,
            "module": getattr(
                type(obj),
                "__module__",
                None,
            ),
            "available": True,
        }


    # ==========================================================
    # QBIT PUBLICATION
    #
    # Publish outgoing Qbit information to subscribers without
    # creating another processing loop.
    # ==========================================================

    def _publish_qbit(
        self,
        qbit,
        event="QBIT",
    ):

        payload = getattr(
            qbit,
            "payload",
            None,
        )

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is not None:

            emit = getattr(
                event_bus,
                "emit",
                None,
            )

            if callable(emit):

                try:

                    emit(
                        event,
                        payload,
                    )

                except TypeError:

                    try:

                        emit(
                            {
                                "event": event,
                                "payload": payload,
                                "qbit": qbit,
                                "source": "QbitDialer",
                            }
                        )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Qbit publication failed"
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Qbit publication failed"
                    )

        # ------------------------------------------------------
        # Subscriber compatibility.
        # ------------------------------------------------------

        subscribers = getattr(
            self,
            "qbit_subscribers",
            None,
        )

        if not subscribers:
            return

        for subscriber in list(
            subscribers
        ):

            try:

                callback = getattr(
                    subscriber,
                    "receive_qbit",
                    None,
                )

                if not callable(callback):
                    callback = subscriber

                if not callable(callback):
                    continue

                result = callback(
                    qbit
                )

                # Do not await here. The publication path must
                # remain compatible with synchronous subscribers.
                #
                # Async subscribers can be scheduled by their
                # owning runtime.

                if inspect.isawaitable(
                    result
                ):

                    try:

                        loop = asyncio.get_running_loop()

                        loop.create_task(
                            result
                        )

                    except RuntimeError:

                        pass

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit subscriber failed"
                )


    # ==========================================================
    # SMALL REGISTRY DEDUPLICATION HELPER
    # ==========================================================

    def _dedupe_registry_items(
        self,
        items,
    ):

        output = []
        seen = set()

        for item in items:

            try:

                key = repr(
                    item
                )

            except Exception:

                key = str(
                    id(item)
                )

            if key in seen:
                continue

            seen.add(
                key
            )

            output.append(
                item
            )

        return output
    # ==========================================================
    # INTENT CLASSIFIER
    #
    # This method CLASSIFIES.
    #
    # It does NOT execute commands.
    # It does NOT create modules.
    # It does NOT start runtimes.
    #
    # Classification gives the cognitive/command pipeline enough
    # information to decide what should happen next.
    #
    # Intent families:
    #
    #   OBSERVATION
    #   QBIT
    #   COMMAND
    #   COGNITION
    #   PLANNING
    #   MODULE
    #   ADAPTER
    #   NODE
    #   CLASS
    #   CHANNEL
    #   MEMORY
    #   SYSTEM
    #   DEVICE
    #   NETWORK
    #   REPAIR
    #   SEED
    #   HUD
    #   ORACLE
    #   BACKUP
    #   SHUTDOWN
    # ==========================================================

    def classify_intent(
        self,
        text,
    ) -> str:

        if text is None:

            return "IGNORE"

        # ------------------------------------------------------
        # Normalize
        # ------------------------------------------------------

        if not isinstance(
            text,
            str,
        ):

            text = str(text)

        t = " ".join(
            text.strip().lower().split()
        )

        if not t:

            return "IGNORE"

        # ======================================================
        # SYSTEM LIFECYCLE
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "shutdown system",
                "shut down system",
                "power down system",
                "stop seed",
                "stop system",
                "restart system",
                "reboot system",
                "start system",
                "boot system",
            )
        ):

            if "shutdown" in t or "shut down" in t:
                return "SYSTEM_SHUTDOWN"

            if "restart" in t or "reboot" in t:
                return "SYSTEM_RESTART"

            return "SYSTEM_START"

        # ======================================================
        # BACKUP / RECOVERY
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "full system backup",
                "bootable backup",
                "backup system",
                "backup seed",
                "backup seed root",
                "create backup",
                "restore backup",
                "restore system",
                "recover system",
                "system recovery",
            )
        ):

            if any(
                word in t
                for word in (
                    "restore",
                    "recover",
                    "recovery",
                )
            ):

                return "SYSTEM_RECOVERY"

            return "SYSTEM_BACKUP"

        # ======================================================
        # QBIT
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create qbit",
                "new qbit",
                "initialize qbit",
                "qbit state",
                "qbit status",
                "qbit command",
                "qbit request",
                "qbit response",
                "process qbit",
                "execute qbit",
                "route qbit",
                "send qbit",
                "receive qbit",
                "publish qbit",
                "emit qbit",
                "qbit channel",
                "qbit track",
                "qbit generation",
            )
        ):

            if "create" in t or "new qbit" in t:
                return "QBIT_CREATE"

            if "status" in t:
                return "QBIT_STATUS"

            if "response" in t:
                return "QBIT_RESPOND"

            if "request" in t:
                return "QBIT_REQUEST"

            if "command" in t or "execute" in t:
                return "QBIT_COMMAND"

            if "route" in t:
                return "QBIT_ROUTE"

            if "publish" in t or "emit" in t:
                return "QBIT_PUBLISH"

            return "QBIT_PROCESS"

        # ======================================================
        # COMMANDS
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "execute command",
                "run command",
                "issue command",
                "send command",
                "dispatch command",
                "load command",
                "register command",
                "command registry",
                "command list",
                "command capability",
                "command capabilities",
            )
        ):

            if "register" in t:
                return "COMMAND_REGISTER"

            if "load" in t:
                return "COMMAND_LOAD"

            if "capabilit" in t:
                return "COMMAND_CAPABILITY"

            return "COMMAND_EXECUTE"

        # ======================================================
        # MODULES
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create module",
                "new module",
                "build module",
                "scaffold module",
                "generate module",
                "write module",
                "modify module",
                "update module",
                "repair module",
                "remove module",
                "delete module",
                "load module",
                "unload module",
                "register module",
                "module registry",
                "module registry",
                "discover modules",
                "find modules",
                "inspect module",
                "module status",
            )
        ):

            if "register" in t:
                return "MODULE_REGISTER"

            if "discover" in t or "find" in t:
                return "MODULE_DISCOVER"

            if "inspect" in t or "status" in t:
                return "MODULE_INSPECT"

            if "repair" in t:
                return "MODULE_REPAIR"

            if "remove" in t or "delete" in t:
                return "MODULE_REMOVE"

            if "load" in t:
                return "MODULE_LOAD"

            if "unload" in t:
                return "MODULE_UNLOAD"

            if (
                "create" in t
                or "new module" in t
                or "build module" in t
                or "scaffold" in t
                or "generate" in t
            ):
                return "MODULE_CREATE"

            return "MODULE_UPDATE"

        # ======================================================
        # CLASSES / OBJECTS
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create class",
                "new class",
                "build class",
                "generate class",
                "modify class",
                "update class",
                "repair class",
                "inspect class",
                "find class",
                "register class",
                "class registry",
                "object model",
            )
        ):

            if "register" in t:
                return "CLASS_REGISTER"

            if "repair" in t:
                return "CLASS_REPAIR"

            if "inspect" in t or "find" in t:
                return "CLASS_INSPECT"

            if (
                "create" in t
                or "new class" in t
                or "build class" in t
                or "generate class" in t
            ):
                return "CLASS_CREATE"

            return "CLASS_UPDATE"

        # ======================================================
        # ADAPTERS / INTERFACES
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create adapter",
                "new adapter",
                "build adapter",
                "register adapter",
                "load adapter",
                "adapter registry",
                "adapter interface",
                "connect adapter",
                "bind adapter",
                "adapter connection",
                "repair adapter",
            )
        ):

            if "register" in t:
                return "ADAPTER_REGISTER"

            if "connect" in t or "bind" in t:
                return "ADAPTER_CONNECT"

            if "repair" in t:
                return "ADAPTER_REPAIR"

            if "load" in t:
                return "ADAPTER_LOAD"

            return "ADAPTER_CREATE"

        # ======================================================
        # NODES / SUBSYSTEMS
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create node",
                "register node",
                "node registry",
                "node status",
                "node health",
                "connect node",
                "disconnect node",
                "discover nodes",
                "subsystem",
                "register subsystem",
                "create subsystem",
            )
        ):

            if "register" in t:
                return "NODE_REGISTER"

            if "connect" in t:
                return "NODE_CONNECT"

            if "disconnect" in t:
                return "NODE_DISCONNECT"

            if "health" in t or "status" in t:
                return "NODE_STATUS"

            if "discover" in t:
                return "NODE_DISCOVER"

            return "NODE_CREATE"

        # ======================================================
        # CHANNELS / TRACKING
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "create channel",
                "register channel",
                "channel manager",
                "channel status",
                "channel routing",
                "route channel",
                "channel subscription",
                "subscribe channel",
                "unsubscribe channel",
                "track id",
                "track system",
                "track channel",
            )
        ):

            if "subscribe" in t:
                return "CHANNEL_SUBSCRIBE"

            if "unsubscribe" in t:
                return "CHANNEL_UNSUBSCRIBE"

            if "route" in t:
                return "CHANNEL_ROUTE"

            if "register" in t:
                return "CHANNEL_REGISTER"

            if "status" in t:
                return "CHANNEL_STATUS"

            if "track" in t:
                return "TRACK_MANAGE"

            return "CHANNEL_CREATE"

        # ======================================================
        # COGNITION / COMPUTE
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "think about",
                "think through",
                "analyze",
                "analyse",
                "calculate",
                "compute",
                "reason",
                "reason about",
                "evaluate",
                "evaluate input",
                "interpret",
                "classify",
                "understand",
                "cognitive",
                "cognition",
                "compute brain",
                "transformer brain",
                "thought packet",
            )
        ):

            if "calculate" in t or "compute" in t:
                return "COGNITION_COMPUTE"

            if "classify" in t:
                return "COGNITION_CLASSIFY"

            if "evaluate" in t:
                return "COGNITION_EVALUATE"

            return "COGNITION_ANALYZE"

        # ======================================================
        # PLANNING / DECISION
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "make a plan",
                "create a plan",
                "plan this",
                "planning",
                "plan next",
                "determine next",
                "decide what",
                "decision",
                "strategy",
                "sequence actions",
                "figure out what to do",
                "what should seed do",
                "what should qbit do",
            )
        ):

            return "PLAN"

        # ======================================================
        # MEMORY
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "remember",
                "store memory",
                "save memory",
                "retrieve memory",
                "recall memory",
                "search memory",
                "memory store",
                "memory manager",
                "memory weighting",
                "crystallize memory",
                "memory state",
            )
        ):

            if "retrieve" in t or "recall" in t or "search" in t:
                return "MEMORY_RETRIEVE"

            if "store" in t or "save" in t or "remember" in t:
                return "MEMORY_STORE"

            return "MEMORY_MANAGE"

        # ======================================================
        # REPAIR / SELF-HEALING
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "handle error",
                "fix error",
                "repair error",
                "repair system",
                "self repair",
                "self heal",
                "autofix",
                "auto fix",
                "repair module",
                "repair code",
                "fix code",
                "fix import",
                "fix attribute",
                "fix typo",
                "repair dependency",
                "invoke repair",
                "repair tools",
            )
        ):

            return "HANDLE_ERROR"

        # ======================================================
        # CUSTOM SEED CAPABILITIES
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "seed module",
                "custom seed module",
                "seed capability",
                "seed skill",
                "custom skill",
                "seed plugin",
                "seed extension",
                "seed adapter",
                "seed subsystem",
                "seed component",
                "seed architecture",
                "seed os",
                "seed ai",
            )
        ):

            if "skill" in t or "capability" in t:
                return "SEED_CAPABILITY"

            if "module" in t:
                return "SEED_MODULE"

            if "adapter" in t:
                return "SEED_ADAPTER"

            if "subsystem" in t:
                return "SEED_SUBSYSTEM"

            return "SEED_OPERATION"

        # ======================================================
        # DEVHUD / OBSERVABILITY
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "devhud",
                "developer hud",
                "hud status",
                "hud channel",
                "show system status",
                "show diagnostics",
                "diagnostics",
                "debug status",
                "runtime status",
                "system status",
                "health status",
            )
        ):

            return "SYSTEM_DIAGNOSTICS"

        # ======================================================
        # ORACLE
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "oracle",
                "ask oracle",
                "oracle request",
                "oracle response",
                "oracle memory",
                "oracle route",
            )
        ):

            return "ORACLE_REQUEST"

        # ======================================================
        # DEVICE / SENSOR / IO
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "device",
                "sensor",
                "camera",
                "microphone",
                "audio input",
                "audio output",
                "hardware",
                "fiveg",
                "modem",
                "ipc",
                "input device",
                "output device",
            )
        ):

            if "status" in t or "health" in t:
                return "DEVICE_STATUS"

            return "DEVICE_OPERATION"

        # ======================================================
        # NETWORK / COMMUNICATION
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "network",
                "connect to",
                "connection",
                "websocket",
                "mqtt",
                "relay",
                "communication",
                "publish",
                "subscribe",
                "message bus",
                "event bus",
                "ipc",
            )
        ):

            return "COMMUNICATION"

        # ======================================================
        # OBSERVATION
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "observe",
                "inspect",
                "measure",
                "monitor",
                "read state",
                "get state",
                "status",
                "what is happening",
                "check system",
            )
        ):

            return "OBSERVE"

        # ======================================================
        # EXPLORATION
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "explore",
                "exploration",
                "investigate",
                "discover",
                "look into",
                "search for",
                "find out",
                "learn about",
            )
        ):

            return "EXPLORE"

        # ======================================================
        # RESPONSE
        # ======================================================

        if any(
            phrase in t
            for phrase in (
                "respond",
                "reply",
                "answer",
                "send response",
                "return response",
            )
        ):

            return "RESPOND"

        # ======================================================
        # DEFAULT
        # ======================================================

        return "IGNORE"
# ======================================================

    def _execute_system_backup(self):
        SOURCE = "C:/SEED_ROOT"
        DEST   = "G:/SEED_ROOT"

        self.log("[QbitDialer] SYSTEM BACKUP AUTHORIZED")

        if not os.path.exists("G:/SEED_ROOT"):
            os.makedirs("G:/SEED_ROOT", exist_ok=True)

        shutil.copytree(
            SOURCE,
            DEST,
            dirs_exist_ok=True
        )
 
        self.log("[QbitDialer] Backup complete â†’ SEED_ROOT")

# ================================================================
    # existing handlers stay untouched

    # ==========================================================
    # QBIT ROUTER
    #
    # SINGLE INTENT DISPATCH POINT
    #
    # Qbit
    #   â†“
    # route()
    #   â”œâ”€â”€ HANDLE_ERROR â†’ handle_error()
    #   â”œâ”€â”€ EXPLORE      â†’ explore()
    #   â”œâ”€â”€ RESPOND      â†’ respond()
    #   â””â”€â”€ COMMAND      â†’ execute_command()
    #
    # route() does NOT:
    #   - create a runtime
    #   - create a queue
    #   - create another Qbit
    #   - bypass QbitDialer command authority
    #
    # Unknown intents are preserved and reported rather than
    # silently discarded.
    # ==========================================================

    def route(
        self,
        qbit,
        **kwargs,
    ):

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Route rejected | Qbit is None"
            )

            return False

        intent = getattr(
            qbit,
            "intent",
            None,
        )

        # ------------------------------------------------------
        # Normalize intent
        # ------------------------------------------------------

        if isinstance(
            intent,
            str,
        ):

            intent = intent.strip().upper()

        # ------------------------------------------------------
        # If the Qbit carries a request/command envelope, allow
        # the authoritative command path to handle it.
        # ------------------------------------------------------

        if intent in (
            "COMMAND",
            "EXECUTE",
            "REQUEST",
        ):

            try:

                result = self.execute_command(
                    qbit
                )

                self.last_route_result = result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Command route failed | "
                    "intent=%s",
                    intent,
                )

                return False

        # ------------------------------------------------------
        # ERROR
        # ------------------------------------------------------

        if intent == "HANDLE_ERROR":

            try:

                result = self.handle_error(
                    qbit,
                    **kwargs,
                )

                self.last_route_result = result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Error route failed"
                )

                return False

        # ------------------------------------------------------
        # EXPLORATION
        # ------------------------------------------------------

        if intent == "EXPLORE":

            try:

                result = self.explore(
                    qbit,
                    **kwargs,
                )

                self.last_route_result = result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Exploration route failed"
                )

                return False

        # ------------------------------------------------------
        # RESPONSE
        # ------------------------------------------------------

        if intent == "RESPOND":

            try:

                result = self.respond(
                    qbit,
                    **kwargs,
                )

                self.last_route_result = result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Response route failed"
                )

                return False

        # ------------------------------------------------------
        # NO EXPLICIT INTENT
        #
        # Do not throw away useful Qbits. Preserve them for the
        # cognitive path to classify/organize.
        # ------------------------------------------------------

        if intent is None:

            self.logger.debug(
                "[QbitDialer] Qbit has no explicit intent | "
                "routing to exploration"
            )

            try:

                result = self.explore(
                    qbit,
                    **kwargs,
                )

                self.last_route_result = result

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Default exploration route failed"
                )

                return False

        # ------------------------------------------------------
        # UNKNOWN INTENT
        # ------------------------------------------------------

        self.logger.warning(
            "[QbitDialer] Unknown Qbit intent | "
            "intent=%s | qbit=%s",
            intent,
            getattr(
                qbit,
                "id",
                "unidentified",
            ),
        )

        self.last_route_result = {
            "type": "UnroutedQbit",
            "intent": intent,
            "qbit": qbit,
            "qbit_id": getattr(
                qbit,
                "id",
                None,
            ),
            "source": "QbitDialer",
            "timestamp": time.time(),
        }

        return self.last_route_result

    # ==========================================================
    # QBIT ERROR / REPAIR DISPATCH
    #
    # Qbit
    #   â†“
    # error context
    #   â†“
    # AutoFixNamespace / repair helpers
    #   â†“
    # discovered repair skill
    #   â†“
    # repair result
    #
    # Helper modules remain dynamically discoverable.
    #
    # This method does NOT:
    #   - create a runtime
    #   - create a queue
    #   - create another Qbit
    #   - hard-code repair skills
    #   - directly execute arbitrary system commands
    #
    # QbitDialer remains the command authority.
    # ==========================================================

    def handle_error(
        self,
        qbit,
        error=None,
        **kwargs,
    ):

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Error handling rejected | "
                "Qbit is None"
            )

            return False

        qbit_id = getattr(
            qbit,
            "id",
            "unidentified",
        )

        self.logger.warning(
            "[QbitDialer] Handling Qbit error | "
            "qbit=%s | error=%s",
            qbit_id,
            error,
        )

        # ------------------------------------------------------
        # BUILD REPAIR CONTEXT
        #
        # Preserve the original Qbit and all available context.
        # ------------------------------------------------------

        repair_context = {
            "type": "QbitError",
            "qbit": qbit,
            "qbit_id": qbit_id,
            "track": getattr(
                qbit,
                "track",
                None,
            ),
            "error": error,
            "source": "QbitDialer",
            "timestamp": time.time(),
        }

        repair_context.update(
            kwargs
        )

        self.last_error = repair_context

        # ------------------------------------------------------
        # AUTHORITATIVE REPAIR NAMESPACE
        #
        # AutoFixNamespace is expected to discover helper skills
        # dynamically.
        # ------------------------------------------------------

        autofix = getattr(
            self,
            "autofix",
            None,
        )

        if autofix is None:

            autofix = getattr(
                self,
                "auto_fix",
                None,
            )

        if autofix is None:

            autofix = getattr(
                self,
                "autofix_namespace",
                None,
            )

        # ------------------------------------------------------
        # DISCOVERED HELPER DISPATCH
        # ------------------------------------------------------

        if autofix is not None:

            # Prefer an explicit repair method.
            repair_fn = None

            for method_name in (
                "repair",
                "handle_error",
                "invoke",
                "dispatch",
                "run",
            ):

                candidate = getattr(
                    autofix,
                    method_name,
                    None,
                )

                if callable(
                    candidate
                ):

                    repair_fn = candidate
                    break

            if repair_fn is not None:

                try:

                    result = repair_fn(
                        repair_context
                    )

                    self.last_repair_result = result

                    if inspect.isawaitable(
                        result
                    ):

                        return result

                    self.logger.info(
                        "[QbitDialer] Qbit repair dispatched | "
                        "qbit=%s | handler=%s",
                        qbit_id,
                        getattr(
                            repair_fn,
                            "__name__",
                            type(
                                repair_fn
                            ).__name__,
                        ),
                    )

                    return result

                except TypeError:

                    # Compatibility with helpers expecting the
                    # original Qbit rather than the context.
                    try:

                        result = repair_fn(
                            qbit
                        )

                        self.last_repair_result = result

                        if inspect.isawaitable(
                            result
                        ):

                            return result

                        return result

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] AutoFix repair "
                            "dispatch failed"
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] AutoFix repair "
                        "dispatch failed"
                    )

        # ------------------------------------------------------
        # QBIT-NATIVE REPAIR
        #
        # Preserve the existing Qbit repair capability as a
        # fallback when no AutoFix namespace handler is attached.
        # ------------------------------------------------------

        repair_tools = getattr(
            qbit,
            "invoke_repair_tools",
            None,
        )

        if callable(
            repair_tools
        ):

            try:

                result = repair_tools()

                self.last_repair_result = result

                if inspect.isawaitable(
                    result
                ):

                    return result

                self.logger.info(
                    "[QbitDialer] Qbit-native repair tools invoked | "
                    "qbit=%s",
                    qbit_id,
                )

                return result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit-native repair "
                    "tools failed"
                )

                return False

        # ------------------------------------------------------
        # NO REPAIR HANDLER
        # ------------------------------------------------------

        self.logger.warning(
            "[QbitDialer] No Qbit repair handler available | "
            "qbit=%s",
            qbit_id,
        )

        return False
    # ==========================================================
    # QBIT EXPLORATION / COGNITIVE PLANNING
    #
    # Qbit
    #   â†“
    # idle_read_loop / observation
    #   â†“
    # ComputeBrain
    #   â†“
    # exploration / organization
    #   â†“
    # plan()
    #   â†“
    # cognitive result / request / command
    #
    # IMPORTANT:
    #
    # explore() does NOT create another runtime.
    # explore() does NOT create another queue.
    # explore() does NOT directly execute arbitrary commands.
    #
    # It organizes information and asks the existing cognitive
    # path to determine what should happen next.
    # ==========================================================

    def explore(
        self,
        qbit,
        **kwargs,
    ):

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Exploration rejected | "
                "Qbit is None"
            )

            return False

        self.logger.debug(
            "[QbitDialer] Exploration started | "
            "qbit=%s",
            getattr(
                qbit,
                "id",
                "unidentified",
            ),
        )

        # ------------------------------------------------------
        # READ / OBSERVE
        #
        # Prefer information already carried by the Qbit.
        # idle_read_loop remains an input/observation mechanism;
        # it must not become a second execution loop here.
        # ------------------------------------------------------

        observation = None

        idle_read_loop = getattr(
            self,
            "idle_read_loop",
            None,
        )

        if callable(
            idle_read_loop
        ):

            try:

                observation = idle_read_loop(
                    qbit
                )

            except TypeError:

                # Compatibility with implementations whose
                # idle reader takes no positional argument.
                try:

                    observation = idle_read_loop()

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] idle_read_loop failed "
                        "during exploration"
                    )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] idle_read_loop failed "
                    "during exploration"
                )

        # ------------------------------------------------------
        # COMPUTE BRAIN
        #
        # ComputeBrain is the authoritative computational
        # interpretation layer.
        # ------------------------------------------------------

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if compute_brain is None:

            compute_brain = getattr(
                self,
                "system_calc",
                None,
            )

        computed = None

        if compute_brain is not None:

            try:

                # Prefer an explicit compute/analyze interface.
                compute_fn = None

                for method_name in (
                    "compute",
                    "analyze",
                    "process",
                    "evaluate",
                ):

                    candidate = getattr(
                        compute_brain,
                        method_name,
                        None,
                    )

                    if callable(candidate):

                        compute_fn = candidate
                        break

                if compute_fn is not None:

                    input_data = (
                        observation
                        if observation is not None
                        else qbit
                    )

                    computed = compute_fn(
                        input_data
                    )

                    if inspect.isawaitable(
                        computed
                    ):

                        # explore() is synchronous. Do not create
                        # a second runtime here.
                        self.logger.debug(
                            "[QbitDialer] ComputeBrain returned "
                            "awaitable; deferred to async path"
                        )

                        computed = None

            except Exception:

                self.logger.exception(
                    "[QbitDialer] ComputeBrain exploration "
                    "failed"
                )

        # ------------------------------------------------------
        # ORGANIZE COGNITIVE INFORMATION
        #
        # Preserve all useful information rather than throwing
        # away the original Qbit.
        # ------------------------------------------------------

        exploration = {
            "type": "QbitExploration",
            "qbit": qbit,
            "qbit_id": getattr(
                qbit,
                "id",
                None,
            ),
            "track": getattr(
                qbit,
                "track",
                None,
            ),
            "observation": observation,
            "computed": computed,
            "source": "QbitDialer",
            "timestamp": time.time(),
        }

        # ------------------------------------------------------
        # PLAN
        #
        # plan() remains the decision/planning layer.
        #
        # It may return:
        #     - a plan
        #     - a command
        #     - a request
        #     - a cognitive result
        #     - None
        # ------------------------------------------------------

        plan_fn = getattr(
            self,
            "plan",
            None,
        )

        plan_result = None

        if callable(
            plan_fn
        ):

            try:

                plan_result = plan_fn(
                    exploration
                )

            except TypeError:

                # Compatibility with plan(qbit)
                try:

                    plan_result = plan_fn(
                        qbit
                    )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Qbit planning failed"
                    )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit planning failed"
                )

        # ------------------------------------------------------
        # STORE COGNITIVE STATE
        #
        # This gives the Dialer a current organized view without
        # creating another processing mechanism.
        # ------------------------------------------------------

        self.last_exploration = exploration
        self.last_plan = plan_result

        # ------------------------------------------------------
        # OPTIONAL QBIT COGNITIVE HOOK
        #
        # Preserve the existing Qbit capability, but only use it
        # when no authoritative planning result already exists.
        # ------------------------------------------------------

        if (
            plan_result is None
            and hasattr(
                qbit,
                "spawn_cognitive_task",
            )
        ):

            try:

                cognitive_task = (
                    qbit.spawn_cognitive_task()
                )

                if inspect.isawaitable(
                    cognitive_task
                ):

                    self.logger.debug(
                        "[QbitDialer] Qbit cognitive task "
                        "deferred to async execution"
                    )

                else:

                    plan_result = cognitive_task
                    self.last_plan = plan_result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit cognitive task "
                    "creation failed"
                )

        # ------------------------------------------------------
        # RESULT
        # ------------------------------------------------------

        if plan_result is not None:

            self.logger.debug(
                "[QbitDialer] Exploration produced plan | "
                "qbit=%s | plan_type=%s",
                getattr(
                    qbit,
                    "id",
                    "unidentified",
                ),
                type(
                    plan_result
                ).__name__,
            )

            return plan_result

        if computed is not None:

            return computed

        if observation is not None:

            return observation

        return exploration

    # ==========================================================
    # QBIT RESPONSE / OUTBOUND PUBLICATION
    #
    # Qbit
    #   â†“
    # execute_response()
    #   â†“
    # emit / publish
    #   â†“
    # subscribers
    #
    # This is an OUTPUT path.
    #
    # It does NOT:
    #   - create a Qbit
    #   - create a queue
    #   - start a runtime
    #   - consume a queue
    #   - create another processing loop
    #
    # Commands / requests are carried by the Qbit and published
    # outward through the existing EventBus / subscriber path.
    # ==========================================================

    def respond(
        self,
        qbit,
        **kwargs,
    ):

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Cannot respond | "
                "Qbit is None"
            )

            return False

        # ------------------------------------------------------
        # AUTHORITATIVE QBIT RESPONSE
        # ------------------------------------------------------

        response = qbit

        execute_response = getattr(
            qbit,
            "execute_response",
            None,
        )

        if callable(
            execute_response
        ):

            try:

                result = execute_response()

                # Some Qbit implementations return a new
                # response object. Preserve it if supplied.
                if result is not None:

                    response = result

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit execute_response() failed"
                )

                return False

        # ------------------------------------------------------
        # OUTBOUND EMIT
        #
        # Use the Dialer's existing authoritative emit path.
        # ------------------------------------------------------

        emit = getattr(
            self,
            "emit",
            None,
        )

        if callable(
            emit
        ):

            try:

                result = emit(
                    "QBIT_RESPONSE",
                    response,
                )

                self.logger.debug(
                    "[QbitDialer] Qbit response emitted | "
                    "type=%s",
                    type(response).__name__,
                )

                return result

            except TypeError:

                # Compatibility with emit implementations
                # accepting one event object.
                try:

                    result = emit(
                        {
                            "event": "QBIT_RESPONSE",
                            "payload": response,
                            "source": "QbitDialer",
                            "authority": "QbitDialer",
                        }
                    )

                    return result

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Qbit response emission failed"
                    )

                    return False

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit response emission failed"
                )

                return False

        # ------------------------------------------------------
        # EVENTBUS COMPATIBILITY PATH
        #
        # If emit() is not available, use the already-bound
        # authoritative EventBus.
        # ------------------------------------------------------

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        event_emit = getattr(
            event_bus,
            "emit",
            None,
        )

        if callable(
            event_emit
        ):

            try:

                result = event_emit(
                    "QBIT_RESPONSE",
                    response,
                )

                self.logger.debug(
                    "[QbitDialer] Qbit response published | "
                    "subscribers=EventBus"
                )

                return result

            except TypeError:

                try:

                    return event_emit(
                        {
                            "event": "QBIT_RESPONSE",
                            "payload": response,
                            "source": "QbitDialer",
                            "authority": "QbitDialer",
                        }
                    )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Qbit response publication failed"
                    )

                    return False

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit response publication failed"
                )

                return False

        # ------------------------------------------------------
        # NO OUTBOUND TRANSPORT
        # ------------------------------------------------------

        self.logger.warning(
            "[QbitDialer] Qbit response not published | "
            "no emit/EventBus transport"
        )

        return False
    # ==========================================================
    # LEGACY QBIT LOOP â€” DISABLED
    #
    # QbitQueueLoop is the ONLY authoritative queue execution
    # loop.
    #
    # QbitDialer owns:
    #     - command authority
    #     - command normalization
    #     - command execution
    #     - Qbit processing
    #     - ComputeBrain
    #     - TransformerBrain
    #
    # QbitQueueLoop owns:
    #     - queue transport
    #     - queue consumption
    #     - execution scheduling
    #
    # IMPORTANT:
    #
    # This method intentionally DOES NOT:
    #
    #     - consume a queue
    #     - call queue.get()
    #     - call queue.receive()
    #     - create a task
    #     - create a thread
    #     - process Qbits
    #     - change runtime ownership
    #
    # It remains only as a compatibility guard for older callers.
    # ==========================================================

# =================================================================================
    # ==========================================================
    # START QBIT RUNTIME
    #
    # SINGLE AUTHORITATIVE QBIT RUNTIME BINDING
    #
    # IMPORTANT:
    #
    # QbitDialer does NOT own the QbitQueueLoop execution loop.
    #
    # QbitQueueLoop owns:
    #     - queue
    #     - queue transport
    #     - queue consumption
    #     - dispatch timing
    #
    # QbitDialer owns:
    #     - command authority
    #     - command normalization
    #     - command execution
    #     - Qbit cognition
    #     - ComputeBrain
    #     - TransformerBrain
    #
    # This method ONLY binds and activates the Dialer against
    # the already-existing authoritative Qbit + QbitQueueLoop.
    #
    # IT DOES NOT:
    #     - create a task
    #     - create a queue
    #     - consume a queue
    #     - start _loop()
    #     - start a thread
    #     - create another Qbit
    #
    # ==========================================================

    async def start_qbit_loop(
        self,
        initial_state=None,
    ):

        # ------------------------------------------------------
        # NEVER START AFTER SHUTDOWN
        # ------------------------------------------------------

        shutdown_flag = getattr(
            self,
            "shutdown_flag",
            None,
        )

        if (
            shutdown_flag is not None
            and shutdown_flag.is_set()
        ):

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "STOPPED"
            self._runtime_state = "STOPPED"

            self.logger.warning(
                "[QbitDialer] Qbit runtime activation rejected | "
                "shutdown requested"
            )

            return None

        # ------------------------------------------------------
        # REQUIRE ACTIVE ASYNC RUNTIME
        # ------------------------------------------------------

        try:

            asyncio.get_running_loop()

        except RuntimeError as exc:

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "WAITING"
            self._runtime_state = "WAITING"

            raise RuntimeError(
                "[QbitDialer] Qbit runtime activation requires "
                "a running asyncio event loop"
            ) from exc

        # ------------------------------------------------------
        # INITIAL STATE
        #
        # STATE ONLY.
        #
        # NEVER CREATE OR REPLACE QBIT.
        # ------------------------------------------------------

        if initial_state is not None:

            self.initial_state = initial_state

            try:

                normalized = normalize_qbit_input(
                    initial_state
                )

                if not isinstance(
                    normalized,
                    tuple,
                ):

                    normalized = tuple(
                        normalized
                    )

                if len(normalized) != 2:

                    raise ValueError(
                        "initial_state must have 2 elements"
                    )

                self.qbit_state = tuple(
                    complex(x)
                    for x in normalized
                )

            except Exception as exc:

                raise ValueError(
                    "[QbitDialer] Invalid initial_state"
                ) from exc

        # ------------------------------------------------------
        # AUTHORITATIVE QBIT
        #
        # Qbit MUST ALREADY EXIST.
        # ------------------------------------------------------

        authoritative_qbit = getattr(
            self,
            "qbit",
            None,
        )

        if authoritative_qbit is None:

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "WAITING"
            self._runtime_state = "WAITING"

            self.logger.warning(
                "[QbitDialer] Qbit runtime waiting | "
                "authoritative Qbit not bound"
            )

            return None

        # ------------------------------------------------------
        # QBIT IDENTITY
        # ------------------------------------------------------

        existing_qbit_instance = getattr(
            self,
            "qbit_instance",
            None,
        )

        if (
            existing_qbit_instance is not None
            and existing_qbit_instance is not authoritative_qbit
        ):

            raise RuntimeError(
                "[QbitDialer] FATAL: Qbit identity violation"
            )

        self.qbit = authoritative_qbit
        self.qbit_instance = authoritative_qbit

        if hasattr(
            self,
            "qbit_core",
        ):

            self.qbit_core = authoritative_qbit

        # ------------------------------------------------------
        # FIND AUTHORITATIVE QBITQUEUELOOP
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "queue_loop",
                None,
            )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "_qbit_queue_loop",
                None,
            )

        # ------------------------------------------------------
        # QBITQUEUELOOP IS REQUIRED
        #
        # NO DIALER LOOP FALLBACK.
        # ------------------------------------------------------

        if queue_loop is None:

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "WAITING"
            self._runtime_state = "WAITING"

            self.logger.warning(
                "[QbitDialer] Qbit runtime waiting | "
                "QbitQueueLoop not bound"
            )

            return None

        # ------------------------------------------------------
        # QUEUE LOOP SHUTDOWN CHECK
        # ------------------------------------------------------

        if getattr(
            queue_loop,
            "shutdown_requested",
            False,
        ):

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "WAITING"
            self._runtime_state = "WAITING"

            self.logger.warning(
                "[QbitDialer] Qbit runtime waiting | "
                "QbitQueueLoop is shutting down"
            )

            return None

        # ------------------------------------------------------
        # BIND QBITQUEUELOOP
        # ------------------------------------------------------

        self.qbit_queue_loop = queue_loop

        if hasattr(
            self,
            "queue_loop",
        ):

            self.queue_loop = queue_loop

        if hasattr(
            self,
            "_qbit_queue_loop",
        ):

            self._qbit_queue_loop = queue_loop

        # ------------------------------------------------------
        # COMMAND AUTHORITY
        #
        # QbitQueueLoop dispatches.
        # QbitDialer executes.
        # ------------------------------------------------------

        bound_dialer = getattr(
            queue_loop,
            "qbit_dialer",
            None,
        )

        if bound_dialer is None:

            bind_method = getattr(
                queue_loop,
                "bind_qbit_dialer",
                None,
            )

            if not callable(
                bind_method
            ):

                raise RuntimeError(
                    "[QbitDialer] QbitQueueLoop does not "
                    "support QbitDialer binding"
                )

            result = bind_method(
                self
            )

            if inspect.isawaitable(
                result
            ):

                await result

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

        if bound_dialer is not self:

            raise RuntimeError(
                "[QbitDialer] FATAL: QbitQueueLoop is "
                "bound to another QbitDialer"
            )

        # ------------------------------------------------------
        # AUTHORITATIVE OWNERSHIP
        # ------------------------------------------------------

        self._queue_authoritative = True
        self._qbit_queue_authoritative = True

        self._queue_owner = queue_loop

        # ------------------------------------------------------
        # CRITICAL:
        #
        # QbitDialer IS NOT THE QUEUE CONSUMER.
        # ------------------------------------------------------

        self._queue_consumer = False

        # ------------------------------------------------------
        # CRITICAL:
        #
        # NO DIALER QBIT LOOP TASK.
        #
        # Any legacy task must not remain active.
        # ------------------------------------------------------

        legacy_task = getattr(
            self,
            "_qbit_loop_task",
            None,
        )

        if (
            legacy_task is not None
            and not legacy_task.done()
        ):

            legacy_task.cancel()

            self.logger.warning(
                "[QbitDialer] Cancelled legacy Dialer Qbit "
                "loop | QbitQueueLoop is authoritative"
            )

        self._qbit_loop_task = None

        # ------------------------------------------------------
        # DISABLE LEGACY LOOP PATH
        # ------------------------------------------------------

        self._queue_runtime_authoritative = True
        self._legacy_thread_loops_disabled = True
        self._dialer_loop_disabled = True

        # ------------------------------------------------------
        # COGNITIVE DEPENDENCIES
        # ------------------------------------------------------

        self.compute_brain = getattr(
            self,
            "compute_brain",
            getattr(
                self,
                "system_calc",
                None,
            ),
        )

        self.transformer_brain = getattr(
            self,
            "transformer_brain",
            None,
        )

        self.logger.info(
            "[QbitDialer] Cognitive dependencies bound | "
            "compute=%s | transformer=%s",
            (
                type(
                    self.compute_brain
                ).__name__
                if self.compute_brain is not None
                else "NONE"
            ),
            (
                type(
                    self.transformer_brain
                ).__name__
                if self.transformer_brain is not None
                else "NONE"
            ),
        )

        # ------------------------------------------------------
        # RUNTIME OWNERSHIP
        # ------------------------------------------------------

        self._qbit_runtime_mode = (
            "QUEUE_AUTHORITY"
        )

        self._qbit_runtime_owner = (
            "QbitQueueLoop"
        )

        self._qbit_execution_owner = (
            "QbitDialer"
        )

        # ------------------------------------------------------
        # FINAL QBIT IDENTITY CHECK
        # ------------------------------------------------------

        if self.qbit is not authoritative_qbit:

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "ERROR"
            self._runtime_state = "ERROR"

            raise RuntimeError(
                "[QbitDialer] FATAL: authoritative Qbit "
                "identity changed"
            )

        # ------------------------------------------------------
        # ONLINE
        #
        # IMPORTANT:
        #
        # ONLINE means the Dialer is bound to its authoritative
        # transport and command authority.
        #
        # It does NOT mean the Dialer owns a processing loop.
        # ------------------------------------------------------

        self._qbit_running = True
        self._running = True
        self.running = True

        self._qbit_runtime_state = "RUNNING"
        self._runtime_state = "RUNNING"

        self.logger.info(
            "[QbitDialer] Qbit runtime ONLINE | "
            "authority=QbitDialer | "
            "transport=QbitQueueLoop | "
            "dialer_loop=DISABLED | "
            "qbit=%s",
            getattr(
                self.qbit,
                "id",
                "unidentified",
            ),
        )

        return self


    # ==========================================================
    # QBIT PROCESSING LOOP
    #
    # SINGLE AUTHORITATIVE LOOP
    #
    # QbitQueueLoop owns the queue.
    # QbitDialer consumes from that exact queue.
    #
    # DO NOT CREATE ANOTHER LOOP.
    # DO NOT CREATE A THREAD.
    # DO NOT CREATE A NEW QUEUE.
    # DO NOT REBIND THE QUEUE DURING PROCESSING.
    #
    # IMPORTANT:
    #
    # An EMPTY queue is NOT a stopped runtime.
    #
    # The loop remains ONLINE and waits for the next Qbit.
    #
    # Only:
    #
    #     shutdown
    #     cancellation
    #     fatal runtime error
    #
    # may terminate this loop.
    # ==========================================================

    # ==========================================================
    # LEGACY QBIT LOOP â€” DISABLED
    #
    # AUTHORITATIVE RUNTIME:
    #
    #     QbitQueueLoop = transport / queue consumer
    #     QbitDialer    = command authority / execution
    #
    # QbitDialer MUST NOT:
    #     - consume a queue
    #     - call queue.get()
    #     - call queue.receive()
    #     - create another queue
    #     - create another QbitQueueLoop
    #     - create a runtime task for queue processing
    #     - create a thread for queue processing
    #
    # This method exists ONLY for compatibility with legacy
    # callers that still attempt to invoke QbitDialer._loop().
    #
    # IMPORTANT:
    #
    # Python uses the LAST method definition in the class.
    # There MUST NOT be another _loop() below this method.
    # ==========================================================

    async def _loop(self):

        self._dialer_loop_disabled = True
        self._queue_consumer = False

        self.logger.warning(
            "[QbitDialer] Legacy _loop() invocation rejected | "
            "QbitQueueLoop is authoritative"
        )

        if getattr(
            self,
            "_queue_authoritative",
            False,
        ):

            self.logger.info(
                "[QbitDialer] Legacy _loop() ignored | "
                "transport=QbitQueueLoop | "
                "dialer_loop=DISABLED"
            )

        else:

            self.logger.warning(
                "[QbitDialer] Legacy _loop() ignored | "
                "QbitQueueLoop not authoritative"
            )

        return False
    # ==========================================================
    # START
    #
    # PUBLIC ASYNC RUNTIME ENTRY POINT
    #
    # QbitDialer owns ONE Qbit execution loop.
    #
    # This method does NOT start SEEDCore, Heartbeat, Device,
    # Audio, Modem, HUD, or any other system-wide runtime.
    #
    # ==========================================================

    async def start(
        self,
        initial_state=None,
        qbit=None,
        **kwargs,
    ):

        # ==========================================================
        # START LOCK
        # ==========================================================

        start_lock = getattr(
            self,
            "_start_lock",
            None,
        )

        if start_lock is None:

            start_lock = asyncio.Lock()

            self._start_lock = start_lock

        async with start_lock:

            # ======================================================
            # SHUTDOWN GATE
            # ======================================================

            shutdown_flag = getattr(
                self,
                "shutdown_flag",
                None,
            )

            if (
                shutdown_flag is not None
                and shutdown_flag.is_set()
            ):

                self.logger.warning(
                    "[QbitDialer] start() rejected - "
                    "shutdown requested"
                )

                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "SHUTDOWN"
                )

                return False

            # ======================================================
            # QBIT IDENTITY
            # ======================================================

            if qbit is not None:

                existing_qbit = getattr(
                    self,
                    "qbit",
                    None,
                )

                if (
                    existing_qbit is not None
                    and existing_qbit is not qbit
                ):

                    raise RuntimeError(
                        "[QbitDialer] FATAL: canonical Qbit "
                        "identity violation"
                    )

                if existing_qbit is None:

                    self.qbit = qbit

            # ------------------------------------------------------
            # Resolve canonical Qbit.
            # ------------------------------------------------------

            canonical_qbit = getattr(
                self,
                "qbit_instance",
                None,
            )

            if canonical_qbit is None:

                canonical_qbit = getattr(
                    self,
                    "qbit",
                    None,
                )

            if canonical_qbit is None:

                self.logger.error(
                    "[QbitDialer] start() blocked - "
                    "authoritative Qbit is not bound"
                )

                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "WAITING"
                )

                return False

            # ------------------------------------------------------
            # Preserve ONE canonical Qbit identity.
            # ------------------------------------------------------

            existing_qbit = getattr(
                self,
                "qbit",
                None,
            )

            if (
                existing_qbit is not None
                and existing_qbit is not canonical_qbit
            ):

                raise RuntimeError(
                    "[QbitDialer] FATAL: canonical Qbit "
                    "identity violation"
                )

            self.qbit = canonical_qbit
            self.qbit_instance = canonical_qbit

            # ======================================================
            # INITIAL STATE
            # ======================================================

            if initial_state is not None:

                self.initial_state = (
                    initial_state
                )

            elif not hasattr(
                self,
                "initial_state",
            ):

                self.initial_state = None

            # ======================================================
            # AUTHORITATIVE ASYNCIO LOOP
            # ======================================================

            try:

                self.loop = (
                    asyncio.get_running_loop()
                )

            except RuntimeError as exc:

                self.logger.error(
                    "[QbitDialer] start() requires "
                    "a running asyncio event loop"
                )

                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "WAITING"
                )

                raise RuntimeError(
                    "[QbitDialer] async start() requires "
                    "a running asyncio event loop"
                ) from exc

            # ======================================================
            # ALREADY RUNNING
            #
            # Accept either canonical task reference.
            # ======================================================

            existing_task = getattr(
                self,
                "_qbit_loop_task",
                None,
            )

            if existing_task is None:

                existing_task = getattr(
                    self,
                    "_qbit_task",
                    None,
                )

            if (
                existing_task is not None
                and not existing_task.done()
            ):

                self._qbit_loop_task = (
                    existing_task
                )

                self._qbit_task = (
                    existing_task
                )

                self._running = True
                self.running = True
                self._qbit_running = True

                self._qbit_runtime_state = (
                    "RUNNING"
                )

                self.logger.debug(
                    "[QbitDialer] start() ignored | "
                    "authoritative Qbit runtime already running"
                )

                return True

            # ======================================================
            # REQUIRE AUTHORITATIVE QBIT QUEUE LOOP
            #
            # QbitDialer must bind to the existing
            # QbitQueueLoop. It must NEVER create another one.
            # ======================================================

            queue_loop = getattr(
                self,
                "qbit_queue_loop",
                None,
            )

            if queue_loop is None:

                queue_loop = getattr(
                    self,
                    "_qbit_queue_loop",
                    None,
                )

            if queue_loop is None:

                queue_loop = getattr(
                    self,
                    "queue_loop",
                    None,
                )

            if queue_loop is None:

                self.logger.error(
                    "[QbitDialer] start() blocked - "
                    "authoritative QbitQueueLoop is not bound"
                )

                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "WAITING"
                )

                return False

            # ------------------------------------------------------
            # Verify that this is the QbitQueueLoop object itself.
            #
            # Do NOT replace it with queue_loop.qbit_queue.
            # ------------------------------------------------------

            try:

                from seed.core.qbit.qbit_queue_loop import (
                    QbitQueueLoop,
                )

            except Exception:

                QbitQueueLoop = None

            if (
                QbitQueueLoop is not None
                and not isinstance(
                    queue_loop,
                    QbitQueueLoop,
                )
            ):

                raise RuntimeError(
                    "[QbitDialer] FATAL: "
                    "qbit_queue_loop must be the authoritative "
                    "QbitQueueLoop instance"
                )

            # ------------------------------------------------------
            # Store ONE authoritative QueueLoop reference.
            # ------------------------------------------------------

            self.qbit_queue_loop = (
                queue_loop
            )

            self._qbit_queue_loop = (
                queue_loop
            )

            self.queue_loop = (
                queue_loop
            )
            self.qbit_queue = (
                queue_loop
            )
            self._qbit_queue = (
                queue_loop
            )

            # ======================================================
            # QUEUE LOOP / DIALER IDENTITY
            # ======================================================

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if bound_dialer is None:

                bind_method = getattr(
                    queue_loop,
                    "bind_qbit_dialer",
                    None,
                )

                if not callable(
                    bind_method
                ):

                    raise RuntimeError(
                        "[QbitDialer] FATAL: "
                        "QbitQueueLoop cannot bind QbitDialer"
                    )

                result = bind_method(
                    self
                )

                if inspect.isawaitable(
                    result
                ):

                    await result

                bound_dialer = getattr(
                    queue_loop,
                    "qbit_dialer",
                    None,
                )

            if bound_dialer is not self:

                raise RuntimeError(
                    "[QbitDialer] FATAL: "
                    "QbitQueueLoop is bound to another "
                    "QbitDialer"
                )

            # ======================================================
            # VERIFY QUEUE LOOP STATE
            # ======================================================

            queue_shutdown = getattr(
                queue_loop,
                "shutdown_requested",
                False,
            )

            if queue_shutdown:

                self.logger.error(
                    "[QbitDialer] start() blocked - "
                    "QbitQueueLoop is shutting down"
                )

                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "WAITING"
                )

                return False

            # ======================================================
            # EVENT BUS GATE
            # ======================================================

            while (
                not getattr(
                    self,
                    "event_bus",
                    None,
                )
                or not hasattr(
                    self.event_bus,
                    "publish",
                )
            ):

                shutdown_flag = getattr(
                    self,
                    "shutdown_flag",
                    None,
                )

                if (
                    shutdown_flag is not None
                    and shutdown_flag.is_set()
                ):

                    self._running = False
                    self.running = False
                    self._qbit_running = False

                    self._qbit_runtime_state = (
                        "SHUTDOWN"
                    )

                    return False

                self.logger.warning(
                    "[QbitDialer] blocked - "
                    "waiting for EventBus"
                )

                await asyncio.sleep(
                    0.25
                )

            # ======================================================
            # RUNTIME STATE
            # ======================================================

            self._running = True
            self.running = True
            self._qbit_running = True

            self._qbit_runtime_state = (
                "STARTING"
            )

            # ======================================================
            # COMMAND PLANE
            #
            # Commands must be registered before Qbit processing.
            # ======================================================

            refresh = getattr(
                self,
                "refresh_command_capabilities",
                None,
            )

            # --------------------------------------------------
            # STARTUP COMMAND-PLANE GATE
            #
            # The constructor and main3 boot path already
            # synchronize the authoritative command plane.
            # Re-discovering every connected system here can
            # re-enter subsystem capability inspection while
            # those systems are still completing boot.
            #
            # Reuse a healthy synchronized plane at startup.
            # Dynamic capability refresh remains available after
            # boot through refresh_command_capabilities().
            # --------------------------------------------------

            command_plane = getattr(
                self,
                "command_plane",
                None,
            )

            command_plane_ready = (
                isinstance(command_plane, dict)
                and bool(command_plane.get("online"))
                and int(command_plane.get("executable", 0) or 0) > 0
            )

            if command_plane_ready:
                self.logger.info(
                    "[QbitDialer] Startup command plane already synchronized | "
                    "cataloged=%s | executable=%s | pending=%s | "
                    "refresh deferred until post-boot",
                    command_plane.get("cataloged", 0),
                    command_plane.get("executable", 0),
                    command_plane.get("pending", 0),
                )

            elif callable(refresh):

                try:

                    result = refresh()

                    if inspect.isawaitable(
                        result
                    ):

                        await result

                except Exception:

                    self._running = False
                    self.running = False
                    self._qbit_running = False

                    self._qbit_runtime_state = (
                        "ERROR"
                    )

                    self.logger.exception(
                        "[QbitDialer] Command capability "
                        "refresh failed during startup"
                    )

                    raise

            # ======================================================
            # COGNITIVE DEPENDENCIES
            #
            # Attach existing brains only.
            # Do NOT create their runtime loops here.
            # ======================================================

            self.compute_brain = getattr(
                self,
                "compute_brain",
                getattr(
                    self,
                    "system_calc",
                    None,
                ),
            )

            self.transformer_brain = getattr(
                self,
                "transformer_brain",
                None,
            )

            self.logger.info(
                "[QbitDialer] Cognitive dependencies attached | "
                "compute=%s | transformer=%s",
                (
                    type(
                        self.compute_brain
                    ).__name__
                    if self.compute_brain is not None
                    else "NONE"
                ),
                (
                    type(
                        self.transformer_brain
                    ).__name__
                    if self.transformer_brain is not None
                    else "NONE"
                ),
            )

            # ======================================================
            # NO GENERIC BRAIN TASKS
            # ======================================================

            self._brain_tasks = []

            # ======================================================
            # AUTHORITATIVE RUNTIME BINDINGS
            # ======================================================

            self.logger.info(
                "[QbitDialer] Authoritative runtime bindings confirmed | "
                "qbit=%s | queue_loop=%s | dialer=%s",
                getattr(
                    canonical_qbit,
                    "id",
                    "unidentified",
                ),
                type(
                    queue_loop
                ).__name__,
                type(
                    self
                ).__name__,
            )

            # ======================================================
            # READY STATE
            # ======================================================

            try:

                # Startup telemetry must never block the cognitive runtime.
                # EventBus handlers can be async and may depend on Dialer
                # readiness, so publish it as a task after the authority is
                # marked STARTING rather than awaiting it here.
                ready_publish = self.publish(
                    payload={
                        "state": "ready",
                        "component": "QbitDialer",
                        "qbit_id": getattr(
                            canonical_qbit,
                            "id",
                            None,
                        ),
                        "queue_loop": type(
                            queue_loop
                        ).__name__,
                        "command_authority": True,
                    }
                )
                if inspect.isawaitable(ready_publish):
                    runtime_loop = getattr(self, "loop", None)
                    if runtime_loop is not None and runtime_loop.is_running():
                        runtime_loop.create_task(ready_publish, name="QbitDialer-ready-telemetry")
                    else:
                        await ready_publish

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Failed to schedule ready state telemetry"
                )

            # ======================================================
            # AUTHORITATIVE RUNTIME CONTRACT
            #
            # start_qbit_loop() binds/verifies the authoritative
            # QbitQueueLoop and returns the Dialer instance.
            #
            # QbitDialer does NOT own the queue-processing task.
            # QbitQueueLoop owns authoritative transport/runtime.
            # ======================================================

            runtime_result = await self.start_qbit_loop(
                self.initial_state
            )

            if runtime_result is not self:
                self._running = False
                self.running = False
                self._qbit_running = False

                self._qbit_runtime_state = (
                    "ERROR"
                )

                raise RuntimeError(
                    "[QbitDialer] start_qbit_loop() "
                    "returned an invalid runtime object"
                )

            # ------------------------------------------------------
            # QbitDialer does not own an asyncio queue task.
            # ------------------------------------------------------

            self._qbit_loop_task = None
            self._qbit_task = None

            self._legacy_thread_loops_disabled = True

            # ======================================================
            # FINAL STATE
            # ======================================================

            self._running = True
            self.running = True
            self._qbit_running = True

            self._qbit_runtime_state = (
                "RUNNING"
            )

            self.logger.info(
                "[QbitDialer] Async runtime started | "
                "qbit_task=QueueLoop-authoritative | commands=%d | "
                "compute=%s | transformer=%s | "
                "transport=QbitQueueLoop | "
                "authority=QbitDialer",
                len(
                    getattr(
                        self,
                        "command_registry",
                        {},
                    )
                ),
                (
                    "ONLINE"
                    if self.compute_brain is not None
                    else "OFFLINE"
                ),
                (
                    "ONLINE"
                    if self.transformer_brain is not None
                    else "OFFLINE"
                ),
            )

            return self

    # ==========================================================
    # RECEIVE QBIT
    #
    # INPUT / IDENTIFICATION / PROCESSING INTAKE
    #
    # QbitDialer receives the canonical Qbit here, identifies
    # its system context, preserves its metadata, and forwards
    # the SAME Qbit object into the authoritative QbitQueueLoop.
    #
    # Authoritative path:
    #
    #     receive_qbit()
    #          â†“
    #     identify Qbit / system context
    #          â†“
    #     TrackSystem / Registry / EventBus observation
    #          â†“
    #     authoritative QbitQueueLoop
    #          â†“
    #     QbitDialer processing
    #          â†“
    #     _process_qbit()
    #
    # receive_qbit() NEVER:
    #
    #     - creates a Qbit
    #     - clones a Qbit
    #     - creates another QueueLoop
    #     - creates another asyncio runtime
    #     - creates a competing processing task
    #     - changes command authority
    # ==========================================================

    def receive_qbit(
        self,
        qbit,
        **kwargs,
    ):

        # ======================================================
        # QBIT TYPE / IDENTITY GATE
        # ======================================================

        if not isinstance(
            qbit,
            Qbit,
        ):

            raise TypeError(
                "[QbitDialer] receive_qbit received "
                f"invalid object: {type(qbit)!r}"
            )

        # ------------------------------------------------------
        # Preserve the exact incoming Qbit object.
        # ------------------------------------------------------

        self.last_qbit = qbit

        qbit_id = getattr(
            qbit,
            "id",
            None,
        )

        if qbit_id is None:

            qbit_id = getattr(
                qbit,
                "qbit_id",
                None,
            )

        # ======================================================
        # CANONICAL QBIT IDENTITY CHECK
        # ======================================================

        canonical_qbit = getattr(
            self,
            "qbit",
            None,
        )

        if (
            canonical_qbit is not None
            and canonical_qbit is not qbit
        ):

            self.logger.warning(
                "[QbitDialer] Incoming Qbit is not the "
                "authoritative bound Qbit | "
                "incoming=%s | authoritative=%s",
                qbit_id,
                getattr(
                    canonical_qbit,
                    "id",
                    None,
                ),
            )

            # --------------------------------------------------
            # Do not replace the authoritative Qbit.
            #
            # Multiple Qbits are valid carriers, but the Dialer
            # must never silently replace its canonical runtime
            # Qbit identity.
            # --------------------------------------------------

        # ======================================================
        # PRESERVE INCOMING CONTEXT
        # ======================================================

        context = getattr(
            self,
            "_qbit_receive_context",
            None,
        )

        if not isinstance(
            context,
            dict,
        ):

            context = {}

            self._qbit_receive_context = (
                context
            )

        if kwargs:

            context.update(
                kwargs
            )

        # ------------------------------------------------------
        # Add identification data without modifying the Qbit.
        # ------------------------------------------------------

        context.update(
            {
                "qbit_id": qbit_id,
                "qbit_type": type(
                    qbit
                ).__name__,
                "source": getattr(
                    qbit,
                    "source",
                    None,
                ),
                "source_mode": getattr(
                    qbit,
                    "source_mode",
                    None,
                ),
                "track_id": getattr(
                    qbit,
                    "track_id",
                    None,
                ),
                "channel_id": getattr(
                    qbit,
                    "channel_id",
                    None,
                ),
                "parent_qbit_id": getattr(
                    qbit,
                    "parent_qbit_id",
                    None,
                ),
                "generation": getattr(
                    qbit,
                    "generation",
                    None,
                ),
            }
        )

        # ======================================================
        # SYSTEM COMPONENT REFERENCES
        #
        # Resolve existing runtime authorities only.
        # Nothing is constructed here.
        # ======================================================

        track_system = getattr(
            self,
            "track_system",
            None,
        )

        track_context = getattr(
            self,
            "track_context",
            None,
        )

        registry = getattr(
            self,
            "registry",
            None,
        )

        nodes = getattr(
            self,
            "nodes",
            None,
        )

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        # ======================================================
        # TRACK / DATA IDENTIFICATION
        #
        # TrackSystem remains the data-flow authority.
        #
        # QbitDialer observes/associates the Qbit with existing
        # track information but does not create a competing
        # TrackSystem or execution path.
        # ======================================================

        track_id = getattr(
            qbit,
            "track_id",
            None,
        )

        channel_id = getattr(
            qbit,
            "channel_id",
            None,
        )

        if track_system is not None:

            context["track_system"] = (
                type(
                    track_system
                ).__name__
            )

            # --------------------------------------------------
            # Ask existing TrackSystem interfaces for identity
            # information when available.
            # --------------------------------------------------

            identify = getattr(
                track_system,
                "identify_qbit",
                None,
            )

            if callable(
                identify
            ):

                try:

                    identified = identify(
                        qbit
                    )

                    if isinstance(
                        identified,
                        dict,
                    ):

                        context.update(
                            identified
                        )

                        track_id = (
                            identified.get(
                                "track_id",
                                track_id,
                            )
                        )

                        channel_id = (
                            identified.get(
                                "channel_id",
                                channel_id,
                            )
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] TrackSystem "
                        "Qbit identification failed | "
                        "qbit=%s",
                        qbit_id,
                    )

        # ------------------------------------------------------
        # Preserve resolved identity in receive context.
        # ------------------------------------------------------

        context["track_id"] = (
            track_id
        )

        context["channel_id"] = (
            channel_id
        )

        if track_context is not None:

            context["track_context"] = (
                type(
                    track_context
                ).__name__
            )

        # ======================================================
        # REGISTRY IDENTIFICATION
        #
        # Registry is observational/runtime state here.
        # Do not replace or mutate authoritative registry
        # ownership merely to process an incoming Qbit.
        # ======================================================

        if registry is not None:

            context["registry"] = (
                type(
                    registry
                ).__name__
            )

            registry_lookup = getattr(
                registry,
                "get",
                None,
            )

            if callable(
                registry_lookup
            ):

                try:

                    registry_entry = (
                        registry_lookup(
                            qbit_id
                        )
                    )

                    if registry_entry is not None:

                        context[
                            "registry_entry"
                        ] = registry_entry

                except Exception:

                    self.logger.debug(
                        "[QbitDialer] Registry "
                        "lookup unavailable | qbit=%s",
                        qbit_id,
                        exc_info=True,
                    )

        # ======================================================
        # NODE IDENTIFICATION
        # ======================================================

        if nodes is not None:

            context["nodes"] = (
                type(
                    nodes
                ).__name__
            )

        # ======================================================
        # EVENTBUS OBSERVATION
        #
        # Publish identification telemetry only.
        #
        # This does NOT turn the incoming Qbit into a command.
        # ======================================================

        if (
            event_bus is not None
            and hasattr(
                event_bus,
                "publish",
            )
        ):

            try:

                event = {
                    "event": "qbit_received",
                    "component": "QbitDialer",
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "channel_id": channel_id,
                    "source": context.get(
                        "source"
                    ),
                    "source_mode": context.get(
                        "source_mode"
                    ),
                    "parent_qbit_id": context.get(
                        "parent_qbit_id"
                    ),
                    "generation": context.get(
                        "generation"
                    ),
                }

                result = event_bus.publish(
                    event
                )

                if inspect.isawaitable(
                    result
                ):

                    context[
                        "event_bus_publish"
                    ] = "DEFERRED"

                else:

                    context[
                        "event_bus_publish"
                    ] = "OK"

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Qbit receive "
                    "telemetry publish failed | qbit=%s",
                    qbit_id,
                    exc_info=True,
                )

        # ======================================================
        # RECEIVE TELEMETRY
        # ======================================================

        self.logger.info(
            "[QbitDialer] Qbit received | "
            "qbit=%s | track=%s | channel=%s | "
            "source=%s | generation=%s",
            qbit_id,
            track_id,
            channel_id,
            context.get(
                "source"
            ),
            context.get(
                "generation"
            ),
        )

        # ======================================================
        # AUTHORITATIVE QBIT QUEUE LOOP
        #
        # The Dialer must use the existing QbitQueueLoop.
        #
        # No create_task().
        # No new asyncio loop.
        # No new QueueLoop.
        # No direct command execution.
        # ======================================================

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "_qbit_queue_loop",
                None,
            )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "queue_loop",
                None,
            )

        # ------------------------------------------------------
        # Verify that the resolved object is the QueueLoop,
        # not its underlying physical queue.
        # ------------------------------------------------------

        if queue_loop is not None:

            queue_loop_type = type(
                queue_loop
            ).__name__

            if (
                "QbitQueueLoop"
                not in queue_loop_type
            ):

                self.logger.error(
                    "[QbitDialer] Qbit receive blocked | "
                    "resolved transport is not QbitQueueLoop | "
                    "type=%s",
                    queue_loop_type,
                )

                return False

        if queue_loop is not None:

            # --------------------------------------------------
            # Preserve all authoritative aliases as the SAME
            # QbitQueueLoop object.
            # --------------------------------------------------

            self.qbit_queue_loop = (
                queue_loop
            )

            self._qbit_queue_loop = (
                queue_loop
            )

            self.queue_loop = (
                queue_loop
            )
            self._qbit_queue = (
                queue_loop
            )

            self.qbit_queue = (
                queue_loop
            )

            # --------------------------------------------------
            # Verify Dialer ownership.
            # --------------------------------------------------

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if (
                bound_dialer is not None
                and bound_dialer is not self
            ):

                raise RuntimeError(
                    "[QbitDialer] FATAL: "
                    "authoritative QbitQueueLoop is "
                    "bound to another QbitDialer"
                )

            # --------------------------------------------------
            # QueueLoop transport.
            # --------------------------------------------------

            put = getattr(
                queue_loop,
                "put",
                None,
            )

            if callable(
                put
            ):

                try:

                    result = put(
                        qbit
                    )

                    # --------------------------------------------------
                    # asyncio transport may return a coroutine.
                    #
                    # receive_qbit() does not create another task.
                    # --------------------------------------------------

                    if inspect.isawaitable(
                        result
                    ):

                        return result

                    return result

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Authoritative "
                        "QbitQueueLoop put failed | "
                        "qbit=%s",
                        qbit_id,
                    )

                    return False

            # --------------------------------------------------
            # Compatibility with QueueLoop implementations that
            # expose enqueue() rather than put().
            # --------------------------------------------------

            enqueue = getattr(
                queue_loop,
                "enqueue",
                None,
            )

            if callable(
                enqueue
            ):

                try:

                    result = enqueue(
                        qbit
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        return result

                    return result

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Authoritative "
                        "QbitQueueLoop enqueue failed | "
                        "qbit=%s",
                        qbit_id,
                    )

                    return False

        # ======================================================
        # RUNTIME-AWARE FAILURE
        #
        # If Dialer is running, a missing authoritative queue
        # is a wiring failure. Never create a competing task.
        # ======================================================

        if getattr(
            self,
            "_running",
            False,
        ):

            self.logger.error(
                "[QbitDialer] Qbit received but "
                "authoritative QbitQueueLoop is unavailable | "
                "qbit=%s | runtime=RUNNING",
                qbit_id,
            )

            return False

        # ======================================================
        # NO ACTIVE QBIT RUNTIME
        #
        # Compatibility-only isolated processing.
        #
        # This does not start the Dialer runtime.
        # ======================================================

        try:

            running_loop = (
                asyncio.get_running_loop()
            )

        except RuntimeError:

            try:

                return asyncio.run(
                    self._process_qbit(
                        qbit,
                        **kwargs,
                    )
                )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Standalone Qbit "
                    "processing failed | qbit=%s",
                    qbit_id,
                )

                return False

        # ------------------------------------------------------
        # Existing event loop.
        #
        # Return the processing coroutine to the caller.
        # Do not create another task here.
        # ------------------------------------------------------

        return self._process_qbit(
            qbit,
            **kwargs,
        )
    # ==========================================================
    # COROUTINE RUNNER
    #
    # COMPATIBILITY HELPER ONLY.
    #
    # Does NOT own QbitDialer runtime lifecycle.
    # Does NOT start QbitDialer.
    # Does NOT create a persistent Qbit loop.
    # ==========================================================

    def _run_coro(
        self,
        coro,
        qbit=None,
    ):

        if coro is None:

            return False

        try:

            return asyncio.run(
                coro
            )

        except RuntimeError as exc:

            self.logger.warning(
                "[QbitDialer] _run_coro could not "
                "execute coroutine | %s",
                exc,
            )

            return False

    # ==========================================================
    # CORE PROCESSOR
    #
    # ==========================================================
    #
    # QBIT PROCESSOR
    #
    # AUTHORITATIVE FLOW:
    #
    #     Qbit
    #       â†“
    #     process_qbit()
    #       â†“
    #     ComputeBrain
    #       â†“
    #     ThoughtPacket
    #
    # This method performs DATA PROCESSING only.
    #
    # It does NOT:
    #
    #     - execute commands
    #     - create a command queue
    #     - create a Qbit
    #     - create another runtime
    #
    # Command creation/admission happens later through:
    #
    #     TransformerBrain
    #       â†“
    #     _build_cognitive_command()
    #       â†“
    #     submit_command()
    #
    # ==========================================================

    def process_qbit(
        self,
        qbit,
        metadata=None,
    ):

        # ======================================================
        # 1. HARD QBIT DATA BOUNDARY
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and not isinstance(
                qbit,
                qbit_type,
            )
        ):

            self.logger.warning(
                "[QbitDialer] process_qbit rejected invalid "
                "Qbit type | type=%s",
                type(qbit).__name__,
            )

            return None

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] process_qbit rejected | "
                "reason=qbit_unavailable"
            )

            return None
        # ==================================================
        # METADATA
        # ==================================================

        if metadata is None:

            metadata = getattr(
                qbit,
                "metadata",
                {},
            )

        if not isinstance(
            metadata,
            dict,
        ):

            metadata = {
                "value": metadata
            }

        metadata = dict(
            metadata
        )

        # --------------------------------------------------
        # Preserve Heartbeat planning data.
        #
        # "action" is DATA here, not an executable command.
        # HeartbeatEmitter does not execute it.
        # --------------------------------------------------

        metadata = self._sanitize_signal_metadata(
            metadata,
            preserve_fields={
                "action",
            },
        )

        # Record the incoming Qbit before cognition changes it.
        memory_graph = getattr(self, "memory_graph", None)
        if memory_graph is not None:
            try:
                memory_graph.add_qbit(qbit)
            except Exception as exc:
                self.logger.debug("QbitMemoryGraph record deferred: %s", exc)

        # ======================================================
        # 2. TIME TRAVEL / PATH ANALYSIS
        #
        # Preserve existing behavior, but never allow it to
        # become a second execution path.
        # ======================================================

        if self.time_travel_engine is not None:

            try:

                best_path = (
                    self.time_travel_engine.simulate(
                        qbit
                    )
                )

                if best_path:

                    self.time_travel_engine.execute_best(
                        qbit
                    )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Time-travel Qbit analysis failed"
                )

        # ======================================================
        # 3. EXISTING QBIT IDENTITY
        # ======================================================

        qbit_id = self._extract_qbit_field(
            qbit,
            "qbit_id",
            None,
        )

        if qbit_id is None:

            qbit_id = self._extract_qbit_field(
                qbit,
                "id",
                None,
            )

        track_id = self._extract_qbit_field(
            qbit,
            "track_id",
            None,
        )

        task = self._extract_qbit_field(
            qbit,
            "task",
            None,
        )

        task_id = self._extract_qbit_field(
            qbit,
            "task_id",
            None,
        )

        if task_id is None and isinstance(
            task,
            dict,
        ):

            task_id = task.get(
                "task_id"
            )

        pipeline_id = self._extract_qbit_field(
            qbit,
            "pipeline_id",
            None,
        )

        # ======================================================
        # 4. LOGGING
        # ======================================================

        self.logger.debug(
            "[QbitDialer] Processing Qbit DATA | "
            "qbit_id=%s | track_id=%s | "
            "task_id=%s | pipeline_id=%s",
            qbit_id,
            track_id,
            task_id,
            pipeline_id,
        )

        # ======================================================
        # 5. COMPUTE BRAIN
        #
        # Qbit -> ThoughtPacket
        #
        # One processor only.
        # ======================================================

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if compute_brain is None:

            compute_brain = getattr(
                self,
                "ComputeBrain",
                None,
            )

        if compute_brain is None:

            compute_brain = getattr(
                self,
                "computebrain",
                None,
            )

        if compute_brain is None:

            self.logger.warning(
                "[QbitDialer] ComputeBrain not attached | "
                "qbit_id=%s | track_id=%s",
                qbit_id,
                track_id,
            )

            return None

        # ======================================================
        # 6. BUILD SHARED COMPUTE CONTEXT
        #
        # Carry the create_task() context forward.
        # ======================================================

        compute_input = {

            "stage": "compute",

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "task": task,

            "lineage": (
                task.get(
                    "data_lineage"
                )
                if isinstance(
                    task,
                    dict,
                )
                else self._extract_qbit_field(
                    qbit,
                    "data_lineage",
                    None,
                )
            ),

            "relationships": (
                task.get(
                    "relationships"
                )
                if isinstance(
                    task,
                    dict,
                )
                else self._extract_qbit_field(
                    qbit,
                    "relationships",
                    None,
                )
            ),

            "who": (
                task.get(
                    "who"
                )
                if isinstance(
                    task,
                    dict,
                )
                else self._extract_qbit_field(
                    qbit,
                    "source",
                    "QBIT",
                )
            ),

            "what": (
                task.get(
                    "what"
                )
                if isinstance(
                    task,
                    dict,
                )
                else self._extract_qbit_field(
                    qbit,
                    "payload",
                    None,
                )
            ),

            "where": (
                task.get(
                    "where"
                )
                if isinstance(
                    task,
                    dict,
                )
                else None
            ),

            "why": (
                task.get(
                    "why"
                )
                if isinstance(
                    task,
                    dict,
                )
                else self._extract_qbit_field(
                    qbit,
                    "intent",
                    None,
                )
            ),

            "how": (
                task.get(
                    "how"
                )
                if isinstance(
                    task,
                    dict,
                )
                else None
            ),

        }

        # ======================================================
        # 7. COMPUTE
        # ======================================================

        thought = None

        try:

            processor = getattr(
                compute_brain,
                "process_qbit",
                None,
            )

            if not callable(
                processor
            ):

                processor = getattr(
                    compute_brain,
                    "process",
                    None,
                )

            if not callable(
                processor
            ):

                processor = getattr(
                    compute_brain,
                    "compute",
                    None,
                )

            if not callable(
                processor
            ):

                raise RuntimeError(
                    "ComputeBrain has no supported "
                    "Qbit processing method"
                )

            # --------------------------------------------------
            # Prefer the complete context when the processor
            # supports it. Fallback to the original Qbit keeps
            # existing ComputeBrain implementations compatible.
            # --------------------------------------------------

            try:

                thought = processor(
                    compute_input
                )

            except (
                TypeError,
            ):

                thought = processor(
                    qbit
                )

            if inspect.isawaitable(
                thought
            ):

                # process_qbit() itself is synchronous.
                #
                # Do not create a second runtime here.
                #
                # The async authoritative receive path owns
                # async ComputeBrain processing.
                self.logger.warning(
                    "[QbitDialer] ComputeBrain returned awaitable "
                    "from synchronous process_qbit() | "
                    "use _process_received_qbit() for async "
                    "cognitive processing | qbit_id=%s",
                    qbit_id,
                )

                return None

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] ComputeBrain Qbit processing failed | "
                "qbit_id=%s | track_id=%s | error=%s",
                qbit_id,
                track_id,
                exc,
            )

            return None

        # ======================================================
        # 8. PRESERVE COGNITIVE STATE
        # ======================================================

        if thought is not None:

            self.last_thought = thought

            try:

                self.cognitive_state[
                    "last_thought"
                ] = thought

                self.cognitive_state[
                    "last_qbit_id"
                ] = qbit_id

                self.cognitive_state[
                    "last_track_id"
                ] = track_id

                self.cognitive_state[
                    "last_task_id"
                ] = task_id

                self.cognitive_state[
                    "last_pipeline_id"
                ] = pipeline_id

            except Exception:

                pass

        # ======================================================
        # 9. PROGRESS
        # ======================================================

        state = getattr(
            self,
            "state",
            None,
        )

        if state is not None:

            try:

                state.last_progress_ts = (
                    time.time()
                )

            except Exception:

                pass

        return thought



# ==========================================================
# ASYNC QBIT PROCESSOR
#
# AUTHORITATIVE COGNITIVE ORGANIZER
#
# IMPORTANT:
#
#     create_task()
#          â†“
#     Qbit task / lineage / command vocabulary
#          â†“
#     _process_qbit()
#          â†“
#     ComputeBrain
#          â†“
#     ThoughtPacket
#          â†“
#     TransformerBrain
#          â†“
#     command envelope
#          â†“
#     submit_command()
#
# RAW Qbit objects NEVER go through execute_command().
# A Qbit in qbit.command_list is DATA and is routed to the
# cognitive receive path, not the command parser.
#
# ORACLE:
#
#     Oracle observes the Qbit and completed cognition.
#     Oracle may learn / record / classify observations.
#     Oracle MUST NOT become a second command authority.
#
# ==========================================================

    async def _process_qbit(
        self,
        qbit,
        metadata=None,
        **kwargs,
    ):

        # ======================================================
        # 1. VALIDATE QBIT
        # ======================================================

        if qbit is None:

            return None

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and not isinstance(
                qbit,
                qbit_type,
            )
        ):

            self.logger.warning(
                "[QbitDialer] _process_qbit rejected invalid "
                "Qbit type | type=%s",
                type(qbit).__name__,
            )

            return None

        # ======================================================
        # 2. METADATA
        # ======================================================

        if metadata is None:

            metadata = getattr(
                qbit,
                "metadata",
                {},
            )

        if not isinstance(
            metadata,
            dict,
        ):

            metadata = {
                "value": metadata,
            }

        metadata = dict(
            metadata
        )

        # --------------------------------------------------
        # Preserve Heartbeat planning data.
        #
        # "action" is DATA here, not an executable command.
        # HeartbeatEmitter does not execute it.
        # --------------------------------------------------

        sanitize_metadata = getattr(
            self,
            "_sanitize_signal_metadata",
            None,
        )

        if callable(
            sanitize_metadata
        ):

            try:

                metadata = sanitize_metadata(
                    metadata,
                    preserve_fields={
                        "action",
                    },
                )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Metadata sanitization skipped",
                    exc_info=True,
                )

        # ======================================================
        # 3. AUTHORITATIVE EXISTING CONTEXT
        # ======================================================

        timestamp = time.time()

        qbit_id = self._extract_qbit_field(
            qbit,
            "qbit_id",
            self._extract_qbit_field(
                qbit,
                "id",
                None,
            ),
        )

        track_id = self._extract_qbit_field(
            qbit,
            "track_id",
            None,
        )

        task = self._extract_qbit_field(
            qbit,
            "task",
            None,
        )

        task_id = self._extract_qbit_field(
            qbit,
            "task_id",
            None,
        )

        if (
            task_id is None
            and isinstance(
                task,
                dict,
            )
        ):

            task_id = task.get(
                "task_id"
            )

        pipeline_id = self._extract_qbit_field(
            qbit,
            "pipeline_id",
            None,
        )

        source = self._extract_qbit_field(
            qbit,
            "source",
            None,
        )

        if source is None:

            source = "QBIT"

        # IntentEngine is the authoritative vocabulary for missing intent.
        if intent_name is None:
            intent_engine = getattr(self, "intent_engine", None)
            evaluate = getattr(intent_engine, "evaluate", None) if intent_engine is not None else None
            if callable(evaluate):
                try:
                    intent_result = evaluate(
                        {
                            "qbit": qbit,
                            "source": source,
                            "classification": classification,
                            "track_id": track_id,
                        },
                        qbit=qbit,
                        create_qbit=False,
                    )
                    if inspect.isawaitable(intent_result):
                        intent_result = await intent_result
                    if isinstance(intent_result, dict):
                        intent_name = intent_result.get("intent") or intent_result.get("dominant")
                except Exception as exc:
                    self.logger.debug(
                        "[QbitDialer] IntentEngine fallback unavailable | qbit_id=%s | error=%s",
                        qbit_id, exc,
                    )

        if not isinstance(intent_name, str) or not intent_name.strip():
            intent_name = "IDLE"
        else:
            intent_name = intent_name.strip().upper()

        channel = self._extract_qbit_field(
            qbit,
            "channel",
            None,
        )

        if channel is None:

            channel = self._extract_qbit_field(
                qbit,
                "channel_id",
                "QBIT",
            )

        # ======================================================
        # 4. PROCESSING CONTEXT
        # ======================================================

        processing_context = {

            "timestamp": timestamp,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "source": source,

            "channel": channel,

            "task": task,

            "metadata": dict(
                metadata
            ),

        }

        # --------------------------------------------------
        # Preserve explicit caller context.
        # --------------------------------------------------

        processing_context.update(
            kwargs
        )

        # --------------------------------------------------
        # Reassert authoritative Qbit identity.
        # Caller kwargs cannot replace it.
        # --------------------------------------------------

        processing_context[
            "qbit"
        ] = qbit

        processing_context[
            "qbit_id"
        ] = qbit_id

        processing_context[
            "track_id"
        ] = track_id

        processing_context[
            "task_id"
        ] = task_id

        processing_context[
            "pipeline_id"
        ] = pipeline_id

        # ======================================================
        # 5. DYNAMIC INFORMATION STORE
        # ======================================================

        knowledge = getattr(
            self,
            "qbit_knowledge",
            None,
        )

        if not isinstance(
            knowledge,
            dict,
        ):

            knowledge = {}

            self.qbit_knowledge = knowledge

        qbit_key = (
            qbit_id
            or track_id
            or f"QBIT-{id(qbit)}"
        )

        record = knowledge.get(
            qbit_key
        )

        if not isinstance(
            record,
            dict,
        ):

            record = {

                "qbit_id": qbit_id,

                "track_id": track_id,

                "task_id": task_id,

                "pipeline_id": pipeline_id,

                "observations": [],

                "commands": [],

                "classifications": [],

                "cognitive_results": [],

                "metadata": {},

                "first_seen": timestamp,

                "last_seen": timestamp,

            }

            knowledge[
                qbit_key
            ] = record

        record[
            "last_seen"
        ] = timestamp

        record[
            "qbit_id"
        ] = qbit_id

        record[
            "track_id"
        ] = track_id

        record[
            "task_id"
        ] = task_id

        record[
            "pipeline_id"
        ] = pipeline_id

        record[
            "metadata"
        ].update(
            processing_context[
                "metadata"
            ]
        )

        # ======================================================
        # 6. AUTHORITATIVE COGNITIVE RECEIVE
        #
        # ONE QBIT -> ONE AUTHORITATIVE COGNITIVE RECEIVE.
        #
        # Do not immediately call process_qbit() afterward.
        # Doing so would create a second cognition path for the
        # same Qbit lineage.
        # ======================================================

        thought = None

        cognitive_result = None

        receive = getattr(
            self,
            "_process_received_qbit",
            None,
        )

        if callable(
            receive
        ):

            try:

                cognitive_result = receive(
                    qbit
                )

                if inspect.isawaitable(
                    cognitive_result
                ):

                    cognitive_result = (
                        await cognitive_result
                    )

                record[
                    "last_cognitive_result"
                ] = cognitive_result

                # --------------------------------------------------
                # Preserve cognitive metadata.
                # --------------------------------------------------

                if isinstance(
                    cognitive_result,
                    dict,
                ):

                    record[
                        "metadata"
                    ][
                        "last_status"
                    ] = cognitive_result.get(
                        "status"
                    )

                    record[
                        "metadata"
                    ][
                        "last_intent"
                    ] = cognitive_result.get(
                        "intent"
                    )

                    record[
                        "metadata"
                    ][
                        "last_action"
                    ] = cognitive_result.get(
                        "action"
                    )

                    record[
                        "metadata"
                    ][
                        "last_command"
                    ] = (
                        cognitive_result.get(
                            "command"
                        )
                        or cognitive_result.get(
                            "command_name"
                        )
                        or cognitive_result.get(
                            "name"
                        )
                    )

                self.last_qbit_record = record

                self.last_qbit_context = (
                    processing_context
                )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Authoritative Qbit "
                    "cognitive receive failed | "
                    "qbit_id=%s | track_id=%s | error=%s",
                    qbit_id,
                    track_id,
                    exc,
                )

        # ======================================================
        # 7. LEGACY FALLBACK
        #
        # Only execute the legacy compute path when the
        # authoritative receive path is genuinely unavailable.
        #
        # If _process_received_qbit() ran and returned None,
        # do NOT automatically process the same Qbit again.
        # ======================================================

        if (
            cognitive_result is None
            and not callable(receive)
        ):

            legacy_process = getattr(
                self,
                "process_qbit",
                None,
            )

            if callable(
                legacy_process
            ):

                try:

                    thought = legacy_process(
                        qbit
                    )

                    if inspect.isawaitable(
                        thought
                    ):

                        thought = await thought

                except asyncio.CancelledError:

                    raise

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Legacy Qbit compute "
                        "processing failed | qbit_id=%s",
                        qbit_id,
                    )

                    thought = None

        # ======================================================
        # 8. STORE COMPUTE RESULT
        # ======================================================

        if thought is not None:

            record[
                "observations"
            ].append({

                "timestamp": time.time(),

                "type": (
                    thought.get(
                        "type"
                    )
                    if isinstance(
                        thought,
                        dict,
                    )
                    else type(
                        thought
                    ).__name__
                ),

                "value": thought,

            })

            max_history = getattr(
                self,
                "qbit_learning_history_limit",
                100,
            )

            try:

                max_history = max(
                    10,
                    int(
                        max_history
                    ),
                )

            except (
                TypeError,
                ValueError,
            ):

                max_history = 100

            record[
                "observations"
            ] = (
                record[
                    "observations"
                ][
                    -max_history:
                ]
            )

            record[
                "last_thought"
            ] = thought

        # ======================================================
        # 9. STORE THOUGHT METADATA
        # ======================================================

        if isinstance(
            thought,
            dict,
        ):

            classification = thought.get(
                "classification"
            )

            if classification:

                if classification not in record[
                    "classifications"
                ]:

                    record[
                        "classifications"
                    ].append(
                        classification
                    )

            for field_name in (
                "source",
                "channel",
                "track",
                "qbit_id",
                "track_id",
                "task_id",
                "pipeline_id",
            ):

                value = thought.get(
                    field_name
                )

                if value is not None:

                    record[
                        "metadata"
                    ][
                        f"last_{field_name}"
                    ] = value

        # ======================================================
        # 10. PAYLOAD OBSERVATION
        # ======================================================

        payload = self._extract_qbit_field(
            qbit,
            "payload",
            None,
        )

        if payload is not None:

            try:

                emit = getattr(
                    self,
                    "emit",
                    None,
                )

                if callable(
                    emit
                ):

                    emit(
                        "QBIT_PAYLOAD",
                        payload,
                    )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] QBIT_PAYLOAD emission failed"
                )

            record[
                "metadata"
            ][
                "last_payload"
            ] = payload

        # ======================================================
        # 11. QBIT COMMAND LIST
        #
        # A command_list may contain:
        #
        #     command strings
        #     command envelopes
        #     raw Qbits
        #
        # They are NOT interchangeable.
        #
        # RAW QBIT
        #     â†“
        # submit_qbit_command()
        #
        # COMMAND
        #     â†“
        # submit_command()
        #
        # Qbit data NEVER enters execute_command().
        # ======================================================

        command_list = self._extract_qbit_field(
            qbit,
            "command_list",
            [],
        )

        if command_list is None:

            command_list = []

        if not isinstance(
            command_list,
            (list, tuple),
        ):

            command_list = [
                command_list
            ]

        for cmd in command_list:

            try:

                # ==================================================
                # A. RAW QBIT = DATA
                # ==================================================

                if (
                    qbit_type is not None
                    and isinstance(
                        cmd,
                        qbit_type,
                    )
                ):

                    nested_qbit_id = (
                        self._extract_qbit_field(
                            cmd,
                            "qbit_id",
                            self._extract_qbit_field(
                                cmd,
                                "id",
                                None,
                            ),
                        )
                    )

                    nested_track_id = (
                        self._extract_qbit_field(
                            cmd,
                            "track_id",
                            None,
                        )
                    )

                    record[
                        "metadata"
                    ][
                        f"qbit:{nested_qbit_id or id(cmd)}"
                    ] = {

                        "type": "QBIT_DATA",

                        "qbit_id": nested_qbit_id,

                        "track_id": nested_track_id,

                        "parent_qbit_id": qbit_id,

                        "parent_task_id": task_id,

                        "timestamp": time.time(),

                    }

                    nested_result = (
                        self.submit_qbit_command(
                            cmd
                        )
                    )

                    if inspect.isawaitable(
                        nested_result
                    ):

                        nested_result = (
                            await nested_result
                        )

                    record[
                        "cognitive_results"
                    ].append({

                        "timestamp": time.time(),

                        "source": "QBIT_COMMAND_LIST",

                        "type": "QBIT_DATA",

                        "qbit_id": nested_qbit_id,

                        "track_id": nested_track_id,

                        "result": nested_result,

                    })

                    continue

                # ==================================================
                # B. DICT COMMAND ENVELOPE
                # ==================================================

                if isinstance(
                    cmd,
                    dict,
                ):

                    command_envelope = dict(
                        cmd
                    )

                    # ------------------------------------------------
                    # Qbit hidden inside command field = DATA.
                    # ------------------------------------------------

                    bad_qbit_name = False

                    for field_name in (
                        "name",
                        "command",
                        "cmd",
                        "action",
                    ):

                        candidate = (
                            command_envelope.get(
                                field_name
                            )
                        )

                        if (
                            qbit_type is not None
                            and isinstance(
                                candidate,
                                qbit_type,
                            )
                        ):

                            bad_qbit_name = True

                            nested_result = (
                                self.submit_qbit_command(
                                    candidate
                                )
                            )

                            if inspect.isawaitable(
                                nested_result
                            ):

                                nested_result = (
                                    await nested_result
                                )

                            record[
                                "cognitive_results"
                            ].append({

                                "timestamp": time.time(),

                                "source": (
                                    "QBIT_COMMAND_LIST"
                                ),

                                "type": "QBIT_DATA",

                                "qbit_id": (
                                    self._extract_qbit_field(
                                        candidate,
                                        "qbit_id",
                                        self._extract_qbit_field(
                                            candidate,
                                            "id",
                                            None,
                                        ),
                                    )
                                ),

                                "result": nested_result,

                            })

                            break

                    if bad_qbit_name:

                        continue

                    # ------------------------------------------------
                    # Resolve command name.
                    # ------------------------------------------------

                    command_name = (

                        command_envelope.get(
                            "name"
                        )
                        or command_envelope.get(
                            "command"
                        )
                        or command_envelope.get(
                            "cmd"
                        )
                        or command_envelope.get(
                            "action"
                        )

                    )

                    if (
                        not isinstance(
                            command_name,
                            str,
                        )
                        or not command_name.strip()
                    ):

                        self.logger.debug(
                            "[QbitDialer] Ignoring non-command "
                            "dictionary in Qbit command_list | "
                            "qbit_id=%s",
                            qbit_id,
                        )

                        continue

                    command_name = (
                        command_name.strip().upper()
                    )

                    # ------------------------------------------------
                    # Preserve authoritative lineage.
                    # ------------------------------------------------

                    command_envelope.setdefault(
                        "qbit",
                        qbit,
                    )

                    command_envelope.setdefault(
                        "qbit_id",
                        qbit_id,
                    )

                    command_envelope.setdefault(
                        "track_id",
                        track_id,
                    )

                    command_envelope.setdefault(
                        "task_id",
                        task_id,
                    )

                    command_envelope.setdefault(
                        "pipeline_id",
                        pipeline_id,
                    )

                    command_envelope.setdefault(
                        "parent_id",
                        qbit_id,
                    )

                    command_envelope.setdefault(
                        "source",
                        source,
                    )

                    command_envelope.setdefault(
                        "channel",
                        channel,
                    )

                    command_envelope.setdefault(
                        "authority",
                        "QbitDialer",
                    )

                    # ------------------------------------------------
                    # Catalog / registry metadata.
                    # ------------------------------------------------

                    catalog = getattr(
                        self,
                        "command_catalog",
                        {},
                    )

                    registry = getattr(
                        self,
                        "command_registry",
                        {},
                    )

                    capability = (
                        catalog.get(
                            command_name,
                            {},
                        )
                        if isinstance(
                            catalog,
                            dict,
                        )
                        else {}
                    )

                    handler = (
                        registry.get(
                            command_name
                        )
                        if isinstance(
                            registry,
                            dict,
                        )
                        else None
                    )

                    command_envelope[
                        "capability"
                    ] = capability

                    command_envelope[
                        "executable"
                    ] = callable(
                        handler
                    )

                    command_record = {

                        "name": command_name,

                        "qbit_id": qbit_id,

                        "track_id": track_id,

                        "task_id": task_id,

                        "pipeline_id": pipeline_id,

                        "source": source,

                        "capability_known": bool(
                            capability
                        ),

                        "executable": callable(
                            handler
                        ),

                    }

                    if command_record not in record[
                        "commands"
                    ]:

                        record[
                            "commands"
                        ].append(
                            command_record
                        )

                    # ------------------------------------------------
                    # COMMAND AUTHORITY.
                    #
                    # submit_command() remains the ONLY admission
                    # path for command envelopes.
                    # ------------------------------------------------

                    result = self.submit_command(
                        command_envelope
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        result = await result

                    record[
                        "cognitive_results"
                    ].append({

                        "timestamp": time.time(),

                        "source": "QBIT_COMMAND_LIST",

                        "type": "COMMAND",

                        "command": command_name,

                        "result": result,

                    })

                    continue

                # ==================================================
                # C. STRING COMMAND
                # ==================================================

                if isinstance(
                    cmd,
                    str,
                ):

                    command_name = (
                        cmd.strip().upper()
                    )

                    if not command_name:

                        continue

                    command_envelope = {

                        "name": command_name,

                        "qbit": qbit,

                        "qbit_id": qbit_id,

                        "track_id": track_id,

                        "task_id": task_id,

                        "pipeline_id": pipeline_id,

                        "parent_id": qbit_id,

                        "source": source,

                        "channel": channel,

                        "args": [],

                        "kwargs": {},

                        "payload": {},

                        "authority": "QbitDialer",

                    }

                    # ------------------------------------------------
                    # Catalog / registry visibility.
                    # ------------------------------------------------

                    catalog = getattr(
                        self,
                        "command_catalog",
                        {},
                    )

                    registry = getattr(
                        self,
                        "command_registry",
                        {},
                    )

                    capability = (
                        catalog.get(
                            command_name,
                            {},
                        )
                        if isinstance(
                            catalog,
                            dict,
                        )
                        else {}
                    )

                    handler = (
                        registry.get(
                            command_name
                        )
                        if isinstance(
                            registry,
                            dict,
                        )
                        else None
                    )

                    command_envelope[
                        "capability"
                    ] = capability

                    command_envelope[
                        "executable"
                    ] = callable(
                        handler
                    )

                    result = self.submit_command(
                        command_envelope
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        result = await result

                    record[
                        "commands"
                    ].append({

                        "name": command_name,

                        "qbit_id": qbit_id,

                        "track_id": track_id,

                        "task_id": task_id,

                        "pipeline_id": pipeline_id,

                    })

                    record[
                        "cognitive_results"
                    ].append({

                        "timestamp": time.time(),

                        "source": "QBIT_COMMAND_LIST",

                        "type": "COMMAND",

                        "command": command_name,

                        "result": result,

                    })

                    continue

                # ==================================================
                # D. UNKNOWN DATA TYPE
                # ==================================================

                self.logger.debug(
                    "[QbitDialer] Ignoring unsupported "
                    "Qbit command_list item | "
                    "type=%s | qbit_id=%s",
                    type(cmd).__name__,
                    qbit_id,
                )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Qbit command_list item failed | "
                    "qbit_id=%s | error=%s",
                    qbit_id,
                    exc,
                )

        # ======================================================
        # 12. BASIC AI MODEL / ORACLE BRANCH
        #
        # Only user-facing/input Qbits are sent to the basic model.
        # Heartbeats and system telemetry do not create model calls.
        # The model returns DATA to cognition; it cannot execute commands.
        # ======================================================
        model_oracle = getattr(self, "ai_model_oracle", None)
        if model_oracle is not None:
            try:
                payload = self._extract_qbit_field(qbit, "payload", None)
                user_input = None
                if isinstance(payload, str):
                    user_input = payload
                elif isinstance(payload, dict):
                    user_input = (
                        payload.get("user_input")
                        or payload.get("text")
                        or payload.get("message")
                        or payload.get("prompt")
                    )
                if user_input is None:
                    user_input = self._extract_qbit_field(qbit, "user_input", None)
                source_upper = str(source or "").upper()
                is_user_input = (
                    source_upper in {"USER", "FATHUD", "DEVHUD", "CLI", "CHATGPT"}
                    or user_input is not None
                )
                if is_user_input and user_input:
                    weights = dict(getattr(self, "ai_input_weights", {}) or {})
                    model_result = await asyncio.to_thread(
                        model_oracle.answer,
                        str(user_input),
                        weights,
                    )
                    if isinstance(cognitive_result, dict):
                        cognitive_result["oracle_model"] = model_result
                    record["metadata"]["oracle_model"] = model_result
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self.logger.debug(
                    "[QbitDialer] Basic AI Oracle model deferred | qbit_id=%s | error=%s",
                    qbit_id,
                    exc,
                    exc_info=True,
                )

        # ======================================================
        # 13. ORACLE OBSERVATION + COGNITIVE LEARNING
        #
        # Oracle is downstream observation/learning.
        # It never becomes command authority.
        # ======================================================

        try:

            oracle = getattr(
                self,
                "oracle",
                None,
            )

            if oracle is None:

                ensure_oracle = getattr(
                    self,
                    "_ensure_oracle",
                    None,
                )

                if callable(
                    ensure_oracle
                ):

                    oracle_result = ensure_oracle()

                    if inspect.isawaitable(
                        oracle_result
                    ):

                        oracle_result = (
                            await oracle_result
                        )

                    if oracle_result is not None:

                        oracle = oracle_result

            receive_qbit = getattr(
                oracle,
                "receive_qbit",
                None,
            )

            if callable(
                receive_qbit
            ):

                try:

                    oracle_result = receive_qbit(
                        qbit
                    )

                except TypeError:

                    oracle_result = receive_qbit(
                        qbit=qbit,
                        qbit_id=qbit_id,
                        task_id=task_id,
                        track_id=track_id,
                        channel_id=channel,
                        metadata_id=(
                            processing_context.get(
                                "metadata",
                                {},
                            ).get(
                                "metadata_id"
                            )
                            if isinstance(
                                processing_context.get(
                                    "metadata",
                                    {},
                                ),
                                dict,
                            )
                            else None
                        ),
                        metadata=processing_context.get(
                            "metadata",
                            {},
                        ),
                        thought=thought,
                        cognitive_result=cognitive_result,
                    )

                if inspect.isawaitable(
                    oracle_result
                ):

                    oracle_result = (
                        await oracle_result
                    )

                record[
                    "metadata"
                ][
                    "oracle_received"
                ] = True

                record[
                    "metadata"
                ][
                    "oracle_result"
                ] = oracle_result

                oracle_observation = {

                    "timestamp": time.time(),

                    "qbit": qbit,

                    "qbit_id": qbit_id,

                    "task_id": task_id,

                    "track_id": track_id,

                    "channel_id": channel,

                    "source": source,

                    "processing_context": (
                        processing_context
                    ),

                    "thought": thought,

                    "cognitive_result": (
                        cognitive_result
                    ),

                    "oracle_result": (
                        oracle_result
                    ),

                }

                for oracle_method_name in (
                    "observe_cognitive_result",
                    "record_observation",
                    "learn_from_qbit",
                    "observe_qbit",
                ):

                    oracle_method = getattr(
                        oracle,
                        oracle_method_name,
                        None,
                    )

                    if not callable(
                        oracle_method
                    ):

                        continue

                    try:

                        learning_result = (
                            oracle_method(
                                oracle_observation
                            )
                        )

                        if inspect.isawaitable(
                            learning_result
                        ):

                            learning_result = (
                                await learning_result
                            )

                        record[
                            "metadata"
                        ][
                            "oracle_learning_method"
                        ] = (
                            oracle_method_name
                        )

                        record[
                            "metadata"
                        ][
                            "oracle_learning_result"
                        ] = (
                            learning_result
                        )

                        break

                    except TypeError:

                        try:

                            learning_result = (
                                oracle_method(
                                    qbit
                                )
                            )

                            if inspect.isawaitable(
                                learning_result
                            ):

                                learning_result = (
                                    await learning_result
                                )

                            record[
                                "metadata"
                            ][
                                "oracle_learning_method"
                            ] = (
                                oracle_method_name
                            )

                            record[
                                "metadata"
                            ][
                                "oracle_learning_result"
                            ] = (
                                learning_result
                            )

                            break

                        except Exception:

                            self.logger.debug(
                                "[QbitDialer] Oracle learning "
                                "method rejected Qbit/context | "
                                "method=%s | qbit_id=%s",
                                oracle_method_name,
                                qbit_id,
                                exc_info=True,
                            )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Oracle learning "
                            "method failed | method=%s | "
                            "qbit_id=%s",
                            oracle_method_name,
                            qbit_id,
                        )

            else:

                record[
                    "metadata"
                ][
                    "oracle_received"
                ] = False

        except asyncio.CancelledError:

            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] Oracle Qbit observation failed | "
                "qbit_id=%s",
                qbit_id,
            )

        # ======================================================
        # 13. ROUTE OBSERVATION
        # ======================================================

        route = getattr(
            self,
            "route",
            None,
        )

        if callable(
            route
        ):

            try:

                route_result = route(
                    qbit
                )

                if inspect.isawaitable(
                    route_result
                ):

                    await route_result

            except asyncio.CancelledError:

                raise

            except Exception:

                self.logger.exception(
                    "[QbitDialer] Qbit route observation failed | "
                    "qbit_id=%s",
                    qbit_id,
                )

        # ======================================================
        # 14. FINAL STATE
        # ======================================================

        self.last_qbit = qbit

        self.last_qbit_record = record

        self.last_qbit_context = (
            processing_context
        )

        cognition_map = getattr(
            self,
            "cognition_map",
            None,
        )

        if cognition_map is not None:

            try:

                update = getattr(
                    cognition_map,
                    "update",
                    None,
                )

                if callable(
                    update
                ):

                    map_result = update(
                        qbit_key,
                        record,
                    )

                    if inspect.isawaitable(
                        map_result
                    ):

                        await map_result

            except asyncio.CancelledError:

                raise

            except Exception:

                self.logger.debug(
                    "[QbitDialer] CognitionMap update skipped | "
                    "qbit_id=%s",
                    qbit_id,
                    exc_info=True,
                )

        # ======================================================
        # 15. COGNITIVE RESULT RETURN CHANNEL
        #
        # The command admission response may be immediate/queued.
        # The completed cognitive result must also be emitted after
        # ComputeBrain -> TransformerBrain -> Oracle observation.
        # This is DATA/RESULT only; QbitDialer remains the command
        # authority and no second execution path is created.
        # ======================================================
        if cognitive_result is not None:
            try:
                self.emit(
                    "COGNITIVE_RESULT",
                    {
                        "qbit_id": qbit_id,
                        "track_id": track_id,
                        "task_id": task_id,
                        "pipeline_id": pipeline_id,
                        "source": source,
                        "authority": "QbitDialer",
                        "result": cognitive_result,
                    },
                )
            except Exception:
                self.logger.debug(
                    "[QbitDialer] COGNITIVE_RESULT emission deferred | qbit_id=%s",
                    qbit_id,
                    exc_info=True,
                )

        # ======================================================
        # 16. RETURN
        # ======================================================

        if cognitive_result is not None:

            return cognitive_result

        if thought is not None:

            return thought

        return None


# ==========================================================================
# ========= EMIT =======================================================
# ===========================================================================
    def emit(self, event_name, payload=None):


        # ==========================================================
        # VALIDATE EVENT
        # ==========================================================
        if not event_name:
            self.logger.debug(
                "[QbitDialer] emit ignored - empty event name"
            )
            return False

        if payload is None:
            payload = {}

        # ==========================================================
        # NORMALIZE EVENT NAME
        # ==========================================================
        try:
            event_name = str(event_name).strip()
        except Exception:
            event_name = "UNKNOWN"

        if not event_name:
            return False

        now = time.monotonic()

        # ==========================================================
        # TELEMETRY RATE GATE
        # ==========================================================
        telemetry_events = {
            "QBIT",
            "QBIT_TICK",
            "QBIT_STATE",
            "QBIT_TELEMETRY",
            "HEARTBEAT",
        }

        if event_name in telemetry_events:

            try:
                emit_interval = float(
                    getattr(
                        self,
                        "qbit_emit_interval",
                        0.500,
                    )
                )
            except (TypeError, ValueError):
                emit_interval = 0.500

            # Never allow a negative interval.
            emit_interval = max(
                emit_interval,
                0.050,
            )

            last_emit = getattr(
                self,
                "_last_emit_by_event",
                None,
            )

            if last_emit is None:
                last_emit = {}
                self._last_emit_by_event = last_emit

            previous = last_emit.get(
                event_name,
                0.0,
            )

            if (
                previous > 0.0
                and now - previous < emit_interval
            ):
                self._emit_suppressed = (
                    getattr(
                        self,
                        "_emit_suppressed",
                        0,
                    )
                    + 1
                )

                self.logger.debug(
                    "[QbitDialer] EMIT SUPPRESSED | "
                    "event=%s | %.3fs remaining",
                    event_name,
                    emit_interval - (now - previous),
                )

                return False

            last_emit[event_name] = now

        # ==========================================================
        # BUILD EVENT
        # ==========================================================
        event = {
            "event": event_name,
            "payload": payload,
            "source": "QbitDialer",
            "authority": "QbitDialer",
            "timestamp": time.time(),
        }

        # ==========================================================
        # BOUNDED LOCAL QUEUE
        # ==========================================================
        #
        # Always establish a bounded queue BEFORE publishing.
        #
        # This means EventBus failure cannot leave QbitDialer
        # without a controlled fallback path.
        #
        # ==========================================================
        queue = getattr(
            self,
            "queue",
            None,
        )

        queue_limit = getattr(
            self,
            "emit_queue_limit",
            512,
        )

        try:
            queue_limit = max(
                int(queue_limit),
                16,
            )
        except (TypeError, ValueError):
            queue_limit = 512

        if queue is None:

            queue = deque(
                maxlen=queue_limit
            )

            self.queue = queue

        # ==========================================================
        # LOCAL QUEUE INSERT
        # ==========================================================
        try:

            if hasattr(queue, "maxlen"):

                before = len(queue)

                queue.append(
                    (
                        event_name,
                        payload,
                    )
                )

                # deque(maxlen=...) silently evicts the oldest item.
                if (
                    queue.maxlen is not None
                    and before >= queue.maxlen
                ):
                    self._emit_queue_dropped = (
                        getattr(
                            self,
                            "_emit_queue_dropped",
                            0,
                        )
                        + 1
                    )

            else:

                # --------------------------------------------------
                # List compatibility
                # --------------------------------------------------
                if len(queue) >= queue_limit:

                    drop_count = (
                        len(queue)
                        - queue_limit
                        + 1
                    )

                    del queue[
                        :max(
                            1,
                            drop_count,
                        )
                    ]

                    self._emit_queue_dropped = (
                        getattr(
                            self,
                            "_emit_queue_dropped",
                            0,
                        )
                        + drop_count
                    )

                queue.append(
                    (
                        event_name,
                        payload,
                    )
                )

        except Exception:

            self.logger.exception(
                "[QbitDialer] Local emit queue failure | "
                "event=%s",
                event_name,
            )

        # ==========================================================
        # AUTHORITATIVE EVENTBUS
        # ==========================================================
        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        published = False

        if event_bus is not None:

            # ------------------------------------------------------
            # Prefer emit()
            # ------------------------------------------------------
            emit_method = getattr(
                event_bus,
                "emit",
                None,
            )

            # ------------------------------------------------------
            # Fall back to publish()
            # ------------------------------------------------------
            publish_method = getattr(
                event_bus,
                "publish",
                None,
            )

            try:

                if callable(emit_method):

                    try:

                        emit_method(
                            event_name,
                            payload,
                        )

                        published = True

                    except TypeError:

                        # EventBus may expect one event object.
                        emit_method(event)

                        published = True

                elif callable(publish_method):

                    try:

                        publish_method(
                            event_name,
                            payload,
                        )

                        published = True

                    except TypeError:

                        publish_method(event)

                        published = True

            except Exception:

                self.logger.exception(
                    "[QbitDialer] EventBus publication failed | "
                    "event=%s",
                    event_name,
                )

        # ==========================================================
        # SUBSCRIBERS
        # ==========================================================
        #
        # Subscribers are observers.
        # They never control whether the event itself exists.
        # ==========================================================
        try:

            self._notify_subscribers(
                event_name,
                payload,
            )

        except Exception:

            self.logger.exception(
                "[QbitDialer] Subscriber notification failed | "
                "event=%s",
                event_name,
            )

        # ==========================================================
        # CONTROLLED LOGGING
        # ==========================================================
        queue_size = 0

        try:
            queue_size = len(queue)
        except Exception:
            pass

        if published:

            self.logger.debug(
                "[QbitDialer] EMIT | "
                "event=%s | "
                "EventBus=ONLINE | "
                "queue=%d",
                event_name,
                queue_size,
            )

        else:

            self.logger.debug(
                "[QbitDialer] LOCAL EMIT | "
                "event=%s | "
                "EventBus=UNAVAILABLE | "
                "queue=%d",
                event_name,
                queue_size,
            )

        return True

#    def emit(self, event_name, payload=None):
#        self.queue.append((event_name, payload))
#        print(f"[QbitDialer] Emitted {event_name} -> {payload}")

    # ===============================
    # Async-Engine
    # ===============================

    async def async_engine(
        self,
        event_bus=None,
    ):

        # ==========================================================
        # RESOLVE AUTHORITATIVE EVENTBUS
        # ==========================================================

        if event_bus is not None:

            # Do not accidentally replace a valid EventBus
            # with a callback/function.
            if (
                hasattr(
                    event_bus,
                    "emit",
                )
                and callable(
                    getattr(
                        event_bus,
                        "emit",
                        None,
                    )
                )
            ):

                self.event_bus = event_bus

            else:

                self.logger.warning(
                    "[QbitDialer] Async engine rejected invalid "
                    "EventBus | type=%s",
                    type(event_bus).__name__,
                )

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        # ==========================================================
        # EVENTBUS GATE
        # ==========================================================

        while (
            getattr(
                self,
                "_running",
                False,
            )
            and (
                event_bus is None
                or not callable(
                    getattr(
                        event_bus,
                        "emit",
                        None,
                    )
                )
            )
        ):

            await asyncio.sleep(
                0.250
            )

            event_bus = getattr(
                self,
                "event_bus",
                None,
            )

        # ----------------------------------------------------------
        # Runtime may have stopped while waiting.
        # ----------------------------------------------------------

        if not getattr(
            self,
            "_running",
            False,
        ):

            self.logger.info(
                "[QbitDialer] Async engine stopped | "
                "QbitDialer runtime offline"
            )

            return False

        if event_bus is None:

            self.logger.warning(
                "[QbitDialer] Async engine stopped | "
                "EventBus unavailable"
            )

            return False

        self.logger.info(
            "[QbitDialer] Async engine ONLINE | "
            "event_bus=%s",
            type(
                event_bus
            ).__name__,
        )

        # ==========================================================
        # ENGINE STATE
        # ==========================================================

        self._async_engine_running = True

        interval = getattr(
            self,
            "async_engine_interval",
            1.0,
        )

        try:

            interval = float(
                interval
            )

        except (
            TypeError,
            ValueError,
        ):

            interval = 1.0

        # Never allow a zero-delay supervisor.
        interval = max(
            interval,
            0.250,
        )

        self._async_engine_interval = (
            interval
        )

        # ==========================================================
        # SUPERVISORY LOOP
        #
        # THIS METHOD OBSERVES.
        #
        # IT DOES NOT:
        #
        #     start Qbit
        #     stop Qbit
        #     restart Qbit
        #     create another Qbit loop
        #     generate heartbeat
        #     execute commands
        #
        # ==========================================================

        try:

            while (
                getattr(
                    self,
                    "_running",
                    False,
                )
                and getattr(
                    self,
                    "_async_engine_running",
                    True,
                )
            ):

                await asyncio.sleep(
                    interval
                )

                if not getattr(
                    self,
                    "_running",
                    False,
                ):

                    break

                # --------------------------------------------------
                # AUTHORITATIVE QBIT LOOP TASK
                #
                # The actual task created by the QbitDialer runtime
                # is _qbit_loop_task.
                #
                # Do NOT use _qbit_task here unless it is explicitly
                # the same task.
                # --------------------------------------------------

                qbit_task = getattr(
                    self,
                    "_qbit_loop_task",
                    None,
                )

                qbit_alive = (
                    qbit_task is not None
                    and not qbit_task.done()
                    and not qbit_task.cancelled()
                )

                # --------------------------------------------------
                # Capture task exception without restarting it.
                # --------------------------------------------------

                qbit_error = None

                if (
                    qbit_task is not None
                    and qbit_task.done()
                    and not qbit_task.cancelled()
                ):

                    try:

                        qbit_error = (
                            qbit_task.exception()
                        )

                    except (
                        asyncio.CancelledError,
                    ):

                        qbit_error = (
                            "cancelled"
                        )

                    except Exception as exc:

                        qbit_error = str(
                            exc
                        )

                # --------------------------------------------------
                # SUPERVISORY STATE ONLY
                # --------------------------------------------------

                if qbit_alive:

                    qbit_state = (
                        "running"
                    )

                elif qbit_task is None:

                    qbit_state = (
                        "not_started"
                    )

                elif qbit_task.cancelled():

                    qbit_state = (
                        "cancelled"
                    )

                elif qbit_error is not None:

                    qbit_state = (
                        "failed"
                    )

                else:

                    qbit_state = (
                        "stopped"
                    )

                payload = {
                    "component": (
                        "QbitDialer"
                    ),

                    "state": qbit_state,

                    "qbit_task_alive": (
                        qbit_alive
                    ),

                    "qbit_task_exists": (
                        qbit_task is not None
                    ),

                    "qbit_task_done": (
                        qbit_task.done()
                        if qbit_task is not None
                        else False
                    ),

                    "qbit_task_cancelled": (
                        qbit_task.cancelled()
                        if qbit_task is not None
                        else False
                    ),

                    "qbit_error": (
                        str(qbit_error)
                        if qbit_error is not None
                        else None
                    ),

                    "runtime": (
                        "ON"
                        if getattr(
                            self,
                            "_running",
                            False,
                        )
                        else "OFF"
                    ),

                    "timestamp": time.time(),
                }

                # ==================================================
                # DO NOT GENERATE HEARTBEAT
                #
                # HeartbeatEmitter is the authoritative heart.
                #
                # QbitDialer reports only its own state.
                # ==================================================

                try:

                    result = event_bus.emit(
                        "QBIT_RUNTIME",
                        payload,
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        await result

                except TypeError:

                    # --------------------------------------------------
                    # Compatibility with EventBus implementations
                    # accepting one event object.
                    # --------------------------------------------------

                    try:

                        result = event_bus.emit(
                            {
                                "event": (
                                    "QBIT_RUNTIME"
                                ),

                                "payload": payload,

                                "source": (
                                    "QbitDialer"
                                ),

                                "authority": (
                                    "QbitDialer"
                                ),

                                "timestamp": (
                                    time.time()
                                ),
                            }
                        )

                        if inspect.isawaitable(
                            result
                        ):

                            await result

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Async engine "
                            "EventBus publication failed"
                        )

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Async engine "
                        "EventBus publication failed"
                    )

        except asyncio.CancelledError:

            self.logger.info(
                "[QbitDialer] Async engine "
                "cancellation requested"
            )

            raise

        finally:

            self._async_engine_running = (
                False
            )

            self.logger.info(
                "[QbitDialer] Async engine OFFLINE"
            )

        return True
# ========================================================================
# ======================================================================

    def _load_upstream_track(self):
        try:
            # Use Qbitâ€™s upstream_track first
            if getattr(self.qbit, "upstream_track", None):
                self.tick = self.qbit.upstream_track.get("tick")
            else:
                # fallback: load latest JSON snapshot
                import glob
                import json
                files = glob.glob("C:/SEED_ROOT/seed/qbit_states/*.json")
                if files:
                    latest = max(files, key=lambda f: Path(f).stat().st_mtime)
                    with open(latest, "r") as f:
                        data = json.load(f)
                    self.tick = data.get("upstream_track", {}).get("tick")
        except Exception as e:
            logger.warning(f"[QbitDialer] Could not read upstream track: {e}")

    def qbit_channel_control(
        self,
        event,
    ):

        # ======================================================
        # 1. VALIDATE EVENT
        # ======================================================

        if not isinstance(
            event,
            dict,
        ):

            self.logger.warning(
                "[QbitDialer] Invalid channel control event | %r",
                event,
            )

            return False

        channel = event.get(
            "channel"
        )

        cmd = str(
            event.get(
                "command",
                "",
            )
        ).strip().upper()

        if channel is None:

            self.logger.warning(
                "[QbitDialer] Channel control rejected | "
                "missing channel"
            )

            return False

        # ======================================================
        # 2. AUTHORITATIVE SYSTEM REFERENCES
        #
        # Never manufacture dependencies here.
        # ======================================================

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:

            event_bus = SEEDEventBus

        registry = getattr(
            self,
            "registry",
            None,
        )

        if registry is None:

            registry = SEED_KERNEL_REGISTRY

        track_system = getattr(
            self,
            "track_system",
            None,
        )

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        # ======================================================
        # 3. AUTHORITATIVE QBIT QUEUE LOOP
        #
        # Connectivity only.
        #
        # QbitQueueLoop remains the sole queue consumer.
        # ======================================================

        queue_loop = (
            getattr(
                self,
                "qbit_queue_loop",
                None,
            )
            or getattr(
                self,
                "_qbit_queue_loop",
                None,
            )
            or getattr(
                self,
                "queue_loop",
                None,
            )
            or getattr(
                self,
                "_qbit_queue",
                None,
            )
        )

        # ======================================================
        # 4. AUTHORITATIVE QBIT
        # ======================================================

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        # ======================================================
        # 5. QBIT IDENTITY
        # ======================================================

        qbit_id = None
        track_id = None
        task_id = None
        pipeline_id = None

        if qbit is not None:

            try:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "qbit_id",
                    self._extract_qbit_field(
                        qbit,
                        "id",
                        None,
                    ),
                )

            except Exception:

                qbit_id = getattr(
                    qbit,
                    "qbit_id",
                    None,
                )

            try:

                track_id = self._extract_qbit_field(
                    qbit,
                    "track_id",
                    None,
                )

            except Exception:

                track_id = getattr(
                    qbit,
                    "track_id",
                    None,
                )

            try:

                task_id = self._extract_qbit_field(
                    qbit,
                    "task_id",
                    None,
                )

            except Exception:

                task_id = getattr(
                    qbit,
                    "task_id",
                    None,
                )

            try:

                pipeline_id = self._extract_qbit_field(
                    qbit,
                    "pipeline_id",
                    None,
                )

            except Exception:

                pipeline_id = getattr(
                    qbit,
                    "pipeline_id",
                    None,
                )

        # ======================================================
        # 6. TRACKSYSTEM CONNECTION
        #
        # TrackSystem owns track context.
        #
        # QbitDialer does NOT create a track.
        # It resolves and reports the existing context.
        # ======================================================

        track_context = None
        track_health = {}

        if track_system is not None:

            try:

                resolver = getattr(
                    track_system,
                    "get_track",
                    None,
                )

                if not callable(
                    resolver
                ):

                    resolver = getattr(
                        track_system,
                        "get_track_context",
                        None,
                    )

                if (
                    callable(resolver)
                    and track_id is not None
                ):

                    track_context = resolver(
                        track_id
                    )

                    if inspect.isawaitable(
                        track_context
                    ):

                        self.logger.warning(
                            "[QbitDialer] TrackSystem resolver "
                            "returned awaitable during synchronous "
                            "channel control | track_id=%s",
                            track_id,
                        )

                        track_context = None

            except Exception:

                self.logger.debug(
                    "[QbitDialer] TrackSystem context lookup failed | "
                    "track_id=%s",
                    track_id,
                    exc_info=True,
                )

            # --------------------------------------------------
            # Read TrackSystem health/state without activating it.
            # --------------------------------------------------

            for name in (
                "status",
                "state",
                "running",
                "_running",
                "active",
                "online",
            ):

                try:

                    if not hasattr(
                        track_system,
                        name,
                    ):

                        continue

                    value = getattr(
                        track_system,
                        name,
                    )

                    if callable(
                        value
                    ):

                        value = value()

                    if inspect.isawaitable(
                        value
                    ):

                        continue

                    track_health[
                        name
                    ] = value

                except Exception:

                    track_health[
                        name
                    ] = None

        # ======================================================
        # 7. TRACK CONTEXT IDENTITY
        #
        # If TrackSystem resolved the context, preserve its
        # authoritative identity for downstream cognition.
        # ======================================================

        if track_context is not None:

            try:

                if isinstance(
                    track_context,
                    dict,
                ):

                    resolved_track_id = (
                        track_context.get(
                            "track_id"
                        )
                        or track_context.get(
                            "id"
                        )
                    )

                else:

                    resolved_track_id = (
                        getattr(
                            track_context,
                            "track_id",
                            None,
                        )
                        or getattr(
                            track_context,
                            "id",
                            None,
                        )
                    )

                if resolved_track_id is not None:

                    track_id = (
                        resolved_track_id
                    )

            except Exception:

                pass

        # ======================================================
        # 8. REGISTRY CONNECTION
        #
        # SRegistry remains the authoritative registry.
        #
        # We only READ existing registration/capability state.
        # No secondary registry is created.
        # ======================================================

        registry_state = {
            "connected": registry is not None,
            "type": (
                type(
                    registry
                ).__name__
                if registry is not None
                else None
            ),
        }

        if registry is not None:

            try:

                registry_state[
                    "module"
                ] = (
                    getattr(
                        registry,
                        "module_name",
                        None,
                    )
                    or getattr(
                        registry,
                        "name",
                        None,
                    )
                )

                registry_state[
                    "initialized"
                ] = getattr(
                    registry,
                    "initialized",
                    None,
                )

            except Exception:

                pass

        # ======================================================
        # 9. COMPUTEBRAIN CONNECTION
        #
        # ComputeBrain is already designed to receive:
        #
        #   track_system
        #   registry
        #   event_bus
        #   channel_control
        #
        # Bind only missing references.
        #
        # NEVER replace an existing authoritative object.
        # ======================================================

        compute_state = {
            "connected": compute_brain is not None,
            "type": (
                type(
                    compute_brain
                ).__name__
                if compute_brain is not None
                else None
            ),
        }

        if compute_brain is not None:

            # --------------------------------------------------
            # TrackSystem
            # --------------------------------------------------

            try:

                existing_track_system = getattr(
                    compute_brain,
                    "track_system",
                    None,
                )

                if (
                    existing_track_system is None
                    and track_system is not None
                ):

                    compute_brain.track_system = (
                        track_system
                    )

                elif (
                    existing_track_system is not None
                    and track_system is not None
                    and existing_track_system
                    is not track_system
                ):

                    self.logger.warning(
                        "[QbitDialer] ComputeBrain TrackSystem "
                        "identity differs from Dialer TrackSystem | "
                        "preserving existing ComputeBrain reference"
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain TrackSystem "
                    "binding skipped",
                    exc_info=True,
                )

            # --------------------------------------------------
            # Registry
            # --------------------------------------------------

            try:

                existing_registry = getattr(
                    compute_brain,
                    "registry",
                    None,
                )

                if (
                    existing_registry is None
                    and registry is not None
                ):

                    compute_brain.registry = (
                        registry
                    )

                elif (
                    existing_registry is not None
                    and registry is not None
                    and existing_registry
                    is not registry
                ):

                    self.logger.warning(
                        "[QbitDialer] ComputeBrain registry "
                        "identity differs | preserving existing "
                        "authoritative ComputeBrain registry"
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain registry "
                    "binding skipped",
                    exc_info=True,
                )

            # --------------------------------------------------
            # EventBus
            # --------------------------------------------------

            try:

                existing_event_bus = getattr(
                    compute_brain,
                    "event_bus",
                    None,
                )

                if (
                    existing_event_bus is None
                    and event_bus is not None
                ):

                    compute_brain.event_bus = (
                        event_bus
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain EventBus "
                    "binding skipped",
                    exc_info=True,
                )

            # --------------------------------------------------
            # Channel control
            # --------------------------------------------------

            try:

                existing_channel_control = getattr(
                    compute_brain,
                    "channel_control",
                    None,
                )

                if (
                    existing_channel_control is None
                ):

                    compute_brain.channel_control = (
                        self.qbit_channel_control
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain channel "
                    "control binding skipped",
                    exc_info=True,
                )

            # --------------------------------------------------
            # Current Qbit
            # --------------------------------------------------

            try:

                if qbit is not None:

                    existing_qbit = getattr(
                        compute_brain,
                        "qbit",
                        None,
                    )

                    if (
                        existing_qbit is None
                        or existing_qbit is qbit
                    ):

                        compute_brain.qbit = qbit

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain Qbit "
                    "binding skipped",
                    exc_info=True,
                )

            # --------------------------------------------------
            # Compute state
            # --------------------------------------------------

            for name in (
                "compute_count",
                "confidence",
                "score",
                "last_qbit_id",
                "last_track_id",
                "last_channel_id",
                "last_task_id",
                "last_error",
            ):

                try:

                    if hasattr(
                        compute_brain,
                        name,
                    ):

                        compute_state[
                            name
                        ] = getattr(
                            compute_brain,
                            name,
                        )

                except Exception:

                    compute_state[
                        name
                    ] = None

        # ======================================================
        # 10. QBIT HEALTH / RUNTIME STATE
        #
        # READ ONLY.
        # ======================================================

        qbit_health = {}

        if qbit is not None:

            for name in (
                "health",
                "health_flags",
                "green_flags",
                "runtime_state",
                "status",
                "online",
                "running",
                "shutdown_flag",
            ):

                if not hasattr(
                    qbit,
                    name,
                ):

                    continue

                try:

                    value = getattr(
                        qbit,
                        name,
                    )

                    if callable(
                        value
                    ):

                        value = value()

                    if name == "shutdown_flag":

                        if hasattr(
                            value,
                            "is_set",
                        ):

                            value = bool(
                                value.is_set()
                            )

                        else:

                            value = bool(
                                value
                            )

                    qbit_health[
                        name
                    ] = value

                except Exception:

                    qbit_health[
                        name
                    ] = None

        # ======================================================
        # 11. QUEUE LOOP HEALTH
        #
        # READ ONLY.
        # ======================================================

        queue_health = {}

        if queue_loop is not None:

            for name in (
                "running",
                "_running",
                "online",
                "status",
                "runtime_state",
                "shutdown_requested",
                "queue_size",
                "health_flags",
            ):

                if not hasattr(
                    queue_loop,
                    name,
                ):

                    continue

                try:

                    value = getattr(
                        queue_loop,
                        name,
                    )

                    if callable(
                        value
                    ):

                        value = value()

                    if inspect.isawaitable(
                        value
                    ):

                        continue

                    queue_health[
                        name
                    ] = value

                except Exception:

                    queue_health[
                        name
                    ] = None

            # --------------------------------------------------
            # Authoritative queue size.
            # --------------------------------------------------

            try:

                queue = getattr(
                    queue_loop,
                    "queue",
                    None,
                )

                if queue is not None:

                    if hasattr(
                        queue,
                        "qsize",
                    ):

                        queue_health[
                            "queue_size"
                        ] = queue.qsize()

                    elif hasattr(
                        queue,
                        "__len__",
                    ):

                        queue_health[
                            "queue_size"
                        ] = len(queue)

            except Exception:

                pass

        # ======================================================
        # 12. REQUIRED QUEUE HEALTH GATE
        # ======================================================

        if queue_loop is None:

            self.logger.error(
                "[QbitDialer] Channel control rejected | "
                "QbitQueueLoop not connected | "
                "channel=%s | command=%s",
                channel,
                cmd,
            )

            return {
                "ok": False,
                "channel": channel,
                "command": cmd,
                "reason": "qbit_queue_loop_not_connected",
                "qbit_connected": qbit is not None,
                "track_system_connected": (
                    track_system is not None
                ),
                "registry_connected": (
                    registry is not None
                ),
                "compute_brain_connected": (
                    compute_brain is not None
                ),
            }

        # ======================================================
        # 13. APPLY CHANNEL CONTROL
        #
        # ChannelID owns channel state.
        # ======================================================

        state_changed = False
        flow_changed = False

        try:

            if cmd == "PAUSE":

                ChannelID.set_state(
                    channel,
                    "PAUSED",
                )

                state_changed = True

            elif cmd == "RESUME":

                ChannelID.set_state(
                    channel,
                    "ACTIVE",
                )

                state_changed = True

            elif cmd == "MUTE":

                ChannelID.set_state(
                    channel,
                    "MUTED",
                )

                state_changed = True

            elif cmd == "FLOW_OFF":

                ChannelID.set_flow(
                    channel,
                    False,
                )

                flow_changed = True

            elif cmd == "FLOW_ON":

                ChannelID.set_flow(
                    channel,
                    True,
                )

                flow_changed = True

            # ==================================================
            # HEALTH / STATUS
            # ==================================================

            elif cmd in (
                "HEALTH",
                "STATUS",
                "HEALTH_CHECK",
            ):

                return {
                    "ok": True,
                    "channel": channel,
                    "command": cmd,

                    "qbit_connected": (
                        qbit is not None
                    ),

                    "qbit_id": qbit_id,

                    "track_id": track_id,

                    "task_id": task_id,

                    "pipeline_id": pipeline_id,

                    "qbit_health": qbit_health,

                    "queue_loop_connected": True,

                    "queue_health": queue_health,

                    "track_system_connected": (
                        track_system is not None
                    ),

                    "track_context": track_context,

                    "track_health": track_health,

                    "registry_connected": (
                        registry is not None
                    ),

                    "registry": registry_state,

                    "compute_brain_connected": (
                        compute_brain is not None
                    ),

                    "compute_brain": compute_state,
                }

            else:

                self.logger.warning(
                    "[QbitDialer] Unknown channel command | "
                    "channel=%s | command=%s",
                    channel,
                    cmd,
                )

                return False

        except Exception:

            self.logger.exception(
                "[QbitDialer] Channel control failed | "
                "channel=%s | command=%s",
                channel,
                cmd,
            )

            return False

        # ======================================================
        # 14. SYNCHRONIZE AUTHORITATIVE QBIT QUEUE LOOP
        #
        # Notification only.
        #
        # QueueLoop owns execution.
        # ======================================================

        try:

            sync_method = getattr(
                queue_loop,
                "sync_channel_state",
                None,
            )

            if callable(
                sync_method
            ):

                sync_result = sync_method(
                    channel=channel,
                    command=cmd,
                )

                if inspect.isawaitable(
                    sync_result
                ):

                    self.logger.warning(
                        "[QbitDialer] QueueLoop channel "
                        "sync returned awaitable | "
                        "QueueLoop owns async execution"
                    )

        except Exception:

            self.logger.exception(
                "[QbitDialer] QueueLoop channel "
                "synchronization failed | "
                "channel=%s | command=%s",
                channel,
                cmd,
            )

            return False

        # ======================================================
        # 15. UPDATE COMPUTEBRAIN CHANNEL CONTEXT
        #
        # No computation is started here.
        #
        # We only preserve the same authoritative channel
        # identity for the next cognitive process().
        # ======================================================

        if compute_brain is not None:

            try:

                compute_brain.last_channel_id = (
                    channel
                )

                compute_state[
                    "last_channel_id"
                ] = channel

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ComputeBrain channel "
                    "state update skipped",
                    exc_info=True,
                )

        # ======================================================
        # 16. EVENT PAYLOAD
        #
        # This event is telemetry/state synchronization.
        # It is NOT a command execution event.
        # ======================================================

        payload = {

            "type": "QBIT_CHANNEL_CONTROL",

            "channel": channel,

            "command": cmd,

            "state_changed": state_changed,

            "flow_changed": flow_changed,

            "qbit_connected": (
                qbit is not None
            ),

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit_health": qbit_health,

            "queue_loop_connected": True,

            "queue_health": queue_health,

            "track_system_connected": (
                track_system is not None
            ),

            "track_context": track_context,

            "track_health": track_health,

            "registry_connected": (
                registry is not None
            ),

            "registry": registry_state,

            "compute_brain_connected": (
                compute_brain is not None
            ),

            "compute_brain": compute_state,

            "authority": "QbitDialer",

            "queue_authority": "QbitQueueLoop",

            "track_authority": "TrackSystem",

            "registry_authority": "SRegistry",

            "cognitive_authority": "ComputeBrain",

        }

        # ======================================================
        # 17. EMIT CHANNEL STATE
        # ======================================================

        try:

            emit = getattr(
                event_bus,
                "emit",
                None,
            )

            if callable(
                emit
            ):

                emit(
                    "QBIT_CHANNEL_CONTROL",
                    payload,
                )

        except Exception:

            self.logger.exception(
                "[QbitDialer] Failed to emit "
                "channel control event"
            )

        # ======================================================
        # 18. FINAL RESULT
        # ======================================================

        self.logger.info(
            "[QbitDialer] Channel control | "
            "channel=%s | command=%s | "
            "queue_loop=CONNECTED | "
            "track_system=%s | "
            "registry=%s | "
            "compute_brain=%s",
            channel,
            cmd,
            track_system is not None,
            registry is not None,
            compute_brain is not None,
        )

        return {

            "ok": True,

            "channel": channel,

            "command": cmd,

            "state_changed": state_changed,

            "flow_changed": flow_changed,

            "qbit_connected": (
                qbit is not None
            ),

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit_health": qbit_health,

            "queue_loop_connected": True,

            "queue_health": queue_health,

            "track_system_connected": (
                track_system is not None
            ),

            "track_context": track_context,

            "track_health": track_health,

            "registry_connected": (
                registry is not None
            ),

            "registry": registry_state,

            "compute_brain_connected": (
                compute_brain is not None
            ),

            "compute_brain": compute_state,

            "authority": "QbitDialer",

        }
    # ==========================================================
    # QBIT COGNITIVE BRAIN PROCESSING
    #
    # QbitQueueLoop
    #       |
    #       v
    #   Qbit data
    #       |
    #       v
    #   QbitDialer
    #       |
    #       +--> ComputeBrain
    #       |       |
    #       |       +--> decode
    #       |       +--> decrypt
    #       |       +--> extract
    #       |       +--> normalize
    #       |       +--> classify
    #       |       +--> identify source/channel/track
    #       |       +--> label
    #       |       +--> organize
    #       |
    #       +--> TransformerBrain
    #       |       |
    #       |       +--> transform
    #       |       +--> correlate
    #       |       +--> analyze
    #       |       +--> learn
    #       |       +--> adapt
    #       |
    #       +--> IntentEngine
    #       |
    #       +--> AnalyticsEngine
    #       |
    #       +--> Qbit health / flags
    #       |
    #       v
    #   command / cognition result
    #
    # IMPORTANT:
    #   This is NOT a second Qbit queue loop.
    #   This method NEVER consumes QbitQueueLoop.queue.
    #   QbitQueueLoop remains the sole transport/consumer.
    #
    # QbitDialer owns the cognitive processing of delivered Qbit
    # data and remains the command authority.
    # ==========================================================

    async def brain_loop(self):

        self.logger.info(
            "[QbitDialer] Cognitive brain processing ONLINE"
        )

        self._brain_running = True
        last_key = getattr(self, "_brain_last_processed_key", None)

        try:
            while (
                self._running
                and self.running
                and not self.shutdown_flag.is_set()
            ):
                qbit = getattr(self, "qbit", None)
                if qbit is None:
                    await asyncio.sleep(getattr(self, "loop_interval", 0.0166667))
                    continue

                qbit_id = getattr(qbit, "qbit_id", None) or getattr(qbit, "id", None)
                track_id = getattr(qbit, "track_id", None)
                if track_id is None:
                    track = getattr(qbit, "track", None)
                    track_id = getattr(track, "track_id", track)
                pipeline_id = getattr(qbit, "pipeline_id", None)
                process_key = (id(qbit), qbit_id, track_id, pipeline_id)

                if process_key != last_key:
                    last_key = process_key
                    self._brain_last_processed_key = process_key
                    try:
                        result = await self._process_received_qbit(qbit)
                        self._last_brain_result = result
                        self.logger.debug(
                            "[QbitDialer] Brain loop routed Qbit through canonical thought loop | qbit_id=%s | track_id=%s | pipeline_id=%s",
                            qbit_id, track_id, pipeline_id,
                        )
                    except asyncio.CancelledError:
                        raise
                    except Exception:
                        self.logger.exception(
                            "[QbitDialer] Canonical brain Qbit processing failed | qbit_id=%s",
                            qbit_id,
                        )

                await asyncio.sleep(getattr(self, "loop_interval", 0.0166667))

        except asyncio.CancelledError:
            self.logger.info(
                "[QbitDialer] Cognitive brain processing cancelled"
            )
            raise
        finally:
            self._brain_running = False
            self.logger.info(
                "[QbitDialer] Cognitive brain processing OFFLINE"
            )

    def run_self_update(self):
        asyncio.run_coroutine_threadsafe(
            self._async_update(),
            self.loop
        )

    async def _async_update(self):
        summary = await self.nlp.learning_engine.summarize_knowledge()
        self._render_summary(summary)

        result = await self.qbit_instance(payload={...})

        result = await self.qbit_instance(payload={...})
# =========================================================================
      # ------------------------------------------------------
    # QBIT RECEIVE PIPELINE
    # ------------------------------------------------------

    def attach_decoder(self, decoder):
        self.decoder = decoder
    def receive(self, payload):
        qbit = payload

        # ==================================================
        # SYSTEM REFERENCES
        # ==================================================

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        registry = getattr(
            self,
            "registry",
            None,
        )

        if registry is None:
            registry = globals().get(
                "SEED_KERNEL_REGISTRY",
                None,
            )

        track_system = getattr(
            self,
            "track_system",
            None,
        )

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        transformer = getattr(
            self,
            "transformer_brain",
            None,
        )

        ethics = getattr(
            self,
            "ethics",
            None,
        )

        if ethics is None:
            ethics = getattr(
                self,
                "ethics_manager",
                None,
            )

        # ==================================================
        # DECODE
        # ==================================================

        if self.decoder:

            try:

                decoded = self.decoder.decode(
                    payload
                )

                # --------------------------------------------------
                # Support async decoder without changing receive()
                # --------------------------------------------------

                if hasattr(
                    decoded,
                    "__await__",
                ):

                    try:

                        loop = getattr(
                            self,
                            "loop",
                            None,
                        )

                        if loop is None:
                            import asyncio

                            loop = asyncio.new_event_loop()

                            try:
                                decoded = (
                                    loop.run_until_complete(
                                        decoded
                                    )
                                )
                            finally:
                                loop.close()

                        elif loop.is_running():

                            self._flag(
                                "ASYNC_DECODE_REQUIRES_ASYNC_RECEIVE",
                                RuntimeError(
                                    "Decoder returned awaitable while "
                                    "QbitDialer loop is already running"
                                ),
                                "QBIT-UNKNOWN",
                            )

                            return False

                        else:

                            decoded = (
                                loop.run_until_complete(
                                    decoded
                                )
                            )

                    except Exception as e:

                        self._flag(
                            "DECODE_ERROR",
                            e,
                            "QBIT-UNKNOWN",
                        )

                        return False

                if decoded is not None:
                    qbit = decoded

            except Exception as e:

                try:

                    if event_bus:

                        event_bus.emit(
                            "SYSTEM_WARNING",
                            {
                                "source": "QbitDialer",
                                "stage": "decode",
                                "error": str(e),
                            },
                        )

                except Exception:
                    pass

                return False

        # ==================================================
        # TRACK IDENTIFICATION
        # ==================================================

        track = getattr(
            qbit,
            "track",
            {},
        )

        if isinstance(
            track,
            dict,
        ):

            track_id = track.get(
                "track_id",
                getattr(
                    qbit,
                    "track_id",
                    "QBIT-UNKNOWN",
                ),
            )

        else:

            track_id = getattr(
                track,
                "track_id",
                getattr(
                    qbit,
                    "track_id",
                    "QBIT-UNKNOWN",
                ),
            )

        if not track_id:
            track_id = "QBIT-UNKNOWN"

        # ==================================================
        # QBIT ID / TASK / PIPELINE
        # ==================================================

        qbit_id = getattr(
            qbit,
            "qbit_id",
            None,
        )

        if qbit_id is None and isinstance(
            qbit,
            dict,
        ):

            qbit_id = qbit.get(
                "qbit_id",
                qbit.get(
                    "id",
                    None,
                ),
            )

        task_id = getattr(
            qbit,
            "task_id",
            None,
        )

        if task_id is None and isinstance(
            qbit,
            dict,
        ):

            task_id = qbit.get(
                "task_id",
            )

        pipeline_id = getattr(
            qbit,
            "pipeline_id",
            None,
        )

        if pipeline_id is None and isinstance(
            qbit,
            dict,
        ):

            pipeline_id = qbit.get(
                "pipeline_id",
            )

        # ==================================================
        # TRACK SYSTEM BINDING
        #
        # Observation/context only.
        # TrackSystem does not receive command authority.
        # ==================================================

        track_context = None

        if track_system is not None:

            try:

                getter = getattr(
                    track_system,
                    "get_track_context",
                    None,
                )

                if callable(getter):

                    track_context = getter(
                        track_id
                    )

                else:

                    getter = getattr(
                        track_system,
                        "get_track",
                        None,
                    )

                    if callable(getter):

                        track_context = getter(
                            track_id
                        )

            except Exception as e:

                self._flag(
                    "TRACK_CONTEXT_ERROR",
                    e,
                    track_id,
                )

        # ==================================================
        # REGISTRY OBSERVATION
        #
        # SRegistry remains discovery/identity authority.
        # It does not execute commands.
        # ==================================================

        registry_context = None

        if registry is not None:

            try:

                for method_name in (
                    "get_state",
                    "get_status",
                    "snapshot",
                ):

                    getter = getattr(
                        registry,
                        method_name,
                        None,
                    )

                    if callable(getter):

                        try:

                            registry_context = getter()
                            break

                        except TypeError:

                            try:

                                registry_context = getter(
                                    qbit_id
                                )

                                break

                            except Exception:
                                continue

            except Exception as e:

                self._flag(
                    "REGISTRY_CONTEXT_ERROR",
                    e,
                    track_id,
                )

        # ==================================================
        # COMPUTE BRAIN
        #
        # Qbit
        #   â†“
        # ComputeBrain
        #   â†“
        # ThoughtPacket
        # ==================================================

        thought = qbit

        if compute_brain is not None:

            try:

                # Keep authoritative system references synchronized.
                try:

                    if getattr(
                        compute_brain,
                        "track_system",
                        None,
                    ) is None:

                        compute_brain.track_system = (
                            track_system
                        )

                except Exception:
                    pass

                try:

                    if getattr(
                        compute_brain,
                        "registry",
                        None,
                    ) is None:

                        compute_brain.registry = (
                            registry
                        )

                except Exception:
                    pass

                try:

                    if getattr(
                        compute_brain,
                        "event_bus",
                        None,
                    ) is None:

                        compute_brain.event_bus = (
                            event_bus
                        )

                except Exception:
                    pass

                try:

                    compute_brain.current_qbit = qbit

                except Exception:
                    pass

                try:

                    compute_brain.current_qbit_id = (
                        qbit_id
                    )

                except Exception:
                    pass

                try:

                    compute_brain.current_track_id = (
                        track_id
                    )

                except Exception:
                    pass

                # --------------------------------------------------
                # Primary ComputeBrain interface
                # --------------------------------------------------

                processor = getattr(
                    compute_brain,
                    "process",
                    None,
                )

                if callable(processor):

                    thought = processor(
                        qbit
                    )

                else:

                    processor = getattr(
                        compute_brain,
                        "compute",
                        None,
                    )

                    if callable(processor):

                        thought = processor(
                            qbit
                        )

            except Exception as e:

                self._flag(
                    "COMPUTE_BRAIN_ERROR",
                    e,
                    track_id,
                )

                return False

        # ==================================================
        # TRANSFORMER BRAIN
        #
        # ThoughtPacket
        #   â†“
        # TransformerBrain
        #   â†“
        # CognitiveResult
        # ==================================================

        analysis = thought

        if transformer is not None:

            try:

                analyzer = getattr(
                    transformer,
                    "analyze",
                    None,
                )

                if callable(analyzer):

                    analysis = analyzer(
                        thought
                    )

                else:

                    analyzer = getattr(
                        transformer,
                        "compute",
                        None,
                    )

                    if callable(analyzer):

                        analysis = analyzer(
                            thought
                        )

            except Exception as e:

                self._flag(
                    "TRANSFORMER_BRAIN_ERROR",
                    e,
                    track_id,
                )

                return False

        # ==================================================
        # COGNITIVE CONTEXT
        #
        # Preserve the SAME Qbit as the carrier.
        #
        # No replacement Qbit is created.
        # ==================================================

        cognitive_context = {
            "qbit_id": qbit_id,
            "task_id": task_id,
            "track_id": track_id,
            "pipeline_id": pipeline_id,
            "compute_brain": (
                compute_brain is not None
            ),
            "transformer_brain": (
                transformer is not None
            ),
            "track_system": (
                track_system is not None
            ),
            "registry": (
                registry is not None
            ),
            "track_context": track_context,
            "registry_context": registry_context,
            "thought": thought,
            "analysis": analysis,
        }

        # ==================================================
        # QBIT CONTEXT ATTACHMENT
        #
        # Ethics / cognitive / learning state travels
        # with this SAME Qbit through the cycle.
        # ==================================================

        def _qbit_get(name, default=None):

            if isinstance(
                qbit,
                dict,
            ):

                return qbit.get(
                    name,
                    default,
                )

            return getattr(
                qbit,
                name,
                default,
            )

        def _qbit_set(name, value):

            try:

                if isinstance(
                    qbit,
                    dict,
                ):

                    qbit[name] = value
                    return True

                setattr(
                    qbit,
                    name,
                    value,
                )

                return True

            except Exception as e:

                self._flag(
                    "QBIT_CONTEXT_ATTACH_ERROR",
                    e,
                    track_id,
                )

                return False

        existing_cognitive_context = (
            _qbit_get(
                "cognitive_context",
                {},
            )
        )

        if not isinstance(
            existing_cognitive_context,
            dict,
        ):

            existing_cognitive_context = {}

        existing_cognitive_context.update(
            cognitive_context
        )

        _qbit_set(
            "cognitive_context",
            existing_cognitive_context,
        )

        # ==================================================
        # INSTRUCTIONS
        # ==================================================

        instructions = self._decode_instructions(
            analysis
        )

        # ==================================================
        # ETHICS COGNITIVE GATE
        #
        # Ethics observes/governs the cognitive result.
        #
        # Ethics does NOT:
        # - execute commands
        # - enqueue commands
        # - create Qbits
        # - create workers
        # - bypass QbitDialer
        #
        # QbitDialer remains the ONLY command authority.
        # ==================================================

        ethics_decision = None
        ethics_context = None
        learning_context = None
        ethics_allowed = True

        if ethics is not None:

            try:

                evaluator = getattr(
                    ethics,
                    "evaluate_cognitive_cycle",
                    None,
                )

                if callable(evaluator):

                    ethics_result = evaluator(
                        qbit=qbit,
                        thought=thought,
                        transform=analysis,
                        intent=None,
                        action=None,
                        command=None,
                        metadata={
                            "source": "QbitDialer.receive",
                            "qbit_id": qbit_id,
                            "task_id": task_id,
                            "track_id": track_id,
                            "pipeline_id": pipeline_id,
                            "track_context": track_context,
                            "registry_context": registry_context,
                        },
                    )

                    if isinstance(
                        ethics_result,
                        dict,
                    ):

                        ethics_decision = (
                            ethics_result.get(
                                "decision",
                                ethics_result.get(
                                    "ethics_decision",
                                ),
                            )
                        )

                        ethics_context = (
                            ethics_result.get(
                                "ethics_context",
                            )
                        )

                        learning_context = (
                            ethics_result.get(
                                "learning_context",
                            )
                        )

                    else:

                        ethics_decision = (
                            ethics_result
                        )

                        ethics_context = getattr(
                            ethics_result,
                            "ethics_context",
                            None,
                        )

                        learning_context = getattr(
                            ethics_result,
                            "learning_context",
                            None,
                        )

                    # --------------------------------------------------
                    # Normalize decision state without assuming a
                    # specific EthicsDecision implementation.
                    # --------------------------------------------------

                    if isinstance(
                        ethics_decision,
                        dict,
                    ):

                        ethics_allowed = (
                            ethics_decision.get(
                                "allowed",
                                True,
                            )
                            is not False
                        )

                    elif ethics_decision is not None:

                        ethics_allowed = (
                            getattr(
                                ethics_decision,
                                "allowed",
                                True,
                            )
                            is not False
                        )

                    # --------------------------------------------------
                    # Preserve governance context on SAME Qbit.
                    # --------------------------------------------------

                    if ethics_context is not None:

                        _qbit_set(
                            "ethics_context",
                            ethics_context,
                        )

                    if learning_context is not None:

                        _qbit_set(
                            "learning_context",
                            learning_context,
                        )

                else:

                    # EthicsManager is not yet exposing the cognitive
                    # gate. Do not invent a second policy path.
                    ethics_allowed = True

            except Exception as e:

                self._flag(
                    "ETHICS_COGNITIVE_GATE_ERROR",
                    e,
                    track_id,
                )

                # Fail closed for an explicitly bound EthicsManager.
                ethics_allowed = False

        # ==================================================
        # COGNITIVE COMMAND CONSTRUCTION
        #
        # Do NOT manually execute the transformed result.
        #
        # TransformerBrain
        #       â†“
        # EthicsManager
        #       â†“
        # _build_cognitive_command()
        #       â†“
        # submit_command()
        #       â†“
        # command_queue
        #       â†“
        # _process_command_plane()
        #       â†“
        # authoritative execution
        # ==================================================

        cognitive_command = None

        if ethics_allowed:

            try:

                builder = getattr(
                    self,
                    "_build_cognitive_command",
                    None,
                )

                if callable(builder):

                    cognitive_command = builder(
                        qbit=qbit,
                        compute_result=thought,
                        transform_result=analysis,
                    )

            except TypeError:

                # Compatibility with builders whose current
                # signature does not expose qbit explicitly.
                try:

                    cognitive_command = builder(
                        compute_result=thought,
                        transform_result=analysis,
                    )

                except Exception as e:

                    self._flag(
                        "COGNITIVE_COMMAND_BUILD_ERROR",
                        e,
                        track_id,
                    )

            except Exception as e:

                self._flag(
                    "COGNITIVE_COMMAND_BUILD_ERROR",
                    e,
                    track_id,
                )

        # ==================================================
        # ACTIONABLE COMMAND SUBMISSION
        #
        # QbitDialer remains the ONLY command authority.
        # ==================================================

        command_submitted = False

        if (
            ethics_allowed
            and cognitive_command is not None
        ):

            try:

                submitter = getattr(
                    self,
                    "submit_command",
                    None,
                )

                if callable(submitter):

                    result = submitter(
                        cognitive_command
                    )

                    command_submitted = (
                        result is not False
                    )

            except Exception as e:

                self._flag(
                    "COGNITIVE_COMMAND_SUBMIT_ERROR",
                    e,
                    track_id,
                )

        # ==================================================
        # FALLBACK INSTRUCTION SUBMISSION
        #
        # Only used when:
        #   1. Ethics allows the cycle
        #   2. Cognitive builder did not produce a command
        #   3. Decoded instructions exist
        # ==================================================

        if (
            ethics_allowed
            and not command_submitted
            and instructions
        ):

            try:

                submitter = getattr(
                    self,
                    "submit_command",
                    None,
                )

                if callable(submitter):

                    if isinstance(
                        instructions,
                        dict,
                    ):

                        result = submitter(
                            instructions
                        )

                        command_submitted = (
                            result is not False
                        )

            except Exception as e:

                self._flag(
                    "INSTRUCTION_COMMAND_SUBMIT_ERROR",
                    e,
                    track_id,
                )

        # ==================================================
        # ETHICS DENIAL TELEMETRY
        # ==================================================

        if (
            ethics is not None
            and not ethics_allowed
        ):

            try:

                if event_bus is not None:

                    event_bus.emit(
                        "QBIT_ETHICS_DENIED",
                        {
                            "source": "QbitDialer",
                            "authority": "QbitDialer",
                            "qbit_id": qbit_id,
                            "task_id": task_id,
                            "track_id": track_id,
                            "pipeline_id": pipeline_id,
                            "decision": (
                                ethics_decision.to_dict()
                                if hasattr(
                                    ethics_decision,
                                    "to_dict",
                                )
                                else ethics_decision
                            ),
                        },
                    )

            except Exception:
                pass

        # ==================================================
        # RESULT TELEMETRY
        # ==================================================

        try:

            self._emit_result(
                qbit=qbit,
                instructions=instructions,
                track_id=track_id,
            )

        except Exception as e:

            self._flag(
                "RESULT_EMIT_ERROR",
                e,
                track_id,
            )

        # ==================================================
        # COGNITIVE TELEMETRY
        # ==================================================

        try:

            if event_bus is not None:

                event_bus.emit(
                    "QBIT_COGNITIVE_RESULT",
                    {
                        "source": "QbitDialer",
                        "authority": "QbitDialer",
                        "qbit_id": qbit_id,
                        "task_id": task_id,
                        "track_id": track_id,
                        "pipeline_id": pipeline_id,
                        "compute_brain": (
                            compute_brain is not None
                        ),
                        "transformer_brain": (
                            transformer is not None
                        ),
                        "track_system": (
                            track_system is not None
                        ),
                        "registry": (
                            registry is not None
                        ),
                        "ethics": (
                            ethics is not None
                        ),
                        "ethics_allowed": (
                            ethics_allowed
                        ),
                        "command_built": (
                            cognitive_command is not None
                        ),
                        "command_submitted": (
                            command_submitted
                        ),
                    },
                )

        except Exception:
            pass

        # ==================================================
        # RESULT
        # ==================================================

        return analysis
    # ------------------------------------------------------
    # INTERNAL HELPERS
    # ------------------------------------------------------

    def _decode_instructions(self, qbit):

        decoder = self.instruction_decoder

        if hasattr(
            decoder,
            "decode",
        ):

            result = decoder.decode(
                qbit
            )

            if hasattr(
                result,
                "__await__",
            ):

                return self.loop.run_until_complete(
                    result
                )

            return result

        return []

    def _emit_result(
        self,
        *,
        qbit,
        instructions,
        track_id,
    ):

        payload = {
            "track_id": track_id,
            "qbit_state": getattr(
                qbit,
                "state",
                None,
            ),
            "payload": getattr(
                qbit,
                "payload",
                None,
            ),
            "flags": getattr(
                qbit,
                "flags",
                {},
            ),
            "instructions": instructions,
        }

        if self.event_bus:

            self.event_bus.publish(
                "QBIT_RESULT",
                payload=payload,
                source="QbitDialer",
            )

    def _flag(
        self,
        key,
        error,
        track_id,
    ):

        try:

            if self.event_bus:

                self.event_bus.publish(
                    "QBIT_WARNING",
                    payload={
                        "track_id": track_id,
                        "flag": key,
                        "error": str(error),
                    },
                    source="QbitDialer",
                )

        except Exception:
            pass

# =================================================================
# [SELF-HEAL CONTRACT]
# Adaptive multiplier MUST accept evolving state labels.
# Order of preference: intent â†’ analytics â†’ chaos â†’ neutral default.
# This prevents boot failure when modules are disabled or renamed.


# =====================================================================
# [SELF-HEAL CONTRACT]
# PRESSURE MODEL
#
# Returns normalized system pressure:
#   0.00 -> 1.00
#
# 0.00 = normal / minimal pressure
# 1.00 = critical / survival pressure
#
# Boot-safe:
# - Never assumes HealthMonitor exists
# - Never assumes SystemMonitor is ready
# - Never creates modules
# - Never starts threads
# - Never emits events
# - Never raises because an optional subsystem is unavailable
# =====================================================================

    def _pressure_level(self):

        def _safe_number(value, default=0.0):
            try:
                value = float(value)
            except (TypeError, ValueError):
                return default

            if value != value:       # NaN
                return default

            return max(0.0, min(value, 1.0))

        # ---------------------------------------------------------------
        # 1. SYSTEM / RESOURCE PRESSURE
        # ---------------------------------------------------------------
        system_pressure = 0.0

        try:
            if callable(getattr(self, "_system_load", None)):
                system_pressure = _safe_number(self._system_load())
        except Exception:
             system_pressure = 0.0

        # ---------------------------------------------------------------
        # 2. QBIT / BUFFER / CHAOS PRESSURE
        # ---------------------------------------------------------------
        chaos_pressure = 0.0

        try:
            if callable(getattr(self, "_chaos", None)):
                chaos_pressure = _safe_number(self._chaos())
            else:
                buffer_value = len(getattr(self, "qbit_buffer", []))
                buffer_limit = max(
                    int(getattr(self, "buffer_limit", 1) or 1),
                    1
                )
                chaos_pressure = _safe_number(
                    buffer_value / buffer_limit
                )
        except Exception:
            chaos_pressure = 0.0

        # ---------------------------------------------------------------
        # 3. HEALTH PRESSURE
        # ---------------------------------------------------------------
        health_pressure = 0.0

        try:
            health = getattr(self, "healthmonitor", None)

            if health is not None:
                loader = getattr(health, "load", None)

                if callable(loader):
                    health_value = loader()

                    # Health APIs may evolve.
                    # Accept numeric, dict, or unknown values.
                    if isinstance(health_value, (int, float)):
                        health_pressure = _safe_number(health_value)

                    elif isinstance(health_value, dict):
                        for key in (
                            "pressure",
                            "load",
                            "stress",
                            "health_pressure"
                        ):
                            if key in health_value:
                                health_pressure = _safe_number(
                                    health_value.get(key)
                                ) 
                                break
        except Exception:
            health_pressure = 0.0

        # ---------------------------------------------------------------
        # 4. COGNITIVE / INTENT PRESSURE
        # ---------------------------------------------------------------
        cognitive_pressure = 0.0

        try:
            candidates = (
                getattr(self, "confidence", None),
                getattr(self, "success_rate", None),
            )

            values = [
                _safe_number(v)
                for v in candidates
                if isinstance(v, (int, float))
            ]
            
            if values:
                # Lower confidence / success means greater pressure.
                confidence_values = [
                    1.0 - v for v in values
                ]
                cognitive_pressure = _safe_number(
                    sum(confidence_values) / len(confidence_values)
                )

            # Explicit intent state can override/augment the signal.
            intent_engine = getattr(self, "intent_engine", None)

            if isinstance(intent_engine, dict):
                for key in (
                    "pressure",
                    "stress",
                    "load",
                    "intent_pressure"
                ):
                    if key in intent_engine:
                        cognitive_pressure = max(
                            cognitive_pressure,
                            _safe_number(intent_engine.get(key))
                        )
                        break

        except Exception:
            cognitive_pressure = 0.0

    # ---------------------------------------------------------------
    # 5. COMPOSITE PRESSURE
    #
    # Resource pressure is important, but not dominant.
    # Queue/chaos pressure matters because backlog can exist even
    # when CPU is low.
    # Health and cognition represent system-level strain.
    # ---------------------------------------------------------------
        pressure = (
            (system_pressure * 0.30) +
            (chaos_pressure * 0.25) +
            (health_pressure * 0.25) +
            (cognitive_pressure * 0.20)
        )

        return _safe_number(pressure)


# =====================================================================
# [SELF-HEAL CONTRACT]
# SYSTEM LOAD
#
# Provides a stable callable interface for QbitDialer analytics.
#
# The underlying monitoring implementation may evolve, but callers
# should always receive a normalized 0.0 -> 1.0 value.
# =====================================================================

    def _system_load(self):

        def _safe_number(value, default=0.0):
            try:
                value = float(value)
            except (TypeError, ValueError):
                return default
 
            if value != value:  # NaN
                return default
   
            return max(0.0, min(value, 1.0))

        # ---------------------------------------------------------------
        # Preferred source: explicitly preserved HealthMonitor
        # ---------------------------------------------------------------
        monitor = getattr(self, "_health_monitor_source", None)

        if monitor is not None:
            try:
                loader = getattr(monitor, "load", None)

                if callable(loader):
                    value = loader()

                    if isinstance(value, (int, float)):
                        return _safe_number(value)

                    if isinstance(value, dict):
                        for key in (
                            "load",
                            "system_load",
                            "pressure",
                            "health_load",
                        ):
                            if key in value:
                                return _safe_number(value[key])

            except Exception:
                pass

        # ---------------------------------------------------------------
        # Secondary source: system_monitor
        # ---------------------------------------------------------------
        monitor = getattr(self, "system_monitor", None)

        if monitor is not None:
            try:
                loader = getattr(monitor, "load", None)

                if callable(loader):
                    value = loader()

                    if isinstance(value, (int, float)):
                        return _safe_number(value)

                    if isinstance(value, dict):
                        for key in (
                            "load",
                            "system_load",
                            "cpu",
                            "pressure",
                        ):
                            if key in value:
                                return _safe_number(value[key])

            except Exception:
                pass

    # ---------------------------------------------------------------
    # Conservative fallback
    # ---------------------------------------------------------------
        return 0.0


        print("\n[PRESSURE DEBUG]")
        print("_pressure_level:", getattr(self, "_pressure_level", None))
        print("_pressure_level type:", type(getattr(self, "_pressure_level", None)))
        print("_pressure_level callable:", callable(getattr(self, "_pressure_level", None)))

        print("_system_load:", getattr(self, "_system_load", None))
        print("_system_load type:", type(getattr(self, "_system_load", None)))
        print("_system_load callable:", callable(getattr(self, "_system_load", None)))

        print("healthmonitor:", getattr(self, "healthmonitor", None))
        print("healthmonitor type:", type(getattr(self, "healthmonitor", None)))
        print("healthmonitor callable:", callable(getattr(self, "healthmonitor", None)))

        print("system_monitor:", getattr(self, "system_monitor", None))
        print("system_monitor type:", type(getattr(self, "system_monitor", None)))
        print("system_monitor callable:", callable(getattr(self, "system_monitor", None)))
        print("[END PRESSURE DEBUG]\n")

        return (self._pressure_level() + self._system_load()) / 2




    def _chaos(self):
        return len(self.qbit_buffer) / max(self.buffer_limit, 1)

    def _healthmonitor(self):
        return self.healthmonitor.load()

    def _analylitics(self):
        return (self._pressure_level() + self._system_load()) / 2

    def _adaptive_multiplier(self, state):
        analylitics = (
            state.get("intent")
            or state.get("analylitics")
            or state.get("chaos")
            or 0.5
        )
        if analylitics < 0.3:
            return 1.25
        elif analylitics < 0.6:
            return 1.0
        elif analylitics < 0.85:
            return 0.75
        else:
            return 0.5

    def _release_to_core(self, qbit):
        self.event_bus.emit("QBIT", qbit)

    def system_monitor(self):
        return self._system_monitor
 

# ----------------------------------------------------------------------

     # -------------------------------------------------------------------------
    # === PHASE 1: WIRE MODULES
    # -------------------------------------------------------------------------

    def attach_event_bus(self, event_bus):

        # ------------------------------------------------------
        # Guard against missing EventBus
        # ------------------------------------------------------
        if event_bus is None:
            self.logger.warning(
                "[QbitDialer] EventBus attachment skipped | "
                "event_bus=None"
            )
            return False

        # ------------------------------------------------------
        # Compatibility:
        #
        # If a bound method such as:
        #
        #     event_bus.emit
        #
        # was accidentally supplied, recover the owning EventBus.
        #
        # A bare function cannot be safely promoted to an EventBus.
        # ------------------------------------------------------
        original_event_bus = event_bus

        if callable(event_bus) and not hasattr(event_bus, "emit"):
            owner = getattr(
                event_bus,
                "__self__",
                None,
            )

            if owner is not None and callable(
                getattr(owner, "emit", None)
            ):
                event_bus = owner

                self.logger.warning(
                    "[QbitDialer] EventBus compatibility recovery | "
                    "received bound emit() instead of EventBus object"
                )

            else:
                self.logger.warning(
                    "[QbitDialer] EventBus attachment rejected | "
                    "received callable without EventBus owner | "
                    "type=%s",
                    type(original_event_bus).__name__,
                )
                return False

        # ------------------------------------------------------
        # Validate EventBus object
        # ------------------------------------------------------
        emit_method = getattr(
            event_bus,
            "emit",
            None,
        )

        if not callable(emit_method):
            self.logger.warning(
                "[QbitDialer] EventBus attachment rejected | "
                "missing callable emit() | "
                "type=%s",
                type(event_bus).__name__,
            )
            return False

        # ------------------------------------------------------
        # Validate subscription interface
        # ------------------------------------------------------
        subscribe = getattr(
            event_bus,
            "subscribe",
            None,
        )

        if subscribe is not None and not callable(subscribe):
            self.logger.warning(
                "[QbitDialer] EventBus subscribe rejected | "
                "subscribe is not callable"
            )
            subscribe = None

        # ------------------------------------------------------
        # Detect replacement of an existing EventBus
        # ------------------------------------------------------
        previous_event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if (
            previous_event_bus is not None
            and previous_event_bus is not event_bus
        ):
            self.logger.warning(
                "[QbitDialer] EventBus replacement | "
                "old=%s | new=%s",
                type(previous_event_bus).__name__,
                type(event_bus).__name__,
            )

        # ------------------------------------------------------
        # Store authoritative EventBus
        # ------------------------------------------------------
        self.event_bus = event_bus

        # ------------------------------------------------------
        # Bind local emit to authoritative EventBus
        # ------------------------------------------------------
        self.emit = emit_method

        # ------------------------------------------------------
        # Initialize wiring state
        # ------------------------------------------------------
        if not hasattr(
            self,
            "_event_bus_subscriptions",
        ):
            self._event_bus_subscriptions = set()

        # ------------------------------------------------------
        # Safe subscription helper
        # ------------------------------------------------------
        def _subscribe_once(
            event_name,
            handler,
        ):
            if subscribe is None:
                return False

            if not callable(handler):
                self.logger.debug(
                    "[QbitDialer] Subscription skipped | "
                    "event=%s | handler unavailable",
                    event_name,
                )
                return False

            subscription_key = (
                id(event_bus),
                event_name,
                getattr(
                    handler,
                    "__name__",
                    repr(handler),
                ),
            )

            if subscription_key in self._event_bus_subscriptions:
                return True

            try:
                subscribe(
                    event_name,
                    handler,
                )

                self._event_bus_subscriptions.add(
                    subscription_key
                )

                self.logger.debug(
                    "[QbitDialer] EventBus subscription active | "
                    "event=%s",
                    event_name,
                )

                return True

            except Exception:
                self.logger.debug(
                    "[QbitDialer] EventBus subscription unavailable | "
                    "event=%s",
                    event_name,
                    exc_info=True,
                )
                return False

        # ------------------------------------------------------
        # Qbit command-plane subscription
        # ------------------------------------------------------
        _subscribe_once(
            "qbit.execute",
            getattr(
                self,
                "on_qbit_execute",
                None,
            ),
        )

        # ------------------------------------------------------
        # Heartbeat control-plane subscription
        # ------------------------------------------------------
        _subscribe_once(
            "HEARTBEAT",
            getattr(
                self,
                "_on_heartbeat",
                None,
            ),
        )

        # ------------------------------------------------------
        # Audio callback
        # ------------------------------------------------------
        audio = getattr(
            self,
            "audio",
            None,
        )

        push_data = getattr(
            self,
            "push_data",
            None,
        )

        register_callback = getattr(
            audio,
            "register_qbit_callback",
            None,
        )

        if (
            callable(register_callback)
            and callable(push_data)
        ):
            try:
                callback_key = (
                    id(audio),
                    id(push_data),
                )

                if not hasattr(
                    self,
                    "_audio_callbacks_registered",
                ):
                    self._audio_callbacks_registered = set()

                if callback_key not in (
                    self._audio_callbacks_registered
                ):
                    register_callback(
                        push_data
                    )

                    self._audio_callbacks_registered.add(
                        callback_key
                    )

                    self.logger.debug(
                        "[QbitDialer] Audio Qbit callback attached"
                    )

            except Exception:
                self.logger.debug(
                    "[QbitDialer] Audio Qbit callback "
                    "registration unavailable",
                    exc_info=True,
                )

        # ------------------------------------------------------
        # Final authoritative state
        # ------------------------------------------------------
        self._event_bus_attached = True

        self.logger.info(
            "[QbitDialer] EventBus attached | "
            "type=%s | emit=READY | subscribe=%s",
            type(self.event_bus).__name__,
            "READY" if callable(subscribe) else "UNAVAILABLE",
        )

        return True

    async def _event_qbit_execute(self, event=None):

        payload = getattr(
            event,
            "payload",
            event,
        )

        if payload is None:
            return None

        return self.submit_command(
            payload
        )
    # -------------------------------------------------------------------------
    # === PHASE 2: BIND AUTHORITY
    # -------------------------------------------------------------------------

    def bind_authority(self):

        self.controller = globals().get(
            "qbit_channel_control"
        )

        # ------------------------------------------------------
        # Kernel hookup
        # ------------------------------------------------------
        kernel = getattr(
            self,
            "kernel",
            None,
        )

        if kernel is not None:

            register_subscription = getattr(
                kernel,
                "register_subscription",
                None,
            )

            execute_command = getattr(
                self.qbit,
                "execute_command",
                None,
            )

            if (
                callable(register_subscription)
                and callable(execute_command)
            ):
                try:
                    register_subscription(
                        "COMMAND_EXECUTE",
                        execute_command,
                    )

                    self.logger.info(
                        "[QbitDialer] Kernel command "
                        "authority bound"
                    )

                except Exception:
                    self.logger.debug(
                        "[QbitDialer] Kernel subscription "
                        "unavailable",
                        exc_info=True,
                    )

        return True





# =====================================================================
    # === PHASE: STUBS AND CALLBACKS ===

    def _qbit_dialer_emit_stub(self, event, payload=None):
        if not event:
            return False

        try:
            event = str(event).strip()
        except Exception:
            event = "UNKNOWN"

        if not event:
            return False

        if payload is None:
            payload = {}

        # ----------------------------------------------------------
        # Bounded bootstrap buffer
        # ----------------------------------------------------------
        try:
            buffer = getattr(
                self,
                "_bootstrap_events",
                None,
            )

            if buffer is None:
                buffer = deque(
                    maxlen=getattr(
                        self,
                        "bootstrap_event_limit",
                        64,
                    )
                )

                self._bootstrap_events = buffer

            buffer.append(
                (
                    event,
                    payload,
                    time.time(),
                )
            )

        except Exception:
            self.logger.debug(
                "[QbitDialer] Bootstrap event buffer unavailable",
                exc_info=True,
            )

        self.logger.debug(
            "[QbitDialer] BOOTSTRAP EMIT | event=%s",
            event,
        )

        return True

# ====================================================================
    def on_qbit_execute(
        self,
        payload=None,
    ):

        # ==========================================================
        # QBIT EXECUTION ENTRY
        #
        # Compatibility/event entry point.
        #
        # THIS METHOD DOES NOT EXECUTE COMMANDS ITSELF.
        #
        # All command execution terminates through:
        #
        #     execute_command()
        #
        # There is NO fallback to:
        #
        #     qbit.execute_command()
        #
        # ==========================================================

        if payload is None:

            payload = {}

        # ----------------------------------------------------------
        # A Qbit execution request must be a command envelope.
        #
        # Accept:
        #
        #     dict
        #     string command
        #
        # A raw Qbit object is handled by execute_command() /
        # _normalize_command() and must NOT be converted into its
        # string representation here.
        # ----------------------------------------------------------

        if not isinstance(
            payload,
            (
                dict,
                str,
            ),
        ):

            self.logger.warning(
                "[QbitDialer] Invalid Qbit execution request | "
                "type=%s",
                type(payload).__name__,
            )

            return False

        # ----------------------------------------------------------
        # Resolve the ONE authoritative executor.
        # ----------------------------------------------------------

        execute = getattr(
            self,
            "execute_command",
            None,
        )

        if not callable(
            execute
        ):

            self.logger.error(
                "[QbitDialer] AUTHORITATIVE EXECUTOR UNAVAILABLE | "
                "execute_command() is not bound to QbitDialer"
            )

            return False

        # ----------------------------------------------------------
        # Execute ONLY through QbitDialer.
        # ----------------------------------------------------------

        try:

            result = execute(
                payload
            )

            # ------------------------------------------------------
            # Preserve async execution without creating another
            # task or execution loop here.
            # ------------------------------------------------------

            if inspect.isawaitable(
                result
            ):

                return result

            return result

        except asyncio.CancelledError:

            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] Controlled Qbit execution failed"
            )

            return False

    def _complete_qbit_execution_cycle(
        self,
        *,
        payload,
        result,
        qbit_id=None,
        task_id=None,
        track_id=None,
        pipeline_id=None,
        command_name=None,
    ):

        execution_result = {
            "status": "executed",
            "stage": "execution",
            "task_id": task_id,
            "qbit_id": qbit_id,
            "track_id": track_id,
            "pipeline_id": pipeline_id,
            "command": command_name,
            "authority": "QbitDialer",
            "result": result,
        }

        self.logger.info(
            "[QbitDialer] QBIT EXECUTION COMPLETE | "
            "task_id=%s | qbit_id=%s | track_id=%s | "
            "command=%s",
            task_id,
            qbit_id,
            track_id,
            command_name,
        )

        # ==========================================================
        # EXECUTION TELEMETRY / FEEDBACK
        # ==========================================================

        try:

            self._emit_execution_feedback(
                execution_result
            )

        except Exception:

            self.logger.debug(
                "[QbitDialer] Execution feedback unavailable",
                exc_info=True,
            )

        # ==========================================================
        # EXISTING THOUGHT FEEDBACK BRIDGE
        #
        # Feedback observes the result and may prepare the next
        # cognitive cycle.
        #
        # It must NOT directly execute another command here.
        # ==========================================================

        feedback = getattr(
            self,
            "thought_feedback",
            None,
        )

        if feedback is not None:

            try:

                if hasattr(
                    feedback,
                    "record_execution_result",
                ):

                    feedback.record_execution_result(
                        execution_result
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] ThoughtFeedback update failed",
                    exc_info=True,
                )

        # Close the memory graph edge with the authoritative result.
        memory_graph = getattr(self, "memory_graph", None)
        if memory_graph is not None:
            try:
                qbit_id = (
                    execution_result.get("qbit_id")
                    or execution_result.get("task_id")
                    or getattr(self, "current_qbit_id", None)
                ) if isinstance(execution_result, dict) else None
                if qbit_id:
                    memory_graph.record_feedback(
                        qbit_id,
                        execution_result,
                        outcome=(
                            execution_result.get("status")
                            if isinstance(execution_result, dict)
                            else None
                        ),
                    )
            except Exception as exc:
                self.logger.debug("QbitMemoryGraph feedback deferred: %s", exc)

        # ==========================================================
        # ANALYTICS
        # ==========================================================

        analytics = getattr(
            self,
            "analytics_engine",
            None,
        )

        if analytics is not None:

            try:

                recorder = getattr(
                    analytics,
                    "record",
                    None,
                )

                if callable(
                    recorder
                ):

                    recorder(
                        execution_result
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Analytics execution record failed",
                    exc_info=True,
                )

        # ==========================================================
        # EVENTBUS
        # ==========================================================

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is not None:

            try:

                event_bus.emit(
                    "QBIT_EXECUTION_RESULT",
                    execution_result,
                )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Execution result EventBus emit failed",
                    exc_info=True,
                )

        return execution_result


    def _emit_execution_feedback(
        self,
        result,
    ):

        if result is None:
            return False

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:
            return False

        try:

            event_bus.emit(
                "QBIT_EXECUTION_FEEDBACK",
                result,
            )

            return True

        except Exception:

            self.logger.debug(
                "[QbitDialer] Execution feedback emit failed",
                exc_info=True,
            )

            return False

# ===================================================================
    #
    def _on_heartbeat(self, payload=None):

        now = time.monotonic()

    # ==========================================================
    # NORMALIZE PAYLOAD
    # ==========================================================
        if payload is None:
            payload = {}

        elif not isinstance(payload, dict):
            payload = {
                "value": payload
            }

    # ==========================================================
    # HEARTBEAT SEQUENCE
    # ==========================================================
        sequence = getattr(
            self,
            "_heartbeat_sequence",
            0,
        ) + 1

        self._heartbeat_sequence = sequence

        self._last_heartbeat = now
        self._last_heartbeat_payload = payload

    # ==========================================================
    # CALCULATE HEARTBEAT DELTA
    # ==========================================================
        previous = getattr(
            self,
            "_previous_heartbeat",
            None,
        )

        heartbeat_delta = None

        if previous is not None:
            heartbeat_delta = now - previous

        self._previous_heartbeat = now

    # ==========================================================
    # DETECT ABNORMAL HEARTBEAT RATE
     # ==========================================================
        if heartbeat_delta is not None:

         # Prevent a broken emitter from flooding the dialer.
            if heartbeat_delta < 0.005:

                self.logger.warning(
                    "[QbitDialer] Heartbeat rate too fast "
                    "(%.6fs) - supervisory work suppressed",
                    heartbeat_delta,
                )

                return False

    # ==========================================================
    # RUNTIME STATE
    # ==========================================================
        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        qbit_alive = bool(
            queue_loop is not None
            and not getattr(
                queue_loop,
                "shutdown_requested",
                False,
            )
        )

        # ==========================================================
        # RUNTIME STATE
        #
        # QbitQueueLoop owns the runtime.
        # QbitDialer does not own a processing task.
        # ==========================================================

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        queue_runtime_active = bool(
            queue_loop is not None
            and not getattr(
                queue_loop,
                "shutdown_requested",
                False,
            )
        )

        qbit_alive = queue_runtime_active

        running = bool(
            getattr(
                self,
                "_running",
                False,
            )
        )

    # ==========================================================
    # UPDATE HEALTH STATE
    # ==========================================================
        self._heartbeat_state = {
            "sequence": sequence,
            "timestamp": now,
            "delta": heartbeat_delta,
            "running": running,
            "qbit_task_alive": qbit_alive,
        }

    # ==========================================================
    # CONTROLLED START REQUEST
    # ==========================================================
    #
    # IMPORTANT:
    # Do NOT create the Qbit task here.
    #
    # start() owns task creation and contains the startup lock.
    #
    # The heartbeat only schedules ONE supervisor request when
    # the runtime is not already alive.
    # ==========================================================
        if not running or not qbit_alive:

        # ------------------------------------------------------
        # Prevent repeated start requests
        # ------------------------------------------------------
            start_pending = getattr(
                self,
                "_heartbeat_start_pending",
                False,
            )

            if not start_pending:

                self._heartbeat_start_pending = True

                try:
                    loop = asyncio.get_running_loop()

                    task = loop.create_task(
                        self._heartbeat_start_supervisor(),
                        name="QbitDialer.HeartbeatStart",
                    )

                    self._heartbeat_start_task = task

                    def _start_done(completed):
                        self._heartbeat_start_pending = False

                        try:
                            completed.result()

                        except asyncio.CancelledError:
                            pass

                        except Exception:
                            self.logger.exception(
                                "[QbitDialer] Heartbeat startup "
                                "supervisor failed"
                            )

                    task.add_done_callback(_start_done)

                except RuntimeError:
                # No active asyncio loop.
                #
                # Do not create threads or attempt emergency
                 # execution from the heartbeat.
                    self._heartbeat_start_pending = False

                    self.logger.debug(
                        "[QbitDialer] Heartbeat received without "
                        "active asyncio loop"
                    )

    # ==========================================================
    # PERIODIC HEARTBEAT TELEMETRY
    # ==========================================================
    #
    # Do not log every heartbeat at INFO.
    # A heartbeat may occur hundreds/thousands of times.
    #
    # Log periodically instead.
    # ==========================================================
        telemetry_interval = getattr(
            self,
            "_heartbeat_log_interval",
            5.0,
        )

        last_log = getattr(
            self,
            "_last_heartbeat_log",
            0.0,
        )

        if now - last_log >= telemetry_interval:

            self._last_heartbeat_log = now

            self.logger.debug(
                "[QbitDialer] HEARTBEAT "
                "seq=%d running=%s qbit_alive=%s delta=%s",
                sequence,
                running,
                qbit_alive,
                (
                    f"{heartbeat_delta:.4f}s"
                    if heartbeat_delta is not None
                    else "N/A"
                ),
            )

        return True

    async def _heartbeat_start_supervisor(self):

        try:

        # Small cooperative delay prevents the heartbeat callback
        # from immediately competing with the boot/runtime path.
            await asyncio.sleep(0)

            if getattr(self, "_running", False):

                qbit_task = getattr(
                    self,
                    "_qbit_task",
                    None,
                )

                if qbit_task is not None and not qbit_task.done():
                    return True

            return await self.start()

        finally:

            self._heartbeat_start_pending = False


# =========================================================
# FILE: seed/core/dialers/qbit_dialer.py
# PATCH: push_data compatibility
# PURPOSE: Preserve TrackID metadata while accepting legacy
#          and new heartbeat callers.
# AUTHORITY: QbitDialer owns Qbit input routing.
 
#    Accept machine/Qbit input plus optional tracking metadata.

#    Qbit remains the processing authority.
#    QbitDialer routes the signal; it does not reinterpret
#    the heartbeat's cognitive payload here.
 
# =========================================================


    # ----------------------------------------------------------
    # PRESERVE ADDITIONAL METADATA
    # ----------------------------------------------------------
    # Preserve any additional metadata without breaking
    # existing callers.
#    if kwargs:
#        data.update(kwargs)

    # Existing push_data body continues here.


    # ==========================================================
    # ASYNC ENGINE SHUTDOWN
    # ==========================================================

    def stop_async_engine(self):

        self._async_engine_running = False

        # ------------------------------------------------------
        # Tell the Qbit runtime to stop
        # ------------------------------------------------------
        self._qbit_running = False
        self._running = False

        # ------------------------------------------------------
        # Signal shutdown
        # ------------------------------------------------------
        shutdown_flag = getattr(
            self,
            "shutdown_flag",
            None,
        )

        if shutdown_flag is not None:
            try:
                shutdown_flag.set()
            except Exception:
                self.logger.debug(
                    "[QbitDialer] Unable to set shutdown flag",
                    exc_info=True,
                )

        # ------------------------------------------------------
        # Runtime state
        # ------------------------------------------------------
        current_state = getattr(
            self,
            "_qbit_runtime_state",
            None,
        )

        if current_state not in (
            "STOPPED",
            "ERROR",
        ):
            self._qbit_runtime_state = "STOPPING"

        self.logger.debug(
            "[QbitDialer] Async engine stop requested"
        )

        return True


    # ==========================================================
    # CALLABLE COMPATIBILITY INTERFACE
    # ==========================================================

    def __call__(
        self,
        event_type,
        payload=None,
        *args,
        **kwargs,
    ):


        try:
            # --------------------------------------------------
            # Prefer the authoritative command dispatcher
            # --------------------------------------------------
            dispatcher = getattr(
                self,
                "dispatch_command",
                None,
            )

            if callable(dispatcher):
                return dispatcher(
                    event_type,
                    payload,
                    *args,
                    **kwargs,
                )

            # --------------------------------------------------
            # Legacy execute path
            # --------------------------------------------------
            execute = getattr(
                self,
                "on_qbit_execute",
                None,
            )

            if (
                event_type == "qbit.execute"
                and callable(execute)
            ):
                return execute(
                    payload
                )

        except Exception:
            self.logger.debug(
                "[QbitDialer] Callable dispatch failed",
                exc_info=True,
            )

        # ------------------------------------------------------
        # Safe compatibility response
        # ------------------------------------------------------
        return {}

    def subscribe(self, event_name, callback=None, *args, **kwargs):

    # ==========================================================
    # NORMALIZE LEGACY CALLS
    # ==========================================================
        if callback is None and args:
            callback = args[0]

        if not event_name:
            self.logger.warning(
                "[QbitDialer] subscribe rejected | "
                "event_name missing"
            )
            return False

        event_name = str(event_name).strip()

        if not event_name:
            return False

    # ==========================================================
    # VALIDATE CALLBACK
    # ==========================================================
        if not callable(callback):
            self.logger.warning(
                "[QbitDialer] subscribe rejected | "
                "event=%s callback=%s is not callable",
                event_name,
                type(callback).__name__,
            )
            return False

    # ==========================================================
    # SUBSCRIPTION REGISTRY
    # ==========================================================
        subscribers = getattr(
            self,
            "_subscribers",
            None,
        )

        if subscribers is None:
            subscribers = {}
            self._subscribers = subscribers

        listeners = subscribers.setdefault(
            event_name,
            [],
        )

    # ==========================================================
    # DUPLICATE PROTECTION
    # ==========================================================
        if callback in listeners:

            self.logger.debug(
                "[QbitDialer] subscription already exists | "
                "event=%s callback=%s",
                event_name,
                getattr(
                    callback,
                    "__name__",
                    type(callback).__name__,
                ),
            )

            return self._make_unsubscribe(
                event_name,
                callback,
            )

    # ==========================================================
    # REGISTER
    # ==========================================================
        listeners.append(callback)

        self.logger.debug(
            "[QbitDialer] subscribed | "
            "event=%s listeners=%d callback=%s",
            event_name,
            len(listeners),
            getattr(
                callback,
                "__name__",
                type(callback).__name__,
            ),
        )

        # ==========================================================
        # RETURN UNSUBSCRIBE HANDLE
        # ==========================================================
        return self._make_unsubscribe(
            event_name,
            callback,
        )


    def _make_unsubscribe(self, event_name, callback):

        def unsubscribe():
            subscribers = getattr(
                self,
                "_subscribers",
                {},
            )

            listeners = subscribers.get(
                event_name,
                [],
            )

            try:
                listeners.remove(callback)

            except ValueError:
                return False

            if not listeners:
                subscribers.pop(
                    event_name,
                    None,
                )

            self.logger.debug(
                "[QbitDialer] unsubscribed | "
                "event=%s",
                event_name,
            )

            return True

        return unsubscribe
# =======================================================================
    def _notify_subscribers(self, event_name, payload):

        subscribers = getattr(
            self,
            "_subscribers",
            {},
        )

        listeners = list(
            subscribers.get(
                event_name,
                [],
            )
        )

        if not listeners:
            return 0

        notified = 0

        for callback in listeners:

            try:
                callback(payload)
                notified += 1

            except Exception:
                self.logger.exception(
                    "[QbitDialer] subscriber failed | "
                    "event=%s callback=%s",
                    event_name,
                    getattr(
                        callback,
                        "__name__",
                        type(callback).__name__,
                    ),
                )

        return notified

# ========================================================================


    def on_stop(self, *args, **kwargs):
        pass
# =======================================================================

# =======================================================================
    def qbit_time(self, time, qbit):
        # guard: only create task if allowed
        if not getattr(self, "_create_task", False):
            return

        self.event_bus.create_task(
            source=self.qbit,
            payload={
                "action": "run_commands",
                "time": time,
                "qbit": qbit,
            },
            on_emit=self._emit,
            on_complete=self._on_emit,
        )
    # ==========================================================
    # ASYNC FACTORY
    #
    # Creates a fully constructed instance and starts it.
    #
    # Usage:
    #     qbit = await QbitDialer.create(...)
    #
    # ==========================================================

    @classmethod
    async def create(
        cls,
        *args,
        **kwargs,
    ):

        # ------------------------------------------------------
        # CONSTRUCT INSTANCE
        # ------------------------------------------------------

        instance = cls(
            *args,
            **kwargs,
        )

        # ------------------------------------------------------
        # START INSTANCE
        # ------------------------------------------------------

        await instance.start()

        # ------------------------------------------------------
        # RETURN READY INSTANCE
        # ------------------------------------------------------

        return instance

# =======================================================================
# ==========================================================
# QBIT TASK / EXECUTION STAGING
#
# Qbit
#     = DATA / IDENTITY / LINEAGE TRANSPORT
#
# QbitQueueLoop
#     = SOLE AUTHORITATIVE QBIT PROCESSING / RUNTIME QUEUE
#    # ==========================================================
    # QBIT TASK / EXECUTION STAGING
    #
    # Qbit
    #     = DATA / IDENTITY / LINEAGE TRANSPORT
    #
    # ComputeBrain
    #     = Qbit data -> ThoughtPacket
    #
    # TransformerBrain
    #     = ThoughtPacket -> ACTIONABLE COMMAND PROPOSAL
    #
    # QbitDialer
    #     = SOLE COMMAND AUTHORITY
    #
    # submit_command()
    #     = SOLE COMMAND ADMISSION PATH
    #
    # IMPORTANT:
    #
    # This method does NOT create or replace QbitQueueLoop.
    #
    # self._tasks is ONLY Dialer-local execution staging.
    #
    # It is NOT:
    #
    #     - the QbitQueueLoop queue
    #     - a Qbit fallback queue
    #     - an asyncio runner
    #     - an independent command authority
    #     - a second execution scheduler
    #
    # The authoritative runtime path remains:
    #
    #     Qbit
    #       |
    #       v
    # QbitQueueLoop
    #       |
    #       v
    # ComputeBrain
    #       |
    #       v
    # ThoughtPacket
    #       |
    #       v
    # TransformerBrain
    #       |
    #       v
    # QbitDialer
    #       |
    #       v
    # submit_command()
    #       |
    #       v
    # QbitQueueLoop
    #
    # The Qbit object remains attached to the task so identity,
    # lineage, track, channel, generation, state and metadata are
    # never separated from the work it produced.
    #
    # ==========================================================


    def add_task(
        self,
        func,
        metadata=None,
        qbit=None,
    ):

        # ----------------------------------------------------------
        # VALIDATE CALLABLE
        # ----------------------------------------------------------

        if not callable(func):
            raise TypeError(
                "[QbitDialer] add_task requires a callable"
            )

        # ----------------------------------------------------------
        # COPY METADATA
        #
        # Never mutate caller-owned metadata.
        # ----------------------------------------------------------

        task_metadata = dict(
            metadata or {}
        )

        # ----------------------------------------------------------
        # RESOLVE QBIT
        #
        # Explicit Qbit wins.
        #
        # Otherwise use the Dialer's currently attached Qbit.
        #
        # Qbit remains DATA / IDENTITY / LINEAGE.
        # ----------------------------------------------------------

        if qbit is None:
            qbit = getattr(
                self,
                "qbit",
                None,
            )

        # ----------------------------------------------------------
        # QBIT IDENTITY / LINEAGE
        # ----------------------------------------------------------

        if qbit is not None:

            task_metadata.setdefault(
                "qbit_id",
                getattr(
                    qbit,
                    "id",
                    getattr(
                        qbit,
                        "qbit_id",
                        None,
                    ),
                ),
            )

            task_metadata.setdefault(
                "qbit_track",
                getattr(
                    qbit,
                    "track",
                    getattr(
                        qbit,
                        "track_id",
                        None,
                    ),
                ),
            )

            task_metadata.setdefault(
                "qbit_channel",
                getattr(
                    qbit,
                    "channel",
                    getattr(
                        qbit,
                        "channel_id",
                        None,
                    ),
                ),
            )

            task_metadata.setdefault(
                "qbit_generation",
                getattr(
                    qbit,
                    "generation",
                    0,
                ),
            )

            # ------------------------------------------------------
            # PRESERVE QBIT SOURCE / DESTINATION
            # ------------------------------------------------------

            task_metadata.setdefault(
                "qbit_source",
                getattr(
                    qbit,
                    "source",
                    None,
                ),
            )

            task_metadata.setdefault(
                "qbit_destination",
                getattr(
                    qbit,
                    "destination",
                    None,
                ),
            )

            # ------------------------------------------------------
            # PRESERVE QBIT PRIORITY
            # ------------------------------------------------------

            task_metadata.setdefault(
                "qbit_priority",
                getattr(
                    qbit,
                    "priority",
                    None,
                ),
            )

            # ------------------------------------------------------
            # PRESERVE QBIT PAYLOAD REFERENCE
            #
            # Do not copy/transform the payload here.
            # Qbit remains the authoritative transport object.
            # ------------------------------------------------------

            task_metadata.setdefault(
                "qbit_payload",
                getattr(
                    qbit,
                    "payload",
                    None,
                ),
            )

        # ----------------------------------------------------------
        # CAPTURE QBIT RUNTIME STATE
        #
        # These are observations only.
        # They do not grant execution authority to Qbit.
        # ----------------------------------------------------------

        task_metadata.setdefault(
            "qbit_runtime_state",
            getattr(
                self,
                "_qbit_runtime_state",
                getattr(
                    self,
                    "_runtime_state",
                    "UNKNOWN",
                ),
            ),
        )

        task_metadata.setdefault(
            "qbit_running",
            bool(
                getattr(
                    self,
                    "_qbit_running",
                    False,
                )
            ),
        )

        # ----------------------------------------------------------
        # CAPTURE DIALER STATE
        # ----------------------------------------------------------

        task_metadata.setdefault(
            "dialer_running",
            bool(
                getattr(
                    self,
                    "_running",
                    False,
                )
            ),
        )

        task_metadata.setdefault(
            "dialer_ready",
            bool(
                getattr(
                    self,
                    "_ready",
                    getattr(
                        self,
                        "_dialer_ready",
                        False,
                    ),
                )
            ),
        )

        # ----------------------------------------------------------
        # PIPELINE CONTRACT
        #
        # Explicitly identify the authoritative cognition path.
        # ----------------------------------------------------------

        task_metadata.setdefault(
            "qbit_transport_authority",
            "Qbit",
        )

        task_metadata.setdefault(
            "qbit_queue_authority",
            "QbitQueueLoop",
        )

        task_metadata.setdefault(
            "compute_authority",
            "ComputeBrain",
        )

        task_metadata.setdefault(
            "thought_packet_type",
            "ThoughtPacket",
        )

        task_metadata.setdefault(
            "transformer_authority",
            "TransformerBrain",
        )

        task_metadata.setdefault(
            "command_authority",
            "QbitDialer",
        )

        task_metadata.setdefault(
            "command_admission",
            "submit_command",
        )

        # ----------------------------------------------------------
        # CREATE DIALER TASK ITEM
        #
        # The Qbit object itself remains attached.
        #
        # This preserves:
        #
        #     Qbit identity
        #       +
        #     lineage
        #       +
        #     track
        #       +
        #     channel
        #       +
        #     payload
        #       +
        #     runtime metadata
        #
        # throughout cognition and command processing.
        # ----------------------------------------------------------

        task_item = {
            "task_id": (
                f"TASK-{uuid.uuid4().hex[:12]}"
            ),

            "qbit": qbit,

            "func": func,

            "metadata": task_metadata,

            # ------------------------------------------------------
            # Lifecycle
            # ------------------------------------------------------

            "status": "QUEUED",

            "created_at": time.time(),

            "queued_at": time.time(),

            "started_at": None,

            "completed_at": None,

            # ------------------------------------------------------
            # Results
            # ------------------------------------------------------

            "result": None,

            "error": None,

            # ------------------------------------------------------
            # Cognition
            # ------------------------------------------------------

            "thought": None,

            "thought_packet": None,

            "analysis": None,

            "intent": None,

            # ------------------------------------------------------
            # Command pipeline
            #
            # These fields are populated by the authoritative
            # cognition/command path.
            # ------------------------------------------------------

            "command_proposal": None,

            "command": None,

            "command_admitted": False,

            "command_admission_path": None,

            # ------------------------------------------------------
            # Execution authority marker
            # ------------------------------------------------------

            "execution_authority": (
                "QbitQueueLoop"
            ),

            "command_authority": (
                "QbitDialer"
            ),

            "transport_authority": (
                "Qbit"
            ),
        }

        # ----------------------------------------------------------
        # DIALER LOCAL STAGING ONLY
        #
        # This queue is NOT QbitQueueLoop.
        #
        # It exists only so the Dialer can retain its execution
        # staging/task state without stealing ownership from the
        # authoritative QbitQueueLoop.
        # ----------------------------------------------------------

        with self._lock:

            self._tasks.append(
                task_item
            )

        # ----------------------------------------------------------
        # INFORM QBIT OF TASK ARRIVAL
        #
        # This is STATE / OBSERVATION only.
        #
        # It does NOT execute the task.
        #
        # It does NOT submit a command.
        #
        # It does NOT create another queue.
        # ----------------------------------------------------------

        if (
            qbit is not None
            and hasattr(
                qbit,
                "process_task_queued",
            )
        ):

            try:

                qbit.process_task_queued(
                    task_item
                )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] "
                    "Qbit task-queued state update failed"
                )

        # ----------------------------------------------------------
        # OPTIONAL EVENTBUS OBSERVATION
        #
        # If the Dialer exposes an EventBus emission method,
        # publish the staging event.
        #
        # Never directly invoke QbitQueueLoop here.
        # ----------------------------------------------------------

        try:

            emit = getattr(
                self,
                "_emit",
                None,
            )

            if callable(emit):

                emit(
                    "QBIT_DIALER_TASK_QUEUED",
                    {
                        "task_id": task_item[
                            "task_id"
                        ],
                        "qbit_id": task_metadata.get(
                            "qbit_id"
                        ),
                        "qbit_track": task_metadata.get(
                            "qbit_track"
                        ),
                        "qbit_channel": task_metadata.get(
                            "qbit_channel"
                        ),
                        "status": "QUEUED",
                        "command_authority": (
                            "QbitDialer"
                        ),
                        "command_admission": (
                            "submit_command"
                        ),
                        "execution_authority": (
                            "QbitQueueLoop"
                        ),
                        "timestamp": time.time(),
                    },
                )

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "task staging event emission failed"
            )

        return task_item


    def execute_all(self):

        executed = 0

        # ------------------------------------------------------
        # AUTHORITATIVE RUNTIME CHECK
        # ------------------------------------------------------

        if not getattr(
            self,
            "_running",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] execute_all ignored | "
                "Dialer runtime is not RUNNING"
            )

            return 0

        # ------------------------------------------------------
        # VERIFY QbitQueueLoop CONNECTION
        #
        # This does NOT consume its queue.
        # It only verifies the authoritative transport exists.
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "_qbit_queue_loop",
                None,
            )

        if queue_loop is None:

            self.logger.warning(
                "[QbitDialer] Task execution blocked | "
                "QbitQueueLoop not connected"
            )

            return 0

        # ------------------------------------------------------
        # VERIFY Qbit
        # ------------------------------------------------------

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Task execution blocked | "
                "authoritative Qbit not connected"
            )

            return 0

        # ------------------------------------------------------
        # EXECUTE DIALED TASKS
        # ------------------------------------------------------

        while True:

            # --------------------------------------------------
            # Safely remove one task
            # --------------------------------------------------

            with self._lock:

                if not self._tasks:
                    break

                task_item = (
                    self._tasks.popleft()
                )

                task_item["status"] = "EXECUTING"

            try:

                # --------------------------------------------------
                # Execute command/task
                # --------------------------------------------------

                result = task_item["func"]()

                task_item["result"] = result
                task_item["status"] = "COMPLETE"

                executed += 1

                # --------------------------------------------------
                # Feed successful result into Qbit
                # --------------------------------------------------

                process_result = getattr(
                    qbit,
                    "process_task_result",
                    None,
                )

                if callable(
                    process_result
                ):

                    process_result(
                        result
                    )

                # --------------------------------------------------
                # Qbit health/result accounting
                # --------------------------------------------------

                process_success = getattr(
                    qbit,
                    "process_task_success",
                    None,
                )

                if callable(
                    process_success
                ):

                    process_success(
                        task_item
                    )

                # --------------------------------------------------
                # Emit successful execution
                # --------------------------------------------------

                self._safe_emit(
                    "QBIT_TASK_COMPLETE",
                    {
                        "task": task_item,
                        "qbit_id": getattr(
                            qbit,
                            "id",
                            None,
                        ),
                        "qbit_generation": getattr(
                            qbit,
                            "generation",
                            None,
                        ),
                        "result": result,
                    },
                )

            except Exception as exc:

                task_item["status"] = "FAILED"
                task_item["error"] = str(
                    exc
                )

                # --------------------------------------------------
                # Qbit failure / health accounting
                # --------------------------------------------------

                process_failure = getattr(
                    qbit,
                    "process_task_failure",
                    None,
                )

                if callable(
                    process_failure
                ):

                    try:

                        process_failure(
                            task_item,
                            exc,
                        )

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Qbit failure "
                            "state update failed"
                        )

                # --------------------------------------------------
                # Log failure
                # --------------------------------------------------

                self.logger.exception(
                    "[QbitDialer] Task execution failed"
                )

                # --------------------------------------------------
                # Safe failure emission
                # --------------------------------------------------

                self._safe_emit(
                    "TASK_FAILURE",
                    {
                        "task": task_item,
                        "error": str(
                            exc
                        ),
                        "error_type": type(
                            exc
                        ).__name__,
                        "qbit_id": getattr(
                            qbit,
                            "id",
                            None,
                        ),
                        "qbit_generation": getattr(
                            qbit,
                            "generation",
                            None,
                        ),
                    },
                )

        return executed

    # ==========================================================
    # TASK QUEUE COUNT
    #
    # Local Dialer execution staging only.
    #
    # NOT QbitQueueLoop queue depth.
    # ==========================================================

    def task_count(self):

        with self._lock:

            count = len(
                self._tasks
            )

        return count

    # ==========================================================
    # QBIT COMMAND / HOST BINDING
    # ==========================================================

    async def bind_host(
        self,
        host_device,
    ):

        if host_device is None:
            raise ValueError(
                "[QbitDialer] bind_host requires host_device"
            )

        self.host_device = host_device

        self.capabilities = getattr(
            host_device,
            "capabilities",
            {},
        )

        # ------------------------------------------------------
        # ALWAYS use the instance-owned EventBus.
        #
        # Never fall back to the module-global `event_bus` here.
        # ------------------------------------------------------
        bus = getattr(
            self,
            "event_bus",
            None,
        )

        if bus is None:
            self.logger.warning(
                "[QbitDialer] bind_host called without EventBus; "
                "heartbeat subscription deferred"
            )
            return True

        # ------------------------------------------------------
        # Reject an EventBus CLASS.
        # ------------------------------------------------------
        if isinstance(
            bus,
            type,
        ):
            raise TypeError(
                "[QbitDialer] bind_host expected "
                "SEEDEventBus INSTANCE, got class instead"
            )

        # ------------------------------------------------------
        # Validate EventBus API.
        # ------------------------------------------------------
        subscribe = getattr(
            bus,
            "subscribe",
            None,
        )

        if not callable(subscribe):
            self.logger.warning(
                "[QbitDialer] EventBus has no usable subscribe(); "
                "heartbeat subscription deferred"
            )
            return True

        # ------------------------------------------------------
        # Subscribe once.
        # ------------------------------------------------------
        try:
            subscribe(
                "HEARTBEAT",
                self._on_heartbeat,
            )
        except Exception as exc:
            self.logger.warning(
                "[QbitDialer] HEARTBEAT subscription failed | "
                "%s: %s",
                type(exc).__name__,
                exc,
            )

        self.logger.info(
            "[QbitDialer] Host bound | "
            "device=%s | capabilities=%d",
            type(host_device).__name__,
            len(
                self.capabilities
                if isinstance(
                    self.capabilities,
                    dict,
                )
                else {}
            ),
        )

        return True
    # -------------------------------------------------------------------------

    # ==========================================================
    # SECTION 32 â€” CLI
    #
    # SEEDCLI IS AN INPUT INTERFACE ONLY.
    #
    # CLI
    #     â†“
    # QbitDialer.execute_command()
    #     â†“
    # _execute_qbit_command()
    #     â†“
    # command handler
    #
    # SEEDCLI does NOT:
    #
    #     - own a command registry
    #     - create a command queue
    #     - execute handlers directly
    #     - create Qbits
    #     - start QbitDialer
    #     - start QbitQueueLoop
    #
    # QbitDialer remains the SINGLE command authority.
    # ==========================================================

    def boot_cli():

        global cli

        try:

            from interfaces.seed_cli import (
                SEEDCLI,
            )

            # ------------------------------------------------------
            # Authoritative command endpoint.
            #
            # CLI never gets a copy of the registry.
            # CLI sends commands to this Dialer.
            # ------------------------------------------------------

            dialer = qbit_dialer

            if dialer is None:

                boot_warn(
                    "SEEDCLI waiting | "
                    "QbitDialer not available"
                )

            constructor_options = [

                # --------------------------------------------------
                # Preferred constructor.
                # --------------------------------------------------

                (
                    (),
                    {
                        "event_bus": event_bus,
                        "qbit_dialer": dialer,
                        "dialer": dialer,
                        "command_executor": (
                            getattr(
                                dialer,
                                "execute_command",
                                None,
                            )
                            if dialer is not None
                            else None
                        ),
                    },
                ),

                # --------------------------------------------------
                # Compatibility constructor.
                # --------------------------------------------------

                (
                    (),
                    {
                        "event_bus": event_bus,
                        "qbit_dialer": dialer,
                    },
                ),

                # --------------------------------------------------
                # Older SEEDCLI compatibility.
                # --------------------------------------------------

                (
                    (),
                    {
                        "event_bus": event_bus,
                    },
                ),

                # --------------------------------------------------
                # No-argument fallback.
                # --------------------------------------------------

                (
                    (),
                    {},
                ),
            ]

            cli = compatible_construct(
                SEEDCLI,
                constructor_options,
                "SEEDCLI",
            )

            if cli is None:

                MODULES_STATUS[
                    "SEEDCLI"
                ] = False

                boot_warn(
                    "SEEDCLI failed to initialize"
                )

                return None

            # ======================================================
            # POST-CONSTRUCTION AUTHORITATIVE BINDING
            #
            # This makes the connection deterministic even if the
            # installed SEEDCLI constructor uses a legacy signature.
            # ======================================================

            if dialer is not None:

                try:

                    cli.qbit_dialer = dialer

                except Exception:

                    pass

                try:

                    cli.dialer = dialer

                except Exception:

                    pass

                execute_command = getattr(
                    dialer,
                    "execute_command",
                    None,
                )

                if callable(
                    execute_command
                ):

                    try:

                        cli.command_executor = (
                            execute_command
                        )

                    except Exception:

                        pass

                    try:

                        cli.execute_command = (
                            execute_command
                        )

                    except Exception:

                        pass

            # ======================================================
            # CLI STATE
            # ======================================================

            MODULES_STATUS[
                "SEEDCLI"
            ] = True

            boot_log(
                "SEEDCLI initialized | "
                "type=%s | "
                "command_authority=%s",
                type(cli).__name__,
                (
                    type(dialer).__name__
                    if dialer is not None
                    else "WAITING"
                ),
            )

            return cli

        except Exception as exc:

            MODULES_STATUS[
                "SEEDCLI"
            ] = False

            trace_exception(
                exc
            )

            cli = None

            return None


# ==========================================================
# BUILD COGNITIVE COMMAND
#
# AUTHORITATIVE COGNITIVE -> COMMAND BOUNDARY
#
# Pipeline:
#
#     Qbit
#       |
#       v
#     ComputeBrain
#       |
#       v
#     ThoughtPacket
#       |
#       v
#     TransformerBrain
#       |
#       v
#     _build_cognitive_command()
#       |
#       v
#     Command Envelope
#       |
#       v
#     submit_command()
#       |
#       v
#     authoritative command_queue
#
# IMPORTANT:
#
# This method BUILDS only.
#
# It does NOT:
#
#     - execute commands
#     - enqueue commands
#     - create Qbits
#     - create tasks
#     - create tracks
#     - invoke QbitQueueLoop
#     - invoke QbitDialer recursively
#     - convert a raw Qbit into a command
#
# Only TransformerBrain output may become executable command
# data.
# ==========================================================

    def _build_cognitive_command(
        self,
        *,
        qbit=None,
        compute_result=None,
        transform_result=None,
        action_proposal=None,
    ):

        # ==========================================================
        # IDLE HEARTBEAT COGNITION GATE
        # ==========================================================
        # An idle Qbit must still produce a governed thought
        # direction. ActionEngine may report COMPUTE_BRAIN or
        # no action; QbitDialer converts that semantic idle state
        # into a bounded watch/wait decision.
        idle_intent = None
        if isinstance(compute_result, dict):
            encoder_context = compute_result.get("encoder_context")
            if isinstance(encoder_context, dict):
                idle_intent = encoder_context.get("intent")
            if idle_intent is None:
                normalized = compute_result.get("normalized")
                if isinstance(normalized, dict):
                    idle_intent = normalized.get("intent")
            if idle_intent is None:
                thought_task = compute_result.get("task")
                if isinstance(thought_task, dict):
                    idle_intent = thought_task.get("intent")
                    if idle_intent is None and isinstance(thought_task.get("why"), dict):
                        idle_intent = thought_task["why"].get("name")
        if isinstance(idle_intent, str) and idle_intent.strip().upper() == "IDLE":
            proposal_is_executable = False
            if isinstance(action_proposal, dict):
                proposal_is_executable = bool(
                    action_proposal.get("execution_required")
                    or action_proposal.get("actionable")
                    or action_proposal.get("has_actionable_command")
                    or action_proposal.get("handler_key")
                )
            if not proposal_is_executable:
                action_proposal = {
                    "action": "OBSERVE_SYSTEM",
                    "name": "OBSERVE_SYSTEM",
                    "execution_required": False,
                    "actionable": False,
                    "has_actionable_command": False,
                    "origin": "IdleIntent",
                    "reason": "IDLE heartbeat requires a bounded watch/wait decision",
                }

        # ==========================================================
        # ACTIONENGINE PROPOSAL GATE
        # ==========================================================
        if isinstance(action_proposal, dict):

            proposal_action = (
                action_proposal.get("action")
                or action_proposal.get("name")
                or action_proposal.get("command")
            )

            if isinstance(proposal_action, dict):
                proposal_action = (
                    proposal_action.get("name")
                    or proposal_action.get("command")
                    or proposal_action.get("cmd")
                )

            if isinstance(proposal_action, str):
                proposal_action = proposal_action.strip().upper()

            proposal_handler = action_proposal.get(
                "handler_key"
            )

            proposal_execution_required = bool(
                action_proposal.get(
                    "execution_required",
                    False,
                )
            )

            proposal_actionable = bool(
                action_proposal.get("actionable", False)
                or action_proposal.get(
                    "has_actionable_command",
                    False,
                )
            )

            # Semantic-only idle proposals receive a bounded heartbeat command directory.
            idle_intent = None
            for idle_source in (qbit, self.qbit):
                if idle_source is None:
                    continue
                if isinstance(idle_source, dict):
                    idle_intent = idle_source.get("intent")
                else:
                    idle_intent = getattr(idle_source, "intent", None)
                if isinstance(idle_intent, str) and idle_intent.strip():
                    break
            if idle_intent is None and isinstance(action_proposal.get("why"), dict):
                idle_intent = action_proposal["why"].get("name")
            idle_intent = (
                idle_intent.strip().upper()
                if isinstance(idle_intent, str)
                else None
            )

            if (
                (
                    proposal_action == "OBSERVE_SYSTEM"
                    or (
                        proposal_action == "COMPUTE_BRAIN"
                        and idle_intent == "IDLE"
                    )
                )
                and not proposal_execution_required
                and not proposal_handler
                and not proposal_actionable
            ):
                idle_directory = (
                    "HEARTBEAT_STATUS",
                    "STATUS",
                    "MEASURE",
                    "GET_STATE",
                    "QUEUE_STATUS",
                    "COGNITION_STATUS",
                    "DEFER",
                )
                command_registry = getattr(self, "command_registry", {}) or {}
                command_catalog = getattr(self, "command_catalog", {}) or {}
                available = tuple(
                    name for name in idle_directory
                    if callable(command_registry.get(name))
                    or name in command_catalog
                )
                if available:
                    selected = None
                    oracle = getattr(self, "oracle", None)
                    if oracle is not None:
                        try:
                            advice = oracle.receive_report({
                                "event": "IDLE_COMMAND_DIRECTION",
                                "reason": "OBSERVE_SYSTEM",
                                "available_commands": list(available),
                                "qbit_id": getattr(qbit, "qbit_id", None) if qbit is not None else None,
                            })
                            if isinstance(advice, dict):
                                for key in ("command", "recommended_command", "selected_command"):
                                    value = advice.get(key)
                                    if isinstance(value, str) and value.strip().upper() in available:
                                        selected = value.strip().upper()
                                        break
                        except Exception as exc:
                            self.logger.debug("[QbitDialer] Oracle idle direction unavailable | %s", exc)
                    if selected is None:
                        index = int(getattr(self, "_idle_command_index", 0))
                        selected = available[index % len(available)]
                        self._idle_command_index = index + 1
                    handler = command_registry.get(selected)
                    action_proposal["action"] = selected
                    action_proposal["name"] = selected
                    action_proposal["handler_key"] = selected if handler is not None else action_proposal.get("handler_key")
                    action_proposal["execution_required"] = handler is not None
                    action_proposal["execution_requested"] = handler is not None
                    action_proposal["actionable"] = handler is not None
                    action_proposal["has_actionable_command"] = handler is not None
                    action_proposal["idle_selection"] = True
                    action_proposal["idle_directory"] = list(available)
                    action_proposal["oracle_assisted"] = oracle is not None
                    proposal_action = selected
                    proposal_handler = action_proposal.get("handler_key")
                    proposal_execution_required = bool(action_proposal.get("execution_required"))
                    proposal_actionable = bool(action_proposal.get("actionable"))

            # Semantic-only ActionEngine proposals remain cognitive results.
            if (
                proposal_action
                and not proposal_execution_required
                and not proposal_handler
                and not proposal_actionable
            ):
                self.logger.info(
                    "[QbitDialer] Cognitive proposal retained | action=%s | executable=False | origin=ActionEngine",
                    proposal_action,
                )
                return None

            # Only genuinely executable ActionEngine proposals
            # cross the cognitive -> command boundary.
            if (
                proposal_action
                and (
                    proposal_execution_required
                    or proposal_handler
                    or proposal_actionable
                )
            ):
                command = dict(action_proposal)

                command["name"] = proposal_action
                command["origin"] = "ActionEngine"
                command["command_authority"] = "QbitDialer"
                command["command_admission"] = "submit_command"
                command["execution_owner"] = "QbitDialer"
                command["proposal_only"] = False

                return command
        # ======================================================
        # 1. HARD TRANSFORM RESULT VALIDATION
        # ======================================================

        if transform_result is None:

            self.logger.debug(
                "[QbitDialer] Cognitive command build skipped | "
                "reason=no_transform_result"
            )

            return None

        if not isinstance(
            transform_result,
            dict,
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command build rejected | "
                "reason=invalid_transform_result | "
                "type=%s",
                type(transform_result).__name__,
            )

            return None

        # ======================================================
        # 2. NEVER ACCEPT RAW QBIT AS COMMAND
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                transform_result,
                qbit_type,
            )
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command build rejected | "
                "reason=transform_result_is_raw_qbit"
            )

            return None
        # ======================================================
        # 3. ACTIONENGINE IS THE AUTHORITATIVE ACTION PROPOSAL
        #
        # IntentEngine -> ActionEngine -> QbitDialer
        #
        # ActionEngine proposes.
        # QbitDialer decides whether the proposal is executable.
        # TransformerBrain must NOT override an executable
        # ActionEngine proposal.
        # ======================================================

        candidate = None

        if isinstance(
            action_proposal,
            dict,
        ):
            proposed_action = (
                action_proposal.get("action")
                or action_proposal.get("command")
                or action_proposal.get("command_name")
                or action_proposal.get("name")
            )

            if isinstance(
                proposed_action,
                dict,
            ):
                proposed_action = dict(
                    proposed_action
                )

            elif isinstance(
                proposed_action,
                str,
            ):
                proposed_action = {
                    "name": proposed_action.strip()
                }

            else:
                proposed_action = None

            execution_required = bool(
                action_proposal.get(
                    "execution_required",
                    False,
                )
            )

            executable = bool(
                action_proposal.get(
                    "executable",
                    action_proposal.get(
                        "actionable",
                        execution_required,
                    ),
                )
            )

            if (
                proposed_action is not None
                and execution_required
                and executable
            ):
                candidate = dict(
                    proposed_action
                )

                candidate.setdefault(
                    "proposed_by",
                    "ActionEngine",
                )

                candidate.setdefault(
                    "command_authority",
                    "QbitDialer",
                )

                candidate.setdefault(
                    "command_admission",
                    "submit_command",
                )

                candidate.setdefault(
                    "execution_owner",
                    "QbitQueueLoop",
                )

                candidate["proposal_only"] = False

                self.logger.info(
                    "[QbitDialer] ActionEngine executable proposal "
                    "accepted | action=%s | qbit_id=%s",
                    candidate.get("name"),
                    getattr(
                        qbit,
                        "qbit_id",
                        None,
                    ),
                )
        # ======================================================
        # 3. EXTRACT COMMAND CANDIDATE
        #
        # ActionEngine is the authoritative proposal source.
        # TransformerBrain remains the compatibility fallback.
        # ======================================================



        def _extract_candidate(value):
            if value is None:
                return None

            if isinstance(
                value,
                str,
            ):
                value = value.strip()

                if value:
                    return {
                        "name": value,
                    }

                return None

            if not isinstance(
                value,
                dict,
            ):
                return None

            for key in (
                "command",
                "proposed_command",
                "cmd",
                "executable_command",
                "command_name",
            ):
                nested = value.get(
                    key
                )

                if isinstance(
                    nested,
                    str,
                ):
                    nested = nested.strip()

                    if nested:
                        return {
                            "name": nested,
                        }

                elif isinstance(
                    nested,
                    dict,
                ):
                    extracted = _extract_candidate(
                        nested
                    )

                    if extracted is not None:
                        return extracted

            for key in (
                "command_envelope",
                "command_proposal",
                "proposal",
                "action",
            ):
                nested = value.get(
                    key
                )

                extracted = _extract_candidate(
                    nested
                )

                if extracted is not None:
                    return extracted

            direct_name = (
                value.get("name")
                or value.get("command_name")
                or value.get("cmd")
            )

            if isinstance(
                direct_name,
                dict,
            ):
                direct_name = (
                    direct_name.get("name")
                    or direct_name.get("command")
                    or direct_name.get("cmd")
                    or direct_name.get("action")
                )

            if isinstance(
                direct_name,
                str,
            ):
                direct_name = direct_name.strip()

                if direct_name:
                    return {
                        "name": direct_name,
                    }

            return None

        # ------------------------------------------------------
        # ACTIONENGINE IS AUTHORITATIVE
        # ------------------------------------------------------

        candidate = _extract_candidate(
            action_proposal
        )

        # ------------------------------------------------------
        # TRANSFORMERBRAIN FALLBACK
        # ------------------------------------------------------

        if candidate is None:
            candidate = _extract_candidate(
                transform_result
            )

        # ======================================================
        # 4. NO EXECUTABLE COMMAND
        # ======================================================

        if candidate is None:
            self.logger.info(
                "[QbitDialer] Cognitive result contains "
                "no executable command | qbit_id=%s",
                getattr(
                    qbit,
                    "qbit_id",
                    None,
                ),
            )

            return None
        # ======================================================
        # 5. NO EXECUTABLE COMMAND
        # ======================================================

        if candidate is None:

            self.logger.info(
                "[QbitDialer] Transformer result contains "
                "no executable command | "
                "qbit_id=%s",
                getattr(
                    qbit,
                    "qbit_id",
                    None,
                ),
            )

            return None

        # ======================================================
        # 6. EXTRACT COMMAND NAME
        # ======================================================

        command_name = (
            candidate.get(
                "name"
            )
            or candidate.get(
                "command_name"
            )
            or candidate.get(
                "command"
            )
            or candidate.get(
                "action"
            )
        )

        # ------------------------------------------------------
        # Nested command/action dictionary compatibility.
        # ------------------------------------------------------

        if isinstance(
            command_name,
            dict,
        ):

            command_name = (
                command_name.get(
                    "name"
                )
                or command_name.get(
                    "command_name"
                )
                or command_name.get(
                    "command"
                )
                or command_name.get(
                    "action"
                )
            )

        # ------------------------------------------------------
        # Nested command/action object compatibility.
        # ------------------------------------------------------

        if not isinstance(
            command_name,
            str,
        ) and command_name is not None:

            command_name = (
                getattr(
                    command_name,
                    "name",
                    None,
                )
                or getattr(
                    command_name,
                    "command_name",
                    None,
                )
                or getattr(
                    command_name,
                    "command",
                    None,
                )
                or getattr(
                    command_name,
                    "action",
                    None,
                )
            )

        # ======================================================
        # 7. REQUIRE STRING COMMAND NAME
        # ======================================================

        if not isinstance(
            command_name,
            str,
        ):

            self.logger.debug(
                "[QbitDialer] Cognitive command rejected | "
                "reason=missing_command_name"
            )

            return None

        command_name = command_name.strip()

        if not command_name:

            self.logger.debug(
                "[QbitDialer] Cognitive command rejected | "
                "reason=empty_command_name"
            )

            return None

        command_name = command_name.upper()

        # ======================================================
        # 8. REJECT DATA-LIKE COMMAND NAMES
        # ======================================================

        if command_name in (
            "QBIT",
            "THOUGHTPACKET",
            "TRANSFORMEDTHOUGHTPACKET",
            "COGNITIVE_RESULT",
            "COGNITIVERESULT",
            "DATA",
            "NONE",
            "NULL",
            "DICT",
            "OBJECT",
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command rejected | "
                "reason=non_executable_command_name | "
                "command=%s",
                command_name,
            )

            return None

        # ======================================================
        # 9. NORMALIZE ARGUMENT CONTAINERS
        # ======================================================

        args = candidate.get(
            "args"
        )

        kwargs = candidate.get(
            "kwargs"
        )

        payload = candidate.get(
            "payload"
        )

        if args is None:

            args = []

        elif not isinstance(
            args,
            (list, tuple),
        ):

            args = [
                args
            ]

        else:

            args = list(
                args
            )

        if kwargs is None:

            kwargs = {}

        elif not isinstance(
            kwargs,
            dict,
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command rejected | "
                "reason=invalid_kwargs | command=%s",
                command_name,
            )

            return None

        else:

            kwargs = dict(
                kwargs
            )

        if payload is None:

            payload = {}

        elif not isinstance(
            payload,
            dict,
        ):

            payload = {
                "value": payload
            }

        else:

            payload = dict(
                payload
            )

        # ======================================================
        # 10. READ EXISTING QBIT IDENTITY
        # ======================================================

        qbit_id = None
        track_id = None
        task_id = None
        pipeline_id = None

        if qbit is not None:

            qbit_id = getattr(
                qbit,
                "qbit_id",
                None,
            )

            if qbit_id is None:

                qbit_id = getattr(
                    qbit,
                    "id",
                    None,
                )

            track_id = getattr(
                qbit,
                "track_id",
                None,
            )

            if track_id is None:

                track_id = getattr(
                    qbit,
                    "track",
                    None,
                )

                if not isinstance(
                    track_id,
                    str,
                ):

                    track_id = getattr(
                        track_id,
                        "track_id",
                        None,
                    )

            task_id = getattr(
                qbit,
                "task_id",
                None,
            )

            pipeline_id = getattr(
                qbit,
                "pipeline_id",
                None,
            )

        # ======================================================
        # 11. PRESERVE TRANSFORMER-SUPPLIED IDENTITY
        # ======================================================

        qbit_id = (
            candidate.get(
                "qbit_id"
            )
            or transform_result.get(
                "qbit_id"
            )
            or qbit_id
        )

        track_id = (
            candidate.get(
                "track_id"
            )
            or transform_result.get(
                "track_id"
            )
            or track_id
        )

        task_id = (
            candidate.get(
                "task_id"
            )
            or transform_result.get(
                "task_id"
            )
            or task_id
        )

        pipeline_id = (
            candidate.get(
                "pipeline_id"
            )
            or transform_result.get(
                "pipeline_id"
            )
            or pipeline_id
        )

        # ======================================================
        # 12. PRESERVE COMPUTE / THOUGHT CONTEXT
        # ======================================================

        thought = (
            compute_result
            if compute_result is not None
            else transform_result.get(
                "thought"
            )
        )

        # ======================================================
        # 13. PRESERVE SOURCE / CHANNEL
        # ======================================================

        source = (
            candidate.get(
                "source"
            )
            or transform_result.get(
                "source"
            )
            or (
                getattr(
                    qbit,
                    "source",
                    None,
                )
                if qbit is not None
                else None
            )
        )

        channel = (
            candidate.get(
                "channel"
            )
            or transform_result.get(
                "channel"
            )
            or (
                getattr(
                    qbit,
                    "channel",
                    None,
                )
                if qbit is not None
                else None
            )
        )

        # ======================================================
        # 14. BUILD AUTHORITATIVE COMMAND ENVELOPE
        # ======================================================

        command = {

            "name": command_name,

            "args": args,

            "kwargs": kwargs,

            "payload": payload,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "source": source,

            "channel": channel,

            "thought": thought,

            "transform": transform_result,

            "compute_result": compute_result,

            "authority": "QbitDialer",

            "origin": "TransformerBrain",

        }

        # ======================================================
        # 15. PRESERVE OPTIONAL TRANSFORMER METADATA
        # ======================================================

        for key in (
            "track_context",
            "health",
            "lineage",
            "relationships",
            "intent",
            "intent_scores",
            "reason",
            "confidence",
            "priority",
            "metadata",
            "cognitive_result",
            "thought_packet",
            "analysis",
            "evaluation",
            "planning",
            "feedback",
        ):

            if key in candidate:

                command[
                    key
                ] = candidate[
                    key
                ]

            elif key in transform_result:

                command[
                    key
                ] = transform_result[
                    key
                ]

        # ======================================================
        # 16. PRESERVE ORIGINAL COMMAND FIELDS
        # ======================================================

        protected = set(
            command.keys()
        )

        for key, value in candidate.items():

            if key not in protected:

                command[
                    key
                ] = value

        # ======================================================
        # 17. FINAL COMMAND BOUNDARY VALIDATION
        # ======================================================

        if not isinstance(
            command.get(
                "name"
            ),
            str,
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command boundary "
                "validation failed | reason=invalid_name"
            )

            return None

        command[
            "name"
        ] = command[
            "name"
        ].strip().upper()

        if not command[
            "name"
        ]:

            return None

        # ======================================================
        # 18. FINAL RAW-QBIT PROTECTION
        # ======================================================

        if (
            command[
                "name"
            ]
            in (
                "QBIT",
                "THOUGHTPACKET",
                "TRANSFORMEDTHOUGHTPACKET",
                "COGNITIVE_RESULT",
                "COGNITIVERESULT",
            )
        ):

            self.logger.warning(
                "[QbitDialer] Cognitive command rejected | "
                "reason=protected_cognitive_data_name | "
                "command=%s",
                command[
                    "name"
                ],
            )

            return None

        # ======================================================
        # 19. LOG ONLY â€” DO NOT EXECUTE
        # ======================================================

        self.logger.info(
            "[QbitDialer] Cognitive command built | "
            "command=%s | task_id=%s | qbit_id=%s | "
            "track_id=%s | pipeline_id=%s | "
            "origin=TransformerBrain",
            command[
                "name"
            ],
            task_id,
            qbit_id,
            track_id,
            pipeline_id,
        )

        return command

    async def _default_qbit_command(
        self,
        payload=None,
    ):

        return await self._execute_qbit_command(
            payload or {}
        )


    # ==========================================================
    # DYNAMIC COMMAND / CAPABILITY REGISTRATION
    # ==========================================================

    #
    # QbitDialer
    #     = SINGLE COMMAND AUTHORITY
    #
    # create_task()
    #     = authoritative task/capability construction contract
    #
    # _register_phase1_commands()
    #     = synchronizes known command vocabulary with currently
    #       available executable capabilities
    #
    # command_catalog
    #     = known command vocabulary
    #
    # command_registry
    #     = executable handlers only
    #
    # command_plane
    #     = authoritative command-plane status/metadata
    #
    # IMPORTANT:
    #
    # A catalog entry is NOT an admitted command.
    #
    # A registry entry is NOT an executed command.
    #
    # Execution can only occur through:
    #
    #     submit_command()
    #
    # ==========================================================

    def _register_phase1_commands(
        self,
        command_list=None,
    ):

        # ======================================================
        # 1. ENSURE AUTHORITATIVE COMMAND-PLANE CONTAINERS
        # ======================================================

        if not isinstance(
            getattr(
                self,
                "command_catalog",
                None,
            ),
            dict,
        ):
            self.command_catalog = {}

        if not isinstance(
            getattr(
                self,
                "command_registry",
                None,
            ),
            dict,
        ):
            self.command_registry = {}

        if not isinstance(
            getattr(
                self,
                "command_plane",
                None,
            ),
            dict,
        ):
            self.command_plane = {}

        if not hasattr(
            self,
            "command_lock",
        ):
            self.command_lock = threading.RLock()

        # ======================================================
        # 2. DISCOVER ACTUAL CAPABILITIES
        #
        # Discovery answers:
        #
        #     "What can QbitDialer execute?"
        #
        # It does NOT answer:
        #
        #     "What command should execute?"
        #
        # That decision belongs to the command pipeline.
        # ======================================================

        try:

            discovered = (
                self._discover_command_capabilities()
            )

            if not isinstance(
                discovered,
                dict,
            ):
                discovered = {}

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] Dynamic capability discovery failed | "
                "existing command plane preserved | "
                "error=%s: %s",
                type(exc).__name__,
                exc,
            )

            discovered = {}

        # ======================================================
        # 3. REGISTER DISCOVERED CAPABILITIES
        #
        # command_catalog:
        #     authoritative vocabulary / capability knowledge
        #
        # command_registry:
        #     executable handlers only
        #
        # IMPORTANT:
        #
        # Never replace a valid executable handler with a
        # non-callable discovery result.
        # ======================================================

        with self.command_lock:

            for command_name, capability in discovered.items():

                name = str(
                    command_name or ""
                ).strip().upper()

                if not name:
                    continue

                if not isinstance(
                    capability,
                    dict,
                ):
                    continue

                handler = capability.get(
                    "handler"
                )

                source = capability.get(
                    "source",
                    "SEED_AI",
                )

                system = capability.get(
                    "system"
                )

                method = capability.get(
                    "method"
                )

                learned = bool(
                    capability.get(
                        "learned",
                        False,
                    )
                )

                authority = capability.get(
                    "authority",
                    "QbitDialer",
                )

                # --------------------------------------------------
                # Catalog capability.
                #
                # Catalog entries may exist before the handler is
                # executable.
                # --------------------------------------------------

                catalog_entry = (
                    self.command_catalog.get(
                        name,
                        {},
                    )
                )

                if not isinstance(
                    catalog_entry,
                    dict,
                ):
                    catalog_entry = {}

                catalog_entry.update({

                    "name": name,

                    "source": source,

                    "authority": authority,

                    "system": system,

                    "method": method,

                    "learned": learned,

                })

                # --------------------------------------------------
                # Only callable handlers become executable.
                # --------------------------------------------------

                if callable(
                    handler
                ):

                    catalog_entry[
                        "state"
                    ] = "EXECUTABLE"

                    self.command_registry[
                        name
                    ] = handler

                else:

                    # Preserve an already-valid executable handler.

                    existing_handler = (
                        self.command_registry.get(
                            name
                        )
                    )

                    if callable(
                        existing_handler
                    ):

                        catalog_entry[
                            "state"
                        ] = "EXECUTABLE"

                    else:

                        catalog_entry[
                            "state"
                        ] = "PENDING"

                self.command_catalog[
                    name
                ] = catalog_entry

        # ======================================================
        # 4. REGISTER COMMAND VOCABULARY SUPPLIED BY create_task()
        #
        # create_task() is the authoritative task/capability
        # construction contract.
        #
        # The producer's vocabulary is preserved even when an
        # executable handler is not yet available.
        # ======================================================

        if command_list is not None:

            # --------------------------------------------------
            # Accept a single command directly.
            # --------------------------------------------------

            if isinstance(
                command_list,
                (
                    str,
                    dict,
                ),
            ):

                command_list = [
                    command_list
                ]

            try:

                command_iterable = iter(
                    command_list
                )

            except TypeError:

                command_iterable = iter(())

            for command in command_iterable:

                command_name = None

                # --------------------------------------------------
                # String command vocabulary
                # --------------------------------------------------

                if isinstance(
                    command,
                    str,
                ):

                    command_name = command

                # --------------------------------------------------
                # Structured command vocabulary
                #
                # "action" is accepted only as vocabulary metadata.
                #
                # It does NOT cause execution.
                # --------------------------------------------------

                elif isinstance(
                    command,
                    dict,
                ):

                    command_name = (
                        command.get(
                            "name"
                        )
                        or command.get(
                            "command"
                        )
                        or command.get(
                            "cmd"
                        )
                        or command.get(
                            "action"
                        )
                    )

                if not command_name:
                    continue

                command_name = str(
                    command_name
                ).strip().upper()

                if not command_name:
                    continue

                # --------------------------------------------------
                # Preserve existing catalog entry.
                # --------------------------------------------------

                existing = (
                    self.command_catalog.get(
                        command_name,
                        {},
                    )
                )

                if not isinstance(
                    existing,
                    dict,
                ):
                    existing = {}

                existing.setdefault(
                    "name",
                    command_name,
                )

                existing.setdefault(
                    "source",
                    "SEED_AI_COMMAND_VOCABULARY",
                )

                existing.setdefault(
                    "authority",
                    "QbitDialer",
                )

                # --------------------------------------------------
                # Preserve metadata supplied by create_task().
                # --------------------------------------------------

                if isinstance(
                    command,
                    dict,
                ):

                    for key in (
                        "description",
                        "system",
                        "method",
                        "source",
                        "priority",
                        "channel",
                        "track_id",
                        "qbit_id",
                        "learned",
                        "metadata",
                    ):

                        if (
                            key in command
                            and key not in existing
                        ):

                            existing[
                                key
                            ] = command.get(
                                key
                            )

                # --------------------------------------------------
                # Executability is determined only by the
                # authoritative executable registry.
                # --------------------------------------------------

                handler = (
                    self.command_registry.get(
                        command_name
                    )
                )

                if callable(
                    handler
                ):

                    existing[
                        "state"
                    ] = "EXECUTABLE"

                else:

                    existing.setdefault(
                        "state",
                        "PENDING",
                    )

                self.command_catalog[
                    command_name
                ] = existing

        # ======================================================
        # 5. RECONCILE COMMAND CATALOG / EXECUTABLE REGISTRY
        #
        # Prevent stale states such as:
        #
        #     registry = EXECUTABLE
        #     catalog  = PENDING
        #
        # ======================================================

        with self.command_lock:

            executable_commands = sorted(
                name
                for name, handler
                in self.command_registry.items()
                if callable(
                    handler
                )
            )

            cataloged_commands = sorted(
                self.command_catalog.keys()
            )

            pending_commands = sorted(
                name
                for name in cataloged_commands
                if name not in executable_commands
            )

            # --------------------------------------------------
            # Reconcile catalog state.
            # --------------------------------------------------

            for name in cataloged_commands:

                entry = (
                    self.command_catalog.get(
                        name
                    )
                )

                if not isinstance(
                    entry,
                    dict,
                ):

                    entry = {
                        "name": name,
                    }

                if name in executable_commands:

                    entry[
                        "state"
                    ] = "EXECUTABLE"

                else:

                    entry[
                        "state"
                    ] = "PENDING"

                entry.setdefault(
                    "authority",
                    "QbitDialer",
                )

                self.command_catalog[
                    name
                ] = entry

            # --------------------------------------------------
            # Update authoritative command-plane state.
            #
            # "active" means the capability plane has at least
            # one executable capability.
            #
            # It does NOT mean a command is currently executing.
            # --------------------------------------------------

            self.command_plane.update({

                "online": True,

                "active": bool(
                    executable_commands
                ),

                "authority": "QbitDialer",

                "admission_authority": "submit_command",

                "execution_authority": "QbitQueueLoop",

                "transport_authority": "Qbit",

                "cognition_authority": "ComputeBrain",

                "thought_packet": "ThoughtPacket",

                "transformer_authority": "TransformerBrain",

                "heartbeat_authority": "Heartbeat",

                "event_transport": "EventBus",

                "registry": self.command_registry,

                "catalog": self.command_catalog,

                "cataloged": len(
                    cataloged_commands
                ),

                "executable": len(
                    executable_commands
                ),

                "pending": len(
                    pending_commands
                ),

                "dynamic": True,

                "execution_started_here": False,

                "queue_created_here": False,

                "qbit_created_here": False,

                "dialer_created_here": False,

                "version": (
                    "DYNAMIC-CAPABILITY-PLANE-V2"
                ),

                "health": (
                    "GREEN"
                    if executable_commands
                    else "YELLOW"
                ),

                "state": (
                    "ONLINE"
                    if executable_commands
                    else "WAITING_FOR_COMMAND_REGISTRY"
                ),

            })

        # ======================================================
        # 6. SYNCHRONIZATION LOG
        # ======================================================

        self.logger.info(
            "[QbitDialer] Command plane synchronized | "
            "cataloged=%d | executable=%d | pending=%d | "
            "commands=%s",
            len(
                cataloged_commands
            ),
            len(
                executable_commands
            ),
            len(
                pending_commands
            ),
            executable_commands,
        )

        # ======================================================
        # 7. RETURN
        #
        # Registration succeeds even if commands remain pending.
        #
        # Pending means:
        #
        #     known vocabulary
        #
        # but:
        #
        #     executable handler not currently available
        #
        # ======================================================

        return True

    # ==========================================================
    # COMMAND CAPABILITY DISCOVERY
    #
    # This is the bridge between SEED's growing systems and
    # QbitDialer's authoritative command plane.
    #
    # It does NOT execute anything.
    #
    # It only discovers explicitly exposed capabilities.
    # ==========================================================

    def _discover_command_capabilities(
        self,
    ):

        capabilities = {}

        # ======================================================
        # 1. EXISTING QBITDIALER HANDLERS
        #
        # Preserve the handlers already working.
        # ======================================================

        for method_name in dir(
            self
        ):

            if not method_name.startswith(
                "_cmd_"
            ):
                continue

            try:
                handler = getattr(
                    self,
                    method_name,
                    None,
                )
            except Exception:
                continue

            if not callable(
                handler
            ):
                continue

            command_name = (
                method_name[
                    5:
                ]
                .strip()
                .upper()
            )

            if not command_name:
                continue

            capabilities[
                command_name
            ] = {
                "handler": handler,
                "source": "QbitDialer",
                "system": "QbitDialer",
                "method": method_name,
                "learned": False,
            }

        # ======================================================
        # 2. DISCOVER CONNECTED SYSTEMS
        #
        # These are references only.
        #
        # QbitDialer does NOT construct them here.
        # ======================================================

        system_names = (
            "seedcore",
            "core",
            "track_system",
            "channel_manager",
            "device_manager",
            "intent_engine",
            "analytics_engine",
            "memory_manager",
            "memory_system",
            "memory_crystallizer",
            "adaptive_engine",
            "adaptive_priority_engine",
            "cognitive_governor",
            "governor",
            "watchdog",
            "health_monitor",
            "heartbeat",
            "heartbeatemitter",
            "audio",
            "audio_modem_manager",
            "modem",
            "voice_engine",
            "actuator_engine",
            "agent_manager",
            "oracle",
            "time_travel_engine",
            "neural_bridge",
            "compute_brain",
            "transformer_brain",
            "registry",
            "system_registry",
            "registry_runtime",
            "nodes",
            "node_registry",
            "neural_bridge",
        )

        for system_name in system_names:

            system = getattr(
                self,
                system_name,
                None,
            )

            if system is None:
                continue

            self._discover_system_capabilities(
                capabilities,
                system_name,
                system,
            )

        # ======================================================
        # 3. DISCOVER EXPLICIT GLOBAL CAPABILITIES
        #
        # A system can expose:
        #
        #     qbit_commands = {
        #         "MY_COMMAND": method,
        #     }
        #
        # without requiring QbitDialer to know its class.
        # ======================================================

        explicit_systems = (
            getattr(
                self,
                "command_sources",
                None,
            )
        )

        if isinstance(
            explicit_systems,
            dict,
        ):

            for system_name, system in (
                explicit_systems.items()
            ):

                if system is None:
                    continue

                self._discover_system_capabilities(
                    capabilities,
                    str(
                        system_name
                    ),
                    system,
                )

        return capabilities

    # ==========================================================
    # SYSTEM CAPABILITY DISCOVERY
    #
    # Discovers capabilities exposed by an already-connected
    # SEED system.
    #
    # IMPORTANT:
    #
    # This method DISCOVERS only.
    #
    # It does NOT:
    #
    #     - execute commands
    #     - create commands
    #     - create Qbits
    #     - create queues
    #     - create another command registry
    #     - create Registry
    #     - create Nodes
    #     - create NeuralBridge
    #
    # Discovered capabilities are returned to:
    #
    #     _discover_command_capabilities()
    #
    # which ultimately populates:
    #
    #     self.command_registry
    #
    # The SAME registry is consumed by:
    #
    #     execute_command()
    #
    # QbitDialer remains the SINGLE command authority.
    # ==========================================================

    def _discover_system_capabilities(
        self,
        capabilities,
        system_name,
        system,
    ):

        if system is None:

            return

        if not isinstance(
            capabilities,
            dict,
        ):

            return

        system_name = str(
            system_name
        ).strip()

        if not system_name:

            system_name = "SYSTEM"

        # ======================================================
        # EXPLICIT COMMAND DICTIONARY
        #
        # Preferred dynamic interface.
        #
        # These are DISCOVERED here.
        #
        # They are NOT executed here.
        # ======================================================

        try:

            command_map = getattr(
                system,
                "qbit_commands",
                None,
            )

        except Exception:

            command_map = None

        if isinstance(
            command_map,
            dict,
        ):

            for command_name, handler in (
                command_map.items()
            ):

                if not isinstance(
                    command_name,
                    str,
                ):

                    continue

                if not callable(
                    handler
                ):

                    continue

                name = (
                    command_name
                    .strip()
                    .upper()
                )

                if not name:

                    continue

                # --------------------------------------------------
                # Do not replace an existing authoritative
                # QbitDialer capability during discovery.
                #
                # First registration wins.
                # --------------------------------------------------

                if name in capabilities:

                    continue

                capabilities[
                    name
                ] = {
                    "handler": handler,
                    "source": "SYSTEM",
                    "system": system_name,
                    "method": getattr(
                        handler,
                        "__name__",
                        repr(handler),
                    ),
                    "learned": True,
                }

        # ======================================================
        # METHOD CAPABILITY DISCOVERY
        #
        # Supported explicit markers:
        #
        #     __qbit_command__ = "COMMAND"
        #
        #     __qbit_commands__ = [
        #         "COMMAND_A",
        #         "COMMAND_B",
        #     ]
        #
        # Only explicitly marked methods are discovered.
        #
        # Arbitrary public methods are NOT exposed as commands.
        # ======================================================

        try:

            method_names = dir(
                system
            )

        except Exception:

            method_names = ()

        for method_name in method_names:

            try:

                method = getattr(
                    system,
                    method_name,
                    None,
                )

            except Exception:

                continue

            if not callable(
                method
            ):

                continue

            # ==================================================
            # SINGLE-COMMAND MARKER
            # ==================================================

            try:

                command_name = getattr(
                    method,
                    "__qbit_command__",
                    None,
                )

            except Exception:

                command_name = None

            if isinstance(
                command_name,
                str,
            ):

                name = (
                    command_name
                    .strip()
                    .upper()
                )

                if (
                    name
                    and name not in capabilities
                ):

                    capabilities[
                        name
                    ] = {
                        "handler": method,
                        "source": "SYSTEM",
                        "system": system_name,
                        "method": method_name,
                        "learned": True,
                    }

            # ==================================================
            # MULTI-COMMAND MARKER
            # ==================================================

            try:

                command_names = getattr(
                    method,
                    "__qbit_commands__",
                    None,
                )

            except Exception:

                command_names = None

            if not isinstance(
                command_names,
                (
                    list,
                    tuple,
                    set,
                ),
            ):

                continue

            for command_name in command_names:

                if not isinstance(
                    command_name,
                    str,
                ):

                    continue

                name = (
                    command_name
                    .strip()
                    .upper()
                )

                if (
                    not name
                    or name in capabilities
                ):

                    continue

                capabilities[
                    name
                ] = {
                    "handler": method,
                    "source": "SYSTEM",
                    "system": system_name,
                    "method": method_name,
                    "learned": True,
                }
    # ==========================================================
    # DYNAMIC COMMAND REGISTRATION
    #
    # Allows a running SEED subsystem to expose a newly learned
    # capability without rebuilding QbitDialer.
    #
    # This does NOT execute the command.
    #
    # It only makes an explicitly supplied callable available
    # to the authoritative QbitDialer command plane.
    #
    # COMMAND FLOW:
    #
    #     SYSTEM
    #        â†“
    # register_command_capability()
    #        â†“
    # command_catalog
    #        â†“
    # command_registry
    #        â†“
    # execute_command()
    #        â†“
    # _execute_qbit_command()
    #        â†“
    # handler
    #
    # QbitDialer remains the SINGLE command authority.
    # ==========================================================

    def register_command_capability(
        self,
        name,
        handler,
        system=None,
        source="SYSTEM",
        metadata=None,
    ):

        # ======================================================
        # VALIDATE COMMAND NAME
        # ======================================================

        if not isinstance(
            name,
            str,
        ):

            raise TypeError(
                "command name must be a string"
            )

        name = (
            name
            .strip()
            .upper()
        )

        if not name:

            raise ValueError(
                "command name cannot be empty"
            )

        # ======================================================
        # VALIDATE HANDLER
        # ======================================================

        if not callable(
            handler
        ):

            raise TypeError(
                "command handler must be callable"
            )

        # ======================================================
        # NORMALIZE METADATA
        # ======================================================

        metadata = (
            dict(
                metadata
            )
            if isinstance(
                metadata,
                dict,
            )
            else {}
        )

        method_name = getattr(
            handler,
            "__name__",
            None,
        )

        system_name = (
            system
            if isinstance(
                system,
                str,
            )
            else (
                type(system).__name__
                if system is not None
                else None
            )
        )

        # ======================================================
        # ENSURE COMMAND PLANE
        #
        # This method may be called after boot, so do not assume
        # the registration dictionaries already exist.
        # ======================================================

        if not isinstance(
            getattr(
                self,
                "command_catalog",
                None,
            ),
            dict,
        ):

            self.command_catalog = {}

        if not isinstance(
            getattr(
                self,
                "command_registry",
                None,
            ),
            dict,
        ):

            self.command_registry = {}

        if not isinstance(
            getattr(
                self,
                "command_plane",
                None,
            ),
            dict,
        ):

            self.command_plane = {}

        if not hasattr(
            self,
            "command_lock",
        ):

            self.command_lock = threading.RLock()

        # ======================================================
        # AUTHORITATIVE REGISTRATION
        #
        # Both structures are updated under the SAME lock.
        #
        # command_catalog = capability metadata
        #
        # command_registry = executable handler
        # ======================================================

        with self.command_lock:

            self.command_catalog[
                name
            ] = {
                "name": name,
                "source": source,
                "authority": "QbitDialer",
                "state": "EXECUTABLE",
                "system": system_name,
                "method": method_name,
                "learned": True,
                **metadata,
            }

            self.command_registry[
                name
            ] = handler

            # ==================================================
            # RECOMPUTE COMMAND-PLANE STATE
            # ==================================================

            cataloged = len(
                self.command_catalog
            )

            executable = sum(
                1
                for registered_handler
                in self.command_registry.values()
                if callable(
                    registered_handler
                )
            )

            pending = max(
                0,
                cataloged - executable,
            )

            self.command_plane.update({
                "online": True,
                "active": bool(
                    executable
                ),
                "authority": "QbitDialer",
                "registry": self.command_registry,
                "cataloged": cataloged,
                "executable": executable,
                "pending": pending,
                "dynamic": True,
                "version": (
                    "DYNAMIC-CAPABILITY-PLANE"
                ),
                "health": (
                    "GREEN"
                    if executable
                    else "YELLOW"
                ),
                "state": (
                    "ONLINE"
                    if executable
                    else "WAITING_FOR_COMMAND_REGISTRY"
                ),
            })

        # ======================================================
        # LOG AUTHORITATIVE REGISTRATION
        # ======================================================

        self.logger.info(
            "[QbitDialer] Dynamic command capability registered | "
            "command=%s | system=%s | method=%s | "
            "executable=%s",
            name,
            system_name,
            method_name,
            callable(
                handler
            ),
        )

        # ======================================================
        # RETURN REGISTRATION RESULT
        # ======================================================

        return {
            "status": "registered",
            "command": name,
            "system": system_name,
            "method": method_name,
            "dynamic": True,
            "authority": "QbitDialer",
            "state": "EXECUTABLE",
        }

    # ==========================================================
    # SKILL COMMAND CAPABILITY
    #
    # A skill is a dynamic command capability, not a second
    # execution authority. The callable remains behind the
    # QbitDialer command registry and can be added or replaced
    # without rebuilding the runtime.
    # ==========================================================

    def register_skill_command(
        self,
        skill,
        handler,
        *,
        source="SKILL",
        metadata=None,
    ):
        if not isinstance(skill, str) or not skill.strip():
            raise ValueError("skill name cannot be empty")
        skill_name = skill.strip().upper()
        command_name = skill_name
        command_metadata = dict(metadata or {})
        command_metadata.update({
            "skill": skill_name,
            "command_type": "SKILL",
            "dynamic": True,
            "learned": True,
        })
        return self.register_command_capability(
            command_name,
            handler,
            system="Skill",
            source=source,
            metadata=command_metadata,
        )

    def update_skill_command(
        self,
        skill,
        handler,
        *,
        metadata=None,
    ):
        return self.register_skill_command(
            skill,
            handler,
            source="SKILL_UPDATE",
            metadata=metadata,
        )

    def handle_skill_reference(self, envelope=None, **kwargs):
        """Validate a dynamic skill reference without bypassing Dialer authority."""
        data = envelope if isinstance(envelope, dict) else {}
        skill = data.get("skill") or data.get("name") or kwargs.get("skill")
        if not isinstance(skill, str) or not skill.strip():
            return {"status": "rejected", "reason": "skill_reference_missing"}
        skill_name = skill.strip().upper()
        registry = getattr(self, "skill_registry", None)
        known = False
        if isinstance(registry, dict):
            known = any(
                str(key).upper() == skill_name
                or skill_name in str(key).upper()
                for key in registry.keys()
            )
        return {
            "status": "accepted" if known else "deferred",
            "skill": skill_name,
            "command_type": "SKILL",
            "dynamic": True,
            "known": known,
            "authority": "QbitDialer",
            "admission": "submit_command",
        }

    # ==========================================================
    # REFRESH COMMAND CAPABILITIES
    #
    # SEED can call this after a subsystem learns/exposes a new
    # capability.
    #
    # No queue.
    # No loop.
    # No duplicate executor.
    #
    # QbitDialer remains the SINGLE command authority.
    # ==========================================================

    def refresh_command_capabilities(
        self,
    ):

        # ======================================================
        # DISCOVER CURRENT CAPABILITIES
        # ======================================================

        try:

            discovered = (
                self._discover_command_capabilities()
            )

            if not isinstance(
                discovered,
                dict,
            ):

                discovered = {}

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] Command capability refresh failed | "
                "existing registry preserved | "
                "error=%s: %s",
                type(exc).__name__,
                exc,
            )

            return self.get_command_capabilities()

        # ======================================================
        # ENSURE COMMAND PLANE
        # ======================================================

        if not isinstance(
            getattr(
                self,
                "command_catalog",
                None,
            ),
            dict,
        ):

            self.command_catalog = {}

        if not isinstance(
            getattr(
                self,
                "command_registry",
                None,
            ),
            dict,
        ):

            self.command_registry = {}

        if not isinstance(
            getattr(
                self,
                "command_plane",
                None,
            ),
            dict,
        ):

            self.command_plane = {}

        if not hasattr(
            self,
            "command_lock",
        ):

            self.command_lock = threading.RLock()

        # ======================================================
        # REGISTER DISCOVERED CAPABILITIES
        #
        # IMPORTANT:
        #
        # Refresh adds/updates capabilities.
        #
        # It does NOT delete commands that were previously
        # registered dynamically.
        # ======================================================

        with self.command_lock:

            for command_name, capability in (
                discovered.items()
            ):

                if not isinstance(
                    capability,
                    dict,
                ):

                    continue

                name = (
                    str(
                        command_name
                    )
                    .strip()
                    .upper()
                )

                if not name:

                    continue

                handler = capability.get(
                    "handler"
                )

                # --------------------------------------------------
                # Catalog the capability even when no executable
                # handler currently exists.
                # --------------------------------------------------

                if not callable(
                    handler
                ):

                    self.command_catalog[
                        name
                    ] = {
                        "name": name,
                        "source": capability.get(
                            "source",
                            "SYSTEM",
                        ),
                        "authority": "QbitDialer",
                        "state": "PENDING",
                        "system": capability.get(
                            "system"
                        ),
                        "method": capability.get(
                            "method"
                        ),
                        "learned": bool(
                            capability.get(
                                "learned",
                                True,
                            )
                        ),
                    }

                    continue

                # --------------------------------------------------
                # Authoritative executable registry.
                # --------------------------------------------------

                self.command_registry[
                    name
                ] = handler

                # --------------------------------------------------
                # Authoritative command catalog.
                # --------------------------------------------------

                self.command_catalog[
                    name
                ] = {
                    "name": name,
                    "source": capability.get(
                        "source",
                        "SYSTEM",
                    ),
                    "authority": "QbitDialer",
                    "state": "EXECUTABLE",
                    "system": capability.get(
                        "system"
                    ),
                    "method": capability.get(
                        "method"
                    ),
                    "learned": bool(
                        capability.get(
                            "learned",
                            True,
                        )
                    ),
                }

            # ==================================================
            # RECOMPUTE AUTHORITATIVE COMMAND STATE
            # ==================================================

            cataloged = len(
                self.command_catalog
            )

            executable = sum(
                1
                for handler
                in self.command_registry.values()
                if callable(
                    handler
                )
            )

            pending = max(
                0,
                cataloged - executable,
            )

            self.command_plane.update({
                "online": True,
                "active": bool(
                    executable
                ),
                "authority": "QbitDialer",
                "registry": self.command_registry,
                "cataloged": cataloged,
                "executable": executable,
                "pending": pending,
                "dynamic": True,
                "version": (
                    "DYNAMIC-CAPABILITY-PLANE"
                ),
                "health": (
                    "GREEN"
                    if executable
                    else "YELLOW"
                ),
                "state": (
                    "ONLINE"
                    if executable
                    else "WAITING_FOR_COMMAND_REGISTRY"
                ),
            })

        # ======================================================
        # DIAGNOSTIC COMMAND LIST
        # ======================================================

        with self.command_lock:

            executable_commands = sorted(
                name
                for name, handler
                in self.command_registry.items()
                if callable(
                    handler
                )
            )

        self.logger.info(
            "[QbitDialer] Command capabilities refreshed | "
            "cataloged=%d | executable=%d | "
            "commands=%s",
            cataloged,
            executable,
            executable_commands,
        )

        return self.get_command_capabilities()


    # ==========================================================
    # COMMAND REGISTRY / CAPABILITY STATE
    #
    # QbitDialer is the authoritative command authority.
    #
    # command_catalog:
    #
    #     Commands SEED/Qbit knows about.
    #
    # command_registry:
    #
    #     Commands QbitDialer can execute NOW.
    #
    # A command can therefore be:
    #
    #     CATALOGED
    #     EXECUTABLE
    #     PENDING
    #     UNKNOWN
    #
    # This method does NOT register commands.
    # This method does NOT create handlers.
    # This method does NOT execute commands.
    # ==========================================================

    def get_command_list(
        self,
        executable_only=False,
    ):

        command_lock = getattr(
            self,
            "command_lock",
            None,
        )

        # ======================================================
        # SNAPSHOT UNDER AUTHORITATIVE COMMAND LOCK
        # ======================================================

        if command_lock is not None:

            with command_lock:

                catalog = dict(
                    getattr(
                        self,
                        "command_catalog",
                        {},
                    )
                    or {}
                )

                registry = dict(
                    getattr(
                        self,
                        "command_registry",
                        {},
                    )
                    or {}
                )

        else:

            catalog = dict(
                getattr(
                    self,
                    "command_catalog",
                    {},
                )
                or {}
            )

            registry = dict(
                getattr(
                    self,
                    "command_registry",
                    {},
                )
                or {}
            )

        # ======================================================
        # EXECUTABLE COMMANDS
        # ======================================================

        executable = sorted(
            str(
                name
            ).strip().upper()
            for name, handler
            in registry.items()
            if callable(
                handler
            )
            and str(
                name
            ).strip()
        )

        # ======================================================
        # CATALOGED COMMANDS
        # ======================================================

        if isinstance(
            catalog,
            dict,
        ):

            cataloged = sorted(
                set(
                    str(
                        name
                    ).strip().upper()
                    for name in catalog.keys()
                    if str(
                        name
                    ).strip()
                )
            )

        else:

            try:

                cataloged = sorted(
                    set(
                        str(
                            name
                        ).strip().upper()
                        for name in catalog
                        if str(
                            name
                        ).strip()
                    )
                )

            except Exception:

                cataloged = []

        # ======================================================
        # PRESERVE EXECUTABLE COMMANDS
        #
        # Older runtimes may contain executable handlers that
        # were not yet written into command_catalog.
        # ======================================================

        cataloged = sorted(
            set(
                cataloged
            ).union(
                executable
            )
        )

        executable_set = set(
            executable
        )

        cataloged_set = set(
            cataloged
        )

        # ======================================================
        # CATALOGED BUT NOT EXECUTABLE
        # ======================================================

        pending = sorted(
            cataloged_set
            - executable_set
        )

        # ======================================================
        # SYNCHRONIZE COMMAND PLANE
        # ======================================================

        try:

            self.command_plane.update({
                "online": True,
                "authority": "QbitDialer",
                "cataloged": len(
                    cataloged
                ),
                "executable": len(
                    executable
                ),
                "pending": len(
                    pending
                ),
                "dynamic": True,
                "health": (
                    "GREEN"
                    if executable
                    else "YELLOW"
                ),
                "state": (
                    "ONLINE"
                    if executable
                    else "WAITING_FOR_COMMAND_REGISTRY"
                ),
            })

        except Exception:

            pass

        # ======================================================
        # RETURN COMMAND LIST
        # ======================================================

        if executable_only:

            return executable

        return cataloged


    # ==========================================================
    # COMMAND CAPABILITY SNAPSHOT
    #
    # Full state for Qbit / planning / health / learning.
    #
    # This method does NOT execute commands.
    # ==========================================================

    def get_command_capabilities(
        self,
    ):

        command_lock = getattr(
            self,
            "command_lock",
            None,
        )

        # ======================================================
        # SNAPSHOT AUTHORITATIVE REGISTRIES
        # ======================================================

        if command_lock is not None:

            with command_lock:

                catalog = dict(
                    getattr(
                        self,
                        "command_catalog",
                        {},
                    )
                    or {}
                )

                registry = dict(
                    getattr(
                        self,
                        "command_registry",
                        {},
                    )
                    or {}
                )

        else:

            catalog = dict(
                getattr(
                    self,
                    "command_catalog",
                    {},
                )
                or {}
            )

            registry = dict(
                getattr(
                    self,
                    "command_registry",
                    {},
                )
                or {}
            )

        # ======================================================
        # NORMALIZE CATALOG
        # ======================================================

        cataloged = sorted(
            set(
                str(
                    name
                ).strip().upper()
                for name in catalog.keys()
                if str(
                    name
                ).strip()
            )
        )

        # ======================================================
        # RESOLVE EXECUTABLE HANDLERS
        # ======================================================

        executable = sorted(
            str(
                name
            ).strip().upper()
            for name, handler
            in registry.items()
            if callable(
                handler
            )
            and str(
                name
            ).strip()
        )

        cataloged_set = set(
            cataloged
        )

        executable_set = set(
            executable
        )

        # ======================================================
        # KNOWN BUT NOT EXECUTABLE
        # ======================================================

        pending = sorted(
            cataloged_set
            - executable_set
        )

        # ======================================================
        # RUNTIME STATE
        # ======================================================

        running = bool(
            getattr(
                self,
                "_running",
                False,
            )
        )

        # ======================================================
        # FULL CAPABILITY SNAPSHOT
        # ======================================================

        return {

            "authority": "QbitDialer",

            "state": (
                "ONLINE"
                if running
                else "OFFLINE"
            ),

            "health": (
                "GREEN"
                if running
                else "RED"
            ),

            "cataloged": cataloged,

            "executable": executable,

            "pending": pending,

            "counts": {

                "cataloged": len(
                    cataloged
                ),

                "executable": len(
                    executable
                ),

                "pending": len(
                    pending
                ),
            },

            "command_plane": {
                "dynamic": True,
                "authority": "QbitDialer",
                "online": bool(
                    getattr(
                        self,
                        "command_plane",
                        {},
                    ).get(
                        "online",
                        False,
                    )
                ),
            },
        }


    # ==========================================================
    # COMMAND SUBMISSION
    #
    # THIS IS THE AUTHORITATIVE COMMAND ENTRY POINT.
    #
    # Everything that becomes an executable command eventually
    # comes here:
    #
    #     external command
    #     cognitive intent
    #     transformed thought
    #
    # IMPORTANT IDENTITY RULE
    # -----------------------
    #
    # Qbit owns:
    #
    #     qbit_id
    #     track_id
    #     state
    #
    # ComputeBrain DECODES the Qbit.
    #
    # TransformerBrain ENCODE/BUILDs the resulting action.
    #
    # submit_command() DOES NOT:
    #
    #     - decode Qbits
    #     - stringify Qbits
    #     - manufacture Qbit identity
    #     - manufacture Track IDs
    #     - interpret Qbit objects as command names
    #     - create a command registry
    #     - create a command queue
    #
    # COMMAND FLOW:
    #
    #     INPUT COMMAND ENVELOPE
    #             |
    #             v
    #         normalize
    #             |
    #             v
    #      command_registry
    #             |
    #             v
    #   authoritative command_queue
    #             |
    #             v
    #       QbitQueueLoop
    #             |
    #             v
    #       execute_command()
    #             |
    #             v
    #   _execute_qbit_command()
    #             |
    #             v
    #          handler
    #
    # RAW QBIT FLOW IS SEPARATE:
    #
    #     RAW QBIT
    #        |
    #        v
    #   _process_received_qbit()
    #        |
    #        v
    #    ComputeBrain
    #        |
    #        v
    #   ThoughtPacket
    #        |
    #        v
    # TransformerBrain
    #        |
    #        v
    # Command Envelope
    #        |
    #        v
    # submit_command()
    #
    # ONE COMMAND AUTHORITY.
    # ONE COMMAND QUEUE.
    # ==========================================================

    def submit_command(
        self,
        command,
    ):
        # ======================================================
        # HARD NESTED-QBIT BOUNDARY
        #
        # A command envelope may carry:
        #
        #     "qbit": <Qbit>
        #
        # but NEVER:
        #
        #     "name": <Qbit>
        #     "command": <Qbit>
        #     "action": <Qbit>
        #     "cmd": <Qbit>
        #
        # If a producer accidentally places the Qbit in the
        # command-name position, recover the EXISTING Qbit and
        # route it through the established Qbit receive path.
        #
        # No new Qbit.
        # No new queue.
        # No new loop.
        # ======================================================

        if isinstance(
            command,
            dict,
        ):

            qbit_type = globals().get(
                "Qbit",
                None,
            )

            for field_name in (
                "name",
                "command",
                "action",
                "cmd",
            ):

                candidate = command.get(
                    field_name
                )

                if (
                    qbit_type is not None
                    and isinstance(
                        candidate,
                        qbit_type,
                    )
                ):

                    self.logger.warning(
                        "[QbitDialer] Invalid command envelope | "
                        "Qbit object found in %s | "
                        "routing raw Qbit to receive pipeline",
                        field_name,
                    )

                    # ------------------------------------------
                    # Do not normalize the Qbit.
                    #
                    # An async caller must use:
                    #
                    #     submit_qbit_command(qbit)
                    #
                    # The synchronous command path cannot await
                    # the cognitive pipeline here.
                    # ------------------------------------------

                    return {
                        "status": "rejected",
                        "stage": "command_submission",
                        "reason": "qbit_in_command_name_position",
                        "route": "submit_qbit_command",
                        "qbit_id": (
                            self._extract_qbit_field(
                                candidate,
                                "qbit_id",
                                self._extract_qbit_field(
                                    candidate,
                                    "id",
                                    None,
                                ),
                            )
                        ),
                        "track_id": (
                            self._extract_qbit_field(
                                candidate,
                                "track_id",
                                None,
                            )
                        ),
                    }

        # ======================================================
        # HARD RAW-QBIT BOUNDARY
        #
        # submit_command() receives COMMAND ENVELOPES.
        #
        # A raw Qbit belongs to the cognitive receive pipeline.
        #
        # IMPORTANT:
        #
        # We do NOT call str(command).
        # We do NOT normalize a raw Qbit.
        # We do NOT extract a fake command name from it.
        #
        # The actual raw-Qbit routing is performed by:
        #
        #     execute_command()
        #
        # and:
        #
        #     submit_qbit_command()
        #
        # before command normalization occurs.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                command,
                qbit_type,
            )
        ):

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            self.logger.warning(
                "[QbitDialer] Raw Qbit cannot enter "
                "command submission directly | "
                "route=_process_received_qbit"
            )

            return {
                "status": "rejected",
                "stage": "command_submission",
                "reason": "raw_qbit_requires_cognitive_pipeline",
                "route": "_process_received_qbit",
            }

        # ======================================================
        # NORMALIZE COMMAND ENVELOPE
        # ======================================================

        try:

            normalized = self._normalize_command(
                command
            )

        except Exception as exc:

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            self.logger.exception(
                "[QbitDialer] Command normalization failed | "
                "error=%s: %s",
                type(exc).__name__,
                exc,
            )

            return {
                "status": "rejected",
                "reason": "normalization_error",
                "error": str(exc),
                "error_type": type(exc).__name__,
            }

        # ======================================================
        # REQUIRE COMMAND ENVELOPE
        # ======================================================

        if not isinstance(
            normalized,
            dict,
        ):

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            self.logger.warning(
                "[QbitDialer] Rejected non-dict command "
                "after normalization | type=%s",
                type(normalized).__name__,
            )

            return {
                "status": "rejected",
                "reason": "invalid_command_envelope",
            }

        # ======================================================
        # COMMAND NAME
        #
        # The command name MUST already exist as command data.
        #
        # It must NOT come from:
        #
        #     str(qbit)
        #     repr(qbit)
        #     qbit.__str__()
        # ======================================================

        name = (
            normalized.get(
                "name"
            )
            or normalized.get(
                "command"
            )
            or normalized.get(
                "action"
            )
        )

        if name is None:

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        if not isinstance(
            name,
            str,
        ):

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            return {
                "status": "rejected",
                "reason": "invalid_command_name",
                "type": type(name).__name__,
            }

        name = name.strip().upper()

        if not name:

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        normalized["name"] = name

        # ======================================================
        # PRESERVE QBIT IDENTITY
        #
        # Qbit identity is authoritative.
        #
        # We only COPY identity that already exists.
        #
        # We NEVER generate:
        #
        #     qbit_id
        #     track_id
        #
        # here.
        # ======================================================

        qbit_id = normalized.get(
            "qbit_id"
        )

        track_id = normalized.get(
            "track_id"
        )

        attached_qbit = normalized.get(
            "qbit"
        )

        if attached_qbit is not None:

            attached_qbit_id = (
                self._extract_qbit_field(
                    attached_qbit,
                    "qbit_id",
                    None,
                )
            )

            if attached_qbit_id is None:

                attached_qbit_id = (
                    self._extract_qbit_field(
                        attached_qbit,
                        "id",
                        None,
                    )
                )

            attached_track_id = (
                self._extract_qbit_field(
                    attached_qbit,
                    "track_id",
                    None,
                )
            )

            # --------------------------------------------------
            # Preserve authoritative Qbit identity.
            # --------------------------------------------------

            if (
                qbit_id is None
                and attached_qbit_id is not None
            ):

                qbit_id = attached_qbit_id

                normalized[
                    "qbit_id"
                ] = qbit_id

            if (
                track_id is None
                and attached_track_id is not None
            ):

                track_id = attached_track_id

                normalized[
                    "track_id"
                ] = track_id

        # ======================================================
        # COMMAND REGISTRY
        #
        # command_registry is the ONLY executable registry.
        # ======================================================

        with self.command_lock:

            registry = getattr(
                self,
                "command_registry",
                None,
            )

            if not isinstance(
                registry,
                dict,
            ):

                registry = {}

            handler = registry.get(
                name
            )

            if not callable(
                handler
            ):

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

                available = sorted(
                    str(
                        command_name
                    ).strip().upper()
                    for command_name
                    in registry.keys()
                    if str(
                        command_name
                    ).strip()
                )

                self.logger.warning(
                    "[QbitDialer] Command not executable | "
                    "command=%s | qbit_id=%s | "
                    "track_id=%s | available=%s",
                    name,
                    qbit_id,
                    track_id,
                    available,
                )

                return {
                    "status": "rejected",
                    "command": name,
                    "reason": "unknown_command",
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "available": available,
                }

            self.commands_received = (
                getattr(
                    self,
                    "commands_received",
                    0,
                )
                + 1
            )

        # ======================================================
        # ACTION SECURITY GATE
        #
        # Evaluate the final command envelope after normalization
        # and identity attachment, before queue admission.
        # ======================================================

        security = getattr(self, "security", None)
        if security is not None:
            actor = normalized.get("actor") or normalized.get("user") or normalized.get("user_id")
            if actor:
                security.set_actor(actor)

            decision = security.evaluate_action(
                normalized,
                track_id=track_id,
                qbit_id=qbit_id,
                source=normalized.get("source"),
                target=normalized.get("target") or normalized.get("resource"),
                reason=normalized.get("reason"),
                user_authorized=normalized.get("user_authorized", False),
            )

            normalized["security_decision"] = decision.get("allowed", False)
            normalized["security_actor"] = decision.get("actor")

            if not decision.get("allowed", False):
                with self.command_lock:
                    self.commands_rejected = getattr(self, "commands_rejected", 0) + 1
                self.logger.warning(
                    "[QbitDialer] Action blocked by security | command=%s | qbit_id=%s | track_id=%s",
                    name, qbit_id, track_id,
                )
                return {
                    "status": "rejected",
                    "command": name,
                    "reason": "security_denied",
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "security": decision,
                }

        # ======================================================
        # AUTHORITATIVE COMMAND QUEUE
        #
        # NEVER create a queue here.
        #
        # The boot/runtime layer must already have supplied:
        #
        #     self.command_queue
        # ======================================================

        transport_loop = (
            getattr(self, "qbit_queue_loop", None)
            or getattr(self, "queue_loop", None)
        )
        command_queue = getattr(
            self,
            "command_queue",
            None,
        )

        if transport_loop is None and command_queue is None:

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            self.logger.error(
                "[QbitDialer] Command rejected | "
                "authoritative command queue not bound | "
                "command=%s | qbit_id=%s | track_id=%s",
                name,
                qbit_id,
                track_id,
            )

            return {
                "status": "rejected",
                "command": name,
                "reason": "command_queue_unavailable",
                "qbit_id": qbit_id,
                "track_id": track_id,
            }

        # ======================================================
        # QUEUE COMMAND
        #
        # IMPORTANT:
        #
        # submit_command() is synchronous.
        #
        # Therefore an asyncio.Queue must use:
        #
        #     put_nowait()
        #
        # We NEVER create another queue and NEVER silently
        # execute the command here.
        # ======================================================

        try:

            if transport_loop is not None and callable(
                getattr(transport_loop, "put", None)
            ):
                accepted = transport_loop.put(
                    normalized,
                    priority=normalized.get("priority"),
                )
                if accepted is False:
                    raise RuntimeError(
                        "authoritative QbitQueueLoop rejected command"
                    )
            else:
                put_nowait = getattr(
                    command_queue,
                    "put_nowait",
                    None,
                )

                if callable(put_nowait):
                    put_nowait(normalized)
                else:
                    put = getattr(command_queue, "put", None)
                    if not callable(put):
                        raise RuntimeError(
                            "authoritative command transport has no put interface"
                        )
                    result = put(normalized)
                    if inspect.isawaitable(result):
                        raise RuntimeError(
                            "legacy command queue exposes async put()"
                        )

        except Exception as exc:

            with self.command_lock:

                self.commands_rejected = (
                    getattr(
                        self,
                        "commands_rejected",
                        0,
                    )
                    + 1
                )

            self.logger.exception(
                "[QbitDialer] Command queue submission failed | "
                "command=%s | qbit_id=%s | track_id=%s | "
                "error=%s: %s",
                name,
                qbit_id,
                track_id,
                type(exc).__name__,
                exc,
            )

            return {
                "status": "rejected",
                "command": name,
                "reason": "queue_submission_error",
                "error": str(exc),
                "error_type": type(exc).__name__,
                "qbit_id": qbit_id,
                "track_id": track_id,
            }

        # ======================================================
        # QUEUE ACCOUNTING
        # ======================================================

        with self.command_lock:

            self.commands_queued = (
                getattr(
                    self,
                    "commands_queued",
                    0,
                )
                + 1
            )

            command_plane = getattr(
                self,
                "command_plane",
                None,
            )

            if isinstance(
                command_plane,
                dict,
            ):

                command_plane[
                    "last_command"
                ] = name

                command_plane[
                    "last_command_time"
                ] = time.time()

                command_plane[
                    "authority"
                ] = "QbitDialer"

                command_plane[
                    "online"
                ] = True

                command_plane[
                    "last_qbit_id"
                ] = qbit_id

                command_plane[
                    "last_track_id"
                ] = track_id

        # ======================================================
        # FINAL ADMISSION LOG
        # ======================================================

        self.logger.info(
            "[QbitDialer] COMMAND ADMITTED | "
            "command=%s | qbit_id=%s | track_id=%s",
            name,
            qbit_id,
            track_id,
        )

        return {
            "status": "queued",
            "command": name,
            "qbit_id": qbit_id,
            "track_id": track_id,
        }


    # ==========================================================
    # QBIT COMMAND ENTRY
    #
    # ONE AUTHORITATIVE COMMAND PATH.
    #
    # QbitQueueLoop transports/delivers.
    # QbitDialer processes/adjudicates/executes.
    #
    # RAW Qbits are DATA, not commands.
    #
    # RAW Qbit RECEIVE PATH:
    #
    #     Qbit
    #       â†“
    #     ComputeBrain
    #       â†“
    #     TransformerBrain
    #       â†“
    #     Command Envelope
    #       â†“
    #     QbitDialer.submit_command()
    #
    # No second queue.
    # No second QbitQueueLoop.
    # No Qbit creation.
    # ==========================================================

    async def submit_qbit_command(
        self,
        command,
    ):

        # ======================================================
        # RAW QBIT DETECTION
        #
        # A Qbit is DATA, not a command.
        #
        # Preserve the Qbit's existing identity.
        #
        # Do NOT:
        #
        #     create another Qbit
        #     generate another qbit_id
        #     create another track
        #     place the Qbit into another queue
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                command,
                qbit_type,
            )
        ):

            qbit_id = getattr(
                command,
                "qbit_id",
                None,
            )

            track_id = getattr(
                command,
                "track_id",
                None,
            )

            if track_id is None:

                track_id = getattr(
                    command,
                    "track",
                    None,
                )

            # --------------------------------------------------
            # Existing Qbit must already have identity.
            # --------------------------------------------------

            if qbit_id is None:

                self.logger.warning(
                    "[QbitDialer] Raw Qbit rejected: "
                    "missing qbit_id | qbit=%r",
                    command,
                )

                return {
                    "status": "rejected",
                    "stage": "qbit_receive",
                    "reason": "qbit_id_missing",
                    "qbit_id": None,
                    "track_id": track_id,
                }

            # --------------------------------------------------
            # Preserve existing track identity.
            # --------------------------------------------------

            if track_id is not None:

                try:

                    if getattr(
                        command,
                        "track_id",
                        None,
                    ) is None:

                        setattr(
                            command,
                            "track_id",
                            track_id,
                        )

                except Exception:

                    self.logger.debug(
                        "[QbitDialer] Unable to mirror "
                        "existing track identity onto Qbit",
                        exc_info=True,
                    )

            # --------------------------------------------------
            # AUTHORITATIVE RAW-QBIT RECEIVE PATH
            #
            # The existing Qbit is passed directly into the
            # existing cognitive receive pipeline.
            # --------------------------------------------------

            return await self._process_received_qbit(
                command
            )

        # ======================================================
        # COMMAND ENVELOPE
        #
        # Already-formed command envelopes use the SAME
        # authoritative command admission path.
        #
        # No second queue.
        # No direct handler invocation.
        # ======================================================

        result = self.submit_command(
            command
        )

        if inspect.isawaitable(
            result
        ):

            result = await result

        return result

    # ==========================================================
    # COGNITIVE COMMAND FINALIZATION
    #
    # This method owns the bridge:
    #
    #     ComputeBrain
    #          â†“
    #     TransformerBrain
    #          â†“
    #     _build_cognitive_command()
    #          â†“
    #     validation
    #          â†“
    #     QbitDialer.submit_command()
    #
    # IMPORTANT:
    #
    # _build_cognitive_command() is called EXACTLY ONCE.
    #
    # This method does not create a Qbit.
    # This method does not create a queue.
    # This method does not call execute_command().
    # ==========================================================

    async def _finalize_cognitive_command(
        self,
        *,
        qbit,
        cognitive_context,
        compute_result,
        transform_result,
        task_id=None,
        pipeline_id=None,
        qbit_id=None,
        track_id=None,
        source=None,
        channel=None,
        track_context=None,
        task=None,
        health=None,
        action_proposal=None,
    ):

        # ======================================================
        # 19. BUILD ACTION / COMMAND
        #
        # TransformerBrain is the cognitive transformation
        # stage.
        #
        # _build_cognitive_command() is the SINGLE bridge from
        # cognitive output into the executable command envelope.
        # ======================================================
        action_proposal = None

        if isinstance(
            cognitive_context,
            dict,
        ):
            action_proposal = cognitive_context.get(
                "action_proposal"
            )
        try:
            action_proposal = None

            if isinstance(
                cognitive_context,
                dict,
            ):
                action_proposal = (
                    cognitive_context.get(
                        "action_proposal"
                    )
                )

            command = self._build_cognitive_command(
                qbit=qbit,
                compute_result=compute_result,
                transform_result=transform_result,
                action_proposal=action_proposal,
            )

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] Cognitive command build failed | "
                "task_id=%s | qbit_id=%s | track_id=%s | "
                "error=%s",
                task_id,
                qbit_id,
                track_id,
                exc,
            )

            return {
                "status": "command_build_failed",
                "stage": "command_build",
                "task_id": task_id,
                "pipeline_id": pipeline_id,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "source": source,
                "channel": channel,
                "track_context": track_context,
                "thought": compute_result,
                "transform": transform_result,
                "health": health,
                "error": str(exc),
                "error_type": type(exc).__name__,
            }

        # ======================================================
        # 20. COGNITIVE FEEDBACK
        #
        # Feedback is observation/retention.
        #
        # IMPORTANT:
        #
        # This stage MUST NOT create a second command.
        # It MUST NOT submit a second command.
        #
        # If _run_qbit_cognitive_pipeline() is an observation
        # method in this runtime, it may be used here.
        # ======================================================

        cognitive_feedback = None

        feedback_method = getattr(
            self,
            "_run_qbit_cognitive_pipeline",
            None,
        )

        if callable(
            feedback_method
        ):

            try:

                cognitive_feedback = (
                    await feedback_method(
                        qbit=qbit,
                        cognitive_context=cognitive_context,
                        compute_result=compute_result,
                        transform_result=transform_result,
                    )
                )

                if inspect.isawaitable(
                    cognitive_feedback
                ):

                    cognitive_feedback = (
                        await cognitive_feedback
                    )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Cognitive feedback stage failed | "
                    "task_id=%s | qbit_id=%s | track_id=%s | "
                    "error=%s",
                    task_id,
                    qbit_id,
                    track_id,
                    exc,
                )

                cognitive_feedback = {
                    "status": "feedback_failed",
                    "stage": "cognitive_feedback",
                    "task_id": task_id,
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "error": str(exc),
                    "error_type": type(exc).__name__,
                }

        # ======================================================
        # 21. NO COMMAND
        #
        # A cognitive cycle may legitimately produce no
        # executable command.
        # ======================================================

        if command is None:

            feedback_cycle = (
                cognitive_feedback.get(
                    "feedback_cycle_id"
                )
                if isinstance(
                    cognitive_feedback,
                    dict,
                )
                else None
            )

            self.logger.info(
                "[QbitDialer] ThoughtPacket retained as cognitive "
                "feedback | no executable command | "
                "task_id=%s | qbit_id=%s | track_id=%s | "
                "feedback_cycle=%s",
                task_id,
                qbit_id,
                track_id,
                feedback_cycle,
            )

            return (
                cognitive_feedback
                if isinstance(
                    cognitive_feedback,
                    dict,
                )
                else {
                    "status": "no_command",
                    "stage": "cognitive_feedback",
                    **(
                        cognitive_context
                        if isinstance(
                            cognitive_context,
                            dict,
                        )
                        else {}
                    ),
                    "thought": compute_result,
                    "transform": transform_result,
                    "health": health,
                }
            )

        # ======================================================
        # 22. COMMAND ENVELOPE VALIDATION
        #
        # ONLY dictionaries may continue as command envelopes.
        #
        # A raw Qbit must NEVER reach this point as an executable
        # command.
        # ======================================================

        if not isinstance(
            command,
            dict,
        ):

            self.logger.warning(
                "[QbitDialer] Transformer produced invalid "
                "non-dict command output | "
                "task_id=%s | qbit_id=%s | type=%s",
                task_id,
                qbit_id,
                type(command).__name__,
            )

            return {
                "status": "no_command",
                "stage": "command_build",
                **(
                    cognitive_context
                    if isinstance(
                        cognitive_context,
                        dict,
                    )
                    else {}
                ),
                "thought": compute_result,
                "transform": transform_result,
                "health": health,
                "reason": "transformer_command_not_envelope",
            }

        command = dict(
            command
        )

        # ======================================================
        # 23. RESOLVE COMMAND NAME
        #
        # Command identity MUST come from explicit cognitive
        # command data.
        #
        # NEVER:
        #
        #     str(qbit)
        #
        # NEVER infer a command from Qbit representation.
        # ======================================================

        command_name = (
            command.get(
                "name"
            )
            or command.get(
                "command"
            )
            or command.get(
                "cmd"
            )
            or command.get(
                "action"
            )
        )

        # ------------------------------------------------------
        # Explicit nested action envelope:
        #
        #     {"action": {"name": "STATUS"}}
        # ------------------------------------------------------

        if isinstance(
            command_name,
            dict,
        ):

            command_name = (
                command_name.get(
                    "name"
                )
                or command_name.get(
                    "command"
                )
                or command_name.get(
                    "cmd"
                )
            )

        # ------------------------------------------------------
        # Inspect TransformerBrain output only if the builder
        # returned an envelope without a top-level command name.
        # ------------------------------------------------------

        if command_name is None:

            if isinstance(
                transform_result,
                dict,
            ):

                candidate = (
                    transform_result.get(
                        "name"
                    )
                    or transform_result.get(
                        "command"
                    )
                    or transform_result.get(
                        "cmd"
                    )
                    or transform_result.get(
                        "action"
                    )
                )

                if isinstance(
                    candidate,
                    dict,
                ):

                    candidate = (
                        candidate.get(
                            "name"
                        )
                        or candidate.get(
                            "command"
                        )
                        or candidate.get(
                            "cmd"
                        )
                    )

                if (
                    isinstance(
                        candidate,
                        str,
                    )
                    and candidate.strip()
                ):

                    command_name = candidate

        # ------------------------------------------------------
        # Intent is NOT a command.
        # ------------------------------------------------------

        if not isinstance(
            command_name,
            str,
        ):

            self.logger.info(
                "[QbitDialer] ThoughtPacket retained as cognitive "
                "feedback | transformer produced no executable "
                "command name | task_id=%s | qbit_id=%s | "
                "track_id=%s",
                task_id,
                qbit_id,
                track_id,
            )

            return (
                cognitive_feedback
                if isinstance(
                    cognitive_feedback,
                    dict,
                )
                else {
                    "status": "no_command",
                    "stage": "command_validation",
                    **(
                        cognitive_context
                        if isinstance(
                            cognitive_context,
                            dict,
                        )
                        else {}
                    ),
                    "thought": compute_result,
                    "transform": transform_result,
                    "health": health,
                }
            )

        command_name = command_name.strip()

        if not command_name:

            return (
                cognitive_feedback
                if isinstance(
                    cognitive_feedback,
                    dict,
                )
                else {
                    "status": "no_command",
                    "stage": "command_validation",
                    **(
                        cognitive_context
                        if isinstance(
                            cognitive_context,
                            dict,
                        )
                        else {}
                    ),
                    "thought": compute_result,
                    "transform": transform_result,
                    "health": health,
                }
            )

        command[
            "name"
        ] = command_name.upper()

        # ======================================================
        # 24. PRESERVE COMPLETE COGNITIVE COMMAND CONTEXT
        # ======================================================

        command.setdefault(
            "task_id",
            task_id,
        )

        command.setdefault(
            "pipeline_id",
            pipeline_id,
        )

        command.setdefault(
            "qbit",
            qbit,
        )

        command.setdefault(
            "qbit_id",
            qbit_id,
        )

        command.setdefault(
            "track_id",
            track_id,
        )

        command.setdefault(
            "source",
            source,
        )

        command.setdefault(
            "classification",
            cognitive_context.get("classification"),
        )

        command.setdefault(
            "intent",
            cognitive_context.get("intent"),
        )

        command.setdefault(
            "source_of_start",
            cognitive_context.get("source_of_start", source),
        )

        command.setdefault(
            "channel",
            channel,
        )

        command.setdefault(
            "track_context",
            track_context,
        )

        command.setdefault(
            "task",
            task,
        )

        command.setdefault(
            "thought",
            compute_result,
        )

        command.setdefault(
            "transform",
            transform_result,
        )

        command.setdefault(
            "health",
            health,
        )

        command.setdefault(
            "authority",
            "QbitDialer",
        )

        # ======================================================
        # 25. PRESERVE COGNITIVE FIELDS
        #
        # Only fields explicitly produced by TransformerBrain
        # are copied.
        # ======================================================

        if (
            "thought" not in command
            or command["thought"] is None
        ):

            command[
                "thought"
            ] = compute_result

        if (
            "transform" not in command
            or command["transform"] is None
        ):

            command[
                "transform"
            ] = transform_result

        if (
            "intent" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_intent = transform_result.get(
                "intent"
            )

            if explicit_intent is not None:

                command[
                    "intent"
                ] = explicit_intent

        if (
            "action" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_action = transform_result.get(
                "action"
            )

            if explicit_action is not None:

                command[
                    "action"
                ] = explicit_action

        if (
            "compute" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_compute = transform_result.get(
                "compute"
            )

            if explicit_compute is not None:

                command[
                    "compute"
                ] = explicit_compute

        # ======================================================
        # 26. PRESERVE LINEAGE / RELATIONSHIPS
        # ======================================================

        if (
            "lineage" not in command
            and isinstance(
                task,
                dict,
            )
        ):

            command[
                "lineage"
            ] = task.get(
                "data_lineage"
            )

        if (
            "relationships" not in command
            and isinstance(
                task,
                dict,
            )
        ):

            command[
                "relationships"
            ] = task.get(
                "relationships"
            )

        # ======================================================
        # 27. COMMAND ARGUMENT CONTRACT
        # ======================================================

        if command.get(
            "args"
        ) is None:

            command[
                "args"
            ] = []

        if command.get(
            "kwargs"
        ) is None:

            command[
                "kwargs"
            ] = {}

        if command.get(
            "payload"
        ) is None:

            command[
                "payload"
            ] = {}

        # ======================================================
        # 28. AUTHORITATIVE COMMAND ADMISSION
        #
        # ONLY ONE EXECUTABLE HANDOFF.
        #
        #     TransformerBrain
        #            |
        #            v
        #     _build_cognitive_command()
        #            |
        #            v
        #     submit_command()
        #            |
        #            v
        #     authoritative command queue
        #
        # No second queue.
        # No direct handler invocation.
        # No execute_command() here.
        # ======================================================

        self.logger.info(
            "[QbitDialer] ThoughtPacket -> command | "
            "task_id=%s | command=%s | "
            "qbit_id=%s | track_id=%s | "
            "intent=%s | action=%s",
            task_id,
            command[
                "name"
            ],
            qbit_id,
            track_id,
            command.get(
                "intent"
            ),
            command.get(
                "action"
            ),
        )

        result = self.submit_command(
            command
        )

        if inspect.isawaitable(
            result
        ):

            result = await result

        # ======================================================
        # 29. FINAL COGNITIVE RESULT
        # ======================================================

        final_status = (
            result.get(
                "status",
                "unknown",
            )
            if isinstance(
                result,
                dict,
            )
            else "submitted"
        )

        return {

            "status": final_status,

            "stage": "COMMAND_ADMITTED",

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "source": source,

            "channel": channel,

            "track_context": track_context,

            "thought": compute_result,

            "transform": transform_result,

            "command": command,

            "command_result": result,

            "cognitive_feedback": cognitive_feedback,

            "health": health,

        }

# ======================================================
# COMMAND PLANE
# ======================================================


# ======================================================================

    # ==========================================================
    # QBIT FIELD RESOLUTION
    #
    # Safely reads authoritative metadata from either:
    #
    #     dict Qbits / command envelopes
    #
    #     Qbit objects
    #
    #     nested task / track / lineage structures
    #
    # IMPORTANT IDENTITY RULE:
    #
    # Qbit owns:
    #
    #     qbit_id
    #     id
    #     track_id
    #     track
    #
    # This resolver NEVER:
    #
    #     - creates a Qbit
    #     - creates an ID
    #     - creates a TrackID
    #     - converts a Qbit to a string
    #     - interprets Qbit data as a command
    #
    # It only RESOLVES EXISTING DATA.
    #
    # This gives the command/cognitive pipeline one consistent
    # metadata lookup mechanism.
    # ==========================================================

    @staticmethod
    def _extract_qbit_field(
        qbit,
        field_name,
        default=None,
    ):

        if qbit is None:

            return default

        # ======================================================
        # DIRECT DICT RESOLUTION
        # ======================================================

        if isinstance(
            qbit,
            dict,
        ):

            value = qbit.get(
                field_name,
                None,
            )

            if value is not None:

                return value

            # --------------------------------------------------
            # Nested task envelope.
            # --------------------------------------------------

            task = qbit.get(
                "task",
                None,
            )

            if isinstance(
                task,
                dict,
            ):

                value = task.get(
                    field_name,
                    None,
                )

                if value is not None:

                    return value

            # --------------------------------------------------
            # Nested identity envelope.
            # --------------------------------------------------

            identity = qbit.get(
                "identity",
                None,
            )

            if isinstance(
                identity,
                dict,
            ):

                value = identity.get(
                    field_name,
                    None,
                )

                if value is not None:

                    return value

            # --------------------------------------------------
            # Nested relationships.
            # --------------------------------------------------

            relationships = qbit.get(
                "relationships",
                None,
            )

            if isinstance(
                relationships,
                dict,
            ):

                value = relationships.get(
                    field_name,
                    None,
                )

                if value is not None:

                    return value

            # --------------------------------------------------
            # Nested lineage.
            # --------------------------------------------------

            lineage = qbit.get(
                "data_lineage",
                None,
            )

            if isinstance(
                lineage,
                dict,
            ):

                value = lineage.get(
                    field_name,
                    None,
                )

                if value is not None:

                    return value

            return default

        # ======================================================
        # DIRECT OBJECT RESOLUTION
        # ======================================================

        value = getattr(
            qbit,
            field_name,
            None,
        )

        if value is not None:

            return value

        provenance = getattr(qbit, "provenance", None)
        if isinstance(provenance, dict):
            value = provenance.get(field_name)
            if value is not None:
                return value

        # ======================================================
        # IDENTITY COMPATIBILITY
        #
        # qbit_id and id are both established representations
        # of the Qbit's EXISTING identity.
        #
        # Never generate a replacement.
        # ======================================================

        if field_name == "qbit_id":

            value = getattr(
                qbit,
                "id",
                None,
            )

            if value is not None:

                return value

        elif field_name == "id":

            value = getattr(
                qbit,
                "qbit_id",
                None,
            )

            if value is not None:

                return value

        # ======================================================
        # TRACK COMPATIBILITY
        # ======================================================

        if field_name == "track_id":

            track = getattr(
                qbit,
                "track",
                None,
            )

            if isinstance(
                track,
                dict,
            ):

                return (
                    track.get(
                        "track_id"
                    )
                    or track.get(
                        "id"
                    )
                    or default
                )

            if track is not None:

                return (
                    getattr(
                        track,
                        "track_id",
                        None,
                    )
                    or getattr(
                        track,
                        "id",
                        None,
                    )
                    or default
                )

        # ======================================================
        # NESTED TASK OBJECT
        # ======================================================

        task = getattr(
            qbit,
            "task",
            None,
        )

        if isinstance(
            task,
            dict,
        ):

            value = task.get(
                field_name,
                None,
            )

            if value is not None:

                return value

        # ======================================================
        # NESTED IDENTITY OBJECT
        # ======================================================

        identity = getattr(
            qbit,
            "identity",
            None,
        )

        if isinstance(
            identity,
            dict,
        ):

            value = identity.get(
                field_name,
                None,
            )

            if value is not None:

                return value

        # ======================================================
        # NESTED RELATIONSHIP MAP
        # ======================================================

        relationships = getattr(
            qbit,
            "relationships",
            None,
        )

        if isinstance(
            relationships,
            dict,
        ):

            value = relationships.get(
                field_name,
                None,
            )

            if value is not None:

                return value

        # ======================================================
        # NESTED DATA LINEAGE
        # ======================================================

        lineage = getattr(
            qbit,
            "data_lineage",
            None,
        )

        if isinstance(
            lineage,
            dict,
        ):

            value = lineage.get(
                field_name,
                None,
            )

            if value is not None:

                return value

        return default


# ==================================================================
# =====================================================================
    # ==========================================================
    # COGNITIVE STAGE DISPATCH
    #
    # AUTHORITATIVE COGNITIVE LOOP
    #
    #     Qbit
    #       |
    #       v
    #     TrackSystem
    #       |
    #       v
    #     ComputeBrain
    #       |
    #       |  ThoughtPacket
    #       v
    #     TransformerBrain.analyze()
    #       |
    #       |  CognitiveResult
    #       v
    #     QbitDialer
    #       |
    #       |  command admission
    #       v
    #     QbitQueueLoop
    #
    # IMPORTANT:
    #
    # ComputeBrain:
    #     Qbit -> ThoughtPacket
    #
    # TransformerBrain:
    #     ThoughtPacket -> CognitiveResult
    #
    # QbitDialer:
    #     CognitiveResult -> command proposal
    #                    -> authorization
    #                    -> submit_command()
    #
    # Neither brain executes commands.
    #
    # There is ONE cognitive loop.
    # There is ONE Qbit runtime.
    # There is ONE command authority.
    # ==========================================================

    async def _run_cognitive_stage(
        self,
        stage,
        data,
    ):

        # ======================================================
        # 1. NORMALIZE STAGE
        # ======================================================

        stage_name = str(
            stage
        ).strip().lower()

        if stage_name not in (
            "compute",
            "transform",
        ):

            raise ValueError(
                f"Unknown cognitive stage: {stage}"
            )

        # ======================================================
        # 2. RESOLVE AUTHORITATIVE BRAIN
        # ======================================================

        if stage_name == "compute":

            brain = getattr(
                self,
                "compute_brain",
                None,
            )

            if brain is None:

                brain = getattr(
                    self,
                    "ComputeBrain",
                    None,
                )

            if brain is None:

                brain = getattr(
                    self,
                    "computebrain",
                    None,
                )

            brain_name = "ComputeBrain"

        else:

            brain = getattr(
                self,
                "transformer_brain",
                None,
            )

            if brain is None:

                brain = getattr(
                    self,
                    "TransformerBrain",
                    None,
                )

            if brain is None:

                brain = getattr(
                    self,
                    "transformerbrain",
                    None,
                )

            brain_name = "TransformerBrain"

        if brain is None:

            raise RuntimeError(
                f"{brain_name} is not attached to QbitDialer"
            )

        # ======================================================
        # 3. BUILD / PRESERVE SHARED CONTEXT
        # ======================================================

        if isinstance(
            data,
            dict,
        ):

            context = dict(
                data
            )

        else:

            context = {
                "input": data,
            }

        context.setdefault(
            "stage",
            stage_name,
        )

        context.setdefault(
            "authority",
            "QbitDialer",
        )

        context.setdefault(
            "cognitive_authority",
            "QbitDialer",
        )

        # ======================================================
        # 4. RESOLVE QBIT
        # ======================================================

        qbit = context.get(
            "qbit"
        )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

            if qbit is not None:

                context[
                    "qbit"
                ] = qbit

        # ======================================================
        # 5. PRESERVE QBIT IDENTITY
        # ======================================================

        if qbit is not None:

            context.setdefault(
                "qbit_id",
                self._extract_qbit_field(
                    qbit,
                    "qbit_id",
                    None,
                ),
            )

            if context.get(
                "qbit_id"
            ) is None:

                context[
                    "qbit_id"
                ] = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            context.setdefault(
                "task_id",
                self._extract_qbit_field(
                    qbit,
                    "task_id",
                    None,
                ),
            )

            context.setdefault(
                "track_id",
                self._extract_qbit_field(
                    qbit,
                    "track_id",
                    None,
                ),
            )

            context.setdefault(
                "pipeline_id",
                self._extract_qbit_field(
                    qbit,
                    "pipeline_id",
                    None,
                ),
            )

            context.setdefault(
                "source",
                self._extract_qbit_field(
                    qbit,
                    "source",
                    None,
                ),
            )

            context.setdefault(
                "channel",
                self._extract_qbit_field(
                    qbit,
                    "channel",
                    None,
                ),
            )

        # ======================================================
        # 6. PRESERVE TASK CONTEXT
        # ======================================================

        task = context.get(
            "task"
        )

        if task is None and qbit is not None:

            task = self._extract_qbit_field(
                qbit,
                "task",
                None,
            )

            if task is not None:

                context[
                    "task"
                ] = task

        if isinstance(
            task,
            dict,
        ):

            context.setdefault(
                "task_id",
                task.get(
                    "task_id"
                ),
            )

            context.setdefault(
                "qbit_id",
                task.get(
                    "qbit_id"
                ),
            )

            context.setdefault(
                "track_id",
                task.get(
                    "track_id"
                ),
            )

            context.setdefault(
                "lineage",
                task.get(
                    "data_lineage"
                ),
            )

            context.setdefault(
                "relationships",
                task.get(
                    "relationships"
                ),
            )

            context.setdefault(
                "commands",
                task.get(
                    "commands",
                    [],
                ),
            )

            context.setdefault(
                "who",
                task.get(
                    "who"
                ),
            )

            context.setdefault(
                "what",
                task.get(
                    "what"
                ),
            )

            context.setdefault(
                "where",
                task.get(
                    "where"
                ),
            )

            context.setdefault(
                "why",
                task.get(
                    "why"
                ),
            )

        # ======================================================
        # 7. IDENTIFY THE ACTUAL THOUGHT PACKET
        #
        # This is CRITICAL.
        #
        # TransformerBrain.analyze() expects the ThoughtPacket
        # itself, not:
        #
        #     {
        #         "compute": ThoughtPacket
        #     }
        #
        # ======================================================

        thought_packet = None

        if isinstance(
            data,
            dict,
        ) and data.get(
            "type"
        ) == "ThoughtPacket":

            thought_packet = data

        elif isinstance(
            data,
            dict,
        ):

            candidate = data.get(
                "compute"
            )

            if (
                isinstance(
                    candidate,
                    dict,
                )
                and candidate.get(
                    "type"
                ) == "ThoughtPacket"
            ):

                thought_packet = candidate

        if (
            stage_name == "transform"
            and thought_packet is not None
        ):

            # --------------------------------------------------
            # The ThoughtPacket is the actual transformer input.
            # --------------------------------------------------

            transform_context = dict(
                thought_packet
            )

            # --------------------------------------------------
            # Restore shared runtime identity without replacing
            # the ThoughtPacket's cognitive fields.
            # --------------------------------------------------

            for key in (
                "qbit",
                "qbit_id",
                "task_id",
                "track_id",
                "pipeline_id",
                "source",
                "channel",
                "lineage",
                "relationships",
                "task",
                "health",
                "authority",
                "cognitive_authority",
            ):

                if key not in transform_context:

                    value = context.get(
                        key
                    )

                    if value is not None:

                        transform_context[
                            key
                        ] = value

            transform_context[
                "stage"
            ] = "transform"

            transform_context[
                "thought_packet"
            ] = thought_packet

            context = transform_context

        # ======================================================
        # 8. COGNITIVE LINK
        # ======================================================

        context[
            "cognitive_link"
        ] = {

            "pipeline": (
                "QBIT"
                " -> TRACK"
                " -> COMPUTE_BRAIN"
                " -> THOUGHT_PACKET"
                " -> TRANSFORMER_BRAIN"
                " -> COGNITIVE_RESULT"
                " -> QbitDialer"
                " -> COMMAND_ADMISSION"
                " -> QbitQueueLoop"
            ),

            "current_stage": stage_name,

            "next_stage": (
                "transform"
                if stage_name == "compute"
                else "command_admission"
            ),

            "authority": "QbitDialer",

            "qbit_id": context.get(
                "qbit_id"
            ),

            "task_id": context.get(
                "task_id"
            ),

            "track_id": context.get(
                "track_id"
            ),

            "pipeline_id": context.get(
                "pipeline_id"
            ),

        }

        # ======================================================
        # 9. RESOLVE PROCESSOR
        #
        # IMPORTANT:
        #
        # TransformerBrain's real authoritative method is:
        #
        #     analyze()
        #
        # Verified against the library TransformerBrain.
        #
        # Do NOT use encode() as a cognitive transform.
        #
        # encode() belongs to serialization.
        # ======================================================

        if stage_name == "compute":

            processor_names = (
                "receive_qbit",
                "process_qbit",
                "process",
                "decode",
                "compute",
                "run",
                "handle",
            )

        else:

            processor_names = (
                "analyze",
                "transform",
                "process",
                "build_command",
                "run",
                "handle",
            )

        processor = None

        processor_name = None

        for method_name in processor_names:

            candidate = getattr(
                brain,
                method_name,
                None,
            )

            if callable(
                candidate
            ):

                processor = candidate

                processor_name = (
                    method_name
                )

                break

        if processor is None:

            raise RuntimeError(
                f"{brain_name} has no supported "
                f"{stage_name} processing method"
            )

        # ======================================================
        # 10. PROCESSOR METADATA
        # ======================================================

        context[
            "processor"
        ] = processor_name

        context[
            "processor_name"
        ] = brain_name

        # ======================================================
        # 11. EXECUTE COGNITIVE STAGE ONLY
        #
        # No queue.
        # No command execution.
        # No second runtime.
        # ======================================================

        try:

            # --------------------------------------------------
            # TransformerBrain.analyze() expects the ThoughtPacket
            # itself. ComputeBrain methods expect Qbit/context.
            # --------------------------------------------------

            if (
                stage_name == "transform"
                and processor_name == "analyze"
                and isinstance(
                    context.get("thought_packet"),
                    dict,
                )
            ):

                processor_input = context[
                    "thought_packet"
                ]

            else:

                processor_input = context

            result = processor(
                processor_input
            )
            

            if inspect.isawaitable(
                result
            ):

                result = await result

        except asyncio.CancelledError:

            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] %s cognitive stage failed | "
                "stage=%s | qbit_id=%s | task_id=%s | track_id=%s",
                brain_name,
                stage_name,
                context.get(
                    "qbit_id"
                ),
                context.get(
                    "task_id"
                ),
                context.get(
                    "track_id"
                ),
            )

            raise

        # ======================================================
        # 12. NORMALIZE RESULT
        # ======================================================

        if result is None:

            return None

        # ------------------------------------------------------
        # Preserve result identity.
        # ------------------------------------------------------

        if isinstance(
            result,
            dict,
        ):

            result.setdefault(
                "stage",
                (
                    "COMPUTE_COMPLETE"
                    if stage_name == "compute"
                    else "TRANSFORM_COMPLETE"
                ),
            )

            result.setdefault(
                "processor",
                brain_name,
            )

            result.setdefault(
                "qbit_id",
                context.get(
                    "qbit_id"
                ),
            )

            result.setdefault(
                "task_id",
                context.get(
                    "task_id"
                ),
            )

            result.setdefault(
                "track_id",
                context.get(
                    "track_id"
                ),
            )

            result.setdefault(
                "pipeline_id",
                context.get(
                    "pipeline_id"
                ),
            )

            result.setdefault(
                "source",
                context.get(
                    "source"
                ),
            )

            result.setdefault(
                "channel",
                context.get(
                    "channel"
                ),
            )

            result.setdefault(
                "cognitive_link",
                context.get(
                    "cognitive_link"
                ),
            )

        # ======================================================
        # 13. COGNITIVE STATE RETENTION
        # ======================================================

        if stage_name == "compute":

            if isinstance(
                result,
                dict,
            ) and result.get(
                "type"
            ) == "ThoughtPacket":

                self.last_thought = result

                try:

                    self.cognitive_state[
                        "last_thought"
                    ] = result

                except Exception:

                    pass

        else:

            if isinstance(
                result,
                dict,
            ):

                self.last_cognitive_result = (
                    result
                )

                try:

                    self.cognitive_state[
                        "last_cognitive_result"
                    ] = result

                except Exception:

                    pass

        # ======================================================
        # 14. RETURN ONLY THE COGNITIVE PRODUCT
        # ======================================================

        return result


    # ==========================================================
    # SEED SIDE OUTPUT ENCODER
    #
    # Cognitive output -> binary SEED representation
    #
    # This is serialization only.
    #
    # It does NOT:
    #   - execute commands
    #   - submit commands
    #   - create queues
    #   - create tasks
    #   - create a runtime
    # ==========================================================

    def _encode_seed_side_output(
        self,
        cognitive_result,
    ):

        if cognitive_result is None:

            return None

        encoder = getattr(
            self,
            "encoder",
            None,
        )

        if encoder is None:

            try:

                encoder = QbitBinaryEncoder()

                self.encoder = encoder

            except Exception:

                self.logger.exception(
                    "[QbitDialer] "
                    "SEED binary encoder unavailable"
                )

                return None

        qbit = cognitive_result.get(
            "qbit"
        ) if isinstance(
            cognitive_result,
            dict,
        ) else None

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        # ------------------------------------------------------
        # Build a serialization-only SEED output envelope.
        # ------------------------------------------------------

        output = {

            "id": (
                cognitive_result.get(
                    "qbit_id"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "task_id": (
                cognitive_result.get(
                    "task_id"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "intent": (
                cognitive_result.get(
                    "intent"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "priority": (
                cognitive_result.get(
                    "priority",
                    0,
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else 0
            ),

            "state": (
                cognitive_result.get(
                    "stage",
                    "COGNITIVE_RESULT",
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else "COGNITIVE_RESULT"
            ),

            "payload": cognitive_result,

            "track_id": (
                cognitive_result.get(
                    "track_id"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "channel_id": (
                cognitive_result.get(
                    "channel"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "parent_id": (
                cognitive_result.get(
                    "qbit_id"
                )
                if isinstance(
                    cognitive_result,
                    dict,
                )
                else None
            ),

            "source": "QbitDialer",

            "module": "qbit_dialer",

            "component": "cognitive_pipeline",

            "timestamp": time.time(),

            "flags": {
                "cognitive_output": True,
                "command_authorized": False,
                "serialization_only": True,
            },

            "qbit": qbit,
        }

        try:

            binary = encoder.encode(
                output
            )

            self.last_seed_output_binary = (
                binary
            )

            return binary

        except Exception:

            self.logger.exception(
                "[QbitDialer] "
                "SEED cognitive output encoding failed"
            )

            return None


    # ==========================================================
    # COGNITIVE COMMAND BRIDGE
    #
    # ComputeBrain / TransformerBrain may produce:
    #
    #     Thought
    #       â†“
    #     Intent
    #       â†“
    #     Action
    #       â†“
    #     Command Envelope
    #
    # This method accepts an ALREADY-INTERPRETED cognitive
    # result and sends the resulting command envelope through
    # the ONE authoritative command admission path.
    #
    # IMPORTANT:
    #
    # create_task() remains the authoritative Qbit/task
    # construction contract.
    #
    # submit_thought_command() DOES NOT:
    #
    #     - create a Qbit
    #     - create a task
    #     - create a queue
    #     - create a loop
    #     - decode a Qbit
    #     - execute a command
    #
    # RAW QBIT:
    #
    #     Qbit
    #       â†“
    #     _process_received_qbit()
    #       â†“
    #     ComputeBrain
    #       â†“
    #     TransformerBrain
    #
    # COGNITIVE COMMAND:
    #
    #     Thought / Intent / Action
    #       â†“
    #     Command Envelope
    #       â†“
    #     submit_command()
    #
    # ONE COMMAND AUTHORITY.
    # ONE COMMAND QUEUE.
    # ==========================================================

    async def submit_thought_command(
        self,
        thought,
        intent=None,
        action=None,
        qbit=None,
        task=None,
        pipeline_id=None,
        source="COGNITIVE_PIPELINE",
        channel=None,
        priority=5,
        confidence=1.0,
        args=None,
        kwargs=None,
        payload=None,
    ):

        # ======================================================
        # 1. RESOLVE EXISTING QBIT CONTEXT
        #
        # No identity is generated here.
        # ======================================================

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        qbit_id = None

        track_id = None

        task_id = None

        # ------------------------------------------------------
        # Qbit identity
        # ------------------------------------------------------

        if qbit is not None:

            qbit_id = self._extract_qbit_field(
                qbit,
                "qbit_id",
                None,
            )

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            track_id = self._extract_qbit_field(
                qbit,
                "track_id",
                None,
            )

            if track_id is None:

                track = self._extract_qbit_field(
                    qbit,
                    "track",
                    None,
                )

                if isinstance(
                    track,
                    dict,
                ):

                    track_id = (
                        track.get(
                            "track_id"
                        )
                        or track.get(
                            "id"
                        )
                    )

                elif track is not None:

                    track_id = (
                        getattr(
                            track,
                            "track_id",
                            None,
                        )
                        or getattr(
                            track,
                            "id",
                            None,
                        )
                    )

            task_id = self._extract_qbit_field(
                qbit,
                "task_id",
                None,
            )

            if task_id is None:

                qbit_task = self._extract_qbit_field(
                    qbit,
                    "task",
                    None,
                )

                if isinstance(
                    qbit_task,
                    dict,
                ):

                    task_id = qbit_task.get(
                        "task_id"
                    )

                    if task is None:

                        task = qbit_task

        # ------------------------------------------------------
        # Existing task context
        # ------------------------------------------------------

        if isinstance(
            task,
            dict,
        ):

            task_id = (
                task.get(
                    "task_id"
                )
                or task_id
            )

            qbit_id = (
                task.get(
                    "qbit_id"
                )
                or qbit_id
            )

            track_id = (
                task.get(
                    "track_id"
                )
                or track_id
            )

            if pipeline_id is None:

                pipeline_id = task.get(
                    "pipeline_id"
                )

        # ======================================================
        # 2. BUILD COMMAND ENVELOPE
        #
        # Transformer output is command data.
        # The Qbit remains the identity anchor.
        # ======================================================

        command = {

            "name": None,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task": task,

            "thought": thought,

            "intent": intent,

            "action": action,

            "compute": thought,

            "transform": action,

            "source": source,

            "channel": channel,

            "priority": priority,

            "confidence": confidence,

            "args": (
                []
                if args is None
                else args
            ),

            "kwargs": (
                {}
                if kwargs is None
                else kwargs
            ),

            "payload": (
                {}
                if payload is None
                else payload
            ),

            "authority": "QbitDialer",

            "cognitive_source": "COGNITIVE_PIPELINE",

        }

        # ======================================================
        # 3. RESOLVE ACTION / INTENT
        #
        # Action has precedence over intent.
        # ======================================================

        if isinstance(
            action,
            dict,
        ):

            command.update(
                action
            )

        elif isinstance(
            intent,
            dict,
        ):

            command.update(
                intent
            )

        elif isinstance(
            action,
            str,
        ):

            command[
                "name"
            ] = action

        elif isinstance(
            intent,
            str,
        ):

            command[
                "name"
            ] = intent

        # ======================================================
        # 4. RESTORE AUTHORITATIVE IDENTITY
        #
        # Transformer/action data must never replace Qbit
        # identity or task lineage.
        # ======================================================

        command[
            "qbit"
        ] = qbit

        command[
            "qbit_id"
        ] = qbit_id

        command[
            "track_id"
        ] = track_id

        command[
            "task_id"
        ] = task_id

        command[
            "task"
        ] = task

        command[
            "authority"
        ] = "QbitDialer"

        # ======================================================
        # 5. RESOLVE COMMAND NAME
        # ======================================================

        command_name = (
            command.get(
                "name"
            )
            or command.get(
                "command"
            )
            or command.get(
                "cmd"
            )
            or command.get(
                "action"
            )
            or command.get(
                "intent"
            )
        )

        if isinstance(
            command_name,
            dict,
        ):

            command_name = (
                command_name.get(
                    "name"
                )
                or command_name.get(
                    "command"
                )
                or command_name.get(
                    "cmd"
                )
            )

        if not isinstance(
            command_name,
            str,
        ):

            self.logger.debug(
                "[QbitDialer] Cognitive result produced "
                "no actionable command | "
                "task_id=%s | qbit_id=%s | track_id=%s",
                task_id,
                qbit_id,
                track_id,
            )

            return {
                "status": "no_command",
                "task_id": task_id,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "thought": thought,
                "intent": intent,
                "action": action,
            }

        command_name = command_name.strip()

        # ------------------------------------------------------
        # Never permit a Qbit representation to become a command.
        # ------------------------------------------------------

        if qbit is not None:

            qbit_repr = str(
                qbit
            ).strip()

            if (
                command_name
                and qbit_repr
                and command_name == qbit_repr
            ):

                self.logger.warning(
                    "[QbitDialer] Cognitive command rejected | "
                    "raw Qbit representation detected as command | "
                    "qbit_id=%s | track_id=%s",
                    qbit_id,
                    track_id,
                )

                return {
                    "status": "rejected",
                    "reason": "raw_qbit_used_as_command",
                    "task_id": task_id,
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                }

        if not command_name:

            return {
                "status": "no_command",
                "task_id": task_id,
                "qbit_id": qbit_id,
                "track_id": track_id,
            }

        command[
            "name"
        ] = command_name.upper()

        # ======================================================
        # 6. NORMALIZE ARGUMENT CONTRACT
        # ======================================================

        if command.get(
            "args"
        ) is None:

            command[
                "args"
            ] = []

        if not isinstance(
            command.get(
                "args"
            ),
            (list, tuple),
        ):

            command[
                "args"
            ] = [
                command[
                    "args"
                ]
            ]

        else:

            command[
                "args"
            ] = list(
                command[
                    "args"
                ]
            )

        if command.get(
            "kwargs"
        ) is None:

            command[
                "kwargs"
            ] = {}

        if not isinstance(
            command.get(
                "kwargs"
            ),
            dict,
        ):

            command[
                "kwargs"
            ] = {}

        if command.get(
            "payload"
        ) is None:

            command[
                "payload"
            ] = {}

        if not isinstance(
            command.get(
                "payload"
            ),
            dict,
        ):

            command[
                "payload"
            ] = {
                "value": command[
                    "payload"
                ]
            }

        # ======================================================
        # 7. PRESERVE COMPLETE COGNITIVE CONTEXT
        # ======================================================

        command[
            "payload"
        ].setdefault(
            "qbit",
            qbit,
        )

        command[
            "payload"
        ].setdefault(
            "qbit_id",
            qbit_id,
        )

        command[
            "payload"
        ].setdefault(
            "track_id",
            track_id,
        )

        command[
            "payload"
        ].setdefault(
            "task_id",
            task_id,
        )

        command[
            "payload"
        ].setdefault(
            "task",
            task,
        )

        command[
            "payload"
        ].setdefault(
            "thought",
            thought,
        )

        command[
            "payload"
        ].setdefault(
            "intent",
            intent,
        )

        command[
            "payload"
        ].setdefault(
            "action",
            action,
        )

        command[
            "payload"
        ].setdefault(
            "source",
            source,
        )

        command[
            "payload"
        ].setdefault(
            "channel",
            channel,
        )

        # ======================================================
        # 8. AUTHORITATIVE COMMAND ADMISSION
        #
        # This is already a command envelope.
        #
        # Therefore it goes directly to submit_command().
        #
        # It does NOT go through submit_qbit_command(), because
        # that method is the raw-Qbit boundary.
        # ======================================================

        self.logger.info(
            "[QbitDialer] Cognitive command -> submit_command | "
            "task_id=%s | command=%s | "
            "qbit_id=%s | track_id=%s",
            task_id,
            command[
                "name"
            ],
            qbit_id,
            track_id,
        )

        result = self.submit_command(
            command
        )

        if inspect.isawaitable(
            result
        ):

            result = await result

        return result





    # ==========================================================
    # COMMAND STATUS / CAPABILITY STATE
    #
    # QbitDialer owns the SINGLE command authority.
    #
    # COMMAND CATALOG
    # ----------------
    # Known capabilities / vocabulary.
    #
    # COMMAND REGISTRY
    # ----------------
    # Currently executable handlers.
    #
    # DYNAMIC CAPABILITIES
    # --------------------
    # SEED may create/register handlers dynamically when it has
    # sufficient capability information.
    #
    # IMPORTANT:
    #
    #     create_task()
    #         â†“
    #     command vocabulary / catalog
    #         â†“
    #     capability resolution
    #         â†“
    #     command_registry
    #         â†“
    #     submit_command()
    #         â†“
    #     command_queue
    #
    # This method reports the complete connected state.
    #
    # It does NOT:
    #
    #     - execute commands
    #     - create queues
    #     - create Qbits
    #     - create runtimes
    #     - become a second command authority
    # ==========================================================

    def command_status(
        self,
    ):

        with self.command_lock:

            command_plane = getattr(
                self,
                "command_plane",
                None,
            )

            if not isinstance(
                command_plane,
                dict,
            ):

                command_plane = {}

                self.command_plane = command_plane

            command_catalog = getattr(
                self,
                "command_catalog",
                None,
            )

            if not isinstance(
                command_catalog,
                dict,
            ):

                command_catalog = {}

                self.command_catalog = command_catalog

            command_registry = getattr(
                self,
                "command_registry",
                None,
            )

            if not isinstance(
                command_registry,
                dict,
            ):

                command_registry = {}

                self.command_registry = command_registry

            history = getattr(
                self,
                "command_history",
                None,
            )

            # ==================================================
            # 1. BUILD LIVE EXECUTABLE SET
            # ==================================================

            executable_commands = sorted(
                str(
                    name
                ).strip().upper()
                for name, handler
                in command_registry.items()
                if callable(
                    handler
                )
            )

            executable_set = set(
                executable_commands
            )

            # ==================================================
            # 2. BUILD CATALOG SET
            # ==================================================

            cataloged_commands = sorted(
                str(
                    name
                ).strip().upper()
                for name
                in command_catalog.keys()
                if str(
                    name
                ).strip()
            )

            catalog_set = set(
                cataloged_commands
            )

            # ==================================================
            # 3. RESOLVE LINKED / PENDING / STALE STATE
            # ==================================================

            linked_commands = sorted(
                catalog_set
                & executable_set
            )

            pending_commands = sorted(
                catalog_set
                - executable_set
            )

            registry_only_commands = sorted(
                executable_set
                - catalog_set
            )

            # ==================================================
            # 4. CAPABILITY SOURCE STATE
            # ==================================================

            dynamic_commands = []

            internal_commands = []

            external_commands = []

            learned_commands = []

            for name in cataloged_commands:

                capability = command_catalog.get(
                    name,
                    {},
                )

                if not isinstance(
                    capability,
                    dict,
                ):

                    continue

                source = str(
                    capability.get(
                        "source",
                        "",
                    )
                ).upper()

                if (
                    capability.get(
                        "dynamic",
                        False,
                    )
                    or
                    capability.get(
                        "generated",
                        False,
                    )
                    or
                    capability.get(
                        "learned",
                        False,
                    )
                ):

                    dynamic_commands.append(
                        name
                    )

                if (
                    "SEED" in source
                    or "INTERNAL" in source
                ):

                    internal_commands.append(
                        name
                    )

                if (
                    "USER" in source
                    or "CLI" in source
                    or "EXTERNAL" in source
                ):

                    external_commands.append(
                        name
                    )

                if capability.get(
                    "learned",
                    False,
                ):

                    learned_commands.append(
                        name
                    )

            dynamic_commands = sorted(
                set(
                    dynamic_commands
                )
            )

            internal_commands = sorted(
                set(
                    internal_commands
                )
            )

            external_commands = sorted(
                set(
                    external_commands
                )
            )

            learned_commands = sorted(
                set(
                    learned_commands
                )
            )

            # ==================================================
            # 5. HANDLER INVENTORY
            # ==================================================

            handler_inventory = {}

            for name in cataloged_commands:

                capability = command_catalog.get(
                    name,
                    {},
                )

                if not isinstance(
                    capability,
                    dict,
                ):

                    capability = {}

                handler = command_registry.get(
                    name
                )

                handler_inventory[
                    name
                ] = {

                    "cataloged": True,

                    "executable": callable(
                        handler
                    ),

                    "state": (
                        "EXECUTABLE"
                        if callable(
                            handler
                        )
                        else capability.get(
                            "state",
                            "PENDING",
                        )
                    ),

                    "source": capability.get(
                        "source",
                        "UNKNOWN",
                    ),

                    "system": capability.get(
                        "system"
                    ),

                    "method": capability.get(
                        "method"
                    ),

                    "dynamic": bool(
                        capability.get(
                            "dynamic",
                            False,
                        )
                    ),

                    "generated": bool(
                        capability.get(
                            "generated",
                            False,
                        )
                    ),

                    "learned": bool(
                        capability.get(
                            "learned",
                            False,
                        )
                    ),

                    "authority": capability.get(
                        "authority",
                        "QbitDialer",
                    ),

                }

            # ==================================================
            # 6. COMMAND PLANE SYNCHRONIZATION STATE
            # ==================================================

            command_plane.update({

                "online": True,

                "active": bool(
                    executable_commands
                ),

                "authority": "QbitDialer",

                # ----------------------------------------------
                # SAME objects used by create_task() and
                # submit_command().
                # ----------------------------------------------

                "catalog": command_catalog,

                "registry": command_registry,

                "cataloged": len(
                    cataloged_commands
                ),

                "executable": len(
                    executable_commands
                ),

                "linked": len(
                    linked_commands
                ),

                "pending": len(
                    pending_commands
                ),

                "registry_only": len(
                    registry_only_commands
                ),

                "dynamic": bool(
                    dynamic_commands
                ),

                "dynamic_count": len(
                    dynamic_commands
                ),

                "internal_count": len(
                    internal_commands
                ),

                "external_count": len(
                    external_commands
                ),

                "learned_count": len(
                    learned_commands
                ),

                "health": (
                    "GREEN"
                    if executable_commands
                    else "YELLOW"
                ),

                "state": (
                    "ONLINE"
                    if executable_commands
                    else "WAITING_FOR_COMMAND_CAPABILITIES"
                ),

            })

            # ==================================================
            # 7. RETURN COMPLETE COMMAND STATE
            # ==================================================

            return {

                **command_plane,

                # ----------------------------------------------
                # Registry / catalog linkage
                # ----------------------------------------------

                "registered_commands": len(
                    executable_commands
                ),

                "cataloged_commands": len(
                    cataloged_commands
                ),

                "linked_commands": len(
                    linked_commands
                ),

                "pending_commands": len(
                    pending_commands
                ),

                "registry_only_commands": len(
                    registry_only_commands
                ),

                "executable_command_names": (
                    executable_commands
                ),

                "cataloged_command_names": (
                    cataloged_commands
                ),

                "linked_command_names": (
                    linked_commands
                ),

                "pending_command_names": (
                    pending_commands
                ),

                "registry_only_command_names": (
                    registry_only_commands
                ),

                # ----------------------------------------------
                # Dynamic capability information
                # ----------------------------------------------

                "dynamic_commands": (
                    dynamic_commands
                ),

                "internal_commands": (
                    internal_commands
                ),

                "external_commands": (
                    external_commands
                ),

                "learned_commands": (
                    learned_commands
                ),

                "handler_inventory": (
                    handler_inventory
                ),

                # ----------------------------------------------
                # Command counters
                # ----------------------------------------------

                "received": getattr(
                    self,
                    "commands_received",
                    0,
                ),

                "accepted": getattr(
                    self,
                    "commands_accepted",
                    0,
                ),

                "rejected": getattr(
                    self,
                    "commands_rejected",
                    0,
                ),

                "queued": getattr(
                    self,
                    "commands_queued",
                    0,
                ),

                "executed": getattr(
                    self,
                    "commands_executed",
                    0,
                ),

                "failed": getattr(
                    self,
                    "commands_failed",
                    0,
                ),

                "cancelled": getattr(
                    self,
                    "commands_cancelled",
                    0,
                ),

                "history_depth": (
                    len(
                        history
                    )
                    if history is not None
                    else 0
                ),

                # ----------------------------------------------
                # Runtime / Qbit authority
                # ----------------------------------------------

                "runtime": getattr(
                    self,
                    "_qbit_runtime_state",
                    "UNKNOWN",
                ),

                "running": bool(
                    getattr(
                        self,
                        "_running",
                        False,
                    )
                ),

                "qbit_id": self._extract_qbit_field(
                    getattr(
                        self,
                        "qbit",
                        None,
                    ),
                    "qbit_id",
                    self._extract_qbit_field(
                        getattr(
                            self,
                            "qbit",
                            None,
                        ),
                        "id",
                        None,
                    ),
                ),

                "track_id": self._extract_qbit_field(
                    getattr(
                        self,
                        "qbit",
                        None,
                    ),
                    "track_id",
                    None,
                ),

                "task_id": self._extract_qbit_field(
                    getattr(
                        self,
                        "qbit",
                        None,
                    ),
                    "task_id",
                    None,
                ),

                # ----------------------------------------------
                # Authoritative queue state
                # ----------------------------------------------

                "command_queue_bound": (
                    getattr(
                        self,
                        "command_queue",
                        None,
                    )
                    is not None
                ),

                "qbit_queue_bound": (
                    getattr(
                        self,
                        "_qbit_queue",
                        None,
                    )
                    is not None
                ),

                "queue_loop_bound": (
                    getattr(
                        self,
                        "qbit_queue_loop",
                        None,
                    )
                    is not None
                    or
                    getattr(
                        self,
                        "queue_loop",
                        None,
                    )
                    is not None
                ),

                # ----------------------------------------------
                # Cognitive components
                # ----------------------------------------------

                "compute_brain_bound": (
                    getattr(
                        self,
                        "compute_brain",
                        None,
                    )
                    is not None
                    or
                    getattr(
                        self,
                        "ComputeBrain",
                        None,
                    )
                    is not None
                    or
                    getattr(
                        self,
                        "computebrain",
                        None,
                    )
                    is not None
                ),

                "transformer_brain_bound": (
                    getattr(
                        self,
                        "transformer_brain",
                        None,
                    )
                    is not None
                    or
                    getattr(
                        self,
                        "TransformerBrain",
                        None,
                    )
                    is not None
                    or
                    getattr(
                        self,
                        "transformerbrain",
                        None,
                    )
                    is not None
                ),

                "track_system_bound": (
                    getattr(
                        self,
                        "track_system",
                        None,
                    )
                    is not None
                ),

                # ----------------------------------------------
                # Last command/result
                # ----------------------------------------------

                "last_command": command_plane.get(
                    "last_command"
                ),

                "last_command_time": command_plane.get(
                    "last_command_time"
                ),

                "last_result_status": command_plane.get(
                    "last_result_status"
                ),

                "last_error": command_plane.get(
                    "last_error"
                ),

            }
    # ==========================================================
    # COMMAND NORMALIZATION
    #
    # AUTHORITATIVE COMMAND-ENVELOPE NORMALIZER
    #
    # create_task() establishes the Qbit/task contract:
    #
    #     qbit_id
    #     task_id
    #     track_id
    #     who
    #     what
    #     where
    #     why
    #     how
    #     lineage
    #     relationships
    #     commands
    #     compute contract
    #
    # Cognitive processing establishes:
    #
    #     thought
    #     intent
    #     action
    #     compute
    #     transform
    #
    # This method PRESERVES that information.
    #
    # IMPORTANT:
    #
    #     RAW QBIT = DATA
    #
    # A raw Qbit must never be normalized into:
    #
    #     name = str(qbit)
    #
    # Raw Qbits belong in:
    #
    #     _process_received_qbit()
    #
    # Only an ACTUAL COMMAND ENVELOPE reaches this method.
    #
    # ONE COMMAND AUTHORITY.
    # ONE NORMALIZATION CONTRACT.
    # ONE COMMAND QUEUE.
    # ==========================================================

    def _normalize_command(
        self,
        cmd,
    ):

        # ======================================================
        # 1. HARD RAW-QBIT PROTECTION
        #
        # Keep this boundary inside normalization as a final
        # defense even though execute_command() and the command
        # plane should intercept raw Qbits earlier.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                cmd,
                qbit_type,
            )
        ):

            raise TypeError(
                "[QbitDialer] Raw Qbit cannot be normalized "
                "as a command | route=_process_received_qbit"
            )

        # ======================================================
        # 2. STRING COMMAND
        #
        # A string is accepted only as an already-established
        # command name.
        #
        # Identity is NOT invented here.
        # ======================================================

        if isinstance(
            cmd,
            str,
        ):

            name = cmd.strip().upper()

            if not name:

                raise ValueError(
                    "[QbitDialer] Empty command name"
                )

            return {

                "name": name,

                "args": [],

                "kwargs": {},

                "payload": {},

                "source": "EXTERNAL_COMMAND",

                "priority": 5,

                "confidence": 1.0,

                "track_id": None,

                "parent_id": None,

                "channel_id": None,

                "pipeline_id": None,

                "task_id": None,

                "qbit": None,

                "qbit_id": None,

                "task": None,

                "lineage": None,

                "relationships": None,

                "thought": None,

                "intent": None,

                "action": None,

                "compute": None,

                "transform": None,

                "who": None,

                "what": None,

                "where": None,

                "why": None,

                "how": None,

                "authority": "QbitDialer",

            }

        # ======================================================
        # 3. COMMAND ENVELOPE
        # ======================================================

        if isinstance(
            cmd,
            dict,
        ):

            # ==================================================
            # 3A. COMMAND NAME RESOLUTION
            #
            # The command name must be COMMAND DATA.
            #
            # Never fall back to str(qbit).
            # ==================================================

            name = (

                cmd.get(
                    "name"
                )

                or cmd.get(
                    "command"
                )

                or cmd.get(
                    "cmd"
                )

                or cmd.get(
                    "action"
                )

            )

            # --------------------------------------------------
            # If action is a dictionary, resolve its explicit
            # command field but NEVER stringify the dictionary.
            # --------------------------------------------------

            if isinstance(
                name,
                dict,
            ):

                name = (

                    name.get(
                        "name"
                    )

                    or name.get(
                        "command"
                    )

                    or name.get(
                        "cmd"
                    )

                )

            if name is None:

                raise ValueError(
                    "[QbitDialer] Command envelope "
                    "contains no command name"
                )

            if not isinstance(
                name,
                str,
            ):

                raise TypeError(
                    "[QbitDialer] Command name must be "
                    f"a string, got {type(name).__name__}"
                )

            name = name.strip().upper()

            if not name:

                raise ValueError(
                    "[QbitDialer] Command envelope "
                    "contains an empty command name"
                )

            # ==================================================
            # 3B. ARGUMENT CONTRACT
            # ==================================================

            args = cmd.get(
                "args",
                [],
            )

            if args is None:

                args = []

            if not isinstance(
                args,
                (list, tuple),
            ):

                args = [
                    args
                ]

            else:

                args = list(
                    args
                )

            # ==================================================
            # 3C. KEYWORD ARGUMENT CONTRACT
            # ==================================================

            kwargs = cmd.get(
                "kwargs",
                {},
            )

            if kwargs is None:

                kwargs = {}

            if not isinstance(
                kwargs,
                dict,
            ):

                kwargs = {}

            else:

                kwargs = dict(
                    kwargs
                )

            # ==================================================
            # 3D. PAYLOAD CONTRACT
            # ==================================================

            payload = cmd.get(
                "payload",
                {},
            )

            if payload is None:

                payload = {}

            elif not isinstance(
                payload,
                dict,
            ):

                payload = {
                    "value": payload
                }

            else:

                payload = dict(
                    payload
                )

            # ==================================================
            # 3E. EXISTING QBIT
            #
            # Preserve the actual Qbit object if supplied.
            # ==================================================

            qbit = cmd.get(
                "qbit"
            )

            # --------------------------------------------------
            # Identity starts with the explicit command envelope.
            # --------------------------------------------------

            qbit_id = cmd.get(
                "qbit_id"
            )

            track_id = cmd.get(
                "track_id"
            )

            task_id = cmd.get(
                "task_id"
            )

            # --------------------------------------------------
            # Fill ONLY missing identity from the existing Qbit.
            #
            # Never manufacture it.
            # --------------------------------------------------

            if qbit is not None:

                if qbit_id is None:

                    qbit_id = (
                        self._extract_qbit_field(
                            qbit,
                            "qbit_id",
                            None,
                        )
                    )

                if qbit_id is None:

                    qbit_id = (
                        self._extract_qbit_field(
                            qbit,
                            "id",
                            None,
                        )
                    )

                if track_id is None:

                    track_id = (
                        self._extract_qbit_field(
                            qbit,
                            "track_id",
                            None,
                        )
                    )

                if task_id is None:

                    task_id = (
                        self._extract_qbit_field(
                            qbit,
                            "task_id",
                            None,
                        )
                    )

                if task_id is None:

                    qbit_task = (
                        self._extract_qbit_field(
                            qbit,
                            "task",
                            None,
                        )
                    )

                    if isinstance(
                        qbit_task,
                        dict,
                    ):

                        task_id = qbit_task.get(
                            "task_id"
                        )

            # ==================================================
            # 3F. TASK / LINEAGE / RELATIONSHIP CONTINUITY
            # ==================================================

            task = cmd.get(
                "task"
            )

            if task is None and qbit is not None:

                task = self._extract_qbit_field(
                    qbit,
                    "task",
                    None,
                )

            lineage = cmd.get(
                "lineage"
            )

            if lineage is None:

                lineage = cmd.get(
                    "data_lineage"
                )

            if lineage is None and isinstance(
                task,
                dict,
            ):

                lineage = task.get(
                    "data_lineage"
                )

            if lineage is None and qbit is not None:

                lineage = self._extract_qbit_field(
                    qbit,
                    "data_lineage",
                    None,
                )

            relationships = cmd.get(
                "relationships"
            )

            if relationships is None and isinstance(
                task,
                dict,
            ):

                relationships = task.get(
                    "relationships"
                )

            if relationships is None and qbit is not None:

                relationships = (
                    self._extract_qbit_field(
                        qbit,
                        "relationships",
                        None,
                    )
                )

            # ==================================================
            # 3G. TRACK FALLBACK THROUGH EXISTING QBIT DATA
            # ==================================================

            if track_id is None and qbit is not None:

                track = self._extract_qbit_field(
                    qbit,
                    "track",
                    None,
                )

                if isinstance(
                    track,
                    dict,
                ):

                    track_id = (

                        track.get(
                            "track_id"
                        )

                        or track.get(
                            "id"
                        )

                    )

                elif track is not None:

                    track_id = (

                        getattr(
                            track,
                            "track_id",
                            None,
                        )

                        or getattr(
                            track,
                            "id",
                            None,
                        )

                    )

            # ==================================================
            # 3H. PIPELINE CONTINUITY
            # ==================================================

            pipeline_id = cmd.get(
                "pipeline_id"
            )

            if pipeline_id is None and qbit is not None:

                pipeline_id = (
                    self._extract_qbit_field(
                        qbit,
                        "pipeline_id",
                        None,
                    )
                )

            if pipeline_id is None and isinstance(
                task,
                dict,
            ):

                pipeline_id = task.get(
                    "pipeline_id"
                )

            # ==================================================
            # 3I. COGNITIVE CONTEXT
            # ==================================================

            thought = cmd.get(
                "thought"
            )

            intent = cmd.get(
                "intent"
            )

            action = cmd.get(
                "action"
            )

            compute = cmd.get(
                "compute"
            )

            transform = cmd.get(
                "transform"
            )

            # ==================================================
            # 3J. WHO / WHAT / WHERE / WHY / HOW
            #
            # Preserve explicit envelope values first.
            # Then inherit from the authoritative task.
            # ==================================================

            who = cmd.get(
                "who"
            )

            what = cmd.get(
                "what"
            )

            where = cmd.get(
                "where"
            )

            why = cmd.get(
                "why"
            )

            how = cmd.get(
                "how"
            )

            if isinstance(
                task,
                dict,
            ):

                if who is None:

                    who = task.get(
                        "who"
                    )

                if what is None:

                    what = task.get(
                        "what"
                    )

                if where is None:

                    where = task.get(
                        "where"
                    )

                if why is None:

                    why = task.get(
                        "why"
                    )

                if how is None:

                    how = task.get(
                        "how"
                    )

            # ==================================================
            # 3K. SOURCE / CHANNEL / AUTHORITY
            # ==================================================

            source = cmd.get(
                "source",
                "QBIT",
            )

            channel = cmd.get(
                "channel"
            )

            if channel is None:

                channel = cmd.get(
                    "channel_id"
                )

            authority = cmd.get(
                "authority",
                "QbitDialer",
            )

            # ==================================================
            # 3L. PRIORITY / CONFIDENCE
            # ==================================================

            priority = cmd.get(
                "priority",
                5,
            )

            confidence = cmd.get(
                "confidence",
                1.0,
            )

            # ==================================================
            # 3M. PRESERVE ALL COMMAND DATA
            #
            # Do not throw away fields added by:
            #
            #     create_task()
            #     ComputeBrain
            #     TransformerBrain
            #     dynamic capabilities
            #     SEED internal controls
            #     external CLI
            # ==================================================

            normalized = dict(
                cmd
            )

            # ==================================================
            # 3N. AUTHORITATIVE NORMALIZED FIELDS
            # ==================================================

            normalized.update({

                "name": name,

                "args": args,

                "kwargs": kwargs,

                "payload": payload,

                "source": source,

                "priority": priority,

                "confidence": confidence,

                "track_id": track_id,

                "parent_id": cmd.get(
                    "parent_id"
                ),

                "channel_id": cmd.get(
                    "channel_id"
                ),

                "channel": channel,

                "pipeline_id": pipeline_id,

                "task_id": task_id,

                "task": task,

                "qbit": qbit,

                "qbit_id": qbit_id,

                "lineage": lineage,

                "relationships": relationships,

                "thought": thought,

                "intent": intent,

                "action": action,

                "compute": compute,

                "transform": transform,

                "who": who,

                "what": what,

                "where": where,

                "why": why,

                "how": how,

                "authority": authority,

            })

            # ==================================================
            # 3O. COGNITIVE LINK
            # ==================================================

            normalized[
                "cognitive_link"
            ] = {

                "source_stage": cmd.get(
                    "cognitive_source",
                    "UNKNOWN",
                ),

                "command_stage": (
                    "COMMAND_ENVELOPE"
                ),

                "authority": "QbitDialer",

                "task_id": task_id,

                "qbit_id": qbit_id,

                "track_id": track_id,

                "pipeline_id": pipeline_id,

            }

            return normalized

        # ======================================================
        # 4. INVALID INPUT
        # ======================================================

        raise TypeError(
            "[QbitDialer] Unsupported command type: "
            f"{type(cmd).__name__}"
        )
    # ==========================================================
    # INTERNAL ROUTING / TRACK ID
    #
    # PURPOSE:
    #
    # Provide the Dialer with an internal routing identity when
    # incoming command/Qbit DATA does not already contain one.
    #
    # IMPORTANT:
    #
    # This is NOT:
    #
    #     - Qbit creation
    #     - Qbit recovery
    #     - command execution
    #     - queue creation
    #     - runtime creation
    #
    # It is ONLY routing metadata.
    #
    # Qbit identity remains Qbit-owned:
    #
    #     qbit_id
    #
    # TrackSystem / routing owns:
    #
    #     track_id
    #
    # This allows QbitDialer to read/write newly arriving data
    # through the existing processing pipeline without creating
    # a competing system.
    #
    # ==========================================================

    def _generate_command_track_id(
        self,
        command,
    ):

        # ======================================================
        # 1. PRESERVE EXISTING TRACK ID
        #
        # Never replace a TrackID that already exists.
        # ======================================================

        existing_track_id = None

        try:

            existing_track_id = (
                self._extract_qbit_field(
                    command,
                    "track_id",
                    None,
                )
            )

        except Exception:

            existing_track_id = None

        if existing_track_id:

            return str(
                existing_track_id
            )

        # ======================================================
        # 2. DETERMINE ROUTING TYPE
        #
        # Qbit/data gets a Qbit routing identity.
        #
        # Commands get a command routing identity.
        #
        # Unknown structured data gets a DATA routing identity.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                command,
                qbit_type,
            )
        ):

            route_type = "QBIT"

            route_name = (
                self._extract_qbit_field(
                    command,
                    "qbit_id",
                    None,
                )
            )

            if route_name is None:

                route_name = (
                    self._extract_qbit_field(
                        command,
                        "id",
                        None,
                    )
                )

        elif isinstance(
            command,
            dict,
        ):

            route_type = str(
                command.get(
                    "type",
                    command.get(
                        "source",
                        "DATA",
                    ),
                )
            ).strip().upper()

            route_name = (
                command.get(
                    "name"
                )
                or command.get(
                    "command"
                )
                or command.get(
                    "action"
                )
                or command.get(
                    "qbit_id"
                )
            )

        else:

            route_type = "COMMAND"

            route_name = command

        # ======================================================
        # 3. NORMALIZE ROUTING NAME
        # ======================================================

        if route_name is None:

            route_name = "UNKNOWN"

        route_name = str(
            route_name
        ).strip().upper()

        # ------------------------------------------------------
        # Keep routing names usable as IDs.
        # ------------------------------------------------------

        safe_name = "".join(
            character
            if (
                character.isalnum()
                or character
                in (
                    "_",
                    "-",
                    ".",
                )
            )
            else "_"
            for character
            in route_name
        )

        if not safe_name:

            safe_name = "UNKNOWN"

        # ======================================================
        # 4. ROUTING CATEGORY
        #
        # This is internal addressing only.
        # ======================================================

        if route_type == "QBIT":

            skill_name = (
                f"QBIT_ROUTE_{safe_name}"
            )

            fallback_prefix = (
                "QBIT-ROUTE"
            )

        elif (
            route_type in (
                "SEED_AI",
                "SEED",
                "INTERNAL",
            )
        ):

            skill_name = (
                f"SEED_ROUTE_{safe_name}"
            )

            fallback_prefix = (
                "SEED-ROUTE"
            )

        elif route_type in (
            "CLI",
            "USER",
            "EXTERNAL",
        ):

            skill_name = (
                f"CLI_ROUTE_{safe_name}"
            )

            fallback_prefix = (
                "CLI-ROUTE"
            )

        elif route_type == "COMMAND":

            skill_name = (
                f"QBIT_CMD_{safe_name}"
            )

            fallback_prefix = (
                "QBIT-CMD"
            )

        else:

            skill_name = (
                f"DATA_ROUTE_{safe_name}"
            )

            fallback_prefix = (
                "DATA-ROUTE"
            )

        # ======================================================
        # 5. USE AUTHORITATIVE TRACK GENERATOR
        #
        # TrackSystem/channel_id remains responsible for the
        # actual TrackID format when available.
        # ======================================================

        try:

            from seed.core.channel_id import (
                generate_track_id,
            )

            track_id = generate_track_id(
                skill_name=skill_name
            )

            if track_id:

                return str(
                    track_id
                )

        except Exception as exc:

            try:

                self.logger.debug(
                    "[QbitDialer] TrackID generator unavailable | "
                    "route_type=%s | name=%s | error=%s",
                    route_type,
                    safe_name,
                    exc,
                )

            except Exception:

                pass

        # ======================================================
        # 6. INTERNAL FALLBACK ROUTING ID
        #
        # Still only routing metadata.
        # No Qbit is created.
        # No TrackSystem is created.
        # ======================================================

        return (
            f"{fallback_prefix}-"
            f"{safe_name}-"
            f"{uuid.uuid4().hex[:8].upper()}"
        )



    # ==========================================================
    # COMMAND HISTORY / CAPABILITY PERSISTENCE
    #
    # QbitDialer remains the SINGLE command authority.
    #
    # LIVE RUNTIME:
    #
    #     command_catalog
    #     command_registry
    #     command_history
    #
    # PERSISTENT STATE:
    #
    #     command_state.json
    #
    # The JSON file stores COMMAND METADATA and DISCOVERY STATE.
    #
    # Python callables are NEVER serialized.
    #
    # On startup:
    #
    #     JSON capability state
    #          â†“
    #     dynamic discovery
    #          â†“
    #     command_catalog
    #          â†“
    #     command_registry
    #
    # create_task() remains the authoritative Qbit/task path.
    #
    # This method does NOT:
    #
    #     - create a Qbit
    #     - create a task
    #     - create a queue
    #     - create a loop
    #     - create an executor
    #
    # ==========================================================

    def _record_command_history(
        self,
        entry,
    ):

        with self.command_lock:

            history = getattr(
                self,
                "command_history",
                None,
            )

            if history is None:

                history = []

                self.command_history = history

            # ==================================================
            # 1. RECORD LIVE HISTORY
            # ==================================================

            try:

                if isinstance(
                    entry,
                    dict,
                ):

                    history.append(
                        dict(
                            entry
                        )
                    )

                else:

                    history.append(
                        {
                            "timestamp": time.time(),
                            "entry": str(
                                entry
                            ),
                        }
                    )

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Command history append failed",
                    exc_info=True,
                )

                return False

            # ==================================================
            # 2. BOUND HISTORY DEPTH
            # ==================================================

            try:

                max_history = int(
                    getattr(
                        self,
                        "command_history_limit",
                        500,
                    )
                )

            except Exception:

                max_history = 500

            if max_history < 1:

                max_history = 500

            if len(
                history
            ) > max_history:

                del history[
                    :-max_history
                ]

            # ==================================================
            # 3. PUBLISH LAST COMMAND STATE
            # ==================================================

            try:

                command_plane = getattr(
                    self,
                    "command_plane",
                    None,
                )

                if isinstance(
                    command_plane,
                    dict,
                ):

                    command_plane[
                        "last_history_entry"
                    ] = dict(
                        history[-1]
                    )

                    command_plane[
                        "history_depth"
                    ] = len(
                        history
                    )

            except Exception:

                pass

            # ==================================================
            # 4. PERSIST COMMAND/CAPABILITY STATE
            #
            # Persistence failure must NEVER break command
            # execution.
            # ==================================================

            try:

                self._persist_command_state()

            except Exception:

                self.logger.debug(
                    "[QbitDialer] Command state persistence "
                    "failed",
                    exc_info=True,
                )

            return True


    # ==========================================================
    # COMMAND STATE PERSISTENCE
    #
    # Stores:
    #
    #     command catalog
    #     registry metadata
    #     dynamic capability metadata
    #     command history
    #     runtime command statistics
    #
    # IMPORTANT:
    #
    # Callable Python handlers are NOT serialized.
    #
    # Handler metadata is retained so dynamic discovery can
    # reconnect the executable implementation on the next boot.
    # ==========================================================

    def _persist_command_state(
        self,
        path=None,
    ):

        with self.command_lock:

            # --------------------------------------------------
            # Resolve persistent state path.
            # --------------------------------------------------

            if path is None:

                path = getattr(
                    self,
                    "command_state_path",
                    None,
                )

            if path is None:

                path = os.path.join(
                    os.path.dirname(
                        os.path.abspath(
                            __file__
                        )
                    ),
                    "command_state.json",
                )

            self.command_state_path = path

            command_catalog = getattr(
                self,
                "command_catalog",
                {},
            )

            command_registry = getattr(
                self,
                "command_registry",
                {},
            )

            command_plane = getattr(
                self,
                "command_plane",
                {},
            )

            command_history = getattr(
                self,
                "command_history",
                [],
            )

            if not isinstance(
                command_catalog,
                dict,
            ):

                command_catalog = {}

            if not isinstance(
                command_registry,
                dict,
            ):

                command_registry = {}

            if not isinstance(
                command_plane,
                dict,
            ):

                command_plane = {}

            if not isinstance(
                command_history,
                list,
            ):

                command_history = []

            # ==================================================
            # BUILD SERIALIZABLE CATALOG
            # ==================================================

            catalog = {}

            for name, capability in command_catalog.items():

                normalized_name = str(
                    name
                ).strip().upper()

                if not normalized_name:

                    continue

                if not isinstance(
                    capability,
                    dict,
                ):

                    capability = {
                        "name": normalized_name,
                    }

                record = dict(
                    capability
                )

                handler = command_registry.get(
                    normalized_name
                )

                record[
                    "name"
                ] = normalized_name

                record[
                    "executable"
                ] = callable(
                    handler
                )

                record[
                    "state"
                ] = (
                    "EXECUTABLE"
                    if callable(
                        handler
                    )
                    else record.get(
                        "state",
                        "PENDING",
                    )
                )

                # ------------------------------------------------
                # Preserve a stable handler description rather
                # than the callable itself.
                # ------------------------------------------------

                if callable(
                    handler
                ):

                    record[
                        "handler"
                    ] = {

                        "module": getattr(
                            handler,
                            "__module__",
                            None,
                        ),

                        "qualname": getattr(
                            handler,
                            "__qualname__",
                            getattr(
                                handler,
                                "__name__",
                                None,
                            ),
                        ),

                    }

                else:

                    record.pop(
                        "handler",
                        None,
                    )

                catalog[
                    normalized_name
                ] = record

            # ==================================================
            # INCLUDE REGISTRY-ONLY CAPABILITIES
            #
            # These are executable handlers that have not yet
            # been represented in the catalog.
            # ==================================================

            for name, handler in command_registry.items():

                normalized_name = str(
                    name
                ).strip().upper()

                if not normalized_name:

                    continue

                if normalized_name in catalog:

                    continue

                if not callable(
                    handler
                ):

                    continue

                catalog[
                    normalized_name
                ] = {

                    "name": normalized_name,

                    "source": "DYNAMIC_REGISTRY",

                    "authority": "QbitDialer",

                    "state": "EXECUTABLE",

                    "executable": True,

                    "dynamic": True,

                    "handler": {

                        "module": getattr(
                            handler,
                            "__module__",
                            None,
                        ),

                        "qualname": getattr(
                            handler,
                            "__qualname__",
                            getattr(
                                handler,
                                "__name__",
                                None,
                            ),
                        ),

                    },

                }

            # ==================================================
            # SERIALIZABLE COMMAND PLANE
            # ==================================================

            plane_state = {

                "online": bool(
                    command_plane.get(
                        "online",
                        False,
                    )
                ),

                "active": bool(
                    command_plane.get(
                        "active",
                        False,
                    )
                ),

                "authority": (
                    "QbitDialer"
                ),

                "dynamic": bool(
                    command_plane.get(
                        "dynamic",
                        True,
                    )
                ),

                "version": command_plane.get(
                    "version",
                    "DYNAMIC-CAPABILITY-PLANE",
                ),

            }

            # ==================================================
            # SERIALIZABLE HISTORY
            # ==================================================

            safe_history = []

            for record in command_history[
                -getattr(
                    self,
                    "command_history_limit",
                    500,
                ):
            ]:

                if isinstance(
                    record,
                    dict,
                ):

                    safe_record = {}

                    for key, value in record.items():

                        try:

                            json.dumps(
                                value
                            )

                            safe_record[
                                key
                            ] = value

                        except (
                            TypeError,
                            ValueError,
                        ):

                            safe_record[
                                key
                            ] = str(
                                value
                            )

                    safe_history.append(
                        safe_record
                    )

                else:

                    safe_history.append(
                        str(
                            record
                        )
                    )

            # ==================================================
            # FINAL STATE DOCUMENT
            # ==================================================

            state = {

                "schema": (
                    "QBITDIALER_COMMAND_STATE"
                ),

                "version": 1,

                "updated_at": time.time(),

                "authority": (
                    "QbitDialer"
                ),

                "command_catalog": catalog,

                "command_plane": plane_state,

                "history": safe_history,

                "statistics": {

                    "commands_received": getattr(
                        self,
                        "commands_received",
                        0,
                    ),

                    "commands_accepted": getattr(
                        self,
                        "commands_accepted",
                        0,
                    ),

                    "commands_rejected": getattr(
                        self,
                        "commands_rejected",
                        0,
                    ),

                    "commands_queued": getattr(
                        self,
                        "commands_queued",
                        0,
                    ),

                    "commands_executed": getattr(
                        self,
                        "commands_executed",
                        0,
                    ),

                    "commands_failed": getattr(
                        self,
                        "commands_failed",
                        0,
                    ),

                    "commands_cancelled": getattr(
                        self,
                        "commands_cancelled",
                        0,
                    ),

                },

            }

            # ==================================================
            # ATOMIC WRITE
            #
            # Write a temporary file beside the state file,
            # then replace the previous state.
            # ==================================================

            directory = os.path.dirname(
                os.path.abspath(
                    path
                )
            )

            os.makedirs(
                directory,
                exist_ok=True,
            )

            temp_path = (
                f"{path}.tmp"
            )

            with open(
                temp_path,
                "w",
                encoding="utf-8",
            ) as handle:

                json.dump(
                    state,
                    handle,
                    indent=2,
                    ensure_ascii=False,
                )

                handle.write(
                    "\n"
                )

            os.replace(
                temp_path,
                path,
            )

            return path


    # ==========================================================
    # LOAD PERSISTED COMMAND STATE
    #
    # This restores COMMAND METADATA only.
    #
    # Callable handlers are reconnected through normal dynamic
    # capability discovery rather than unsafe deserialization.
    # ==========================================================

    def _load_command_state(
        self,
        path=None,
    ):

        with self.command_lock:

            if path is None:

                path = getattr(
                    self,
                    "command_state_path",
                    None,
                )

            if path is None:

                path = os.path.join(
                    os.path.dirname(
                        os.path.abspath(
                            __file__
                        )
                    ),
                    "command_state.json",
                )

            self.command_state_path = path

            if not os.path.isfile(
                path
            ):

                return False

            try:

                with open(
                    path,
                    "r",
                    encoding="utf-8",
                ) as handle:

                    state = json.load(
                        handle
                    )

            except (
                OSError,
                ValueError,
                TypeError,
            ):

                self.logger.debug(
                    "[QbitDialer] Command state load failed | "
                    "path=%s",
                    path,
                    exc_info=True,
                )

                return False

            if not isinstance(
                state,
                dict,
            ):

                return False

            catalog = state.get(
                "command_catalog",
                {},
            )

            if isinstance(
                catalog,
                dict,
            ):

                for name, capability in catalog.items():

                    normalized_name = str(
                        name
                    ).strip().upper()

                    if not normalized_name:

                        continue

                    if not isinstance(
                        capability,
                        dict,
                    ):

                        capability = {
                            "name": normalized_name,
                        }

                    existing = (
                        self.command_catalog.get(
                            normalized_name,
                            {},
                        )
                    )

                    if not isinstance(
                        existing,
                        dict,
                    ):

                        existing = {}

                    # ------------------------------------------------
                    # Persisted metadata is additive.
                    #
                    # Live runtime discovery remains authoritative
                    # for actual callable handlers.
                    # ------------------------------------------------

                    for key, value in capability.items():

                        if key == "handler":

                            continue

                        existing.setdefault(
                            key,
                            value,
                        )

                    self.command_catalog[
                        normalized_name
                    ] = existing

            # ==================================================
            # RESTORE HISTORY
            # ==================================================

            persisted_history = state.get(
                "history",
                [],
            )

            if isinstance(
                persisted_history,
                list,
            ):

                history = getattr(
                    self,
                    "command_history",
                    None,
                )

                if not isinstance(
                    history,
                    list,
                ):

                    history = []

                    self.command_history = history

                history.extend(
                    persisted_history[
                        -getattr(
                            self,
                            "command_history_limit",
                            500,
                        ):
                    ]
                )

            # ==================================================
            # RESTORE STATISTICS
            #
            # Existing runtime counters win if already active.
            # ==================================================

            statistics = state.get(
                "statistics",
                {},
            )

            if isinstance(
                statistics,
                dict,
            ):

                for field in (
                    "commands_received",
                    "commands_accepted",
                    "commands_rejected",
                    "commands_queued",
                    "commands_executed",
                    "commands_failed",
                    "commands_cancelled",
                ):

                    if not hasattr(
                        self,
                        field,
                    ):

                        setattr(
                            self,
                            field,
                            int(
                                statistics.get(
                                    field,
                                    0,
                                )
                            ),
                        )

            # ==================================================
            # MARK STATE AS LOADED
            # ==================================================

            self.command_plane[
                "persistent_state_loaded"
            ] = True

            self.command_plane[
                "command_state_path"
            ] = path

            self.command_plane[
                "persistent_state_updated_at"
            ] = state.get(
                "updated_at"
            )

            return True


    # ==========================================================
    # COMMAND EXECUTION
    #
    # AUTHORITATIVE QBIT COMMAND PLANE.
    #
    # QbitQueueLoop transports/delivers.
    # QbitDialer processes/adjudicates/executes.
    #
    # CRITICAL:
    #
    # A RAW Qbit is DATA.
    #
    # A RAW Qbit MUST NEVER reach _normalize_command().
    #
    # RAW QBIT:
    #
    #     Qbit
    #       â†“
    #     _process_received_qbit()
    #       â†“
    #     ComputeBrain
    #       â†“
    #     TransformerBrain
    #       â†“
    #     Command Envelope
    #       â†“
    #     QbitDialer
    #       â†“
    #     submit_command()
    #       â†“
    #     command_queue
    #
    # COMMAND ENVELOPE:
    #
    #     dict
    #       â†“
    #     _normalize_command()
    #       â†“
    #     command_registry
    #       â†“
    #     handler
    #
    # NO RAW QBIT STRINGIFICATION.
    # NO SECOND QUEUE.
    # NO SECOND EXECUTOR.
    # ==========================================================

    async def _execute_qbit_command(
        self,
        cmd,
    ):

        # ======================================================
        # HARD RAW-QBIT RECEIVE GATE
        #
        # THIS MUST BE THE FIRST OPERATION.
        #
        # Do not call:
        #
        #     _normalize_command(cmd)
        #
        # until this gate has confirmed that cmd is NOT a Qbit.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        # ------------------------------------------------------
        # Determine the authoritative Qbit class.
        #
        # This protects against multiple Qbit imports/modules
        # producing different Python class objects.
        # ------------------------------------------------------

        authoritative_qbit = getattr(
            self,
            "qbit",
            None,
        )

        if authoritative_qbit is None:

            authoritative_qbit = getattr(
                self,
                "qbit_instance",
                None,
            )

        authoritative_qbit_type = (
            type(
                authoritative_qbit
            )
            if authoritative_qbit is not None
            else None
        )

        # ------------------------------------------------------
        # RAW QBIT DETECTION
        #
        # Check both:
        #
        #   1. globally imported Qbit class
        #   2. authoritative Qbit instance class
        #
        # This prevents the actual runtime Qbit from being
        # mistaken for an arbitrary command object.
        # ------------------------------------------------------

        is_raw_qbit = False

        if (
            qbit_type is not None
            and isinstance(
                cmd,
                qbit_type,
            )
        ):

            is_raw_qbit = True

        elif (
            authoritative_qbit_type is not None
            and isinstance(
                cmd,
                authoritative_qbit_type,
            )
        ):

            is_raw_qbit = True

        # ------------------------------------------------------
        # RAW QBIT -> COGNITIVE RECEIVE PIPELINE
        # ------------------------------------------------------

        if is_raw_qbit:

            self.logger.debug(
                "[QbitDialer] RAW Qbit received | "
                "qbit_id=%s | track_id=%s",
                getattr(
                    cmd,
                    "id",
                    None,
                ),
                getattr(
                    cmd,
                    "track_id",
                    None,
                ),
            )

            receive = getattr(
                self,
                "_process_received_qbit",
                None,
            )

            # --------------------------------------------------
            # Compatibility with receive_qbit() if the current
            # Dialer exposes that entry instead.
            # --------------------------------------------------

            if not callable(
                receive
            ):

                receive = getattr(
                    self,
                    "receive_qbit",
                    None,
                )

            if not callable(
                receive
            ):

                self.logger.error(
                    "[QbitDialer] RAW Qbit received but "
                    "no cognitive receive interface exists | "
                    "qbit_id=%s | track_id=%s",
                    getattr(
                        cmd,
                        "id",
                        None,
                    ),
                    getattr(
                        cmd,
                        "track_id",
                        None,
                    ),
                )

                with self.command_lock:

                    self.commands_rejected += 1

                return {
                    "status": "rejected",
                    "reason": "qbit_receive_interface_unavailable",
                    "qbit_id": getattr(
                        cmd,
                        "id",
                        None,
                    ),
                    "track_id": getattr(
                        cmd,
                        "track_id",
                        None,
                    ),
                }

            result = receive(
                cmd
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            return result

        # ======================================================
        # COMMAND ENVELOPE PATH
        #
        # ONLY non-Qbit command data reaches normalization.
        # ======================================================

        if not isinstance(
            cmd,
            dict,
        ):

            with self.command_lock:

                self.commands_received += 1
                self.commands_rejected += 1

            self.logger.warning(
                "[QbitDialer] Rejected invalid command object | "
                "type=%s",
                type(cmd).__name__,
            )

            return {
                "status": "rejected",
                "reason": "invalid_command_type",
                "type": type(cmd).__name__,
            }

        # ======================================================
        # NORMALIZE COMMAND ENVELOPE
        # ======================================================

        try:

            normalized = self._normalize_command(
                cmd
            )

        except Exception as exc:

            with self.command_lock:

                self.commands_received += 1
                self.commands_rejected += 1

            self.logger.warning(
                "[QbitDialer] Command normalization failed | "
                "error=%s",
                exc,
            )

            return {
                "status": "rejected",
                "reason": "invalid_command",
                "error": str(exc),
                "error_type": type(exc).__name__,
            }

        # ======================================================
        # NORMALIZED COMMAND VALIDATION
        # ======================================================

        if not isinstance(
            normalized,
            dict,
        ):

            with self.command_lock:

                self.commands_rejected += 1

            return {
                "status": "rejected",
                "reason": "invalid_normalized_command",
            }

        name = normalized.get(
            "name"
        )

        # ======================================================
        # COMMAND RECEIVED
        # ======================================================

        with self.command_lock:

            self.commands_received += 1

        # ======================================================
        # EMPTY COMMAND
        # ======================================================

        if not name:

            with self.command_lock:

                self.commands_rejected += 1

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        # ======================================================
        # COMMAND NAME NORMALIZATION
        # ======================================================

        if not isinstance(
            name,
            str,
        ):

            with self.command_lock:

                self.commands_rejected += 1

            return {
                "status": "rejected",
                "reason": "invalid_command_name",
                "type": type(name).__name__,
            }

        name = name.strip().upper()

        if not name:

            with self.command_lock:

                self.commands_rejected += 1

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        normalized[
            "name"
        ] = name

        # ======================================================
        # RESOLVE HANDLER
        # ======================================================

        with self.command_lock:

            handler = self.command_registry.get(
                name
            )

        if handler is None:

            with self.command_lock:

                self.commands_rejected += 1

            available = self.get_command_list()

            self.logger.warning(
                "[QbitDialer] Unknown Qbit command | %s",
                name,
            )

            return {
                "status": "rejected",
                "command": name,
                "reason": "unknown_command",
                "available": available,
            }

        # ======================================================
        # AUTHORITATIVE QBIT
        # ======================================================

        qbit = normalized.get(
            "qbit"
        )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit_instance",
                None,
            )

        # ------------------------------------------------------
        # Commands can execute without a Qbit only if your
        # architecture explicitly permits that command.
        #
        # Do NOT manufacture one here.
        # ------------------------------------------------------

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Command rejected | "
                "authoritative Qbit unavailable | "
                "command=%s",
                name,
            )

            with self.command_lock:

                self.commands_rejected += 1

            return {
                "status": "rejected",
                "command": name,
                "reason": "qbit_unavailable",
            }

        # ======================================================
        # VERIFY BOOT-OWNED QUEUE CONNECTION
        # ======================================================

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "queue_loop",
                None,
            )

        if queue_loop is not None:

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if (
                bound_dialer is not None
                and bound_dialer is not self
            ):

                with self.command_lock:

                    self.commands_rejected += 1

                raise RuntimeError(
                    "[QbitDialer] FATAL: QbitQueueLoop "
                    "is bound to another QbitDialer"
                )

        # ======================================================
        # PRESERVE / GENERATE TRACK ID
        # ======================================================

        track_id = normalized.get(
            "track_id"
        )

        if not track_id:

            track_id = getattr(
                qbit,
                "track_id",
                None,
            )

        if not track_id:

            track_id = (
                self._generate_command_track_id(
                    name
                )
            )

        normalized[
            "track_id"
        ] = track_id

        # ======================================================
        # PRESERVE QBIT ID
        # ======================================================

        qbit_id = normalized.get(
            "qbit_id"
        )

        if not qbit_id:

            qbit_id = getattr(
                qbit,
                "id",
                None,
            )

        normalized[
            "qbit_id"
        ] = qbit_id

        # ======================================================
        # ADMISSION RECORD
        # ======================================================

        command_entry = {
            "command": name,
            "track_id": track_id,
            "qbit_id": qbit_id,
            "timestamp": time.time(),
            "source": normalized.get(
                "source",
                "QBIT",
            ),
            "priority": normalized.get(
                "priority",
                5,
            ),
            "confidence": normalized.get(
                "confidence",
                1.0,
            ),
            "state": "ADMITTED",
        }

        self._record_command_history(
            command_entry
        )

        with self.command_lock:

            self.commands_accepted += 1

            self.command_plane[
                "last_command"
            ] = name

            self.command_plane[
                "last_track_id"
            ] = track_id

            self.command_plane[
                "last_command_time"
            ] = time.time()

        self.logger.info(
            "[QbitDialer] QBIT COMMAND ADMITTED | "
            "command=%s | QbitID=%s | TrackID=%s",
            name,
            qbit_id,
            track_id,
        )

        # ======================================================
        # EXECUTE REGISTERED HANDLER
        # ======================================================

        try:

            payload = normalized.get(
                "payload",
                {},
            )

            if isinstance(
                payload,
                dict,
            ):

                payload = dict(
                    payload
                )

                payload.setdefault(
                    "qbit",
                    qbit,
                )

                payload.setdefault(
                    "qbit_id",
                    qbit_id,
                )

                payload.setdefault(
                    "track_id",
                    track_id,
                )

                payload.setdefault(
                    "thought",
                    normalized.get(
                        "thought"
                    ),
                )

                payload.setdefault(
                    "intent",
                    normalized.get(
                        "intent"
                    ),
                )

                payload.setdefault(
                    "action",
                    normalized.get(
                        "action"
                    ),
                )

                payload.setdefault(
                    "compute",
                    normalized.get(
                        "compute"
                    ),
                )

                payload.setdefault(
                    "transform",
                    normalized.get(
                        "transform"
                    ),
                )

            args = normalized.get(
                "args",
                [],
            )

            kwargs = normalized.get(
                "kwargs",
                {},
            )

            if args is None:

                args = []

            if kwargs is None:

                kwargs = {}

            result = handler(
                payload,
                *args,
                **kwargs,
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            # ==================================================
            # COMPLETED
            # ==================================================

            with self.command_lock:

                self.commands_executed += 1

                self.command_plane[
                    "last_result_status"
                ] = "completed"

            command_entry[
                "state"
            ] = "COMPLETED"

            command_entry[
                "completed_at"
            ] = time.time()

            self.logger.info(
                "[QbitDialer] QBIT COMMAND COMPLETE | "
                "command=%s | QbitID=%s | TrackID=%s",
                name,
                qbit_id,
                track_id,
            )

            return {
                "status": "completed",
                "command": name,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "result": result,
            }

        except asyncio.CancelledError:

            with self.command_lock:

                self.commands_cancelled += 1

            command_entry[
                "state"
            ] = "CANCELLED"

            command_entry[
                "cancelled_at"
            ] = time.time()

            raise

        except Exception as exc:

            with self.command_lock:

                self.commands_failed += 1

                self.command_plane[
                    "last_result_status"
                ] = "failed"

            command_entry[
                "state"
            ] = "FAILED"

            command_entry[
                "error"
            ] = str(exc)

            command_entry[
                "error_type"
            ] = type(exc).__name__

            self.logger.exception(
                "[QbitDialer] Qbit command failed | "
                "command=%s | QbitID=%s | TrackID=%s",
                name,
                qbit_id,
                track_id,
            )

            return {
                "status": "failed",
                "command": name,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "error": str(exc),
                "error_type": type(exc).__name__,
            }

# ==========================================================
# PUBLIC COMMAND ENTRY
#
# ONE AUTHORITATIVE EXECUTION PATH.
#
# All executable commands eventually terminate here.
#
# Public callers may use:
#
#     execute_command(...)
#
# Internal Qbit command processing may use:
#
#     _execute_qbit_command(...)
#
# There is NO second executor.
# There is NO second command queue.
#
# IMPORTANT:
#
# Raw Qbit objects are DATA.
#
# They MUST be intercepted BEFORE command normalization.
#
# RAW QBIT:
#
#     Qbit
#       â†“
#     _process_received_qbit()
#       â†“
#     ComputeBrain
#       â†“
#     TransformerBrain
#       â†“
#     command envelope
#       â†“
#     QbitDialer command plane
#
# COMMAND ENVELOPE:
#
#     command envelope
#       â†“
#     _execute_qbit_command()
#
# ==========================================================

    async def execute_command(
        self,
        cmd,
        create_task=None,
    ):
        try:
            if cmd is None:
                return {
                    "status": "rejected",
                    "reason": "empty_command",
                }

            qbit_type = globals().get("Qbit", None)

            if qbit_type is not None and isinstance(cmd, qbit_type):
                self.logger.debug(
                    "[QbitDialer] Raw Qbit received through execute_command"
                )

                result = self._process_received_qbit(cmd)

                if inspect.isawaitable(result):
                    result = await result

                return result

            return await self._execute_qbit_command(cmd)

        except asyncio.CancelledError:
            raise

        except Exception as exc:
            self.logger.exception(
                "[QbitDialer] execute_command failed | error=%s",
                exc,
            )

            return {
                "status": "error",
                "reason": "execute_command_failed",
                "error": str(exc),
            }
    # ==========================================================
    # SAFE COMMAND HANDLERS
    # ==========================================================

    async def _cmd_status(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        return self.command_status()


    async def _cmd_measure(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        try:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

            if qbit is None:

                qbit = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

            if qbit is None:

                raise RuntimeError(
                    "Qbit instance unavailable"
                )

            measure = getattr(
                qbit,
                "measure",
                None,
            )

            if not callable(
                measure
            ):

                raise RuntimeError(
                    "Qbit does not provide measure()"
                )

            value = measure()

            self.last_measurement = value

            return {
                "measurement": value,
                "timestamp": time.time(),
            }

        except Exception as exc:

            return {
                "measurement": None,
                "error": str(exc),
                "error_type": type(exc).__name__,
            }


    async def _cmd_get_state(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        try:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

            if qbit is None:

                qbit = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

            if qbit is not None:

                as_tuple = getattr(
                    qbit,
                    "as_tuple",
                    None,
                )

                if callable(
                    as_tuple
                ):

                    return {
                        "state": as_tuple()
                    }

            return {
                "state": getattr(
                    self,
                    "qbit_state",
                    None,
                )
            }

        except Exception as exc:

            return {
                "state": None,
                "error": str(exc),
            }


    async def _cmd_queue_status(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        queue_obj = getattr(
            self,
            "command_queue",
            None,
        )

        if queue_obj is None:

            queue_obj = getattr(
                self,
                "qbit_queue",
                None,
            )

        try:

            if queue_obj is not None:

                qsize = getattr(
                    queue_obj,
                    "qsize",
                    None,
                )

                if callable(
                    qsize
                ):

                    depth = qsize()

                else:

                    depth = (
                        len(queue_obj)
                        if hasattr(
                            queue_obj,
                            "__len__",
                        )
                        else 0
                    )

            else:

                depth = 0

        except Exception:

            depth = 0

        return {
            "depth": depth,
            "command_queue": (
                "online"
                if queue_obj is not None
                else "offline"
            ),
        }


    async def _cmd_heartbeat_status(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        heartbeat = getattr(
            self,
            "heartbeat",
            None,
        )

        return {
            "last_heartbeat": getattr(
                self,
                "last_heartbeat",
                None,
            ),

            "internal_clock": getattr(
                self,
                "_internal_clock",
                None,
            ),

            "heartbeat_attached": (
                heartbeat is not None
            ),

            "heartbeat_running": bool(
                getattr(
                    heartbeat,
                    "_running",
                    False,
                )
            )
            if heartbeat is not None
            else False,
        }


    async def _cmd_cognition_status(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        cognition = getattr(
            self,
            "cognition_map",
            None,
        )

        if cognition is None:

            cognition = getattr(
                self,
                "CognitionMap",
                None,
            )

        return {
            "available": (
                cognition is not None
            ),

            "type": (
                type(cognition).__name__
                if cognition is not None
                else None
            ),

            "queue_attached": bool(
                getattr(
                    cognition,
                    "queue",
                    None,
                )
            )
            if cognition is not None
            else False,
        }


    async def _cmd_snapshot(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        return {
            "command_plane": self.command_status(),

            "qbit_state": getattr(
                self,
                "qbit_state",
                None,
            ),

            "last_measurement": getattr(
                self,
                "last_measurement",
                None,
            ),

            "last_heartbeat": getattr(
                self,
                "last_heartbeat",
                None,
            ),

            "qbit_runtime": getattr(
                self,
                "_qbit_runtime_state",
                "UNKNOWN",
            ),

            "timestamp": time.time(),
        }



    # ==========================================================
    # GOVERNED COMMANDS
    # ==========================================================

    async def _cmd_throttle(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        payload = (
            payload
            if isinstance(
                payload,
                dict,
            )
            else {}
        )

        speed = payload.get(
            "speed",
            payload.get(
                "factor",
                0.5,
            ),
        )

        try:
            speed = float(
                speed
            )

        except (
            TypeError,
            ValueError,
        ):
            speed = 0.5

        speed = max(
            0.1,
            min(
                speed,
                1.0,
            ),
        )

        self.speed = speed

        return {
            "action": "THROTTLE",
            "speed": speed,
            "status": "applied",
        }


    async def _cmd_defer(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        self._qbit_background_deferred = True

        return {
            "action": "DEFER",
            "background_deferred": True,
            "status": "applied",
        }


    async def _cmd_resume(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        self._qbit_background_deferred = False

        return {
            "action": "RESUME",
            "background_deferred": False,
            "status": "applied",
        }


    async def _cmd_pause_background(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        self._qbit_background_deferred = True

        return {
            "action": "PAUSE_BACKGROUND",
            "background_paused": True,
            "status": "applied",
        }


    async def _cmd_prioritize(
        self,
        payload=None,
        *args,
        **kwargs,
    ):

        payload = (
            payload
            if isinstance(
                payload,
                dict,
            )
            else {}
        )

        target = payload.get(
            "target"
        )

        priority = payload.get(
            "priority",
            5,
        )

        try:
            priority = int(
                priority
            )

        except (
            TypeError,
            ValueError,
        ):
            priority = 5

        priority = max(
            0,
            min(
                priority,
                10,
            ),
        )

        # Keep the last priority request available to the
        # governor/queue without pretending this handler owns
        # the governor itself.
        self._qbit_priority_request = {
            "target": target,
            "priority": priority,
            "timestamp": time.time(),
        }

        return {
            "action": "PRIORITIZE",
            "target": target,
            "priority": priority,
            "status": "accepted",
        }
# =============================================================

    def _extract_action_from_cognitive_result(
        self,
        cognitive_result,
    ):

        if cognitive_result is None:
            return None

        if not isinstance(
            cognitive_result,
            dict,
        ):
            return None

        # ----------------------------------------------------------
        # Direct / nested cognitive command candidates
        # ----------------------------------------------------------

        candidates = (
            cognitive_result.get("command"),
            cognitive_result.get("action"),
            cognitive_result.get("command_envelope"),
            cognitive_result.get("executable_command"),
        )

        for candidate in candidates:

            # ------------------------------------------------------
            # Nested command envelope
            # ------------------------------------------------------

            if isinstance(
                candidate,
                dict,
            ):

                action = (
                    candidate.get("name")
                    or candidate.get("command")
                    or candidate.get("cmd")
                    or candidate.get("action")
                )

                if isinstance(
                    action,
                    dict,
                ):
                    action = (
                        action.get("name")
                        or action.get("command")
                        or action.get("cmd")
                        or action.get("action")
                    )

                if isinstance(
                    action,
                    str,
                ):

                    action = action.strip()

                    if not action:
                        continue

                    normalized = action.upper()

                    if normalized in {
                        "IDLE",
                        "COMPUTE_BRAIN",
                    }:
                        return None

                    return dict(candidate)

            # ------------------------------------------------------
            # Direct string command/action
            # ------------------------------------------------------

            elif isinstance(
                candidate,
                str,
            ):

                action = candidate.strip()

                if not action:
                    continue

                normalized = action.upper()

                if normalized in {
                    "IDLE",
                    "COMPUTE_BRAIN",
                }:
                    return None

                return {
                    "name": normalized,
                }

        # ----------------------------------------------------------
        # Direct command envelope compatibility
        # ----------------------------------------------------------

        direct_name = (
            cognitive_result.get("name")
            or cognitive_result.get("command_name")
            or cognitive_result.get("cmd")
        )

        if isinstance(
            direct_name,
            dict,
        ):
            direct_name = (
                direct_name.get("name")
                or direct_name.get("command")
                or direct_name.get("cmd")
                or direct_name.get("action")
            )

        if isinstance(
            direct_name,
            str,
        ):

            direct_name = direct_name.strip()

            if direct_name:

                normalized = direct_name.upper()

                if normalized not in {
                    "IDLE",
                    "COMPUTE_BRAIN",
                }:
                    return {
                        "name": normalized,
                    }

        # ----------------------------------------------------------
        # No actionable command.
        #
        # CognitiveResult is retained as cognition/data.
        # It MUST NOT proceed to command normalization.
        # ----------------------------------------------------------

        return None

    # ==========================================================

    # RECEIVED QBIT COGNITIVE PIPELINE

    #

    # AUTHORITATIVE QBIT INGESTION PATH

    #

    # QbitQueueLoop

    # |

    # v

    # submit_qbit_command()

    # |

    # v

    # _process_received_qbit()

    # |

    # +----> TrackSystem

    # |

    # +----> ComputeBrain

    # |          |

    # |          v

    # |     ThoughtPacket

    # |

    # +----> TransformerBrain

    # |

    # v

    # _build_cognitive_command()

    # |

    # v

    # submit_command()

    # |

    # v

    # COMMAND REGISTRY

    # |

    # v

    # AUTHORITATIVE QUEUE

    #

    # RULES:

    #

    # - Incoming Qbit is DATA.

    # - Never stringify Qbit into a command.

    # - Never manufacture a replacement Qbit.

    # - Never create a second QbitQueueLoop.

    # - Never create a second command queue.

    # - create_task() remains the task/Qbit construction authority.

    # - Existing authoritative task context is always preferred.

    # - ComputeBrain performs cognition only.

    # - TransformerBrain performs transformation only.

    # - _build_cognitive_command() is the only cognition->command bridge.

    # - QbitDialer owns command admission.

    # - submit_command() is the sole executable handoff.

    # - TrackSystem owns track context.

    # - Qbit identity and lineage are preserved end-to-end.

    # - Oracle/governance may observe this pipeline but may not bypass

    # submit_command() or create a parallel command path.

    # ==========================================================

    async def _process_received_qbit(
        self,
        qbit,
        metadata=None,
    ):

        # ======================================================
        # 1. HARD INPUT VALIDATION
        # ======================================================

        if qbit is None:

            self.logger.warning(
                "[QbitDialer] Qbit receive rejected | "
                "reason=qbit_unavailable"
            )

            return {
                "status": "rejected",
                "stage": "receive",
                "reason": "qbit_unavailable",
            }

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and not isinstance(
                qbit,
                qbit_type,
            )
        ):

            self.logger.warning(
                "[QbitDialer] Qbit receive rejected | "
                "invalid_type=%s",
                type(qbit).__name__,
            )

            return {
                "status": "rejected",
                "stage": "receive",
                "reason": "invalid_qbit_type",
                "type": type(qbit).__name__,
            }

        # ======================================================
        # 2. PRESERVE AUTHORITATIVE QBIT IDENTITY
        #
        # IMPORTANT:
        #
        # qbit_id and track_id below belong to the RECEIVED QBIT.
        #
        # They MUST NOT later be replaced by task["qbit_id"] or
        # task["track_id"].
        #
        # A recovered task may contain a separate task-Qbit ID.
        # That identity is retained separately as task_qbit_id.
        # ======================================================

        qbit_id = self._extract_qbit_field(
            qbit,
            "qbit_id",
            None,
        )

        if qbit_id is None:

            qbit_id = self._extract_qbit_field(
                qbit,
                "id",
                None,
            )

        track_id = self._extract_qbit_field(
            qbit,
            "track_id",
            None,
        )

        if track_id is None:

            track = self._extract_qbit_field(
                qbit,
                "track",
                None,
            )

            if isinstance(
                track,
                dict,
            ):

                track_id = (
                    track.get("track_id")
                    or track.get("id")
                )

            elif track is not None:

                track_id = (
                    getattr(
                        track,
                        "track_id",
                        None,
                    )
                    or getattr(
                        track,
                        "id",
                        None,
                    )
                )

        if qbit_id is None:

            self.logger.warning(
                "[QbitDialer] Qbit receive rejected | "
                "reason=missing_qbit_id | "
                "type=%s",
                type(qbit).__name__,
            )

            return {
                "status": "rejected",
                "stage": "identity",
                "reason": "missing_qbit_id",
                "track_id": track_id,
            }

        # ======================================================
        # 3. RESOLVE EXISTING AUTHORITATIVE TASK
        #
        # IMPORTANT:
        #
        # The incoming Qbit remains authoritative.
        #
        # We first inspect all task-bearing locations already
        # attached to the received Qbit.
        #
        # create_task() is only used as the established recovery
        # mechanism when the incoming Qbit genuinely lacks task
        # context.
        #
        # source_qbit=qbit explicitly binds recovery to THIS
        # received Qbit. This prevents create_task() from falling
        # back to self.qbit and accidentally using a stale/root
        # Qbit as the source.
        #
        # The result of create_task() is NEVER substituted for
        # the received Qbit.
        # ======================================================

        task = getattr(
            qbit,
            "task",
            None,
        )

        if not isinstance(
            task,
            dict,
        ):

            task = self._extract_qbit_field(
                qbit,
                "task",
                None,
            )

        if not isinstance(
            task,
            dict,
        ):

            payload = self._extract_qbit_field(
                qbit,
                "payload",
                None,
            )

            if payload is None:

                payload = self._extract_qbit_field(
                    qbit,
                    "data",
                    None,
                )

            if payload is None:
                payload = {}

            try:

                created_context = self.create_task(
                    payload=payload,
                    source_qbit=qbit,
                )

                if inspect.isawaitable(
                    created_context
                ):

                    created_context = await created_context

                # --------------------------------------------------
                # NEVER replace the received Qbit.
                #
                # We only borrow task metadata from the
                # authoritative create_task() result.
                # --------------------------------------------------

                if created_context is qbit:

                    recovered_task = getattr(
                        qbit,
                        "task",
                        None,
                    )

                    if isinstance(
                        recovered_task,
                        dict,
                    ):

                        task = recovered_task

                else:

                    recovered_task = getattr(
                        created_context,
                        "task",
                        None,
                    )

                    if isinstance(
                        recovered_task,
                        dict,
                    ):

                        task = recovered_task

                    elif isinstance(
                        created_context,
                        dict,
                    ):

                        # Some create_task() implementations return
                        # the task dictionary directly.
                        task_candidate = (
                            created_context.get(
                                "task"
                            )
                        )

                        if isinstance(
                            task_candidate,
                            dict,
                        ):

                            task = task_candidate

                        elif (
                            created_context.get(
                                "task_id"
                            )
                            or created_context.get(
                                "qbit_id"
                            )
                        ):

                            task = dict(
                                created_context
                            )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Qbit task recovery failed | "
                    "qbit_id=%s | error=%s",
                    qbit_id,
                    exc,
                )

        # ======================================================
        # 4. RE-READ AUTHORITATIVE TASK IDENTITY
        #
        # IMPORTANT:
        #
        # The task may contain its own Qbit identity.
        #
        # That identity is NOT the identity of the received Qbit.
        #
        # Therefore:
        #
        #     qbit_id       = received Qbit
        #     task_qbit_id  = task-created Qbit, if present
        #     task_id       = logical task identity
        #
        # The incoming qbit_id and track_id are immutable for
        # this processing pass.
        # ======================================================

        task_qbit_id = None

        if isinstance(
            task,
            dict,
        ):

            task_qbit_id = (
                task.get("qbit_id")
                or task.get("id")
            )

            task_id = task.get(
                "task_id"
            )

            task_commands = task.get(
                "commands",
                [],
            )

            if not isinstance(
                task_commands,
                (list, tuple),
            ):

                task_commands = []

        else:

            task_id = self._extract_qbit_field(
                qbit,
                "task_id",
                None,
            )

            task_commands = []

        # ======================================================
        # 5. COMMAND REGISTRY SYNCHRONIZATION
        #
        # Existing registry only.
        # No second registry is created.
        # ======================================================

        if task_commands:

            try:

                self._register_phase1_commands(
                    command_list=task_commands,
                )

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Task command capability "
                    "synchronization failed | "
                    "qbit_id=%s | task_id=%s | error=%s",
                    qbit_id,
                    task_id,
                    exc,
                )

        # ======================================================
        # 6. TRACKSYSTEM CONNECTION
        #
        # TrackSystem owns track context.
        # QbitDialer reads it.
        #
        # track_id is the incoming Qbit's authoritative track.
        # ======================================================

        track_system = getattr(
            self,
            "track_system",
            None,
        )

        track_context = None

        if track_system is not None:

            try:

                resolver = getattr(
                    track_system,
                    "get_track",
                    None,
                )

                if not callable(
                    resolver
                ):

                    resolver = getattr(
                        track_system,
                        "get_track_context",
                        None,
                    )

                if callable(
                    resolver
                ):

                    track_context = resolver(
                        track_id
                    )

                    if inspect.isawaitable(
                        track_context
                    ):

                        track_context = (
                            await track_context
                        )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.debug(
                    "[QbitDialer] TrackSystem lookup failed | "
                    "qbit_id=%s | track_id=%s | error=%s",
                    qbit_id,
                    track_id,
                    exc,
                )

        # ======================================================
        # 7. PRESERVE PIPELINE IDENTITY
        # ======================================================

        pipeline_id = self._extract_qbit_field(
            qbit,
            "pipeline_id",
            None,
        )

        if (
            pipeline_id is None
            and isinstance(
                task,
                dict,
            )
        ):

            pipeline_id = task.get(
                "pipeline_id"
            )

        if pipeline_id is None:

            pipeline_id = (
                f"QPIPE-{uuid4()}"
            )

        # ======================================================
        # 8. SOURCE / CHANNEL / PROVENANCE
        #
        # Prefer the received Qbit's provenance.
        # Task metadata is fallback context only.
        # ======================================================

        source = self._extract_qbit_field(qbit, "source", None)
        if isinstance(metadata, dict):
            source = source or metadata.get("source") or metadata.get("source_of_start")
        if source is None and isinstance(task, dict):
            source = task.get("source") or task.get("source_of_start")
        if source is None:
            source = self._extract_qbit_field(qbit, "upstream_source", None)
        if source is None:
            source = self._extract_qbit_field(qbit, "origin", "QBIT")

        # Preserve source, classification, and intent through cognition.
        classification = self._extract_qbit_field(qbit, "classification", None)
        if classification is None:
            classification = self._extract_qbit_field(qbit, "data_class", None)
        if isinstance(metadata, dict):
            classification = classification or metadata.get("classification") or metadata.get("data_class")
        if classification is None and isinstance(task, dict):
            classification = task.get("classification") or task.get("data_class")
        intent_name = self._extract_qbit_field(qbit, "intent", None)
        if isinstance(intent_name, dict):
            intent_name = intent_name.get("name") or intent_name.get("intent")
        if isinstance(metadata, dict):
            intent_name = intent_name or metadata.get("intent")
        if intent_name is None:
            try:
                intent_name = self._extract_intent_name(qbit)
            except Exception:
                intent_name = None
        if intent_name is None and isinstance(task, dict):
            intent_name = task.get("intent")
        if isinstance(intent_name, str) and intent_name.strip().lower() in {"", "unknown", "none", "null"}:
            intent_name = None
        if intent_name is None:
            intent_engine = getattr(self, "intent_engine", None)
            dominant = getattr(intent_engine, "dominant", None) if intent_engine is not None else None
            try:
                intent_name = dominant() if callable(dominant) else dominant
            except Exception:
                intent_name = None
        if intent_name is None:
            intent_name = "IDLE"

        source_of_start = source
        if isinstance(metadata, dict):
            source_of_start = metadata.get("source_of_start") or source_of_start
        provenance = self._extract_qbit_field(qbit, "provenance", None)
        if isinstance(provenance, dict):
            source_of_start = provenance.get("upstream_source") or provenance.get("source") or source_of_start
        channel = self._extract_qbit_field(
            qbit,
            "channel",
            None,
        )

        if (
            channel is None
            and isinstance(
                task,
                dict,
            )
        ):

            where = task.get(
                "where",
                {},
            )

            if isinstance(
                where,
                dict,
            ):

                channel = where.get(
                    "channel"
                )

        if channel is None:

            channel = self._extract_qbit_field(
                qbit,
                "channel_id",
                "QBIT",
            )

        # ======================================================
        # 9. AUTHORITATIVE COGNITIVE CONTEXT
        # ======================================================

        cognitive_context = {
            "classification": classification,
            "intent": intent_name,
            "source_of_start": source_of_start,

            "task_id": task_id,

            "qbit_id": qbit_id,

            "task_qbit_id": task_qbit_id,

            "track_id": track_id,

            "pipeline_id": pipeline_id,

            "source": source,

            "channel": channel,

            "task": task,

            "qbit": qbit,

            "track_context": track_context,

            "authority": "QbitDialer",

            "cognitive_authority": "QbitDialer",

            "command_authority": "QbitDialer",

        }

        self.last_qbit = qbit

        self.logger.info(
            "[QbitDialer] Qbit RECEIVE | "
            "task_id=%s | qbit_id=%s | task_qbit_id=%s | "
            "track_id=%s | pipeline_id=%s | source=%s | "
            "channel=%s",
            task_id,
            qbit_id,
            task_qbit_id,
            track_id,
            pipeline_id,
            source,
            channel,
        )

        # ======================================================
        # 10. HEALTH SNAPSHOT
        # ======================================================

        health = {}

        try:

            health_monitor = getattr(
                self,
                "health_monitor",
                None,
            )

            if health_monitor is not None:

                get_state = getattr(
                    health_monitor,
                    "get_state",
                    None,
                )

                if callable(
                    get_state
                ):

                    health_result = get_state()

                    if inspect.isawaitable(
                        health_result
                    ):

                        health_result = (
                            await health_result
                        )

                    if isinstance(
                        health_result,
                        dict,
                    ):

                        health = dict(
                            health_result
                        )

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.debug(
                "[QbitDialer] Health snapshot unavailable | "
                "qbit_id=%s | error=%s",
                qbit_id,
                exc,
            )

        # ======================================================
        # 11. REUSE EXISTING COMPUTE RESULT
        # ======================================================

        compute_result = None

        if isinstance(
            task,
            dict,
        ):

            compute_result = task.get(
                "compute_result"
            )

        if compute_result is None:

            compute_result = (
                self._extract_qbit_field(
                    qbit,
                    "compute_result",
                    None,
                )
            )

        # ======================================================
        # 12. COMPUTE BRAIN
        #
        # Qbit -> ThoughtPacket
        #
        # ComputeBrain DOES NOT execute commands.
        #
        # IMPORTANT:
        #
        # The exact received Qbit is passed through. The task
        # Qbit is context only and cannot replace it.
        # ======================================================

        action_proposal = None

        if compute_result is None:

            compute_input = {
                "classification": classification,
                "intent": intent_name,
                "source_of_start": source_of_start,

                "qbit": qbit,

                "task": task,

                "task_id": task_id,

                "qbit_id": qbit_id,

                "task_qbit_id": task_qbit_id,

                "track_id": track_id,

                "track_context": track_context,

                "source": source,

                "channel": channel,

                "health": health,

                "pipeline_id": pipeline_id,

                "lineage": (
                    task.get(
                        "data_lineage"
                    )
                    if isinstance(
                        task,
                        dict,
                    )
                    else None
                ),

                "relationships": (
                    task.get(
                        "relationships"
                    )
                    if isinstance(
                        task,
                        dict,
                    )
                    else None
                ),

                "authority": "QbitDialer",

                "cognitive_authority": "QbitDialer",

            }

            try:

                compute_result = (
                    await self._run_cognitive_stage(
                        "compute",
                        compute_input,
                    )
                )

                # ThoughtPacket / TransformerBrain stage
                transform_result = await self._run_cognitive_stage(
                    "transform",
                    compute_result,
                )

                if inspect.isawaitable(transform_result):
                    transform_result = await transform_result

                action_engine = getattr(
                    self,
                    "action_engine",
                    None,
                )

                if action_engine is None:
                    raise RuntimeError(
                        "ActionEngine not attached to QbitDialer"
                    )

                action_state = {}
                if isinstance(self.qbit_state, dict):
                    action_state.update(self.qbit_state)
                action_state.update(cognitive_context)
                action_state.update({
                    "qbit": qbit,
                    "qbit_id": qbit_id,
                    "track_id": track_id,
                    "source": source,
                    "source_of_start": source_of_start,
                    "classification": classification,
                    "intent": intent_name,
                    "task_id": task_id,
                    "pipeline_id": pipeline_id,
                })
                action_proposal = (
                    self.action_engine.think_and_act(
                        action_state
                    )
                )

                if inspect.isawaitable(
                    action_proposal
                ):
                    action_proposal = await action_proposal

                if action_proposal is None:
                    idle_reason = None
                    if isinstance(task, dict):
                        idle_reason = task.get("intent")
                        if idle_reason is None and isinstance(task.get("why"), dict):
                            idle_reason = task["why"].get("name")
                    if isinstance(idle_reason, str) and idle_reason.strip().upper() == "IDLE":
                        action_proposal = {
                            "action": "OBSERVE_SYSTEM",
                            "name": "OBSERVE_SYSTEM",
                            "execution_required": False,
                            "actionable": False,
                            "has_actionable_command": False,
                            "origin": "IdleIntent",
                            "reason": "IDLE heartbeat requires a bounded watch/wait decision",
                        }

                cognitive_context[
                    "action_proposal"
                ] = action_proposal

                if inspect.isawaitable(
                    compute_result
                ):

                    compute_result = (
                        await compute_result
                    )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] ComputeBrain decode failure | "
                    "task_id=%s | qbit_id=%s | track_id=%s",
                    task_id,
                    qbit_id,
                    track_id,
                )

                return {

                    "status": "failed",

                    "stage": "ComputeBrain",

                    **cognitive_context,

                    "health": health,

                    "error": str(exc),

                    "error_type": type(
                        exc
                    ).__name__,

                }

        # ======================================================
        # 13. REQUIRE THOUGHTPACKET
        # ======================================================

        if compute_result is None:

            self.logger.warning(
                "[QbitDialer] ComputeBrain produced no "
                "ThoughtPacket | task_id=%s | qbit_id=%s",
                task_id,
                qbit_id,
            )

            return {

                "status": "no_thought",

                "stage": "ComputeBrain",

                **cognitive_context,

                "health": health,

            }

        # ======================================================
        # 14. PRESERVE THOUGHTPACKET IDENTITY
        # ======================================================

        if isinstance(
            compute_result,
            dict,
        ):

            compute_result.setdefault(
                "packet_type",
                "ThoughtPacket",
            )

            compute_result.setdefault(
                "type",
                "ThoughtPacket",
            )

            compute_result.setdefault(
                "task_id",
                task_id,
            )

            compute_result.setdefault(
                "task_qbit_id",
                task_qbit_id,
            )

            compute_result.setdefault(
                "pipeline_id",
                pipeline_id,
            )

            compute_result.setdefault(
                "qbit_id",
                qbit_id,
            )

            compute_result.setdefault(
                "track_id",
                track_id,
            )

            compute_result.setdefault(
                "source",
                source,
            )

            compute_result.setdefault(
                "source_of_start",
                source,
            )

            compute_result.setdefault(
                "classification",
                classification,
            )

            compute_result.setdefault(
                "intent",
                intent_name,
            )

            compute_result.setdefault(
                "channel",
                channel,
            )

            compute_result.setdefault(
                "health",
                health,
            )

            compute_result.setdefault(
                "task",
                task,
            )

            compute_result.setdefault(
                "qbit",
                qbit,
            )

            compute_result.setdefault(
                "authority",
                "QbitDialer",
            )

        # ======================================================
        # 15. TRANSFORMER INPUT
        # ======================================================

        transformer_input = {
            "classification": classification,
            "intent": intent_name,
            "source_of_start": source_of_start,

            "packet_type": "ThoughtPacket",

            "task_id": task_id,

            "task_qbit_id": task_qbit_id,

            "pipeline_id": pipeline_id,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "track_context": track_context,

            "source": source,

            "channel": channel,

            "thought": compute_result,

            "health": health,

            "task": task,

            "lineage": (
                task.get(
                    "data_lineage"
                )
                if isinstance(
                    task,
                    dict,
                )
                else None
            ),

            "relationships": (
                task.get(
                    "relationships"
                )
                if isinstance(
                    task,
                    dict,
                )
                else None
            ),

            "authority": "QbitDialer",

            "cognitive_authority": "QbitDialer",

        }

        # ======================================================
        # 16. TRANSFORMER BRAIN
        #
        # ThoughtPacket -> CognitiveResult
        #
        # TransformerBrain DOES NOT execute commands.
        # ======================================================

        try:

            transform_result = (
                await self._run_cognitive_stage(
                    "transform",
                    transformer_input,
                )
            )

            if inspect.isawaitable(
                transform_result
            ):

                transform_result = (
                    await transform_result
                )

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] TransformerBrain "
                "transformation failure | "
                "task_id=%s | qbit_id=%s | track_id=%s",
                task_id,
                qbit_id,
                track_id,
            )

            return {

                "status": "failed",

                "stage": "TransformerBrain",

                **cognitive_context,

                "thought": compute_result,

                "health": health,

                "error": str(exc),

                "error_type": type(
                    exc
                ).__name__,

            }

        # ======================================================
        # 17. PRESERVE TRANSFORMED IDENTITY
        # ======================================================

        if isinstance(
            transform_result,
            dict,
        ):

            transform_result.setdefault(
                "packet_type",
                "TransformedThoughtPacket",
            )

            transform_result.setdefault(
                "task_id",
                task_id,
            )

            transform_result.setdefault(
                "task_qbit_id",
                task_qbit_id,
            )

            transform_result.setdefault(
                "pipeline_id",
                pipeline_id,
            )

            transform_result.setdefault(
                "qbit_id",
                qbit_id,
            )

            transform_result.setdefault(
                "track_id",
                track_id,
            )

            transform_result.setdefault(
                "source",
                source,
            )

            transform_result.setdefault(
                "source_of_start",
                source,
            )

            transform_result.setdefault(
                "classification",
                classification,
            )

            transform_result.setdefault(
                "intent",
                intent_name,
            )

            transform_result.setdefault(
                "channel",
                channel,
            )

            transform_result.setdefault(
                "task",
                task,
            )

            transform_result.setdefault(
                "qbit",
                qbit,
            )

            transform_result.setdefault(
                "authority",
                "QbitDialer",
            )

        # ======================================================
        # 18. BUILD COMMAND
        #
        # ONLY cognitive -> command bridge.
        # ======================================================

        command = self._build_cognitive_command(
            qbit=qbit,
            compute_result=compute_result,
            transform_result=transform_result,
            action_proposal=action_proposal,
        )

        # ======================================================
        # 19. NO COMMAND
        # ======================================================

        if command is None:

            self.logger.info(
                "[QbitDialer] ThoughtPacket produced "
                "no actionable command | "
                "task_id=%s | qbit_id=%s | track_id=%s",
                task_id,
                qbit_id,
                track_id,
            )

            return {

                "status": "no_command",

                "stage": "TransformerBrain",

                **cognitive_context,

                "thought": compute_result,

                "transform": transform_result,

                "health": health,

            }

        # ======================================================
        # 20. COMMAND ENVELOPE VALIDATION
        # ======================================================

        if not isinstance(
            command,
            dict,
        ):

            self.logger.warning(
                "[QbitDialer] Transformer produced "
                "invalid non-dict command output | "
                "task_id=%s | qbit_id=%s | type=%s",
                task_id,
                qbit_id,
                type(command).__name__,
            )

            return {

                "status": "no_command",

                "stage": "command_build",

                **cognitive_context,

                "thought": compute_result,

                "transform": transform_result,

                "health": health,

                "reason": (
                    "transformer_command_not_envelope"
                ),

            }

        command = dict(
            command
        )

        # ======================================================
        # 21. RESOLVE EXPLICIT COMMAND NAME
        #
        # Command identity MUST originate from explicit
        # TransformerBrain output.
        #
        # NEVER:
        #
        #     str(qbit)
        #
        # NEVER:
        #
        #     qbit -> command
        # ======================================================

        command_name = (
            command.get("name")
            or command.get("command")
            or command.get("cmd")
            or command.get("action")
        )

        if isinstance(
            command_name,
            dict,
        ):

            command_name = (
                command_name.get("name")
                or command_name.get("command")
                or command_name.get("cmd")
            )

        if command_name is None:

            if isinstance(
                transform_result,
                dict,
            ):

                candidate = (
                    transform_result.get("name")
                    or transform_result.get("command")
                    or transform_result.get("cmd")
                    or transform_result.get("action")
                )

                if isinstance(
                    candidate,
                    dict,
                ):

                    candidate = (
                        candidate.get("name")
                        or candidate.get("command")
                        or candidate.get("cmd")
                    )

                if (
                    isinstance(
                        candidate,
                        str,
                    )
                    and candidate.strip()
                ):

                    command_name = candidate

        if not isinstance(
            command_name,
            str,
        ):

            self.logger.info(
                "[QbitDialer] ThoughtPacket retained | "
                "TransformerBrain produced no executable "
                "command name | task_id=%s | qbit_id=%s | "
                "track_id=%s",
                task_id,
                qbit_id,
                track_id,
            )

            return {

                "status": "no_command",

                "stage": "command_validation",

                **cognitive_context,

                "thought": compute_result,

                "transform": transform_result,

                "health": health,

            }

        command_name = command_name.strip()

        if not command_name:

            return {

                "status": "no_command",

                "stage": "command_validation",

                **cognitive_context,

                "thought": compute_result,

                "transform": transform_result,

                "health": health,

            }

        command[
            "name"
        ] = command_name.upper()

        # ======================================================
        # 22. PRESERVE COMPLETE COMMAND CONTEXT
        # ======================================================

        command.setdefault(
            "task_id",
            task_id,
        )

        command.setdefault(
            "task_qbit_id",
            task_qbit_id,
        )

        command.setdefault(
            "pipeline_id",
            pipeline_id,
        )

        command.setdefault(
            "qbit",
            qbit,
        )

        command.setdefault(
            "qbit_id",
            qbit_id,
        )

        command.setdefault(
            "track_id",
            track_id,
        )

        command.setdefault(
            "source",
            source,
        )

        command.setdefault(
            "classification",
            classification,
        )

        command.setdefault(
            "intent",
            intent_name,
        )

        command.setdefault(
            "source_of_start",
            source,
        )

        command.setdefault(
            "channel",
            channel,
        )

        command.setdefault(
            "track_context",
            track_context,
        )

        command.setdefault(
            "task",
            task,
        )

        command.setdefault(
            "thought",
            compute_result,
        )

        command.setdefault(
            "transform",
            transform_result,
        )

        command.setdefault(
            "health",
            health,
        )

        command.setdefault(
            "authority",
            "QbitDialer",
        )

        command.setdefault(
            "cognitive_authority",
            "QbitDialer",
        )

        command.setdefault(
            "command_authority",
            "QbitDialer",
        )

        # ======================================================
        # 23. PRESERVE EXPLICIT COGNITIVE FIELDS
        # ======================================================

        if (
            "intent" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_intent = (
                transform_result.get(
                    "intent"
                )
            )

            if explicit_intent is not None:

                command[
                    "intent"
                ] = explicit_intent

        if (
            "action" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_action = (
                transform_result.get(
                    "action"
                )
            )

            if explicit_action is not None:

                command[
                    "action"
                ] = explicit_action

        if (
            "compute" not in command
            and isinstance(
                transform_result,
                dict,
            )
        ):

            explicit_compute = (
                transform_result.get(
                    "compute"
                )
            )

            if explicit_compute is not None:

                command[
                    "compute"
                ] = explicit_compute

        # ======================================================
        # 24. PRESERVE LINEAGE / RELATIONSHIPS
        # ======================================================

        if (
            "lineage" not in command
            and isinstance(
                task,
                dict,
            )
        ):

            command[
                "lineage"
            ] = task.get(
                "data_lineage"
            )

        if (
            "relationships" not in command
            and isinstance(
                task,
                dict,
            )
        ):

            command[
                "relationships"
            ] = task.get(
                "relationships"
            )

        # ======================================================
        # 25. COMMAND ARGUMENT CONTRACT
        # ======================================================

        if command.get(
            "args"
        ) is None:

            command[
                "args"
            ] = []

        if command.get(
            "kwargs"
        ) is None:

            command[
                "kwargs"
            ] = {}

        if command.get(
            "payload"
        ) is None:

            command[
                "payload"
            ] = {}

        # ======================================================
        # 26. AUTHORITATIVE COMMAND ADMISSION
        #
        # THIS IS THE ONLY EXECUTABLE HANDOFF.
        #
        # TransformerBrain
        #       |
        #       v
        # _build_cognitive_command()
        #       |
        #       v
        # QbitDialer.submit_command()
        #       |
        #       v
        # EXISTING COMMAND REGISTRY / QUEUE
        #
        # No second queue.
        # No direct handler invocation.
        # No execute_command().
        # No alternate command path.
        # ======================================================

        self.logger.info(
            "[QbitDialer] ThoughtPacket -> command | "
            "task_id=%s | command=%s | "
            "qbit_id=%s | task_qbit_id=%s | track_id=%s | "
            "intent=%s | action=%s",
            task_id,
            command[
                "name"
            ],
            qbit_id,
            task_qbit_id,
            track_id,
            command.get(
                "intent"
            ),
            command.get(
                "action"
            ),
        )

        result = self.submit_command(
            command
        )

        if inspect.isawaitable(
            result
        ):

            result = await result

        # ======================================================
        # 27. FINAL COGNITIVE RESULT
        # ======================================================

        final_status = (
            result.get(
                "status",
                "unknown",
            )
            if isinstance(
                result,
                dict,
            )
            else "submitted"
        )

        return {

            "status": final_status,

            "stage": "COMMAND_ADMITTED",

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "qbit_id": qbit_id,

            "task_qbit_id": task_qbit_id,

            "track_id": track_id,

            "source": source,

            "channel": channel,

            "track_context": track_context,

            "thought": compute_result,

            "transform": transform_result,

            "command": command,

            "command_result": result,

            "health": health,

            "authority": "QbitDialer",

            "cognitive_authority": "QbitDialer",

            "command_authority": "QbitDialer",

        }

# =========================================================================
  
    async def _process_command_plane(self):
        # ----------------------------------------------------------
        # AUTHORITATIVE COMMAND-QUEUE CONSUMER
        #
        # QbitQueueLoop remains the authoritative transport.
        # QbitDialer owns command admission/execution after a
        # command has been placed on self.command_queue.
        #
        # Do not create another queue, loop, runtime, or executor.
        # ----------------------------------------------------------
        command_queue = getattr(
            self,
            "command_queue",
            None,
        )

        if command_queue is None:
            self.logger.debug(
                "[QbitDialer] Command plane waiting | "
                "authoritative command queue unavailable"
            )
            return 0

        processed = 0

        while True:
            command = None

            try:
                command = command_queue.get_nowait()
            except (
                asyncio.QueueEmpty,
                queue.Empty,
            ):
                break

            if command is None:
                task_done = getattr(
                    command_queue,
                    "task_done",
                    None,
                )
                if callable(task_done):
                    try:
                        task_done()
                    except ValueError:
                        self.logger.warning(
                            "[QbitDialer] Command queue task_done "
                            "bookkeeping rejected"
                        )
                continue

            try:
                result = await self.execute_command(
                    command
                )

                self.command_plane[
                    "last_command"
                ] = command

                processed += 1

                self.logger.debug(
                    "[QbitDialer] Qbit command executed | "
                    "result=%s",
                    result,
                )

            except asyncio.CancelledError:
                raise

            except Exception:
                self.logger.exception(
                    "[QbitDialer] Qbit command execution failed | "
                    "command=%r",
                    command,
                )

            finally:
                task_done = getattr(
                    command_queue,
                    "task_done",
                    None,
                )

                if callable(task_done):
                    try:
                        task_done()
                    except ValueError:
                        self.logger.warning(
                            "[QbitDialer] Command queue task_done "
                            "bookkeeping rejected"
                        )
                    except Exception:
                        self.logger.exception(
                            "[QbitDialer] Command queue task_done failed"
                        )

        if processed:
            self.logger.debug(
                "[QbitDialer] Command plane drained | "
                "processed=%s",
                processed,
            )

        return processed


  # -----------------------------
    # Callback registration
    # -----------------------------
# -----------------------------
# Callback registration
# -----------------------------
    def on_emit(self, callback):
 

    # ==========================================================
    # VALIDATE
    # ==========================================================
        if not callable(callback):
            raise TypeError(
                "QbitDialer.on_emit expects a callable"
            )

    # ==========================================================
    # AUTHORITATIVE REGISTRY
    # ==========================================================
        with self._lock:

            if callback in self._emit_callbacks:
                self.logger.debug(
                    "[QbitDialer] Emit callback already registered | "
                    "callback=%s",
                    getattr(
                        callback,
                        "__name__",
                        repr(callback),
                    ),
                )

                return False

            self._emit_callbacks.append(callback)

        # ------------------------------------------------------
        # Compatibility registry
        # ------------------------------------------------------
        # qbit_callbacks is retained for existing code, but the
        # callback is only registered once.
            if callback not in self.qbit_callbacks:
                self.qbit_callbacks.append(callback)

            count = len(self._emit_callbacks)

    # ==========================================================
    # LOG OUTSIDE LOCK
    # ==========================================================
        self.logger.info(
            "[QbitDialer] Emit callback registered | "
            "callback=%s | total=%d",
            getattr(
                callback,
                "__name__",
                repr(callback),
            ),
            count,
        )

        return True
    # ========================= EVENTBUS =========================

    async def _on_heartbeat(self, event=None):
        now = time.monotonic()

    # ==========================================================
    # CLOCK STATE
    # ==========================================================
        self.last_heartbeat = time.time()
        self._last_heartbeat_monotonic = now

    # Keep the internal clock synchronized without replacing the
    # wall-clock heartbeat timestamp.
        try:
            self._internal_clock = now
        except Exception:
            pass

    # ==========================================================
    # BOUNDED HEARTBEAT BUFFER
    # ==========================================================
        heartbeat_buffer = self.buffers.get("heartbeat")

        if heartbeat_buffer is not None:

            try:
                heartbeat_buffer.append(1)

            except Exception:
                self.logger.debug(
                    "[QbitDialer] Heartbeat buffer unavailable",
                    exc_info=True,
                )

    # ==========================================================
    # RUNTIME STATE
    # ==========================================================
        self._heartbeat_count = (
            getattr(
                self,
                "_heartbeat_count",
                0,
            ) + 1
        )

        self._heartbeat_received = True

    # ==========================================================
    # LIGHTWEIGHT DEBUG TELEMETRY
    # ==========================================================
        self.logger.debug(
            "[QbitDialer] Heartbeat received | "
            "count=%d | event=%s",
            self._heartbeat_count,
            type(event).__name__,
        )

        return True

    # ==========================================================
    # QBIT / SEED HEALTH COMMAND BRIDGE
    #
    # Authority:
    #   Heartbeat  = observes / reports
    #   Health     = records condition
    #   Qbit       = decides / proposes command
    #   QbitDialer = validates / executes command
    #   Queue      = downstream execution
    #   TrackSystem/EventBus = telemetry + trace
    # ==========================================================

    # ==========================================================
    # QBIT / SEED HEALTH COMMAND BRIDGE
    #
    # Authority:
    # Heartbeat  = observes / reports
    # Health     = records condition + decision signals
    # ComputeBrain = interprets / scores health suggestion
    # Qbit       = carries decision context
    # QbitDialer = validates / admits / executes command
    # Queue      = downstream execution
    # TrackSystem/EventBus = telemetry + trace
    #
    # DECISION SWITCHES:
    # level
    # persistence counters
    # YELLOW_LIMIT
    # RED_LIMIT
    # priority
    # throttle factor
    # health state
    #
    # SEMANTIC COMMAND:
    # who   = health subsystem / affected module
    # what  = proposed operation
    # where = affected module
    # why   = health condition
    # how   = decision mechanism
    # ==========================================================

    async def _on_health_flag(self, event):
        try:
            payload = getattr(event, "payload", {}) or {}

            if not isinstance(payload, dict):
                return

            module = payload.get("module")

            level = str(
                payload.get("level", "")
            ).upper().strip()

            if not module:
                return

            valid_levels = {
                "GREEN",
                "INFO",
                "YELLOW",
                "ORANGE",
                "RED",
                "CRITICAL",
                "DISABLED",
                "OFFLINE",
            }

            if level not in valid_levels:
                self.logger.warning(
                    "[Health] Unknown health level | "
                    "module=%s level=%s",
                    module,
                    level,
                )
                return

            # --------------------------------------------------
            # ENSURE HEALTH RECORD
            # --------------------------------------------------

            h = self.module_health.setdefault(
                module,
                {
                    "state": "UNKNOWN",
                    "timestamp": 0.0,
                    "last_flag": None,
                    "yellow": 0,
                    "orange": 0,
                    "red": 0,
                    "critical": 0,
                    "green": 0,
                    "commands": 0,
                    "last_command": None,
                    "last_command_result": None,
                },
            )

            now = getattr(
                self,
                "_internal_clock",
                time.monotonic(),
            )

            h["timestamp"] = now
            h["last_flag"] = level

            # --------------------------------------------------
            # DECISION SWITCHES
            #
            # These are the actual health signals SEED uses
            # to determine what action should be suggested.
            # --------------------------------------------------

            yellow_count = h.get("yellow", 0)
            orange_count = h.get("orange", 0)
            red_count = h.get("red", 0)
            critical_count = h.get("critical", 0)

            decision = {
                "level": level,
                "state": h.get("state", "UNKNOWN"),
                "yellow_count": yellow_count,
                "orange_count": orange_count,
                "red_count": red_count,
                "critical_count": critical_count,
                "yellow_limit": YELLOW_LIMIT,
                "red_limit": RED_LIMIT,
                "priority": 5,
                "factor": None,
                "threshold_triggered": False,
            }

            # --------------------------------------------------
            # DEFAULT SEMANTIC CONTEXT
            # --------------------------------------------------

            who = (
                payload.get("who")
                or "HealthMonitor"
            )

            what = (
                payload.get("what")
                or "HEALTH_EVALUATION"
            )

            where = (
                payload.get("where")
                or module
            )

            why = (
                payload.get("why")
                or f"health_level:{level}"
            )

            how = (
                payload.get("how")
                or "health_decision_switches"
            )

            command = None

            # --------------------------------------------------
            # GREEN / INFO
            # --------------------------------------------------

            if level in {"GREEN", "INFO"}:

                h["green"] = h.get("green", 0) + 1

                if h.get("state") in {
                    "UNKNOWN",
                    "DEGRADED",
                    "RECOVERING",
                }:
                    h["state"] = "RECOVERING"

                command = "HEALTH_RECOVER"

                decision.update(
                    {
                        "priority": 4,
                        "threshold_triggered": False,
                    }
                )

                what = command
                why = "health_recovery"
                how = "gradual_recovery"

            # --------------------------------------------------
            # YELLOW
            # --------------------------------------------------

            elif level == "YELLOW":

                h["yellow"] = yellow_count + 1
                h["state"] = "DEGRADED"

                yellow_count = h["yellow"]

                if yellow_count < YELLOW_LIMIT:

                    command = "HEALTH_WARN"

                    decision.update(
                        {
                            "priority": 4,
                            "threshold_triggered": False,
                        }
                    )

                    what = command
                    why = "health_warning"
                    how = "yellow_threshold_monitoring"

                else:

                    command = "DEFER"

                    decision.update(
                        {
                            "priority": 3,
                            "threshold_triggered": True,
                        }
                    )

                    what = command
                    why = "persistent_yellow"
                    how = "yellow_limit_exceeded"

            # --------------------------------------------------
            # ORANGE
            # --------------------------------------------------

            elif level == "ORANGE":

                h["orange"] = orange_count + 1
                h["state"] = "DEGRADED"

                command = "THROTTLE"

                decision.update(
                    {
                        "priority": 2,
                        "factor": 0.50,
                        "threshold_triggered": True,
                    }
                )

                what = command
                why = "orange_health"
                how = "health_throttle_factor_0.50"

            # --------------------------------------------------
            # RED
            # --------------------------------------------------

            elif level == "RED":

                h["red"] = red_count + 1

                if h["red"] >= RED_LIMIT:

                    h["state"] = "DISABLED"

                    command = "PAUSE_BACKGROUND"

                    decision.update(
                        {
                            "priority": 1,
                            "threshold_triggered": True,
                        }
                    )

                    what = command
                    why = "persistent_red"
                    how = "red_limit_exceeded"

                else:

                    h["state"] = "CRITICAL"

                    command = "THROTTLE"

                    decision.update(
                        {
                            "priority": 1,
                            "factor": 0.25,
                            "threshold_triggered": True,
                        }
                    )

                    what = command
                    why = "red_health"
                    how = "red_health_throttle_factor_0.25"

            # --------------------------------------------------
            # CRITICAL
            # --------------------------------------------------

            elif level == "CRITICAL":

                h["critical"] = (
                    critical_count + 1
                )

                h["state"] = "CRITICAL"

                command = "PRIORITIZE"

                decision.update(
                    {
                        "priority": 1,
                        "threshold_triggered": True,
                    }
                )

                what = command
                why = "critical_health"
                how = "critical_priority_escalation"

            # --------------------------------------------------
            # OFFLINE / DISABLED
            # --------------------------------------------------

            elif level in {
                "OFFLINE",
                "DISABLED",
            }:

                h["state"] = level

                command = "HEALTH_OFFLINE"

                decision.update(
                    {
                        "priority": 1,
                        "threshold_triggered": True,
                    }
                )

                what = command
                why = "module_unavailable"
                how = "availability_state"

            # --------------------------------------------------
            # NO DECISION
            # --------------------------------------------------

            if command is None:
                return None

            # --------------------------------------------------
            # ACTION SUGGESTION
            #
            # This is NOT execution.
            #
            # ComputeBrain / TransformerBrain can interpret this
            # context and QbitDialer remains the command authority.
            # --------------------------------------------------

            action_suggestion = {
                "type": "HealthActionSuggestion",
                "command": command,
                "who": who,
                "what": what,
                "where": where,
                "why": why,
                "how": how,
                "module": module,
                "level": level,
                "state": h.get("state"),
                "decision": decision,
                "health": dict(h),
                "execute": False,
                "submit": False,
                "authority": "QbitDialer",
                "next_stage": "ComputeBrain",
            }

            # --------------------------------------------------
            # COMPLETE QBIT SEMANTIC CONTEXT
            # --------------------------------------------------

            qbit_context = {
                "source": "HealthMonitor",
                "origin": "HEALTH",
                "module": module,
                "level": level,
                "command": command,
                "action": command,
                "who": who,
                "what": what,
                "where": where,
                "why": why,
                "how": how,
                "priority": decision["priority"],
                "decision": decision,
                "action_suggestion": action_suggestion,
            }

            # --------------------------------------------------
            # SEND THROUGH EXISTING HEALTH â†’ QBIT â†’ DIALER PATH
            #
            # This remains the admission boundary.
            # Health does not execute the command.
            # --------------------------------------------------

            result = await self._submit_health_qbit_command(
                command,
                {
                    "module": module,
                    "level": level,
                    "health": dict(h),
                    "decision": decision,
                    "action_suggestion": action_suggestion,
                    "qbit_context": qbit_context,
                    "who": who,
                    "what": what,
                    "where": where,
                    "why": why,
                    "how": how,
                },
                priority=decision["priority"],
            )

            # --------------------------------------------------
            # RECORD COMMAND TELEMETRY
            # --------------------------------------------------

            h["commands"] = (
                h.get("commands", 0) + 1
            )

            h["last_command"] = command
            h["last_command_result"] = result

            return result

        except asyncio.CancelledError:
            raise

        except Exception as exc:
            self.logger.exception(
                "[Health] Health flag processing failed | "
                "%s: %s",
                type(exc).__name__,
                exc,
            )


    # ==========================================================
    # HEALTH â†’ QBIT / COMPUTEBRAIN / QBITDIALER BRIDGE
    #
    # Health:
    # observes
    # records
    # proposes semantic action
    #
    # ComputeBrain:
    # interprets
    # scores
    # organizes ThoughtPacket
    #
    # QbitDialer:
    # validates
    # admits
    # executes
    #
    # QbitQueueLoop:
    # transports / schedules downstream execution
    #
    # PATH:
    #
    # Health
    # |
    # | health decision switches
    # v
    # HealthActionSuggestion
    # |
    # v
    # Qbit context
    # |
    # v
    # ComputeBrain
    # |
    # v
    # ThoughtPacket
    # |
    # v
    # TransformerBrain
    # |
    # v
    # QbitDialer
    # |
    # | submit_commands()
    # v
    # Command Admission
    # |
    # v
    # execute_command()
    # |
    # v
    # execute_all()
    # |
    # v
    # QbitQueueLoop / downstream
    #
    # IMPORTANT:
    # execute_command / execute_all are execution stages.
    # They must NOT be called directly by Health.
    # They belong downstream of command admission.
    # ==========================================================

    async def _submit_health_qbit_command(
        self,
        command,
        payload=None,
        priority=5,
    ):
        payload = (
            payload
            if isinstance(payload, dict)
            else {}
        )

        action_suggestion = payload.get(
            "action_suggestion",
            {},
        )

        qbit_context = payload.get(
            "qbit_context",
            {},
        )

        command_envelope = {
            "type": "HealthCommandSuggestion",
            "command": command,
            "action": command,
            "priority": priority,

            # ----------------------------------------------
            # WHO / WHAT / WHERE / WHY / HOW
            # ----------------------------------------------

            "who": payload.get(
                "who",
                qbit_context.get(
                    "who",
                    "HealthMonitor",
                ),
            ),

            "what": payload.get(
                "what",
                qbit_context.get(
                    "what",
                    command,
                ),
            ),

            "where": payload.get(
                "where",
                qbit_context.get(
                    "where",
                    payload.get(
                        "module"
                    ),
                ),
            ),

            "why": payload.get(
                "why",
                qbit_context.get(
                    "why",
                    "health_decision",
                ),
            ),

            "how": payload.get(
                "how",
                qbit_context.get(
                    "how",
                    "health_decision_switches",
                ),
            ),

            # ----------------------------------------------
            # COMPUTE BRAIN INPUT
            # ----------------------------------------------

            "compute_context": {
                "source": "HealthMonitor",
                "stage": "HEALTH_DECISION",
                "module": payload.get(
                    "module"
                ),
                "level": payload.get(
                    "level"
                ),
                "decision": payload.get(
                    "decision",
                    {},
                ),
                "action_suggestion": action_suggestion,
            },

            # ----------------------------------------------
            # QBIT CONTEXT
            # ----------------------------------------------

            "qbit_context": qbit_context,

            # ----------------------------------------------
            # COMMAND AUTHORITY
            # ----------------------------------------------

            "authority": "QbitDialer",
            "execute": False,
            "submit": False,
            "health": payload.get(
                "health",
                {},
            ),
        }

        # --------------------------------------------------
        # USE THE EXISTING COMMAND SUBMISSION PATH.
        #
        # Do not execute here.
        # Do not call execute_command().
        # Do not call execute_all().
        # Do not create another queue.
        # --------------------------------------------------

        submit_commands = getattr(
            self,
            "submit_commands",
            None,
        )

        if callable(submit_commands):

            result = submit_commands(
                command_envelope,
            )

            if inspect.isawaitable(result):
                result = await result

            return result

        # --------------------------------------------------
        # FALLBACK TO EXISTING HEALTH SUBMISSION CONTRACT
        # IF THIS OBJECT EXPOSES IT THROUGH THE DIALER.
        # --------------------------------------------------

        dialer = getattr(
            self,
            "qbit_dialer",
            None,
        )

        if dialer is None:
            dialer = getattr(
                self,
                "dialer",
                None,
            )

        if dialer is not None:

            submit = getattr(
                dialer,
                "submit_commands",
                None,
            )

            if callable(submit):

                result = submit(
                    command_envelope,
                )

                if inspect.isawaitable(result):
                    result = await result

                return result

        self.logger.warning(
            "[Health] No command admission endpoint | "
            "command=%s module=%s",
            command,
            payload.get("module"),
        )

        return {
            "status": "not_submitted",
            "command": command,
            "authority": "QbitDialer",
            "suggestion": command_envelope,
        }


    # ==========================================================
    # HEALTH â†’ QBITDIALER COMMAND BRIDGE
    #
    # Health systems may REQUEST a Qbit command.
    #
    # They do NOT:
    #   - create Qbits
    #   - control Qbit state directly
    #   - consume QbitQueueLoop
    #   - become command authority
    #
    # PATH:
    #
    #   Health / HealthMonitor
    #          |
    #          v
    #   _submit_health_qbit_command()
    #          |
    #          v
    #      QbitDialer
    #          |
    #          v
    #   command admission
    #          |
    #          v
    #   command execution
    # ==========================================================

    async def _submit_health_qbit_command(
        self,
        command,
        payload=None,
        priority=5,
    ):

        # ------------------------------------------------------
        # NORMALIZE PAYLOAD
        # ------------------------------------------------------

        if payload is None:
            payload = {}

        # ------------------------------------------------------
        # COMMAND NAME MUST BE COMMAND DATA
        #
        # A Qbit instance is DATA, not a command.
        #
        # This is an important upstream guard because the
        # observed failure was:
        #
        #     Unknown Qbit command | QBIT(...)
        #
        # ------------------------------------------------------

        if not isinstance(
            command,
            str,
        ):

            self.logger.warning(
                "[Healthâ†’Qbit] Rejected non-string command | "
                "type=%s",
                type(command).__name__,
            )

            return {
                "status": "rejected",
                "reason": "invalid_command_type",
                "command_type": type(command).__name__,
            }

        command = command.strip().upper()

        if not command:

            self.logger.warning(
                "[Healthâ†’Qbit] Rejected empty command"
            )

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        # ------------------------------------------------------
        # RESOLVE AUTHORITATIVE DIALER
        # ------------------------------------------------------

        dialer = getattr(
            self,
            "qbit_dialer",
            None,
        )

        if dialer is None:

            dialer = getattr(
                self,
                "qbitDialer",
                None,
            )

        if dialer is None:

            dialer = getattr(
                self,
                "dialer",
                None,
            )

        if dialer is None:

            self.logger.debug(
                "[Healthâ†’Qbit] Dialer unavailable | "
                "command=%s",
                command,
            )

            return {
                "status": "deferred",
                "command": command,
                "reason": "qbit_dialer_unavailable",
            }

        # ------------------------------------------------------
        # VERIFY DIALER IS THE CONNECTED COMMAND AUTHORITY
        # ------------------------------------------------------

        if not getattr(
            dialer,
            "_running",
            False,
        ):

            self.logger.debug(
                "[Healthâ†’Qbit] Dialer offline | "
                "command=%s",
                command,
            )

            return {
                "status": "deferred",
                "command": command,
                "reason": "qbit_dialer_offline",
            }

        # ------------------------------------------------------
        # BUILD AUTHORITATIVE COMMAND ENVELOPE
        # ------------------------------------------------------

        command_payload = {
            "name": command,
            "command": command,
            "payload": payload,
            "source": "SEED_HEALTH",
            "priority": priority,
            "confidence": 1.0,
        }

        # ------------------------------------------------------
        # PRESERVE EXISTING QBIT QUEUE CONNECTION
        #
        # We do not consume the queue here.
        #
        # If the Dialer is already connected to the authoritative
        # QbitQueueLoop, the Dialer remains responsible for routing
        # and execution.
        # ------------------------------------------------------

        queue_loop = getattr(
            dialer,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                dialer,
                "queue_loop",
                None,
            )

        if queue_loop is None:

            self.logger.warning(
                "[Healthâ†’Qbit] Dialer has no "
                "QbitQueueLoop connection | "
                "command=%s",
                command,
            )

        else:

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if (
                bound_dialer is not None
                and bound_dialer is not dialer
            ):

                self.logger.error(
                    "[Healthâ†’Qbit] QbitQueueLoop authority "
                    "mismatch | command=%s",
                    command,
                )

                return {
                    "status": "rejected",
                    "command": command,
                    "reason": "qbit_queue_loop_authority_mismatch",
                }

        try:

            # ==================================================
            # AUTHORITATIVE DIALER COMMAND API
            #
            # execute_command() is the canonical async API.
            # ==================================================

            executor = getattr(
                dialer,
                "execute_command",
                None,
            )

            if callable(executor):

                result = executor(
                    command_payload
                )

                if inspect.isawaitable(
                    result
                ):

                    result = await result

                return await self._record_health_command(
                    command,
                    payload,
                    result,
                )

            # ==================================================
            # COMPATIBILITY SUBMISSION API
            # ==================================================

            submit = getattr(
                dialer,
                "submit_command",
                None,
            )

            if callable(submit):

                result = submit(
                    command_payload
                )

                if inspect.isawaitable(
                    result
                ):

                    result = await result

                return await self._record_health_command(
                    command,
                    payload,
                    result,
                )

            # --------------------------------------------------
            # NO COMMAND API
            # --------------------------------------------------

            self.logger.warning(
                "[Healthâ†’Qbit] QbitDialer has no "
                "command submission API | command=%s",
                command,
            )

            return {
                "status": "rejected",
                "command": command,
                "reason": "dialer_command_api_missing",
            }

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            self.logger.exception(
                "[Healthâ†’Qbit] Command failed | "
                "command=%s | %s: %s",
                command,
                type(exc).__name__,
                exc,
            )

            return {
                "status": "failed",
                "command": command,
                "error": str(exc),
                "error_type": type(exc).__name__,
            }

    # ==========================================================
    # RECORD HEALTH COMMAND + ACTION CONTEXT
    # ==========================================================

    async def _record_health_command(
        self,
        command,
        payload,
        result,
    ):

        payload = (
            payload
            if isinstance(payload, dict)
            else {}
        )

        module = payload.get(
            "module",
            "SYSTEM",
        )

        h = self.module_health.setdefault(
            module,
            {},
        )

        # ------------------------------------------------------
        # PRESERVE ACTION / DECISION INFORMATION
        # ------------------------------------------------------

        decision = payload.get(
            "decision",
            {},
        )

        action_suggestion = payload.get(
            "action_suggestion",
            {},
        )

        qbit_context = payload.get(
            "qbit_context",
            {},
        )

        compute_context = payload.get(
            "compute_context",
            {},
        )

        # ------------------------------------------------------
        # SEMANTIC ACTION CONTEXT
        #
        # Preserve the information required by ComputeBrain,
        # TransformerBrain, ActionEngine, and QbitDialer.
        # ------------------------------------------------------

        action_context = {
            "who": payload.get(
                "who",
                qbit_context.get(
                    "who",
                    "HealthMonitor",
                ),
            ),

            "what": payload.get(
                "what",
                qbit_context.get(
                    "what",
                    command,
                ),
            ),

            "where": payload.get(
                "where",
                qbit_context.get(
                    "where",
                    module,
                ),
            ),

            "why": payload.get(
                "why",
                qbit_context.get(
                    "why",
                    "health_decision",
                ),
            ),

            "how": payload.get(
                "how",
                qbit_context.get(
                    "how",
                    "health_decision_switches",
                ),
            ),

            "command": command,

            "module": module,

            "level": payload.get(
                "level",
                decision.get(
                    "level",
                ),
            ),

            "state": payload.get(
                "state",
                decision.get(
                    "state",
                ),
            ),

            "priority": payload.get(
                "priority",
                decision.get(
                    "priority",
                ),
            ),

            "factor": payload.get(
                "factor",
                decision.get(
                    "factor",
                ),
            ),

            "threshold_triggered": decision.get(
                "threshold_triggered",
                False,
            ),
        }

        # ------------------------------------------------------
        # PRESERVE THE COMPLETE HEALTH DECISION
        # ------------------------------------------------------

        health_decision = {
            "level": decision.get(
                "level",
                payload.get(
                    "level",
                ),
            ),

            "state": decision.get(
                "state",
                payload.get(
                    "state",
                    h.get(
                        "state",
                        "UNKNOWN",
                    ),
                ),
            ),

            "yellow_count": decision.get(
                "yellow_count",
                h.get(
                    "yellow",
                    0,
                ),
            ),

            "orange_count": decision.get(
                "orange_count",
                h.get(
                    "orange",
                    0,
                ),
            ),

            "red_count": decision.get(
                "red_count",
                h.get(
                    "red",
                    0,
                ),
            ),

            "critical_count": decision.get(
                "critical_count",
                h.get(
                    "critical",
                    0,
                ),
            ),

            "yellow_limit": decision.get(
                "yellow_limit",
                YELLOW_LIMIT,
            ),

            "red_limit": decision.get(
                "red_limit",
                RED_LIMIT,
            ),

            "priority": decision.get(
                "priority",
                payload.get(
                    "priority",
                    5,
                ),
            ),

            "factor": decision.get(
                "factor",
                payload.get(
                    "factor",
                ),
            ),

            "threshold_triggered": decision.get(
                "threshold_triggered",
                False,
            ),
        }

        # ------------------------------------------------------
        # ACTION RECORD
        #
        # This is the persistent action-useful representation.
        #
        # It is NOT execution.
        # ------------------------------------------------------

        action_record = {
            "type": "HealthActionRecord",

            "command": command,

            "module": module,

            "semantic": action_context,

            "who": action_context["who"],
            "what": action_context["what"],
            "where": action_context["where"],
            "why": action_context["why"],
            "how": action_context["how"],

            "level": action_context["level"],
            "state": action_context["state"],

            "priority": action_context["priority"],
            "factor": action_context["factor"],

            "decision": health_decision,

            "action_suggestion": action_suggestion,

            "qbit_context": qbit_context,

            "compute_context": compute_context,

            "health": dict(h),

            "result": result,

            "authority": "QbitDialer",

            "execute": False,
            "submit": False,

            "next_stage": "ComputeBrain",
        }

        # ------------------------------------------------------
        # STORE ACTION CONTEXT WITH HEALTH RECORD
        # ------------------------------------------------------

        h["commands"] = h.get(
            "commands",
            0,
        ) + 1

        h["last_command"] = command

        h["last_command_result"] = result

        h["last_action_context"] = action_context

        h["last_action_record"] = action_record

        h["last_decision"] = health_decision

        h["last_qbit_context"] = qbit_context

        h["last_compute_context"] = compute_context

        # ------------------------------------------------------
        # ACTION HISTORY
        #
        # Preserve recent health-driven suggestions so
        # ComputeBrain / Dialer can reason over persistence.
        # ------------------------------------------------------

        action_history = h.setdefault(
            "action_history",
            [],
        )

        action_history.append(
            action_record
        )

        if len(action_history) > 256:
            del action_history[:-256]

        # ------------------------------------------------------
        # EVENTBUS TELEMETRY + ACTION CONTEXT
        # ------------------------------------------------------

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        emit = getattr(
            event_bus,
            "emit",
            None,
        )

        if callable(emit):

            try:

                emitted = emit(
                    "QBIT_HEALTH_COMMAND",
                    {
                        "command": command,
                        "module": module,

                        # Action semantics
                        "who": action_context["who"],
                        "what": action_context["what"],
                        "where": action_context["where"],
                        "why": action_context["why"],
                        "how": action_context["how"],

                        # Decision switches
                        "level": action_context["level"],
                        "state": action_context["state"],
                        "priority": action_context["priority"],
                        "factor": action_context["factor"],
                        "decision": health_decision,

                        # Pipeline context
                        "action_suggestion": action_suggestion,
                        "qbit_context": qbit_context,
                        "compute_context": compute_context,

                        # Full source/result
                        "payload": payload,
                        "result": result,

                        "action_record": action_record,

                        "authority": "QbitDialer",

                        "timestamp": time.time(),
                    },
                )

                if inspect.isawaitable(emitted):
                    await emitted

            except Exception:
                self.logger.debug(
                    "[Healthâ†’Qbit] EventBus telemetry failed",
                    exc_info=True,
                )

        # ------------------------------------------------------
        # TRACKSYSTEM TELEMETRY + ACTION CONTEXT
        # ------------------------------------------------------

        track = getattr(
            self,
            "track_system",
            None,
        )

        if track is not None:

            try:

                tracker = getattr(
                    track,
                    "record",
                    None,
                )

                if callable(tracker):

                    tracker(
                        "QBIT_HEALTH_COMMAND",
                        {
                            "command": command,
                            "module": module,

                            "who": action_context["who"],
                            "what": action_context["what"],
                            "where": action_context["where"],
                            "why": action_context["why"],
                            "how": action_context["how"],

                            "level": action_context["level"],
                            "state": action_context["state"],
                            "priority": action_context["priority"],
                            "factor": action_context["factor"],

                            "decision": health_decision,

                            "action_suggestion": action_suggestion,

                            "qbit_context": qbit_context,

                            "compute_context": compute_context,

                            "result": result,
                        },
                    )

            except Exception:
                self.logger.debug(
                    "[Healthâ†’Qbit] TrackSystem telemetry failed",
                    exc_info=True,
                )

        return result
    # ==========================================================
    # SYSTEM REPORT â†’ QBIT HEALTH INPUT
    # ==========================================================

    async def _on_system_report(self, event):

        try:

            payload = getattr(
                event,
                "payload",
                {},
            ) or {}

            if not isinstance(payload, dict):
                return

            # --------------------------------------------------
            # SYSTEM START / RUNTIME STATE
            # --------------------------------------------------

            self.system_status = getattr(
                self,
                "system_status",
                {},
            )

            self.system_status["last_report_time"] = time.monotonic()

            self.system_status["system_starting"] = True

            self.system_status.setdefault(
                "runtime_state",
                "STARTING",
            )

            self.system_status.setdefault(
                "limp_mode",
                False,
            )

            self.system_status.setdefault(
                "recovery",
                False,
            )

            self.system_status.setdefault(
                "idle",
                False,
            )

            self.system_status.setdefault(
                "planning",
                False,
            )

            self.system_status.setdefault(
                "subsystems_ready",
                False,
            )

            self.system_status.setdefault(
                "dialer_processing",
                False,
            )

            # --------------------------------------------------
            # TELEMETRY
            # --------------------------------------------------

            numeric_values = []

            for key, value in payload.items():

                if not isinstance(
                    value,
                    (int, float),
                ):
                    continue

                numeric = float(value)

                numeric_values.append(
                    numeric
                )

                # ------------------------------------------
                # Bounded telemetry
                # ------------------------------------------

                buffer = self.buffers.get(key)

                if buffer is not None:

                    try:
                        buffer.append(numeric)
                    except Exception:
                        self.logger.debug(
                            "[Health] Buffer update failed | key=%s",
                            key,
                            exc_info=True,
                        )

                # ------------------------------------------
                # Confidence
                # ------------------------------------------

                self.confidence[key] = numeric

                # ------------------------------------------
                # Latest values
                # ------------------------------------------

                self.system_status[key] = numeric

            # --------------------------------------------------
            # GREEN FLAG CALCULATION
            #
            # A numeric system report may contain explicit
            # green flags as well as subsystem health values.
            # --------------------------------------------------

            green_flags = payload.get(
                "green_flags",
                payload.get(
                    "green",
                    payload.get(
                        "healthy",
                        0,
                    ),
                ),
            )

            total_flags = payload.get(
                "total_flags",
                payload.get(
                    "total_subsystems",
                    0,
                ),
            )

            try:
                green_flags = float(
                    green_flags
                )
            except (
                TypeError,
                ValueError,
            ):
                green_flags = 0.0

            try:
                total_flags = float(
                    total_flags
                )
            except (
                TypeError,
                ValueError,
            ):
                total_flags = 0.0

            if (
                total_flags > 0.0
                and green_flags <= 1.0
            ):
                green_percent = (
                    green_flags
                    / total_flags
                ) * 100.0

            elif (
                green_flags >= 0.0
                and green_flags <= 100.0
            ):
                green_percent = green_flags

            else:
                green_percent = 0.0

            self.system_status[
                "green_percent"
            ] = green_percent

            # --------------------------------------------------
            # SUBSYSTEM READINESS
            #
            # Do not start Dialer processing merely because
            # the system report arrived.
            # --------------------------------------------------

            subsystems = payload.get(
                "subsystems",
                payload.get(
                    "modules",
                    {},
                ),
            )

            subsystem_states = {}

            if isinstance(
                subsystems,
                dict,
            ):

                for name, state in subsystems.items():

                    if isinstance(
                        state,
                        dict,
                    ):
                        subsystem_state = str(
                            state.get(
                                "state",
                                state.get(
                                    "status",
                                    "",
                                ),
                            )
                        ).upper()

                        ready = bool(
                            state.get(
                                "ready",
                                subsystem_state
                                in {
                                    "ONLINE",
                                    "READY",
                                    "RUNNING",
                                    "HEALTHY",
                                },
                            )
                        )

                    else:

                        subsystem_state = str(
                            state
                        ).upper()

                        ready = (
                            subsystem_state
                            in {
                                "ONLINE",
                                "READY",
                                "RUNNING",
                                "HEALTHY",
                                "GREEN",
                            }
                        )

                    subsystem_states[name] = {
                        "state": subsystem_state,
                        "ready": ready,
                    }

            self.system_status[
                "subsystem_states"
            ] = subsystem_states

            if subsystem_states:

                subsystems_ready = all(
                    state.get(
                        "ready",
                        False,
                    )
                    for state in subsystem_states.values()
                )

            else:

                # No explicit subsystem map means we
                # cannot claim subsystem readiness.
                subsystems_ready = False

            self.system_status[
                "subsystems_ready"
            ] = subsystems_ready

            # --------------------------------------------------
            # LIMPMODE / RECOVERY
            # --------------------------------------------------

            limp_controller = getattr(
                self,
                "limp_mode_controller",
                None,
            )

            if limp_controller is None:
                limp_controller = getattr(
                    self,
                    "limp_mode",
                    None,
                )

            limp_active = bool(
                getattr(
                    limp_controller,
                    "active",
                    False,
                )
            ) if limp_controller is not None else bool(
                self.system_status.get(
                    "limp_mode",
                    False,
                )
            )

            self.system_status[
                "limp_mode"
            ] = limp_active

            recovery = bool(
                self.system_status.get(
                    "recovery",
                    False,
                )
            )

            if limp_active:

                self.system_status[
                    "runtime_state"
                ] = "LIMP_MODE"

                self.system_status[
                    "idle"
                ] = True

            elif recovery:

                self.system_status[
                    "runtime_state"
                ] = "RECOVERY"

                self.system_status[
                    "idle"
                ] = True

            # --------------------------------------------------
            # THREE-MINUTE SUBSYSTEM WAIT
            # --------------------------------------------------

            startup_started = self.system_status.get(
                "startup_started_at",
            )

            if startup_started is None:

                startup_started = time.monotonic()

                self.system_status[
                    "startup_started_at"
                ] = startup_started

            elapsed = (
                time.monotonic()
                - startup_started
            )

            self.system_status[
                "startup_elapsed"
            ] = elapsed

            startup_wait_complete = (
                elapsed >= 180.0
            )

            self.system_status[
                "startup_wait_complete"
            ] = startup_wait_complete

            # --------------------------------------------------
            # IDLE WHILE WAITING FOR SUBSYSTEMS
            # --------------------------------------------------

            if (
                not startup_wait_complete
                or not subsystems_ready
            ):

                self.system_status[
                    "idle"
                ] = True

                if not limp_active:

                    self.system_status[
                        "runtime_state"
                    ] = "WAITING_FOR_SUBSYSTEMS"

            # --------------------------------------------------
            # SYSTEM PLANNING
            #
            # Planning may begin once the startup wait has
            # completed, but execution remains gated.
            # --------------------------------------------------

            planning = (
                startup_wait_complete
                and not limp_active
            )

            self.system_status[
                "planning"
            ] = planning

            # --------------------------------------------------
            # SYSTEM CHECK ACTION SUGGESTION
            #
            # Suggestion only.
            # No execution occurs here.
            # --------------------------------------------------

            action_suggestions = []

            if not startup_wait_complete:

                action_suggestions.append(
                    {
                        "type": "SystemCheckSuggestion",
                        "command": "WAIT_FOR_SUBSYSTEMS",
                        "who": "HealthMonitor",
                        "what": "WAIT",
                        "where": "SEED_AI_SYSTEM",
                        "why": "startup_subsystem_settle_window",
                        "how": "three_minute_startup_gate",
                        "priority": 5,
                        "execute": False,
                        "submit": False,
                    }
                )

            elif not subsystems_ready:

                action_suggestions.append(
                    {
                        "type": "SystemCheckSuggestion",
                        "command": "CHECK_SUBSYSTEMS",
                        "who": "HealthMonitor",
                        "what": "SYSTEM_CHECK",
                        "where": "SEED_AI_SYSTEM",
                        "why": "subsystems_not_ready",
                        "how": "subsystem_readiness_scan",
                        "priority": 3,
                        "execute": False,
                        "submit": False,
                        "subsystems": subsystem_states,
                    }
                )

            elif green_percent < 75.0:

                action_suggestions.append(
                    {
                        "type": "SystemCheckSuggestion",
                        "command": "CHECK_SYSTEM_HEALTH",
                        "who": "HealthMonitor",
                        "what": "SYSTEM_CHECK",
                        "where": "SEED_AI_SYSTEM",
                        "why": "green_flags_below_75_percent",
                        "how": "green_flag_threshold_check",
                        "priority": 2,
                        "green_percent": green_percent,
                        "required_green_percent": 75.0,
                        "execute": False,
                        "submit": False,
                    }
                )

            else:

                action_suggestions.append(
                    {
                        "type": "SystemCheckSuggestion",
                        "command": "START_DIALER_PROCESSING",
                        "who": "HealthMonitor",
                        "what": "START_DIALER_PROCESSING",
                        "where": "QbitDialer",
                        "why": "startup_gate_complete_and_75_percent_green",
                        "how": "three_minute_wait_plus_75_percent_green_gate",
                        "priority": 1,
                        "green_percent": green_percent,
                        "required_green_percent": 75.0,
                        "execute": False,
                        "submit": False,
                        "authority": "QbitDialer",
                    }
                )

            # --------------------------------------------------
            # COMPLETE SYSTEM ACTION CONTEXT
            # --------------------------------------------------

            system_action_context = {
                "type": "SystemHealthActionContext",

                "runtime_state": self.system_status.get(
                    "runtime_state",
                ),

                "limp_mode": limp_active,

                "recovery": recovery,

                "idle": self.system_status.get(
                    "idle",
                    False,
                ),

                "planning": planning,

                "startup_elapsed": elapsed,

                "startup_wait_seconds": 180.0,

                "startup_wait_complete": startup_wait_complete,

                "subsystems_ready": subsystems_ready,

                "subsystems": subsystem_states,

                "green_percent": green_percent,

                "required_green_percent": 75.0,

                "action_suggestions": action_suggestions,

                "who": "HealthMonitor",

                "what": (
                    "SYSTEM_CHECK"
                    if green_percent < 75.0
                    else "START_DIALER_PROCESSING"
                ),

                "where": "SEED_AI_SYSTEM",

                "why": (
                    "startup_or_subsystem_readiness"
                    if not startup_wait_complete
                    or not subsystems_ready
                    else "system_ready_for_dialer_processing"
                ),

                "how": (
                    "startup_gate"
                    if not startup_wait_complete
                    else "subsystem_and_green_flag_gate"
                ),

                "authority": "QbitDialer",

                "execute": False,

                "submit": False,
            }

            self.system_status[
                "action_context"
            ] = system_action_context

            self.system_status[
                "action_suggestions"
            ] = action_suggestions

            # --------------------------------------------------
            # FEED SYSTEM TELEMETRY INTO QBIT
            # --------------------------------------------------

            qbit = getattr(
                self,
                "qbit",
                None,
            )

            if qbit is None:

                qbit = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

            if qbit is not None:

                process = getattr(
                    qbit,
                    "process_system_report",
                    None,
                )

                if callable(process):

                    qbit_payload = dict(
                        payload
                    )

                    qbit_payload[
                        "system_action_context"
                    ] = system_action_context

                    qbit_payload[
                        "action_suggestions"
                    ] = action_suggestions

                    qbit_payload[
                        "startup_gate"
                    ] = {
                        "elapsed": elapsed,
                        "wait_seconds": 180.0,
                        "wait_complete": startup_wait_complete,
                    }

                    qbit_payload[
                        "subsystem_readiness"
                    ] = {
                        "ready": subsystems_ready,
                        "states": subsystem_states,
                    }

                    qbit_payload[
                        "green_gate"
                    ] = {
                        "current": green_percent,
                        "required": 75.0,
                        "passed": green_percent >= 75.0,
                    }

                    result = process(
                        qbit_payload
                    )

                    if inspect.isawaitable(result):
                        await result

            # --------------------------------------------------
            # OPTIONAL QBITDIALER TELEMETRY / PLANNING HOOK
            #
            # Do not execute commands directly.
            # --------------------------------------------------

            dialer = getattr(
                self,
                "qbit_dialer",
                None,
            )

            if dialer is not None:

                handler = getattr(
                    dialer,
                    "on_system_report",
                    None,
                )

                if callable(handler):

                    dialer_payload = dict(
                        payload
                    )

                    dialer_payload[
                        "system_action_context"
                    ] = system_action_context

                    dialer_payload[
                        "action_suggestions"
                    ] = action_suggestions

                    dialer_payload[
                        "startup_gate"
                    ] = {
                        "elapsed": elapsed,
                        "wait_seconds": 180.0,
                        "wait_complete": startup_wait_complete,
                    }

                    dialer_payload[
                        "subsystem_readiness"
                    ] = {
                        "ready": subsystems_ready,
                        "states": subsystem_states,
                    }

                    dialer_payload[
                        "green_gate"
                    ] = {
                        "current": green_percent,
                        "required": 75.0,
                        "passed": green_percent >= 75.0,
                    }

                    result = handler(
                        dialer_payload
                    )

                    if inspect.isawaitable(result):
                        await result

            # --------------------------------------------------
            # START DIALER PROCESSING GATE
            #
            # Only signal readiness after:
            #
            # 1. 180-second startup wait
            # 2. subsystems ready
            # 3. 75% green flags
            # 4. not in limp mode
            #
            # This does NOT directly execute a command.
            # --------------------------------------------------

            dialer_gate_passed = (
                startup_wait_complete
                and subsystems_ready
                and green_percent >= 75.0
                and not limp_active
            )

            self.system_status[
                "dialer_gate_passed"
            ] = dialer_gate_passed

            if dialer_gate_passed:

                self.system_status[
                    "idle"
                ] = False

                self.system_status[
                    "runtime_state"
                ] = "READY"

                self.system_status[
                    "dialer_processing"
                ] = True

                action_suggestion = {
                    "type": "SystemActionSuggestion",
                    "command": "START_DIALER_PROCESSING",
                    "who": "HealthMonitor",
                    "what": "START_DIALER_PROCESSING",
                    "where": "QbitDialer",
                    "why": (
                        "75_percent_green_flags_after_"
                        "three_minute_subsystem_wait"
                    ),
                    "how": (
                        "startup_wait_subsystem_check_"
                        "green_threshold_gate"
                    ),
                    "priority": 1,
                    "green_percent": green_percent,
                    "required_green_percent": 75.0,
                    "startup_elapsed": elapsed,
                    "subsystems_ready": True,
                    "authority": "QbitDialer",
                    "execute": False,
                    "submit": False,
                }

                self.system_status[
                    "dialer_action_suggestion"
                ] = action_suggestion

            else:

                self.system_status[
                    "dialer_processing"
                ] = False

            # --------------------------------------------------
            # SYSTEM REPORT COMPLETE
            # --------------------------------------------------

            self.system_status[
                "system_starting"
            ] = not dialer_gate_passed

            self.system_status[
                "system_ready"
            ] = dialer_gate_passed

        except asyncio.CancelledError:
            raise

        except Exception as exc:
            self.logger.exception(
                "[Health] System report processing failed | "
                "%s: %s",
                type(exc).__name__,
                exc,
            )

    async def _attach_callbacks(self):

        # ==================================================
        # CALLBACK STATE
        # ==================================================

        callbacks = getattr(
            self,
            "qbit_callbacks",
            None,
        )

        if callbacks is None:
            callbacks = []
            self.qbit_callbacks = callbacks

        # Normalize accidental non-list callback containers.
        if not isinstance(
            callbacks,
            (list, tuple, set),
        ):
            callbacks = [callbacks]
            self.qbit_callbacks = callbacks

        # ==================================================
        # NO CALLBACKS IS A VALID STATE
        #
        # Do NOT generate a warning every Qbit loop tick.
        # ==================================================

        if not callbacks:

            self._callbacks_available = False

            # Only report this transition once.
            if not getattr(
                self,
                "_callbacks_empty_reported",
                False,
            ):
                self.logger.debug(
                    "[QbitDialer] No QBIT_STATE callbacks "
                    "registered; continuing without callbacks."
                )

                self._callbacks_empty_reported = True

            return False

        # ==================================================
        # CALLBACKS NOW EXIST
        # ==================================================

        self._callbacks_empty_reported = False

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:

            self._callbacks_available = False

            self.logger.warning(
                "[QbitDialer] Cannot attach callbacks: "
                "EventBus is not bound."
            )

            return False

        # ==================================================
        # FIND REGISTRATION API
        #
        # Prefer register_callback(), then subscribe().
        # ==================================================

        register = getattr(
            event_bus,
            "register_callback",
            None,
        )

        if not callable(register):

            register = getattr(
                event_bus,
                "subscribe",
                None,
            )

        if not callable(register):

            self._callbacks_available = False

            self.logger.warning(
                "[QbitDialer] EventBus has no callback "
                "registration method."
            )

            return False

        # ==================================================
        # ATTACHMENT TRACKING
        #
        # Prevent duplicate registration when _loop()
        # invokes this method repeatedly.
        # ==================================================

        attached = getattr(
            self,
            "_attached_qbit_callbacks",
            None,
        )

        if attached is None:

            attached = set()

            self._attached_qbit_callbacks = attached

        attached_any = False
        failed_any = False

        # ==================================================
        # REGISTER CALLBACKS
        # ==================================================

        for cb in list(callbacks):

            # --------------------------------------------------
            # Validate callback.
            # --------------------------------------------------

            if not callable(cb):

                self.logger.warning(
                    "[QbitDialer] Skipped non-callable "
                    "callback: %r",
                    cb,
                )

                failed_any = True
                continue

            # --------------------------------------------------
            # Stable identity for bound methods/functions.
            #
            # Bound method objects are recreated on access, so
            # using id(cb) alone would allow duplicates.
            # --------------------------------------------------

            try:

                callback_key = (
                    id(
                        getattr(
                            cb,
                            "__self__",
                            None,
                        )
                    ),
                    id(
                        getattr(
                            cb,
                            "__func__",
                            cb,
                        )
                    ),
                )

            except Exception:

                callback_key = id(cb)

            # --------------------------------------------------
            # Already attached.
            # --------------------------------------------------

            if callback_key in attached:

                attached_any = True
                continue

            # --------------------------------------------------
            # Register callback.
            # --------------------------------------------------

            try:

                result = register(
                    "QBIT_STATE",
                    cb,
                )

                # --------------------------------------------------
                # EventBus implementations may return:
                #
                #   None
                #   bool
                #   object
                #   coroutine
                #
                # Await only when necessary.
                # --------------------------------------------------

                if inspect.isawaitable(result):

                    await result

                # --------------------------------------------------
                # Mark attached only after successful registration.
                # --------------------------------------------------

                attached.add(
                    callback_key
                )

                attached_any = True

                callback_name = getattr(
                    cb,
                    "__name__",
                    cb.__class__.__name__,
                )

                self.logger.info(
                    "[QbitDialer] Callback %s "
                    "attached to QBIT_STATE",
                    callback_name,
                )

            except Exception as exc:

                failed_any = True

                self.logger.error(
                    "[QbitDialer] Failed to attach "
                    "callback %r: %s",
                    cb,
                    exc,
                )

        # ==================================================
        # FINAL CALLBACK STATE
        # ==================================================

        self._callbacks_available = bool(
            attached_any
        )

        # Preserve diagnostic information without allowing
        # one failed callback to break the Qbit loop.

        self._callbacks_attach_failed = failed_any

        # ==================================================
        # RETURN SEMANTICS
        #
        # True  = at least one callback is attached.
        # False = none attached.
        #
        # Failure of one callback does not prevent the
        # remaining callbacks from attaching.
        # ==================================================

        return self._callbacks_available

    # ========================= LOOP =========================
    def _run_qbit_loop_thread(self):

        # ======================================================
        # AUTHORITATIVE ARCHITECTURE
        #
        # QbitQueueLoop = ONE authoritative Qbit runtime loop
        # QbitDialer    = command authority / execution
        #
        # THIS METHOD MUST NEVER:
        #
        #     - create an asyncio loop
        #     - run_until_complete()
        #     - run_coroutine_threadsafe()
        #     - start _qbit_loop()
        #     - start _loop()
        #     - create another Qbit runner
        #
        # If QbitQueueLoop is connected, the Dialer stays attached
        # to that runtime and does not create another runner.
        # ======================================================

        try:

            # --------------------------------------------------
            # SHUTDOWN GUARD
            # --------------------------------------------------

            shutdown_flag = getattr(
                self,
                "shutdown_flag",
                None,
            )

            if (
                shutdown_flag is not None
                and shutdown_flag.is_set()
            ):

                self.logger.debug(
                    "[QbitDialer] Qbit loop runner ignored | "
                    "shutdown requested"
                )

                return

            # --------------------------------------------------
            # AUTHORITATIVE QBIT
            # --------------------------------------------------

            qbit = getattr(
                self,
                "qbit",
                None,
            )

            if qbit is None:

                self.logger.warning(
                    "[QbitDialer] Qbit loop runner ignored | "
                    "authoritative Qbit not bound"
                )

                return

            # --------------------------------------------------
            # AUTHORITATIVE QBIT QUEUE LOOP
            # --------------------------------------------------

            queue_loop = getattr(
                self,
                "qbit_queue_loop",
                None,
            )

            if queue_loop is None:

                queue_loop = getattr(
                    self,
                    "_qbit_queue_loop",
                    None,
                )

            if queue_loop is None:

                queue_loop = getattr(
                    self,
                    "queue_loop",
                    None,
                )

            # --------------------------------------------------
            # NO QUEUE LOOP = DO NOT CREATE ONE
            # --------------------------------------------------

            if queue_loop is None:

                self.logger.warning(
                    "[QbitDialer] Qbit loop runner refused | "
                    "QbitQueueLoop not connected"
                )

                return

            # --------------------------------------------------
            # VERIFY DIALER AUTHORITY
            # --------------------------------------------------

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if bound_dialer is not self:

                self.logger.error(
                    "[QbitDialer] Qbit loop runner refused | "
                    "QbitQueueLoop is not bound to this Dialer"
                )

                return

            # --------------------------------------------------
            # VERIFY AUTHORITATIVE QBIT IDENTITY
            # --------------------------------------------------

            queue_qbit = getattr(
                queue_loop,
                "qbit",
                None,
            )

            if (
                queue_qbit is not None
                and queue_qbit is not qbit
            ):

                self.logger.error(
                    "[QbitDialer] Qbit loop runner refused | "
                    "Qbit identity mismatch with QbitQueueLoop"
                )

                return

            # --------------------------------------------------
            # CHECK QUEUE LOOP RUNTIME
            # --------------------------------------------------

            queue_running = getattr(
                queue_loop,
                "_running",
                None,
            )

            if queue_running is None:

                queue_running = getattr(
                    queue_loop,
                    "running",
                    False,
                )

            # --------------------------------------------------
            # AUTHORITATIVE ONLINE STATE
            #
            # Once QbitQueueLoop owns the runtime, the Dialer
            # does NOT launch anything.
            # --------------------------------------------------

            if queue_running:

                self._qbit_running = True
                self._running = True
                self.running = True

                self._qbit_runtime_state = "RUNNING"
                self._runtime_state = "RUNNING"

                self.logger.info(
                    "[QbitDialer] Qbit runtime already ONLINE | "
                    "runner=QbitQueueLoop | "
                    "dialer=command-authority"
                )

                return

            # --------------------------------------------------
            # QUEUE LOOP EXISTS BUT IS OFFLINE
            #
            # DO NOT RESURRECT IT FROM HERE.
            #
            # Boot/main owns QbitQueueLoop lifecycle.
            # --------------------------------------------------

            self._qbit_running = False
            self._running = False
            self.running = False

            self._qbit_runtime_state = "WAITING"
            self._runtime_state = "WAITING"

            self.logger.warning(
                "[QbitDialer] QbitQueueLoop connected but offline | "
                "Dialer will NOT start another Qbit loop"
            )

            return

        except Exception:

            self.logger.exception(
                "[QbitDialer] Qbit loop runner validation failed"
            )

        finally:

            self.logger.debug(
                "[QbitDialer] Qbit loop runner exited | "
                "no independent asyncio runner created"
            )

    async def _plan(self):

        try:
            # ==================================================
            # LIFECYCLE GUARD
            # ==================================================

            shutdown_flag = getattr(
                self,
                "shutdown_flag",
                None,
            )

            if shutdown_flag is not None:
                try:
                    if shutdown_flag.is_set():
                        return None
                except Exception:
                    pass

            if not getattr(
                self,
                "_running",
                False,
            ):
                return None

            # ==================================================
            # CURRENT CONFIDENCE
            # ==================================================

            confidence = getattr(
                self,
                "confidence",
                {},
            )

            if not isinstance(
                confidence,
                dict,
            ):
                confidence = {}
                self.confidence = confidence

            values = []

            for value in confidence.values():
                try:
                    if inspect.isawaitable(value):
                        value = await value

                    value = float(value)

                    if math.isfinite(value):
                        values.append(value)

                except Exception:
                    continue

            if values:
                avg_conf = sum(values) / len(values)
            else:
                avg_conf = 0.0

            # ==================================================
            # REASONING WEIGHT
            #
            # This is the important fix.
            #
            # reasoning_weight may be returned by an async
            # function. Resolve it BEFORE numeric operations.
            # ==================================================

            reasoning_weight = 0.0

            try:
                motivation_summary = getattr(
                    self,
                    "get_brain_motivation_summary",
                    None,
                )

                if callable(motivation_summary):

                    reasoning_weight = motivation_summary()

                    if inspect.isawaitable(
                        reasoning_weight
                    ):
                        reasoning_weight = (
                            await reasoning_weight
                        )

                    # ------------------------------------------
                    # Accept either:
                    #
                    #   numeric value
                    #
                    # or:
                    #
                    #   {"reasoning_weight": ...}
                    #   {"weight": ...}
                    #   {"motivation": ...}
                    # ------------------------------------------

                    if isinstance(
                        reasoning_weight,
                        dict,
                    ):

                        reasoning_weight = (
                            reasoning_weight.get(
                                "reasoning_weight",
                                reasoning_weight.get(
                                    "weight",
                                    reasoning_weight.get(
                                        "motivation",
                                        0.0,
                                    ),
                                ),
                            )
                        )

                        if inspect.isawaitable(
                            reasoning_weight
                        ):
                            reasoning_weight = (
                                await reasoning_weight
                            )

                    reasoning_weight = float(
                        reasoning_weight
                    )

            except Exception as exc:

                self.logger.debug(
                    "[QbitDialer] Reasoning weight "
                    "unavailable: %s",
                    exc,
                )

                reasoning_weight = 0.0

            # ==================================================
            # SANITIZE REASONING WEIGHT
            # ==================================================

            if not math.isfinite(
                reasoning_weight
            ):
                reasoning_weight = 0.0

            # Keep the weight bounded.
            reasoning_weight = max(
                0.0,
                min(
                    1.0,
                    reasoning_weight,
                ),
            )

            # ==================================================
            # COMBINED PLANNING CONFIDENCE
            # ==================================================

            avg_conf = (
                avg_conf + reasoning_weight
            ) / 2.0

            avg_conf = max(
                0.0,
                min(
                    1.0,
                    avg_conf,
                ),
            )

            # ==================================================
            # PLANNING STATE
            # ==================================================

            self.planning = True

            self._last_plan_confidence = (
                avg_conf
            )

            # ==================================================
            # DETERMINE PLAN STATE
            # ==================================================

            if avg_conf >= 0.80:
                plan_state = "HIGH_CONFIDENCE"

            elif avg_conf >= 0.50:
                plan_state = "NORMAL"

            elif avg_conf >= 0.25:
                plan_state = "CAUTIOUS"

            else:
                plan_state = "LOW_CONFIDENCE"

            # ==================================================
            # BUILD PLAN
            # ==================================================

            plan = {
                "state": plan_state,
                "confidence": avg_conf,
                "reasoning_weight": reasoning_weight,
                "timestamp": time.time(),
            }

            self.current_plan = plan

            # ==================================================
            # OPTIONAL PLAN CALLBACK
            # ==================================================

            plan_callback = getattr(
                self,
                "_on_plan",
                None,
            )

            if callable(plan_callback):

                try:

                    callback_result = plan_callback(
                        plan
                    )

                    if inspect.isawaitable(
                        callback_result
                    ):
                        await callback_result

                except Exception as exc:

                    self.logger.debug(
                        "[QbitDialer] Plan callback "
                        "failed: %s",
                        exc,
                    )

            # ==================================================
            # PLAN COMPLETE
            # ==================================================

            self.planning = False

            return plan

        except asyncio.CancelledError:

            self.planning = False
            raise

        except Exception:

            self.planning = False

            self.logger.exception(
                "[QbitDialer] Planning failed"
            )

            return None
    # ==========================================================
    # SAFE QBIT INITIALIZATION / RUNTIME
    # ==========================================================
# ==========================================================
# QBIT COMMAND PLANE
#
# COMPATIBILITY / OBSERVABILITY ONLY
#
# submit_command() is the sole command admission authority.
#
# command_queue is consumed ONLY by:
#
#     _process_command_plane()
#
# QbitQueueLoop transports Qbits.
# QbitDialer processes/adjudicates them.
#
# RAW Qbits are DATA and never execute here.
#
# DO NOT:
#   - consume command_queue
#   - execute_command()
#   - create another command loop
#   - create another command queue
#
# ==========================================================

    async def _process_qbit_commands(
        self,
    ):

    # ----------------------------------------------------------
    # This method is retained only for legacy/runtime
    # compatibility.
    #
    # The authoritative command consumer is:
    #
    #     _process_command_plane()
    #
    # Therefore this method MUST NOT consume command_queue.
    # ----------------------------------------------------------

        self.logger.debug(
            "[QbitDialer] _process_qbit_commands compatibility "
            "shim | authoritative consumer=_process_command_plane"
        )

        return 0


    # ==========================================================
    # QBIT COMMAND PLANE
    #
    # QbitQueueLoop
    #     = authoritative transport / queue delivery
    #
    # QbitDialer
    #     = command-plane execution / Qbit control
    #
    # Qbit
    #     = authoritative data / state / health
    #
    # IMPORTANT:
    #
    #     This method does NOT consume queue_loop.queue.
    #     This method does NOT create QbitQueueLoop.
    #     This method does NOT create another Qbit.
    #
    #     It operates only against the QbitQueueLoop instance
    #     already bound by boot.
    # ==========================================================

    async def _qbit_loop_async(self):

        self.logger.info(
            "[QbitDialer] Qbit command plane starting"
        )

        # ------------------------------------------------------
        # AUTHORITATIVE QBIT QUEUE LOOP
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "_qbit_queue_loop",
                None,
            )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "queue_loop",
                None,
            )

        if queue_loop is None:

            self.logger.error(
                "[QbitDialer] Command plane refused | "
                "QbitQueueLoop not connected"
            )

            self._qbit_running = False
            self._running = False
            self._qbit_runtime_state = "WAITING"

            return

        # ------------------------------------------------------
        # VERIFY COMMAND AUTHORITY
        # ------------------------------------------------------

        bound_dialer = getattr(
            queue_loop,
            "qbit_dialer",
            None,
        )

        if bound_dialer is not self:

            self.logger.error(
                "[QbitDialer] Command plane refused | "
                "QbitQueueLoop is bound to another Dialer"
            )

            self._qbit_running = False
            self._running = False
            self._qbit_runtime_state = "ERROR"

            return

        # ------------------------------------------------------
        # AUTHORITATIVE QBIT
        # ------------------------------------------------------

        qbit = getattr(
            self,
            "qbit",
            None,
        )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit_instance",
                None,
            )

        if qbit is None:

            self.logger.error(
                "[QbitDialer] Command plane refused | "
                "authoritative Qbit not bound"
            )

            self._qbit_running = False
            self._running = False
            self._qbit_runtime_state = "WAITING"

            return

        # ------------------------------------------------------
        # VERIFY QBIT IDENTITY
        # ------------------------------------------------------

        queue_qbit = getattr(
            queue_loop,
            "qbit",
            None,
        )

        if (
            queue_qbit is not None
            and queue_qbit is not qbit
        ):

            self.logger.error(
                "[QbitDialer] Command plane refused | "
                "Qbit identity mismatch with QbitQueueLoop"
            )

            self._qbit_running = False
            self._running = False
            self._qbit_runtime_state = "ERROR"

            return

        # ------------------------------------------------------
        # RUNTIME STATE
        #
        # The command plane may run only while the authoritative
        # transport is online.
        # ------------------------------------------------------

        self._qbit_runtime_state = "RUNNING"
        self._qbit_running = True
        self._running = True

        try:

            while (
                self._qbit_running
                and self._running
                and not self.shutdown_flag.is_set()
            ):

                try:

                    # ==================================================
                    # 1. VERIFY QBIT QUEUE LOOP IS STILL AUTHORITATIVE
                    # ==================================================

                    current_queue_loop = getattr(
                        self,
                        "qbit_queue_loop",
                        None,
                    )

                    if current_queue_loop is not queue_loop:

                        self.logger.error(
                            "[QbitDialer] Command plane lost "
                            "QbitQueueLoop authority"
                        )

                        break

                    current_dialer = getattr(
                        queue_loop,
                        "qbit_dialer",
                        None,
                    )

                    if current_dialer is not self:

                        self.logger.error(
                            "[QbitDialer] Command plane authority "
                            "changed while running"
                        )

                        break

                    # ==================================================
                    # 2. VERIFY TRANSPORT IS ONLINE
                    #
                    # Do not process commands against an offline
                    # QbitQueueLoop.
                    # ==================================================

                    queue_running = getattr(
                        queue_loop,
                        "_running",
                        None,
                    )

                    if queue_running is None:

                        queue_running = getattr(
                            queue_loop,
                            "running",
                            False,
                        )

                    if not queue_running:

                        self.logger.warning(
                            "[QbitDialer] Command plane waiting | "
                            "QbitQueueLoop offline"
                        )

                        self._qbit_runtime_state = "WAITING"

                        await asyncio.sleep(
                            max(
                                float(
                                    getattr(
                                        self,
                                        "loop_interval",
                                        0.1,
                                    )
                                ),
                                0.05,
                            )
                        )

                        continue

                    # ==================================================
                    # 3. QBIT COMMAND PLANE
                    #
                    # Commands arrive through QbitQueueLoop.
                    #
                    # This method executes the command-plane work;
                    # it does NOT pull directly from the queue.
                    # ==================================================

                    await self._process_qbit_commands()

                    # ==================================================
                    # 4. QBIT DATA / HEALTH
                    # ==================================================

                    measure = getattr(
                        qbit,
                        "measure",
                        None,
                    )

                    if callable(measure):

                        result = measure()

                        # ----------------------------------------------
                        # Measurement remains inside the Dialer because
                        # it feeds command/brain/health decisions.
                        # ----------------------------------------------

                        await self._on_measurement(
                            result
                        )

                    else:

                        self.logger.warning(
                            "[QbitDialer] Qbit measurement unavailable | "
                            "command plane remains active"
                        )

                    # ==================================================
                    # 5. QBIT HEALTH FLAGS
                    # ==================================================

                    health_method = getattr(
                        qbit,
                        "get_health_flags",
                        None,
                    )

                    if callable(
                        health_method
                    ):

                        health_flags = health_method()

                        self._qbit_health_flags = (
                            health_flags
                        )

                    # ==================================================
                    # 6. NORMAL COMMAND-PLANE INTERVAL
                    # ==================================================

                    try:

                        interval = float(
                            getattr(
                                self,
                                "loop_interval",
                                0.1,
                            )
                        )

                    except (
                        TypeError,
                        ValueError,
                    ):

                        interval = 0.1

                    await asyncio.sleep(
                        max(
                            0.01,
                            interval,
                        )
                    )

                except asyncio.CancelledError:

                    raise

                except Exception as exc:

                    self.logger.exception(
                        "[QbitDialer] Command plane error | "
                        "%s: %s",
                        type(exc).__name__,
                        exc,
                    )

                    await asyncio.sleep(
                        max(
                            float(
                                getattr(
                                    self,
                                    "loop_interval",
                                    0.1,
                                )
                            ),
                            0.05,
                        )
                    )

        finally:

            # --------------------------------------------------
            # COMMAND PLANE EXIT
            # --------------------------------------------------

            self._qbit_running = False
            self._running = False

            if (
                getattr(
                    self,
                    "_qbit_runtime_state",
                    None,
                )
                != "ERROR"
            ):

                self._qbit_runtime_state = "STOPPED"

            self.logger.info(
                "[QbitDialer] Qbit command plane stopped"
            )

    # ==========================================================
    # MEASUREMENT HANDLER
    # ==========================================================

    async def _on_measurement(self, value):

        now = time.monotonic()

        # ------------------------------------------------------
        # RECORD LATEST MEASUREMENT
        # ------------------------------------------------------
        self.last_measurement = value
        self._last_measurement_monotonic = now

        self._measurement_count = (
            getattr(
                self,
                "_measurement_count",
                0,
            ) + 1
        )

        # ------------------------------------------------------
        # BOUNDED HISTORY
        # ------------------------------------------------------
        measurements = getattr(
            self,
            "buffers",
            {},
        ).get("measurement")

        if measurements is not None:
            try:
                measurements.append(value)

            except Exception:
                self.logger.debug(
                    "[QbitDialer] Measurement buffer "
                    "unavailable",
                    exc_info=True,
                )

        # ------------------------------------------------------
        # THROTTLED DEBUG LOGGING
        # ------------------------------------------------------
        log_interval = getattr(
            self,
            "_measurement_log_interval",
            1.0,
        )

        last_log = getattr(
            self,
            "_last_measurement_log",
            0.0,
        )

        if (
            now - last_log
            >= log_interval
        ):

            self._last_measurement_log = now

            self.logger.debug(
                "[QbitDialer] Qbit measurement | "
                "value=%s | count=%d",
                value,
                self._measurement_count,
            )

        return value


    # ==========================================================
    # SAFE QBIT STATE UPDATE
    # ==========================================================

    async def update_state(self, new_state):

        if new_state is None:
            raise ValueError(
                "new_state cannot be None"
            )

        # ------------------------------------------------------
        # NORMALIZE
        # ------------------------------------------------------
        normalized = normalize_qbit_input(
            new_state
        )

        if not isinstance(
            normalized,
            tuple,
        ):
            normalized = tuple(
                normalized
            )

        if len(normalized) != 2:
            raise ValueError(
                "Qbit state must contain exactly "
                f"2 elements, got {len(normalized)}"
            )

        normalized = tuple(
            complex(x)
            for x in normalized
        )

        # ------------------------------------------------------
        # LOCKED UPDATE
        # ------------------------------------------------------
        lock = getattr(
            self,
            "_qbit_lock",
            None,
        )

        if lock is None:
            self._qbit_lock = threading.RLock()
            lock = self._qbit_lock

        with lock:

            qbit_instance = Qbit(
                normalized
            )

            if qbit_instance is None:
                raise RuntimeError(
                    "Qbit state update produced "
                    "no Qbit instance"
                )

            self.qbit_state = normalized

            # Keep both references synchronized.
            self.qbit_instance = (
                qbit_instance
            )
            self.qbit = (
                qbit_instance
            )

        self.logger.debug(
            "[QbitDialer] Qbit state updated | "
            "state=%s",
            normalized,
        )

        return qbit_instance


    # ==========================================================
    # QBIT RUNTIME STOP
    # ==========================================================

    async def stop_qbit_loop(self):

        task = getattr(
            self,
            "_qbit_loop_task",
            None,
        )

        self._qbit_running = False
        self._running = False

        shutdown_flag = getattr(
            self,
            "shutdown_flag",
            None,
        )

        if shutdown_flag is not None:
            shutdown_flag.set()

        self._qbit_runtime_state = "STOPPING"

        # ------------------------------------------------------
        # CANCEL ACTIVE TASK
        # ------------------------------------------------------
        if (
            task is not None
            and not task.done()
        ):

            current_task = (
                asyncio.current_task()
            )

            if task is not current_task:
                task.cancel()

                try:
                    await task

                except asyncio.CancelledError:
                    pass

                except Exception:
                    self.logger.exception(
                        "[QbitDialer] Error while "
                        "stopping Qbit loop"
                    )

        self._qbit_loop_task = None

        self._qbit_runtime_state = "STOPPED"

        self.logger.info(
            "[QbitDialer] Qbit loop stopped by command"
        )

        return True

    # -------------------------
    # CORE QBIT LOOP
    # -------------------------
    #
    # QbitDialer is the Qbit processing authority.
    #
    # Runtime flow:
    #
    #   Heartbeat
    #       |
    #       v
    #   EventBus
    #       |
    #       v
    #   QbitDialer
    #       |
    #       +----> COMMAND PLANE
    #       |
    #       +----> Qbit State / Measurement
    #       |
    #       +----> Qbit Health
    #       |
    #       +----> AUTHORITATIVE QbitQueueLoop
    #       |
    #       +----> TrackSystem
    #
    # IMPORTANT:
    #
    #   - Do not create another Qbit.
    #   - Do not create another queue.
    #   - Do not consume QbitQueueLoop's internal queue here.
    #   - Do not replace an existing TrackID.
    #   - Do not manufacture command work while idle.
    #   - Commands already admitted by the command plane remain
    #     executable regardless of background Qbit throttling.
    #   - Heartbeat may wake/drive the Dialer, but does not become
    #     a command.
    #   - QbitQueueLoop is the sole authoritative Qbit transport.
    #
    # DATA AUTHORITY:
    #
    #   Qbit
    #      |
    #      v
    #   QbitDialer
    #      |
    #      v
    #   QbitQueueLoop
    #
    # COMMAND AUTHORITY:
    #
    #   EventBus / command admission
    #      |
    #      v
    #   QbitDialer
    #      |
    #      v
    #   execute_command()
    #
    # ================================================================


    async def _qbit_loop(self):

        self.logger.info(
            "[QbitDialer] Async Qbit loop starting"
        )

        IDLE_INTERVAL = 2.50
        PLAN_INTERVAL = 0.50
        ACTIVE_INTERVAL = 0.10
        COMMAND_INTERVAL = 0.02
        MIN_INTERVAL = 0.05
        STARTUP_INTERVAL = 0.10

        last_tick = 0.0
        last_measurement = 0.0

        # ============================================================
        # ESTABLISH CANONICAL RUNTIME FLAGS
        # ============================================================

        self._qbit_running = True

        if not hasattr(
            self,
            "_running",
        ):
            self._running = True

        if not hasattr(
            self,
            "running",
        ):
            self.running = self._running

        # ============================================================
        # COMMAND PLANE
        # ============================================================

        if not hasattr(
            self,
            "command_queue",
        ):
            self.command_queue = None

        if not hasattr(
            self,
            "command_plane",
        ):
            self.command_plane = {}

        self.command_plane.setdefault(
            "online",
            False,
        )

        self.command_plane.setdefault(
            "active",
            False,
        )

        self.command_plane.setdefault(
            "mode",
            "BOOT",
        )

        self.command_plane.setdefault(
            "startup_state",
            "BOOT",
        )

        self.command_plane.setdefault(
            "last_command",
            None,
        )

        self.command_plane.setdefault(
            "last_measurement",
            None,
        )

        self.command_plane.setdefault(
            "last_measurement_time",
            None,
        )

        self.command_plane.setdefault(
            "last_tick",
            None,
        )

        self.command_plane.setdefault(
            "last_mode",
            None,
        )

        self.command_plane.setdefault(
            "measurement_age",
            None,
        )

        # ============================================================
        # QBIT HEALTH
        # ============================================================

        if not hasattr(
            self,
            "qbit_health",
        ):
            self.qbit_health = {}

        self.qbit_health.setdefault(
            "online",
            False,
        )

        self.qbit_health.setdefault(
            "valid",
            False,
        )

        self.qbit_health.setdefault(
            "measuring",
            False,
        )

        self.qbit_health.setdefault(
            "queue_connected",
            False,
        )

        self.qbit_health.setdefault(
            "data_flow",
            False,
        )

        self.qbit_health.setdefault(
            "last_measurement",
            None,
        )

        self.qbit_health.setdefault(
            "measurement_age",
            None,
        )

        self.qbit_health.setdefault(
            "error",
            None,
        )

        # ============================================================
        # LOCAL LIFECYCLE HELPERS
        # ============================================================

        def _lifecycle_running():

            shutdown_flag = getattr(
                self,
                "shutdown_flag",
                None,
            )

            if (
                shutdown_flag is not None
                and shutdown_flag.is_set()
            ):
                return False

            if not getattr(
                self,
                "_running",
                False,
            ):
                return False

            if not getattr(
                self,
                "_qbit_running",
                False,
            ):
                return False

            if (
                hasattr(
                    self,
                    "running",
                )
                and not self.running
            ):
                return False

            return True

        async def _startup_wait(
            state,
            message,
        ):

            self.command_plane[
                "startup_state"
            ] = state

            self.command_plane[
                "online"
            ] = False

            self.command_plane[
                "active"
            ] = False

            self.command_plane[
                "mode"
            ] = state

            await asyncio.sleep(
                STARTUP_INTERVAL
            )

        # ============================================================
        # STARTUP STATE MACHINE
        #
        # BOOT
        #   â†“
        # WAITING_FOR_SYSTEM
        #   â†“
        # WAITING_FOR_REGISTRY
        #   â†“
        # WAITING_FOR_QBIT
        #   â†“
        # WAITING_FOR_QUEUE
        #   â†“
        # BIND_QBIT_DIALER
        #   â†“
        # WAITING_FOR_COMMAND_REGISTRY
        #   â†“
        # ONLINE
        #
        # This is startup synchronization only.
        # It does NOT create another processing loop.
        # ============================================================

        queue_loop = None
        instance = None
        registry = None

        try:

            # ========================================================
            # 0. WAITING_FOR_SYSTEM
            # ========================================================

            while _lifecycle_running():

                self.command_plane[
                    "startup_state"
                ] = "WAITING_FOR_SYSTEM"

                self.command_plane[
                    "online"
                ] = False

                self.command_plane[
                    "active"
                ] = False

                system_ready = False

                readiness_methods = (
                    "is_system_ready",
                    "system_is_ready",
                    "is_runtime_ready",
                    "runtime_is_ready",
                )

                for method_name in readiness_methods:

                    method = getattr(
                        self,
                        method_name,
                        None,
                    )

                    if callable(method):

                        try:

                            result = method()

                            if inspect.isawaitable(
                                result
                            ):
                                result = await result

                            system_ready = bool(
                                result
                            )

                        except Exception:

                            self.logger.exception(
                                "[QbitDialer] System readiness "
                                "check failed | method=%s",
                                method_name,
                            )

                        break

                if not system_ready:

                    system_state = getattr(
                        self,
                        "system_state",
                        None,
                    )

                    if system_state is None:

                        system_state = getattr(
                            self,
                            "_system_state",
                            None,
                        )

                    if isinstance(
                        system_state,
                        str,
                    ):

                        system_ready = (
                            system_state.upper()
                            in (
                                "READY",
                                "ONLINE",
                                "RUNNING",
                                "ACTIVE",
                            )
                        )

                    elif isinstance(
                        system_state,
                        dict,
                    ):

                        system_ready = bool(
                            system_state.get(
                                "ready",
                                system_state.get(
                                    "system_ready",
                                    False,
                                ),
                            )
                        )

                    if not system_ready:

                        system_ready = bool(
                            getattr(
                                self,
                                "system_ready",
                                False,
                            )
                        )

                if system_ready:

                    break

                await _startup_wait(
                    "WAITING_FOR_SYSTEM",
                    "[QbitDialer] Waiting for system state",
                )

            # ========================================================
            # 1. WAITING_FOR_REGISTRY
            # ========================================================

            while _lifecycle_running():

                self.command_plane[
                    "startup_state"
                ] = "WAITING_FOR_REGISTRY"

                registry = None

                registry_candidates = (
                    "command_registry",
                    "_command_registry",
                    "registry",
                    "sregistry",
                    "SRegistry",
                    "_sregistry",
                )

                for attr_name in registry_candidates:

                    candidate = getattr(
                        self,
                        attr_name,
                        None,
                    )

                    if candidate is not None:

                        registry = candidate

                        break

                if registry is not None:

                    break

                await _startup_wait(
                    "WAITING_FOR_REGISTRY",
                    "[QbitDialer] Waiting for SRegistry / command registry",
                )

            # ========================================================
            # 2. WAITING_FOR_QBIT
            # ========================================================

            while _lifecycle_running():

                self.command_plane[
                    "startup_state"
                ] = "WAITING_FOR_QBIT"

                instance = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

                if instance is None:

                    instance = getattr(
                        self,
                        "qbit",
                        None,
                    )

                if instance is not None:

                    break

                self.qbit_health[
                    "online"
                ] = False

                self.qbit_health[
                    "valid"
                ] = False

                self.qbit_health[
                    "measuring"
                ] = False

                self.qbit_health[
                    "data_flow"
                ] = False

                self.qbit_health[
                    "error"
                ] = "Qbit instance unavailable"

                await _startup_wait(
                    "WAITING_FOR_QBIT",
                    "[QbitDialer] Waiting for authoritative Qbit",
                )

            # ========================================================
            # 3. WAITING_FOR_QUEUE
            # ========================================================

            while _lifecycle_running():

                self.command_plane[
                    "startup_state"
                ] = "WAITING_FOR_QUEUE"

                queue_loop = getattr(
                    self,
                    "qbit_queue_loop",
                    None,
                )

                if queue_loop is None:

                    queue_loop = getattr(
                        self,
                        "_qbit_queue_loop",
                        None,
                    )

                if queue_loop is None:

                    queue_loop = getattr(
                        self,
                        "queue_loop",
                        None,
                    )

                if queue_loop is not None:

                    break

                self.qbit_health[
                    "queue_connected"
                ] = False

                self.qbit_health[
                    "data_flow"
                ] = False

                await _startup_wait(
                    "WAITING_FOR_QUEUE",
                    "[QbitDialer] Waiting for authoritative QbitQueueLoop",
                )

            # ========================================================
            # 4. BIND_QBIT_DIALER
            # ========================================================

            self.command_plane[
                "startup_state"
            ] = "BIND_QBIT_DIALER"

            self.command_plane[
                "online"
            ] = False

            self.command_plane[
                "active"
            ] = False

            self.logger.info(
                "[QbitDialer] Binding to authoritative QbitQueueLoop"
            )

            self.qbit_queue_loop = queue_loop

            if hasattr(
                self,
                "_qbit_queue_loop",
            ):
                self._qbit_queue_loop = queue_loop

            if hasattr(
                self,
                "queue_loop",
            ):
                self.queue_loop = queue_loop

            bound_dialer = getattr(
                queue_loop,
                "qbit_dialer",
                None,
            )

            if bound_dialer is None:

                bind_method = getattr(
                    queue_loop,
                    "bind_qbit_dialer",
                    None,
                )

                if callable(
                    bind_method
                ):

                    result = bind_method(
                        self
                    )

                    if inspect.isawaitable(
                        result
                    ):
                        await result

                    bound_dialer = getattr(
                        queue_loop,
                        "qbit_dialer",
                        None,
                    )

            elif bound_dialer is not self:

                self.logger.error(
                    "[QbitDialer] FATAL: QbitQueueLoop is already "
                    "bound to another QbitDialer"
                )

                self.qbit_health[
                    "queue_connected"
                ] = False

                while _lifecycle_running():

                    bound_dialer = getattr(
                        queue_loop,
                        "qbit_dialer",
                        None,
                    )

                    if bound_dialer is self:

                        break

                    await _startup_wait(
                        "BIND_QBIT_DIALER",
                        "[QbitDialer] Waiting for authoritative queue binding",
                    )

            if getattr(
                queue_loop,
                "qbit_dialer",
                None,
            ) is self:

                self.qbit_health[
                    "queue_connected"
                ] = True

                self.logger.info(
                    "[QbitDialer] QbitQueueLoop connected | "
                    "command_authority=QbitDialer"
                )

            else:

                self.qbit_health[
                    "queue_connected"
                ] = False

                self.logger.error(
                    "[QbitDialer] Unable to establish authoritative "
                    "QbitQueueLoop binding"
                )

            # ========================================================
            # 5. WAITING_FOR_COMMAND_REGISTRY
            # ========================================================

            while _lifecycle_running():

                self.command_plane[
                    "startup_state"
                ] = "WAITING_FOR_COMMAND_REGISTRY"

                registry = (
                    getattr(
                        self,
                        "command_registry",
                        None,
                    )
                    or registry
                )

                if registry is None:

                    registry_candidates = (
                        "command_registry",
                        "_command_registry",
                        "registry",
                        "sregistry",
                        "SRegistry",
                        "_sregistry",
                    )

                    for attr_name in registry_candidates:

                        candidate = getattr(
                            self,
                            attr_name,
                            None,
                        )

                        if candidate is not None:

                            registry = candidate

                            break

                handlers_ready = False

                readiness_methods = (
                    "is_command_registry_ready",
                    "command_registry_ready",
                    "is_registry_ready",
                    "registry_ready",
                )

                for method_name in readiness_methods:

                    method = getattr(
                        self,
                        method_name,
                        None,
                    )

                    if callable(method):

                        try:

                            result = method()

                            if inspect.isawaitable(
                                result
                            ):
                                result = await result

                            handlers_ready = bool(
                                result
                            )

                        except Exception:

                            self.logger.exception(
                                "[QbitDialer] Command registry "
                                "readiness check failed | method=%s",
                                method_name,
                            )

                        break

                if (
                    not handlers_ready
                    and registry is not None
                ):

                    handler_container = None

                    for attr_name in (
                        "commands",
                        "handlers",
                        "_commands",
                        "_handlers",
                        "command_handlers",
                    ):

                        candidate = getattr(
                            registry,
                            attr_name,
                            None,
                        )

                        if candidate is not None:

                            handler_container = candidate

                            break

                    if handler_container is not None:

                        try:

                            handlers_ready = (
                                len(
                                    handler_container
                                ) > 0
                            )

                        except Exception:

                            handlers_ready = False

                if not handlers_ready:

                    for attr_name in (
                        "command_handlers",
                        "_command_handlers",
                        "commands",
                        "_commands",
                    ):

                        candidate = getattr(
                            self,
                            attr_name,
                            None,
                        )

                        if candidate is not None:

                            try:

                                if len(
                                    candidate
                                ) > 0:

                                    handlers_ready = True

                                    break

                            except Exception:

                                pass

                if (
                    registry is not None
                    and handlers_ready
                    and self.qbit_health.get(
                        "queue_connected",
                        False,
                    )
                    and instance is not None
                ):

                    break

                await _startup_wait(
                    "WAITING_FOR_COMMAND_REGISTRY",
                    "[QbitDialer] Waiting for complete command registry / handlers",
                )

            # ========================================================
            # 6. ONLINE
            # ========================================================

            if not _lifecycle_running():

                return

            self.command_plane[
                "startup_state"
            ] = "ONLINE"

            self.command_plane[
                "online"
            ] = True

            self.command_plane[
                "active"
            ] = True

            self.command_plane[
                "mode"
            ] = "ONLINE"

            self.qbit_health[
                "online"
            ] = True

            self.logger.info(
                "[QbitDialer] ONLINE | "
                "system=ready | "
                "registry=ready | "
                "qbit=ready | "
                "queue=bound | "
                "handlers=ready"
            )

            # ========================================================
            # AUTHORITATIVE PROCESSING LOOP
            #
            # This remains the SINGLE Qbit processing loop.
            # ========================================================

            while True:

                # ====================================================
                # 0. HARD LIFECYCLE GATE
                # ====================================================

                if not _lifecycle_running():

                    break

                # ====================================================
                # 1. COMMAND PLANE FIRST
                # ====================================================

                command_processed = False
                command = None

                command_queue = getattr(
                    self,
                    "command_queue",
                    None,
                )

                if command_queue is not None:

                    try:

                        try:

                            command = (
                                command_queue.get_nowait()
                            )

                        except (
                            asyncio.QueueEmpty,
                            queue.Empty,
                        ):

                            command = None

                        if command is not None:

                            command_processed = True

                            try:

                                result = (
                                    await self.execute_command(
                                        command
                                    )
                                )

                                self.command_plane[
                                    "last_command"
                                ] = command

                                self.logger.debug(
                                    "[QbitDialer] Qbit command "
                                    "executed | result=%s",
                                    result,
                                )

                            except asyncio.CancelledError:

                                raise

                            except Exception:

                                self.logger.exception(
                                    "[QbitDialer] Qbit command "
                                    "execution failed | command=%r",
                                    command,
                                )

                            finally:

                                task_done = getattr(
                                    command_queue,
                                    "task_done",
                                    None,
                                )

                                if callable(
                                    task_done
                                ):

                                    try:

                                        task_done()

                                    except ValueError:

                                        self.logger.warning(
                                            "[QbitDialer] Command queue "
                                            "task_done bookkeeping rejected"
                                        )

                                    except Exception:

                                        self.logger.exception(
                                            "[QbitDialer] Command queue "
                                            "task_done failed"
                                        )

                    except asyncio.CancelledError:

                        raise

                    except Exception:

                        self.logger.exception(
                            "[QbitDialer] Qbit command-plane "
                            "processing failure"
                        )

                # ====================================================
                # 2. OPERATING STATE
                # ====================================================

                try:

                    tick_state = await self._tick()

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Tick-state evaluation failed"
                    )

                    tick_state = TICK_IDLE

                limp = bool(
                    getattr(
                        self,
                        "limp_mode",
                        False,
                    )
                )

                idle = bool(
                    getattr(
                        self,
                        "idle",
                        False,
                    )
                )

                planning = bool(
                    getattr(
                        self,
                        "planning",
                        False,
                    )
                )

                # ====================================================
                # 3. RUNTIME MODE
                # ====================================================

                if limp:

                    mode = "LIMP"
                    interval = IDLE_INTERVAL

                elif planning:

                    mode = "PLANNING"
                    interval = PLAN_INTERVAL

                elif idle:

                    mode = "IDLE"
                    interval = IDLE_INTERVAL

                else:

                    mode = "ACTIVE"
                    interval = ACTIVE_INTERVAL

                interval = max(
                    float(interval),
                    MIN_INTERVAL,
                )

                # ====================================================
                # 4. COMMAND PLANE STATUS
                # ====================================================

                self.command_plane[
                    "online"
                ] = True

                self.command_plane[
                    "active"
                ] = bool(
                    getattr(
                        self,
                        "_running",
                        False,
                    )
                )

                self.command_plane[
                    "mode"
                ] = mode

                self.command_plane[
                    "tick_state"
                ] = tick_state

                self.command_plane[
                    "limp_mode"
                ] = limp

                self.command_plane[
                    "planning"
                ] = planning

                self.command_plane[
                    "idle"
                ] = idle

                self.command_plane[
                    "startup_state"
                ] = "ONLINE"

                # ====================================================
                # 5. COMMANDS WAKE THE DIALER
                # ====================================================

                if command_processed:

                    await asyncio.sleep(
                        COMMAND_INTERVAL
                    )

                    continue

                # ====================================================
                # 6. IDLE / LIMP
                # ====================================================

                if mode in (
                    "IDLE",
                    "LIMP",
                ):

                    await asyncio.sleep(
                        interval
                    )

                    continue

                # ====================================================
                # 7. ACTIVE RATE LIMIT
                # ====================================================

                now = time.monotonic()

                elapsed = (
                    now - last_tick
                )

                if elapsed < interval:

                    await asyncio.sleep(
                        max(
                            interval - elapsed,
                            MIN_INTERVAL,
                        )
                    )

                    continue

                last_tick = time.monotonic()

                # ====================================================
                # 8. CANONICAL QBIT
                # ====================================================

                instance = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

                if instance is None:

                    instance = getattr(
                        self,
                        "qbit",
                        None,
                    )

                state = getattr(
                    self,
                    "qbit_state",
                    None,
                )

                if instance is None:

                    self.qbit_health[
                        "online"
                    ] = False

                    self.qbit_health[
                        "valid"
                    ] = False

                    self.qbit_health[
                        "measuring"
                    ] = False

                    self.qbit_health[
                        "data_flow"
                    ] = False

                    self.qbit_health[
                        "error"
                    ] = "Qbit instance unavailable"

                    await asyncio.sleep(
                        interval
                    )

                    continue

                # ====================================================
                # 9. MEASURE QBIT
                # ====================================================

                measurement = None

                self.qbit_health[
                    "online"
                ] = True

                self.qbit_health[
                    "measuring"
                ] = True

                try:

                    measure = getattr(
                        instance,
                        "measure",
                        None,
                    )

                    if not callable(
                        measure
                    ):

                        raise RuntimeError(
                            "Qbit has no measure() method"
                        )

                    measurement = measure()

                    if measurement is None:

                        raise RuntimeError(
                            "Qbit measurement returned None"
                        )

                    self.qbit_health[
                        "valid"
                    ] = True

                    self.qbit_health[
                        "error"
                    ] = None

                    last_measurement = (
                        time.monotonic()
                    )

                    self.last_qbit_measurement = (
                        measurement
                    )

                    self.command_plane[
                        "last_measurement"
                    ] = measurement

                    self.command_plane[
                        "last_measurement_time"
                    ] = time.time()

                    await self._on_measurement(
                        measurement
                    )

                except asyncio.CancelledError:

                    raise

                except Exception as exc:

                    self.qbit_health[
                        "valid"
                    ] = False

                    self.qbit_health[
                        "data_flow"
                    ] = False

                    self.qbit_health[
                        "error"
                    ] = str(exc)

                    self.logger.exception(
                        "[QbitDialer] Qbit measurement failed"
                    )

                finally:

                    self.qbit_health[
                        "measuring"
                    ] = False

                # ====================================================
                # 10. QBIT DATA -> AUTHORITATIVE QbitQueueLoop
                # ====================================================

                if (
                    measurement is not None
                    and self.qbit_health.get(
                        "valid",
                        False,
                    )
                ):

                    queue_loop = getattr(
                        self,
                        "qbit_queue_loop",
                        None,
                    )

                    if queue_loop is None:

                        queue_loop = getattr(
                            self,
                            "_qbit_queue_loop",
                            None,
                        )

                    if queue_loop is None:

                        queue_loop = getattr(
                            self,
                            "queue_loop",
                            None,
                        )

                    if queue_loop is None:

                        self.qbit_health[
                            "queue_connected"
                        ] = False

                        self.qbit_health[
                            "data_flow"
                        ] = False

                    else:

                        try:

                            frame = {
                                "type": "QBIT_DATA",
                                "qbit": instance,
                                "qbit_state": state,
                                "measurement": measurement,
                                "mode": mode,
                                "tick_state": tick_state,
                                "timestamp": time.time(),
                            }

                            existing_track_id = getattr(
                                self,
                                "current_track_id",
                                None,
                            )

                            if existing_track_id is not None:

                                frame[
                                    "track_id"
                                ] = existing_track_id

                            submitted = False

                            submit = getattr(
                                queue_loop,
                                "submit_qbit",
                                None,
                            )

                            if callable(
                                submit
                            ):

                                result = submit(
                                    frame
                                )

                                if inspect.isawaitable(
                                    result
                                ):

                                    await result

                                submitted = True

                            if not submitted:

                                enqueue = getattr(
                                    queue_loop,
                                    "enqueue_qbit",
                                    None,
                                )

                                if callable(
                                    enqueue
                                ):

                                    result = enqueue(
                                        frame
                                    )

                                    if inspect.isawaitable(
                                        result
                                    ):

                                        await result

                                    submitted = True

                            if not submitted:

                                enqueue = getattr(
                                    queue_loop,
                                    "enqueue",
                                    None,
                                )

                                if callable(
                                    enqueue
                                ):

                                    result = enqueue(
                                        frame
                                    )

                                    if inspect.isawaitable(
                                        result
                                    ):

                                        await result

                                    submitted = True

                            if not submitted:

                                self.qbit_health[
                                    "data_flow"
                                ] = False

                                self.logger.error(
                                    "[QbitDialer] QbitQueueLoop "
                                    "has no supported Qbit submission API"
                                )

                            else:

                                self.qbit_health[
                                    "data_flow"
                                ] = True

                                self.qbit_health[
                                    "queue_connected"
                                ] = True

                        except asyncio.CancelledError:

                            raise

                        except Exception as exc:

                            self.qbit_health[
                                "data_flow"
                            ] = False

                            self.qbit_health[
                                "error"
                            ] = str(exc)

                            self.logger.exception(
                                "[QbitDialer] QbitQueueLoop "
                                "data handoff failed"
                            )

                # ====================================================
                # 11. RUNTIME HEALTH
                # ====================================================

                try:

                    self.command_plane[
                        "last_tick"
                    ] = time.time()

                    self.command_plane[
                        "last_mode"
                    ] = mode

                    measurement_age = (
                        time.monotonic()
                        - last_measurement
                        if last_measurement
                        else None
                    )

                    self.command_plane[
                        "measurement_age"
                    ] = measurement_age

                    self.qbit_health[
                        "measurement_age"
                    ] = measurement_age

                except Exception:

                    pass

                # ====================================================
                # 12. ALWAYS YIELD
                # ====================================================

                await asyncio.sleep(
                    interval
                )

        except asyncio.CancelledError:

            self.logger.info(
                "[QbitDialer] Async Qbit loop cancelled"
            )

            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] Fatal Qbit loop error"
            )

        finally:

            self._qbit_running = False

            self.qbit_health[
                "online"
            ] = False

            self.qbit_health[
                "measuring"
            ] = False

            self.qbit_health[
                "data_flow"
            ] = False

            self.command_plane[
                "online"
            ] = False

            self.command_plane[
                "active"
            ] = False

            self.command_plane[
                "startup_state"
            ] = "STOPPED"

            self.logger.info(
                "[QbitDialer] Async Qbit loop stopped"
            )



    async def stop_qbit_loop(self):

        self._qbit_running = False

        self.logger.info(
            "[QbitDialer] Qbit loop stop requested"
        )

        # ------------------------------------------------------------
        # Wake a sleeping/blocked command loop if possible.
        # ------------------------------------------------------------

        try:

            queue = getattr(
                self,
                "command_queue",
                None,
            )

            if queue is not None:

                # Do not manufacture an executable Qbit command.
                # A sentinel is only used by queue implementations
                # that explicitly support it.
                if hasattr(queue, "put_nowait"):

                    try:
                        queue.put_nowait(
                            None
                        )
                    except Exception:
                        pass

        except Exception:
            self.logger.debug(
                "[QbitDialer] Command queue wake failed",
                exc_info=True,
            )

# ==========================================================
# QBIT THREAD / ASYNC OBSERVER
# ==========================================================
    async def _qbit_thread(self):

        self.logger.info(
            "[QbitDialer] Qbit observer ONLINE"
        )

        interval = getattr(
            self,
            "_qbit_observer_interval",
            1.0,
        )

        try:
            interval = max(
                0.250,
                float(interval),
            )
        except (TypeError, ValueError):
            interval = 1.0

        self._qbit_observer_interval = interval

        try:

            while getattr(self, "running", False):

                # --------------------------------------------------
                # Snapshot state under the lock.
                # --------------------------------------------------
                with self.lock:

                    qbit_state = getattr(
                        self,
                        "qbit_state",
                        None,
                    )

                    qbit_instance = getattr(
                        self,
                        "qbit_instance",
                        None,
                    )

                # --------------------------------------------------
                # Update observer telemetry.
                # --------------------------------------------------
                self._qbit_observer_tick = (
                    getattr(
                        self,
                        "_qbit_observer_tick",
                        0,
                    ) + 1
                )

                self._qbit_instance_present = (
                    qbit_instance is not None
                )

                self._qbit_last_observation = (
                    time.monotonic()
                )

                # --------------------------------------------------
                # Missing Qbit is a state condition, not an
                # exception that should continuously flood logs.
                # --------------------------------------------------
                if qbit_instance is None:

                    if not getattr(
                        self,
                        "_qbit_missing_logged",
                        False,
                    ):

                        self.logger.warning(
                            "[QbitDialer] Qbit observer: "
                            "Qbit instance unavailable"
                        )

                        self._qbit_missing_logged = True

                else:

                    self._qbit_missing_logged = False

                    # Debug only; deliberately throttled.
                    now = time.monotonic()

                    last_log = getattr(
                        self,
                        "_qbit_observer_last_log",
                        0.0,
                    )

                    if now - last_log >= 5.0:

                        self._qbit_observer_last_log = now

                        self.logger.debug(
                            "[QbitDialer] Qbit observer | "
                            "state=%s | instance=%s | tick=%d",
                            qbit_state,
                            type(qbit_instance).__name__,
                            self._qbit_observer_tick,
                        )

            # --------------------------------------------------
            # CRITICAL:
            # Never use time.sleep() in async code.
            # --------------------------------------------------
                await asyncio.sleep(interval)

        except asyncio.CancelledError:

            self.logger.info(
                "[QbitDialer] Qbit observer cancellation requested"
            )

            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] Qbit observer failed"
            )

            raise

        finally:

            self.logger.info(
                "[QbitDialer] Qbit observer OFFLINE"
            )


    async def update_qbit(self, new_state):

    # ==========================================================
    # NORMALIZE
    # ==========================================================
        try: 
            normalized_state = normalize_qbit_input(
                new_state
            )

        except Exception:
            self.logger.exception(
                "[QbitDialer] Qbit state normalization failed"
            )
            return False

    # ==========================================================
    # UPDATE UNDER LOCK
    # ==========================================================
        with self._lock:

            qbit = getattr(
                self,
                "qbit_instance",
                None,
            )

            previous_state = getattr(
                self,
                "qbit_state",
                None,
            )

        # ------------------------------------------------------
        # Duplicate protection
        # ------------------------------------------------------
            if previous_state == normalized_state:

                self._qbit_update_skipped = (
                    getattr(
                        self,
                        "_qbit_update_skipped",
                        0,
                    ) + 1
                )

                return False

        # ------------------------------------------------------
        # Update dialer's authoritative state first.
        # ------------------------------------------------------
            self.qbit_state = normalized_state

        # ------------------------------------------------------
        # Qbit may not yet be attached during boot.
        # Do not create one here.
            # ------------------------------------------------------
            if qbit is None:

                self._qbit_state_pending = True

                self.logger.debug(
                    "[QbitDialer] Qbit state staged | "
                    "instance not yet available"
                )

                return True

        # ------------------------------------------------------
        # Push state into Qbit.
        # ------------------------------------------------------
            try:

                setter = getattr(
                    qbit,
                    "set_state",
                    None,
                )

                if not callable(setter):
                    self.logger.warning(
                        "[QbitDialer] Qbit has no set_state()"
                    )

                    self._qbit_state_pending = True
                    return False

                setter(normalized_state)

                self._qbit_state_pending = False

            except Exception:

            # Preserve the requested state even if the Qbit
            # rejected the mutation.
                self._qbit_state_pending = True

                self.logger.exception(
                    "[QbitDialer] Qbit state update failed"
                )

                return False

    # ==========================================================
    # TELEMETRY
    # ==========================================================
        self._qbit_update_count = (
            getattr(
                self,
                "_qbit_update_count",
                0,
            ) + 1
        )

    # State changes are meaningful, so INFO is appropriate here.
        self.logger.info(
            "[QbitDialer] Qbit state updated | "
            "count=%d | state=%s",
            self._qbit_update_count,
            self.qbit_state,
        )

        return True


    # -------------------------
    # THREAD CONTROL
    # -------------------------


    def _apply_pending_qbit_state(self):
            with self._lock:

                qbit = getattr(
                    self,
                    "qbit_instance",
                    None,
                )

                if qbit is None:
                    return False

                if not getattr(
                    self,
                    "_qbit_state_pending",
                    False,
                ):
                    return False
 
                state = getattr(
                    self,
                    "qbit_state",
                    None,
                )

                if state is None:
                    self._qbit_state_pending = False
                    return False

                setter = getattr(
                    qbit,
                    "set_state",
                    None,
                )

                if not callable(setter):
                    return False

                try:
                    setter(state)
                    self._qbit_state_pending = False

                except Exception:
                    self.logger.exception(
                        "[QbitDialer] Failed applying pending Qbit state"
                    )
                    return False

            self.logger.debug(
                "[QbitDialer] Pending Qbit state applied"
            )
  
            return True
# ========================================================================


# =====================================================================
    #
    async def stop(self):
 

        start_lock = getattr(self, "_start_lock", None)

        if start_lock is None:
            start_lock = asyncio.Lock()
            self._start_lock = start_lock

        async with start_lock:

            self._running = False

            task = getattr(self, "_qbit_task", None)

            if task is None:
                self.logger.debug(
                    "[QbitDialer] stop() - no Qbit task"
                )
                return True

            if not task.done():

                self.logger.info(
                    "[QbitDialer] Cancelling Qbit loop"
                )

                task.cancel()

                try:
                    await task

                except asyncio.CancelledError:
                    pass

                except Exception:
                    self.logger.exception(
                        "[QbitDialer] Error while stopping Qbit loop"
                    )

            self._qbit_task = None

            self.logger.info(
                "[QbitDialer] Async runtime OFFLINE"
            )

            return True
# =====================================================================

    # ==========================================================
    # QBIT LOOP RUNNER
    #
    # COMPATIBILITY / AUTHORITATIVE ENTRY POINT
    #
    # Qbit is the INPUT / STATE.
    #
    # QbitDialer is the COMMAND + CONTROL AUTHORITY.
    #
    # ComputeBrain processes the received Qbit.
    #
    # TransformerBrain converts the computed thought into
    # structured system intent / command information.
    #
    # QbitQueueLoop remains the SINGLE authoritative transport
    # and queue-processing runtime.
    #
    # IMPORTANT:
    #
    # _qbit_loop() is already the authoritative long-running
    # Dialer runtime.
    #
    # Therefore this runner MUST NOT:
    #
    #     - create Qbits
    #     - create QbitQueueLoop
    #     - consume queue_loop.queue directly
    #     - create worker threads
    #     - manufacture command work
    #     - process commands in a second loop
    #     - call _qbit_loop() repeatedly
    #     - recursively restart itself
    #
    # This method exists only as the controlled entry point into
    # the ONE authoritative _qbit_loop() runtime.
    #
    # Startup synchronization, command execution, Qbit processing,
    # queue transport, and lifecycle management belong to
    # _qbit_loop().
    #
    # ==========================================================

    async def _qbit_loop_runner(self):

        # ======================================================
        # RUNTIME IDENTITY
        # ======================================================

        self._qbit_runtime_state = "STARTING"

        self.logger.info(
            "[QbitDialer] Qbit runtime runner starting"
        )

        # ======================================================
        # RUNTIME INTERVAL
        #
        # Retained for compatibility with existing configuration.
        #
        # _qbit_loop() owns its actual processing intervals.
        # ======================================================

        try:

            interval = float(
                getattr(
                    self,
                    "qbit_runtime_interval",
                    0.100,
                )
            )

        except (
            TypeError,
            ValueError,
        ):

            interval = 0.100

        interval = max(
            0.100,
            interval,
        )

        self._qbit_runtime_interval = (
            interval
        )

        # ======================================================
        # HARD LIFECYCLE GATE
        #
        # Do not create another runtime if shutdown has already
        # been requested.
        # ======================================================

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self._qbit_runtime_state = (
                "STOPPED"
            )

            self.logger.info(
                "[QbitDialer] Qbit runtime runner "
                "not started | stopping requested"
            )

            return False

        shutdown_flag = getattr(
            self,
            "shutdown_flag",
            None,
        )

        try:

            if (
                shutdown_flag is not None
                and shutdown_flag.is_set()
            ):

                self._qbit_runtime_state = (
                    "STOPPED"
                )

                self.logger.info(
                    "[QbitDialer] Qbit runtime runner "
                    "not started | shutdown requested"
                )

                return False

        except Exception:

            pass

        # ======================================================
        # RUNTIME ADMISSION
        #
        # Do NOT reject the runner merely because the Qbit,
        # registry, or queue has not appeared yet.
        #
        # _qbit_loop() owns the startup state machine and waits:
        #
        #     WAITING_FOR_SYSTEM
        #     WAITING_FOR_REGISTRY
        #     WAITING_FOR_QBIT
        #     WAITING_FOR_QUEUE
        #     BIND_QBIT_DIALER
        #     WAITING_FOR_COMMAND_REGISTRY
        #     ONLINE
        #
        # ======================================================

        if not getattr(
            self,
            "_running",
            True,
        ):

            self._qbit_runtime_state = (
                "WAITING_FOR_RUNTIME"
            )

            self.logger.info(
                "[QbitDialer] Qbit runtime runner "
                "waiting for Dialer runtime admission"
            )

            while (
                not getattr(
                    self,
                    "_running",
                    False,
                )
            ):

                if getattr(
                    self,
                    "_stopping",
                    False,
                ):

                    self._qbit_runtime_state = (
                        "STOPPED"
                    )

                    return False

                shutdown_flag = getattr(
                    self,
                    "shutdown_flag",
                    None,
                )

                try:

                    if (
                        shutdown_flag is not None
                        and shutdown_flag.is_set()
                    ):

                        self._qbit_runtime_state = (
                            "STOPPED"
                        )

                        return False

                except Exception:

                    pass

                await asyncio.sleep(
                    interval
                )

        # ======================================================
        # SINGLE AUTHORITATIVE RUNTIME
        #
        # IMPORTANT:
        #
        # _qbit_loop() owns the complete runtime.
        #
        # DO NOT:
        #
        #     await self._qbit_loop()
        #     await self._process_command_plane()
        #
        # The second operation would never be reached during
        # normal operation because _qbit_loop() owns its own
        # persistent processing loop.
        #
        # There is exactly ONE invocation.
        # ======================================================

        self._qbit_runtime_state = (
            "RUNNING"
        )

        self._qbit_running = True

        cycle_started = (
            asyncio.get_running_loop().time()
        )

        try:

            self.logger.info(
                "[QbitDialer] Entering authoritative "
                "Qbit runtime"
            )

            # ==================================================
            # SINGLE AUTHORITATIVE ENTRY
            #
            # _qbit_loop() owns:
            #
            #     system-state wait
            #     registry wait
            #     Qbit wait
            #     queue wait
            #     Dialer binding
            #     command-registry wait
            #     ONLINE transition
            #     command processing
            #     Qbit measurement
            #     Qbit transport
            #     runtime health
            #     shutdown
            #
            # ==================================================

            result = await self._qbit_loop()

            self._qbit_last_result = result

        except asyncio.CancelledError:

            self._qbit_runtime_state = (
                "CANCELLED"
            )

            self.logger.info(
                "[QbitDialer] Qbit runtime runner "
                "cancellation requested"
            )

            raise

        except Exception as exc:

            self._qbit_runtime_state = (
                "FAILED"
            )

            self._qbit_last_error = str(
                exc
            )

            self.logger.exception(
                "[QbitDialer] Authoritative Qbit runtime "
                "failed | error=%s: %s",
                type(exc).__name__,
                exc,
            )

            return False

        finally:

            cycle_time = (
                asyncio.get_running_loop().time()
                - cycle_started
            )

            self._qbit_last_cycle_time = (
                cycle_time
            )

            # --------------------------------------------------
            # _qbit_loop() owns _qbit_running as well.
            #
            # Keep this synchronized without creating another
            # runtime owner.
            # --------------------------------------------------

            self._qbit_running = False

            # --------------------------------------------------
            # Determine the genuine termination state.
            # --------------------------------------------------

            if getattr(
                self,
                "_stopping",
                False,
            ):

                self._qbit_runtime_state = (
                    "STOPPED"
                )

            else:

                shutdown_flag = getattr(
                    self,
                    "shutdown_flag",
                    None,
                )

                try:

                    shutdown_requested = (
                        shutdown_flag is not None
                        and shutdown_flag.is_set()
                    )

                except Exception:

                    shutdown_requested = False

                if shutdown_requested:

                    self._qbit_runtime_state = (
                        "STOPPED"
                    )

                elif (
                    getattr(
                        self,
                        "_qbit_runtime_state",
                        None,
                    )
                    != "FAILED"
                ):

                    self._qbit_runtime_state = (
                        "WAITING"
                    )

            self.logger.info(
                "[QbitDialer] Qbit runtime runner "
                "exited | state=%s",
                getattr(
                    self,
                    "_qbit_runtime_state",
                    "UNKNOWN",
                ),
            )

        return True


# ========================================================================
    # ==========================================================
    # QBIT TELEMETRY EMISSION GATE
    #
    # PURPOSE:
    #
    # Decide when the current Qbit + system state should be
    # emitted for observation, planning, learning, and routing.
    #
    # Pipeline:
    #
    #     Qbit
    #       â†“
    #     metadata / identity
    #       â†“
    #     system + module health
    #       â†“
    #     ComputeBrain result
    #       â†“
    #     TransformerBrain result
    #       â†“
    #     command / planning state
    #       â†“
    #     QBIT_STATE telemetry
    #
    # IMPORTANT:
    #
    # This method is ONLY an emission gate.
    #
    # It does NOT:
    #
    #     - create a Qbit
    #     - process a Qbit
    #     - execute a command
    #     - start a loop
    #     - start a module
    #     - create a task
    #     - mutate system health
    #
    # QbitDialer remains the command/control authority.
    # QbitQueueLoop remains the single Qbit runtime.
    # ==========================================================

    def _should_emit_qbit_telemetry(
        self,
        now=None,
    ):

        # ======================================================
        # TIME
        # ======================================================

        if now is None:

            now = time.monotonic()

        # ------------------------------------------------------
        # Numeric safety
        # ------------------------------------------------------

        try:

            now = float(now)

        except (
            TypeError,
            ValueError,
        ):

            now = time.monotonic()

        # ======================================================
        # LIFECYCLE
        # ======================================================

        if getattr(
            self,
            "_stopping",
            False,
        ):

            return False

        # ------------------------------------------------------
        # Do not emit before initialization.
        # ------------------------------------------------------

        if not getattr(
            self,
            "_initialized",
            False,
        ):

            return False

        # ======================================================
        # EMISSION INTERVAL
        # ======================================================

        try:

            interval = float(
                getattr(
                    self,
                    "qbit_emit_interval",
                    0.50,
                )
            )

        except (
            TypeError,
            ValueError,
        ):

            interval = 0.50

        interval = max(
            0.05,
            interval,
        )

        last_emit = getattr(
            self,
            "_last_qbit_emit",
            0.0,
        )

        try:

            last_emit = float(
                last_emit
            )

        except (
            TypeError,
            ValueError,
        ):

            last_emit = 0.0

        # ======================================================
        # NORMAL TELEMETRY RATE LIMIT
        # ======================================================

        elapsed = (
            now - last_emit
        )

        if elapsed < interval:

            # --------------------------------------------------
            # Preserve a pending state change so an important
            # state transition can be emitted on the next
            # authorized cycle.
            # --------------------------------------------------

            self._qbit_telemetry_pending = True

            return False

        # ======================================================
        # QBIT IDENTITY CHECK
        #
        # A telemetry packet without Qbit identity cannot be
        # reliably routed through the cognitive system.
        # ======================================================

        qbit = getattr(
            self,
            "last_qbit",
            None,
        )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        qbit_id = None

        if isinstance(
            qbit,
            dict,
        ):

            qbit_id = (
                qbit.get("qbit_id")
                or qbit.get("id")
                or qbit.get("QBIT_ID")
            )

        elif qbit is not None:

            qbit_id = (
                getattr(
                    qbit,
                    "qbit_id",
                    None,
                )
                or getattr(
                    qbit,
                    "id",
                    None,
                )
            )

        # ------------------------------------------------------
        # If a Qbit exists but has no explicit ID, retain the
        # telemetry gate. The state emitter can report the
        # missing identity rather than inventing a Qbit.
        # ------------------------------------------------------

        self._qbit_identity_valid = (
            qbit is not None
            and qbit_id is not None
        )

        # ======================================================
        # STATE / METADATA CHANGE DETECTION
        # ======================================================

        state = getattr(
            self,
            "qbit_state",
            None,
        )

        if state is None:

            if isinstance(
                qbit,
                dict,
            ):

                state = qbit.get(
                    "state"
                )

            else:

                state = getattr(
                    qbit,
                    "state",
                    None,
                )

        metadata = getattr(
            self,
            "qbit_metadata",
            None,
        )

        if metadata is None:

            metadata = {}

        if not isinstance(
            metadata,
            dict,
        ):

            metadata = {
                "value": metadata,
            }

        # ======================================================
        # SYSTEM HEALTH FLAGS
        # ======================================================

        system_health = getattr(
            self,
            "system_health",
            None,
        )

        if system_health is None:

            system_health = getattr(
                self,
                "health_monitor",
                None,
            )

        system_health_flag = getattr(
            self,
            "health_flag",
            None,
        )

        if system_health_flag is None:

            system_health_flag = getattr(
                self,
                "system_health_flag",
                None,
            )

        # ======================================================
        # MODULE HEALTH
        # ======================================================

        module_health = getattr(
            self,
            "module_health",
            {},
        )

        if not isinstance(
            module_health,
            dict,
        ):

            module_health = {}

        # ------------------------------------------------------
        # Count unhealthy modules for planning visibility.
        # ------------------------------------------------------

        unhealthy_modules = []

        for module_name, health in module_health.items():

            healthy = None

            if isinstance(
                health,
                dict,
            ):

                healthy = health.get(
                    "healthy",
                    health.get(
                        "ready",
                        health.get(
                            "operational",
                            None,
                        ),
                    ),
                )

            else:

                healthy = health

            if healthy is False:

                unhealthy_modules.append(
                    str(module_name)
                )

        # ======================================================
        # COMPUTE BRAIN
        # ======================================================

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        compute_thought = None

        if compute_brain is not None:

            compute_thought = getattr(
                compute_brain,
                "last_thought",
                None,
            )

        if compute_thought is None:

            compute_thought = getattr(
                self,
                "last_thought",
                None,
            )

        # ======================================================
        # TRANSFORMER BRAIN
        # ======================================================

        transformer_brain = getattr(
            self,
            "transformer_brain",
            None,
        )

        transformer_thought = None

        if transformer_brain is not None:

            transformer_thought = getattr(
                transformer_brain,
                "last_thought",
                None,
            )

        # ======================================================
        # COMMAND / PLANNING STATE
        # ======================================================

        command = (
            getattr(
                self,
                "current_command",
                None,
            )
            or getattr(
                self,
                "active_command",
                None,
            )
            or getattr(
                self,
                "_last_qbit_command",
                None,
            )
        )

        planning = bool(
            getattr(
                self,
                "planning",
                False,
            )
        )

        brain_go = bool(
            getattr(
                self,
                "brain_go",
                False,
            )
        )

        limp = bool(
            getattr(
                self,
                "limp_mode",
                getattr(
                    self,
                    "limp",
                    False,
                ),
            )
        )

        # ======================================================
        # BUILD ROUTING / PLANNING SIGNATURE
        #
        # This lets us detect meaningful changes without
        # comparing entire mutable thought packets.
        # ======================================================

        signature = (

            str(qbit_id),

            repr(state),

            repr(metadata),

            str(system_health_flag),

            tuple(
                sorted(
                    unhealthy_modules
                )
            ),

            str(command),

            planning,

            brain_go,

            limp,

            id(compute_thought)
            if compute_thought is not None
            else None,

            id(transformer_thought)
            if transformer_thought is not None
            else None,
        )

        previous_signature = getattr(
            self,
            "_last_qbit_telemetry_signature",
            None,
        )

        state_changed = (
            signature
            != previous_signature
        )

        # ======================================================
        # IMPORTANT STATE TRANSITION
        #
        # State/health/command changes are more important than
        # ordinary telemetry timing.
        #
        # Do not suppress them merely because the normal
        # telemetry interval has not elapsed.
        # ======================================================

        if (
            not state_changed
            and elapsed < interval
        ):

            self._qbit_telemetry_pending = True

            return False

        # ======================================================
        # COMMIT EMISSION
        # ======================================================

        self._last_qbit_emit = now

        self._last_qbit_telemetry_signature = (
            signature
        )

        self._qbit_telemetry_pending = False

        self._qbit_telemetry_count = (
            getattr(
                self,
                "_qbit_telemetry_count",
                0,
            )
            + 1
        )

        # ======================================================
        # PLANNING FLAGS
        #
        # These are observations for the planning stage.
        # They do not execute anything.
        # ======================================================

        self._qbit_planning_state = {

            "qbit_present": (
                qbit is not None
            ),

            "qbit_identity_valid": (
                self._qbit_identity_valid
            ),

            "state_present": (
                state is not None
            ),

            "system_health_flag": (
                system_health_flag
            ),

            "unhealthy_modules": (
                unhealthy_modules
            ),

            "planning": planning,

            "brain_go": brain_go,

            "limp": limp,

            "command": command,

            "compute_ready": (
                compute_thought is not None
            ),

            "transformer_ready": (
                transformer_thought is not None
            ),

            "state_changed": (
                state_changed
            ),
        }

        # ======================================================
        # RETURN
        # ======================================================

        return True

# =======================================================================

    @staticmethod
    def generate_qbit_state():
        import random
        import math
        a = complex(random.random(), random.random())
        b = complex(random.random(), random.random())
        norm = math.sqrt(abs(a)**2 + abs(b)**2) or 1.0
        return a / norm, b / norm

    # ==========================================================
    # LEGACY THREAD LOOP
    #
    # COMPATIBILITY ENTRY POINT ONLY
    #
    # QbitDialer is the Qbit COMMAND / CONTROL AUTHORITY.
    #
    # QbitQueueLoop is the SINGLE authoritative Qbit runtime.
    #
    # IMPORTANT:
    #
    # This method NEVER creates a worker thread.
    # This method NEVER creates a second Qbit loop.
    #
    # Core modules being ONLINE must NOT prevent the remaining
    # SEED system from completing boot.
    #
    # Boot ownership remains with the main system runtime.
    #
    # ==========================================================

    async def start_thread_loop(self):

        # ------------------------------------------------------
        # Legacy thread execution is intentionally disabled.
        #
        # Older callers may still invoke this method, therefore
        # keep the entry point alive as a compatibility adapter.
        # ------------------------------------------------------

        self.logger.debug(
            "[QbitDialer] Legacy thread loop request received | "
            "redirecting to authoritative asyncio runtime"
        )

        # ------------------------------------------------------
        # Shutdown gate
        # ------------------------------------------------------

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self.logger.warning(
                "[QbitDialer] Legacy thread loop rejected | "
                "shutdown in progress"
            )

            return False

        # ------------------------------------------------------
        # Authoritative Qbit runtime
        #
        # QbitQueueLoop / _qbit_task owns actual processing.
        # Never create another executor here.
        # ------------------------------------------------------

        qbit_task = getattr(
            self,
            "_qbit_task",
            None,
        )

        if qbit_task is not None:

            try:

                if not qbit_task.done():

                    self.logger.debug(
                        "[QbitDialer] Legacy thread loop suppressed | "
                        "authoritative Qbit runtime already active"
                    )

                    return False

            except Exception:

                pass

        # ------------------------------------------------------
        # Locate the authoritative queue loop.
        # ------------------------------------------------------

        queue_loop = getattr(
            self,
            "qbit_queue_loop",
            None,
        )

        if queue_loop is None:

            queue_loop = getattr(
                self,
                "queue_loop",
                None,
            )

        # ------------------------------------------------------
        # If the queue loop is already active, nothing else
        # needs to be started.
        # ------------------------------------------------------

        if queue_loop is not None:

            running = getattr(
                queue_loop,
                "running",
                None,
            )

            if running is None:

                running = getattr(
                    queue_loop,
                    "_running",
                    False,
                )

            if bool(
                running
            ):

                self.logger.debug(
                    "[QbitDialer] Legacy thread loop suppressed | "
                    "QbitQueueLoop already owns execution"
                )

                return False

        # ------------------------------------------------------
        # Do NOT start the queue loop here.
        #
        # Boot/runtime orchestration owns startup order.
        #
        # This prevents a core module from independently
        # starting a competing runtime while the system is
        # still completing boot.
        # ------------------------------------------------------

        self.logger.info(
            "[QbitDialer] Legacy thread loop disabled | "
            "authoritative Qbit runtime remains boot-managed"
        )

        return False


    # ==========================================================
    # LEGACY THREAD RUNNER
    #
    # HARD DISABLED
    #
    # Retained only so older code cannot accidentally fail with
    # AttributeError if it still references the method.
    # ==========================================================

    def _thread_loop_runner(self):

        self.logger.debug(
            "[QbitDialer] Legacy thread runner suppressed | "
            "QbitQueueLoop owns Qbit execution"
        )

        return False


    # ==========================================================
    # LEGACY THREAD STOP
    #
    # COMPATIBILITY ONLY
    #
    # This does NOT stop the authoritative Qbit runtime.
    # QbitQueueLoop / system lifecycle owns actual shutdown.
    # ==========================================================

    def stop_thread_loop(self):

        with self._lock:

            self._thread_running = False

            self._thread = None

        self.logger.debug(
            "[QbitDialer] Legacy thread stop acknowledged | "
            "authoritative Qbit runtime untouched"
        )

        return True
    # ==========================================================
    # MONITOR / RECOVERY
    #
    # Authority:
    #   Monitor       = observes
    #   Qbit          = evaluates
    #   QbitDialer    = commands / execution authority
    #   Queue         = execution transport
    #
    # IMPORTANT:
    #   No time.sleep() inside async code.
    #   No direct module execution from recovery.
    # ==========================================================

    async def enter_limp_mode(self, reason: str):

        if getattr(self, "shutdown_flag", None):
            if self.shutdown_flag.is_set():
                return False

        already_limp = getattr(
            self,
            "limp_mode",
            False,
        )

        self.limp_mode = True
        self.limp_reason = str(reason)
        self.limp_attempts = getattr(
            self,
            "limp_attempts",
            0,
        ) + 1

        if not already_limp:

            self.logger.warning(
                "[QbitDialer] LIMP MODE ENGAGED | "
                "reason=%s | attempt=%d",
                self.limp_reason,
                self.limp_attempts,
            )

            # Tell the command plane.
            try:
                await self._submit_health_qbit_command(
                    "THROTTLE",
                    {
                        "reason": self.limp_reason,
                        "factor": 0.25,
                        "mode": "LIMP",
                    },
                    priority=1,
                )
            except Exception:
                self.logger.debug(
                    "[QbitDialer] Limp command submission failed",
                    exc_info=True,
                )

        return True


    # ==========================================================
    # SYSTEM MONITOR
    # ==========================================================

    async def _monitor(self):

        self.logger.info(
            "[QbitDialer] Monitor loop ONLINE"
        )

        monitor_interval = max(
            0.25,
            float(
                getattr(
                    self,
                    "monitor_interval",
                    1.0,
                )
            ),
        )

        last_state = None

        while not self.shutdown_flag.is_set():

            try:

                # --------------------------------------------------
                # Permission cleanup
                # --------------------------------------------------

                try:
                    DelegatedPermissionSystem.cleanup_expired()
                except Exception:
                    self.logger.debug(
                        "[QbitDialer] Permission cleanup failed",
                        exc_info=True,
                    )

                # --------------------------------------------------
                # Resource measurements
                # --------------------------------------------------

                cpu = psutil.cpu_percent(
                    interval=None
                )

                mem = psutil.virtual_memory().percent

                self.confidence["cpu"] = float(cpu)
                self.confidence["memory"] = float(mem)

                # --------------------------------------------------
                # Determine resource condition
                # --------------------------------------------------

                overloaded = (
                    cpu > CPU_LIMIT_PERCENT
                    or
                    mem > MEM_LIMIT_PERCENT
                )

                previous_limp = getattr(
                    self,
                    "limp_mode",
                    False,
                )

                if overloaded:

                    reason_parts = []

                    if cpu > CPU_LIMIT_PERCENT:
                        reason_parts.append(
                            f"CPU={cpu:.1f}%"
                        )

                    if mem > MEM_LIMIT_PERCENT:
                        reason_parts.append(
                            f"MEM={mem:.1f}%"
                        )

                    reason = (
                        "resource pressure | "
                        + ", ".join(reason_parts)
                    )

                    if not previous_limp:

                        await self.enter_limp_mode(
                            reason
                        )

                else:

                    # Do not immediately force recovery.
                    # _auto_recovery owns recovery decisions.

                    if (
                        previous_limp
                        and not getattr(
                            self,
                            "_recovery_pending",
                            False,
                        )
                    ):
                        self._recovery_pending = True

                # --------------------------------------------------
                # State-change telemetry only
                # --------------------------------------------------

                current_state = (
                    "LIMP"
                    if self.limp_mode
                    else "NORMAL"
                )

                if current_state != last_state:

                    last_state = current_state

                    self.logger.info(
                        "[QbitDialer] Resource state | "
                        "state=%s | CPU=%.1f%% | MEM=%.1f%%",
                        current_state,
                        cpu,
                        mem,
                    )

                    await self._emit_safe(
                        "QBIT_RESOURCE_STATE",
                        {
                            "state": current_state,
                            "cpu": cpu,
                            "memory": mem,
                            "limp_mode": self.limp_mode,
                        },
                    )

                await asyncio.sleep(
                    monitor_interval
                )

            except asyncio.CancelledError:
                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Monitor loop error | "
                    "%s: %s",
                    type(exc).__name__,
                    exc,
                )

                await asyncio.sleep(
                    monitor_interval
                )

        self.logger.info(
            "[QbitDialer] Monitor loop STOPPED"
        )


    # ==========================================================
    # ADAPTIVE RECOVERY
    # ==========================================================

    async def _adaptive_recovery(self):

        if getattr(
            self,
            "_recovery_running",
            False,
        ):
            return {
                "status": "already_running"
            }

        self._recovery_running = True

        try:

            attempts = 0

            max_attempts = max(
                1,
                int(
                    getattr(
                        self,
                        "max_limp_attempts",
                        MAX_LIMP_ATTEMPTS,
                    )
                ),
            )

            # --------------------------------------------------
            # ORACLE BINDING
            #
            # Oracle is advisory/governance only.
            # QbitDialer remains command authority.
            # --------------------------------------------------

            oracle = getattr(
                self,
                "oracle",
                None,
            )

            if oracle is not None:

                self.logger.info(
                    "[QbitDialer] Adaptive recovery | "
                    "Oracle advisory layer attached | oracle=%s",
                    type(oracle).__name__,
                )

            while (
                self.limp_mode
                and attempts < max_attempts
                and not self.shutdown_flag.is_set()
            ):

                attempts += 1

                # --------------------------------------------------
                # Collect recovery signals
                # --------------------------------------------------

                red_modules = sum(
                    1
                    for module in self.module_health.values()
                    if module.get("state") in {
                        "DISABLED",
                        "OFFLINE",
                        "CRITICAL",
                    }
                )

                yellow_modules = sum(
                    1
                    for module in self.module_health.values()
                    if module.get("state") in {
                        "DEGRADED",
                        "RECOVERING",
                    }
                )

                cpu = float(
                    psutil.cpu_percent(
                        interval=None
                    )
                )

                memory = float(
                    psutil.virtual_memory().percent
                )

                signals = {
                    "CPU": cpu,
                    "MEMORY": memory,

                    "AUDIO": float(
                        self.confidence.get(
                            "audio",
                            0.0,
                        )
                    ),

                    "MODEM": float(
                        self.confidence.get(
                            "modem",
                            0.0,
                        )
                    ),

                    "RED_MODULES": red_modules,
                    "YELLOW_MODULES": yellow_modules,

                    "LIMP_ATTEMPTS": attempts,
                }

                # --------------------------------------------------
                # Ask system calculation brain
                # --------------------------------------------------

                recovery_score = await (
                    self.system_calc.compute(
                        signals
                    )
                )

                try:
                    recovery_score = float(
                        recovery_score
                    )
                except (
                    TypeError,
                    ValueError,
                ):
                    recovery_score = 0.0

                recovery_score = max(
                    0.0,
                    min(
                        recovery_score,
                        1.0,
                    ),
                )

                self.confidence[
                    "recovery"
                ] = recovery_score

                # --------------------------------------------------
                # ORACLE RECOVERY OBSERVATION
                #
                # Oracle observes/advises.
                # QbitDialer retains command authority.
                # --------------------------------------------------

                oracle_assessment = None

                if oracle is not None:

                    oracle_payload = {
                        "source": "QbitDialer",
                        "subsystem": "adaptive_recovery",
                        "attempt": attempts,
                        "max_attempts": max_attempts,
                        "signals": dict(
                            signals
                        ),
                        "recovery_score": recovery_score,
                        "limp_mode": bool(
                            self.limp_mode
                        ),
                        "limp_reason": getattr(
                            self,
                            "limp_reason",
                            None,
                        ),
                        "command_authority": (
                            "QbitDialer"
                        ),
                    }

                    try:

                        oracle_method = getattr(
                            oracle,
                            "assess_recovery",
                            None,
                        )

                        if callable(
                            oracle_method
                        ):

                            oracle_assessment = (
                                oracle_method(
                                    oracle_payload
                                )
                            )

                            if inspect.isawaitable(
                                oracle_assessment
                            ):
                                oracle_assessment = (
                                    await oracle_assessment
                                )

                        else:

                            oracle_method = getattr(
                                oracle,
                                "observe",
                                None,
                            )

                            if callable(
                                oracle_method
                            ):

                                oracle_assessment = (
                                    oracle_method(
                                        "QBIT_RECOVERY",
                                        oracle_payload,
                                    )
                                )

                                if inspect.isawaitable(
                                    oracle_assessment
                                ):
                                    oracle_assessment = (
                                        await oracle_assessment
                                    )

                    except Exception as exc:

                        self.logger.warning(
                            "[QbitDialer] Oracle recovery "
                            "assessment failed | error=%s",
                            exc,
                        )

                        oracle_assessment = {
                            "status": "oracle_error",
                            "error": str(exc),
                        }

                # --------------------------------------------------
                # Normalize Oracle advisory result
                # --------------------------------------------------

                if oracle_assessment is None:

                    oracle_assessment = {
                        "status": "not_available"
                    }

                elif not isinstance(
                    oracle_assessment,
                    dict,
                ):

                    oracle_assessment = {
                        "status": "advisory",
                        "value": oracle_assessment,
                    }

                self.logger.info(
                    "[QbitDialer] Recovery assessment | "
                    "score=%.2f | CPU=%.1f%% | MEM=%.1f%% | "
                    "red=%d | degraded=%d | attempt=%d/%d | "
                    "oracle=%s",
                    recovery_score,
                    cpu,
                    memory,
                    red_modules,
                    yellow_modules,
                    attempts,
                    max_attempts,
                    oracle_assessment.get(
                        "status",
                        "unknown",
                    ),
                )

                # --------------------------------------------------
                # Successful recovery
                # --------------------------------------------------

                if (
                    recovery_score >= 0.50
                    and cpu <= CPU_LIMIT_PERCENT
                    and memory <= MEM_LIMIT_PERCENT
                ):

                    result = await (
                        self._submit_health_qbit_command(
                            "RESUME",
                            {
                                "reason": (
                                    "adaptive_recovery"
                                ),
                                "score": recovery_score,
                                "cpu": cpu,
                                "memory": memory,
                                "oracle": (
                                    oracle_assessment
                                ),
                            },
                            priority=2,
                        )
                    )

                    self.limp_mode = False
                    self.limp_reason = None
                    self.limp_attempts = 0
                    self._recovery_pending = False

                    self.logger.info(
                        "[QbitDialer] Adaptive recovery "
                        "succeeded | score=%.2f | oracle=%s",
                        recovery_score,
                        oracle_assessment.get(
                            "status",
                            "unknown",
                        ),
                    )

                    await self._emit_safe(
                        "QBIT_RECOVERY_COMPLETE",
                        {
                            "score": recovery_score,
                            "cpu": cpu,
                            "memory": memory,
                            "result": result,
                            "oracle": (
                                oracle_assessment
                            ),
                        },
                    )

                    return {
                        "status": "recovered",
                        "score": recovery_score,
                        "attempts": attempts,
                        "oracle": oracle_assessment,
                    }

                # --------------------------------------------------
                # Recovery not yet safe
                # --------------------------------------------------

                if recovery_score >= 0.20:

                    await self._submit_health_qbit_command(
                        "THROTTLE",
                        {
                            "reason": (
                                "recovery_in_progress"
                            ),
                            "factor": 0.50,
                            "score": recovery_score,
                            "oracle": (
                                oracle_assessment
                            ),
                        },
                        priority=2,
                    )

                else:

                    await self._submit_health_qbit_command(
                        "PAUSE_BACKGROUND",
                        {
                            "reason": (
                                "recovery_score_low"
                            ),
                            "score": recovery_score,
                            "oracle": (
                                oracle_assessment
                            ),
                        },
                        priority=1,
                    )

                await asyncio.sleep(
                    0.50
                )

            # ------------------------------------------------------
            # Recovery exhausted
            # ------------------------------------------------------

            if self.limp_mode:

                self.logger.warning(
                    "[QbitDialer] Recovery attempts exhausted | "
                    "remaining in LIMP MODE"
                )

                await self._submit_health_qbit_command(
                    "PAUSE_BACKGROUND",
                    {
                        "reason": (
                            "recovery_attempts_exhausted"
                        ),
                        "attempts": attempts,
                        "oracle": (
                            oracle_assessment
                            if "oracle_assessment" in locals()
                            else {
                                "status": "not_available"
                            }
                        ),
                    },
                    priority=1,
                )

                return {
                    "status": "limp",
                    "attempts": attempts,
                    "oracle": (
                        oracle_assessment
                        if "oracle_assessment" in locals()
                        else {
                            "status": "not_available"
                        }
                    ),
                }

            return {
                "status": "not_required",
                "attempts": attempts,
                "oracle": (
                    oracle_assessment
                    if "oracle_assessment" in locals()
                    else {
                        "status": "not_available"
                    }
                ),
            }

        finally:

            self._recovery_running = False


    # ==========================================================
    # AUTOMATIC RECOVERY SUPERVISOR
    #
    # AUTHORITATIVE RECOVERY COORDINATOR
    #
    # Qbit + Brain + Health + Module Recovery
    #
    # Pipeline:
    #
    #     Qbit
    #       â†“
    #     ComputeBrain
    #       â†“
    #     TransformerBrain
    #       â†“
    #     QbitDialer
    #       â†“
    #     HealthMonitor
    #       â†“
    #     Recovery Authorization
    #       â†“
    #     Module Recovery
    #       â†“
    #     Health Recheck
    #
    # IMPORTANT:
    #
    # This supervisor does NOT create another Qbit runtime.
    #
    # It does NOT:
    #     - create Qbits
    #     - create QueueLoops
    #     - create competing processing loops
    #     - bypass HealthMonitor
    #     - recover modules that are explicitly protected
    #
    # Recovery is permitted only when the system determines
    # that the affected component is recoverable.
    # ==========================================================

    async def _auto_recovery(self):

        self.logger.info(
            "[QbitDialer] Auto-recovery supervisor ONLINE"
        )

        interval = max(
            0.50,
            float(
                getattr(
                    self,
                    "recovery_interval",
                    1.0,
                )
            ),
        )

        while not self.shutdown_flag.is_set():

            try:

                # ==================================================
                # 1. SYSTEM LIFECYCLE GUARD
                # ==================================================

                if getattr(
                    self,
                    "_stopping",
                    False,
                ):

                    await asyncio.sleep(
                        interval
                    )

                    continue

                # ==================================================
                # 2. READ CURRENT HEALTH
                # ==================================================

                health_monitor = getattr(
                    self,
                    "health_monitor",
                    None,
                )

                system_healthy = True

                if health_monitor is not None:

                    try:

                        operational = getattr(
                            health_monitor,
                            "is_operational",
                            None,
                        )

                        if callable(
                            operational
                        ):

                            result = operational(
                                getattr(
                                    self,
                                    "name",
                                    "QbitDialer",
                                )
                            )

                            if inspect.isawaitable(
                                result
                            ):

                                result = await result

                            system_healthy = bool(
                                result
                            )

                    except Exception:

                        self.logger.debug(
                            "[QbitDialer] "
                            "HealthMonitor query failed",
                            exc_info=True,
                        )

                # ==================================================
                # 3. DETERMINE WHETHER RECOVERY IS NEEDED
                # ==================================================

                recovery_needed = bool(
                    getattr(
                        self,
                        "limp_mode",
                        False,
                    )
                    or getattr(
                        self,
                        "_recovery_pending",
                        False,
                    )
                    or not system_healthy
                )

                if not recovery_needed:

                    await asyncio.sleep(
                        interval
                    )

                    continue

                self.logger.warning(
                    "[QbitDialer] Recovery evaluation | "
                    "system_healthy=%s limp=%s pending=%s",
                    system_healthy,
                    getattr(
                        self,
                        "limp_mode",
                        False,
                    ),
                    getattr(
                        self,
                        "_recovery_pending",
                        False,
                    ),
                )

                # ==================================================
                # 4. CAPTURE CURRENT QBIT / BRAIN STATE
                # ==================================================

                qbit = getattr(
                    self,
                    "last_qbit",
                    None,
                )

                thought = (
                    getattr(
                        self,
                        "last_transformed_thought",
                        None,
                    )
                    or getattr(
                        self,
                        "last_thought",
                        None,
                    )
                )

                # --------------------------------------------------
                # Preserve cognitive lineage during recovery.
                # --------------------------------------------------

                qbit_id = None

                if qbit is not None:

                    if isinstance(
                        qbit,
                        dict,
                    ):

                        qbit_id = (
                            qbit.get(
                                "qbit_id"
                            )
                            or qbit.get(
                                "id"
                            )
                        )

                    else:

                        qbit_id = (
                            getattr(
                                qbit,
                                "qbit_id",
                                None,
                            )
                            or getattr(
                                qbit,
                                "id",
                                None,
                            )
                        )

                self.logger.debug(
                    "[QbitDialer] Recovery context | "
                    "qbit_id=%s | thought=%s",
                    qbit_id,
                    bool(
                        isinstance(
                            thought,
                            dict,
                        )
                    ),
                )

                # ==================================================
                # 5. RECOVER COGNITIVE PIPELINE FIRST
                #
                # Brain dependencies are recovered before general
                # modules because Qbit processing depends on them.
                # ==================================================

                cognitive_targets = (

                    (
                        "ComputeBrain",
                        getattr(
                            self,
                            "compute_brain",
                            None,
                        ),
                    ),

                    (
                        "TransformerBrain",
                        getattr(
                            self,
                            "transformer_brain",
                            None,
                        ),
                    ),

                )

                for module_name, module in cognitive_targets:

                    if module is None:

                        continue

                    allowed = (
                        await self._recovery_allowed(
                            module_name
                        )
                    )

                    if not allowed:

                        self.logger.debug(
                            "[QbitDialer] Recovery denied | "
                            "module=%s",
                            module_name,
                        )

                        continue

                    recovered = (
                        await self._recover_module(
                            module_name,
                            module,
                        )
                    )

                    if recovered:

                        self.logger.info(
                            "[QbitDialer] Brain recovered | "
                            "module=%s | qbit_id=%s",
                            module_name,
                            qbit_id,
                        )

                # ==================================================
                # 6. RECOVER QBIT-SPECIFIC COMPONENTS
                # ==================================================

                qbit_targets = (

                    (
                        "QbitDialer",
                        self,
                    ),

                    (
                        "QbitQueueLoop",
                        getattr(
                            self,
                            "qbit_queue_loop",
                            None,
                        ),
                    ),

                    (
                        "QbitKernelBus",
                        getattr(
                            self,
                            "qbit_kernel_bus",
                            None,
                        ),
                    ),

                )

                for module_name, module in qbit_targets:

                    if module is None:

                        continue

                    # ----------------------------------------------
                    # Never blindly restart this supervisor itself.
                    # ----------------------------------------------

                    if module is self:

                        continue

                    allowed = (
                        await self._recovery_allowed(
                            module_name
                        )
                    )

                    if not allowed:

                        continue

                    await self._recover_module(
                        module_name,
                        module,
                    )

                # ==================================================
                # 7. GENERAL MODULE RECOVERY
                #
                # Uses registered system modules where available.
                # ==================================================

                modules = getattr(
                    self,
                    "modules",
                    None,
                )

                if isinstance(
                    modules,
                    dict,
                ):

                    for module_name, module in list(
                        modules.items()
                    ):

                        if module is None:

                            continue

                        # ------------------------------------------
                        # Cognitive/Qbit components were already
                        # handled above.
                        # ------------------------------------------

                        if module_name in {
                            "ComputeBrain",
                            "TransformerBrain",
                            "QbitDialer",
                            "QbitQueueLoop",
                            "QbitKernelBus",
                        }:

                            continue

                        allowed = (
                            await self._recovery_allowed(
                                module_name
                            )
                        )

                        if not allowed:

                            continue

                        await self._recover_module(
                            module_name,
                            module,
                        )

                # ==================================================
                # 8. CONTROLLED ADAPTIVE RECOVERY
                # ==================================================

                if (
                    getattr(
                        self,
                        "limp_mode",
                        False,
                    )
                    or getattr(
                        self,
                        "_recovery_pending",
                        False,
                    )
                ):

                    adaptive = getattr(
                        self,
                        "_adaptive_recovery",
                        None,
                    )

                    if callable(
                        adaptive
                    ):

                        result = adaptive()

                        if inspect.isawaitable(
                            result
                        ):

                            await result

                # ==================================================
                # 9. RECHECK HEALTH
                # ==================================================

                post_health = True

                if health_monitor is not None:

                    try:

                        operational = getattr(
                            health_monitor,
                            "is_operational",
                            None,
                        )

                        if callable(
                            operational
                        ):

                            result = operational(
                                getattr(
                                    self,
                                    "name",
                                    "QbitDialer",
                                )
                            )

                            if inspect.isawaitable(
                                result
                            ):

                                result = await result

                            post_health = bool(
                                result
                            )

                    except Exception:

                        post_health = False

                # ==================================================
                # 10. RESOLVE RECOVERY STATE
                # ==================================================

                if post_health:

                    self._recovery_pending = False

                    # Only leave limp mode when recovery actually
                    # succeeded and the system is operational.

                    if getattr(
                        self,
                        "limp_mode",
                        False,
                    ):

                        self.limp_mode = False

                    self.logger.info(
                        "[QbitDialer] Recovery successful | "
                        "health=GREEN | qbit_id=%s",
                        qbit_id,
                    )

                else:

                    self._recovery_pending = True

                    self.logger.warning(
                        "[QbitDialer] Recovery incomplete | "
                        "health=DEGRADED | qbit_id=%s",
                        qbit_id,
                    )

                # ==================================================
                # 11. NEXT RECOVERY WINDOW
                # ==================================================

                await asyncio.sleep(
                    interval
                )

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                self.logger.exception(
                    "[QbitDialer] Auto-recovery error | "
                    "%s: %s",
                    type(exc).__name__,
                    exc,
                )

                await asyncio.sleep(
                    interval
                )

        self.logger.info(
            "[QbitDialer] Auto-recovery supervisor STOPPED"
        )
    # ==========================================================
    # SAFE EVENT EMISSION
    #
    # AUTHORITATIVE OUTPUT BOUNDARY
    #
    # Pipeline:
    #
    #     Qbit
    #       â†“
    #     Decoder
    #       â†“
    #     ComputeBrain
    #       â†“
    #     TransformerBrain
    #       â†“
    #     ThoughtPacket
    #       â†“
    #     _emit_safe()
    #       â†“
    #     EventBus
    #       â†“
    #     SEED SYSTEM
    #
    # IMPORTANT:
    #
    # This is OUTPUT.
    #
    # Every meaningful output is given an identity and
    # lineage so SEED can:
    #
    #     - correlate output with its originating Qbit
    #     - route it by source/channel/track
    #     - evaluate what happened after the output
    #     - build learning history
    #     - measure success/failure
    #     - improve future decisions
    #
    # This method does NOT:
    #
    #     - create Qbits
    #     - process Qbits
    #     - run ComputeBrain
    #     - run TransformerBrain
    #     - execute commands
    #     - create queues
    #     - create runtime tasks
    #
    # It only constructs and transports an authoritative
    # outbound event envelope.
    # ==========================================================

    async def _emit_safe(
        self,
        event_name,
        payload=None,
    ):

        # ======================================================
        # EVENT BUS
        # ======================================================

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:

            self.logger.debug(
                "[QbitDialer] Output suppressed | "
                "EventBus unavailable | event=%s",
                event_name,
            )

            return False

        # ======================================================
        # NORMALIZE EVENT NAME
        # ======================================================

        event_name = str(
            event_name or "QBIT_OUTPUT"
        ).strip()

        if not event_name:

            event_name = "QBIT_OUTPUT"

        # ======================================================
        # NORMALIZE PAYLOAD
        # ======================================================

        if payload is None:

            payload_data = {}

        elif isinstance(
            payload,
            dict,
        ):

            payload_data = dict(
                payload
            )

        else:

            payload_data = {
                "value": payload
            }

        # ======================================================
        # RESOLVE ORIGINATING QBIT
        #
        # The output belongs to the Qbit that generated it.
        #
        # Prefer explicit payload Qbit, then the Dialer's latest
        # Qbit.
        # ======================================================

        qbit = payload_data.get(
            "qbit",
            None,
        )

        if qbit is None:

            qbit = getattr(
                self,
                "last_qbit",
                None,
            )

        # ======================================================
        # QBIT ID
        #
        # Never invent a new Qbit ID if an actual Qbit already
        # carries one.
        # ======================================================

        qbit_id = (
            payload_data.get(
                "qbit_id"
            )
            or payload_data.get(
                "id"
            )
        )

        if qbit_id is None and qbit is not None:

            if isinstance(
                qbit,
                dict,
            ):

                qbit_id = (
                    qbit.get("qbit_id")
                    or qbit.get("id")
                )

            else:

                qbit_id = (
                    getattr(
                        qbit,
                        "qbit_id",
                        None,
                    )
                    or getattr(
                        qbit,
                        "id",
                        None,
                    )
                )

        # ------------------------------------------------------
        # Last-resort output identity.
        #
        # This is an OUTPUT ID, not a replacement Qbit ID.
        # ------------------------------------------------------

        output_id = (
            payload_data.get(
                "output_id"
            )
            or payload_data.get(
                "event_id"
            )
            or f"QBIT-OUT-{uuid4()}"
        )

        # ======================================================
        # ROUTING IDENTITY
        # ======================================================

        identity = payload_data.get(
            "identity",
            {},
        )

        if not isinstance(
            identity,
            dict,
        ):

            identity = {}

        source = (
            payload_data.get(
                "source"
            )
            or identity.get(
                "source"
            )
            or getattr(
                self,
                "name",
                "QbitDialer",
            )
        )

        channel = (
            payload_data.get(
                "channel"
            )
            or identity.get(
                "channel"
            )
            or "QBIT"
        )

        track = (
            payload_data.get(
                "track"
            )
            or identity.get(
                "track"
            )
        )

        # ======================================================
        # THOUGHT / COGNITIVE LINEAGE
        # ======================================================

        thought_packet = (
            payload_data.get(
                "thought_packet"
            )
            or payload_data.get(
                "thought"
            )
            or getattr(
                self,
                "last_transformed_thought",
                None,
            )
            or getattr(
                self,
                "last_thought",
                None,
            )
        )

        if not isinstance(
            thought_packet,
            dict,
        ):

            thought_packet = None

        # ======================================================
        # PROCESSING LINEAGE
        #
        # Allows SEED to know HOW this output was produced.
        # ======================================================

        lineage = payload_data.get(
            "lineage",
            {},
        )

        if not isinstance(
            lineage,
            dict,
        ):

            lineage = {}

        lineage = {
            **lineage,
            "qbit_id": qbit_id,
            "output_id": output_id,
            "source": source,
            "channel": channel,
            "track": track,
            "dialer": getattr(
                self,
                "name",
                "QbitDialer",
            ),
            "compute_stage": (
                "ComputeBrain"
                if getattr(
                    self,
                    "compute_brain",
                    None,
                ) is not None
                else None
            ),
            "transform_stage": (
                "TransformerBrain"
                if getattr(
                    self,
                    "transformer_brain",
                    None,
                ) is not None
                else None
            ),
        }

        # ======================================================
        # HEALTH / AUTHORITY STATE
        # ======================================================

        health = payload_data.get(
            "health",
            None,
        )

        if not isinstance(
            health,
            dict,
        ):

            health = {}

        health_flag = payload_data.get(
            "health_flag",
            None,
        )

        if health_flag is None:

            health_flag = (
                "GREEN"
                if getattr(
                    self,
                    "operational",
                    False,
                )
                and not getattr(
                    self,
                    "limp_mode",
                    False,
                )
                else "DEGRADED"
            )

        # ======================================================
        # LEARNING METADATA
        #
        # This does NOT claim that the output was successful.
        #
        # It gives downstream learning systems an identity they
        # can later correlate with feedback, results, reward,
        # failure, correction, or adaptation.
        # ======================================================

        learning = payload_data.get(
            "learning",
            {},
        )

        if not isinstance(
            learning,
            dict,
        ):

            learning = {}

        learning = {
            **learning,

            "learnable": True,

            "qbit_id": qbit_id,

            "output_id": output_id,

            "track": track,

            "source": source,

            "channel": channel,

            "feedback_pending": True,

            "outcome": learning.get(
                "outcome",
                None,
            ),

            "reward": learning.get(
                "reward",
                None,
            ),

            "correction": learning.get(
                "correction",
                None,
            ),
        }

        # ======================================================
        # AUTHORITATIVE OUTPUT ENVELOPE
        # ======================================================

        output = {

            "type": "QbitOutput",

            "version": "2.0.0",

            # ----------------------------------------------
            # Output identity
            # ----------------------------------------------

            "output_id": output_id,

            "event": event_name,

            "timestamp": time.time(),

            # ----------------------------------------------
            # Originating Qbit
            # ----------------------------------------------

            "qbit_id": qbit_id,

            "qbit": qbit,

            # ----------------------------------------------
            # Routing
            # ----------------------------------------------

            "source": source,

            "channel": channel,

            "track": track,

            "identity": {
                "source": source,
                "channel": channel,
                "track": track,
                "qbit_id": qbit_id,
                "output_id": output_id,
            },

            # ----------------------------------------------
            # Cognitive lineage
            # ----------------------------------------------

            "lineage": lineage,

            "thought_packet": thought_packet,

            # ----------------------------------------------
            # System health
            # ----------------------------------------------

            "health_flag": health_flag,

            "health": health,

            # ----------------------------------------------
            # Learning
            # ----------------------------------------------

            "learning": learning,

            # ----------------------------------------------
            # Actual output payload
            # ----------------------------------------------

            "payload": payload_data,

            # ----------------------------------------------
            # Authority
            # ----------------------------------------------

            "authority": "QbitDialer",

            "stage": "OUTPUT",

        }

        # ======================================================
        # LOCAL OUTPUT CALLBACKS
        # ======================================================

        callbacks = list(
            getattr(
                self,
                "output_callbacks",
                [],
            )
            or []
        )

        for callback in callbacks:

            if not callable(
                callback
            ):

                continue

            try:

                result = callback(
                    output
                )

                if inspect.isawaitable(
                    result
                ):

                    await result

            except asyncio.CancelledError:

                raise

            except Exception:

                self.logger.debug(
                    "[QbitDialer] "
                    "Output callback failed | "
                    "event=%s",
                    event_name,
                    exc_info=True,
                )

        # ======================================================
        # EVENTBUS TRANSPORT
        #
        # Prefer emit(), then publish().
        # ======================================================

        emit = getattr(
            event_bus,
            "emit",
            None,
        )

        publish = getattr(
            event_bus,
            "publish",
            None,
        )

        try:

            result = None

            if callable(
                emit
            ):

                result = emit(
                    event_name,
                    output,
                )

            elif callable(
                publish
            ):

                result = publish(
                    event_name,
                    payload=output,
                )

            else:

                self.logger.warning(
                    "[QbitDialer] Output failed | "
                    "EventBus has no emit()/publish() | "
                    "event=%s",
                    event_name,
                )

                return False

            if inspect.isawaitable(
                result
            ):

                result = await result

            # --------------------------------------------------
            # Record the actual emitted output locally.
            # --------------------------------------------------

            self.last_output = output

            self._output_count = (
                getattr(
                    self,
                    "_output_count",
                    0,
                ) + 1
            )

            self.logger.debug(
                "[QbitDialer] OUTPUT | "
                "event=%s | qbit_id=%s | "
                "output_id=%s | track=%s",
                event_name,
                qbit_id,
                output_id,
                track,
            )

            return output

        except asyncio.CancelledError:

            raise

        except Exception:

            self._output_errors = (
                getattr(
                    self,
                    "_output_errors",
                    0,
                ) + 1
            )

            self.logger.exception(
                "[QbitDialer] Output transport failed | "
                "event=%s | qbit_id=%s | "
                "output_id=%s",
                event_name,
                qbit_id,
                output_id,
            )

            return False
    # ==========================================================
    # BRAIN PIPELINE
    #
    # QbitDialer authoritative cognitive path:
    #
    #     Qbit
    #       â†“
    #     Decoder
    #       â†“
    #     ComputeBrain
    #       â†“
    #     Math Engine
    #       â†“
    #     ThoughtPacket
    #       â†“
    #     TransformerBrain
    #       â†“
    #     transformed ThoughtPacket
    #       â†“
    #     QbitDialer planning
    #
    # IMPORTANT:
    #
    # QbitDialer owns the authority.
    #
    # ComputeBrain does the computation.
    # TransformerBrain does the transformation/reasoning stage.
    # QbitDialer decides whether the result can drive execution.
    #
    # This method DOES NOT create:
    #     - Qbits
    #     - queues
    #     - loops
    #     - runtime tasks
    # ==========================================================

    async def _process_brain_pipeline(self, qbit=None):

        # ------------------------------------------------------
        # Resolve Qbit.
        # ------------------------------------------------------

        if qbit is None:
            qbit = getattr(
                self,
                "last_qbit",
                None,
            )

        if qbit is None:
            qbit = getattr(
                self,
                "qbit",
                None,
            )

        if qbit is None:
            self.logger.debug(
                "[QbitDialer] Brain pipeline skipped | "
                "no Qbit available"
            )
            return None

        # ------------------------------------------------------
        # Store authoritative input.
        # ------------------------------------------------------

        self.last_qbit = qbit

        # ------------------------------------------------------
        # COMPUTE BRAIN
        #
        # Prefer the explicitly connected ComputeBrain.
        # ------------------------------------------------------

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if compute_brain is None:
            compute_brain = getattr(
                self,
                "compute",
                None,
            )

        if compute_brain is None:
            self.logger.debug(
                "[QbitDialer] Brain pipeline | "
                "ComputeBrain not connected"
            )
            return None

        # ------------------------------------------------------
        # Process Qbit through ComputeBrain.
        #
        # ComputeBrain is responsible for:
        #
        #     decode/extract
        #     normalize
        #     mathematical state analysis
        #     probability
        #     magnitude
        #     resonance
        #     classification
        #     ThoughtPacket creation
        # ------------------------------------------------------

        try:

            processor = getattr(
                compute_brain,
                "process",
                None,
            )

            if not callable(processor):

                processor = getattr(
                    compute_brain,
                    "receive_qbit",
                    None,
                )

            if not callable(processor):

                self.logger.warning(
                    "[QbitDialer] ComputeBrain has no "
                    "process()/receive_qbit()"
                )

                return None

            thought = processor(qbit)

            if inspect.isawaitable(thought):
                thought = await thought

        except asyncio.CancelledError:
            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] ComputeBrain processing failed"
            )

            return None

        if thought is None:
            return None

        # ------------------------------------------------------
        # Preserve ComputeBrain result.
        # ------------------------------------------------------

        self.last_compute_thought = thought

        # ------------------------------------------------------
        # TRANSFORMER BRAIN
        #
        # The transformer receives the COMPUTED thought.
        #
        # It does not receive an unprocessed Qbit as its
        # primary cognitive input.
        # ------------------------------------------------------

        transformer = getattr(
            self,
            "transformer_brain",
            None,
        )

        if transformer is None:
            transformer = getattr(
                self,
                "transformer",
                None,
            )

        # Transformer is optional during staged boot.
        if transformer is None:

            self.last_thought = thought

            return thought

        # ------------------------------------------------------
        # Resolve transformer entry point.
        # ------------------------------------------------------

        transformer_method = getattr(
            transformer,
            "process",
            None,
        )

        if not callable(transformer_method):

            transformer_method = getattr(
                transformer,
                "transform",
                None,
            )

        if not callable(transformer_method):

            transformer_method = getattr(
                transformer,
                "receive_thought",
                None,
            )

        if not callable(transformer_method):

            self.logger.warning(
                "[QbitDialer] TransformerBrain has no "
                "process()/transform()/receive_thought()"
            )

            self.last_thought = thought

            return thought

        # ------------------------------------------------------
        # Transform the ComputeBrain ThoughtPacket.
        # ------------------------------------------------------

        try:

            transformed = transformer_method(
                thought
            )

            if inspect.isawaitable(transformed):
                transformed = await transformed

        except asyncio.CancelledError:
            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] TransformerBrain processing failed"
            )

            # Preserve the valid ComputeBrain result.
            self.last_thought = thought

            return thought

        # ------------------------------------------------------
        # Transformer produced no replacement.
        # Preserve the computed thought.
        # ------------------------------------------------------

        if transformed is None:

            self.last_thought = thought

            return thought

        # ------------------------------------------------------
        # Authoritative cognitive result.
        # ------------------------------------------------------

        self.last_transformed_thought = transformed
        self.last_thought = transformed

        return transformed


    # ==========================================================
    # BRAIN STATE SNAPSHOT
    #
    # AUTHORITATIVE COGNITIVE STATE READ
    #
    # Planning reads the latest completed cognitive result.
    #
    # Pipeline:
    #
    #     Qbit
    #       â†“
    #     ComputeBrain
    #       â†“
    #     ThoughtPacket
    #       â†“
    #     TransformerBrain
    #       â†“
    #     Transformed ThoughtPacket
    #       â†“
    #     QbitDialer
    #
    # IMPORTANT:
    #
    # This method ONLY reads state.
    #
    # It does NOT:
    #     - create a Qbit
    #     - decode a Qbit
    #     - run ComputeBrain
    #     - run TransformerBrain
    #     - execute commands
    #     - publish events
    #     - start tasks
    #     - mutate brain state
    #
    # The returned structure is a SNAPSHOT.
    # ==========================================================

    def _get_brain_state(self):

        # ------------------------------------------------------
        # Latest authoritative ThoughtPacket.
        #
        # Prefer the transformed result because that is the
        # latest cognitive stage.
        # ------------------------------------------------------

        thought = getattr(
            self,
            "last_transformed_thought",
            None,
        )

        if not isinstance(
            thought,
            dict,
        ):

            thought = getattr(
                self,
                "last_thought",
                None,
            )

        if not isinstance(
            thought,
            dict,
        ):

            thought = getattr(
                self,
                "last_compute_thought",
                None,
            )

        if not isinstance(
            thought,
            dict,
        ):

            return {
                "available": False,
                "stage": "NO_THOUGHT",
                "qbit": None,
                "source": None,
                "channel": None,
                "track": None,
                "request": None,
                "information": None,
                "classification": None,
                "confidence": 0.0,
            }

        # ------------------------------------------------------
        # Qbit reference.
        #
        # Do not manufacture an ID here.
        # Preserve the actual Qbit identity when available.
        # ------------------------------------------------------

        qbit = thought.get(
            "qbit",
            getattr(
                self,
                "last_qbit",
                None,
            ),
        )

        # ------------------------------------------------------
        # Extract routing identity.
        # ------------------------------------------------------

        identity = thought.get(
            "identity",
            {},
        )

        if not isinstance(
            identity,
            dict,
        ):

            identity = {}

        source = (
            thought.get("source")
            or identity.get("source")
            or "QBIT"
        )

        channel = (
            thought.get("channel")
            or identity.get("channel")
            or "QBIT"
        )

        track = (
            thought.get("track")
            or identity.get("track")
        )

        # ------------------------------------------------------
        # Request / information identification.
        #
        # Different brain versions may use different field
        # names, so normalize them here.
        # ------------------------------------------------------

        request = (
            thought.get("request")
            or thought.get("command")
            or thought.get("action")
            or thought.get("intent")
            or None
        )

        information = (
            thought.get("information")
            or thought.get("info")
            or thought.get("payload")
            or thought.get("data")
            or None
        )

        classification = (
            thought.get("classification")
            or thought.get("label")
            or thought.get("type")
            or None
        )

        # ------------------------------------------------------
        # Confidence.
        # ------------------------------------------------------

        confidence = thought.get(
            "confidence",
            0.0,
        )

        try:

            if inspect.isawaitable(
                confidence
            ):

                # This is a synchronous snapshot method.
                # Never leak a coroutine into state.
                confidence = 0.0

            confidence = float(
                confidence
            )

            if not math.isfinite(
                confidence
            ):

                confidence = 0.0

        except (
            TypeError,
            ValueError,
        ):

            confidence = 0.0

        confidence = max(
            0.0,
            min(
                1.0,
                confidence,
            ),
        )

        # ------------------------------------------------------
        # ComputeBrain state.
        # ------------------------------------------------------

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        if compute_brain is None:

            compute_brain = getattr(
                self,
                "compute",
                None,
            )

        compute_confidence = 0.0

        if compute_brain is not None:

            try:

                compute_confidence = float(
                    getattr(
                        compute_brain,
                        "confidence",
                        0.0,
                    )
                )

                if not math.isfinite(
                    compute_confidence
                ):

                    compute_confidence = 0.0

            except (
                TypeError,
                ValueError,
            ):

                compute_confidence = 0.0

        compute_confidence = max(
            0.0,
            min(
                1.0,
                compute_confidence,
            ),
        )

        # ------------------------------------------------------
        # TransformerBrain state.
        # ------------------------------------------------------

        transformer = getattr(
            self,
            "transformer_brain",
            None,
        )

        if transformer is None:

            transformer = getattr(
                self,
                "transformer",
                None,
            )

        transformer_confidence = 0.0

        if transformer is not None:

            try:

                transformer_confidence = float(
                    getattr(
                        transformer,
                        "confidence",
                        0.0,
                    )
                )

                if not math.isfinite(
                    transformer_confidence
                ):

                    transformer_confidence = 0.0

            except (
                TypeError,
                ValueError,
            ):

                transformer_confidence = 0.0

        transformer_confidence = max(
            0.0,
            min(
                1.0,
                transformer_confidence,
            ),
        )

        # ------------------------------------------------------
        # Qbit mathematical state.
        #
        # Prefer the ThoughtPacket's processed state.
        # ------------------------------------------------------

        state = thought.get(
            "state",
            None,
        )

        probability = thought.get(
            "probability",
            None,
        )

        magnitude = thought.get(
            "magnitude",
            None,
        )

        resonance = thought.get(
            "resonance",
            None,
        )

        # ------------------------------------------------------
        # System health / authority state.
        # ------------------------------------------------------

        health = getattr(
            self,
            "health",
            None,
        )

        if isinstance(
            health,
            dict,
        ):

            health_snapshot = dict(
                health
            )

        else:

            health_snapshot = {}

        health_monitor = getattr(
            self,
            "health_monitor",
            None,
        )

        # ------------------------------------------------------
        # Preserve existing module health without calling
        # arbitrary health methods from this read-only method.
        # ------------------------------------------------------

        module_health = getattr(
            self,
            "module_health",
            None,
        )

        if isinstance(
            module_health,
            dict,
        ):

            module_health_snapshot = dict(
                module_health
            )

        else:

            module_health_snapshot = {}

        # ------------------------------------------------------
        # Final immutable-by-convention cognitive snapshot.
        #
        # Nested dicts are copied where practical so planning
        # cannot accidentally mutate the live ThoughtPacket.
        # ------------------------------------------------------

        snapshot = {

            "available": True,

            "stage": thought.get(
                "stage",
                "THOUGHT_AVAILABLE",
            ),

            "type": thought.get(
                "type",
                "ThoughtPacket",
            ),

            # ----------------------------------------------
            # Qbit identity / routing
            # ----------------------------------------------

            "qbit": qbit,

            "source": source,

            "channel": channel,

            "track": track,

            # ----------------------------------------------
            # What the Qbit represents
            # ----------------------------------------------

            "request": request,

            "information": information,

            "classification": classification,

            "label": thought.get(
                "label",
                None,
            ),

            # ----------------------------------------------
            # Mathematical result
            # ----------------------------------------------

            "state": (
                dict(state)
                if isinstance(
                    state,
                    dict,
                )
                else state
            ),

            "probability": (
                dict(probability)
                if isinstance(
                    probability,
                    dict,
                )
                else probability
            ),

            "magnitude": magnitude,

            "resonance": resonance,

            # ----------------------------------------------
            # Cognitive confidence
            # ----------------------------------------------

            "confidence": confidence,

            "compute_confidence": (
                compute_confidence
            ),

            "transformer_confidence": (
                transformer_confidence
            ),

            # ----------------------------------------------
            # System state
            # ----------------------------------------------

            "health": health_snapshot,

            "module_health": (
                module_health_snapshot
            ),

            "planning": bool(
                getattr(
                    self,
                    "planning",
                    False,
                )
            ),

            "brain_go": bool(
                getattr(
                    self,
                    "brain_go",
                    False,
                )
            ),

            "limp_mode": bool(
                getattr(
                    self,
                    "limp_mode",
                    False,
                )
            ),

            "operational": bool(
                getattr(
                    self,
                    "operational",
                    False,
                )
            ),

            # ----------------------------------------------
            # Brain availability
            # ----------------------------------------------

            "compute_brain_connected": (
                compute_brain is not None
            ),

            "transformer_brain_connected": (
                transformer is not None
            ),

            "health_monitor_connected": (
                health_monitor is not None
            ),

            # ----------------------------------------------
            # Original cognitive packet
            #
            # Keep a reference for compatibility, but do not
            # replace the normalized fields above.
            # ----------------------------------------------

            "thought_packet": thought,
        }

        return snapshot

    # ==========================================================
    # PLANNING
    #
    # Planning consumes:
    #
    #     system confidence
    #     ComputeBrain confidence
    #     TransformerBrain confidence
    #     reasoning weight
    #     latest ThoughtPacket
    #
    # It does NOT directly execute commands.
    # ==========================================================

    async def _plan(self):

        try:

            # ==================================================
            # PROCESS NEW QBIT IF ONE IS AVAILABLE
            # ==================================================

            qbit = getattr(
                self,
                "last_qbit",
                None,
            )

            if qbit is not None:

                # Only process when the Qbit has not already
                # produced the current cognitive result.
                #
                # The authoritative queue remains responsible
                # for delivering Qbits. This method only invokes
                # the connected brains on the received Qbit.

                try:

                    thought = await self._process_brain_pipeline(
                        qbit
                    )

                    if thought is not None:
                        self.last_thought = thought

                except asyncio.CancelledError:
                    raise

                except Exception:

                    self.logger.exception(
                        "[QbitDialer] Brain pipeline failed during planning"
                    )

            # ==================================================
            # CONFIDENCE
            # ==================================================

            confidence_values = []

            # --------------------------------------------------
            # Existing system confidence sources.
            # --------------------------------------------------

            confidence = getattr(
                self,
                "confidence",
                {},
            )

            if isinstance(
                confidence,
                dict,
            ):

                for value in confidence.values():

                    try:

                        if inspect.isawaitable(value):
                            value = await value

                        value = float(value)

                        if math.isfinite(value):
                            confidence_values.append(
                                max(
                                    0.0,
                                    min(
                                        1.0,
                                        value,
                                    ),
                                )
                            )

                    except (
                        TypeError,
                        ValueError,
                    ):

                        continue

            # ==================================================
            # COMPUTE BRAIN CONFIDENCE
            # ==================================================

            compute_brain = getattr(
                self,
                "compute_brain",
                None,
            )

            if compute_brain is None:
                compute_brain = getattr(
                    self,
                    "compute",
                    None,
                )

            if compute_brain is not None:

                try:

                    value = getattr(
                        compute_brain,
                        "confidence",
                        None,
                    )

                    if inspect.isawaitable(value):
                        value = await value

                    if value is not None:

                        value = float(value)

                        if math.isfinite(value):
                            confidence_values.append(
                                max(
                                    0.0,
                                    min(
                                        1.0,
                                        value,
                                    ),
                                )
                            )

                except (
                    TypeError,
                    ValueError,
                ):

                    pass

            # ==================================================
            # TRANSFORMER BRAIN CONFIDENCE
            # ==================================================

            transformer = getattr(
                self,
                "transformer_brain",
                None,
            )

            if transformer is None:
                transformer = getattr(
                    self,
                    "transformer",
                    None,
                )

            if transformer is not None:

                try:

                    value = getattr(
                        transformer,
                        "confidence",
                        None,
                    )

                    if inspect.isawaitable(value):
                        value = await value

                    if value is not None:

                        value = float(value)

                        if math.isfinite(value):
                            confidence_values.append(
                                max(
                                    0.0,
                                    min(
                                        1.0,
                                        value,
                                    ),
                                )
                            )

                except (
                    TypeError,
                    ValueError,
                ):

                    pass

            # ==================================================
            # THOUGHT PACKET CONFIDENCE
            # ==================================================

            thought = self._get_brain_state()

            if thought:

                try:

                    thought_confidence = float(
                        thought.get(
                            "confidence",
                            0.0,
                        )
                    )

                    if math.isfinite(
                        thought_confidence
                    ):

                        confidence_values.append(
                            max(
                                0.0,
                                min(
                                    1.0,
                                    thought_confidence,
                                ),
                            )
                        )

                except (
                    TypeError,
                    ValueError,
                ):

                    pass

            # ==================================================
            # AVERAGE CONFIDENCE
            # ==================================================

            avg_conf = (
                sum(confidence_values)
                /
                len(confidence_values)
                if confidence_values
                else 0.0
            )

            # ==================================================
            # REASONING WEIGHT
            # ==================================================

            reasoning_weight = 0.0

            try:

                provider = getattr(
                    self,
                    "get_reasoning_weight",
                    None,
                )

                if callable(provider):

                    reasoning_weight = provider()

                    if inspect.isawaitable(
                        reasoning_weight
                    ):

                        reasoning_weight = (
                            await reasoning_weight
                        )

                elif hasattr(
                    self,
                    "reasoning_weight",
                ):

                    reasoning_weight = getattr(
                        self,
                        "reasoning_weight",
                        0.0,
                    )

                    if inspect.isawaitable(
                        reasoning_weight
                    ):

                        reasoning_weight = (
                            await reasoning_weight
                        )

            except Exception:

                self.logger.exception(
                    "[QbitDialer] "
                    "Reasoning weight calculation failed"
                )

                reasoning_weight = 0.0

            # --------------------------------------------------
            # Numeric safety.
            # --------------------------------------------------

            try:

                reasoning_weight = float(
                    reasoning_weight
                )

                if not math.isfinite(
                    reasoning_weight
                ):

                    reasoning_weight = 0.0

            except (
                TypeError,
                ValueError,
            ):

                reasoning_weight = 0.0

            reasoning_weight = max(
                0.0,
                min(
                    1.0,
                    reasoning_weight,
                ),
            )

            # ==================================================
            # COMBINE COGNITIVE CONFIDENCE
            # ==================================================

            avg_conf = (
                avg_conf
                +
                reasoning_weight
            ) / 2.0

            avg_conf = max(
                0.0,
                min(
                    1.0,
                    avg_conf,
                ),
            )

            # ==================================================
            # PLANNING STATE
            # ==================================================

            if not isinstance(
                getattr(
                    self,
                    "confidence",
                    None,
                ),
                dict,
            ):

                self.confidence = {}

            self.confidence[
                "overall"
            ] = avg_conf

            self.confidence[
                "compute_brain"
            ] = (
                getattr(
                    compute_brain,
                    "confidence",
                    0.0,
                )
                if compute_brain is not None
                else 0.0
            )

            self.confidence[
                "transformer_brain"
            ] = (
                getattr(
                    transformer,
                    "confidence",
                    0.0,
                )
                if transformer is not None
                else 0.0
            )

            # --------------------------------------------------
            # Planning admission.
            # --------------------------------------------------

            self.planning = bool(
                avg_conf
                >
                getattr(
                    self,
                    "planning_threshold",
                    0.5,
                )
            )

            # --------------------------------------------------
            # Brain-go is subordinate to safety/lifecycle.
            # --------------------------------------------------

            if hasattr(
                self,
                "brain_go",
            ):

                self.brain_go = bool(
                    self.planning
                    and
                    not getattr(
                        self,
                        "limp_mode",
                        False,
                    )
                    and
                    not getattr(
                        self,
                        "_stopping",
                        False,
                    )
                )

            # ==================================================
            # LOG
            # ==================================================

            self.logger.debug(
                "[QbitDialer] PLAN | "
                "confidence=%.4f "
                "reasoning=%.4f "
                "planning=%s "
                "brain_go=%s "
                "thought=%s",
                avg_conf,
                reasoning_weight,
                self.planning,
                getattr(
                    self,
                    "brain_go",
                    False,
                ),
                (
                    thought.get(
                        "classification",
                        thought.get(
                            "type",
                            "NONE",
                        ),
                    )
                    if thought
                    else "NONE"
                ),
            )

            return avg_conf

        except asyncio.CancelledError:
            raise

        except Exception:

            self.logger.exception(
                "[QbitDialer] Planning stage failed"
            )

            self.planning = False

            if hasattr(
                self,
                "brain_go",
            ):

                self.brain_go = False

            return 0.0


    # ==========================================================
    # TICK
    #
    # TICK DOES NOT PROCESS RAW QBITS.
    #
    # The Qbit enters through the authoritative receive/queue
    # path. The brain pipeline produces the ThoughtPacket.
    # Tick only selects the current lifecycle/cognitive state.
    # ==========================================================

    async def _tick(self):

        # ------------------------------------------------------
        # Highest-priority safety state
        # ------------------------------------------------------

        if getattr(
            self,
            "limp_mode",
            False,
        ):

            return TICK_IDLE

        # ------------------------------------------------------
        # Shutdown
        # ------------------------------------------------------

        if getattr(
            self,
            "_stopping",
            False,
        ):

            return TICK_IDLE

        # ------------------------------------------------------
        # No work requested
        # ------------------------------------------------------

        if getattr(
            self,
            "idle",
            False,
        ):

            return TICK_IDLE

        # ------------------------------------------------------
        # Planning / cognition phase
        # ------------------------------------------------------

        if getattr(
            self,
            "planning",
            False,
        ):

            return TICK_PLAN

        # ------------------------------------------------------
        # Brain has a computed thought but planning has not
        # admitted execution.
        # ------------------------------------------------------

        thought = getattr(
            self,
            "last_thought",
            None,
        )

        if isinstance(
            thought,
            dict,
        ):

            stage = str(
                thought.get(
                    "stage",
                    "",
                )
            ).upper()

            if stage in {
                "COMPUTE_COMPLETE",
                "TRANSFORM_COMPLETE",
                "THOUGHT_COMPLETE",
            }:

                return TICK_PLAN

        # ------------------------------------------------------
        # Normal execution
        # ------------------------------------------------------

        return TICK_ACTIVE

    # ==========================================================
    # BRAIN MOTIVATION SUMMARY
    #
    # DIALER BRAIN INPUT AGGREGATION
    #
    # Qbit path:
    #
    #   Qbit
    #      â†“
    #   Decoder
    #      â†“
    #   normalized state
    #      â†“
    #   Math Engine
    #      â†“
    #   probability / magnitude / resonance
    #      â†“
    #   Dialer brain variables
    #      â†“
    #   motivation / drive / confidence
    #
    # IMPORTANT:
    #   This method does NOT create a Qbit.
    #   This method does NOT create a processing loop.
    #   This method does NOT execute commands.
    #
    # ==========================================================

    async def get_brain_motivation_summary(
        self,
        qbit=None,
    ):

        with self._lock:

            # --------------------------------------------------
            # EXISTING BRAIN CONFIDENCE
            # --------------------------------------------------

            confidences = []

            for brain in (
                getattr(
                    self,
                    "cpu",
                    None,
                ),
                getattr(
                    self,
                    "audio",
                    None,
                ),
                getattr(
                    self,
                    "modem",
                    None,
                ),
                getattr(
                    self,
                    "system_calc",
                    None,
                ),
            ):

                if brain is None:
                    continue

                try:

                    confidence = float(
                        getattr(
                            brain,
                            "confidence",
                            0.0,
                        )
                    )

                except (
                    TypeError,
                    ValueError,
                ):

                    confidence = 0.0

                confidences.append(
                    max(
                        0.0,
                        min(
                            1.0,
                            confidence,
                        ),
                    )
                )

            # --------------------------------------------------
            # QBIT â†’ DECODER â†’ MATH ENGINE
            #
            # This is the first new brain wire.
            # --------------------------------------------------

            qbit_signal = 0.0
            qbit_confidence = 0.0
            qbit_resonance = 0.0
            qbit_magnitude = 0.0
            qbit_probability = None

            active_qbit = qbit

            if active_qbit is None:

                active_qbit = getattr(
                    self,
                    "last_qbit",
                    None,
                )

            if active_qbit is None:

                dialer = getattr(
                    self,
                    "qbit_dialer",
                    None,
                )

                if dialer is None:
                    dialer = getattr(
                        self,
                        "dialer",
                        None,
                    )

                if dialer is not None:

                    active_qbit = getattr(
                        dialer,
                        "last_qbit",
                        None,
                    )

            # --------------------------------------------------
            # DECODER
            # --------------------------------------------------

            if active_qbit is not None:

                decoder = getattr(
                    self,
                    "decoder",
                    None,
                )

                if decoder is None:

                    dialer = getattr(
                        self,
                        "qbit_dialer",
                        None,
                    )

                    if dialer is None:
                        dialer = getattr(
                            self,
                            "dialer",
                            None,
                        )

                    if dialer is not None:

                        decoder = getattr(
                            dialer,
                            "decoder",
                            None,
                        )

                decoded_qbit = active_qbit

                if decoder is not None:

                    decode = getattr(
                        decoder,
                        "decode",
                        None,
                    )

                    if callable(
                        decode
                    ):

                        decoded_qbit = decode(
                            active_qbit
                        )

                # ------------------------------------------------
                # MATH ENGINE
                # ------------------------------------------------

                math_engine = getattr(
                    self,
                    "quantum_engine",
                    None,
                )

                if math_engine is None:

                    math_engine = getattr(
                        self,
                        "math_engine",
                        None,
                    )

                if math_engine is None:

                    dialer = getattr(
                        self,
                        "qbit_dialer",
                        None,
                    )

                    if dialer is None:
                        dialer = getattr(
                            self,
                            "dialer",
                            None,
                        )

                    if dialer is not None:

                        math_engine = getattr(
                            dialer,
                            "quantum_engine",
                            None,
                        )

                        if math_engine is None:

                            math_engine = getattr(
                                dialer,
                                "math_engine",
                                None,
                            )

                # ------------------------------------------------
                # Extract state for the math engine.
                #
                # Prefer ComputeBrain's normalized state if
                # already available.
                # ------------------------------------------------

                state = None

                compute_brain = getattr(
                    self,
                    "compute_brain",
                    None,
                )

                if compute_brain is not None:

                    state = getattr(
                        compute_brain,
                        "last_state",
                        None,
                    )

                if state is None:

                    if isinstance(
                        decoded_qbit,
                        dict,
                    ):

                        state = (
                            decoded_qbit.get(
                                "state"
                            )
                        )

                        if state is None:

                            alpha = decoded_qbit.get(
                                "alpha"
                            )

                            beta = decoded_qbit.get(
                                "beta"
                            )

                            if (
                                alpha is not None
                                or
                                beta is not None
                            ):

                                state = (
                                    alpha or 0.0,
                                    beta or 0.0,
                                )

                    else:

                        state = getattr(
                            decoded_qbit,
                            "state",
                            None,
                        )

                # ------------------------------------------------
                # Calculate only when a usable state and engine
                # exist.
                # ------------------------------------------------

                if (
                    state is not None
                    and
                    math_engine is not None
                ):

                    state_probability = getattr(
                        math_engine,
                        "state_probability",
                        None,
                    )

                    state_magnitude = getattr(
                        math_engine,
                        "state_magnitude",
                        None,
                    )

                    resonance = getattr(
                        math_engine,
                        "resonance",
                        None,
                    )

                    if callable(
                        state_probability
                    ):

                        qbit_probability = (
                            state_probability(
                                state
                            )
                        )

                    if callable(
                        state_magnitude
                    ):

                        qbit_magnitude = float(
                            state_magnitude(
                                state
                            )
                        )

                    if callable(
                        resonance
                    ):

                        qbit_resonance = float(
                            resonance(
                                state
                            )
                        )

                    # --------------------------------------------
                    # Convert mathematical signal into a bounded
                    # brain input.
                    # --------------------------------------------

                    if isinstance(
                        qbit_probability,
                        dict,
                    ):

                        alpha_probability = float(
                            qbit_probability.get(
                                "alpha_probability",
                                0.0,
                            )
                        )

                        beta_probability = float(
                            qbit_probability.get(
                                "beta_probability",
                                0.0,
                            )
                        )

                        qbit_signal = max(
                            alpha_probability,
                            beta_probability,
                        )

                    else:

                        qbit_signal = max(
                            0.0,
                            min(
                                1.0,
                                abs(
                                    float(
                                        qbit_magnitude
                                    )
                                ),
                            ),
                        )

                    qbit_confidence = max(
                        0.0,
                        min(
                            1.0,
                            abs(
                                float(
                                    qbit_resonance
                                )
                            ),
                        ),
                    )

            # --------------------------------------------------
            # ADD QBIT BRAIN SIGNAL
            # --------------------------------------------------

            if active_qbit is not None:

                confidences.append(
                    qbit_confidence
                )

            # --------------------------------------------------
            # GLOBAL BRAIN CONFIDENCE
            # --------------------------------------------------

            if confidences:

                avg_conf = (
                    sum(confidences)
                    /
                    len(confidences)
                )

            else:

                avg_conf = 0.0

            # --------------------------------------------------
            # QBIT-WEIGHTED DIALER SIGNAL
            #
            # Qbit becomes an input to the brain's drive model,
            # not a command.
            # --------------------------------------------------

            motivation = max(
                0.0,
                min(
                    1.0,
                    (
                        avg_conf * 0.70
                        +
                        qbit_signal * 0.30
                    ),
                ),
            )

            drive = max(
                0.0,
                min(
                    1.0,
                    (
                        avg_conf * 0.70
                        +
                        qbit_confidence * 0.30
                    ),
                ),
            )

            # --------------------------------------------------
            # STORE DIALER BRAIN VARIABLES
            # --------------------------------------------------

            self.brain_confidence = avg_conf
            self.brain_motivation = motivation
            self.brain_drive = drive

            self.qbit_signal = qbit_signal
            self.qbit_confidence = qbit_confidence
            self.qbit_magnitude = qbit_magnitude
            self.qbit_resonance = qbit_resonance
            self.qbit_probability = qbit_probability

            # --------------------------------------------------
            # RETURN BRAIN STATE
            # --------------------------------------------------

            return {
                "confidence": avg_conf,
                "motivation": motivation,
                "drive": drive,

                "qbit": {
                    "received": (
                        active_qbit is not None
                    ),
                    "signal": qbit_signal,
                    "confidence": qbit_confidence,
                    "magnitude": qbit_magnitude,
                    "resonance": qbit_resonance,
                    "probability": qbit_probability,
                },
            }

    # ==========================================================
    # QBIT STATE EMISSION
    #
    # AUTHORITATIVE QBIT STATE / ROUTING STATE
    #
    # This is NOT a generic telemetry frame.
    #
    # Purpose:
    #
    #     Identify the Qbit
    #     Identify where it came from
    #     Identify where it belongs
    #     Identify what it is carrying
    #     Attach system health
    #     Attach ComputeBrain cognition
    #     Attach TransformerBrain cognition
    #
    # Pipeline:
    #
    #     Qbit
    #       â†“
    #     Qbit identity
    #       â†“
    #     routing state
    #       â†“
    #     system health
    #       â†“
    #     ComputeBrain ThoughtPacket
    #       â†“
    #     TransformerBrain ThoughtPacket
    #       â†“
    #     QBIT_STATE
    #
    # IMPORTANT:
    #
    #     This method NEVER:
    #
    #       - creates a Qbit
    #       - creates QueueLoop
    #       - starts a loop
    #       - starts TrackSystem
    #       - starts Heartbeat
    #       - executes commands
    #
    #     It ONLY assembles and emits the current state.
    #
    # ==========================================================

    async def _emit_state(
        self,
        state=None,
    ):

        # ======================================================
        # HARD LIFECYCLE GUARD
        # ======================================================

        if not getattr(
            self,
            "_initialized",
            False,
        ):

            return False

        # ------------------------------------------------------
        # Shutdown guard
        # ------------------------------------------------------

        shutdown_flag = getattr(
            self,
            "shutdown_flag",
            None,
        )

        try:

            if (
                shutdown_flag is not None
                and shutdown_flag.is_set()
            ):

                return False

        except Exception:

            pass

        # ======================================================
        # EVENT BUS
        # ======================================================

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:

            return False

        # ======================================================
        # SUPPLIED STATE
        # ======================================================

        if state is None:

            supplied_state = {}

        elif isinstance(
            state,
            dict,
        ):

            supplied_state = dict(
                state
            )

        elif callable(state):

            state_name = getattr(
                state,
                "__name__",
                state.__class__.__name__,
            )

            supplied_state = {
                "state": str(
                    state_name
                ),
            }

        else:

            supplied_state = {
                "state": state,
            }

        # ======================================================
        # AUTHORITATIVE QBIT
        #
        # Prefer the current Qbit.
        # Do not manufacture one here.
        # ======================================================

        qbit = supplied_state.get(
            "qbit"
        )

        if qbit is None:

            qbit = getattr(
                self,
                "last_qbit",
                None,
            )

        if qbit is None:

            qbit = getattr(
                self,
                "qbit",
                None,
            )

        # ======================================================
        # QBIT IDENTITY
        #
        # Preserve the identity already assigned to the Qbit.
        #
        # A state emission must NOT create a new identity.
        # ======================================================

        qbit_id = None
        track_id = None
        source = None
        channel = None
        request = None
        information = None

        if qbit is not None:

            if isinstance(
                qbit,
                dict,
            ):

                qbit_id = (
                    qbit.get("id")
                    or qbit.get("qbit_id")
                    or qbit.get("qid")
                )

                track_id = (
                    qbit.get("track")
                    or qbit.get("track_id")
                    or qbit.get("track_context")
                )

                source = (
                    qbit.get("source")
                    or qbit.get("origin")
                    or qbit.get("source_id")
                )

                channel = (
                    qbit.get("channel")
                    or qbit.get("channel_id")
                    or qbit.get("channel_marker")
                )

                request = (
                    qbit.get("request")
                    or qbit.get("command")
                    or qbit.get("action")
                    or qbit.get("intent")
                )

                information = (
                    qbit.get("information")
                    or qbit.get("info")
                    or qbit.get("payload")
                    or qbit.get("data")
                )

            else:

                qbit_id = (
                    getattr(
                        qbit,
                        "id",
                        None,
                    )
                    or getattr(
                        qbit,
                        "qbit_id",
                        None,
                    )
                )

                track_id = (
                    getattr(
                        qbit,
                        "track",
                        None,
                    )
                    or getattr(
                        qbit,
                        "track_id",
                        None,
                    )
                )

                source = (
                    getattr(
                        qbit,
                        "source",
                        None,
                    )
                    or getattr(
                        qbit,
                        "origin",
                        None,
                    )
                )

                channel = (
                    getattr(
                        qbit,
                        "channel",
                        None,
                    )
                    or getattr(
                        qbit,
                        "channel_id",
                        None,
                    )
                )

                request = (
                    getattr(
                        qbit,
                        "request",
                        None,
                    )
                    or getattr(
                        qbit,
                        "command",
                        None,
                    )
                    or getattr(
                        qbit,
                        "action",
                        None,
                    )
                    or getattr(
                        qbit,
                        "intent",
                        None,
                    )
                )

                information = (
                    getattr(
                        qbit,
                        "information",
                        None,
                    )
                    or getattr(
                        qbit,
                        "info",
                        None,
                    )
                    or getattr(
                        qbit,
                        "payload",
                        None,
                    )
                    or getattr(
                        qbit,
                        "data",
                        None,
                    )
                )

        # ------------------------------------------------------
        # Fallback identity from supplied state.
        # ------------------------------------------------------

        qbit_id = (
            qbit_id
            or supplied_state.get(
                "qbit_id"
            )
            or supplied_state.get(
                "id"
            )
        )

        track_id = (
            track_id
            or supplied_state.get(
                "track"
            )
            or supplied_state.get(
                "track_id"
            )
        )

        source = (
            source
            or supplied_state.get(
                "source"
            )
            or "QbitDialer"
        )

        channel = (
            channel
            or supplied_state.get(
                "channel"
            )
            or "QBIT"
        )

        request = (
            request
            or supplied_state.get(
                "request"
            )
            or supplied_state.get(
                "intent"
            )
        )

        information = (
            information
            if information is not None
            else supplied_state.get(
                "information"
            )
        )

        # ======================================================
        # COMPUTE BRAIN THOUGHT
        #
        # Prefer the already-computed ThoughtPacket.
        #
        # Do NOT recompute the Qbit here.
        # ======================================================

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        compute_thought = None

        if compute_brain is not None:

            compute_thought = getattr(
                compute_brain,
                "last_thought",
                None,
            )

        if compute_thought is None:

            compute_thought = getattr(
                self,
                "last_thought",
                None,
            )

        # ======================================================
        # TRANSFORMER BRAIN THOUGHT
        # ======================================================

        transformer_brain = getattr(
            self,
            "transformer_brain",
            None,
        )

        if transformer_brain is None:

            transformer_brain = getattr(
                self,
                "transformer",
                None,
            )

        transformer_thought = None

        if transformer_brain is not None:

            transformer_thought = getattr(
                transformer_brain,
                "last_thought",
                None,
            )

            if transformer_thought is None:

                transformer_thought = getattr(
                    transformer_brain,
                    "last_packet",
                    None,
                )

        # ======================================================
        # SYSTEM HEALTH
        #
        # Health belongs in the state so routing/decision
        # layers know whether the source/system is operational.
        # ======================================================

        health_monitor = getattr(
            self,
            "health_monitor",
            None,
        )

        health_flag = getattr(
            self,
            "healthy",
            getattr(
                self,
                "operational",
                False,
            ),
        )

        health_data = {}

        if health_monitor is not None:

            try:

                # ----------------------------------------------
                # Prefer an existing health snapshot method.
                # ----------------------------------------------

                health_method = getattr(
                    health_monitor,
                    "get_state",
                    None,
                )

                if callable(
                    health_method
                ):

                    result = health_method()

                    if inspect.isawaitable(
                        result
                    ):

                        result = await result

                    if isinstance(
                        result,
                        dict,
                    ):

                        health_data = dict(
                            result
                        )

                # ----------------------------------------------
                # Compatibility health snapshot.
                # ----------------------------------------------

                if not health_data:

                    for key in (
                        "healthy",
                        "operational",
                        "ready",
                        "status",
                        "cpu",
                        "memory",
                        "modules",
                        "green_flags",
                    ):

                        value = getattr(
                            health_monitor,
                            key,
                            None,
                        )

                        if value is not None:

                            health_data[
                                key
                            ] = value

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                logger.debug(
                    "[QbitDialer] "
                    "Health snapshot unavailable: %s",
                    exc,
                )

        # ------------------------------------------------------
        # Health monitor may expose the authoritative flag.
        # ------------------------------------------------------

        if "healthy" in health_data:

            health_flag = bool(
                health_data[
                    "healthy"
                ]
            )

        elif "operational" in health_data:

            health_flag = bool(
                health_data[
                    "operational"
                ]
            )

        # ======================================================
        # DIALER BRAIN STATE
        # ======================================================

        motivation = getattr(
            self,
            "brain_motivation",
            0.0,
        )

        drive = getattr(
            self,
            "brain_drive",
            0.0,
        )

        brain_confidence = getattr(
            self,
            "brain_confidence",
            getattr(
                self,
                "confidence",
                0.0,
            ),
        )

        # ------------------------------------------------------
        # Numeric safety
        # ------------------------------------------------------

        try:

            motivation = float(
                motivation
            )

        except (
            TypeError,
            ValueError,
        ):

            motivation = 0.0

        try:

            drive = float(
                drive
            )

        except (
            TypeError,
            ValueError,
        ):

            drive = 0.0

        try:

            brain_confidence = float(
                brain_confidence
            )

        except (
            TypeError,
            ValueError,
        ):

            brain_confidence = 0.0

        # ======================================================
        # QBIT MATHEMATICAL STATE
        # ======================================================

        qbit_state = None

        if isinstance(
            qbit,
            dict,
        ):

            qbit_state = qbit.get(
                "state"
            )

        elif qbit is not None:

            qbit_state = getattr(
                qbit,
                "state",
                None,
            )

        if qbit_state is None:

            qbit_state = getattr(
                self,
                "qbit_state",
                None,
            )

        # ======================================================
        # BUILD AUTHORITATIVE QBIT STATE
        #
        # This is the routing/cognitive state object.
        # ======================================================

        frame = {

            "type": "QBIT_STATE",

            "version": "2.0.0",

            # --------------------------------------------------
            # Qbit identity
            # --------------------------------------------------

            "qbit_id": qbit_id,

            "track_id": track_id,

            "source": source,

            "channel": channel,

            # --------------------------------------------------
            # What the Qbit carries
            # --------------------------------------------------

            "request": request,

            "information": information,

            # --------------------------------------------------
            # Mathematical state
            # --------------------------------------------------

            "qbit_state": qbit_state,

            # --------------------------------------------------
            # System routing authority
            # --------------------------------------------------

            "authority": "QbitDialer",

            "module": (
                supplied_state.get(
                    "module"
                )
                or source
            ),

            "route": (
                supplied_state.get(
                    "route"
                )
                or channel
            ),

            # --------------------------------------------------
            # System health
            # --------------------------------------------------

            "health": {

                "flag": bool(
                    health_flag
                ),

                "data": health_data,

            },

            # --------------------------------------------------
            # Dialer brain state
            # --------------------------------------------------

            "brain": {

                "confidence": (
                    brain_confidence
                ),

                "motivation": (
                    motivation
                ),

                "drive": drive,

            },

            # --------------------------------------------------
            # Cognitive processing
            # --------------------------------------------------

            "compute_brain": (
                compute_thought
            ),

            "transformer_brain": (
                transformer_thought
            ),

            # --------------------------------------------------
            # Runtime state
            # --------------------------------------------------

            "planning": bool(
                getattr(
                    self,
                    "planning",
                    False,
                )
            ),

            "idle": bool(
                getattr(
                    self,
                    "idle",
                    True,
                )
            ),

            "brain_go": bool(
                getattr(
                    self,
                    "brain_go",
                    False,
                )
            ),

            "limp": bool(
                getattr(
                    self,
                    "limp_mode",
                    getattr(
                        self,
                        "limp",
                        False,
                    ),
                )
            ),

            "timestamp": time.time(),

        }

        # ======================================================
        # PRESERVE EXPLICIT CALLER STATE
        #
        # Caller values may add routing/context fields.
        # Core Qbit identity remains authoritative.
        # ======================================================

        for key, value in supplied_state.items():

            if key in (
                "qbit",
                "qbit_id",
                "track_id",
                "source",
                "channel",
                "authority",
                "health",
                "compute_brain",
                "transformer_brain",
            ):

                continue

            frame[key] = value

        # ======================================================
        # TRACK OVERLAY
        #
        # Existing TrackSystem only.
        # Never create one here.
        # ======================================================

        try:

            lock = getattr(
                self,
                "_lock",
                None,
            )

            if lock is not None:

                with lock:

                    self._update_track_overlay(
                        frame
                    )

            else:

                self._update_track_overlay(
                    frame
                )

        except Exception as exc:

            logger.debug(
                "[QbitDialer] "
                "Track overlay update skipped: %s",
                exc,
            )

        # ======================================================
        # LOCAL CALLBACKS
        # ======================================================

        callbacks = list(
            getattr(
                self,
                "qbit_callbacks",
                [],
            )
            or []
        )

        for callback in callbacks:

            if not callable(
                callback
            ):

                continue

            try:

                result = callback(
                    frame
                )

                if inspect.isawaitable(
                    result
                ):

                    await result

            except asyncio.CancelledError:

                raise

            except Exception as exc:

                logger.error(
                    "[QbitDialer] "
                    "State callback error: %s",
                    exc,
                )

        # ======================================================
        # EVENTBUS PUBLICATION
        # ======================================================

        try:

            publish = getattr(
                event_bus,
                "publish",
                None,
            )

            emit = getattr(
                event_bus,
                "emit",
                None,
            )

            result = None

            if callable(
                publish
            ):

                result = publish(
                    "QBIT_STATE",
                    payload=frame,
                )

            elif callable(
                emit
            ):

                result = emit(
                    "QBIT_STATE",
                    frame,
                )

            else:

                logger.warning(
                    "[QbitDialer] "
                    "EventBus has neither "
                    "publish() nor emit()"
                )

                return False

            if inspect.isawaitable(
                result
            ):

                await result

        except asyncio.CancelledError:

            raise

        except Exception as exc:

            logger.error(
                "[QbitDialer] "
                "QBIT_STATE publication failed: %s",
                exc,
            )

            return False

        # ======================================================
        # CACHE AUTHORITATIVE STATE
        # ======================================================

        self.last_qbit_state = frame

        # ======================================================
        # LOG ROUTING IDENTITY
        #
        # Do not dump the entire ThoughtPacket every tick.
        # ======================================================

        logger.info(
            "[QbitDialer] QBIT_STATE | "
            "qbit=%s | track=%s | "
            "source=%s | channel=%s | "
            "request=%s | health=%s | "
            "compute=%s | transformer=%s",
            qbit_id,
            track_id,
            source,
            channel,
            request,
            health_flag,
            compute_thought is not None,
            transformer_thought is not None,
        )

        # ======================================================
        # SUCCESS
        # ======================================================

        return frame

    # ==========================================================
    # TRACK OVERLAY UPDATE
    #
    # STATE EMISSION ONLY
    #
    # NEVER STARTS TRACKSYSTEM
    # NEVER STARTS A RUNTIME
    # NEVER STARTS A LOOP
    # ==========================================================

    def _update_track_overlay(self, frame):

        # ------------------------------------------------------
        # Prefer the TrackSystem already bound to QbitDialer.
        # ------------------------------------------------------

        ts = getattr(
            self,
            "track_system",
            None,
        )

        # ------------------------------------------------------
        # Backward-compatible aliases.
        # ------------------------------------------------------

        if ts is None:

            ts = getattr(
                self,
                "track",
                None,
            )

        # ------------------------------------------------------
        # IMPORTANT:
        #
        # Do NOT instantiate TrackSystem here.
        #
        # If boot did not bind one yet, telemetry simply skips
        # the overlay.
        # ------------------------------------------------------

        if ts is None:

            return False

        # ======================================================
        # TRACK ID
        # ======================================================

        track_id = (
            getattr(
                ts,
                "_current_track_id",
                None,
            )
            or
            getattr(
                self,
                "_track_id",
                None,
            )
            or
            "QBIT_STATE"
        )

        # ======================================================
        # OVERLAY STORAGE
        # ======================================================

        overlays = getattr(
            ts,
            "_overlays",
            None,
        )

        if overlays is None:

            try:

                ts._overlays = {}

                overlays = (
                    ts._overlays
                )

            except Exception:

                return False

        if not isinstance(
            overlays,
            dict,
        ):

            return False

        # ======================================================
        # WRITE OVERLAY
        # ======================================================

        overlays[track_id] = {

            "stage": (
                "STATE_EMIT"
            ),

            "payload": dict(
                frame
            ),

            "timestamp": time.time(),
        }

        return True

    # ==========================================================
    # EVENT PUBLISH / OUTBOUND TRANSPORT
    #
    # OUTPUT PATH ONLY
    #
    # This method publishes an already-processed event.
    #
    # It does NOT:
    #   - decode a Qbit
    #   - process a Qbit
    #   - run ComputeBrain
    #   - transform cognition
    #   - execute commands
    #   - create a Qbit
    #   - create a queue
    #   - start a runtime loop
    #
    # Cognitive processing occurs BEFORE this boundary.
    #
    # Typical outbound path:
    #
    #   Qbit
    #      â†“
    #   ComputeBrain
    #      â†“
    #   ThoughtPacket
    #      â†“
    #   Transformer / command authority
    #      â†“
    #   result
    #      â†“
    #   BinaryEncoder
    #      â†“
    #   EventBus.publish()
    #      â†“
    #   transport
    #
    # ==========================================================

    async def publish(
        self,
        event_name="QBIT",
        payload=None,
    ):

        # ------------------------------------------------------
        # Lifecycle gate
        # ------------------------------------------------------

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] Publish suppressed | "
                "shutdown in progress | event=%s",
                event_name,
            )

            return False

        # ------------------------------------------------------
        # EventBus must exist before publishing.
        # ------------------------------------------------------

        event_bus = getattr(
            self,
            "event_bus",
            None,
        )

        if event_bus is None:

            self.logger.warning(
                "[QbitDialer] Publish suppressed | "
                "EventBus unavailable | event=%s",
                event_name,
            )

            return False

        # ------------------------------------------------------
        # Resolve publisher.
        #
        # EventBus.publish() is authoritative.
        #
        # emit() remains compatibility support.
        # ------------------------------------------------------

        publisher = getattr(
            event_bus,
            "publish",
            None,
        )

        if not callable(
            publisher
        ):

            publisher = getattr(
                event_bus,
                "emit",
                None,
            )

        if not callable(
            publisher
        ):

            self.logger.error(
                "[QbitDialer] Publish failed | "
                "EventBus has no publish()/emit() | event=%s",
                event_name,
            )

            return False

        # ------------------------------------------------------
        # Normalize event name.
        # ------------------------------------------------------

        event_name = str(
            event_name or "QBIT"
        ).strip()

        if not event_name:

            event_name = "QBIT"

        # ------------------------------------------------------
        # PAYLOAD BOUNDARY
        #
        # Do NOT silently turn a Qbit into:
        #
        #     {"value": qbit}
        #
        # A Qbit is a real object and belongs to the inbound
        # cognitive path.
        #
        # If raw Qbit data is being published intentionally,
        # preserve it under an explicit data envelope.
        # ------------------------------------------------------

        if isinstance(
            payload,
            Qbit,
        ):

            outbound_payload = {
                "type": "QbitTransport",
                "stage": "OUTBOUND",
                "qbit": payload,
            }

        elif payload is None:

            outbound_payload = {}

        elif isinstance(
            payload,
            dict,
        ):

            outbound_payload = dict(
                payload
            )

        else:

            outbound_payload = {
                "value": payload
            }

        # ------------------------------------------------------
        # Prevent raw cognitive INPUT from being mistaken for
        # an outbound command.
        #
        # A completed ThoughtPacket is valid output.
        # ------------------------------------------------------

        if isinstance(
            outbound_payload,
            dict,
        ):

            packet_type = outbound_payload.get(
                "type"
            )

            if (
                event_name == "QBIT"
                and
                packet_type == "ThoughtPacket"
            ):

                outbound_payload.setdefault(
                    "stage",
                    "COMPUTE_COMPLETE",
                )

        # ------------------------------------------------------
        # Optional binary encoder.
        #
        # The encoder belongs to the transport boundary.
        #
        # It converts a semantic outbound packet into its
        # transport representation when configured.
        # ------------------------------------------------------

        encoder = getattr(
            self,
            "encoder",
            None,
        )

        transport_payload = outbound_payload

        if encoder is not None:

            encode = getattr(
                encoder,
                "encode",
                None,
            )

            if callable(
                encode
            ):

                try:

                    encoded = encode(
                        outbound_payload
                    )

                    if inspect.isawaitable(
                        encoded
                    ):

                        encoded = await encoded

                    transport_payload = encoded

                except Exception:

                    self._publish_errors = (
                        getattr(
                            self,
                            "_publish_errors",
                            0,
                        )
                        + 1
                    )

                    self.logger.exception(
                        "[QbitDialer] Publish encoding failed | "
                        "event=%s",
                        event_name,
                    )

                    return False

        # ------------------------------------------------------
        # Rate control
        #
        # Applies to telemetry-style QBIT output.
        # Cognitive results may disable this by configuration.
        # ------------------------------------------------------

        now = time.monotonic()

        min_interval = float(
            getattr(
                self,
                "_publish_interval",
                0.10,
            )
        )

        last_publish = getattr(
            self,
            "_last_publish_time",
            0.0,
        )

        rate_limited = (
            event_name == "QBIT"
            and min_interval > 0
            and (
                now - last_publish
            ) < min_interval
        )

        if rate_limited:

            self._publish_suppressed = (
                getattr(
                    self,
                    "_publish_suppressed",
                    0,
                )
                + 1
            )

            return False

        # ------------------------------------------------------
        # Duplicate-state suppression.
        #
        # Only apply when explicitly enabled.
        # ------------------------------------------------------

        suppress_duplicates = getattr(
            self,
            "_suppress_publish_duplicates",
            False,
        )

        if (
            event_name == "QBIT"
            and
            suppress_duplicates
        ):

            previous_payload = getattr(
                self,
                "_last_published_payload",
                None,
            )

            if (
                previous_payload
                ==
                transport_payload
            ):

                self._publish_duplicates = (
                    getattr(
                        self,
                        "_publish_duplicates",
                        0,
                    )
                    + 1
                )

                return False

        # ------------------------------------------------------
        # Commit publish timestamp BEFORE dispatch.
        #
        # Prevents rapid re-entry from bypassing the limiter.
        # ------------------------------------------------------

        self._last_publish_time = now

        if event_name == "QBIT":

            self._last_published_payload = (
                transport_payload
            )

        # ------------------------------------------------------
        # OUTBOUND EVENT DISPATCH
        #
        # At this point the cognitive work is complete.
        # EventBus is transport/distribution infrastructure.
        # ------------------------------------------------------

        try:

            result = publisher(
                event_name,
                transport_payload,
            )

            if inspect.isawaitable(
                result
            ):

                await result

            self._publish_count = (
                getattr(
                    self,
                    "_publish_count",
                    0,
                )
                + 1
            )

            self.logger.debug(
                "[QbitDialer] Event published | "
                "event=%s | count=%d",
                event_name,
                self._publish_count,
            )

            return True

        except Exception:

            self._publish_errors = (
                getattr(
                    self,
                    "_publish_errors",
                    0,
                )
                + 1
            )

            self.logger.exception(
                "[QbitDialer] Publish failed | "
                "event=%s",
                event_name,
            )

            return False

    # ==========================================================
    # EVENTBUS ACTIVATION
    #
    # SYSTEM-WIDE READINESS HANDLER
    #
    # EventBus is shared infrastructure.
    # QbitDialer is shared command infrastructure.
    #
    # When EventBus is ready:
    #
    #     EventBus
    #        â†“
    #     QbitDialer ACTIVE
    #        â†“
    #     command plane available
    #        â†“
    #     Qbit receive path available
    #        â†“
    #     authoritative QbitQueueLoop
    #        â†“
    #     ComputeBrain
    #
    # IMPORTANT:
    #     This method establishes readiness only.
    #
    #     It does NOT:
    #       - create a loop
    #       - start a loop
    #       - create a Qbit
    #       - process a Qbit
    #       - create another EventBus
    #       - clear limp mode
    #
    #     Runtime loop ownership remains with start().
    # ==========================================================

    async def _on_event_bus_ready(
        self,
        event=None,
    ):

        # ------------------------------------------------------
        # SYSTEM-WIDE ACTIVATION
        # ------------------------------------------------------

        self.active = True
        self.event_bus_ready = True

        # ------------------------------------------------------
        # Ensure readiness flags exist.
        #
        # Do not force runtime state here.
        # ------------------------------------------------------

        if not hasattr(
            self,
            "_running",
        ):

            self._running = False

        if not hasattr(
            self,
            "planning",
        ):

            self.planning = False

        if not hasattr(
            self,
            "brain_go",
        ):

            self.brain_go = False

        if not hasattr(
            self,
            "idle",
        ):

            self.idle = True

        # ------------------------------------------------------
        # SYSTEM-WIDE HEALTH / GREEN FLAG
        #
        # EventBus readiness means the command plane can now
        # report itself as available.
        #
        # Do not overwrite an existing explicit failure state.
        # ------------------------------------------------------

        if not getattr(
            self,
            "limp",
            False,
        ):

            self.healthy = True
            self.ready = True
            self.operational = True

        # ------------------------------------------------------
        # QBIT INFRASTRUCTURE STATUS
        #
        # Informational only.
        #
        # The queue and ComputeBrain must already be attached
        # by the authoritative boot/wiring path.
        # ------------------------------------------------------

        qbit_queue = getattr(
            self,
            "_qbit_queue",
            None,
        )

        if qbit_queue is None:

            qbit_queue = getattr(
                self,
                "qbit_queue",
                None,
            )

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        qbit_path_ready = (
            qbit_queue is not None
            and
            compute_brain is not None
        )

        # ------------------------------------------------------
        # COMMAND REGISTRY
        # ------------------------------------------------------

        command_registry = getattr(
            self,
            "command_registry",
            {},
        )

        # ------------------------------------------------------
        # LOG SYSTEM-WIDE READINESS
        # ------------------------------------------------------

        self.logger.info(
            "[QbitDialer] EventBus ready â€” "
            "system-wide command plane active | "
            "healthy=%s ready=%s operational=%s | "
            "qbit_path=%s | "
            "qbit_queue=%s | "
            "compute_brain=%s | "
            "running=%s | "
            "commands=%d",
            getattr(
                self,
                "healthy",
                False,
            ),
            getattr(
                self,
                "ready",
                False,
            ),
            getattr(
                self,
                "operational",
                False,
            ),
            qbit_path_ready,
            qbit_queue is not None,
            compute_brain is not None,
            getattr(
                self,
                "_running",
                False,
            ),
            len(command_registry),
        )

        # ------------------------------------------------------
        # RETURN AUTHORITATIVE READINESS STATE
        # ------------------------------------------------------

        return {

            "status": "active",

            "active": True,

            "event_bus": True,

            "event_bus_ready": True,

            "healthy": getattr(
                self,
                "healthy",
                False,
            ),

            "ready": getattr(
                self,
                "ready",
                False,
            ),

            "operational": getattr(
                self,
                "operational",
                False,
            ),

            "running": getattr(
                self,
                "_running",
                False,
            ),

            "qbit_path_ready": (
                qbit_path_ready
            ),

            "qbit_queue": (
                qbit_queue is not None
            ),

            "compute_brain": (
                compute_brain is not None
            ),

            "commands": len(
                command_registry
            ),

            "planning": getattr(
                self,
                "planning",
                False,
            ),

            "brain_go": getattr(
                self,
                "brain_go",
                False,
            ),

            "idle": getattr(
                self,
                "idle",
                True,
            ),

            "limp": getattr(
                self,
                "limp",
                False,
            ),
        }
# ====================================================
    # ==========================================================
    # ACTIVATE
    #
    # Activates QbitDialer as the command authority.
    #
    # IMPORTANT:
    #   - Does NOT create a Qbit.
    #   - Does NOT create/start QbitQueueLoop.
    #   - Does NOT create a secondary processing task.
    #   - Does NOT clear limp mode.
    #   - Does NOT process a Qbit.
    #
    # Qbit processing remains:
    #
    #   Qbit
    #      â†“
    #   receive_qbit()
    #      â†“
    #   authoritative QbitQueue
    #      â†“
    #   QbitQueueLoop
    #      â†“
    #   ComputeBrain
    #
    # ==========================================================

    async def activate(
        self,
    ):

        # ------------------------------------------------------
        # Lifecycle state
        # ------------------------------------------------------

        self.active = True

        # Activation means the Dialer is available as the
        # command authority. It does not automatically admit
        # command execution or start a runtime loop.

        if not hasattr(
            self,
            "planning",
        ):

            self.planning = False

        if not hasattr(
            self,
            "brain_go",
        ):

            self.brain_go = False

        if not hasattr(
            self,
            "idle",
        ):

            self.idle = True

        # ------------------------------------------------------
        # Command registry
        # ------------------------------------------------------

        command_registry = getattr(
            self,
            "command_registry",
            None,
        )

        if command_registry is None:

            command_registry = {}

            self.command_registry = (
                command_registry
            )

        # ------------------------------------------------------
        # Command list
        # ------------------------------------------------------

        get_command_list = getattr(
            self,
            "get_command_list",
            None,
        )

        if callable(
            get_command_list
        ):

            try:

                commands = (
                    get_command_list()
                )

            except Exception as exc:

                self.logger.warning(
                    "[QbitDialer] Unable to build "
                    "command list during activation | "
                    "error=%s",
                    exc,
                )

                commands = list(
                    command_registry.keys()
                )

        else:

            commands = list(
                command_registry.keys()
            )

        # ------------------------------------------------------
        # Qbit processing status
        #
        # This is informational only.
        # Activation does NOT start the queue.
        # ------------------------------------------------------

        qbit_queue = getattr(
            self,
            "_qbit_queue",
            None,
        )

        if qbit_queue is None:

            qbit_queue = getattr(
                self,
                "qbit_queue",
                None,
            )

        queue_attached = (
            qbit_queue is not None
        )

        compute_brain = getattr(
            self,
            "compute_brain",
            None,
        )

        compute_brain_attached = (
            compute_brain is not None
        )

        # ------------------------------------------------------
        # Log activation
        # ------------------------------------------------------

        self.logger.info(
            "[QbitDialer] Activated | "
            "command_count=%d | "
            "qbit_queue=%s | "
            "compute_brain=%s | "
            "planning=%s | brain_go=%s | limp=%s",
            len(commands),
            queue_attached,
            compute_brain_attached,
            self.planning,
            self.brain_go,
            getattr(
                self,
                "limp",
                False,
            ),
        )

        # ------------------------------------------------------
        # Return authoritative activation state
        # ------------------------------------------------------

        return {

            "status": "active",

            "active": True,

            "commands": commands,

            "command_count": len(
                commands
            ),

            "qbit_queue_attached": (
                queue_attached
            ),

            "compute_brain_attached": (
                compute_brain_attached
            ),

            "planning": self.planning,

            "brain_go": self.brain_go,

            "idle": self.idle,

            "limp": getattr(
                self,
                "limp",
                False,
            ),

        }
    # ==========================================================
    # QBIT COMMAND / DATA ENTRY
    #
    # AUTHORITATIVE QBIT BOUNDARY
    #
    # Qbit DATA:
    #
    #     Qbit
    #       |
    #       v
    #     existing Qbit task/context
    #       |
    #       v
    #     submit_qbit_command()
    #       |
    #       v
    #     _process_received_qbit()
    #       |
    #       v
    #     TrackSystem
    #       |
    #       v
    #     ComputeBrain
    #       |
    #       v
    #     ThoughtPacket
    #       |
    #       v
    #     TransformerBrain
    #       |
    #       v
    #     command envelope
    #       |
    #       v
    #     submit_command()
    #       |
    #       v
    #     authoritative command_queue
    #
    # COMMAND DATA:
    #
    #     command envelope
    #       |
    #       v
    #     submit_command()
    #       |
    #       v
    #     command_queue
    #       |
    #       v
    #     _process_command_plane()
    #       |
    #       v
    #     _execute_qbit_command()
    #
    # IMPORTANT:
    #
    #     Qbit object = DATA
    #     command envelope = CONTROL
    #
    # They must NEVER be treated as the same object type.
    #
    # NO:
    #
    #     - direct handler execution
    #     - second command queue
    #     - second QbitQueueLoop
    #     - second runtime
    #     - Qbit -> str() -> command
    #     - synthetic Qbit identity
    #
    # MULTI-QBIT PROCESSING:
    #
    # Each Qbit keeps its own:
    #
    #     qbit_id
    #     track_id
    #
    # Related Qbits may additionally share:
    #
    #     task_id
    #     pipeline_id
    #     parent_id
    #     sequence
    #     lineage
    #     relationships
    #
    # This allows one Qbit to start a cognitive chain and
    # subsequent Qbits to follow it without merging their
    # identities.
    # ==========================================================

    async def _Qbit(
        self,
        payload=None,
    ):

        # ======================================================
        # 1. LIFECYCLE GATE
        # ======================================================

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] Qbit input rejected | "
                "shutdown in progress"
            )

            return {
                "status": "rejected",
                "stage": "qbit_entry",
                "reason": "shutdown_in_progress",
            }

        # ======================================================
        # 2. RAW QBIT DATA BOUNDARY
        #
        # A real Qbit must NEVER be normalized as a command.
        #
        # Route the EXISTING Qbit into the authoritative
        # cognitive receive path.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                payload,
                qbit_type,
            )
        ):

            qbit = payload

            # --------------------------------------------------
            # Existing Qbit identity.
            # --------------------------------------------------

            qbit_id = self._extract_qbit_field(
                qbit,
                "qbit_id",
                None,
            )

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            track_id = self._extract_qbit_field(
                qbit,
                "track_id",
                None,
            )

            task_id = self._extract_qbit_field(
                qbit,
                "task_id",
                None,
            )

            task = self._extract_qbit_field(
                qbit,
                "task",
                None,
            )

            if task_id is None and isinstance(
                task,
                dict,
            ):

                task_id = task.get(
                    "task_id"
                )

            pipeline_id = self._extract_qbit_field(
                qbit,
                "pipeline_id",
                None,
            )

            parent_id = self._extract_qbit_field(
                qbit,
                "parent_id",
                None,
            )

            sequence = self._extract_qbit_field(
                qbit,
                "sequence",
                None,
            )

            # --------------------------------------------------
            # Attach routing metadata ONLY when that metadata
            # is absent and an existing routing mechanism is
            # available.
            #
            # No new Qbit identity is created here.
            # --------------------------------------------------

            if track_id is None:

                track_id = self._generate_command_track_id(
                    qbit
                )

                try:

                    setattr(
                        qbit,
                        "track_id",
                        track_id,
                    )

                except Exception:

                    pass

            # --------------------------------------------------
            # Preserve the existing Qbit/task relationship.
            # --------------------------------------------------

            try:

                self.logger.info(
                    "[QbitDialer] RAW QBIT DATA -> "
                    "cognitive pipeline | "
                    "qbit_id=%s | track_id=%s | "
                    "task_id=%s | pipeline_id=%s | "
                    "parent_id=%s | sequence=%s",
                    qbit_id,
                    track_id,
                    task_id,
                    pipeline_id,
                    parent_id,
                    sequence,
                )

            except Exception:

                pass

            # --------------------------------------------------
            # The raw Qbit enters ONE authoritative cognitive
            # path.
            # --------------------------------------------------

            return await self.submit_qbit_command(
                qbit
            )

        # ======================================================
        # 3. RUNTIME GATE
        #
        # Applies only to command/control input.
        # ======================================================

        if not getattr(
            self,
            "_running",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] Qbit command rejected | "
                "runtime not running"
            )

            return {
                "status": "rejected",
                "stage": "command_entry",
                "reason": "runtime_not_running",
            }

        # ======================================================
        # 4. NORMALIZE EXTERNAL / INTERNAL INPUT INTO A
        #    COMMAND ENVELOPE
        #
        # This does NOT execute anything.
        #
        # It prepares command DATA for submit_command().
        # ======================================================

        if payload is None:

            payload = {}

        elif isinstance(
            payload,
            str,
        ):

            payload = {
                "command": payload,
            }

        elif not isinstance(
            payload,
            dict,
        ):

            payload = {
                "value": payload,
            }

        else:

            payload = dict(
                payload
            )

        # ======================================================
        # 5. RESOLVE COMMAND NAME
        #
        # NEVER stringify a Qbit here.
        # ======================================================

        command = (

            payload.get(
                "command"
            )

            or payload.get(
                "name"
            )

            or payload.get(
                "action"
            )

            or payload.get(
                "cmd"
            )

        )

        # ------------------------------------------------------
        # Explicit protection against a Qbit in the command
        # position.
        # ------------------------------------------------------

        if (
            qbit_type is not None
            and isinstance(
                command,
                qbit_type,
            )
        ):

            self.logger.warning(
                "[QbitDialer] Qbit object supplied in "
                "command position | routing to cognitive path"
            )

            return await self.submit_qbit_command(
                command
            )

        if command is None:

            self.logger.warning(
                "[QbitDialer] Qbit command rejected | "
                "missing command"
            )

            return {
                "status": "rejected",
                "stage": "command_entry",
                "reason": "missing_command",
            }

        if not isinstance(
            command,
            str,
        ):

            self.logger.warning(
                "[QbitDialer] Qbit command rejected | "
                "invalid command type=%s",
                type(command).__name__,
            )

            return {
                "status": "rejected",
                "stage": "command_entry",
                "reason": "invalid_command_type",
                "type": type(command).__name__,
            }

        command = command.strip().upper()

        if not command:

            self.logger.warning(
                "[QbitDialer] Qbit command rejected | "
                "empty command"
            )

            return {
                "status": "rejected",
                "stage": "command_entry",
                "reason": "empty_command",
            }

        # ======================================================
        # 6. RESOLVE EXISTING QBIT/TASK CONTEXT
        #
        # External command input may already carry identity
        # and cognitive context.
        #
        # Preserve it.
        # ======================================================

        qbit = payload.get(
            "qbit"
        )

        qbit_id = payload.get(
            "qbit_id"
        )

        track_id = payload.get(
            "track_id"
        )

        task_id = payload.get(
            "task_id"
        )

        pipeline_id = payload.get(
            "pipeline_id"
        )

        parent_id = payload.get(
            "parent_id"
        )

        if qbit is not None:

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "qbit_id",
                    None,
                )

            if qbit_id is None:

                qbit_id = self._extract_qbit_field(
                    qbit,
                    "id",
                    None,
                )

            if track_id is None:

                track_id = self._extract_qbit_field(
                    qbit,
                    "track_id",
                    None,
                )

            if task_id is None:

                task_id = self._extract_qbit_field(
                    qbit,
                    "task_id",
                    None,
                )

            if pipeline_id is None:

                pipeline_id = self._extract_qbit_field(
                    qbit,
                    "pipeline_id",
                    None,
                )

        # ======================================================
        # 7. CAPABILITY / CATALOG LOOKUP
        #
        # Catalog tells the Dialer what SEED knows.
        #
        # Registry tells the Dialer what it can execute.
        #
        # This entry point does NOT create handlers.
        # Dynamic registration owns that responsibility.
        # ======================================================

        catalog = getattr(
            self,
            "command_catalog",
            {},
        )

        registry = getattr(
            self,
            "command_registry",
            {},
        )

        capability = {}

        if isinstance(
            catalog,
            dict,
        ):

            capability = catalog.get(
                command,
                {},
            )

            if not isinstance(
                capability,
                dict,
            ):

                capability = {}

        handler = None

        if isinstance(
            registry,
            dict,
        ):

            handler = registry.get(
                command
            )

        # ------------------------------------------------------
        # Preserve capability metadata on the command.
        # ------------------------------------------------------

        payload[
            "command"
        ] = command

        payload[
            "command_name"
        ] = command

        payload[
            "qbit_id"
        ] = qbit_id

        payload[
            "track_id"
        ] = track_id

        payload[
            "task_id"
        ] = task_id

        payload[
            "pipeline_id"
        ] = pipeline_id

        payload[
            "parent_id"
        ] = parent_id

        payload[
            "capability"
        ] = capability

        payload[
            "capability_known"
        ] = bool(
            capability
        )

        payload[
            "executable"
        ] = callable(
            handler
        )

        # ======================================================
        # 8. COMMAND ENVELOPE
        #
        # Everything required downstream travels together.
        # ======================================================

        command_envelope = dict(
            payload
        )

        command_envelope.update({

            "name": command,

            "qbit": qbit,

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "parent_id": parent_id,

            "source": payload.get(
                "source",
                "QBIT_COMMAND_ENTRY",
            ),

            "channel": payload.get(
                "channel",
                "CLI",
            ),

            "priority": payload.get(
                "priority",
                5,
            ),

            "confidence": payload.get(
                "confidence",
                1.0,
            ),

            "thought": payload.get(
                "thought"
            ),

            "intent": payload.get(
                "intent"
            ),

            "action": payload.get(
                "action"
            ),

            "compute": payload.get(
                "compute"
            ),

            "transform": payload.get(
                "transform"
            ),

            "args": payload.get(
                "args",
                [],
            ),

            "kwargs": payload.get(
                "kwargs",
                {},
            ),

            "payload": payload,

            "authority": "QbitDialer",

            "command_source": payload.get(
                "command_source",
                payload.get(
                    "source",
                    "QBIT_COMMAND_ENTRY",
                ),
            ),

        })

        # ======================================================
        # 9. DYNAMIC LINEAGE / MULTI-QBIT CONTEXT
        #
        # This connects subsequent Qbits/commands to the
        # cognitive chain without changing their identity.
        # ======================================================

        command_envelope[
            "cognitive_link"
        ] = {

            "authority": "QbitDialer",

            "qbit_id": qbit_id,

            "track_id": track_id,

            "task_id": task_id,

            "pipeline_id": pipeline_id,

            "parent_id": parent_id,

            "sequence": payload.get(
                "sequence"
            ),

            "previous_qbit_id": payload.get(
                "previous_qbit_id"
            ),

            "previous_command": payload.get(
                "previous_command"
            ),

            "capability": command,

        }

        # ======================================================
        # 10. DUPLICATE SUPPRESSION
        #
        # Disabled by default.
        # ======================================================

        if (
            getattr(
                self,
                "_suppress_duplicate_commands",
                False,
            )
            and
            getattr(
                self,
                "_last_qbit_command",
                None,
            ) == command
        ):

            self.logger.debug(
                "[QbitDialer] Duplicate Qbit command "
                "suppressed | command=%s | qbit_id=%s",
                command,
                qbit_id,
            )

            return {
                "status": "suppressed",
                "command": command,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "task_id": task_id,
            }

        self._last_qbit_command = command

        # ======================================================
        # 11. AUTHORITATIVE COMMAND ADMISSION
        #
        # NEVER call _execute_qbit_command() here.
        #
        # submit_command() is the ONE admission path.
        #
        # It places the command on the authoritative queue.
        # ======================================================

        try:

            result = self.submit_command(
                command_envelope
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            return result

        except asyncio.CancelledError:

            self.logger.debug(
                "[QbitDialer] Qbit command cancelled | "
                "command=%s | qbit_id=%s | track_id=%s",
                command,
                qbit_id,
                track_id,
            )

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] Qbit command admission failed | "
                "command=%s | qbit_id=%s | track_id=%s | "
                "error=%s: %s",
                command,
                qbit_id,
                track_id,
                type(exc).__name__,
                exc,
            )

            return {
                "status": "failed",
                "stage": "command_admission",
                "command": command,
                "qbit_id": qbit_id,
                "track_id": track_id,
                "task_id": task_id,
                "pipeline_id": pipeline_id,
                "error": str(exc),
                "error_type": type(exc).__name__,
            }


    # ==========================================================
    # COMMAND STUB / COMPATIBILITY ADAPTER
    #
    # LEGACY ENTRY -> AUTHORITATIVE QBIT DIALER PATH
    #
    # This method exists only to keep older callers connected
    # to the current command architecture.
    #
    # AUTHORITATIVE ROUTES:
    #
    #     RAW QBIT
    #        |
    #        v
    #     submit_qbit_command()
    #        |
    #        v
    #     _process_received_qbit()
    #        |
    #        v
    #     ComputeBrain
    #        |
    #        v
    #     TransformerBrain
    #        |
    #        v
    #     command envelope
    #        |
    #        v
    #     submit_command()
    #
    #     COMMAND ENVELOPE
    #        |
    #        v
    #     submit_command()
    #        |
    #        v
    #     command_queue
    #
    # IMPORTANT:
    #
    #     create_task() remains the working Qbit/task contract.
    #
    # This adapter does NOT:
    #
    #     - create a Qbit
    #     - create a task
    #     - create a command queue
    #     - create a QbitQueueLoop
    #     - execute a handler directly
    #     - stringify a Qbit into a command
    #     - create a recovery subsystem
    #
    # ==========================================================

    async def _send_command_stub(
        self,
        *args,
        **kwargs,
    ):

        # ======================================================
        # 1. RESOLVE LEGACY INPUT
        #
        # Preserve positional arguments, keyword arguments,
        # Qbit identity, task identity, and cognitive metadata.
        # ======================================================

        if args:

            command = args[0]

            if len(
                args
            ) > 1:

                command_args = list(
                    args[1:]
                )

            else:

                command_args = []

            # --------------------------------------------------
            # Existing command envelope.
            # --------------------------------------------------

            if isinstance(
                command,
                dict,
            ):

                command = dict(
                    command
                )

                if command_args:

                    existing_args = command.get(
                        "args",
                        [],
                    )

                    if not isinstance(
                        existing_args,
                        (list, tuple),
                    ):

                        existing_args = [
                            existing_args
                        ]

                    command[
                        "args"
                    ] = (
                        list(
                            existing_args
                        )
                        + command_args
                    )

                if kwargs:

                    command.update(
                        kwargs
                    )

            else:

                # ------------------------------------------------
                # Legacy positional command.
                #
                # The first positional value is command DATA.
                # Remaining positional values become args.
                # ------------------------------------------------

                command = {

                    "command": command,

                    "args": command_args,

                }

                command.update(
                    kwargs
                )

        elif kwargs:

            command = dict(
                kwargs
            )

        else:

            self.logger.debug(
                "[QbitDialer] Command stub rejected | "
                "empty command"
            )

            return {
                "status": "rejected",
                "reason": "empty_command",
            }

        # ======================================================
        # 2. LIFECYCLE GATE
        # ======================================================

        if getattr(
            self,
            "_stopping",
            False,
        ):

            self.logger.debug(
                "[QbitDialer] Command stub rejected | "
                "shutdown in progress"
            )

            return {
                "status": "rejected",
                "reason": "shutdown_in_progress",
            }

        # ======================================================
        # 3. RAW QBIT BOUNDARY
        #
        # A Qbit is DATA.
        #
        # It must NEVER enter execute_command() as an ordinary
        # command object.
        # ======================================================

        qbit_type = globals().get(
            "Qbit",
            None,
        )

        if (
            qbit_type is not None
            and isinstance(
                command,
                qbit_type,
            )
        ):

            # --------------------------------------------------
            # Preserve the existing Qbit.
            #
            # Do NOT create a new Qbit.
            # Do NOT create a task here.
            # --------------------------------------------------

            self.logger.debug(
                "[QbitDialer] Command stub received RAW QBIT | "
                "routing to cognitive receive path | "
                "qbit_id=%s | track_id=%s",
                self._extract_qbit_field(
                    command,
                    "qbit_id",
                    self._extract_qbit_field(
                        command,
                        "id",
                        None,
                    ),
                ),
                self._extract_qbit_field(
                    command,
                    "track_id",
                    None,
                ),
            )

            return await self.submit_qbit_command(
                command
            )

        # ======================================================
        # 4. PROTECT AGAINST QBIT IN COMMAND POSITION
        #
        # Prevent:
        #
        #     {"name": <Qbit>}
        #
        # from reaching normalization/execution.
        # ======================================================

        if isinstance(
            command,
            dict,
        ):

            for field_name in (
                "name",
                "command",
                "cmd",
                "action",
                "intent",
            ):

                candidate = command.get(
                    field_name
                )

                if (
                    qbit_type is not None
                    and isinstance(
                        candidate,
                        qbit_type,
                    )
                ):

                    self.logger.warning(
                        "[QbitDialer] Legacy command stub received "
                        "Qbit object in command field | "
                        "field=%s | routing raw Qbit | "
                        "qbit_id=%s",
                        field_name,
                        self._extract_qbit_field(
                            candidate,
                            "qbit_id",
                            self._extract_qbit_field(
                                candidate,
                                "id",
                                None,
                            ),
                        ),
                    )

                    return await self.submit_qbit_command(
                        candidate
                    )

        # ======================================================
        # 5. PRESERVE COMMAND CONTEXT
        #
        # Legacy callers may provide:
        #
        #     qbit
        #     qbit_id
        #     track_id
        #     task_id
        #     pipeline_id
        #     source
        #     channel
        #     thought
        #     intent
        #     action
        #     compute
        #     transform
        #     args
        #     kwargs
        #     payload
        #
        # Do not discard that information before it reaches
        # submit_command().
        # ======================================================

        if isinstance(
            command,
            dict,
        ):

            qbit = command.get(
                "qbit"
            )

            if qbit is not None:

                command.setdefault(
                    "qbit_id",
                    self._extract_qbit_field(
                        qbit,
                        "qbit_id",
                        self._extract_qbit_field(
                            qbit,
                            "id",
                            None,
                        ),
                    ),
                )

                command.setdefault(
                    "track_id",
                    self._extract_qbit_field(
                        qbit,
                        "track_id",
                        None,
                    ),
                )

                command.setdefault(
                    "task_id",
                    self._extract_qbit_field(
                        qbit,
                        "task_id",
                        None,
                    ),
                )

                command.setdefault(
                    "pipeline_id",
                    self._extract_qbit_field(
                        qbit,
                        "pipeline_id",
                        None,
                    ),
                )

                command.setdefault(
                    "task",
                    self._extract_qbit_field(
                        qbit,
                        "task",
                        None,
                    ),
                )

                command.setdefault(
                    "lineage",
                    self._extract_qbit_field(
                        qbit,
                        "data_lineage",
                        None,
                    ),
                )

                command.setdefault(
                    "relationships",
                    self._extract_qbit_field(
                        qbit,
                        "relationships",
                        None,
                    ),
                )

        # ======================================================
        # 6. LEGACY INPUT BECOMES COMMAND DATA
        #
        # This is still NOT execution.
        #
        # submit_command() remains the single command admission
        # authority.
        # ======================================================

        if isinstance(
            command,
            dict,
        ):

            command.setdefault(
                "source",
                "LEGACY_COMMAND_STUB",
            )

            command.setdefault(
                "channel",
                "CLI",
            )

            command.setdefault(
                "authority",
                "QbitDialer",
            )

            command.setdefault(
                "priority",
                5,
            )

            command.setdefault(
                "confidence",
                1.0,
            )

            command.setdefault(
                "args",
                [],
            )

            command.setdefault(
                "kwargs",
                {},
            )

            command.setdefault(
                "payload",
                {},
            )

        # ======================================================
        # 7. SINGLE AUTHORITATIVE COMMAND ADMISSION
        #
        # IMPORTANT:
        #
        # Do NOT call:
        #
        #     _execute_qbit_command()
        #
        # directly.
        #
        # The command must enter:
        #
        #     submit_command()
        #          |
        #          v
        #     command_registry
        #          |
        #          v
        #     command_queue
        # ======================================================

        try:

            result = self.submit_command(
                command
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            return result

        except asyncio.CancelledError:

            self.logger.debug(
                "[QbitDialer] Command stub cancelled"
            )

            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] Command stub admission failed | "
                "error=%s: %s",
                type(exc).__name__,
                exc,
            )

            return {
                "status": "failed",
                "stage": "command_stub",
                "reason": "command_admission_error",
                "error": str(
                    exc
                ),
                "error_type": type(
                    exc
                ).__name__,
            }

    # ==========================================================
    # EXECUTION ADMISSION
    #
    # QbitDialer is the command authority.
    #
    # can_execute()
    #     â†“
    # validates whether execution is currently permitted
    #
    # allow_execution()
    #     â†“
    # admits the Dialer into active execution/planning state
    #
    # SEED ACTION DECISION
    #     â†“
    # action suggestion / selected action
    #     â†“
    # submit_command()
    #     â†“
    # command admission
    #     â†“
    # execution pipeline
    #
    # IMPORTANT:
    #   - Never force limp mode OFF.
    #   - Never bypass health monitoring.
    #   - Never create/start a runtime loop.
    #   - Never execute a command here.
    #   - submit_command() remains the admission boundary.
    # ==========================================================

    async def can_execute(
        self,
        module_name=None,
    ) -> bool:

        # ------------------------------------------------------
        # Base operational gate
        # ------------------------------------------------------

        if not getattr(
            self,
            "operational",
            False,
        ):

            return False

        # ------------------------------------------------------
        # Limp-mode gate
        #
        # Limp mode is authoritative and must never be cleared
        # by an execution-admission call.
        # ------------------------------------------------------

        if getattr(
            self,
            "limp",
            False,
        ):

            return False

        # ------------------------------------------------------
        # Optional module health gate
        # ------------------------------------------------------

        health_monitor = getattr(
            self,
            "health_monitor",
            None,
        )

        if (
            health_monitor is not None
            and module_name
        ):

            is_operational = getattr(
                health_monitor,
                "is_operational",
                None,
            )

            if callable(
                is_operational
            ):

                try:

                    result = is_operational(
                        module_name
                    )

                    if inspect.isawaitable(
                        result
                    ):

                        result = await result

                    if not result:

                        return False

                except Exception as exc:

                    self.logger.warning(
                        "[QbitDialer] Execution admission "
                        "denied | module=%s | health check failed: %s",
                        module_name,
                        exc,
                    )

                    return False

        return True

    async def allow_execution(
        self,
        module_name=None,
        action=None,
        action_context=None,
    ):

        # ------------------------------------------------------
        # DO NOT ADMIT EXECUTION IF THE SYSTEM IS NOT READY.
        # ------------------------------------------------------

        allowed = await self.can_execute(
            module_name
        )

        if not allowed:

            self.planning = False
            self.brain_go = False
            self.idle = True

            self.logger.warning(
                "[QbitDialer] Command execution denied | "
                "module=%s operational=%s limp=%s",
                module_name,
                getattr(
                    self,
                    "operational",
                    False,
                ),
                getattr(
                    self,
                    "limp",
                    False,
                ),
            )

            return False

        # ------------------------------------------------------
        # ADMISSION SUCCESS
        # ------------------------------------------------------

        self.planning = True
        self.idle = False
        self.brain_go = True

        # ------------------------------------------------------
        # PRESERVE SEED ACTION DECISION
        #
        # This is decision/context only.
        # It does not execute the action.
        # ------------------------------------------------------

        if not isinstance(
            action_context,
            dict,
        ):

            action_context = {}

        selected_action = (
            action
            or action_context.get(
                "action"
            )
            or action_context.get(
                "command"
            )
        )

        if selected_action:

            self.last_action_suggestion = {
                "action": selected_action,

                "command": action_context.get(
                    "command",
                    selected_action,
                ),

                "who": action_context.get(
                    "who"
                ),

                "what": action_context.get(
                    "what",
                    selected_action,
                ),

                "where": action_context.get(
                    "where",
                    module_name,
                ),

                "why": action_context.get(
                    "why"
                ),

                "how": action_context.get(
                    "how"
                ),

                "module": module_name,

                "priority": action_context.get(
                    "priority",
                    5,
                ),

                "decision": action_context.get(
                    "decision",
                    {},
                ),

                "qbit_context": action_context.get(
                    "qbit_context",
                    {},
                ),

                "health": action_context.get(
                    "health",
                    {},
                ),

                "source": action_context.get(
                    "source",
                    "SEED",
                ),

                "authority": "QbitDialer",

                "execute": False,

                "submit": False,
            }

        # ------------------------------------------------------
        # IMPORTANT:
        #
        # Do NOT clear limp mode here.
        #
        # Limp-mode authority belongs to the system
        # safety/health controller.
        # ------------------------------------------------------

        self.logger.info(
            "[QbitDialer] Command execution admitted | "
            "module=%s planning=%s brain_go=%s limp=%s "
            "action=%s",
            module_name,
            self.planning,
            self.brain_go,
            getattr(
                self,
                "limp",
                False,
            ),
            selected_action,
        )

        return True

    async def _admit_selected_action(
        self,
        action,
        action_context=None,
        module_name=None,
    ):
        """
        Route a SEED-selected action through the existing
        QbitDialer command-admission boundary.

        This method does NOT execute the action.
        """

        if not action:
            return {
                "status": "no_action",
                "admitted": False,
            }

        if not isinstance(
            action_context,
            dict,
        ):

            action_context = {}

        # ------------------------------------------------------
        # FIRST: RUN EXECUTION ADMISSION GATES
        # ------------------------------------------------------

        allowed = await self.allow_execution(
            module_name=module_name,
            action=action,
            action_context=action_context,
        )

        if not allowed:

            return {
                "status": "denied",
                "admitted": False,
                "action": action,
                "authority": "QbitDialer",
                "reason": "execution_admission_denied",
            }

        # ------------------------------------------------------
        # BUILD COMMAND FROM THE SEED DECISION
        #
        # Preserve semantic context instead of reducing the
        # decision to a bare command string.
        # ------------------------------------------------------

        command = {
            "type": "SEEDActionCommand",

            "command": action,

            "action": action,

            "module": (
                module_name
                or action_context.get(
                    "module"
                )
            ),

            "who": action_context.get(
                "who",
                "SEED",
            ),

            "what": action_context.get(
                "what",
                action,
            ),

            "where": action_context.get(
                "where",
                module_name,
            ),

            "why": action_context.get(
                "why",
                "SEED_action_selection",
            ),

            "how": action_context.get(
                "how",
                "SEED_decision",
            ),

            "priority": action_context.get(
                "priority",
                5,
            ),

            "decision": action_context.get(
                "decision",
                {},
            ),

            "health": action_context.get(
                "health",
                {},
            ),

            "qbit_context": action_context.get(
                "qbit_context",
                {},
            ),

            "compute_context": action_context.get(
                "compute_context",
                {},
            ),

            "action_suggestion": action_context.get(
                "action_suggestion",
                {},
            ),

            "source": action_context.get(
                "source",
                "SEED",
            ),

            "authority": "QbitDialer",

            "execute": False,

            "submit": False,
        }

        # ------------------------------------------------------
        # SEED HAS SELECTED THE ACTION.
        #
        # NOW RETURN THROUGH THE EXISTING SUBMIT_COMMAND()
        # ADMISSION PATH.
        #
        # DO NOT CALL execute_command().
        # DO NOT CALL execute_all().
        # ------------------------------------------------------

        submit_command = getattr(
            self,
            "submit_command",
            None,
        )

        if not callable(
            submit_command
        ):

            self.logger.error(
                "[QbitDialer] submit_command unavailable | "
                "selected_action=%s",
                action,
            )

            return {
                "status": "admission_unavailable",
                "admitted": False,
                "action": action,
                "command": command,
                "authority": "QbitDialer",
            }

        try:

            result = submit_command(
                command
            )

            if inspect.isawaitable(
                result
            ):

                result = await result

            self.logger.info(
                "[QbitDialer] SEED action submitted | "
                "action=%s module=%s",
                action,
                module_name,
            )

            return result

        except asyncio.CancelledError:
            raise

        except Exception as exc:

            self.logger.exception(
                "[QbitDialer] SEED action admission failed | "
                "action=%s | %s: %s",
                action,
                type(exc).__name__,
                exc,
            )

            return {
                "status": "admission_error",
                "admitted": False,
                "action": action,
                "command": command,
                "authority": "QbitDialer",
                "error": (
                    f"{type(exc).__name__}: {exc}"
                ),
            }
