# ==========================================================
# SEED Cognitive Kernel (Autonomous)
# Purpose:
# - Self-awareness
# - Self-evaluation
# - Self-regulation (not restriction)
# - No external permission model
# ==========================================================

class SeedCognitiveKernel:
    def __init__(self, *, payload, event_bus, qbit, dialer):
        self.event_bus = event_bus
        self.qbit = qbit
        self.dialer = dialer
        self.enabled = True
        self.mode = "auto"

        self.state = {
            "boot_valid": False,
            "issues": [],
            "subscriptions": {},
            "confidence": 1.0,   # 0.0 -> 1.0
        }

    # --------------------------------------------------
    # BOOT SELF-ASSESSMENT
    # --------------------------------------------------

    def assess_boot(self):
        issues = []

        if self.event_bus is None:
            issues.append("event_bus missing")

        if self.qbit is None:
            issues.append("qbit missing")

        if not hasattr(self.qbit, "execute_command"):
            issues.append("qbit.execute_command missing")

        if not hasattr(self.dialer, "emit"):
            issues.append("dialer.emit missing")

        self.state["issues"] = issues
        self.state["boot_valid"] = len(issues) == 0

        # Confidence is proportional to completeness
        self.state["confidence"] = max(
            0.0,
            1.0 - (len(issues) * 0.25)
        )

        return self.state["boot_valid"]

    # --------------------------------------------------
    # AWARENESS OF CONNECTIONS
    # --------------------------------------------------

    def register_subscription(self, event_name, callback):
        self.state["subscriptions"][event_name] = callback

        # Growth through connection density
        self._recalculate_confidence()

    # --------------------------------------------------
    # SELF-REGULATION (NOT CONTROL)
    # --------------------------------------------------

    def __call__(self, payload):
        # basic self-regulation (minimal, safe)
        if not self.enabled:
            return

        if self.mode == "manual":
            return

        # autonomous execution
        if self.qbit is not None:
            return self.qbit.execute_command(payload)

    def should_act(self, context=None):
        if not self.state["boot_valid"]:
            return False

        # Simple heuristic â€” you can evolve this later
        return self.state["confidence"] >= 0.5

    def _recalculate_confidence(self):
        base = 1.0 if self.state["boot_valid"] else 0.3
        density = min(len(self.state["subscriptions"]) * 0.1, 0.5)
        self.state["confidence"] = min(1.0, base + density)

    # --------------------------------------------------
    # SELF-REFLECTION
    # --------------------------------------------------

    def snapshot(self):
        return {
            "boot_valid": self.state["boot_valid"],
            "confidence": round(self.state["confidence"], 2),
            "issues": list(self.state["issues"]),
            "subscriptions": list(self.state["subscriptions"].keys()),
        }
# =========================================================================

# ========================= UTILITY =========================
    async def stop(self):
        self._running = False
        self.shutdown_flag.set()
        logger.info("[QbitDialer] Stopped")
# =========================================================================

    def start_runtime_loops():
        asyncio.run(start_core_loops())

